class Grid{
    public int width, height;
    public char[][] field;
    public boolean[][] visited;

    public Grid( int width, int height ){
        this.width = width;
        this.height = height;
        this.field = new char[height][];
        this.visited = new boolean[height][width];
    }
    public void gi( BufferedReader br ) throws IOException{
        for ( int k = 0; k < height; k++){
            field[k] = br.readLine().toCharArray();
        }
    }

    public int[][] left, right, up, down;
    public void builddp(){
        left = new int[height][width];
        right = new int[height][width];
        up = new int[height][width];
        down = new int[height][width];
        for ( int j = 1; j < height-1; j++){
            for ( int k = 1; k < width-1; k++){
                left[j][k] = field[j][k-1] == '*'? 1 : 0;
                if ( left[j][k] == 1 ){
                    left[j][k] += left[j][k-1];
                }
            }
            for ( int k = width-2; k > 0; k--){
                right[j][k] = field[j][k+1] == '*'? 1 : 0;
                if ( right[j][k] == 1 ){
                    right[j][k] += right[j][k+1];
                }
            }
        }
        for ( int j = 1; j < width-1; j++){
            for ( int k = 1; k < height-1; k++){
                up[k][j] = field[k-1][j] == '*'?1:0;
                if ( up[k][j] == 1 ){
                    up[k][j] += up[k-1][j];
                }
            }
            for ( int k = height-2; k > 0; k--){
                down[k][j] = field[k+1][j] == '*'?1:0;
                if ( down[k][j] == 1 ){
                    down[k][j] += down[k+1][j];
                }
            }
        }
    }

    public List<int[]> ans;
    public boolean drawable = true;
    public void solve(){
        ans = new ArrayList<>();
        for ( int j = 1; j < width-1; j++){
            for ( int k = 1; k < height-1; k++){
                if ( field[k][j] == '*' ){
                    int temp = min( left[j][k], right[j][k] );
                    temp = min(temp, min(up[k][j], down[k][j]));
                    if ( temp != 0 ){
                        visited[k][j] = true;
                        for ( int i = k-temp; i <= k+temp; i++){
                            visited[i][j] = true;
                        }
                        for ( int i = j-temp; i <= j+temp; i++){
                            visited[k][i] = true;
                        }
                        int[] star = new int[3];
                        star[0] = k+1;
                        star[1] = j+1;
                        star[2] = temp;
                        ans.add(star);
                    }
                }
            }
        }
        for ( int k = 0; k < width; k++){
            for ( int j = 0; j < height; j++){
                if ( !visited[j][k] && field[j][k] == '*' ){ drawable = false; return; }
            }
        }
    }

}

