public class StarsDrawing
{

    static int n, m;
    static char[][] grid;

    public static boolean isValid(int i, int j)
    {
        return i > -1 && j > -1 && i < n && j < m && grid[i][j] == '*';
    }

    public static int move(int i, int j, int x, int y)
    {
