                        if (j + l + 1 < m)
                            cntLR[i][j + l + 1]--;

                        cntUD[i - l][j]++;
                        if (i + l + 1 < n)
                            cntUD[i + l + 1][j]--;
                    }
                }

        for (int i = 0; i < n; i++)
            for (int j = 1; j < m; j++)
                cntLR[i][j] += cntLR[i][j - 1];

        for (int i = 1; i < n; i++)
