import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;

public class E1015 {

    public void solve(Scanner in, PrintWriter out) {
        int n = in.nextInt(), m = in.nextInt();
        boolean[][] grid = new boolean[n][m];
        for (int i = 0; i < n; ++i) {
            String line = in.next();
            for (int j = 0; j < m; ++j) {
                grid[i][j] = line.charAt(j) == '*';
            }
        }
        int[][] rid = new int[n][m], cid = new int[n][m];
        ArrayList<Integer> rstart = new ArrayList<>();
        ArrayList<Integer> rend = new ArrayList<>();
        ArrayList<Integer> cstart = new ArrayList<>();
        ArrayList<Integer> cend = new ArrayList<>();

        for (int i = 0; i < n; ++i) {
            Arrays.fill(rid[i], -1);
            Arrays.fill(cid[i], -1);
        }

        int idx = 0;
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < m; ++c) {
                if (!grid[r][c]) continue;
                if (rid[r][c] != -1) continue;
                int cur = idx++;
                rstart.add(c);
                while (c < m && grid[r][c]) {
                    rid[r][c] = cur;
                    ++c;
                }
                --c;
                rend.add(c);
            }
        }

        idx = 0;
        for (int c = 0; c < m; ++c) {
            for (int r = 0; r < n; ++r) {
                if (!grid[r][c]) continue;
                if (cid[r][c] != -1) continue;
                int cur = idx++;
                cstart.add(r);
                while (r < n && grid[r][c]) {
                    cid[r][c] = cur;
                    ++r;
                }
                --r;
                cend.add(r);
            }
        }
        BIT[] rbit = new BIT[n], cbit = new BIT[m];
        for (int i = 0; i < n; ++i) rbit[i] = new BIT(m);
        for (int i = 0; i < m; ++i) cbit[i] = new BIT(n);
        StringBuilder ans = new StringBuilder();
        int cnt = 0;
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < m; ++c) {
                if (rid[r][c] == -1 || cid[r][c] == -1) continue;
                int ridx = rid[r][c], cidx = cid[r][c];
                int lr = cstart.get(cidx), hr = cend.get(cidx);
                int lc = rstart.get(ridx), hc = rend.get(ridx);
                int mindist = Math.min(Math.min(r - lr, hr - r), Math.min(c - lc, hc - c));
                if (mindist == 0) continue;
                ans.append((r + 1) + " " + (c + 1) + " " + mindist + "\n");
                ++cnt;
                rbit[r].add(c - mindist, 1);
                rbit[r].add(c + mindist + 1, -1);
                cbit[c].add(r - mindist, 1);
                cbit[c].add(r + mindist + 1, -1);
            }
        }
        boolean possible = true;
        for (int r = 0; possible && r < n; ++r) {
            for (int c = 0; possible && c < m; ++c) {
                if (!grid[r][c]) continue;
                if (rbit[r].sum(0, c) + cbit[c].sum(0, r) <= 0) {
                    possible = false;
                }
            }
        }
        if (!possible) {
            out.println(-1);
        } else {
            out.println(cnt);
            out.print(ans);
        }
    }

    public class BIT {

        long[] tree;
        int n;

        public BIT(int n) {
            this.n = n + 10;
            tree = new long[n + 1];
        }

        public void add(int i, long val) {
            i += 5;
            while (i <= n) {
                tree[i] += val;
                i += i & -i;
            }
        }

        public long sum(int to) {
            to += 5;
            long res = 0;
            for (int i = to; i >= 1; i -= (i & -i)) {
                res += tree[i];
            }
            return res;
        }

        public long sum(int from, int to) {
            return sum(to) - sum(from - 1);
        }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new E1015().solve(in, out);
        in.close();
        out.close();
    }
}

