import java.util.*;
import java.io.*;

public class Solution{

    static class FastReader{
        BufferedReader br;
        StringTokenizer st;

        public FastReader()
        {
            br = new BufferedReader(new
                     InputStreamReader(System.in));
        }

        String next()
        {
            while (st == null || !st.hasMoreElements())
            {
                try
                {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException  e)
                {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt()
        {
            return Integer.parseInt(next());
        }

        long nextLong()
        {
            return Long.parseLong(next());
        }

        double nextDouble()
        {
            return Double.parseDouble(next());
        }

        String nextLine()
        {
            String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }
    }

    static class Center{
        int x,y,r;
        public Center(int a1 , int a3, int a2){
            x=a1; y=a2; r=a3;
        }
    }

    static Center findstar(int[][] pat, int x, int y, int n, int m){
        int i=x, j=y, clen=0, rlen=0;
        Center res = null;

        clen = 0;
        while(i>=1){
            if(pat[i][y]==0)
                break;
            i--;
            clen++;
        }
        rlen = clen;

        i = x;
        clen = 0;
        while(i<=n){
            if(pat[i][y]==0)
                break;
            i++;
            clen++;
        }
        rlen = Math.min(rlen, clen);

        clen = 0;
        while(j>=1){
            if(pat[x][j]==0)
                break;
            j--;
            clen++;
        }
        rlen = Math.min(rlen, clen);

        j = y;
        clen = 0;
        while(j<=m){
            if(pat[x][j]==0)
                break;
            j++;
            clen++;
        }
        rlen = Math.min(rlen, clen);

        if(rlen>0){
            res = new Center(x, y, rlen);
        }

        return res;
    }

    static void setmark(int[][] pat, Center cur){
        int x=cur.x, y=cur.y, r=cur.r;

        for(int i=0;i<=r;i++){
            pat[x+i][y] = pat[x][y+i] = pat[x-i][y] = pat[x][y-i] = 2;
        }
    }

    static boolean check(int[][] pat, int n, int m){
        for(int i=1;i<=n;i++)
            for(int j=1;j<=m;j++)
                if(pat[i][j]==1)
                    return true;

        return false;
    }

    public static void main (String[] args) throws Exception{
        FastReader sc = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        int n = sc.nextInt();
        int m = sc.nextInt();
        int[][] pat = new int[n+2][m+2];

        for(int i=1;i<=n;i++){
            String line = sc.nextLine();
            for(int j=1;j<=m;j++){
                pat[i][j] = (line.charAt(j-1)=='*'?1:0);
            }
        }

        ArrayList<Center> res = new ArrayList<Center>();

        for(int i=1;i<=n;i++){
            for(int j=1;j<=m;j++){
                Center cur = findstar(pat, i, j, n, m);
                if(cur!=null){

                    setmark(pat, cur);
                    res.add(cur);
                }
            }
        }

        if(check(pat, n, m))
            out.println(-1);
        else{
            out.println(res.size());
            for(Center c: res){
                out.println(c.x+" "+c.y+" "+c.r);
            }
        }

        out.close();
    }

}

