import static java.lang.Integer.min;

public class Main {

    class Star {
        int i, j, len;

        Star(int i, j, int len) {
            this.i = i;
            this.j = j;
            this.len = len;
        }
    }

    class Count {
        int left, right, top, bot;
    }

    public void run() {
        FastScanner in = new FastScanner();
        FastOutput out = new FastOutput();

        int n = in.nextInt(), m = in.nextInt();

        boolean[][] before = new boolean[n][m];
        int[][] vert = new int[n][m], goriz = new int[n][m];
        Count[][] counts = new Count[n][m];

        List<Star> result = new LinkedList<>();

        for (int i = 0; i < n; i++) {
            String str = in.next();
            for (int j = 0; j < m; j++) {
                before[i][j] = str.charAt(j) == '*';
                vert[i][j] = 0;
                counts[i][j] = new Count();
            }
        }

        for (int i = 0; i < n; i++) {
            int stars_ = 0;
            for (int j = 0; j < m; j++) {
                counts[i][j].left = stars_;
                if (before[i][j]) {
                    stars_++;
                } else {
                    stars_ = 0;
                }
            }

            stars_ = 0;
            for (int j = m - 1; j >= 0; j--) {
                counts[i][j].right = stars_;
                if (before[i][j]) {
                    stars_++;
                } else {
                    stars_ = 0;
                }
            }
        }

        for (int j = 0; j < m; j++) {
            int stars_ = 0;
            for (int i = 0; i < n; i++) {
                counts[i][j].top = stars_;
                if (before[i][j]) {
                    stars_++;
                } else {
                    stars_ = 0;
                }
            }

            stars_ = 0;
            for (int i = n - 1; i >= 0; i--) {
                counts[i][j].bot = stars_;
                if (before[i][j]) {
                    stars_++;
                } else {
                    stars_ = 0;
                }
            }
        }


        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (!before[i][j])
                    continue;
                Count c = counts[i][j];
                int l = min(min(min(c.bot, c.top), c.left), c.right);
                if (l < 1)
                    continue;
                Star star = new Star(i, j, l);
                result.add(star);

                vert[i - l][j]++;
                if (i + l + 1 < n)
                    vert[i + l + 1][j]--;

                goriz[i][j - l]++;
                if (j + l + 1 < m)
                    goriz[i][j + l + 1]--;
            }
        }

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {

                    if (i > 0) {
                        vert[i][j] += vert[i - 1][j];
                    }
                    if (j > 0) {
                        goriz[i][j] += goriz[i][j - 1];
                    }
                    boolean removed = vert[i][j] + goriz[i][j] > 0;
                    if (removed != before[i][j] ) {
                        System.out.println("-1");
                        return;
                    }
                }
            }

        out.println(result.size());
        result.forEach(r -> out.print(r.i + 1, r.j + 1, r.len));

        out.finish();
    }


    public static void main(String[] args) {
        new Main().run();
    }
}

