public class E {
	static FastReader sc=null;
	static int dirx[]= {1,-1,-0,0},diry[]= {0,0,-1,1};

	public static void main(String[] args) {
		sc=new FastReader();
		PrintWriter out=new PrintWriter(System.out);
		int n=sc.nextInt(),m=sc.nextInt();
		char b[][]=new char[n][m];
		for(int i=0;i<n;i++)b[i]=sc.next().toCharArray();

		int counts[][]=new int[n][m];

		ArrayList<Pair> stars=new ArrayList<>();
		for(int i=0;i<n;i++) {
			for(int j=0;j<m;j++) {
				if(b[i][j]=='*') {
					int curr=0;
					boolean po=true;
					while(po) {
						curr++;
						for(int k=0;k<4;k++) {
							po&=legal(i,j,curr,k,b);
						}
						if(po) {
							for(int k=0;k<4;k++) {
								int x_new=i+dirx[k]*curr,y_new=j+diry[k]*curr;
								counts[x_new][y_new]++;
							}
						}
					}
					curr--;
					if(curr>0) {
						counts[i][j]++;
						stars.add(new Pair(i+1,j+1,curr));
					}
				}
			}
		}
		boolean poss=true;
		for(int i=0;i<n;i++)
			for(int j=0;j<m;j++)if(b[i][j]=='*')poss&=(counts[i][j]>0);

		if(!poss)out.println(-1);
		else {
			out.println(stars.size());
			for(Pair e:stars) {
				out.println(e.x+" "+e.y+" "+e.l);
			}
		}
		out.close();
	}

	static class Pair{
		int x,y,l;
		Pair(int x,int y,int l){
			this.x=x;
			this.y=y;
			this.l=l;
