public class Main {
  static Scanner in = new Scanner(System.in);
  static PrintWriter out = new PrintWriter(System.out);
  static String grid[];
  static boolean drawn[][];
  static LinkedList<String> ans = new LinkedList<>();

  static void drawStar (int row, int col, int length) {
    int n = 1;
    boolean drawable = true;
    int lengthDrawable = 0;
    while (n <= length && drawable) {
      if (grid[row - n].charAt(col) == '.' ||
        grid[row + n].charAt(col) == '.' ||
        grid[row].charAt(col - n) == '.' ||
        grid[row].charAt(col + n) == '.') {
        drawable = false;
        lengthDrawable = n - 1;
      } 
      n++;
    }

    if (drawable || lengthDrawable > 0) {
      ans.add((String)((row + 1) + " " + (col + 1) + " " + lengthDrawable));
      drawn[row][col] = true;
      for (int i = 1; i <= lengthDrawable; i++) {
        drawn[row + i][col] = true;
        drawn[row - i][col] = true;
        drawn[row][col + i] = true;
        drawn[row][col - i] = true;
      }
    }
  }

  public static void main(String[] args) {
    int n = in.nextInt();
    int m = in.nextInt();
    grid = new String[n];
    drawn = new boolean[n][m];

    in.nextLine();
    for (int i = 0; i < n; i++) {
      grid[i] = in.nextLine();
      for (int j = 0; j < m; j++) {
        if (grid[i].charAt(j) == '.') drawn[i][j] = true;
      }
    }

    for (int i = 1; i < n - 1; i++) {
      for (int j = 1; j < m - 1; j++) {
        if (grid[i].charAt(j) == '.') continue;
        int maxLength = Math.min(i, j);
        maxLength = Math.min(maxLength, ((n - 1) - i));
        maxLength = Math.min(maxLength, ((m - 1) - j));
        drawStar(i, j, maxLength);
      }
    }

    boolean drawableGrid = true;
    for (int i = 0; i < n && drawableGrid; i++) {
      for (int j = 0; j < m && drawableGrid; j++) {
        drawableGrid &= drawn[i][j];
      }
    }

    if (drawableGrid) {
      out.println(ans.size());
      Iterator<String> iterator = ans.iterator();
      while (iterator.hasNext()) {
        out.println(iterator.next());
      }
    } else {
      out.println(-1);
    }

    in.close();
    out.close();
  }
}

