public class r501p5{

    static PrintWriter pw;

    static class Star{
        int i, j, size;
        public Star(int a, int b, int c){
            i = a;
            j = b;
            size = c;
        }
        void display(){
            pw.println(i+" "+j+" "+size);
        }
    }

    public static void main(String args[]) {
        InputReader sc = new InputReader(System.in);
        pw = new PrintWriter(System.out);

        int n = sc.nextInt(), m = sc.nextInt();
        char grid[][] = new char[n][m];
        boolean covered = true;
        int up[][] = new int[n][m], down[][] = new int[n][m], left[][] = new int[n][m], right[][] = new int[n][m], h[][] = new int[n][m], v[][] = new int[n][m];

        ArrayList<Star> list = new ArrayList<>();

        for(int i=0; i<n; i++)
            grid[i] = sc.readString().toCharArray();

        for(int i=0; i<n; i++) {
            for(int j=0; j<m; j++){
                if(i>0 && grid[i-1][j] == '*')
                    up[i][j] = up[i-1][j]+1;
                if(j>0 && grid[i][j-1] == '*')
                    left[i][j] = left[i][j-1]+1;
            }
        }

        for(int i=n-1; i>=0; i--){
            for(int j=m-1; j>=0; j--){
                if(i<n-1 && grid[i+1][j] == '*')
                    down[i][j] = down[i+1][j]+1;
                if(j<m-1 && grid[i][j+1] == '*')
                    right[i][j] = right[i][j+1]+1;
            }
        }

        for(int i=0; i<n; i++){
            for(int j=0; j<m; j++){
                if(grid[i][j] == '*'){
                    int size = Math.min(Math.min(left[i][j], right[i][j]), Math.min(up[i][j], down[i][j]));
                    if(size > 0){
                        list.add(new Star(i+1, j+1, size));

                        h[i][j-size]++;
                        if(j+size+1<m)
                            h[i][j+size+1]--;
                        v[i-size][j]++;
                        if(i+size+1<n)
                            v[i+size+1][j]--;
                    }
                }
            }
        }

        for(int i=0; i<n; i++){
            for(int j=1; j<m; j++)
                h[i][j] += h[i][j-1];
        }

        for(int j=0; j<m; j++){
            for(int i=1; i<n; i++)
                v[i][j] += v[i-1][j];
        }

        for(int i=0; i<n; i++){
            for(int j=0; j<m; j++){
                if(grid[i][j] == '*' && v[i][j] <= 0 && h[i][j] <= 0)
                    covered = false;
            }
        }

