					int row = i + dx;
					int col = j + dy;
					if (row >= 0 && row < n && col >= 0 && col < m) {
						arr[i][j] += arr[row][col];
					}
				}

			}
		}
	}

	static void dp2(int dx, int dy, int arr[][], int n, int m) {
		for (int i = n - 1; i >= 0; i--) {
			for (int j = m - 1; j >= 0; j--) {
				if (grid[i][j] == '*') {
					arr[i][j] = 1;
					int row = i + dx;
					int col = j + dy;
					if (row >= 0 && row < n && col >= 0 && col < m) {
