import java.util.Scanner;

public class StarsDrawingEasy {

	static char prev = 'X';

	public static void main(String [] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt(); int m = sc.nextInt();
		char [][] grid = new char[n+1][];
		grid[0] = new char[m+1];
		for(int i = 1; i<=n; i++) {
			grid[i] = (" " + sc.next()).toCharArray();
		}
		getResult(grid);
		sc.close();
	}

	static void getResult(char [][] grid) {
		int numStars = 0;
		StringBuilder res = new StringBuilder("");
		for(int i = 1; i<grid.length; i++) {
			for(int j = 1; j<grid[1].length; j++) {
				if(grid[i][j]!='*'&&grid[i][j]!=prev) {
					continue;
				}
				int rad = getRad(i, j, grid);
				for(int cur = rad; cur>=1; cur--) {
					if(isPossible(grid, i, j, cur)) {
						numStars++;
						res.append(i + " " + j + " " + cur + "\n");
						modify(grid, i, j, cur);
						break;
					}
				}
			}
		}
		if(valid(grid)) {
			System.out.println(numStars);
			System.out.print(res);
		}
		else {
			System.out.println(-1);
		}
	}

	static boolean valid(char [][] grid) {
		for(char [] cur: grid) {
			for(char curChar : cur) {
				if(curChar=='*') {
					return false;
				}
			}
		}
		return true;
	}

	static boolean isPossible(char [][] grid,int x, int y, int rad) {
		boolean res = true;
		res = res&&check(grid, x, y, 1, 0, rad);
		res = res&&check(grid, x, y, -1, 0, rad);
		res = res&&check(grid, x, y, 0, 1, rad);
		res = res&&check(grid, x, y, 0, -1, rad);
		return res;
	}

	static void modify(char [][] grid, int x, int y, int rad) {
		grid[x][y] = prev;
		modifyLine(grid, x, y, 1, 0, rad);
		modifyLine(grid, x, y, -1, 0, rad);
		modifyLine(grid, x, y, 0, 1, rad);
		modifyLine(grid, x, y, 0, -1, rad);
	}

	static void modifyLine(char [][] grid, int x, int y, int xInc,int yInc,int numInc) {
		for(int i = 1; i<=numInc; i++) {
			x = x + xInc;
			y = y + yInc;
			grid[x][y] = prev;
		}
		return;
	}

	static boolean check(char [][] grid, int  x, int  y, int xInc,int yInc,int numInc) {
		for(int i = 1; i<=numInc; i++) {
			x = x + xInc;
			y = y + yInc;
			if(grid[x][y]==prev||grid[x][y]=='*') {
				continue;
			}
			return false;

		}
		return true;
	}

	static int getRad(int x, int y, char [][] grid) {
		return Math.min(grid[1].length-1-y,Math.min(y-1,Math.min(x-1, grid.length-1-x)));
	}
}

