        for (int col = m - 1; col > -1; col--)
            for (int row = 0; row < n; row++)
                if (isValid(col, row))
                    down[col][row] += isValid(col, row + 1) ? 1 + down[col][row + 1] : 0;

        int[][] right = new int[n][m];       // vertical down
        for (int row = n - 1; row > -1; row--)
            for (int col = 0; col < m; col++)
                if (isValid(row, col))
                    right[row][col] += isValid(row + 1, col) ? 1 + right[row + 1][col] : 0;

        int[][] left = new int[n][m];        // vertical up
        for (int row = 0; row < n; row++)
            for (int col = 0; col < m; col++)
                if (isValid(row, col))
