public class cf501_E {

  public static void main(String[] args) throws IOException {
    Scanner s = new Scanner(new BufferedInputStream(System.in));
    BufferedOutputStream buf = new BufferedOutputStream(System.out);

    solve(s, buf);
    buf.flush();
  }

  public static void solve(Scanner in, OutputStream out) throws IOException {
    int n = in.nextInt();
    int m = in.nextInt();
    in.nextLine();
    char[][] field = new char[n][m];
    char[][] testField = new char[n][m];
    for (int i = 0; i < n; i++) {
      String s = in.nextLine();
      int p = 1;
      for (int j = 0; j < m; j++) {
        field[i][j] = s.charAt(j);
        testField[i][j] = '.';
      }
    }

    int[][] l = new int[n][m];
    int[][] u = new int[n][m];
    int[][] r = new int[n][m];
    int[][] d = new int[n][m];

    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        boolean star = field[i][j] == '*';

        if (j == 0) {
          if (star) {
            l[i][j] = 1;
          } else {
            l[i][j] = 0;
          }
        } else {
          if (star) {
            l[i][j] = l[i][j - 1] + 1;
          } else {
            l[i][j] = 0;
          }
        }

        if (i == 0) {
          if (star) {
            u[i][j] = 1;
          } else {
            u[i][j] = 0;
          }
        } else {
          if (star) {
            u[i][j] = u[i - 1][j] + 1;
          } else {
            u[i][j] = 0;
          }
        }
      }
    }


    for (int i = n - 1; i >= 0; i--) {
      for (int j = m - 1; j >= 0; j--) {
        boolean star = field[i][j] == '*';

        if (j == m - 1) {
          if (star) {
            r[i][j] = 1;
          } else {
            r[i][j] = 0;
          }
        } else {
          if (star) {
            r[i][j] = r[i][j + 1] + 1;
          } else {
            r[i][j] = 0;
          }
        }

        if (i == n - 1) {
          if (star) {
            d[i][j] = 1;
          } else {
            d[i][j] = 0;
          }
        } else {
          if (star) {
            d[i][j] = d[i + 1][j] + 1;
          } else {
            d[i][j] = 0;
          }
        }
      }
    }

    List<Star> ss = new ArrayList<>();
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        int s = Math.min(Math.min(l[i][j], r[i][j]), Math.min(u[i][j], d[i][j])) - 1;
        if (s > 0) {
          ss.add(new Star(i, j, s));
        }
      }
    }

    printStars(testField, ss, n, m);

    boolean eq = equals(field, testField);

    if (eq) {

      out.write(String.format("%d\n", ss.size()).getBytes());
      for (Star star : ss) {

        StringBuilder sb = new StringBuilder();
        sb.append(star.n + 1).append(' ')
                .append(star.m + 1).append(' ')
                .append(star.s).append('\n');
        out.write(sb.toString().getBytes());
      }
    } else {
      out.write("-1".getBytes());
    }
  }

