    for (Star s : ss) {
      int i = s.n;
      int j = s.m;
      h[i][j - s.s]++;
      if (j + s.s + 1 < m) {
        h[i][j + s.s + 1]--;
      }
      v[i - s.s][j]++;
      if (i + s.s + 1 < n) {
        v[i + s.s + 1][j]--;
      }
    }

    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {

        if (i != 0) {
          v[i][j] = v[i][j] + v[i - 1][j];
        }

