public class DrawingStars {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out,false);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][m];
        for(int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        ArrayList<Line> horiz = new ArrayList<>();
        ArrayList<Line> verts = new ArrayList<>();
        int cnt = 0;
        PriorityQueue<Event> q = new PriorityQueue<>();
        StringBuilder sb = new StringBuilder();
        for(int i = 0; i < n; i++) {
            int prev = -1;
            for(int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    if (prev == -1) prev = j;
                } else {
                    if (prev != -1) {
                        if (j - prev > 2) {

                            horiz.add(new Line(prev, j, i));
                            q.offer(new Event(prev, cnt, 1));
                            q.offer(new Event(j, cnt, 0));
                            cnt++;
                        }
                        prev = -1;
                    }
                }
            }
            if (prev != -1 && m - prev > 2) {

                horiz.add(new Line(prev, m, i));
                q.offer(new Event(prev, cnt, 1));
                q.offer(new Event(m, cnt, 0));
                cnt++;
            }
        }
        for(int j = 0; j < m; j++) {
            int prev = -1;
            for(int i = 0; i < n; i++) {
                if (grid[i][j] == '*') {
                    if (prev == -1) prev = i;
                } else {
                    if (prev != -1) {
                        if (i - prev > 2) {

                            verts.add(new Line(prev, i, j));
                        }
                        prev = -1;
                    }
                }
            }
            if (prev != -1) verts.add(new Line(prev, n, j));
        }
        int[][] prefVert = new int[n+1][m];
        int[][] prefHoriz = new int[n][m+1];
        Collections.sort(verts, new Comparator<Line>() {
            public int compare(Line o1, Line o2) {
                if (o1.x == o2.x) return o1.l - o2.l;
                return o1.x - o2.x;
            }
        });
        int v = 0, h = 0;
        Line[] active = new Line[n];
        int ss = verts.size();
        int ans = 0;
        for(int z = 0; z < ss; z++) {
            Line curLine = verts.get(z);
