            for(int j = 0; j < m; j++) { 
                cur += prefHoriz[i][j];
                gh[i][j] = cur;
            }

        }
        for(int j = 0; j < m; j++) { 
            int cur = 0;
            for(int i= 0; i < n; i++) { 
                cur += prefVert[i][j]; 
                gv[j][i] = cur;
            } 

        }
