    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        n = sc.nextInt();
        m = sc.nextInt();


        grid = new char[n][];
        for (int i = 0; i < n; i++)
            grid[i] = sc.next().toCharArray();
        int[] x = new int[n*m];
        int[] y = new int[n*m];
        int[] s = new int[n*m];
        int len = 0;
        cumRow = new int[n][m];
        cumCol = new int[m][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if(grid[i][j] == '*'){
                    cumRow[i][j] = 1;
                    cumCol[j][i] = 1;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 1; j < m; j++) {
                cumRow[i][j] += cumRow[i][j-1];
            }
        }

        for (int i = 0; i < m; i++) {
            for (int j = 1; j < n; j++) {
                cumCol[i][j] += cumCol[i][j-1];
            }
        }

        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++) {
                if(grid[i][j] == '.')
                    continue;
                int lo = 0;
                int hi = 1000;
                while(lo < hi){
                    int mid = lo + (hi-lo+1)/2;
                    if(check(i, j, mid))
                        lo = mid;
                    else
                        hi = mid-1;
                }
                if(lo > 0){
                    x[len] = i;
                    y[len] = j;
                    s[len++] = lo;
                }
            }


        char[][] grid2 = new char[n][m];
        for (int i = 0; i < grid2.length; i++) {
            Arrays.fill(grid2[i], '.');
        }

        for (int k = 0; k < len; k++) {
            int xx = x[k];
            int sz = s[k];
            int yy = y[k];
            for (int i = xx-sz; i <= xx + sz; i++) {
                grid2[i][yy] = '*';
            }

            for (int j = yy-sz; j <= yy + sz; j++) {
                grid2[xx][j] = '*';
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if(grid[i][j] != grid2[i][j]){
                    System.out.println(-1);
                    return;
                }
            }
        }

        pw.println(len);
        for (int i = 0; i < len; i++) {
            pw.println(x[i]+1 + " " + (y[i] + 1) + " " + s[i]);
        }

        pw.flush();
        pw.close();
    }

    static boolean isStar(int i, int j){
        if(i < 0 || j < 0 || i >= n || j >= m)
            return false;
        return grid[i][j] == '*';
    }

    static int[][] cumRow;
    static int[][] cumCol;
    static boolean check(int i, int j, int k){
        if(!isStar(i, j+k) || !isStar(i, j-k) || !isStar(i+k, j) || !isStar(i-k, j))
            return false;
        int a = cumRow[i][j+k];
        if(j-k > 0)
            a -= cumRow[i][j-k-1];

        int b = cumCol[j][i+k];
        if(i-k > 0)
            b -= cumCol[j][i-k-1];

        return a == 2*k+1 && b == 2*k+1;
    }

