					} 

						break;
				}

				if(bestK > 0) {
					rowAns.add(i+1);
					colAns.add(j+1);
					sizeAns.add(bestK);
				}
			}
		}

		boolean flag = true;
		for(int i=0; i<r; i++)
			for(int j=0; j<c; j++) 
				flag &= fill[i][j];

		if(flag) {
