public class StarsDrawing_CF1015E {


	public static void main(String[] args) throws IOException {

		Scanner sc = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);

		int r = sc.nextInt();
		int c = sc.nextInt();
		boolean [][] grid = new boolean [r][c];

		for(int i = 0; i < r; i++){
			String s = sc.next();
			int cr = 0;
			for(int j = 0; j < c; j++){
				if(s.charAt(j) == '*'){
					grid[i][j] = true;
					cr++;
				} else {
					cr = 0;
				}
				//commfr not used later, can be removed but keep for compatibility
			}
		}

		int [][] commbr = new int [r][c];
		int [][] commfc = new int [r][c];
		int [][] commbc = new int [r][c];

		for(int i = 0; i < r; i++){
			int cr = 0;
			for(int j = c - 1; j >= 0; j--){
				if(grid[i][j]){
					cr++;
				} else {
					cr = 0;
				}
				commbr[i][j] = cr;
			}
		}

		for(int j = 0; j < c; j++){
			int cc = 0;
			for(int i = 0; i < r; i++){
				if(grid[i][j]){
					cc++;
				} else {
					cc = 0;
				}
				commfc[i][j] = cc;
			}
		}

		for(int j = 0; j < c; j++){
			int cc = 0;
			for(int i = r - 1; i >= 0; i--){
				if(grid[i][j]){
					cc++;
				} else {
					cc = 0;
				}
				commbc[i][j] = cc;
			}
		}

		int max [][] = new int [r][c];
		for(int i = 0; i < r; i++){
			for(int j = 0; j < c; j++){
				if(grid[i][j]){
					max[i][j] = Math.min(Math.min(
							computeLeft(grid,i,j),
							computeRight(grid,i,j)),
							Math.min(
									computeUp(grid,i,j),
									computeDown(grid,i,j))) - 1;
				}
			}
		}

		SegmentTree [] srow = new SegmentTree [r];
		SegmentTree [] scol = new SegmentTree [c];

		int N = 1; while(N < r) N <<= 1; 
		for(int i = 0; i < c; i++){
			scol[i]  = new SegmentTree(N);
		}

		N = 1; while(N < c) N <<= 1;

		for(int i = 0; i < r; i++){
			srow[i] = new SegmentTree(N);
			for(int j = 0; j < c; j++){
				if(max[i][j] != 0){
					srow[i].update_range(j + 1 - max[i][j], j + 1 + max[i][j], 1);
					scol[j].update_range(i+1 - max[i][j], i + 1 + max[i][j], 1);
				}
			}
		}
		boolean poss = true;
		for(int i = 0; i < r; i++){
			for(int j = 0; j < c; j++){
				if(grid[i][j]){
					if (Math.max(srow[i].query(j+1, j+1), scol[j].query(i + 1, i + 1))< 1){
						poss = false;
						break;
					}
				}
			}
			if(!poss) break;
		}

		if(!poss){
			out.println(-1);
		} else {
			int count = 0;
			StringBuilder sb = new StringBuilder("");
			for(int i = 0;  i < r; i++){
				for(int j = 0; j < c; j++){
					if(max[i][j] != 0){
						sb.append((i + 1) +" " + (j +  1) +" " + max[i][j]+"\n");
						count++;
					}
				}
			}
			out.println(count);
			if(count>0) out.print(sb.toString());
		}

		out.flush();
		out.close();
	}

	static int computeLeft(boolean[][] g,int i,int j){
		int cnt=0;
		for(int jj=j; jj>=0; jj--){
			if(g[i][jj]) cnt++;
			else break;
		}
		return cnt;
	}
	static int computeRight(boolean[][] g,int i,int j){
		int cnt=0;
		for(int jj=j; jj<g[0].length; jj++){
			if(g[i][jj]) cnt++;
			else break;
		}
		return cnt;
	}
	static int computeUp(boolean[][] g,int i,int j){
		int cnt=0;
		for(int ii=i; ii>=0; ii--){
			if(g[ii][j]) cnt++;
			else break;
		}
		return cnt;
	}
	static int computeDown(boolean[][] g,int i,int j){
		int cnt=0;
		for(int ii=i; ii<g.length; ii++){
			if(g[ii][j]) cnt++;
			else break;
		}
		return cnt;
	}

	static class SegmentTree {		

		int N; 			
		int[] sTree, lazy;

		SegmentTree(int N)		
		{
			this.N = N;
			sTree = new int[N<<1];		
			lazy = new int[N<<1];

		}

		void update_point(int index, int val)			
		{
			index += N - 1;				
			sTree[index] += val;			
			while(index>1)				
			{
				index >>= 1;
				sTree[index] = sTree[index<<1] + sTree[(index<<1) + 1];		
			}
		}


		void update_range(int i, int j, int val)		
		{
			update_range(1,1,N,i,j,val);
		}

		void update_range(int node, int b, int e, int i, int j, int val)
		{
			if(i > e || j < b)		
				return;
			if(b >= i && e <= j)		
			{
				sTree[node] += (e-b+1)*val;			
				lazy[node] += val;				
			}							
			else		
			{
				propagate(node, b, e);
				update_range(node<<1,b,(b+e)/2,i,j,val);
				update_range((node<<1)+1,(b+e)/2+1,e,i,j,val);
				sTree[node] = sTree[node<<1] + sTree[(node<<1)+1];		
			}

		}
		void propagate(int node, int b, int e)		
		{
			int mid = (b+e)/2;
			lazy[node<<1] += lazy[node];
			lazy[(node<<1)+1] += lazy[node];
			sTree[node<<1] += (mid-b+1)*lazy[node];		
			sTree[(node<<1)+1] += (e-mid)*lazy[node];		
			lazy[node] = 0;
		}

		int query(int i, int j)
		{
			return query(1,1,N,i,j);
		}

		int query(int node, int b, int e, int i, int j)	
		{
			if(i>e || j <b)
				return 0;		
			if(b>= i && e <= j)
				return sTree[node];
			propagate(node, b, e);
			int q1 = query(node<<1,b,(b+e)/2,i,j);
			int q2 = query((node<<1)+1,(b+e)/2+1,e,i,j);
			return q1 + q2;	

		}
	}

	static class Scanner {
		StringTokenizer st;
		BufferedReader br;

		public Scanner(InputStream s) {
			br = new BufferedReader(new InputStreamReader(s));
		}

		public String next() throws IOException {
			while (st == null || !st.hasMoreTokens())
				st = new StringTokenizer(br.readLine());
			return st.nextToken();
		}

		public int nextInt() throws IOException {
			return Integer.parseInt(next());
		}

		public long nextLong() throws IOException {
			return Long.parseLong(next());
		}

		public String nextLine() throws IOException {
			return br.readLine();
		}

		public double nextDouble() throws IOException {
			String x = next();
			StringBuilder sb = new StringBuilder("0");
			double res = 0, f = 1;
			boolean dec = false, neg = false;
			int start = 0;
			if (x.charAt(0) == '-') {
				neg = true;
				start++;
			}
			for (int i = start; i < x.length(); i++)
				if (x.charAt(i) == '.') {
					res = Long.parseLong(sb.toString());
					sb = new StringBuilder("0");
					dec = true;
				} else {
					sb.append(x.charAt(i));
					if (dec)
						f *= 10;
				}
			res += Long.parseLong(sb.toString()) / f;
			return res * (neg ? -1 : 1);
		}

		public boolean ready() throws IOException {
			return br.ready();
		}

	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class StarsDrawing_CF1015E {

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int r = sc.nextInt();
        int c = sc.nextInt();
        char[][] grid = new char[r][];
        for (int i = 0; i < r; i++) {
            grid[i] = sc.next().toCharArray();
        }

        int[][] up = new int[r][c];
        int[][] down = new int[r][c];
        int[][] left = new int[r][c];
        int[][] right = new int[r][c];

        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                if (grid[i][j] != '*') continue;
                if (i == 0) up[i][j] = 1;
                else if (grid[i - 1][j] != '*') up[i][j] = 1;
                else up[i][j] = up[i - 1][j] + 1;

                if (i == r - 1) down[i][j] = 1;
                else if (grid[i + 1][j] != '*') down[i][j] = 1;
                else down[i][j] = down[i + 1][j] + 1;

                if (j == 0) left[i][j] = 1;
                else if (grid[i][j - 1] != '*') left[i][j] = 1;
                else left[i][j] = left[i][j - 1] + 1;

                if (j == c - 1) right[i][j] = 1;
                else if (grid[i][j + 1] != '*') right[i][j] = 1;
                else right[i][j] = right[i][j + 1] + 1;
            }
        }

        int max[] = new int[r * c];
        int cnt = 0;
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                if (grid[i][j] != '*') continue;
                int u = up[i][j] - 1;
                int d = down[i][j] - 1;
                int l = left[i][j] - 1;
                int rgt = right[i][j] - 1;
                int sz = Math.min(Math.min(u, d), Math.min(l, rgt));
                if (sz > 0) {
                    max[cnt++] = (i + 1) * 1000000 + (j + 1) * 1000 + sz;
                }
            }
        }

        boolean[][] mark = new boolean[r][c];
        for (int i = 0; i < cnt; i++) {
            int tmp = max[i];
            int x = (tmp / 1000) % 100;
            int y = tmp % 1000;
            int s = tmp / 1000000;
            for (int dx = -s; dx <= s; dx++) {
                for (int dy = -s; dy <= s; dy++) {
                    int nx = x + dx, ny = y + dy;
                    if (nx >= 0 && nx < r && ny >= 0 && ny < c && Math.abs(dx) + Math.abs(dy) <= s) {
                        mark[nx][ny] = true;
                    }
                }
            }
        }

        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                if (grid[i][j] == '*' && !mark[i][j]) {
                    System.out.println(-1);
                    out.flush();
                    out.close();
                    return;
                }
            }
        }

        System.out.println(cnt);
        for (int i = 0; i < cnt; i++) {
            int tmp = max[i];
            int x = (tmp / 1000) % 100;
            int y = tmp % 1000;
            int s = tmp / 1000000;
            System.out.println(x + " " + y + " " + s);
        }
        out.flush();
        out.close();
    }

    static class Scanner {
        private final BufferedReader br;
        private StringTokenizer st;

        Scanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

