			for (int i = 0; i < n; i++) {
				grid[i] = in.next().toCharArray();
			}
			List<Pair> pairs = new ArrayList<>();
			for (int i = 1; i < n - 1; i++) {
				for (int j = 1; j < m - 1; j++) {
					if (grid[i][j] == '*' && grid[i - 1][j] == '*' && grid[i + 1][j] == '*' && grid[i][j - 1] == '*' && grid[i][j + 1] == '*') {
						pairs.add(new Pair(i, j));
					}
				}
			}
			List<Triple> tris = new ArrayList<>();
