               int i = min4(u[k][j],d[k][j],r[k][j],l[k][j])-1;

               for(int x = 0; x <= i; x++){
                  check[k+x][j] = true;
                  check[k-x][j] = true;
                  check[k][j+x] = true;
                  check[k][j-x] = true;
