public class E984{

	int n;
	int m;
	char[][] chs;

	int[][] LR;
	int[][] RL;
	int[][] DU;
	int[][] UD;

	private void solve() throws Exception {
		n = nextInt();
		m = nextInt();
		chs = new char[n][];
		cht = new char[n][m];
		for(int i = 0; i < n; i++) for(int j = 0; j < m; j++) cht[i][j] = '.';
		for(int i = 0; i < n; i++) chs[i] = nextToken().toCharArray();
		res = new ArrayList<Integer[]>();

		LR = new int[n][m];
		for(int i = 0; i < n; i++) {
			for(int j = 0; j < m; j++) {
				if(chs[i][j] == '*') LR[i][j] = (j>0?LR[i][j-1]:0)+1;
			}
		}

		RL = new int[n][m];
		for(int i = 0; i < n; i++) {
			for(int j = m-1; j >= 0; j--) {
				if(chs[i][j] == '*') RL[i][j] = (j<m-1?RL[i][j+1]:0)+1;
			}
		}

		UD = new int[n][m];
		for(int j = 0; j < m; j++) {
			for(int i = 0; i < n; i++) {
				if(chs[i][j] == '*') UD[i][j] = (i>0?UD[i-1][j]:0)+1;
			}
		}

		DU = new int[n][m];
		for(int j = 0; j < m; j++) {
			for(int i = n-1; i >= 0; i--) {
				if(chs[i][j] == '*') DU[i][j] = (i<n-1?DU[i+1][j]:0)+1;
			}
		}


		for(int i = 0; i < n; i++) {
			for(int j = 0; j < m; j++) {
				if(chs[i][j] == '*') doit(i,j);
			}
		}
		boolean ok = true;
		for(int i = 0; i < n; i++) {
			for(int j = 0; j < m; j++) {
				if(chs[i][j] != cht[i][j]) ok = false;
			}
		}
		if(!ok) out.println(-1);
