    static class TaskE1 {
        int n;
        int m;
        boolean[][] mrk;
        int[][] grid;

        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            n = in.nextInt();
            m = in.nextInt();

            mrk = new boolean[n][m];
            grid = new int[n][m];
            for (int i = 0; i < n; i++) {
                String s = in.nextLine();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = s.charAt(j) == '.' ? 0 : 1;
                }
            }

            int[][] topx = new int[n][m];
            for (int i = 0; i < m; i++) {
                for (int j = 1; j < n; j++) {
                    topx[j][i] = (grid[j - 1][i] == 1) ? topx[j - 1][i] + 1 : 0;
                }
            }
            int[][] bottomx = new int[n][m];
            for (int i = 0; i < m; i++) {
                for (int j = n - 2; j >= 0; j--) {
                    bottomx[j][i] = (grid[j + 1][i] == 1) ? bottomx[j + 1][i] + 1 : 0;
                }
            }

            int[][] lefty = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 1; j < m; j++) {
                    lefty[i][j] = (grid[i][j - 1] == 1) ? lefty[i][j - 1] + 1 : 0;
                }
            }

            int[][] righty = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = m - 2; j >= 0; j--) {
                    righty[i][j] = (grid[i][j + 1] == 1) ? righty[i][j + 1] + 1 : 0;
                }
            }

            List<Star> sp = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 1) {
                        int p = Math.min(Math.min(topx[i][j], bottomx[i][j]), Math.min(lefty[i][j], righty[i][j]));
                        if (p > 0) {
                            mrk[i][j] = true;
                            sp.add(new Star(i + 1, j + 1, p));
                            color(i, j, p);
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 1 && !mrk[i][j]) {
                        out.println(-1);
                        return;
                    }
                }
            }

            out.println(sp.size());
            for (Star s : sp) {
                out.println(s.x + " " + s.y + " " + s.r);
            }

        }

        private void color(int x, int y, int p) {
            for (int i = x; i >= x - p; i--) {
                mrk[i][y] = true;
            }
            for (int i = y; i >= y - p; i--) {
                mrk[x][i] = true;
            }
            for (int i = x; i <= x + p; i++) {
                mrk[i][y] = true;
            }
            for (int i = y; i <= y + p; i++) {
                mrk[x][i] = true;
            }
        }

        private class Star {
            int x;
            int y;
            int r;

            public Star(int x, int y, int r) {
                this.x = x;
                this.y = y;
                this.r = r;
            }

        }

    }

    static class FastScanner {
        private BufferedReader bufferedReader;
        private StringTokenizer stringTokenizer;

        public FastScanner(InputStream inputStream) {
            bufferedReader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (stringTokenizer == null || !stringTokenizer.hasMoreElements()) {
                try {
                    stringTokenizer = new StringTokenizer(bufferedReader.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return stringTokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            String ret = "";
            try {
                ret = bufferedReader.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return ret;

        }
    }
}

