					if(cur[i].charAt(j) == '*') up[i][j] = 1 + up[i-1][j];
					else up[i][j] = -1;
				}

				if(j == 0){
					if(cur[i].charAt(j) == '*') left[i][j] = 0;
					else left[i][j] = -1;
				}else{
