import java.io.*;

public class problem1015E1 {
	public static void main(String[] args) throws IOException {
		Scanner console = new Scanner(System.in);
		int n = console.nextInt();
		int m = console.nextInt();
		char[][] characters = new char[n][m];
		for (int i = 0; i < n; i++) {
			characters[i] = console.next().toCharArray();
		}
		Queue<Integer> savedstarts = new LinkedList<>();
		int offset;
		for (int i = 1; i < n - 1; i++) {
			for (int j = 1; j < m - 1; j++) {
				if (characters[i][j] == '*') {
					offset = 1;
					while (i - offset >= 0 && i + offset < n && j - offset >= 0 && j + offset < m
							&& characters[i - offset][j] == '*'
							&& characters[i + offset][j] == '*'
							&& characters[i][j - offset] == '*'
							&& characters[i][j + offset] == '*')
						offset++;
					if (offset - 1 != 0) {
						savedstarts.add(i + 1);
						savedstarts.add(j + 1);
						savedstarts.add(offset - 1);
					}
				}
			}
		}
		Queue<Integer> tempq = new LinkedList<>();
		int temp;
		while (savedstarts.size() >= 3) {
			int r = savedstarts.remove();
			int c = savedstarts.remove();
			int s = savedstarts.remove();
			tempq.add(r);
			tempq.add(c);
			tempq.add(s);
		}
		Set<Integer> stars = new HashSet<>();
		int row, col, off;
		while (!tempq.isEmpty()) {
			row = tempq.remove();
			col = tempq.remove();
			off = tempq.remove();
			stars.add(row * m + col);
			while (off != 0) {
				stars.add((row + off) * m + col);
				stars.add((row - off) * m + col);
				stars.add(row * m + (col + off));
				stars.add(row * m + (col - off));
				off--;
			}
		}
		int starcount = 0;
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (characters[i][j] == '*')
					starcount++;
			}
		}
		if (starcount != stars.size()) {
			System.out.println(-1);
			return;
		}
		List<int[]> starsInfo = new ArrayList<>();
		while (!tempq.isEmpty()) {
			int r = tempq.remove();
			int c = tempq.remove();
			int s = tempq.remove();
			starsInfo.add(new int[]{r, c, s});
		}
		System.out.println(starsInfo.size());
		for (int[] st : starsInfo) {
			System.out.println(st[0] + " " + st[1] + " " + st[2]);
		}
	}
}

for (int i = 0; i<savedstarts.size()/3; i++) {
    temp = savedstarts.remove();
