    private void solve() throws IOException {
        int n = in.nextInt(), m = in.nextInt();
        boolean[][] map = new boolean[n][m];
        boolean[][] used = new boolean[n][m];
        for (int i = 0, j = 0; i < n; i++, j = 0) {
            for (char c : in.next().toCharArray()) {
                used[i][j] = !(map[i][j] = c == '*');
                j++;
            }
        }

        int k = 0;
