                        if (l == 1)
                            used[i][j] = true;
                        used[i - l][j] = used[i + l][j] = used[i][j - l] = used[i][j + l] = true;
                        l++;
                    }
                    l--;
                    if (l > 0) {
                        x[k] = i;
                        y[k] = j;
                        s[k++] = l;
                    }
                }
            }
        }

        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                if (!used[i][j] && map[i][j]) {
                    out.println(-1);
                    return;
                }

        out.println(k);
        for (int i = 0; i < k; i++)
            out.println(x[i] + 1 + " " + (y[i] + 1) + " " + s[i]);
    }

