			{
				if(board[i][j])
				{
					if(board[i-1][j])
						q[i][j] = q[i-1][j] + 1;
					if(board[i][j-1])
						w[i][j] = w[i][j-1] + 1;
				}
			}
		}
		for(int i = R-2; i >= 1; i--)
		{
			for(int j = C-2; j >= 1; j--)
			{
				if(board[i][j])
				{
					if(board[i+1][j])
						e[i][j] = e[i+1][j] + 1;
					if(board[i][j+1])
						r[i][j] = r[i][j+1] + 1;
				}
			}
		}

		LinkedList<int[]> x = new LinkedList<>();
		for(int i = 1; i < R-1; i++)
		{
			for(int j = 1; j < C-1; j++)
			{
				int result = Math.min(Math.min(q[i][j], w[i][j]), Math.min(e[i][j], r[i][j]));
				if(result > 0) x.add(new int[] {i+1, j+1, result});
			}
		}

		boolean[][] comp = new boolean[R][C];
		for(int[] temp : x)
		{
			int a = temp[0]-1;
			int b = temp[1]-1;
			int size = temp[2];
			comp[a][b] = true;
			for(int i = 1; i < size; i++)
				comp[a-i][b] = comp[a+i][b] = comp[a][b-i] = comp[a][b+i] = true;

		}

		for(int i = 0; i < R; i++)
		{
			for(int j = 0; j < C; j++)
			{
				if(board[i][j] != comp[i][j])
				{
					System.out.println(-1);
					System.exit(0);
				}
			}
		}


		StringBuilder sb = new StringBuilder();
		sb.append(x.size() + "\n");
		for(int[] temp: x)
			sb.append(temp[0] + " " + temp[1] + " " + temp[2] + "\n");

		out.println(sb.toString());
		out.close();
	}


	public static class FastScanner {
		private InputStream stream;
		private byte[] buf = new byte[1024];
		private int curChar;
		private int numChars;

		public FastScanner(InputStream stream) {
			this.stream = stream;
		}

		int read() {
			if (numChars == -1)
				throw new InputMismatchException();
			if (curChar >= numChars) {
				curChar = 0;
				try {
					numChars = stream.read(buf);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (numChars <= 0)
					return -1;
			}
			return buf[curChar++];
		}

		boolean isSpaceChar(int c) {
			return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
		}

		boolean isEndline(int c) {
			return c == '\n' || c == '\r' || c == -1;
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

		public long nextLong() {
			return Long.parseLong(next());
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public String next() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = read();
			} while (!isSpaceChar(c));
			return res.toString();
		}

		public String nextLine() {
			int c = read();
			while (isEndline(c))
				c = read();
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = read();
			} while (!isEndline(c));
			return res.toString();
		}
	}

}

import java.io.OutputStream;
