public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        E1StarsDrawingEasyEdition solver = new E1StarsDrawingEasyEdition();
        solver.solve(1, in, out);
        out.close();
    }

    static class E1StarsDrawingEasyEdition {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] g = new char[n][];
            for (int i = 0; i < n; ++i) {
                g[i] = in.nextCharArray();
            }
            PriorityQueue<E1StarsDrawingEasyEdition.Star> stars = new PriorityQueue<>(Comparator.reverseOrder());
            for (int i = 1; i < n - 1; ++i) {
                for (int j = 1; j < m - 1; ++j) {
                    if (isMiddle(g, i, j)) {
                        int size = 0;
                        while (size + i < n && size + j < m && i - size >= 0 && j - size >= 0 && isOkey(g, i, j, size)) {
                            ++size;
                        }
                        if (size > 0) {
                            stars.add(new E1StarsDrawingEasyEdition.Star(i, j, size));
                        }
                    }
                }
            }
            int ans = 0;
            List<E1StarsDrawingEasyEdition.Star> res = new ArrayList<>(stars.size());

            while (!stars.isEmpty() && !isCovered(g)) {
                E1StarsDrawingEasyEdition.Star s = stars.poll();
                res.add(s);
                ans++;
                cover(s, g);
            }
            if (isCovered(g)) {
                out.println(ans);
                for (E1StarsDrawingEasyEdition.Star st : res) {
                    out.println((st.r + 1) + " " + (st.c + 1) + " " + (st.sz - 1));
                }
            } else {
                out.println(-1);
            }
        }

        private void cover(E1StarsDrawingEasyEdition.Star s, char[][] g) {
            int x = s.r, y = s.c;
            int sz = 0;
            g[x][y] = '.';
            while (sz < s.sz) {
                fillCell(g, x, y, sz);
                ++sz;
            }
        }

        private void fillCell(char[][] g, int x, int y, int sz) {
            g[x + sz][y] = '.';
            g[x - sz][y] = '.';
            g[x][y + sz] = '.';
            g[x][y - sz] = '.';
        }

        private boolean isCovered(char[][] g) {
            for (int i = 0; i < g.length; ++i) {
                for (int j = 0; j < g[0].length; ++j) {
                    if (g[i][j] == '*') return false;
                }
            }
            return true;
        }

        private boolean isOkey(char[][] g, int i, int j, int size) {
            return isValidDelta(g, i, j, size);
        }

        private boolean isMiddle(char[][] g, int i, int j) {
            if (g[i][j] != '*') return false;
            return isValidDelta(g, i, j, 1);
        }

        private boolean isValidDelta(char[][] g, int i, int j, int delta) {
            return g[i - delta][j] == '*' && g[i][j - delta] == '*' && g[i + delta][j] == '*' && g[i][j + delta] == '*';
        }

        static class Star implements Comparable<E1StarsDrawingEasyEdition.Star> {
            final int r;
            final int c;
            final int sz;

            Star(int r, int c, int sz) {
                this.r = r;
                this.c = c;
                this.sz = sz;
            }

            public int compareTo(E1StarsDrawingEasyEdition.Star o) {
                return Integer.compare(sz, o.sz);
            }

            public String toString() {
                return String.format("(%d, %d, sz=%d)", r, c, sz);
            }

        }

    }

    static class InputReader {
        private InputStream stream;
        private static final int DEFAULT_BUFFER_SIZE = 1 << 16;
        private static final int EOF = -1;
        private byte[] buf = new byte[DEFAULT_BUFFER_SIZE];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (this.numChars == EOF) {
                throw new UnknownError();
            } else {
                if (this.curChar >= this.numChars) {
                    this.curChar = 0;

                    try {
                        this.numChars = this.stream.read(this.buf);
                    } catch (IOException ex) {
                        throw new InputMismatchException();
                    }

                    if (this.numChars <= 0) {
                        return EOF;
                    }
                }

                return this.buf[this.curChar++];
            }
        }

        public int nextInt() {
            int c;
            for (c = this.read(); isSpaceChar(c); c = this.read()) {
            }

            byte sgn = 1;
            if (c == 45) {
                sgn = -1;
                c = this.read();
            }

            int res = 0;

            while (c >= 48 && c <= 57) {
                res *= 10;
                res += c - 48;
                c = this.read();
                if (isSpaceChar(c)) {
                    return res * sgn;
                }
            }

            throw new InputMismatchException();
        }

        public String next() {
            int c;
            while (isSpaceChar(c = this.read())) {
            }

            StringBuilder result = new StringBuilder();
            result.appendCodePoint(c);

            while (!isSpaceChar(c = this.read())) {
                result.appendCodePoint(c);
            }

            return result.toString();
        }

        public static boolean isSpaceChar(int c) {
            return c == 32 || c == 10 || c == 13 || c == 9 || c == EOF;
        }

        public char[] nextCharArray() {
            return next().toCharArray();
        }

    }
}

void cover(E1StarsDrawingEasyEdition.Star s, char[][] g) {
    int x = s.r, y = s.c;
    int sz = 0;
    g[x][y] = '.';
    while (sz < s.sz) {
        fillCell(g, x, y, sz);
        ++sz;
    }
}

