public class Sol2{
	static class triple{
		int x;
		int y;
		int size; 
		public triple(int x, int y, int size) {
			this.x = x;
			this.y = y;
			this.size = size;
		}
	}
	public static int total;
	public static boolean correct = true;
	public static ArrayList<triple> ans = new ArrayList<triple>();
	public static void main(String[] args) throws IOException{
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int m = sc.nextInt();
		boolean board[][] = new boolean[n][m];
		boolean check[][] = new boolean[n][m];
		for(int i=0; i<n; i++) {
			String next = sc.next();
			for(int j=0; j<m; j++) {
				board[i][j] = next.charAt(j)=='*';
			}
		}
		for(int i=1; i<n-1; i++) {
			for(int j=1; j<m-1; j++) {
				if(!board[i][j]) continue;
				int size = Math.min(i, n-i-1);
				size = Math.min(size, j);
				size = Math.min(size, m-j-1);
				for(int k=1; k<=size; k++) {
					if(board[i+k][j] && board[i-k][j]
							&& board[i][j+k] && board[i][j-k]) {
						check[i][j] = true;
						check[i+k][j] = true; check[i-k][j] = true;
						check[i][j+k] = true; check[i][j-k] = true;
						triple t = new triple(i+1,j+1,k);
						if(k>1) {
							ans.remove(ans.size()-1);
						}
						ans.add(t);
						continue;
					}
					break;
				}
			}
		}
		for(int i=0; i<n; i++) {
			for(int j=0; j<m; j++) {
				if(board[i][j]) {
					if(!check[i][j]) {
						correct = false;
					}
				}
			}
		}
		total = ans.size();
		if(!correct) System.out.println(-1);
		else  {
			System.out.println(total);
