					dp[i][j].up=dp[i-1][j].up+1;
				}else {
					dp[i][j].up=0;
				}

				if(arr[i][j-1]=='*') {
					dp[i][j].left=1+dp[i][j-1].left;
				}else {
					dp[i][j].left=0;
				}

			}
		}

		for(int i=n-2;i>=0;i--) {
