            boolean[][] s = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                String in = br.nt();
                for (int j = 0; j < m; j++) {
                    s[i][j] = in.charAt(j) == '*';
                }
            }
            ArrayList<Point> out = new ArrayList<Point>();
            boolean[][] hit = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (s[i][j]) {
                        int a = 0;
                        int b = Math.min(Math.min(n - i-1, m - j-1), Math.min(i, j));
                        for (int k = 1; k <= b; k++) {
                            if (!s[i][j + k] || !s[i][j - k] || !s[i + k][j] || !s[i - k][j])
                                break;
                            hit[i][j + k] = true;
                            hit[i][j - k] = true;
                            hit[i + k][j] = true;
                            hit[i - k][j] = true;
                            a++;
                        }
                        if (a != 0) {
                            hit[i][j] = true;
                            out.add(new Point(i, j, a));
                        }
                    }
                }
            }
            boolean good = true;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (s[i][j] && !hit[i][j]) {
                        good = false;
                    }
                }
