public class Main {

    static int H, W;
    static char[][] C;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        H = sc.nextInt();
        W = sc.nextInt();
        C = new char[H][];
        for (int i = 0; i < H; i++) {
            C[i] = sc.next().toCharArray();
        }

        List<Cord> cords = solve();
        if (cords == null) {
            System.out.println(-1);
        } else {
            PrintWriter pw = new PrintWriter(System.out);
            pw.println(cords.size());
            for (Cord c : cords) {
                pw.println((c.h + 1) + " " + (c.w + 1) + " " + c.size);
            }
            pw.flush();
        }
    }

    static List<Cord> solve() {
        int[][] u = new int[H][W];
        for (int w = 0; w < W; w++) {
            int cnt = 0;
            for (int h = 0; h < H; h++) {
                u[h][w] = cnt;
                if (C[h][w] == '*') cnt++;
                else cnt = 0;
            }
        }
        int[][] d = new int[H][W];
        for (int w = 0; w < W; w++) {
            int cnt = 0;
            for (int h = H - 1; h >= 0; h--) {
                d[h][w] = cnt;
                if (C[h][w] == '*') cnt++;
                else cnt = 0;
            }
        }
        int[][] l = new int[H][W];
        for (int h = 0; h < H; h++) {
            int cnt = 0;
            for (int w = 0; w < W; w++) {
                l[h][w] = cnt;
                if (C[h][w] == '*') cnt++;
                else cnt = 0;
            }
        }
        int[][] r = new int[H][W];
        for (int h = 0; h < H; h++) {
            int cnt = 0;
            for (int w = W - 1; w >= 0; w--) {
                r[h][w] = cnt;
                if (C[h][w] == '*') cnt++;
                else cnt = 0;
            }
        }

        int[][] rowmask = new int[H][W + 1];
        int[][] colmask = new int[H + 1][W];
        List<Cord> cords = new ArrayList<>();
        for (int h = 0; h < H; h++) {
            for (int w = 0; w < W; w++) {
                if (C[h][w] != '*') continue;

                int size = min(l[h][w], r[h][w], u[h][w], d[h][w]);
                if (size >= 1) {
                    cords.add(new Cord(h, w, size));
                    rowmask[h][w - size]++;
                    rowmask[h][w + size + 1]--;
                    colmask[h - size][w]++;
                    colmask[h + size + 1][w]--;
                }
            }
        }

        for (int h = 0; h < H; h++) {
            for (int wi = 1; wi < W; wi++) {
                rowmask[h][wi] += rowmask[h][wi - 1]; // fixed line
            }
        }

        for (int w = 0; w < W; w++) {
            for (int hi = 1; hi < H; hi++) {
                colmask[hi][w] += colmask[hi - 1][w];
            }
        }

        for (int h = 0; h < H; h++) {
            for (int w = 0; w < W; w++) {
                if (C[h][w] == '*' && (rowmask[h][w] == 0 && colmask[h][w] == 0)) return null;
            }
        }

        return cords;
    }

    static class Cord {
        int h, w, size;

        public Cord(int h, int w, int size) {
            this.h = h;
            this.w = w;
            this.size = size;
        }
    }

