class Solve {
  static final int oo = (int) 1e9;
  Kattio io;
  String s;

  Solve(Kattio io) {
    this.io = io;
  }

  boolean check(String s)
  {
    boolean hasNumber = false;
    boolean hasLowerCase = false;
    boolean hasUpperCase = false;
    for (int i=0; i<s.length(); i++)
    {
      char c=s.charAt(i);
      if ('0'<=c && c<='9') hasNumber = true;
      if ('a'<=c && c<='z') hasLowerCase = true;
      if ('A'<=c && c<='Z') hasUpperCase = true;
    }
    return (hasNumber && hasLowerCase && hasUpperCase);
  }

  String check0()
  {
    if (check(s)) return s;
    return "";
  }

  String check1()
  {
    for (int i=0; i<s.length(); i++)
    {
      String p;
      p=s.substring(0,i)+"0";
      if (i+1<s.length()) p += s.substring(i+1,s.length());
      if (check(p)) return p;
      p=s.substring(0,i)+"a";
      if (i+1<s.length()) p += s.substring(i+1,s.length());
      if (check(p)) return p;
      p=s.substring(0,i)+"A";
      if (i+1<s.length()) p += s.substring(i+1,s.length());
      if (check(p)) return p;
    }
    return "";
  }

  String check2()
  {
    for (int i=0; i+1<s.length(); i++)
    {
      String p;
      p=s.substring(0,i)+"0a";
      if (i+2<s.length()) p += s.substring(i+2,s.length());
      if (check(p)) return p;
      p=s.substring(0,i)+"0A";
      if (i+2<s.length()) p += s.substring(i+2,s.length());
      if (check(p)) return p;
      p=s.substring(0,i)+"Aa";
      if (i+2<s.length()) p += s.substring(i+2,s.length());
      if (check(p)) return p;
    }
    return "";
  }

  String check3()
  {
    for (int i=0; i+2<s.length(); i++)
    {
      String p=s.substring(0,i)+"0aA"+s.substring(i+3,s.length());
      if (check(p)) return p;
    }
    return "";
  }

  void main() {
    s = io.getWord();
    if (check0()!="")
      io.println(check0());
    else
    if (check1()!="")
      io.println(check1());
    else
    if (check2()!="")
      io.println(check2());
    else
      io.println(check3());

  }
}


class Kattio extends PrintWriter {
  public Kattio(InputStream i) {
    super(new BufferedOutputStream(System.out));
    r = new BufferedReader(new InputStreamReader(i));
  }

  public Kattio(InputStream i, OutputStream o) {
    super(new BufferedOutputStream(o));
    r = new BufferedReader(new InputStreamReader(i));
  }

  public boolean hasMoreTokens() {
    return peekToken() != null;
  }

  public int getInt() {
    return Integer.parseInt(nextToken());
  }

  public double getDouble() {
    return Double.parseDouble(nextToken());
