public class Main {

    private static boolean isValid(String pass) {
        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasDigit = false;

        for (int i = 0; i < pass.length(); i++) {
            char c = pass.charAt(i);
            if (Character.isLowerCase(c)) {
                hasLower = true;
            } else if (Character.isUpperCase(c)) {
                hasUpper = true;
            } else if (Character.isDigit(c)) {
                hasDigit = true;
            }
        }

        return hasLower && hasUpper && hasDigit;
    }

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int num = scan.nextInt();
        scan.nextLine();

        String[] p = {"a", "A", "1", "aA", "a1", "A1", "aA1"};

        for (int i = 0; i < num; i++) {
            boolean solutionFound = false;
            String pass = scan.nextLine();

            if (isValid(pass)) {
                solutionFound = true;
                System.out.println(pass);
            }

            for (int j = 0; j < p.length; j++) {
                if (solutionFound) {
                    break;
                }

                for (int k = 0; k + p[j].length() <= pass.length(); k++) {
                    String begin = pass.substring(0, k);
                    String end = pass.substring(k + p[j].length());
                    String test = begin + p[j] + end;
                    if (isValid(test)) {
                        System.out.println(test);
                        solutionFound = true;
                        break;
                    }
                }
            }
        }
    }
}

