public class CFA {
    BufferedReader br;
    PrintWriter out;
    StringTokenizer st;
    boolean eof;
    private static final long MOD = 998244353L;
    private static final int[] dx = {0, -1, 0, 1};
    private static final int[] dy = {1, 0, -1, 0};
    private static final String yes = "Yes";
    private static final String no = "No";

    char[] arr = {'!', 'A', 'a', '!', '0'};
    void solve() throws IOException {
        int T = nextInt();
        for (int t = 0; t < T; t++) {
            String str = nextString();
            helper(str);
        }
    }

    void helper(String str) {
        char[] tmp = str.toCharArray();
        int mask = 0;
        for (char c : tmp) {
            if (c >= 'A' && c <= 'Z') {
                mask |= 1;
            }
            else if (c >= 'a' && c <= 'z') {
                mask |= 2;
            }
            else {
                mask |= 4;
            }
        }

        if (mask == 7) {
            outln(str);
            return;
        }

        if (mask == 1 || mask == 2 || mask == 4) {
            int need = 7 - mask;
            tmp[0] = arr[need & (need - 1)];
            need = need & -need;
            tmp[1] = arr[need];

            outln(new String(tmp));
            return;
        }

        List<Integer> l1 = new ArrayList<>();
        List<Integer> l2 = new ArrayList<>();
        List<Integer> l3 = new ArrayList<>();
        for (int i = 0; i < tmp.length; i++) {
            char c = tmp[i];
            if (c >= 'A' && c <= 'Z') {
                l1.add(i);
            }
            else if (c >= 'a' && c <= 'z') {
                l2.add(i);
            }
            else {
                l3.add(i);
            }
        }

        int nxt = 7 - mask;
        if (l1.size() >= 2) {
            tmp[l1.get(0)] = arr[nxt];
        }
        else if (l2.size() >= 2) {
            tmp[l2.get(0)] = arr[nxt];
        }
        else {
            tmp[l3.get(0)] = arr[nxt];
        }

        outln(new String(tmp));
    }

    void shuffle(int[] a) {
        int n = a.length;
        for(int i = 0; i < n; i++) {
            int r = i + (int) (Math.random() * (n - i));
            int tmp = a[i];
            a[i] = a[r];
            a[r] = tmp;
        }
    }

    long gcd(long a, long b) {
        while(a != 0 && b != 0) {
            long c = b;
            b = a % b;
            a = c;
        }
        return a + b;
    }

    private void outln(Object o) {
        out.println(o);
    }
    private void out(Object o) {
        out.print(o);
    }
    private void formatPrint(double val) {
        System.out.format("%.9f%n", val);
    }
    public CFA() throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }
    public static void main(String[] args) throws IOException {
        new CFA();
    }

    public long[] nextLongArr(int n) throws IOException{
        long[] res = new long[n];
        for(int i = 0; i < n; i++)
            res[i] = nextLong();
        return res;
    }
    public int[] nextIntArr(int n) throws IOException {
        int[] res = new int[n];
        for(int i = 0; i < n; i++)
            res[i] = nextInt();
        return res;
    }
    public String nextToken() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (Exception e) {
                eof = true;
                return null;
            }
        }
        return st.nextToken();
    }
    public String nextString() {
        try {
            return br.readLine();
        } catch (IOException e) {
            eof = true;
            return null;
        }
    }
    public int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }
    public long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }
    public double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }
}

