    public static void main(String[] args) {
        FastReader s = new FastReader();
        int T = s.nextInt();
        while (T-- > 0) {
            String str = s.nextLine();
            int lowercount = 0;
            int uppercount = 0;
            int digitcount = 0;
            for (int i = 0; i < str.length(); i++) {
                char ch = str.charAt(i);
                if (Character.isUpperCase(ch)) {
                    uppercount++;
                } else if (Character.isLowerCase(ch)) {
                    lowercount++;
                } else {
                    digitcount++;
                }
            }

            List<Character> change = new ArrayList<>();
            if (lowercount == 0) {
                change.add('a');
            }
            if (uppercount == 0) {
                change.add('A');
            }
            if (digitcount == 0) {
                change.add('0');
            }

            int missingCount = change.size();

            if (missingCount == 0) {
                System.out.println(str);
            } else if (missingCount == 1) {
                // Find any character whose category appears more than once
                int idx = -1;
                for (int i = 0; i < str.length(); i++) {
                    char c = str.charAt(i);
                    int cnt = 0;
                    if (Character.isUpperCase(c)) {
                        cnt = uppercount;
                    } else if (Character.isLowerCase(c)) {
                        cnt = lowercount;
                    } else {
                        cnt = digitcount;
                    }
                    if (cnt > 1) {
                        idx = i;
                        break;
                    }
                }
                // Fallback (theoretically unreachable given problem constraints)
                if (idx == -1) {
                    idx = 0;
                }
                StringBuilder sb = new StringBuilder(str);
                sb.setCharAt(idx, change.get(0));
                System.out.println(sb);
            } else { // missingCount == 2
                StringBuilder sb = new StringBuilder();
                sb.append(change.get(0)).append(change.get(1))
                  .append(str.substring(2));
                System.out.println(sb);
            }
        }
    }
}

