public class VasyaAndPassword {

    public static void main(String[] args){
        BufferedInputStream bf = new BufferedInputStream(System.in);
        BufferedReader r = new BufferedReader(
                new InputStreamReader(bf, StandardCharsets.UTF_8));
        OutputStream out = new BufferedOutputStream ( System.out );
        try {
            int t = Integer.parseInt(r.readLine());
            if(t-->0){
                String s = r.readLine();
                char[] tc = s.toCharArray();
                int nl = 0, nu = 0, nn = 0;
                for(char c:tc){
                    if (c>='a' && c<='z') nl++;
                    if (c>='A' && c<='Z') nu++;
                    if (c>='0' && c<='9') nn++;
                }

                if (nl==0){
                    for(int i=0;i<s.length();i++){
                        char c = tc[i];
                        if ((c>='A' && c<='Z' && nu > 1)||(c>='0' && c<='9' && nn > 1)) {
                            tc[i] = 'a';
                            nl++;          // <-- added
                            break;
                        }
                    }
                }

                if (nu==0){
                    for(int i=0;i<s.length();i++){
                        char c = tc[i];
                        if ((c>='a' && c<='z' && nl > 1)||(c>='0' && c<='9' && nn > 1)) {
                            tc[i] = 'A';
                            nu++;          // <-- added
                            break;
                        }
                    }
                }

                if (nn==0){
                    for(int i=0;i<s.length();i++){
                        char c = tc[i];
                        if ((c>='A' && c<='Z' && nu > 1)||(c>='a' && c<='z' && nl > 1)) {
                            tc[i] = '0';
                            nn++;          // <-- added
                            break;
                        }
                    }
                }

                String ret = new String(tc);
                out.write((ret+"\n").getBytes());
            }
            out.flush();
        }catch(Exception ex){
            ex.printStackTrace();
        }

    }
}

