public class Main {

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();

        int T = fs.nextInt();
        for (int i = 0; i < T; i++) {
            String s = fs.next();
            int len = s.length();
            Map<String, Integer> map = check(s, len);

            if (map.size() == 3) {
                System.out.println(s);
            } else {
                if (map.size() == 1) {
                    if (map.containsKey("num")) {
                        for (int j = 0; j < len-1; j++) {
                            String replace = "Aa";
                            String tmp = "";
                            tmp = s.substring(0, j).concat(replace).concat(s.substring(j + 2));
                            if (check(tmp, len).size() == 3) {
                                System.out.println(tmp);
                                break;
                            }
                        }
                    } else if (map.containsKey("upper")) {
                        for (int j = 0; j < len-1; j++) {
                            String replace = "1a";
                            String tmp = "";
                            tmp = s.substring(0, j).concat(replace).concat(s.substring(j + 2));
                            if (check(tmp, len).size() == 3) {
                                System.out.println(tmp);
                                break;
                            }
                        }
                    } else {
                        for (int j = 0; j < len-1; j++) {
                            String replace = "1A";
                            String tmp = "";
                            tmp = s.substring(0, j).concat(replace).concat(s.substring(j + 2));
                            if (check(tmp, len).size() == 3) {
                                System.out.println(tmp);
                                break;
                            }
                        }
                    }
                } else if (map.size() == 2) {
                    if (!map.containsKey("num")) {
                        for (int j = 0; j < len; j++) {
                            String replace = "1";
                            String tmp = "";
                            tmp = s.substring(0, j).concat(replace).concat(s.substring(j + 1));
                            if (check(tmp, len).size() == 3) {
                                System.out.println(tmp);
                                break;
                            }
                        }

                    } else if (!map.containsKey("upper")) {
                        for (int j = 0; j < len; j++) {
                            String replace = "A";
                            String tmp = "";
                            tmp = s.substring(0, j).concat(replace).concat(s.substring(j + 1));
                            if (check(tmp, len).size() == 3) {
                                System.out.println(tmp);
                                break;
                            }
                        }

                    } else {
                        for (int j = 0; j < len; j++) {
                            String replace = "a";
                            String tmp = "";
                            tmp = s.substring(0, j).concat(replace).concat(s.substring(j + 1));
                            if (check(tmp, len).size() == 3) {
                                System.out.println(tmp);
                                break;
                            }
                        }
                    }
                }
            }
        }



    }

    static Map<String, Integer> check(String s, int len) {
        Map<String, Integer> map = new HashMap<>();
        for (int i = 0; i < len; i++) {
            if (s.charAt(i) >= 48 && s.charAt(i) <= 57) {
                if (!map.containsKey("num")) {
                    map.put("num", 1);
                } else {
                    map.put("num", map.get("num") + 1);
                }
            }
            if (s.charAt(i) >= 65 && s.charAt(i) <= 90) {
                if (!map.containsKey("upper")) {
                    map.put("upper", 1);
                } else {
                    map.put("upper", map.get("upper") + 1);
                }
            }
            if (s.charAt(i) >= 97 && s.charAt(i) <= 122) {
                if (!map.containsKey("lower")) {
                    map.put("lower", 1);
                } else {
                    map.put("lower", map.get("lower") + 1);
                }
            }
        }

        return map;
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() { return Integer.parseInt(next()); }

        long nextLong() { return Long.parseLong(next()); }

        double nextDouble() { return Double.parseDouble(next()); }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            }
            catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

