public class CF1051A {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        while (t-- > 0) {
            String s = sc.next();
            int countL = 0, countU = 0, countD = 0;
            for (int i = 0; i < s.length(); i++) {
                if (Character.isLowerCase(s.charAt(i))) countL++;
                else if (Character.isUpperCase(s.charAt(i))) countU++;
                else countD++;
            }
            if (countL > 0 && countU > 0 && countD > 0) {
                System.out.println(s);
                continue;
            }
            // exactly two categories are missing
            if ((countL == 0 && countD == 0) ||
                (countL == 0 && countU == 0) ||
                (countU == 0 && countD == 0)) {
                char[] arr = s.toCharArray();
                if (countL == 0 && countD == 0) {
                    arr[0] = 'a';
                    arr[1] = '8';
                } else if (countL == 0 && countU == 0) {
                    arr[0] = 'a';
                    arr[1] = 'A';
                } else {
                    arr[0] = '8';
                    arr[1] = 'A';
                }
                System.out.println(new String(arr));
                continue;
            }
            // exactly one category is missing
            char[] arr = s.toCharArray();
            char repl;
            if (countL == 0) repl = 'a';          // need lowercase
            else if (countU == 0) repl = 'A';     // need uppercase
            else repl = '1';                      // need digit

            // find a safe position to replace (belonging to a category that appears more than once)
            int idx = -1;
            for (int i = 0; i < arr.length; i++) {
                char c = arr[i];
                if (Character.isLowerCase(c)) {
                    if (countL > 1) { idx = i; break; }
                } else if (Character.isUpperCase(c)) {
                    if (countU > 1) { idx = i; break; }
                } else {
                    if (countD > 1) { idx = i; break; }
                }
            }
            // fallback – replace the first character (should not be needed for valid inputs)
            if (idx == -1) idx = 0;
            arr[idx] = repl;
            System.out.println(new String(arr));
        }
    }
}

