			str[1] = 'a';
		}
		else if (needLower && needDigit) {
			str[0] = 'a';
			str[1] = '1';
		}
		else {
			// exactly one category is missing
			char replacement = needUpper ? 'A' : (needLower ? 'a' : '1');
			for (int i = 0; i < str.length; i++) {
				char ch = str[i];
				if (Character.isUpperCase(ch) && cap > 1) {
					str[i] = replacement;
					break;
				}
				if (Character.isLowerCase(ch) && sm > 1) {
					str[i] = replacement;
					break;
				}
				if (Character.isDigit(ch) && dig > 1) {
					str[i] = replacement;
					break;
				}
				// if no safe position found, replace the first character
				if (i == str.length - 1) {
					str[0] = replacement;
				}
			}
		}
		return new String(str);
	}
}

