    static class Palindrome {

        static long mod = 1000000007;
        static long maxX = (long) 1e18;
        static long mod2 = 998244353;

        void solve(int testNumber, ScanReader in, PrintWriter out) {
            char[] s = in.next().toCharArray();

            if(ok(s)) {
                out.println(new String(s));
                return;
            }

            int n = s.length;

            char[] t = {'a','A','0'};

            for(int i = 0;i<n;i++) {
                char c = s[i];
                for(int j = 0;j<3;j++) {
                    s[i] = t[j];

                    if(ok(s)) {
                        out.println(new String(s));
                        return;
                    }
                }
                s[i] = c;
            }

            for(int i = 0;i<n - 1;i++) {
                char c = s[i],cc = s[i+1];
                for(int j = 0;j<3;j++) {
                    s[i] = t[j];
                    s[i+1] = t[(j+2)%3];
                    if(ok(s)) {
                        out.println(new String(s));
                        return;
                    }
                }
                s[i] = c;
                s[i+1] = cc;
            }

            s[0] = 'a';s[1] = 'A';s[2] = '0';
            out.println(new String(s));
        }

        boolean ok(char[] s) {
            boolean a = false,A = false, d =false;

            for(Character c : s) {
                if(c >= 'a' && c <= 'z') a= true;
                if(c>='A' && c<='Z') A = true;
                if(c>='0' && c<='9') d = true;
            }
            return a&&A&&d;
        }
    }

    static class ScanReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;
        private BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        public ScanReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();

            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }

                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

        public int nextInt() {
            int c = read();

            while (isSpaceChar(c))
                c = read();

            int sgn = 1;

            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res =+ c - '0';
                c = read();
            }
            while (!isSpaceChar(c));

            return res * sgn;
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;

            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            while (!isSpaceChar(c));
            return res * sgn;
        }

        public double nextDouble() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            double res = 0;
            while (!isSpaceChar(c) && c != '.') {
                if (c == 'e' || c == 'E')
                    return res * Math.pow(10, nextInt());
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            if (c == '.') {
                c = read();
                double m = 1;
                while (!isSpaceChar(c)) {
                    if (c == 'e' || c == 'E')
                        return res * Math.pow(10, nextInt());
                    if (c < '0' || c > '9')
                        throw new InputMismatchException();
                    m /= 10;
                    res += (c - '0') * m;
                    c = read();
                }
            }
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            }
            while (!isSpaceChar(c));

            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null)
                return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public String next() {
            return readString();
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);
        }
    }
}

