public class Solution {
	static FastScanner scr=new FastScanner();
	static PrintStream out=new PrintStream(System.out);
	static StringBuilder sb=new StringBuilder();

	static long gcd(long a,long b){
		if(b==0) {
			return a;
		}

		return gcd(b,a%b);
	}

	static long modPow(long base,long exp,long mod) {
		if(exp==0) {
			return 1;
		}
		if(exp%2==0) {
			long res=(modPow(base,exp/2,mod));
			return (res*res)%mod;
		}
		return (base*modPow(base,exp-1,mod))%mod;
	}
	static class pair{
		int x;int y;
		pair(int x,int y){ 
			this.x=x;this.y=y;

		}
	}
	static class FastScanner {
		BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st=new StringTokenizer("");
	 	String next() {
	 		while (!st.hasMoreTokens())
	 			try {
	 				st=new StringTokenizer(br.readLine());
	 			} catch (IOException e) {
	 				e.printStackTrace();
	 			}
	 			return st.nextToken();
		}
	 	  int[]  sort(int a[]) {

	        int multiplier = 1, len = a.length, max = Integer.MIN_VALUE;
	        int b[] = new int[len];
	        int bucket[];
	        for (int i = 0; i < len; i++) if (max < a[i]) max = a[i];
	        while (max / multiplier > 0) {
	            bucket = new int[10];
	            for (int i = 0; i < len; i++) bucket[(a[i] / multiplier) % 10]++;
	            for (int i = 1; i < 10; i++) bucket[i] += (bucket[i - 1]);
	            for (int i = len - 1; i >= 0; i--) b[--bucket[(a[i] / multiplier) % 10]] = a[i];
	            for (int i = 0; i < len; i++) a[i] = b[i];
	            for (int i = 0; i < len; i++) a[i] = b[i];
	            multiplier *= 10;
	        }
	        return a;
	    }
		int []reverse(int a[]){
			int b[]=new int[a.length];
			int index=0;
			for(int i=a.length-1;i>=0;i--) {
				b[index]=a[i];
			}
			return b;
		}
		int nextInt() {
			return Integer.parseInt(next());
		}
		int[] readArray(int n) {
			int[] a=new int[n];
			for (int i=0; i<n; i++) a[i]=nextInt();
			return a;
		}
		long[] readLongArray(int n) {
			long  [] a=new long  [n];
			for (int i=0; i<n; i++) a[i]=nextLong();
			return a;
		}
		long nextLong() {
			return Long.parseLong(next());
		}
	}

