		int big=0;
		int small=0;
		int digit=0;

		for(int i=0;i<n;i++) {
			if(c[i]>='A' && c[i]<='Z') {
				big++;
			}
			if(c[i]>='a' && c[i]<='z') {
				small++;
			}
			if(c[i]>='0' && c[i]<='9') {
				digit++;
			}
		}
		if(big!=0 && small!=0 && digit!=0 ) {
			out.println(c);
			return;
		}
		for(int i=0;i<n;i++) {
