			if(c[i]>='a' && c[i]<='z' && small>1) {
				if(big==0) {
					c[i]='A';
					big++;
					small--;
				}else if(digit==0){
					c[i]='1';
					small--;
					digit++;
				}
			}
			if(c[i]>='0' && c[i]<='9' && digit>1) {
				if(small==0) {
					c[i]='a';
					digit--;
					small++;
				}else if(big==0){
					c[i]='A';
					digit--;
