                System.out.println(s.substring(0,i)+put+s.substring(i+1));
                break;
            }
            else if(s.charAt(i)>=65 && s.charAt(i)<=90 && max==2){
                System.out.println(s.substring(0,i)+put+s.substring(i+1));
                break;
            }
            else if(s.charAt(i)>=48 && s.charAt(i)<=57 && max==3){
                System.out.println(s.substring(0,i)+put+s.substring(i+1));
                break;
            }  
        }
    }
