            int len =s.length();
            int flaglow=0,flaghigh=0,flagnum=0;
            int c1=0,c2=0,c3=0;
            for(int i=0;i<len;i++){
                char c = s.charAt(i);
                if(c>=97 && c<=122){
                    flaglow = 1;
                    c1++;
                }
                else if(c>=65 && c<=90){
                    flaghigh=1;
                    c2++;
                }
                else{
                    flagnum=1;c3++;
                }
            }
            if(flaghigh==1 && flaglow==1 && flagnum==1){
                System.out.println(s);
            }
            else{
                int max = Math.max(Math.max(c1,c3),c2);
