		Scanner sc = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);
		int t = sc.nextInt();
		sc.nextLine();
		while(t--!=0)
		{
			StringBuffer sb = new StringBuffer(sc.nextLine());
			int isNumber = 0, isCapital = 0, isSmall = 0;
			for(int i=0;i<sb.length();i++)
			{
				int k = getCharDetail(sb.charAt(i));
				if(k==0)
					isSmall++;
				else if(k==1)
					isCapital++;
				else
					isNumber++;
			}
			if(isSmall>0 && isCapital>0 && isNumber>0)
				out.println(sb.toString());
			else
			{
				int need = 0;
				if(isSmall==0)
					need++;
				if(isCapital==0)
					need++;
				if(isNumber==0)
					need++;
				for(int i=0;i<sb.length()-need+1;i++)
				{
					boolean flag = true;
					int tmpSmall = isSmall;
					int tmpCapital = isCapital;
					int tmpNumber = isNumber;
					for(int j=i;j<i+need;j++)
					{
						int k = getCharDetail(sb.charAt(j));
						if(k==0 && tmpSmall>1)
							tmpSmall--;
						else if(k==1 && tmpCapital>1)
							tmpCapital--;
						else if(k==2 && tmpNumber>1)
							tmpNumber--;
						else
						{
							flag = false;
							break;
						}
					}
					if(flag)
					{
						String replaceStr = "";
						if (isSmall == 0) {
							replaceStr += 'a';
						}
						if (isCapital == 0) {
							replaceStr += 'A';
						}
						if (isNumber == 0) {
							replaceStr += '1';
						}
						sb.replace(i, i+need, replaceStr);
						break;
					}
				}
				out.println(sb.toString());
			}
		}
		sc.close();
		out.close();
	}
}

