        int flu = 0;
        int fll = 0;
        int fld = 0;
        for(int i = 0;i<n;++i) {
            char x = ch[i];
            if((int)x >= 65 && (int)x <= 90) {
                flu = 1;
            }   
            else if((int)x >= 97 && (int)x <= 122) {
                fll = 1;
            }   
            else if((int)x < 65) {
                fld = 1;
            }   
            if(flu == 1 && fll == 1 && fld == 1) {
                return true;
            }
        }
        return false;
    }
    static void solve(char[] ch) {
        int n = ch.length;
        if(ok(ch)) {
            out.println(ch);
            return;
        }

        for(int i = 0;i<n;i++) {
            char[] c = String.valueOf(ch).toCharArray();
            c[i] = '1';
            if(ok(c)) {
                out.println(c);
                return;
