		int fld = 0;
		for(int i = 0;i<n;++i) {
			char x = ch[i];
			if ((int)x >= 65 && (int)x <= 90) {
				flu = 1;
			}	
			else if ((int)x >= 97 && (int)x <= 122) {
				fll = 1;
			}	
			else if ((int)x < 65) {
				fld = 1;
			}	
			if(flu == 1 && fll == 1 && fld == 1) {
				return true;
			}
		}
		return false;
	}
	static void solve(char[] ch) {
		int n = ch.length;
		if(ok(ch)) {
			out.println(ch);
			return;
		}

		for(int i = 0;i<n;i++) {
			char[] c = String.valueOf(ch).toCharArray();
			c[i] = '1';
			if(ok(c)) {
				out.println(c);
				return;
			}
			c[i] = 'a';
			if(ok(c)) {
				out.println(c);
				return;
			}
			c[i] = 'A';
			if(ok(c)) {
				out.println(c);
				return;
			}
		}

		if(Character.isUpperCase(ch[2])){
			ch[0] = 'a';
			ch[1] = '1';
			out.println(ch);
			return;
		}
		if(Character.isLowerCase(ch[2])) {
			ch[0] = 'A';
			ch[1] = '1';
			out.println(ch);
			return;
		}
		if(Character.isDigit(ch[2])) {
			ch[0] = 'a';
			ch[1] = 'A';
			out.println(ch);
			return;
		}
	}
	public static void main(String args[]) throws Exception {
		FastReader sc = new FastReader();
		long s = System.currentTimeMillis();
		int t = sc.nextInt();
		while(t-- > 0 ) {
			char[] ch = sc.nextLine().toCharArray();
			solve(ch);
		}
		flush();
		long e = System.currentTimeMillis();
	}
}

