                firstLowerCase = i;
                lowerCaseFlag = true;
            }
        }
        if (!capitalFlag) {
            for (int j = 0; j < str.length(); j++) {
                if (j != firstCapital && j != firstLowerCase && j != firstNumber) {
                    strNew.setCharAt(j, 'A');
                    firstCapital = j;
                    break;
                }
            }
        }
        if (!lowerCaseFlag) {
            for (int j = 0; j < str.length(); j++) {
                if (j != firstCapital && j != firstLowerCase && j != firstNumber) {
                    strNew.setCharAt(j, 'a');
                    firstLowerCase = j;
