public class Main {
    private static boolean check(String string) {
        boolean[] flag = new boolean[3];
        int i, length = string.length();
        for (i = 0; i < length; i++) {
            char ch = string.charAt(i);
            if (ch >= '0' && ch <= '9') {
                flag[0] = true;
            } else if (ch >= 'a' && ch <= 'z') {
                flag[1] = true;
            } else if (ch >= 'A' && ch <= 'Z') {
                flag[2] = true;
            }
        }
        for (i = 0; i < 3; i++) {
            if (!flag[i]) {
                return false;
            }
        }
        return true;
    }

    private static String solve1(String string) {
        int i, length = string.length();
        char[] candidate = "aA1".toCharArray();
        for (i = 0; i < length; i++) {
            for (char ch : candidate) {
                String temp = string.substring(0, i) + ch + string.substring(i + 1);
                if (check(temp)) {
                    return temp;
                }
            }
        }
        return null;
    }

    private static String solve2(String string) {
        int length = string.length();
        String[] candidate = new String[]{"aA", "a1", "A1"};
        for (int i = 0; i < length - 1; i++) {
            for (String c : candidate) {
                String temp = string.substring(0, i) + c + string.substring(i + 2);
                if (check(temp)) {
                    return temp;
                }
            }
        }
        return null;
    }

