        Scanner scan = new Scanner(System.in);
        int i, n = scan.nextInt();
        for (i = 0; i < n; i++) {
            String string = scan.next();
            if (check(string)) {
                System.out.println(string);
            } else {
                String temp = solve1(string);
                if (temp != null) {
                    System.out.println(temp);
                } else {
                    temp = solve2(string);
                    if (temp != null) {
                        System.out.println(temp);
                    } else {
                        System.out.println("aA1" + string.substring(3));
                    }
                }
            }
        }
    }
