public class B {

    /** Try to draw a stamp whose top‑left corner is (i,j) */
    public static void start(String[] src, int n, int m, int i, int j, String[] dst) {
        // the 3×3 stamp must fit completely inside the grid
        if (j + 2 >= m || i + 2 >= n) {
            return;
        }

        // every cell of the border (except the centre) must already be '#'
        int flag = 0;
        for (int r = i; r < i + 3; r++) {
            for (int c = j; c < j + 3; c++) {
                if (r == i + 1 && c == j + 1) {
                    continue;                // centre is ignored
                }
                if (src[r].charAt(c) == '.') {
                    flag = 1;
                    return;
                }
            }
        }

        // draw the border on the destination grid (dst)
        int row = i, col = j;
        dst[row] = dst[row].substring(0, col) + "###" + dst[row].substring(col + 3, m);
        dst[row + 2] = dst[row + 2].substring(0, col) + "###" + dst[row + 2].substring(col + 3, m);
        if (dst[row + 1].charAt(col + 1) == '#') {
            // if the centre cell was already filled we keep it as '#'
            dst[row + 1] = dst[row + 1].substring(0, col) + "###" + dst[row + 1].substring(col + 3, m);
        } else {
            // otherwise we leave the centre empty -> "#.#"
            dst[row + 1] = dst[row + 1].substring(0, col) + "#.#" + dst[row + 1].substring(col + 3, m);
        }
    }

    /** Compare the constructed grid (src) with the original one (orig) */
    public static String check(String[] constructed, int n, int m, String[] original) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (constructed[i].charAt(j) != original[i].charAt(j)) {
                    return "NO";
                }
            }
        }
        return "YES";
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        String[] input = new String[n];
        String[] copy  = new String[n];
        String[] result = new String[n];

        // initialise result grid with all '.'
        for (int i = 0; i < n; i++) {
            result[i] = new String(new char[m]).replace('\0', '.');
        }

        // read the signature
        for (int i = 0; i < n; i++) {
            input[i] = br.readLine();
            copy[i] = input[i];               // keep a copy for later comparison
        }

        // try to place a stamp whenever we see a '#' in the original grid
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (input[i].charAt(j) == '#') {
                    start(input, n, m, i, j, result);
                }
            }
        }

        // check whether the constructed grid matches the original one
        System.out.println(check(result, n, m, copy));
    }
}

import java.io.*;
import java.util.*;

public class B {

    /** Try to draw a 3×3 frame (without centre) whose top‑left corner is (i,j).
     *  The frame can be drawn only if all 8 surrounding cells of the original
     *  grid are '#'.  When it can be drawn we copy the frame onto the result
     *  grid s3.
     */
    public static void start(String[] s, int n, int m, int i, int j, String[] s3) {
        // the 3×3 block must fit into the grid
        if (i + 2 >= n || j + 2 >= m) {
            return;
        }

        // verify that the whole border (except the centre) consists of '#'
        for (int r = i; r < i + 3; r++) {
            for (int c = j; c < j + 3; c++) {
                if (r == i + 1 && c == j + 1) {
                    continue;               // skip the centre
                }
                if (s[r].charAt(c) != '#') {
                    return;                 // cannot draw here
                }
            }
        }

        // draw the border onto the initially empty grid s3
        // top row  : "###"
        s3[i] = s3[i].substring(0, j) + "###" + s3[i].substring(j + 3);
        // bottom row : "###"
        s3[i + 2] = s3[i + 2].substring(0, j) + "###" + s3[i + 2].substring(j + 3);
        // middle row : only the leftmost and rightmost cells become '#'
        String mid = s3[i + 1];
        mid = mid.substring(0, j) + '#' + mid.charAt(j + 1) + '#' + mid.substring(j + 2);
        s3[i + 1] = mid;
    }

    /** Compare the grid produced by the drawing process with the original one. */
    public static String check(String[] s, int n, int m, String[] s2) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (s[i].charAt(j) != s2[i].charAt(j)) {
                    return "NO";
                }
            }
        }
        return "YES";
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        String[] original = new String[n];
        String[] empty    = new String[n];
        String[] result   = new String[n];

        for (int i = 0; i < n; i++) {
            original[i] = br.readLine();
            // initialise the result grid with only '.' characters
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < m; j++) {
                sb.append('.');
            }
            empty[i] = sb.toString();
            result[i] = sb.toString();
        }

        // try to draw a frame whenever we meet a '#' in the original picture
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (original[i].charAt(j) == '#') {
                    start(original, n, m, i, j, result);
                }
            }
        }

        System.out.println(check(result, n, m, original));
    }
}

