public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int rowCount = in.readInt();
            int columnCount = in.readInt();
            char[][] table = IOUtils.readTable(in, rowCount, columnCount);
            boolean[][] goodCell = new boolean[rowCount][columnCount];

            for (int i = 0; i < rowCount; i++) {
                for (int j = 0; j < columnCount; j++) {
                    if (table[i][j] == '#') {
                        checkCell(i, j, table, goodCell, rowCount, columnCount);
                    }
                }
            }

            for (int i = 0; i < rowCount; i++) {
                for (int j = 0; j < columnCount; j++) {
                    if (table[i][j] == '#' && goodCell[i][j] == false) {
                        out.printLine("NO");
                        return;
                    }
                }
            }

            out.printLine("YES");
        }

        private void checkCell(int x, int y, char[][] table, boolean[][] goodCell, int rowCount, int columnCount) {
            if (x + 3 > rowCount || y + 3 > columnCount) {
                return;
            }

            boolean allGood = true;
            for (int i = x; i < x + 3; i++) {
                for (int j = y; j < y + 3; j++) {
                    if (i == x + 1 && j == y + 1) {
                        continue;
                    }

                    if (table[i][j] != '#') {
                        allGood = false;
                    }
                }
            }

            if (allGood) {
                for (int i = x; i < x + 3; i++) {
                    for (int j = y; j < y + 3; j++) {
                        if (i == x + 1 && j == y + 1) {
                            continue;
                        }
                        goodCell[i][j] = true;
                    }
                }
            }
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
