	public void run() {
		FastScanner fs = new FastScanner();
		PrintWriter out = new PrintWriter(System.out);
		System.err.println("Go!");

		int n = fs.nextInt();
		int m = fs.nextInt();
		char[][] g = new char[n][m];
		for(int i = 0; i < n; i++) {
			g[i] = fs.next().toCharArray();
		}
		char[][] me = new char[n][m];
		for(int i = 0; i < n; i++) Arrays.fill(me[i], '.');
		int[] dx = {0, 1, 2, 2, 2, 1, 0, 0};
		int[] dy = {0, 0, 0, 1, 2, 2, 2, 1};
		for(int i = 0; i < n; i++) {
			for(int j = 0; j < m; j++) {
				if(g[i][j] == '.') continue;
				if(i+3 > n || j + 3 > m) continue;
				boolean nope = false;
				for(int k = 0; k < dx.length; k++) {
					int nx = i + dx[k];
					int ny = j + dy[k];
					if(g[nx][ny] == '.') nope = true;
				}
				if (!nope) {                     // <-- fixed: stamp only when all 8 border cells are '#'
					for(int k = 0; k < dx.length; k++) {
						int nx = i + dx[k];
						int ny = j + dy[k];
						me[nx][ny] = '#'; 
					}	
				}
			}
		}
		boolean yes = true;
		for(int i = 0; i < n; i++) {
