public class B {
    static boolean[][] grid, checkGrid;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt(), m = in.nextInt();
        grid = new boolean[n][m];
        checkGrid = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            char[] chars = in.next().toCharArray();
            for (int j = 0; j < m; j++) {
                grid[i][j] = (chars[j] == '#');
            }
        }

        // try every possible centre of a 3×3 stamp
        for (int y = 1; y < n - 1; y++) {
            for (int x = 1; x < m - 1; x++) {
                paint(y, x);
            }
        }

        // verify that every '#' in the original grid was covered
        boolean ok = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != checkGrid[i][j]) {
                    ok = false;
                    break;
                }
            }
            if (!ok) break;
        }

        System.out.println(ok ? "YES" : "NO");
    }

    // stamp with centre at (y,x) if all 8 neighbours are '#'
    static void paint(int y, int x) {
        // verify that the whole 3×3 border consists of '#'
        for (int dy = -1; dy <= 1; dy++) {
            for (int dx = -1; dx <= 1; dx++) {
                if (dx == 0 && dy == 0) continue;            // skip the centre cell
                if (!grid[y + dy][x + dx]) {
                    return;                                   // cannot place stamp here
                }
            }
        }

        // actually place the stamp – mark the 8 cells as covered
        for (int dy = -1; dy <= 1; dy++) {
            for (int dx = -1; dx <= 1; dx++) {
                if (dx == 0 && dy == 0) continue;
                checkGrid[y + dy][x + dx] = true;
            }
        }
    }
}

