public class Rextester{
    public static boolean check(char[][] array,int x,int y){
        try{
            if((array[x-1][y-1]=='#'||array[x-1][y-1]=='-')&&(array[x-1][y]=='#'||array[x-1][y]=='-')&&(array[x-1][y+1]=='-'||array[x-1][y+1]=='#')&&
               (array[x][y-1]=='-'||array[x][y-1]=='#')&&(array[x][y+1]=='#'||array[x][y+1]=='-')&&(array[x+1][y-1]=='-'||array[x+1][y-1]=='#')&&
               (array[x+1][y]=='#'||array[x+1][y]=='-')&&(array[x+1][y+1]=='-'||array[x+1][y+1]=='#')){
                return true;
            }
            else{
                return false;
            }
        }catch(Exception e){
            return false;
        }
    }
    public static void set(char[][] array,int x,int y){
        array[x-1][y-1]='-';
        array[x-1][y]='-';
        array[x-1][y+1]='-';
        array[x][y-1]='-';
        array[x][y+1]='-';          // fixed: set the missing cell (x, y+1)
        array[x+1][y-1]='-';
        array[x+1][y]='-';
        array[x+1][y+1]='-';
    }
    public static void main(String[] args)throws IOException{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int r = new Integer(st.nextToken());
        int c = new Integer(st.nextToken());
        char[][] array = new char[r][c];
        for(int i=0;i<r;i++){
            array[i]=br.readLine().toCharArray();
        }
        br.close();
        for(int i=0;i<r;i++){
            for(int j=0;j<c;j++){
                if(array[i][j]=='#'){
                    if(check(array,i+1,j+1)){
                        set(array,i+1,j+1);
                    }
                    else if(check(array,i+1,j)){
                        set(array,i+1,j);
                    }
                    else if(check(array,i+1,j-1)){
                        set(array,i+1,j-1);
                    }
                    else if(check(array,i,j+1)){
                        set(array,i,j+1);
                    }
                    else if(check(array,i,j-1)){
                        set(array,i,j-1);
                    }
                    else if(check(array,i-1,j+1)){
                        set(array,i-1,j+1);
                    }
                    else if(check(array,i-1,j)){
                        set(array,i-1,j);
                    }
                    else if(check(array,i-1,j-1)){
                        set(array,i-1,j-1);
                    }
                }
            }
        }
        for(int i=0;i<r;i++){
            for(int j=0;j<c;j++){
                if(array[i][j]=='#'){
                    System.out.println("NO");
                    return;
                }
            }
        }
        System.out.println("YES");
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class CF1059B {
    public static void main(String[] args) throws IOException {
        FastReader fr = new FastReader();
        int n = fr.nextInt();
        int m = fr.nextInt();
        char[][] arr = new char[n][m];
        char[][] newArr = new char[n][m];
        for (int i = 0; i < n; i++) {
            arr[i] = fr.nextLine().toCharArray();
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (checkIfCenter(arr, i, j, n, m))
                    newArr[i][j] = 'C';
            }
        }

        boolean ans = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (arr[i][j] == '#') {
                    if (atleastOneCenter(newArr, i, j, n, m))
                        continue;
                    else {
                        ans = false;
                        break;
                    }
                }
            }
        }
        if (ans)
            System.out.println("YES");
        else
            System.out.println("NO");
    }

    static void print(char[][] arr, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                System.out.print(arr[i][j] + " ");
            }
            System.out.println();
        }
    }

    static boolean atleastOneCenter(char[][] arr, int i, int j, int n, int m) {
        boolean canBeFormed = false;
        if (isCenter(arr, i - 1, j - 1, n, m)) canBeFormed = true;
        if (isCenter(arr, i - 1, j, n, m)) canBeFormed = true;
        if (isCenter(arr, i, j - 1, n, m)) canBeFormed = true;
        if (isCenter(arr, i, j + 1, n, m)) canBeFormed = true;
        if (isCenter(arr, i + 1, j - 1, n, m)) canBeFormed = true;
        if (isCenter(arr, i + 1, j, n, m)) canBeFormed = true;
        if (isCenter(arr, i + 1, j + 1, n, m)) canBeFormed = true;
        return canBeFormed;
    }

    static boolean checkIfCenter(char[][] arr, int i, int j, int n, int m) {
        if (i == 0 || i == n - 1 || j == 0 || j == m - 1)
            return false;
        boolean isCenter = true;
        if (!isHash(arr, i - 1, j - 1)) isCenter = false;
        if (!isHash(arr, i - 1, j)) isCenter = false;
        if (!isHash(arr, i - 1, j + 1)) isCenter = false;
        if (!isHash(arr, i, j - 1)) isCenter = false;
        if (!isHash(arr, i, j + 1)) isCenter = false;
        if (!isHash(arr, i + 1, j - 1)) isCenter = false;
        if (!isHash(arr, i + 1, j)) isCenter = false;
        if (!isHash(arr, i + 1, j + 1)) isCenter = false;
        return isCenter;
    }

    static boolean isHash(char[][] arr, int i, int j) {
        if (arr[i][j] == '#') return true;
        return false;
    }

    static boolean isCenter(char[][] arr, int i, int j, int n, int m) {
        if (i <= 0 || i >= n - 1 || j <= 0 || j >= m - 1) return false;
        if (arr[i][j] == 'C') return true;
        return false;
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public Double nextDouble() {
            return Double.parseDouble(next());
        }

        public Float nextFloat() {
            return Float.parseFloat(next());
        }

        String nextLine() {
            String str = "";
            try {
