public class CF1059B {
    public static void main(String[] args) throws IOException {
        FastReader fr = new FastReader();
        int n = fr.nextInt();
        int m = fr.nextInt();
        char[][] arr = new char[n][m];
        char[][] newArr = new char[n][m];
        for (int i = 0; i < n; i++) {
            arr[i] = fr.nextLine().toCharArray();
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (checkIfCenter(arr, i, j, n, m))
                    newArr[i][j] = 'C';
            }
        }

        boolean ans = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (arr[i][j] == '#') {
                    if (atleastOneCenter(newArr, i, j, n, m))
                        continue;
                    else {
                        ans = false;
                        break;
                    }
                }
            }
        }
        if (ans)
            System.out.println("YES");
        else
            System.out.println("NO");
    }

    static void print(char[][] arr, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                System.out.print(arr[i][j] + " ");
            }
            System.out.println();
        }
    }

    static boolean atleastOneCenter(char[][] arr, int i, int j, int n, int m) {
        boolean canBeFormed = false;
        if (isCenter(arr, i - 1, j - 1, n, m)) canBeFormed = true;
        if (isCenter(arr, i - 1, j, n, m)) canBeFormed = true;
        if (isCenter(arr, i - 1, j + 1, n, m)) canBeFormed = true;
        if (isCenter(arr, i, j - 1, n, m)) canBeFormed = true;
        if (isCenter(arr, i, j + 1, n, m)) canBeFormed = true;
        if (isCenter(arr, i + 1, j - 1, n, m)) canBeFormed = true;
        if (isCenter(arr, i + 1, j, n, m)) canBeFormed = true;
        if (isCenter(arr, i + 1, j + 1, n, m)) canBeFormed = true;
        return canBeFormed;
    }



    static boolean checkIfCenter(char[][] arr, int i, int j, int n, int m) {
        if (i == 0 || i == n - 1 || j == 0 || j == m - 1)
            return false;
        boolean isCenter = true;
        if (!isHash(arr, i - 1, j - 1)) isCenter = false;
        if (!isHash(arr, i - 1, j)) isCenter = false;
        if (!isHash(arr, i - 1, j + 1)) isCenter = false;
        if (!isHash(arr, i, j - 1)) isCenter = false;
        if (!isHash(arr, i, j + 1)) isCenter = false;
        if (!isHash(arr, i + 1, j - 1)) isCenter = false;
        if (!isHash(arr, i + 1, j)) isCenter = false;
        if (!isHash(arr, i + 1, j + 1)) isCenter = false;
        return isCenter;
    }

    static boolean isHash(char[][] arr, int i, int j) {
        if (arr[i][j] == '#') return true;
        return false;
    }

    static boolean isCenter(char[][] arr, int i, int j, int n, int m) {
        if (i <= 0 || i >= n - 1 || j <= 0 || j >= m - 1) return false;
        if (arr[i][j] == 'C') return true;
        return false;
    }

