        if (arr[i][j - 1] != '#') return false;
        if (arr[i][j + 1] != '#') return false;
        if (arr[i + 1][j - 1] != '#') return false;
        if (arr[i + 1][j] != '#') return false;
        if (arr[i + 1][j + 1] != '#') return false;
        return true;
    }

