    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            boolean[][] used = new boolean[n][m];
            String[] field = new String[n];
            String[] pat = {"###", "#.#", "###"};
