	private static PrintWriter out;

	public static void main(String[] args) throws FileNotFoundException{







		MyScanner sc = new MyScanner();


		out = new PrintWriter(new BufferedOutputStream(System.out)); 


		int n = sc.ni(), m = sc.ni();
		char[][] sign = new char[n][m];
		for(int i = 0; i < n; i++) sign[i] = sc.nn().toCharArray();

		out.println(getAns(n, m, sign));

		out.close();
	}

	private static String getAns(int n, int m, char[][] sign){
		boolean[][] visited = new boolean[n][m];

		for(int i = 0; i < n; i++){
			for(int j = 0; j < m; j++){
				if(sign[i][j] == '.' || visited[i][j]) continue;
				if(one(sign, i, j, n, m) || two(sign, i, j, n, m) || three(sign, i, j, n, m) || four(sign, i, j, n, m) || five(sign, i, j, n, m) || six(sign, i, j, n, m) || seven(sign, i, j, n, m) || eight(sign, i, j, n, m)) continue;
				return "NO";
			}
		}
		return "YES";
	}

	private static boolean one(char[][] sign, int i, int j, int n, int m){
		if(i + 2 >= n || j + 2 >= m) return false;
		return sign[i][j] == '#' && sign[i+1][j] == '#' && sign[i+2][j] == '#' && sign[i][j+1] == '#' && sign[i][j+2] == '#' && sign[i+1][j+2] == '#' && sign[i+2][j+1] == '#' && sign[i+2][j+2] == '#';
	}

	private static boolean two(char[][] sign, int i, int j, int n, int m){
		if(i + 2 >= n || j + 1 >= m || j - 1 < 0) return false;
		return sign[i][j] == '#' && sign[i][j-1] == '#' && sign[i+2][j] == '#' && sign[i+1][j-1] == '#' && sign[i+2][j-1] == '#' && sign[i][j+1] == '#' && sign[i+1][j+1] == '#' && sign[i+2][j+1] == '#';
	}

	private static boolean three(char[][] sign, int i, int j, int n, int m){
		if(i + 2 >= n || j - 2 < 0) return false;
		return sign[i][j] == '#' && sign[i][j-1] == '#' && sign[i][j-2] == '#' && sign[i+1][j] == '#' && sign[i+1][j-2] == '#' && sign[i+2][j] == '#' && sign[i+2][j-1] == '#' && sign[i+2][j-2] == '#';
	}

	private static boolean four(char[][] sign, int i, int j, int n, int m){
		if(i + 1 >= n || i - 1 < 0 || j + 2 >= m) return false;
		return sign[i][j] == '#' && sign[i-1][j] == '#' && sign[i-1][j+1] == '#' && sign[i-1][j+2] == '#' && sign[i][j+2] == '#' && sign[i+1][j] == '#' && sign[i+1][j+1] == '#' && sign[i+1][j+2] == '#';
	}

	private static boolean five(char[][] sign, int i, int j, int n, int m){
		if(i + 1 >= n || i - 1 < 0 || j - 2 < 0) return false;
		return sign[i][j] == '#' && sign[i-1][j] == '#' && sign[i-1][j-1] == '#' && sign[i-1][j-2] == '#' && sign[i][j-2] == '#' && sign[i+1][j] == '#' && sign[i+1][j-1] == '#' && sign[i+1][j-2] == '#';
	}

	private static boolean six(char[][] sign, int i, int j, int n, int m){
		if(i - 2 < 0 || j + 2 >= m) return false;
		return sign[i][j] == '#' && sign[i-1][j] == '#' && sign[i-2][j] == '#' && sign[i-2][j+1] == '#' && sign[i][j+1] == '#' && sign[i-2][j+2] == '#' && sign[i-1][j+2] == '#' && sign[i][j+2] == '#';
	}

	private static boolean seven(char[][] sign, int i, int j, int n, int m){
		if(i - 2 < 0 || j + 1 >= m || j - 1 < 0) return false;
		return sign[i][j] == '#' && sign[i][j-1] == '#' && sign[i-1][j-1] == '#' && sign[i-2][j-1] == '#' && sign[i-2][j] == '#' && sign[i-2][j+1] == '#' && sign[i-1][j+1] == '#' && sign[i][j+1] == '#';
	}

	private static boolean eight(char[][] sign, int i, int j, int n, int m){
		if(i - 2 < 0 || j - 2 < 0) return false;
		return sign[i][j] == '#' && sign[i-1][j] == '#' && sign[i-2][j] == '#' && sign[i-2][j-1] == '#' && sign[i][j-1] == '#' && sign[i][j-2] == '#' && sign[i-1][j-2] == '#' && sign[i-2][j-2] == '#';
	}
