public class Solution {

    private static final Scanner scanner = new Scanner(System.in);

    private static void correct(int[][] a, int i1, int j1, int[][] visited){
        for(int j = j1; j <= j1 + 2; j++){
            if(a[i1][j] == 0)return;
        }
        for(int j = j1; j <= j1 + 2; j++){
            if(a[i1 + 2][j] == 0)return;
        }
        if(a[i1 + 1][j1] == 0 || a[i1 + 1][j1 + 2] == 0)return;

        for(int j = j1; j <= j1 + 2; j++){
            visited[i1][j] = 1;
        }
        for(int j = j1; j <= j1 + 2; j++){
            visited[i1 + 2][j] = 1;
        }
        visited[i1 + 1][j1] = 1;
        visited[i1 + 1][j1 + 2] = 1;
    }

    private static boolean legal(int[][] a, int i, int j){
        int n = a.length;
        int m = a[0].length;
        return i < n - 2 && j < m - 2;
    }

    public static void main(String[] args) throws IOException {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int[][] a = new int[n][m];
        int[][] check = new int[n][m];
        for(int i = 0; i < n; i++){
            String s = scanner.next();
            for(int j = 0; j < s.length(); j++){
                if(s.charAt(j) == '.')a[i][j] = 0;
                else a[i][j] = 1;
            }
        }

        for(int i = 0; i < n; i++){
            for(int j = 0; j < m; j++){
                if(legal(a, i, j)){
                    correct(a, i, j, check);
                }
            }
        }
        for(int i = 0; i < n; i++){
            for(int j = 0; j < m; j++){
                if(a[i][j] == 1 && check[i][j] == 0){
                    System.out.println("NO");
                    return;
                }
            }
        }
        System.out.println("YES");
    }
}

