import java.io.*;
import java.util.*;

public class c {
    public static PrintWriter out;
    public static FS sc;
    public static void main(String[] Args) throws Exception {
        out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        sc = new FS(System.in);

        int n = sc.nextInt();

        int MAX = 1001;
        int[] freq = new int[MAX];
        for (int i = 0; i < n * n; i++)
            freq[sc.nextInt()]++;

        int[][] ans = new int[n][n];
        for (int[] x : ans)
            Arrays.fill(x, -1);

        /* ---- fill the 4‑element orbits (corners) ---- */
        for (int i = 0; i < n / 2; i++)
            for (int j = 0; j < n / 2; j++) {
                boolean found = false;
                for (int k = 1; k < MAX; k++) {
                    if (freq[k] >= 4) {
                        ans[i][j] = k;
                        ans[n - i - 1][j] = k;
                        ans[i][n - j - 1] = k;
                        ans[n - i - 1][n - j - 1] = k;
                        freq[k] -= 4;
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    out.println("NO");
                    out.close();
                    return;
                }
            }

        /* ---- if n is odd, fill the remaining orbits ---- */
        if (n % 2 == 1) {
            int mid = n / 2;

            /* central row pairs */
            for (int j = 0; j < mid; j++) {
                boolean found = false;
                for (int k = 1; k < MAX; k++) {
                    if (freq[k] >= 2) {
                        ans[mid][j] = k;
                        ans[mid][n - j - 1] = k;
                        freq[k] -= 2;
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    out.println("NO");
                    out.close();
                    return;
                }
            }

            /* central column pairs */
            for (int i = 0; i < mid; i++) {
                boolean found = false;
                for (int k = 1; k < MAX; k++) {
                    if (freq[k] >= 2) {
                        ans[i][mid] = k;
                        ans[n - i - 1][mid] = k;
                        freq[k] -= 2;
                        found = true;
                        break;
                    }
                }
                if (!found) {
                    out.println("NO");
                    out.close();
                    return;
                }
            }

            /* centre cell */
            boolean found = false;
            for (int k = 1; k < MAX; k++) {
                if (freq[k] >= 1) {
                    ans[mid][mid] = k;
                    freq[k] -= 1;
                    found = true;
                    break;
                }
            }
            if (!found) {
                out.println("NO");
                out.close();
                return;
            }
        }

        out.println("YES");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                out.print(ans[i][j]);
                if (j + 1 < n) out.print(' ');
            }
            out.println();
        }
        out.close();
    }

    public static class FS {
        BufferedReader br;
        StringTokenizer st;

        FS(InputStream in) throws Exception {
            br = new BufferedReader(new InputStreamReader(in));
            st = new StringTokenizer("");
        }

        String next() throws Exception {
            if (st.hasMoreTokens()) return st.nextToken();
            st = new StringTokenizer(br.readLine());
            return next();
        }

        int nextInt() throws Exception {
            return Integer.parseInt(next());
        }
    }
}

