    public static void main(String[] Args) throws Exception {
        out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        sc = new FS(System.in);

        int n = sc.nextInt();
        int MAX = 1001;
        int[] freq = new int[MAX];
        for (int i = 0; i < n * n; i++) {
            int v = sc.nextInt();
            if (v < MAX) freq[v]++;
        }
        int[][] ans = new int[n][n];
        for (int[] x : ans) Arrays.fill(x, -1);

        int mid = n / 2;               // floor(n/2)

        // ---- groups of 4 (top‑left quadrant) ----
        for (int i = 0; i < mid; i++) {
            for (int j = 0; j < mid; j++) {
                int need = 4;
                int val = -1;
                for (int k = 1; k < MAX; k++) {
                    if (freq[k] >= need) {
                        val = k;
                        break;
                    }
                }
                if (val == -1) {
                    out.println("NO");
                    out.close();
                    return;
                }
                ans[i][j] = val;
                ans[n - i - 1][j] = val;
                ans[i][n - j - 1] = val;
                ans[n - i - 1][n - j - 1] = val;
                freq[val] -= need;
            }
        }

        // ---- odd n: groups of 2 on the middle row and column ----
        if ((n & 1) == 1) {
            // middle row (except centre)
            for (int j = 0; j < mid; j++) {
                int need = 2;
                int val = -1;
                for (int k = 1; k < MAX; k++) {
                    if (freq[k] >= need) {
                        val = k;
                        break;
