                if (val != -1) {
                    ans[n / 2][n / 2] = val;
                    h[val]--;
                } else {
                    out.println("NO");
                    return;
                }


                for (int i = 0; i < n / 2; i++) {
                    val = -1;
                    for (int j = 1; j <= 1000; j++) {
                        if (h[j] % 4 == 2) {
                            val = j;
                            break;
                        } else if (h[j] % 4 == 0 && h[j] >= 2) {
                            if (val == -1) {
                                val = j;

                            }
                        }
                    }

                    if (val != -1) {
                        ans[n / 2][i] = val;
                        int d = n / 2 - i;
                        ans[n / 2][n / 2 + d] = val;
                        h[val] -= 2;
                    } else {
                        out.println("NO");
                        return;
                    }
                }



                for (int i = 0; i < n / 2; i++) {
                    val = -1;
