                            }
                        }
                    }

                    if (val != -1) {
                        ans[i][n / 2] = val;
                        int d = n / 2 - i;
                        ans[n / 2 + d][n / 2] = val;
                        h[val] -= 2;
                    } else {
                        out.println("NO");
                        return;
                    }
                }

                for (int i = 0; i < n / 2; i++) {
                    for (int j = 0; j < n / 2; j++) {
                        boolean f = false;
                        for (int k = 1; k <= 1000; k++) {
                            if (h[k] >= 4) {
                                f = true;
                                ans[i][j] = k;
                                int dx = n / 2 - i;
                                int dy = n / 2 - j;

