			for (int i = 0; i < L - 1; i++) { 
				list2.add(new Pair(i, L - 1));
			}
			for (int i = 0; i < L - 1; i++) {
				for (int j = 0; j < L - 1; j++) {
					list4.add(new Pair(i, j));
				}
			}
