    int next(int t) {
        P cur = a.get(c);
        if (cur.n == 0) {
            c++;
            return next(t);
        } else {
            cur.n -= t;
            return cur.x;
        }
    }

    class P implements Comparable<P> {
        public int x;
        public int n;
        public int p;
        public P(int x, int n) {
            this.x = x;
            this.n = n;
            p = n % 4 == 0 ? 2 : (n % 2 == 0 ? 1 : 0);
        }

        @Override
        public int compareTo(P p) {
            return Integer.compare(p.p, this.p);
        }
    }



