	public static int[][] makeMatrixEven(int[][] a, int size) {
		int[][] arr = new int[size * 2][size * 2];
		int newSize = size * 2;
		for (int i = 0; i <= size - 1; i++) {
			for (int j = 0; j <= size - 1; j++) {
				arr[i][j] = a[i][j];
				arr[newSize - i - 1][j] = a[i][j];
				arr[i][newSize - j - 1] = a[i][j];
				arr[newSize - i - 1][newSize - j - 1] = a[i][j];
			}
		}
		return arr;
	}

	public static int[][] makeMatrixOdd(int[][] a, int size) {
		int[][] arr = new int[size * 2 - 1][size * 2 - 1];
		int newSize = size * 2 - 1;
		for (int i = 0; i <= size - 2; i++) {
			for (int j = 0; j <= size - 2; j++) {
				arr[i][j] = a[i][j];
				arr[newSize - i - 1][j] = a[i][j];
				arr[i][newSize - j - 1] = a[i][j];
				arr[newSize - i - 1][newSize - j - 1] = a[i][j];
			}
		}

		for (int i = 0; i <= size - 1; i++) {
			arr[i][size - 1] = a[i][size - 1];
			arr[newSize - i - 1][size - 1] = a[i][size - 1];
			arr[size - 1][i] = a[size - 1][i];
			arr[size - 1][newSize - i - 1] = a[size - 1][i];
		}

		return arr;
	}

	public static void printMatrix(int[][] a, PrintWriter p, int n) {
		for (int i = 0; i <= n - 1; i++) {
			for (int j = 0; j <= n - 1; j++) {
				p.print(a[i][j] + " ");
			}
			p.println();
		}
	}

	public static void main(String[] args) {
		MyScanner myScanner = new MyScanner();
		PrintWriter printer = new PrintWriter(System.out, true);
		int n = myScanner.nextInt();
		int[] arr = new int[n * n];
		for (int i = 0; i <= n * n - 1; i++) {
			arr[i] = myScanner.nextInt();
		}
		Arrays.sort(arr);

		Stack<Integer> stack4 = new Stack<>();
		Stack<Integer> stack2 = new Stack<>();
		Stack<Integer> stack1 = new Stack<>();

		int curSpree = 1;
		int cur = arr[0];
		for (int i = 1; i <= n * n - 1; i++) {
			if (arr[i] == cur) {
				curSpree++;
			}

			else {

				for (int j = 0; j <= curSpree / 4 - 1; j++) {
					stack4.push(cur);

				}
				curSpree = curSpree % 4;

				for (int j = 0; j <= curSpree / 2 - 1; j++) {
					stack2.push(cur);
				}

				curSpree = curSpree % 2;

				if (curSpree > 0) {
					stack1.push(cur);
				}
				curSpree = 1;
			}
			cur = arr[i];
		}


		if (curSpree > 0) {
			for (int j = 0; j <= curSpree / 4 - 1; j++) {
				stack4.push(cur);

			}
			curSpree = curSpree % 4;

			for (int j = 0; j <= curSpree / 2 - 1; j++) {
				stack2.push(cur);
			}

			curSpree = curSpree % 2;

			if (curSpree > 0) {
				stack1.push(cur);
			}
		}

		int[][] newA = null;

		if (n % 2 == 0) {
			if (stack2.size() > 0 || stack1.size() > 0) {
				printer.print("NO");
			} else {
				int[][] arr1 = new int[n / 2][n / 2];
				for (int i = 0; i <= n / 2 - 1; i++) {
					for (int j = 0; j <= n / 2 - 1; j++) {
						arr1[i][j] = stack4.pop();
					}
				}
				newA = makeMatrixEven(arr1, n / 2);
				printer.println("YES");
				printMatrix(newA, printer, n);
			}
		} else {
			if (stack1.size() != 1) {
				printer.println("NO");
			} else {
				while (stack2.size() < (n / 2) * 2) {
					int q = stack4.pop();
					stack2.push(q);
					stack2.push(q);
				}


				if (stack2.size() != n - 2 * 2 && stack4.size() != n * 2 - (n / 2 * 2) - 1) {
					printer.println("NO");
				} else {
					int[][] arr1 = new int[n / 2 + 1][n / 2 + 1];
					for (int i = 0; i <= n / 2 - 1; i++) {
						for (int j = 0; j <= n / 2 - 1; j++) {
							arr1[i][j] = stack4.pop();
						}
					}
					arr1[n / 2][n / 2] = stack1.pop();

					for (int i = 0; i <= n / 2 - 1; i++) {
						arr1[n / 2][i] = stack2.pop();
						arr1[i][n / 2] = stack2.pop();
					}
					newA = makeMatrixOdd(arr1, n / 2 + 1);
					printer.println("YES");
					printMatrix(newA, printer, n);
				}
