import java.util.ArrayList;
import java.util.HashMap;
import java.util.Scanner;
import java.util.Set;

public class PalindromicMatrix_Improved_Implementation {
	static int n = 0;

	public static void main(String[] args) {
		Scanner scn = new Scanner(System.in);
		n = scn.nextInt();
		int[] arr = new int[n * n];
		HashMap<Integer, Integer> hmap = new HashMap<>();
		HashMap<Integer, ArrayList<Integer>> freq = new HashMap<>();
		for (int i = 0; i < n * n; i++) {
			arr[i] = scn.nextInt();
			if (hmap.containsKey(arr[i])) {
				hmap.put(arr[i], hmap.get(arr[i]) + 1);
			} else {
				hmap.put(arr[i], 1);
			}
		}
		Set<Integer> set = hmap.keySet();
		for (int i : set) {
			int count = hmap.get(i);
			if (count >= 4) {
				addEle(freq, 4, i);
			} else if (count >= 2) {
				addEle(freq, 2, i);
			} else if (count == 1) {
				addEle(freq, 1, i);
			}
		}

		int[][] ans = new int[n][n];
		int flag = 0;
		for (int i = 0; i < n / 2; i++) {
			for (int j = 0; j < n / 2; j++) {
				if (freq.containsKey(4)) {
					ArrayList<Integer> al = freq.get(4);
					solve(ans, i, j, al.get(al.size() - 1));
					updateFreq(freq, hmap, al,4,4);
				} else {
					flag = 1;
					break;
				}
			}
		}

		if (flag == 1) {
			System.out.println("NO");

		} else {


			if (n % 2 != 0) {
				for(int i=n/2,j=0;j<=n/2;j++) {

					if(j==n/2&&freq.containsKey(1)) {
						ArrayList<Integer> al = freq.get(1);
						ans[i][j]=al.get(al.size()-1);
						updateFreq(freq, hmap, al,1,1);

					}
					else if(freq.containsKey(2)) {
						ArrayList<Integer> al = freq.get(2);
						ans[i][j]=ans[i][n-1-j]=al.get(al.size()-1);
						if(j==n/2)
							updateFreq(freq, hmap, al,2,1);
						else{
							updateFreq(freq, hmap, al,2,2);

						};
					}
					else if(freq.containsKey(4)) {
						ArrayList<Integer> al = freq.get(4);
						ans[i][j]=ans[i][n-1-j]=al.get(al.size()-1);
						if(j==n/2)
							updateFreq(freq, hmap, al,4,1);
						else{
							updateFreq(freq, hmap, al,4,2);

						};

					}
					else {
						flag=1;
						break;
					}

				}
				for(int i=0,j=n/2;i<n/2;i++) {

					if(freq.containsKey(4)) {

						ArrayList<Integer> al = freq.get(4);
						ans[i][j]=ans[n-1-i][j]=al.get(al.size()-1);
						updateFreq(freq, hmap, al,4,2);
					}
					else if(freq.containsKey(2)) {

						ArrayList<Integer> al = freq.get(2);
						ans[i][j]=ans[n-1-i][j]=al.get(al.size()-1);
						updateFreq(freq, hmap, al,2,2);
					}
					else {
						flag=1;
						break;
					}
				}

			}
			if(flag==1) {
				System.out.println("NO");

			}else {
				System.out.println("YES");
				for(int i=0;i<n;i++) {
					for(int j=0;j<n;j++) {
						System.out.print(ans[i][j]+" ");
					}
					System.out.println();
				}
			}
		}
	}
	public static void updateFreq(HashMap<Integer, ArrayList<Integer>> freq, HashMap<Integer, Integer> hmap,
			ArrayList<Integer> al,int x,int sub) {

		int rem_freq = hmap.get(al.get(al.size() - 1)) - sub;
		hmap.put(al.get(al.size() - 1), rem_freq);
		if (rem_freq == 1) {
			if (freq.containsKey(1)) {
				freq.get(1).add(al.get(al.size() - 1));
			} else {
				ArrayList<Integer> a = new ArrayList<Integer>();
				a.add(al.get(al.size() - 1));
				freq.put(1, a);
			}
		} else if (rem_freq > 1) {
			if (freq.containsKey(2)) {
				freq.get(2).add(al.get(al.size() - 1));
			} else {
				ArrayList<Integer> a = new ArrayList<Integer>();
				a.add(al.get(al.size() - 1));
				freq.put(2, a);
			}
		}
		if (rem_freq < x) {
			freq.get(x).remove(al.size() - 1);
			if (freq.get(x).size() == (0-1)) {
				freq.remove(x);
			}
		}
	}

	public static void solve(int[][] ans, int start, int end, int val) {
		ans[start][end] = ans[start][n - 1 - end] = ans[n - 1 - start][end] = ans[n - 1 - start][n - 1 - end] = val;
	}

	public static void addEle(HashMap<Integer, ArrayList<Integer>> freq, int x, int s) {
		if (freq.containsKey(x)) {
			ArrayList<Integer> al = freq.get(x);
			al.add(s);
			freq.put(x, al);
		} else {
			ArrayList<Integer> al = new ArrayList<Integer>();
			al.add(s);
			freq.put(x, al);
		}
	}
}

