            for (int i = 0; i < a.length; ) {
                int j = i;
                while (j < a.length && a[j] == a[i]) ++j;
                int size = (j - i) / 4;
                for (int p = 0; p < size; ++p) nums.add(a[i]);
                for (int p = i; p < i + (size * 4); ++p) a[p] = -1;
                i = j;
            }

            int ptr = 0;
            try {
                for (int i = 0; i < n / 2; ++i) {
                    for (int j = 0; j < n / 2; ++j) {
                        map[i][j] = map[n - 1 - i][j] = map[i][n - 1 - j] = map[n - 1 - i][n - 1 - j] = nums.get(ptr);
                        ++ptr;
                    }
                }
            } catch (Exception e) {
                out.println("NO");
                return;
            }

            a = ArrayUtils.sort(a);
            ArrayList<Integer> rem = new ArrayList<>();
            for (int i = ptr; i < nums.size(); ++i) {
                rem.add(nums.get(i));
            }
            nums = rem;
            try {
                if (n % 2 == 1) {
                    int i = 0;
                    while (i < a.length && a[i] == -1) ++i;
                    for (; i < a.length; ) {
                        int j = i;
                        while (j < a.length && a[j] == a[i]) ++j;
