                        for (int p = 0; p < size; ++p) nums.add(a[i]);
                        for (int p = i; p < i + (size * 2); ++p) a[p] = -1;
                        i = j;
                    }

                    ptr = 0;
                    for (int j = 0; j < n / 2; ++j) {
                        map[n / 2][j] = map[n / 2][n - 1 - j] = nums.get(ptr);
                        ++ptr;
                    }

                    for (int j = 0; j < n / 2; ++j) {
                        map[j][n / 2] = map[n - 1 - j][n / 2] = nums.get(ptr);
                        ++ptr;
                    }

                    a = ArrayUtils.sort(a);
                    rem = new ArrayList<>();
                    for (i = ptr; i < nums.size(); ++i) {
                        rem.add(nums.get(i));
                    }
                    nums = rem;
                    i = 0;
                    while (i < a.length && a[i] == -1) ++i;
                    if (i < a.length) nums.add(a[a.length - 1]);

                    if (nums.size() > 1) {
