			for (int j = 0; j < n; j++)
				m[i][j] = -1;
		for (int i = 0; i < n / 2; i++) {
			for (int j = 0; j < n / 2; j++) {
				pair p = pq.poll();
				if (m[i][n - 1 - j] == -1) {
					if (p.f <= 0) {
						System.out.println("NO");
						return;
					}
					m[i][n - 1 - j] = p.e;
					p.f = p.f - 1;
				}
				if (m[i][j] == -1) {
					if (p.f <= 0) {
						System.out.println("NO");
						return;
					}
					m[i][j] = p.e;
					p.f = p.f - 1;
				}
				if (m[n - 1 - i][j] == -1) {
					if (p.f <= 0) {
						System.out.println("NO");
						return;
					}
					m[n - 1 - i][j] = p.e;
					p.f = p.f - 1;
				}
