						System.out.println("NO");
						return;
					}
					m[n - 1 - i][n - 1 - j] = p.e;
					p.f = p.f - 1;
				}
				if (p.f > 0)
					pq.add(p);
			}
		}
		if (n % 2 == 1) {
			// handle the middle row (row index = n/2)
			for (int i = 0; i < n / 2; i++) {
				pair p = pq.poll();
				if (m[i][n / 2] == -1) {
					if (p.f <= 0) {
						System.out.println("NO");
						return;
					}
					m[i][n / 2] = p.e;
					p.f = p.f - 1;
