					if (p.f <= 0) {
						System.out.println("NO");
						return;
					}
					m[n - 1 - i][n / 2] = p.e;
					p.f = p.f - 1;
				}
				if (p.f > 0)
					pq.add(p);
			}
			// middle cell itself
			if (n % 2 == 1) {
				pair p = pq.poll();
				if (m[n / 2][n / 2] == -1) {
					if (p.f <= 0) {
						System.out.println("NO");
						return;
					}
					m[n / 2][n / 2] = p.e;
					p.f = p.f - 1;
				}
				if (p.f > 0)
					pq.add(p);
			}
			// handle the middle column (except the centre already processed)
			for (int i = 0; i < n / 2; i++) {
				pair p = pq.poll();
				if (m[n / 2][i] == -1) {
					if (p.f <= 0) {
						System.out.println("NO");
						return;
					}
					m[n / 2][i] = p.e;
					p.f = p.f - 1;
				}
				if (m[n / 2][n - 1 - i] == -1) {
					if (p.f <= 0) {
						System.out.println("NO");
						return;
					}
					m[n / 2][n - 1 - i] = p.e;
					p.f = p.f - 1;
				}
				if (p.f > 0)
					pq.add(p);
			}
		}
		System.out.println("YES");
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++)
				System.out.print(m[i][j] + " ");
			System.out.println();
		}
	}

	static class pair {
		int e, f;

		pair(int e, int f) {
			this.e = e;
			this.f = f;
		}
	}

