public class PalindromicMatrix {

	public static void main(String[] args) {

		Scanner in = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);

		int n = in.nextInt();
		int n2 = n*n;
		int [] arr = new int [n2];
		boolean works = true;

		for (int i = 0; i < n2; i++) {
			arr[i] = in.nextInt();
		}
		Arrays.sort(arr);
		int[][] outMat = new int[(n+1)/2][(n+1)/2];

		if (n % 2 == 0) {

			int j = 0;
			while (works && j < n2) {
				int current = arr[j];
				if (current != arr[j + 1] || current != arr[j+2] || current != arr[j+3]) {
					works = false;
				}
				j += 4;
			}
			for(int i = 0; i<n/2; i++) {
				for(int k = 0; k<n/2; k++) {
					outMat[i][k] = arr[(i*(n/2)+k)*4];
				}
			}
		}else {
			int ind4 = 0;
			int ind2 = 0;
			int[] part4 = new int[(n/2)*(n/2)];
			int[] part2 = new int[2*(n/2)];
			int oddV = -1;
			for(int i =0; i< n*n;) {
				int st = i;
				i++;
				while(i<n*n && arr[i] == arr[st]) {
					i++;
