    static public void solveOdd(int n, int[] a){
        int[][] ans = new int[n][n];
        int[] rec = new int[1001];
        for(int w:a) rec[w]++;
        int numOne = 0;
        for(int i=1;i<=1000;i++){
            if(rec[i]%2==1){
                ans[n/2][n/2] = i;
                numOne++;
                rec[i]--;
            }
        }
        if(numOne!=1){
            System.out.println("NO");
            return;
        }
        int row=0,col=0;
        for(int i=1;i<=1000;i++){
            if(rec[i]<4) continue;
            while(rec[i]>=4&&row<n/2){
                rec[i] -= 4;
                ans[row][col] = i;
                ans[row][n-1-col] = i;
                ans[n-1-row][col] = i;
                ans[n-1-row][n-1-col] = i;
                col++;
                if(col==n/2){
                    row++;
                    col = 0;
                }
            }
            if(row==n/2) break;
        }
        if(row!=n/2||col!=0){
            System.out.println("NO");
            return;
        }
        int vert = 0, hori = 0;
        for(int i=1;i<=1000;i++){
            while(rec[i]>0){
                rec[i] -= 2;
                if(hori<n/2){
                    ans[n/2][hori] = ans[n/2][n-1-hori] = i;
                    hori++;
                } else{
                    ans[vert][n/2] = ans[n-1-vert][n/2] = i;
                    vert++;
                }
            }
        }
        System.out.println("YES");
        for(int i=0;i<n;i++){
            for(int j=0;j<n;j++) {
                System.out.print(ans[i][j]);
                System.out.print(" ");
            }
            System.out.println("");
        }
    }
