		for(int i=0;i<n*n;i++) {
			nums[i] = Integer.parseInt(s[i]);
		}
		PriorityQueue<Element> pq = getElements(nums);
		int[][] arr = new int[n][n];
		if(!fill1(arr,pq)) return;
		if(n%2==1) {
			if(!fill2(arr,pq)) return;
			if(!fill3(arr,pq)) return;
		}
		StringBuffer sb = new StringBuffer("YES\n");
		for(int i=0;i<n;i++) {
			for(int j=0;j<n;j++) {
				sb.append(arr[i][j]).append(" ");
			}
			sb.append("\n");
		}
		System.out.println(sb.toString());
	}

	private static boolean fill3(int[][] arr, PriorityQueue<Element> pq) {
		int l = arr.length;
		Element el = pq.poll();
		arr[l/2][l/2] = el.n;
		return true;
	}

	private static boolean fill2(int[][] arr, PriorityQueue<Element> pq) {
		int l = arr.length;
		for(int i=0;i<l/2;i++) {
			Element el =pq.poll();
			if(el.c<2) {
				System.out.println("NO");
				return false;
			}
			arr[l/2][i] = arr[l/2][l-1-i] = el.n;
			if(el.c>2) pq.add(new Element(el.n,el.c-2));
		}
		for(int i=0;i<l/2;i++) {
			Element el =pq.poll();
			if(el.c<2) {
				System.out.println("NO");
				return false;
			}
			arr[i][l/2] = arr[l-1-i][l/2] = el.n;
			if(el.c>2) pq.add(new Element(el.n,el.c-2));
		}
		return true;
	}

	private static boolean fill1(int[][] arr, PriorityQueue<Element> pq) {
		int l = arr.length;
		for(int i=0;i<l/2;i++) {
			for(int j=0;j<l/2;j++) {
				Element el = pq.poll();
				if(el.c<4) {
					System.out.println("NO");
					return false;
				}
				arr[i][j] = arr[l-1-i][j] = arr[i][l-1-j] = arr[l-1-i][l-1-j] =el.n;
				if(el.c>4) pq.add(new Element(el.n,el.c-4));
			}
		}
		return true;
	}

	private static PriorityQueue<Element> getElements(int[] nums) {
		Map<Integer,Integer> mp= new HashMap<Integer,Integer>();
		PriorityQueue<Element> pq = new PriorityQueue<Element>();
		for(int i=0;i<nums.length;i++) {
			if(mp.get(nums[i])!=null) continue;
			int cnt=1;
			for(int j=i+1;j<nums.length;j++) {
				if(nums[i]==nums[j]) cnt++;
			}
			mp.put(nums[i], cnt);
			pq.add(new Element(nums[i],cnt));
		}
		return pq;
	}

}

