/**
 * Fixed solution for the palindromic matrix problem.
 * The only change is correcting the frequency counting logic:
 * the stray “} {” was replaced with a proper “} else {”.
 */
public class PalindromicMatrix {

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

    static class pairComp implements Comparator<Pair> {
        public int compare(Pair a, Pair b) {
            if (a.first != b.first) return b.first - a.first;
            return b.second - a.second;
        }
    }

    static class Pair {
        int first;
        int second;

        Pair(int fir, int sec) {
            this.first = fir;
            this.second = sec;
        }

        int getFirst() {
            return this.first;
        }

        int getSecond() {
            return this.second;
        }

        void setFirst(int x) {
            this.first = x;
        }

        void setSecond(int x) {
            this.second = x;
        }

        public String toString() {
            return this.first + " " + this.second;
        }
    }

    static int rev(int i, int n) {
        return n - i - 1;
    }

    static void no() {
        System.out.println("NO");
        return;
    }

    static void put(ArrayList<Pair> al, PriorityQueue<Pair> pq, int[][] arr2) {
        Pair p = pq.poll();
        if (p.first < al.size()) {
            no();
        }
        for (Pair pa : al) {
            arr2[pa.first][pa.second] = p.second;
        }
        p.first -= al.size();
        pq.add(p);
    }

