        for (int i = 0; i < n * n; i++) {
            int now = arr[i];
            if (hm.containsKey(now)) {
                int set = hm.get(now) + 1;
                hm.put(now, set);
            } else {
                hm.put(now, 1);
            }
        }
        PriorityQueue<Pair> pq = new PriorityQueue<>(new pairComp());
        for (Integer key : hm.keySet()) {
            Pair p = new Pair(hm.get(key), key);
            pq.add(p);
        }

        int m = n / 2;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                int revi = rev(i, n);
