public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        ReaderFastIO in = new ReaderFastIO(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CPalindromicMatrix solver = new CPalindromicMatrix();
        solver.solve(1, in, out);
        out.close();
    }

    static class CPalindromicMatrix {
        private static PrintWriter out;
        private int[][] m;
        private PriorityQueue<Pair> queue;

        public void solve(int testNumber, ReaderFastIO in, PrintWriter out) {

            this.out = out;
            int n = in.nextInt();
            m = new int[n][n];

            Map<Integer, Integer> map = new HashMap<Integer, Integer>();
            queue = new PriorityQueue<Pair>();

            for (int i = 0; i < n * n; i++) {
                int a = in.nextInt();
                map.put(a, map.getOrDefault(a, 0) + 1);
            }

            map.forEach((key, value) -> queue.add(new Pair(value, key)));

            boolean possible = true;

            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    possible = possible && fill(new int[][]{{i, j}, {i, rev(j, n)}, {rev(i, n), j}, {rev(i, n), rev(j, n)}});
                }
            }

            if (n % 2 == 1) {
                for (int i = 0; i < n / 2; i++) {
                    possible = possible && fill(new int[][]{{i, (n - 1) / 2}, {rev(i, n), (n - 1) / 2}});
                    possible = possible && fill(new int[][]{{(n - 1) / 2, i}, {(n - 1) / 2, rev(i, n)}});
                }

                possible = possible && fill(new int[][]{{(n - 1) / 2, (n - 1) / 2}});
            }

            if (possible == false) {
                out.println("NO");
            } else {
                out.println("YES");
                print(m);
            }

        }

        public void print(int[][] m) {
            for (int i = 0; i < m.length; i++) {
                for (int j = 0; j < m[i].length; j++) {
                    out.print(m[i][j] + " ");
                }
                out.println();
            }
        }

        public boolean fill(int[][] coords) {

            Pair<Integer, Integer> pair = queue.poll();

            if (pair.getKey() < coords.length) {
                return false;
            }

            for (int i = 0; i < coords.length; i++) {
                m[coords[i][0]][coords[i][1]] = pair.getValue();
            }

            queue.add(new Pair(pair.getKey() - coords.length, pair.getValue()));

            return true;
        }

        public int rev(int i, int n) {
            return n - 1 - i;
        }

    }

    static class Pair<A, B> implements Comparable<Pair> {
        private A key;
        private B value;

        public Pair(A key, B value) {
            this.key = key;
            this.value = value;
        }

        public A getKey() {
            return key;
        }

        public B getValue() {
            return value;
        }

        public int compareTo(Pair p) {

            if (key instanceof Integer) {
                return -Integer.compare((Integer) this.key, (Integer) p.key);
            } else if (key instanceof Long) {
                return -Long.compare((Long) this.key, (Long) p.key);
            } else if (key instanceof Double) {
                return -Double.compare((Double) this.key, (Double) p.key);
            } else if (key instanceof String) {
                return ((String) this.key).compareTo((String) p.key);
            }

            throw new NullPointerException();
        }

    }

    static class ReaderFastIO {
        BufferedReader br;
        StringTokenizer st;

        public ReaderFastIO() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public ReaderFastIO(InputStream input) {
            br = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

