public class Task {

    public static void main(String[] args) throws IOException {

        new Task().go();
    }

    PrintWriter out;
    Reader in;
    BufferedReader br;

    Task() throws IOException {

        try {


            in = new Reader("input.txt");
            out = new PrintWriter( new BufferedWriter(new FileWriter("output.txt")) );
        }
        catch (Exception e) {


            in = new Reader();
            out = new PrintWriter( new BufferedWriter(new OutputStreamWriter(System.out)) );
        }
    }

    void go() throws IOException {

        int t = 1;
        while (t > 0) {
            solve();

            t++;
        }

        out.flush();
        out.close();
    }

    int inf = 2000000000;
    int mod = 1000000007;
    double eps = 0.000000001;

    int n;
    int m;

    int[] a;
    ArrayList<Integer>[] g;
    void solve() throws IOException {
        int n = in.nextInt();
        int[] cnt = new int[1010];
        for (int i = 0; i < n * n; i++) {
            int x = in.nextInt();
            cnt[x]++;
        }

        int[][] a = new int[n][n];
        int cur = 1;
        for (int i = 0; i < n / 2; i++)
            for (int j = 0; j < n / 2; j++) {
                if (a[i][j] == 0) {

                    while (cur < cnt.length && cnt[cur] < 4) {
                        cur++;
                    }

                    if (cur == cnt.length) {

                        out.print("NO");
                        return;
                    }
                    cnt[cur] -= 4;
                    a[i][j] = cur;
                    a[n - i - 1][j] = cur;
                    a[i][n - j - 1] = cur;
                    a[n - i - 1][n - j - 1] = cur;
                }
            }

            if (n % 2 == 1) {
                cur = 1;
                for (int i = 0; i < n / 2; i++) {
                    while (cur < cnt.length && cnt[cur] < 2) {
                        cur++;
                    }
                    if (cur == cnt.length) {
                        out.print("NO");
                        return;
                    }
                    cnt[cur] -= 2;
                    a[i][n / 2] = cur;
                    a[n - i - 1][n / 2] = cur;
                }

                // ---- fixed part ----
                // after placing the column‑pairs we must start searching
                // for numbers again, otherwise we may skip a suitable value
                // for the row‑pairs and incorrectly output "NO".
                cur = 1;
                for (int i = 0; i < n / 2; i++) {
                    while (cur < cnt.length && cnt[cur] < 2) {
                        cur++;
                    }
                    if (cur == cnt.length) {
                        out.print("NO");
                        return;
                    }
                    cnt[cur] -= 2;
                    a[n / 2][i] = cur;
                    a[n / 2][n - i - 1] = cur;
                }
                // --------------------

            }

            for (int i = 0; i < cnt.length; i++)
                if (cnt[i] == 1)
                    a[n / 2][n / 2] = i;

            out.println("Yes");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++)
                    out.print(a[i][j] + " ");
                out.println();
            }
    }

