import java.io.*;
import java.util.*;

public class tank {

    static final FastScanner fs = new FastScanner();

    static PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        int t = 1;
        while (t-- > 0) {
            run_case();
        }

        out.close();
    }

    static void run_case() {
        int n = fs.nextInt();
        int[] arr = fs.readArray(n * n);
        int[] cnt = new int[1001];

        Queue<Integer> one = new ArrayDeque<>();
        Queue<Integer> two = new ArrayDeque<>();
        Queue<Integer> four = new ArrayDeque<>();

        for (int i : arr) cnt[i]++;

        for (int i = 1; i <= 1000; i++) {
            if (cnt[i] >= 4) {
                while (cnt[i] >= 4) {
                    four.offer(i);
                    cnt[i] -= 4;
                }
            }
            if (cnt[i] >= 2) {
                two.offer(i);
                cnt[i] -= 2;
            }
            if (cnt[i] == 1) {
                one.offer(i);
            }
            cnt[i] = 0;
        }

        int[][] mat = new int[n][n];

        if (n % 2 == 0) {
            if (one.size() > 0 || two.size() > 0) {
                out.println("NO");
                return;
            }

            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    fn(i, j, four.poll(), mat, n);
                }
            }
        } else {
            if (one.size() + two.size() > 2 * n - 1 || one.size() != 1) {
                out.println("NO");
                return;
            }

            mat[n / 2][n / 2] = one.poll();

            while (two.size() < n - 1) {
                int tmp = four.poll();
                two.offer(tmp);
                two.offer(tmp);
            }

            if (two.size() > n - 1) {
                out.println("NO");
                return;
            }

            for (int i = 0; i < n / 2; i++) {
                int tmp = two.poll();
                mat[i][n / 2] = mat[n - i - 1][n / 2] = tmp;
            }

            for (int i = 0; i < n / 2; i++) {
                int tmp = two.poll();
                mat[n / 2][i] = mat[n / 2][n - i - 1] = tmp;
            }

            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    fn(i, j, four.poll(), mat, n);
                }
            }
        }

        out.println("YES");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {          // <-- fixed: start from 0, not -1
                out.print(mat[i][j] + " ");
            }
            out.println();
        }
    }

    static void fn(int i, int j, int val, int[][] mat, int n) {
        mat[i][j] = mat[n - i - 1][j] = mat[i][n - j - 1] = val;
        mat[n - i - 1][n - j - 1] = val;
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");

        String next() {
            while (!st.hasMoreTokens())
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            return st.nextToken();
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return "";
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

