import java.io.*;
import java.util.*;

public class tank {

    static final FastScanner fs = new FastScanner();

    static PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        int t = 1;
        while(t++ > 0) {
            run_case();
        }

        out.close();
    }

    static void run_case() {
        int n = fs.nextInt();
        int[] arr = fs.readArray(n * n);
        int[] cnt = new int[1001];

        Queue<Integer> one = new ArrayDeque<>();
        Queue<Integer> two = new ArrayDeque<>();
        Queue<Integer> four = new ArrayDeque<>();

        for (int i : arr) cnt[i]++;

        for (int i = 1; i <= 1000; i++) {
            if (cnt[i] >= 4) {
                while (cnt[i] >= 4) {
                    four.offer(i);
                    cnt[i] -= 4;
                }
            }

            if (cnt[i] >= 2) {
                two.offer(i);
                cnt[i] -= 2;
            }

            if (cnt[i] == 1) {
                one.offer(i);
            }
            cnt[i] = 0;
        }

        int[][] mat = new int[n][n];

        if (n % 2 == 0) {
            if (one.size() > 0 || two.size() > 0) {
                out.println("NO");
                return;
            }

            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    fn(i, j, four.poll(), mat, n);
                }
            }
        } else {
            if (one.size() + two.size() > 2 * n - 1 || one.size() != 1) {
                out.println("NO");
                return;
            }

            mat[n / 2][n / 2] = one.poll();

            while (two.size() < n - 1) {
                int tmp = four.poll();
                two.offer(tmp);                 // <-- fixed: add only once
                // two.offer(tmp);               // old code added twice
            }

            if (two.size() > n - 1) {
                out.println("NO");
                return;
            }

            for (int i = 0; i < n / 2; i++) {
                int tmp = two.poll();
                mat[i][n / 2] = mat[n - i - 1][n / 2] = tmp;
            }

            for (int i = 0; i < n / 2; i++) {
                int tmp = two.poll();
                mat[n / 2][i] = mat[n / 2][n - i - 1] = tmp;
            }

            for (int i = 0; i < n / 2; i++) {
                for (int j = 0; j < n / 2; j++) {
                    fn(i, j, four.poll(), mat, n);
                }
            }
        }

        out.println("YES");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                out.print(mat[i][j] + " ");
            }
            out.println();
        }
    }

    static void fn(int i, int j, int val, int[][] mat, int n) {
        mat[i][j] = mat[n - i - 1][j] = mat[i][n - j - 1] = val;
        mat[n - i - 1][n - j - 1] = val;
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");

        String next() {
            while (!st.hasMoreTokens())
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            return st.nextToken();
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return "";
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] readArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt();
            return a;
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.*;
public class HelloWorld{

     public static void main(String []args){
        Scanner sc=new Scanner(System.in);
        int n=sc.nextInt();
        int[] ar = new int[1001];
        for(int i=0;i<n*n;i++){
            ar[sc.nextInt()]++;
        }
        boolean flag = false;
        int four = 0, two = 0, one = 0;
        for (int i = 0; i < 1001; i++) {
            int c = ar[i];
            four += c / 4;
            int rem = c % 4;
            two += rem / 2;
            one += rem % 2;
        }
        int groups4Needed = (n/2) * (n/2);
        int pairsNeeded = (n % 2 == 1) ? (n-1) : 0;
        int singlesNeeded = (n % 2 == 1) ? 1 : 0;
        if (four >= groups4Needed && two >= pairsNeeded && one >= singlesNeeded) {
            flag = true;
        } else {
            flag = false;
        }
        int count;
        int ans[][] = new int[n][n];
        int x1 = 0, x2 = 0;
        if (flag) {
            System.out.println("YES");
            for (int i = 0; i < 1001; i++) {
                count = ar[i];
                // place groups of 4
                while (count >= 4 && x1 < groups4Needed) {
                    int r = x1 / (n/2);
                    int cIdx = x1 % (n/2);
                    ans[r][cIdx] = i;
                    ans[n-1-r][cIdx] = i;
                    ans[r][n-1-cIdx] = i;
                    ans[n-1-r][n-1-cIdx] = i;
                    x1++;
                    count -= 4;
                }
                // place pairs (size‑2 orbits) – only when n>1
                while (count >= 2 && n > 1) {
                    if (x2 < (n-1)/2) {
                        ans[x2][(n-1)/2] = i;
                        ans[n-1-x2][(n-1)/2] = i;
                    } else {
                        int col = x2 % ((n-1)/2);
                        ans[(n-1)/2][col] = i;
                        ans[(n-1)/2][n-1-col] = i;
                    }
                    x2++;
                    count -= 2;
                }
                // place the single centre cell if needed
                if (count > 0) {
                    ans[(n-1)/2][(n-1)/2] = i;
                }
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    System.out.print(ans[i][j]);
                    if (j < n-1) System.out.print(" ");
                }
                System.out.println();
            }
        } else {
            System.out.println("NO");
        }
     }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        // frequency of each value (values are between 1 and 1000)
        int[] freq = new int[1001];
        for (int i = 0; i < n * n; i++) {
            int v = sc.nextInt();
            if (v >= 1 && v <= 1000) {
                freq[v]++;
            }
        }

        int half = n / 2;               // floor division
        int need4 = half * half;         // number of 4‑cell groups
        int need2 = (n % 2 == 0) ? 0 : (2 * half); // number of 2‑cell groups when n is odd
        int need1 = (n % 2 == 0) ? 0 : 1; // centre cell when n is odd

        int[][] ans = new int[n][n];
        boolean possible = true;

        // ---------- fill 4‑cell groups ----------
        for (int i = 0; i < half && possible; i++) {
            for (int j = 0; j < half && possible; j++) {
                int val = -1;
                for (int v = 1; v <= 1000 && possible; v++) {
                    if (freq[v] >= 4) {
                        val = v;
                        break;
                    }
                }
                if (val == -1) {
                    possible = false;                 // cannot fill a 4‑group
                } else {
                    ans[i][j] = val;
                    ans[n - 1 - i][j] = val;
                    ans[i][n - 1 - j] = val;
                    ans[n - 1 - i][n - 1 - j] = val;
                    freq[val] -= 4;
                }
            }
        }

        // ---------- fill 2‑cell groups (only when n is odd) ----------
        if (possible && n % 2 == 1) {
            // pairs on the middle row
            for (int j = 0; j < half && possible; j++) {
                int val = -1;
                for (int v = 1; v <= 1000 && possible; v++) {
                    if (freq[v] >= 2) {
                        val = v;
                        break;
                    }
                }
                if (val == -1) {
                    possible = false;
                } else {
                    ans[half][j] = val;
                    ans[half][n - 1 - j] = val;
                    freq[val] -= 2;
                }
            }
            // pairs on the middle column
            for (int i = 0; i < half && possible; i++) {
                int val = -1;
                for (int v = 1; v <= 1000 && possible; v++) {
                    if (freq[v] >= 2) {
                        val = v;
                        break;
                    }
                }
                if (val == -1) {
                    possible = false;
                } else {
                    ans[i][half] = val;
                    ans[n - 1 - i][half] = val;
                    freq[val] -= 2;
                }
            }
        }

        // ---------- fill centre cell ----------
        if (possible && n % 2 == 1) {
            int val = -1;
            for (int v = 1; v <= 1000; v++) {
                if (freq[v] > 0) {
                    val = v;
                    break;
                }
            }
            if (val == -1) {
                possible = false;
            } else {
                ans[half][half] = val;
            }
        }

        // ---------- output ----------
        System.out.println(possible ? "YES" : "NO");
        if (possible) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    System.out.print(ans[i][j]);
                    if (j + 1 < n) System.out.print(" ");
                }
                System.out.println();
            }
        }

        sc.close();
    }
}

