                                    pic[k][j] = '-';
                                    upDown++;
                                }
                                else break;
                            pic[i][j]='-';
                            found = true;
                            break outer;
                        }else{
                            up = down = left = right = false;
                            upDown = leftRight = 0;
                        }
                    }
                }
            }
            if(found) {
                for (int i = 0; i <pic.length; i++)
                    for (int j = 0; j < pic[i].length; j++)
                        if (pic[i][j] == '*') {
                            out.println("NO");
                            return;
                        }
                out.println("YES");
            }else{
                out.println("NO");
            }
        }
    }
