public class PlusFrom {
	public static void main(String[]args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		StringTokenizer st = new StringTokenizer(br.readLine());
		int h = Integer.parseInt(st.nextToken());
		int w = Integer.parseInt(st.nextToken());

		int total = 0;

		boolean[][]plus = new boolean[h][w];

		for(int i = 0; i<h; i++) {
			String s = br.readLine();
			for(int j = 0; j<w; j++) {
				plus[i][j] = s.charAt(j)=='*';
				if(plus[i][j])total++;
			}
		}

		boolean fin = false;

		for(int i = 1; i<h-1 && !fin;i++) {
			for(int j = 1; j<w-1 && !fin; j++) {

				if(plus[i][j]) {

					if(plus[i][j-1] && plus[i-1][j] &&plus[i][j+1] &&plus[i+1][j]) {
						int count = 1;

						for(int x = i+1; x<h && plus[x][j]; x++) {
							count++;
						}
						for(int x = i-1; x>=0 && plus[x][j]; x--) {
							count++;
						}
						for(int x = j+1; x<w && plus[i][x]; x++) {
							count++;
						}
						for(int x = j-1; x>=0 && plus[i][x]; x--) {
							count++;
						}

						if(count==total) {
							System.out.println("YES");
						} else {
							System.out.println("NO");
						}
						fin = true;

					}
				}
			}
		}

