import java.util.Scanner;

public class B {
	public static boolean f = false;

	public static boolean check(char[][] map, int ch, int cw) {
		if (map[ch][cw] == '.' || map[ch - 1][cw] == '.' ||
			map[ch + 1][cw] == '.' || map[ch][cw - 1] == '.' ||
			map[ch][cw + 1] == '.') {
			return false;
		}
		return true;
	}

	public static void mark(char[][] map, int ch, int cw) {
		f = true;
		map[ch][cw] = '.';
		for (int i = ch + 1; i < map.length; i++) {
			if (map[i][cw] == '.') break;
			map[i][cw] = '.';
		}
		for (int i = ch - 1; i >= 1; i--) {
			if (map[i][cw] == '.') break;
			map[i][cw] = '.';
		}
		for (int i = cw + 1; i < map[ch].length; i++) {
			if (map[ch][i] == '.') break;
			map[ch][i] = '.';
		}
		for (int i = cw - 1; i >= 1; i--) {
			if (map[ch][i] == '.') break;
			map[ch][i] = '.';
		}
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int h = sc.nextInt(), w = sc.nextInt();
		if (h <= 2 || w <= 2) {
			System.out.println("NO");
			return;
		}
		char[][] map = new char[h + 1][w + 1];
		String input;
		for (int i = 1; i <= h; i++) {
			input = sc.next();
			for (int j = 1; j <= w; j++) {
				map[i][j] = input.charAt(j - 1);
			}
		}

		for (int i = 2; i < h; i++) {
			if (f) break;
			for (int j = 2; j < w; j++) {
				if (check(map, i, j)) {
					mark(map, i, j);
					break;
				}
			}
		}

		// Removed premature "NO" output that incorrectly terminated the program.
		// Now we simply check if any '*' remain.

		for (int i = 1; i <= h; i++) {
			for (int j = 1; j <= w; j++) {
				if (map[i][j] == '*') {
					System.out.println("NO");
					return;
				}
			}
		}
		System.out.println("YES");
	}
}

