import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;

public class CODEFORCES_1182_B {

	public static void main (String[] t) throws IOException {
		INPUT in = new INPUT (System.in);
		PrintWriter out = new PrintWriter (System.out);

		int H = in.iscan (), W = in.iscan ();
		char[][] grid = new char[H][];

		for (int h = 0; h < H; ++h)
			grid[h] = in.sscan ().toCharArray ();

		boolean[][] vis = new boolean[H][W];
		boolean good = false;

		for (int h = 1; h < H - 1 && !good; ++h) {
			for (int w = 1; w < W - 1 && !good; ++w) {
				if (grid[h][w] == '*') {

					vis[h][w] = true;


					boolean up = false;
					for (int h2 = h - 1; h2 >= 0 && grid[h2][w] == '*'; --h2)
						vis[h2][w] = up = true;


					boolean down = false;
					for (int h2 = h + 1; h2 < H && grid[h2][w] == '*'; ++h2)
						vis[h2][w] = down = true;


					boolean left = false;
					for (int w2 = w - 1; w2 >= 0 && grid[h][w2] == '*'; --w2)
						vis[h][w2] = left = true;


					boolean right = false;
					for (int w2 = w + 1; w2 < W && grid[h][w2] == '*'; ++w2)
						vis[h][w2] = right = true;

					if (up && down && left && right)
						good = true;
					else {
						Arrays.fill (vis[h], false);

						for (int h2 = 0; h2 < H; ++h2)
							vis[h2][w] = false;
					}
				}
			}
		}

		out:
		for (int h = 0; h < H; ++h) {
			for (int w = 0; w < W; ++w) {
				if (grid[h][w] == '*' && !vis[h][w]) {
					good = false;
					break out;
				}
			}
		}

		out.print (good ? "YES" : "NO");
		out.close ();
	}

	private static class INPUT {

		private InputStream stream;
		private byte[] buf = new byte[1024];
		private int curChar, numChars;

		public INPUT (InputStream stream) {
			this.stream = stream;
		}

		public INPUT (String file) throws IOException {
			this.stream = new FileInputStream (file);
		}

		public int cscan () throws IOException {
			if (curChar >= numChars) {
				curChar = 0;
				numChars = stream.read (buf);
			}

			if (numChars == -1)
				return numChars;

			return buf[curChar++];
		}

		public int iscan () throws IOException {
			int c = cscan (), sgn = 1;

			while (space (c))
				c = cscan ();

			if (c == '-') {
				sgn = -1;
				c = cscan ();
			}

			int res = 0;

			do {
				res = (res << 1) + (res << 3);
				res += c - '0';
				c = cscan ();
			}
			while (!space (c));

			return res * sgn;
		}

		public String sscan () throws IOException {
			int c = cscan ();

			while (space (c))
				c = cscan ();

			StringBuilder res = new StringBuilder ();

			do {
				res.appendCodePoint (c);
				c = cscan ();
			}
			while (!space (c));

			return res.toString ();
		}

		public double dscan () throws IOException {
			int c = cscan (), sgn = 1;

			while (space (c))
				c = cscan ();

			if (c == '-') {
				sgn = -1;
				c = cscan ();
			}

			double res = 0;

			while (!space (c) && c != '.') {
				if (c == 'e' || c == 'E')
					return res * UTILITIES.fast_pow (10, iscan ());

				res *= 10;
				res += c - '0';
				c = cscan ();
			}

			if (c == '.') {
				c = cscan ();
				double m = 1;

				while (!space (c)) {
					if (c == 'e' || c == 'E')
						return res * UTILITIES.fast_pow (10, iscan ());

					m /= 10;
					res += (c - '0') * m;
					c = cscan ();
				}
			}

			return res * sgn;
		}

		public long lscan () throws IOException {
			int c = cscan (), sgn = 1;

			while (space (c))
				c = cscan ();

			if (c == '-') {
				sgn = -1;
				c = cscan ();
			}

			long res = 0;

			do {
				res = (res << 1) + (res << 3);
				res += c - '0';
				c = cscan ();
			}
			while (!space (c));

			return res * sgn;
		}

		public boolean space (int c) {
			return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
		}
	}

	public static class UTILITIES {

		static final double EPS = 10e-6;

		public static int lower_bound (int[] arr, int x) {
			int low = 0, high = arr.length, mid = -1;

			while (low < high) {
				mid = (low + high) / 2;

				if (arr[mid] >= x)
					high = mid;
				else
					low = mid + 1;
			}

			return low;
		}

		public static int upper_bound (int[] arr, int x) {
			int low = 0, high = arr.length, mid = -1;

			while (low < high) {
				mid = (low + high) / 2;

				if (arr[mid] > x)
					high = mid;
				else
					low = mid + 1;
			}

			return low;
		}

		public static int gcd (int a, int b) {
