			if(sec == 1 && s[i] == '.'){
				sec++; continue;
			}
			if(sec == 1 && s[i] == '*') {
				b++; continue;
			}
			if(sec == 2 && s[i] == '.') continue;
			if(sec == 2 && s[i] == '*'){
				return new Pair(-2, -1);
			}
		}
		return new Pair(a, b);
	}
