        int[] str = new int[h];
        for (int i = 0; i < h; i++) {
            String tmp = enter.next();
            for (int j = 0; j < w; j++) {
                arr[i][j] = (tmp.charAt(j) == '.') ? 0 : 1;
                summ_all += arr[i][j];               // fixed: accumulate stars
                str[i] += arr[i][j];
            }
        }
        if (!(w > 2 && h > 2)) {
            out.print("NO");
            out.close();
            return;
        }
        int n_cent = -1;
        for (int i = 1; i < h - 1; i++) {
            if (str[i] >= 3) {
                n_cent = i;
                break;
            }
        }
        if (n_cent == -1) {
            out.print("NO");
            out.close();
            return;
        }
        int i_first = 1;
        int i_last = -1;
        while (arr[n_cent][i_first] == 0) i_first++;
        i_last = i_first + 1;
        while (i_last < w && arr[n_cent][i_last] == 1) i_last++;
        i_last--;
        if (i_last == i_first) {
            out.print("NO");
            out.close();
            return;
        }
        int n_stars = i_last - i_first + 1;
        if (arr[n_cent][i_first - 1] == 1) {
            n_stars++;
        } else i_first++;
        i_last--;
        if (i_last < i_first) {
            out.print("NO");
            out.close();
            return;
        }
        for (int i = i_first; i <= i_last; i++) {
            int j = n_cent - 1;
            int kol_vo = 0;
            while (j >= 0 && arr[j][i] == 1) {
                kol_vo++;
                j--;
            }
            if (kol_vo == 0) continue;
            int kol_vo2 = 0;
            j = n_cent + 1;
            while (j < h && arr[j][i] == 1) {
                kol_vo2++;
                j++;
            }
            if (kol_vo2 == 0) {
                out.print("NO");
                out.close();
                return;
            }
            if (kol_vo + kol_vo2 + n_stars == summ_all) {
                out.print("YES");
                out.close();
                return;
            }
        }
        out.print("NO");
        out.close();
        return;
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer stok;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() throws IOException {
            while (stok == null || !stok.hasMoreTokens()) {
                String s = br.readLine();
                if (s == null) {
                    return null;
                }
                stok = new StringTokenizer(s);
            }
            return stok.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        char nextChar() throws IOException {
            return (char) (br.read());
        }

        String nextLine() throws IOException {
            return br.readLine();
        }
    }
}

