import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

import static java.lang.Integer.parseInt;

public class B_Plus_from_Picture {
    static int count, row, col;
    static char[][] mtx;
    static int xAxis[] = {-1, 1, 0, 0};
    static int yAxis[] = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tk = new StringTokenizer(in.readLine());
        row = parseInt(tk.nextToken());
        col = parseInt(tk.nextToken());
        mtx = new char[row + 2][col + 2];
        for (int i = 1; i <= row; i++) {
            char[] line = in.readLine().toCharArray();
            for (int j = 1; j <= col; j++) {
                mtx[i][j] = line[j - 1];
                if (mtx[i][j] == '*')
                    count++;
            }
        }
        solve();
    }

    static void solve() {
        for (int i = 1; i <= row; i++) {
            for (int j = 1; j <= col; j++) {
                if (mtx[i][j] == '*') {
                    boolean flag = true;
                    for (int k = 0; k < 4; k++) {
                        if (mtx[i + xAxis[k]][j + yAxis[k]] != '*') {
                            flag = false;
                            break;
                        }
                    }
                    if (flag) {
                        int ans = countConsecutiveStars(i, j);
                        if (ans == count) {
                            System.out.println("YES");
                            return;
                        }
                    }
                }
            }
        }
        System.out.println("NO");
    }

    private static int countConsecutiveStars(int i, int j) {
        int cnt = 0;
        for (int k = i + 1; k <= row; k++) {
            if (mtx[k][j] == '*' && mtx[k - 1][j] == '*')
                cnt++;
        }
        for (int k = i - 1; k > 0; k--) {
            if (mtx[k][j] == '*' && mtx[k + 1][j] == '*')
                cnt++;
        }
        for (int k = j + 1; k <= col; k++) {
            if (mtx[i][k] == '*' && mtx[i][k - 1] == '*')
                cnt++;
        }
        for (int k = j - 1; k > 0; k--) {
            if (mtx[i][k] == '*' && mtx[i][k + 1] == '*')
                cnt++;
        }
        return cnt + 1;
    }
}

