public class star {

	static void dfs(int graph[][],int x,int y,boolean visited[][],int direction) {
		if(x<0 || y<0 || x>=graph.length || y>=graph[0].length || graph[x][y]==0) {
			return;
		}
		visited[x][y]=true;
		if(x>0 && !visited[x-1][y] && direction==0)
			dfs(graph,x-1,y,visited,direction);
		if(x<graph.length-1 && !visited[x+1][y] && direction==2)
			dfs(graph,x+1,y,visited,direction);
		if(y>=1 && !visited[x][y-1] && direction==3)
			dfs(graph,x,y-1,visited,direction);
		if(y<graph[0].length-1 && !visited[x][y+1] && direction==1)
			dfs(graph,x,y+1,visited,direction);
	}
