        for (int i = x; i >= 0; i--) {
            if (s[i][y] == '#') continue;
            if (s[i][y] == '*') s[i][y] = '#';
            else break;
        }

        for (int i = x; i < s.length; i++) {
            if (s[i][y] == '#') continue;
            if (s[i][y] == '*') s[i][y] = '#';
            else break;
        }

