import java.io.*;
import java.util.*;

public class B {
    static int[] DX = {0, -1, +1, 0, 0};
    static int[] DY = {0, 0, 0, -1, +1};
    static void solve(FastIO io) {
        int h = io.nextInt();
        int w = io.nextInt();

        boolean[][] mat = new boolean[h][w];
        int cnt = 0;
        boolean yes = false;

        for (int i = 0; i < h; i++) {
            String s = io.next();
            for (int j = 0; j < w; j++)
                if (mat[i][j] = s.charAt(j) == '*')
                    cnt++;
        }

        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (!mat[i][j])
                    continue;

                int up = 0;
                int down = 0;
                int left = 0;
                int right = 0;

                int k = i - 1;
                while (k >= 0) {
                    if (mat[k][j]) {
                        up++;
                        k--;
                    } else break;
                }

                k = i + 1;
                while (k < h) {
                    if (mat[k][j]) {
                        down++;
                        k++;
                    } else break;
                }

                k = j - 1;
                while (k >= 0 && mat[i][k]) {
                    left++;
                    k--;
                }

                k = j + 1;
                while (k < w) {
                    if (mat[i][k]) {
                        right++;
                        k++;
                    } else break;
                }

                if (1 + up + down + left + right == cnt && up > 0 && down > 0 && left > 0 && right > 0)
                    yes = true;
            }
        }

        if (cnt <= 4 || h <= 2 || w <= 2)
            yes = false;

        io.println((yes ? "YES" : "NO"));
    }

    public static void main(String[] args) {
        FastIO io = new FastIO();
        solve(io);
        io.close();
    }
}

