            }
        }
        int[] rowCnt = new int[H];
        int[] colCnt = new int[W];
        for(int i = 0; i < H; i++) {
            for(int j = 0; j < W; j++) {
                if (pic[i][j] == '*') {
                    rowCnt[i]++;
                    colCnt[j]++;
                }
            }
        }
        int tot = 0;
        for(int i = 0; i < H; i++) tot += rowCnt[i];   // fixed: accumulate all row counts
        if (tot < 4) bad();
        boolean[][] vis = new boolean[H][W];
        boolean done = false;
        for(int i = 0; i < H && !done; i++) {
            for(int j = 0; j < W && !done; j++) {
                if (pic[i][j] == '*') {
                    vis[i][j] = true;
                    int[] dirsR = new int[] {1, 0, -1, 0};
                    int[] dirsC = new int[] {0, 1, 0, -1};
                    ArrayDeque<Pair> queue = new ArrayDeque<>();
                    queue.offer(new Pair(i, j));
                    int total = 0;
                    done = true;
                    while(!queue.isEmpty()) {
                        total++;
                        Pair cur = queue.poll();
                        for(int k = 0; k < dirsC.length; k++) {
                            int nextR = cur.r + dirsR[k];
                            int nextC = cur.c + dirsC[k];
                            if (nextR < 0 || nextC < 0 || nextR >= H || nextC >= W || vis[nextR][nextC] || pic[nextR][nextC] != '*') continue;
                            vis[nextR][nextC] = true;
                            queue.offer(new Pair(nextR, nextC));
                        }
                    }
                    if (total != tot) bad();
                }
            }
        }
        if (H == 1 || W == 1) bad();
        boolean inc = true;
        for(int i = 1; i < H; i++) {
            if (inc && rowCnt[i] < rowCnt[i-1]) bad();
            else if (rowCnt[i-1] > 1 && rowCnt[i] != 1) bad();
            else if (inc && rowCnt[i] > 1) inc = false;
            else if (!inc && rowCnt[i] > 1) bad();
            else if(!inc && rowCnt[i] > rowCnt[i-1]) bad();
        }
        if (inc) bad();
        inc = true;
        for(int i = 1; i < W; i++) {
            if (inc && colCnt[i] < colCnt[i-1]) bad();
            else if (colCnt[i-1] > 1 && colCnt[i] != 1) bad();
            else if (inc && colCnt[i] > 1) inc = false;
            else if (!inc && colCnt[i] > 1) bad();
            else if(!inc && colCnt[i] > colCnt[i-1]) bad();
        }
        if(inc) bad();
        out.println("YES");
        out.flush();
    }

