                            graph[i * m + j].add((i - 1) * m + j);
                        }
                    }
                    if (j > 0) {
                        if (a[i][j - 1] == '*') {
                            graph[i * m + j].add(i * m + j - 1);
                        }
                    }
                    if (i < n - 1) {
                        if (a[i + 1][j] == '*') {
