import java.lang.*;

public class Main
 {
  public static void main(String[] args) 
  {
    boolean answer = false;
    Scanner input = new Scanner(System.in);
    int h = input.nextInt();
    int w = input.nextInt();
    input.nextLine();
    char picture[][] = new char[h][w];
    for ( int i = 0; i <  h ; i ++)
    {
      String a = input.nextLine();
      for ( int j = 0; j < w ; j++)
      {
        char b = a.charAt(j);
        picture[i][j]= b;
      }
    }

    boolean run = false;
    boolean ran = false;

    for ( int i = 1; i < h-1; i++)
    {
      for( int j = 1 ; j < w-1 ; j++)
      {

        if ( ran == false)
        {
        if(picture [i][j] == '*')
        {
          if ( picture [i + 1][j]=='*')
          {
            if ( picture [i - 1][j]=='*')
            {
              if ( picture[i][j-1]=='*')
              {
                if ( picture [i][j+1] == '*')
                {
                  answer = true;
                  run = true;
                }
              }
            }
          }
        }
        }

        if ( run)
        {
          picture[i][j] = '.';
          for ( int d = i + 1; d < h; d ++)
          {
            if ( picture[d][j] == '*')
            {
               picture [d][j] = '.';
            }
            else
            {
              break;
            }
          }

          for ( int e = i -1; e >= 0; e--)
          {
            if ( picture[e][j] == '*')
            {
               picture [e][j] = '.';
            }
            else
            {
              break;
            }
          }

          for ( int p = j + 1; p < w; p ++)
          {
            if ( picture[i][p] == '*')
            {
               picture [i][p] = '.';
            }
            else
            {
              break;
            }
          }

          for ( int f = j -1; f>=0; f--)
          {
            if ( picture[i][f] == '*')
            {
               picture [i][f] = '.';
            }
            else
            {
              break;
            }
          }
          run = false;
          ran = true;
        }
      }
    }

    for ( int i = 0; i < h; i++)
    {
      for ( int j = 0; j < w; j++)
      {
        if ( picture[i][j] == '*')
        {
          answer = false;
        }
      }
    }

   if ( answer)
   {
     System.out.println("YES");
   }
   else
   {
     System.out.println("NO");
   }

  }
}

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.StringTokenizer;

public class B {
    static class InputReader {
        BufferedReader reader;
        StringTokenizer tokenizer;
        boolean isClosed;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
            isClosed = false;
        }

        String nextLine() {
            try {
                return reader.readLine();
            } catch (Exception e) {
                return "0";
            }
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (Exception e) {
                    isClosed = true;
                    return "0";
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

    }

    static class Pair {
        Integer fst;
        Integer snd;

        Pair(int a, int b) {
            fst = a;
            snd = b;
        }

        @Override
        public int hashCode() {
            return fst.hashCode() ^ snd.hashCode();
        }

        @Override
        public boolean equals(Object o) {
            if (o == null || !(o instanceof Pair)) return false;
            Pair p = (Pair) o;
            return this.fst.equals(p.fst) && this.snd.equals(p.snd);
        }
    }

    public static void main(String[] args) {
        InputReader sc = new InputReader(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        String[] matrix = new String[n];
        int hCenter = 0;
        int jCenter = 0;
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            matrix[i] = line;
        }
        HashSet<Pair> stars = new HashSet<>();
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (matrix[i].charAt(j) == '*' &&
                        matrix[i - 1].charAt(j) == '*' &&
                        matrix[i + 1].charAt(j) == '*' &&
                        matrix[i].charAt(j - 1) == '*' &&
                        matrix[i].charAt(j + 1) == '*') {
                    jCenter = j;
                    hCenter = i;
                }
            }
        }
        boolean found = false;
        boolean stopped = false;
        boolean broken = false;
        if (hCenter == 0 && jCenter == 0) {
            System.out.println("NO");
            return;
        }
        String line = matrix[hCenter];
        for (int i = 0; i < m; i++) {
            if (found) {
                if (line.charAt(i) == '*') {
                    if (stopped) {
                        broken = true;
                    }
                    stars.add(new Pair(hCenter, i));
                } else {
                    stopped = true;
                }
            }
            if (!found && line.charAt(i) == '*') {
                stars.add(new Pair(hCenter, i));
                found = true;
            }
        }
        if (broken) {
            System.out.println("NO");
            return;
        }
        found = false;
        stopped = false;
        for (int i = 0; i < n; i++) {
            if (found) {
                if (matrix[i].charAt(jCenter) == '*') {
                    if (stopped) {
                        broken = true;
                    }
                    stars.add(new Pair(i, jCenter));
                } else {
                    stopped = true;
                }
            } else if (matrix[i].charAt(jCenter) == '*') {
                stars.add(new Pair(i, jCenter));
                found = true;
            }

        }
        if (broken) {
            System.out.println("NO");
            return;
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (matrix[i].charAt(j) == '*' && !stars.contains(new Pair(i, j))) {
                    broken = true;
                }
            }
        }
        if (broken) {
            System.out.println("NO");
        } else System.out.println("YES");
    }
}

