public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BPlusFromPicture solver = new BPlusFromPicture();
        solver.solve(1, in, out);
        out.close();
    }

    static class BPlusFromPicture {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int h = in.nextInt();
            int w = in.nextInt();
            String[] shape = in.nextStringArray(h);
            int count = 0;
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    if (shape[i].charAt(j) == '*') count++;
                }
            }
            boolean yay = false;
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {

                    if (shape[i].charAt(j) == '*') {


                        int up = 0;
                        for (int k = i - 1; k >= 0; k--) {
                            if (shape[k].charAt(j) == '*') up++;
                            else break;
                        }
                        if (up == 0) continue;
                        int down = 0;
                        for (int k = i + 1; k < h; k++) {
                            if (shape[k].charAt(j) == '*') down++;
                            else break;
                        }
                        if (down == 0) continue;
                        int left = 0;

                        for (int k = j - 1; k >= 0; k--) {
                            if (shape[i].charAt(k) == '*') left++;
                            else break;
                        }
                        if (left == 0) continue;

                        int right = 0;

                        for (int k = j + 1; k < w; k++) {
                            if (shape[i].charAt(k) == '*') right++;
                            else break;
                        }
                        if (right == 0) continue;

                        if (left + right + up + down + 1 == count) {
                            yay = true;
                            break;
                        }
                    }
                }
