    {
        Scanner input = new Scanner(System.in);

        int h = input.nextInt();
        int w = input.nextInt();

        String[][] grid = new String[h][w];
        String fix = input.nextLine();

        for(int a = 0; a < h; a++)
        {
            String line = input.nextLine();
            for(int b = 0; b < w; b++)
            {
                grid[a][b] = line.substring(b, b+1);
            }
        }

        for(int i = 1; i < h-1; i++)
        {
            for(int j = 1; j < w-1; j++)
            {
                if(grid[i][j].equals("*") && grid[i-1][j].equals("*") && grid[i+1][j].equals("*") && grid[i][j-1].equals("*") && grid[i][j+1].equals("*"))
                {
                    String[][] copy = new String[h][w];

                    for(int x = 0; x < h; x++)
                    {
                        for(int y = 0; y < w; y++)
                        {
                            copy[x][y] = grid[x][y];
                        }
                    }
                    copy[i][j] = ".";

                    for(int q = i-1; q < h; q++)
                    {
                        if(copy[q][j].equals("."))
                            break;
                        copy[q][j] = ".";
                    }
                    for(int q = i-1; q >= 0; q--)
                    {
                        if(copy[q][j].equals("."))
                            break;
                        copy[q][j] = ".";
                    }

                    for(int q = j+1; q < w; q++)
                    {
                        if(copy[i][q].equals("."))
                            break;
                        copy[i][q] = ".";
                    }
                    for(int q = j-1; q >= 0; q--)
                    {
                        if(copy[i][q].equals("."))
                            break;
                        copy[i][q] = ".";
                    }

                    boolean works = true;

                    for(int a = 0; a < h; a++)
                    {
                        for(int b = 0; b < w; b++)
                        {
                            if(copy[a][b].equals("*"))
                            {
                                works = false;
                            }
                        }
                    }

                    if(works)
                    {
                        System.out.println("YES");
                    }
                    else
                    {
                        System.out.println("NO");
                    }
                    return;
                }
            }
        }
        System.out.println("NO");
    }
}

