    static class task {
        public static void solve(InputReader z, PrintWriter out)
        {
            int r=z.nextInt();
            int c=z.nextInt();
            int ar[][]=new int[r][c];
            int i;int j;
            for(i=0;i<r;i++)
            {
               String a=z.next();
               for(j=0;j<c;j++)
               {
                   char pp=a.charAt(j);
                   if(pp=='.') ar[i][j]=0;
                   else ar[i][j]=1;
               }
            }

            int fl=0; int k;
            for(i=1;i<r-1;i++)
            {
                for(j=1;j<c-1;j++)
                {
                    if(ar[i][j]==1&&ar[i-1][j]==1&&ar[i+1][j]==1&&ar[i][j-1]==1&&ar[i][j+1]==1){
                        fl=1;
                        ar[i][j]=0;
                        for(k=i+1;k<r;k++)
                        {
                            if(ar[k][j]==1)
                            {
                                ar[k][j]=0;
                            }
                            else break;
                        }
                        for(k=i-1;k>=0;k--)
                        {
                            if(ar[k][j]==1)
                            {
                                ar[k][j]=0;
                            }
                            else break;
                        }
                        for(k=j+1;k<c;k++)
                        {
                            if(ar[i][k]==1)
                            {
                                ar[i][k]=0;
                            }
                            else break;
                        }
                        for(k=j-1;k>=0;k--)
                        {
                            if(ar[i][k]==1)
                            {
                                ar[i][k]=0;
                            }
                            else break;
                        }
                        break;
                    }
                }
                if(fl==1)break;
            }

            if(fl==1)
            {
                for(i=0;i<r;i++)
                {
                    for(j=0;j<c;j++)
                    {
                        if(ar[i][j]==1){
                            fl=0;
                            break;
                        }
                    }
                    if(fl==0)break;
                }
                if(fl==0)out.print("NO");
                else out.print("YES");
            }
            else out.print("NO");


        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
        public long nextLong()
        {
            return Long.parseLong(next());
        }

    }
}

