import java.util.Scanner;

public class p1182b {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int h = in.nextInt();
        int w = in.nextInt();
        char[][] grid = new char[h][w];
        int px1 = -1, py1 = -1, px2 = -1, py2 = -1;
        for (int i = 0; i < h; i++) {
            String s = in.next();
            grid[i] = s.toCharArray();
            for (int j = 0; j < w; j++) {
                if (s.charAt(j) == '*') {
                    if (px1 == -1) {
                        px1 = i;
                        py1 = j;
                    } else if (px2 == -1) {
                        if (i != px1 && j != py1) {
                            px2 = i;
                            py2 = j;
                        }
                    }
                }
            }
        }
        if (py2 == -1) {
            System.out.println("NO");
            return;
        }
        int centX = px1;
        int centY = py2;
        if (grid[centX][centY] != '*') {
            centX = px2;
            centY = py1;
        }
        if (grid[centX][centY] != '*' || centX == 0 || centY == 0 || centX == h - 1 || centY == w - 1) {
            System.out.println("NO");
            return;
        }
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (i != centX && j != centY) {
                    if (grid[i][j] == '*') {
                        System.out.println("NO");
                        return;
                    }
                } else if (grid[i][j] == '*') {
                    if (i == centX) {
                        if (j <= centY) {
                            if (grid[i][j + 1] == '.') {
                                System.out.println("NO");
                                return;
                            }
                        }
                        if (j >= centY) {
                            if (grid[i][j - 1] == '.') {
                                System.out.println("NO");
                                return;
                            }
                        }
                    }
                    if (j == centY) {
                        if (i <= centX) {
                            if (grid[i + 1][j] == '.') {
                                System.out.println("NO");
                                return;
                            }
                        }
                        if (i >= centX) {
                            if (grid[i - 1][j] == '.') {
                                System.out.println("NO");
                                return;
                            }
                        }
                    }
                }
            }
        }
        System.out.println("YES");
    }
}

