public class HelloWorld15 {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int w = s.nextInt();
        int h = s.nextInt();
        char[][] arr = new char[w][h];
        for (int i = 0; i < w; i++) {
            String str = s.next();
            arr[i] = str.toCharArray();
        }
        boolean found = false;
        for (int i = 0; i < w; i++) {
            for (int j = 0; j < h; j++) {
                if (arr[i][j] == '*') {
                    if (found) {
                        System.out.println("NO");
                        return;
                    } else {
                        if (checkIfCentre(i, j, arr)) {
                            func(i, j, arr);
                            found = true;
                            break;
                        }
                    }
                }
            }
        }

        for (int i = 0; i < w; i++) {
            for (int j = 0; j < h; j++) {
                if (arr[i][j] == '*') {
                    found = false;
                    break;
                }
            }
        }
        System.out.println(found ? "YES" : "NO");
    }

    private static void func(int i, int j, char[][] arr) {
        int k = i;
        int m = j;
        while (j < arr[0].length && arr[i][j] == '*') {
            arr[i][j] = '.';
            j++;
        }

        j = m - 1;
        while (j >= 0 && arr[i][j] == '*') {
            arr[i][j] = '.';
            j--;
        }

        i = k - 1;
        while (i >= 0 && arr[i][m] == '*') {
            arr[i][m] = '.';
            i--;
        }

        i = k + 1;
        j = m;
        while (i < arr.length && arr[i][j] == '*') {
            arr[i][j] = '.';
            i++;
        }
    }

    private static boolean checkIfCentre(int i, int j, char[][] arr) {
        if (i + 1 >= arr.length || i - 1 < 0 || j + 1 >= arr[0].length || j - 1 < 0) {
            return false;
        }
        return arr[i + 1][j] == '*' && arr[i - 1][j] == '*' &&
               arr[i][j - 1] == '*' && arr[i][j + 1] == '*';
    }
}

