    public static String solver(char[][] ip, int r, int col){
        if(r<3||col<3){
            return "NO";
        }
        int c=-1,cur=0,end=-1,mid=-1,flag=0;
        for (int i=0; i<r; i++) {
            if (cur==1) {
                cur=2;
            }
            for (int j=0; j<col; j++) {
                char ch = ip[i][j];
                if (flag==0&&ch=='*')   flag=1;
                if (cur==0) {
                    if (c==-1 && ch=='*') {
                        c=j;
                        continue;
                    }
                    if (c!=-1) {
                        if (c<j && ch=='*') {
                            return "NO";
                        }
                        if (c>j && ch=='*') {
                            cur=1;
                        }
                        if (j==c && ch!='*')
                            return "NO";
                    }
                }
                if (cur==1) {
                    mid=i;
                    if (ch!='*') {
                        if (j<=c+1) {
                            return "NO";
                        }
                        else if (end==-1) {
                            end=j;
                        }
                    }
                    else if (end!=-1) {
                        return "NO";
                    }
                }
                if (cur==2) {
                    if (ch=='*'&&c!=-1&&j!=c) {
                        return "NO";
                    }
                    if (ch=='.'&&c!=-1&&j==c) {
                        if (mid+1==i)
                            return "NO";
                        else
                            c=-1;
                    }
                    if (c==-1 && ch=='*') {
                        return "NO";
                    }
                }
            }
        }
        if (flag==1 && cur==1)
            return "YES";
        else
            return "NO";
    }
}

