                        posi = i;
                        posj = j;
                    }
                }
            }
            if (posi == -1) {
                out.println("NO");
                return;
            }
            for (int i = posi; i <= n; i++) {
                if (a[i][posj] == '*') {
                    ch[i][posj] = true;
