public class Main {

    private static int h;
    private static int w;
    private static boolean dfsDone;

    public static void main(String[] args) {
        FastReader fr = new FastReader();

        h = fr.nextInt();
        w = fr.nextInt();

        char[][] mat = new char[h][w];
        for (int i = 0; i < h; i++) {
            String in = fr.next();
            mat[i] = in.toCharArray();
        }

        dfsDone = false;
        int i, j;
        for (i = 1; i < h - 1; i++) {
            for (j = 1; j < w - 1; j++) {
                if (mat[i][j] == '*') {
                    if (mat[i - 1][j] == '*' && mat[i + 1][j] == '*' && mat[i][j - 1] == '*' && mat[i][j + 1] == '*') {
                        dfs(mat, i, j);

                        break;
                    }
                }
            }
            if (dfsDone) break;
        }

        if (dfsDone) {
            for (int k = 0; k < h; k++) {
                for (int l = 0; l < w; l++) {
                    if (mat[k][l] == '*') {
                        System.out.println("NO");
                        return;
                    }
                }
            }
        }

        if (dfsDone) System.out.println("YES");
        else System.out.println("NO");
    }

    private static void dfs(char[][] mat, int i, int j) {
        dfsDone = true;
        int x = i, y = j;
        mat[i][j] = '.';
        while (x > 0 && mat[x - 1][y] != '.') {
            mat[x - 1][y] = '.';
            x--;
        }

        x = i; y = j;
        while (x < h - 1 && mat[x + 1][y] != '.') {
            mat[x + 1][y] = '.';
            x++;
        }

        x = i; y = j;
        while (y > 0 && mat[x][y - 1] != '.') {
            mat[x][y - 1] = '.';
            y--;
        }

        x = i; y = j;
        while (y < w - 1 && mat[x][y + 1] != '.') {
            mat[x][y + 1] = '.';
            y++;
        }
    }

    private static void printMat(char[][] mat) {
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                System.out.print(mat[i][j] + " ");
            }
            System.out.println();
        }
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            }
            catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

