        tmppx = px + 1;
        while (tmppx >= 0 && tmppx < h) {
            if (p[tmppx][py]) {
                p[tmppx][py] = false;
                flg = true;
                tmppx++;
            } else {
                break;
            }
        }
        if (!flg) {
            System.out.println("NO");
            return;
        }

        // ---- left direction ----
        flg = false;
        int tmppy = py - 1;
        while (tmppy >= 0 && tmppy < w) {
            if (p[px][tmppy]) {
                p[px][tmppy] = false;
                flg = true;
                tmppy--;
            } else {
                break;
            }
        }
        if (!flg) {
            System.out.println("NO");
            return;
        }

