        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        boolean[][] used = new boolean[n][m];
        char[][] b = new char[n][m];
        boolean found1 = false;
        int indx = 0;
        int indy = 0;
        for (int i = 0; i < n; ++i) {
            char[] c = reader.readLine().toCharArray();
            for (int j = 0; j < c.length; ++j) {
                b[i][j] = c[j];
                if (j > 0 && j < m - 1 && i > 0 && i < n - 1) {
                    if (b[i - 1][j] != '.' && b[i][j - 1] != '.' && b[i][j] == '*') {
                        if (found1) {
                            System.out.println("NO");
                            return;
                        }
                        found1 = true;
                        indx = i;
                        indy = j;
                    }
                }
            }
        }
        if (!found1) {
            System.out.println("NO");
            return;
        }
        int i = indx;
        while (i < n && b[i][indy] == '*') {
            used[i][indy] = true;
            ++i;
        }
        if (i == indx + 1) {
            System.out.println("NO");
            return;
        }
        i = indx;
        while (i >= 0 && b[i][indy] == '*') {
            used[i][indy] = true;
            --i;
        }
        if (i == indx - 1) {
            System.out.println("NO");
            return;
        }
        int j = indy;
        while (j < m && b[indx][j] == '*') {
            used[indx][j] = true;
            ++j;
        }
        if (j == indy + 1) {
            System.out.println("NO");
            return;
        }
        j = indy;
        while (j >= 0 && b[indx][j] == '*') {
            used[indx][j] = true;
            --j;
        }
        if (j == indy - 1) {
            System.out.println("NO");
            return;
        }
        for (int l = 0; l < n; ++l) {
            for (int k = 0; k < m; ++k) {
                if (b[l][k] != '.' && !used[l][k]) {
                    System.out.println("NO");
                    return;
                }
            }
        }
        System.out.println("YES");
    }
}

