            System.out.println("NO");
            return;
        }
        char[][] c = new char[h][w];
        for (int i = 0; i < h; i++) {
            c[i] = scan.next().toCharArray();
        }
        boolean found = false;
        for (int i = 1; i < h - 1; i++){
            for (int j = 1; j < w - 1; j++) {
                if (c[i][j] == '*' && c[i + 1][j] == '*' && c[i - 1][j] == '*' && c[i][j + 1] == '*' && c[i][j - 1] == '*') {
                    found = true;
                    int k = i;
                    c[i][j] = '.';
                    while (k + 1 < h && c[k + 1][j] == '*') {
                        c[k + 1][j] = '.';
                        k++;
                    }
                    k = i;
                    while (k - 1 >= 0 && c[k - 1][j] == '*') {
                        c[k - 1][j] = '.';
                        k--;
                    }
                    // clear right side
                    k = j;
                    while (k + 1 < w && c[i][k + 1] == '*') {
                        c[i][k + 1] = '.';
