import java.io.IOException;
import java.io.InputStream;
import java.util.Arrays;

public class Solution {

    public static void main(String[] args) throws IOException {
        StringBuilder sb = new StringBuilder();
        FastReader in = new FastReader(System.in);
        int r = in.nextInt();
        int c = in.nextInt();
        char[][] arr = new char[r][c];
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                arr[i][j] = in.nextChar();
            }
        }

        int centerRow = -1, centerCol = -1;
        for (int i = 1; i < r - 1; i++) {
            for (int j = 1; j < c - 1; j++) {
                if (arr[i][j] == '*' && arr[i - 1][j] == '*' && arr[i + 1][j] == '*' && arr[i][j - 1] == '*' && arr[i][j + 1] == '*') {
                    centerRow = i;
                    centerCol = j;
                    break;
                }
            }
            if (centerRow != -1) break;
        }

        if (centerRow == -1 || centerCol == -1) {
            System.out.println("NO");
            return;
        }

        boolean[][] valid = new boolean[r][c];
        // mark vertical ray upwards
        for (int i = centerRow; i >= 0; i--) {
            if (arr[i][centerCol] != '*') break;
            valid[i][centerCol] = true;
        }
        // mark vertical ray downwards
        for (int i = centerRow; i < r; i++) {
            if (arr[i][centerCol] != '*') break;
            valid[i][centerCol] = true;
        }
        // mark horizontal ray leftwards
        for (int j = centerCol; j >= 0; j--) {
            if (arr[centerRow][j] != '*') break;
            valid[centerRow][j] = true;
        }
        // mark horizontal ray rightwards
        for (int j = centerCol; j < c; j++) {
            if (arr[centerRow][j] != '*') break;
            valid[centerRow][j] = true;
        }

        // verify that every '*' is part of the cross
        boolean allStarsMarked = true;
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                if (arr[i][j] == '*' && !valid[i][j]) {
                    allStarsMarked = false;
                    break;
                }
            }
            if (!allStarsMarked) break;
        }

        // also ensure we found exactly one center
        System.out.println(allStarsMarked ? "YES" : "NO");
    }
}

class FastReader {

    byte[] buf = new byte[2048];
    int index, total;
    InputStream in;

    FastReader(InputStream is) {
        in = is;
    }

    int scan() throws IOException {
        if (index >= total) {
            index = 0;
            total = in.read(buf);
            if (total <= 0) {
                return -1;
            }
        }
        return buf[index++];
    }

    String next() throws IOException {
        int c;
        for (c = scan(); c <= 32; c = scan()) ;
        StringBuilder sb = new StringBuilder();
        for (; c > 32; c = scan()) {
            sb.append((char) c);
        }
        return sb.toString();
    }

    String nextLine() throws IOException {
        int c;
        for (c = scan(); c <= 32; c = scan()) ;
        StringBuilder sb = new StringBuilder();
        for (; c != 10 && c != 13; c = scan()) {
            sb.append((char) c);
        }
        return sb.toString();
    }

    char nextChar() throws IOException {
        int c;
        for (c = scan(); c <= 32; c = scan()) ;
        return (char) c;
    }

    int nextInt() throws IOException {
        int c, val = 0;
        for (c = scan(); c <= 32; c = scan()) ;
        boolean neg = c == '-';
        if (c == '-' || c == '+') {
            c = scan();
        }
        for (; c >= '0' && c <= '9'; c = scan()) {
            val = (val << 3) + (val << 1) + (c & 15);
        }
        return neg ? -val : val;
    }

    long nextLong() throws IOException {
        int c;
        long val = 0;
        for (c = scan(); c <= 32; c = scan()) ;
        boolean neg = c == '-';
        if (c == '-' || c == '+') {
            c = scan();
        }
        for (; c >= '0' && c <= '9'; c = scan()) {
            val = (val << 3) + (val << 1) + (c & 15);
        }
        return neg ? -val : val;
    }
}

