				if (grid[j][i]==1) break;
				if (j==n-1) init++;
			}
		}
		int max = 0;
		for (int i=0; i<n-k+1; i++) {
			for (int j=0; j<n-k+1; j++) {

				if (psums[i][j]+psums2[i][j]>max) max = psums[i][j]+psums2[i][j];
