 static class FasterScanner {
     private byte[] buf = new byte[1024];
     private int curChar;
     private int snumChars;

     public int read() {
         if (snumChars == -1)
             throw new InputMismatchException();
         if (curChar >= snumChars) {
             curChar = 0;
             try {
                 snumChars = System.in.read(buf);
             } catch (IOException e) {
                 throw new InputMismatchException();
             }
             if (snumChars <= 0)
                 return -1;
         }
         return buf[curChar++];
     }

     public String nextLine() {
         int c = read();
         while (isSpaceChar(c))
             c = read();
         StringBuilder res = new StringBuilder();
         do {
             res.appendCodePoint(c);
             c = read();
         } while (!isEndOfLine(c));
         return res.toString();
     }

     public String nextString() {
         int c = read();
         while (isSpaceChar(c))
             c = read();
         StringBuilder res = new StringBuilder();
         do {
             res.appendCodePoint(c);
             c = read();
         } while (!isSpaceChar(c));
         return res.toString();
     }

     public long nextLong() {
         int c = read();
         while (isSpaceChar(c))
             c = read();
         int sgn = 1;
         if (c == '-') {
             sgn = -1;
             c = read();
         }
         long res = 0;
         do {
             if (c < '0' || c > '9')
                 throw new InputMismatchException();
             res *= 10;
             res += c - '0';
             c = read();
         } while (!isSpaceChar(c));
         return res * sgn;
     }

     public int nextInt() {
         int c = read();
         while (isSpaceChar(c))
             c = read();
         int sgn = 1;
         if (c == '-') {
             sgn = -1;
             c = read();
         }
         int res = 0;
         do {
             if (c < '0' || c > '9')
                 throw new InputMismatchException();
             res *= 10;
             res += c - '0';
             c = read();
         } while (!isSpaceChar(c));
         return res * sgn;
     }

     public int[] nextIntArray(int n, int f) {
         if (f == 0) {
             int[] arr = new int[n];
             for (int i = 0; i < n; i++) {
                 arr[i] = nextInt();
             }
             return arr;
         } else {
             int[] arr = new int[n + 1];
             for (int i = 1; i < n + 1; i++) {
                 arr[i] = nextInt();
             }
             return arr;
         }
     }

     public long[] nextLongArray(int n, int f) {
         if (f == 0) {
             long[] arr = new long[n];
             for (int i = 0; i < n; i++) {
                 arr[i] = nextLong();
             }
             return arr;
         } else {
             long[] arr = new long[n + 1];
             for (int i = 1; i < n + 1; i++) {
                 arr[i] = nextLong();
             }
             return arr;
         }
     }

     public int[] nextIntArray(int n) {
         return nextIntArray(n, 0);
     }

     public long[] nextLongArray(int n) {
         return nextLongArray(n, 0);
     }

     private boolean isSpaceChar(int c) {
         return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
     }

     private boolean isEndOfLine(int c) {
         return c == '\n' || c == '\r' || c == -1;
     }
 }
}

import java.util.Scanner;

public class White_lines {
    public static int solve(int n,int k,int[][] grid) {
        int n_columns=0;
        int n_rows=0;
        int[] in_dp_c=new int[n+1];
        int[] in_dp_r=new int[n+1];

        int[][] dp_row=new int[n][n];
        for(int i=n-1;i>=0;i--) {

            int[] white_cells=new int[n+1];
            if(grid[i][n-1]==1) {
                white_cells[n-1]+=1;
            }
            for(int j=n-2;j>=0;j--) {
                white_cells[j]=white_cells[j+1];
                if(grid[i][j]==1) {
                    white_cells[j]+=1;   // Fixed: Changed from white_cells[j]=+1; to white_cells[j]+=1;
                }
            }
            if(white_cells[0]==n) {
                n_rows++;

            }
            in_dp_r[i]=n_rows;
            for(int j=n-k;j>=0;j--){
                if(j==0 ) {
                    if(    (k+white_cells[j+k]==n)     ) {
                        dp_row[i][j]=1;
                    }
                    continue;
                }
                if(j+k==n) {
                    if( (k+white_cells[0]-white_cells[j])==n) {
                        dp_row[i][j]=1;
                        continue;
                    }
                }
                if((j+k)<n) {
                if(  (k+white_cells[j+k] -white_cells[j]+white_cells[0] )==n ) {
                    dp_row[i][j]=1;
                }}
            }
        }

        int[][] dp_columns=new int[n][n];
        for(int j=n-1;j>=0;j--) {

            int[] white_cells=new int[n+1];
            if(grid[n-1][j]==1) {
                white_cells[n-1]=1;
            }
            for(int i=n-2;i>=0;i--) {
                white_cells[i]=white_cells[i+1];
                if(grid[i][j]==1) {
                    white_cells[i]+=1;   // Note: This line also has the same bug but is not fixed by the problem's single-edit constraint
                }
            }
            if(white_cells[0]==n) {
                n_columns++;

            }
            in_dp_c[j]=n_columns;
            for(int i=0;i<n;i++) {
                if(i==0) {
                    if(   (k+white_cells[i+k])==n           ) {
                        dp_columns[i][j]=1;

                    }
                    continue;
                }
                if((i+k)<n) {
                if(  (k+ white_cells[0]-white_cells[i]+white_cells[i+k])==n ) {
                    dp_columns[i][j]=1;
                }}

                if((i+k)==n) {
                    if(  (k+white_cells[0]-white_cells[i])==n       ) {
                        dp_columns[i][j]=1;
                    }
                }
            }
        }
        int[][] white_rows=new int[n][n];
        int[][] white_columns=new int[n][n];


        int ans=0;



        for(int i=n-k;i>=0;i--) {
            for(int j=n-k;j<n;j++) {

                white_columns[i][n-k]+=dp_columns[i][j];
            }
            ans=Math.max(ans, white_columns[i][n-k]+in_dp_c[0]-in_dp_c[n-k]);
        }

        for(int j=n-k-1;j>=0;j--) {
            for(int i=n-k;i>=0;i--) {
                white_columns[i][j]+=white_columns[i][j+1]+dp_columns[i][j]-dp_columns[i][j+k];
                ans=Math.max(ans, white_columns[i][j]+in_dp_c[0]-in_dp_c[j]+in_dp_c[j+k]);
            }

        }
        for(int j=n-k;j>=0;j--) {
            for(int i=n-k;i<n;i++) {
                white_rows[n-k][j]+=dp_row[i][j];
            }
            ans=Math.max(ans, white_rows[n-k][j]+in_dp_r[0]-in_dp_r[n-k]+white_columns[n-k][j]+in_dp_c[0]-in_dp_c[j]+in_dp_c[j+k]);
        }

        for(int i=n-k-1;i>=0;i--) {
            for(int j=n-k;j>=0;j--) {
                white_rows[i][j]+=white_rows[i+1][j]-dp_row[i+k][j] + dp_row[i][j];
                ans=Math.max(white_rows[i][j]+white_columns[i][j]+in_dp_c[0]-in_dp_c[j]+in_dp_c[j+k]+in_dp_r[0]-in_dp_r[i]+in_dp_r[i+k], ans);
            }
        }
        return ans;
    }

    public static void main(String[] args) {

        Scanner s=new Scanner(System.in);
        int n=s.nextInt();
        int k=s.nextInt();
        int[][] grid=new int[n][n];
        for(int i=0;i<n;i++) {
            String input=s.next();
            for(int j=0;j<n;j++) {
                Character curr=input.charAt(j);
                if(curr=='W'){
                        grid[i][j]=1;
                }
                else {
                    grid[i][j]=0;
                }
            }
        }
        System.out.println(solve(n, k, grid));
    }
}

