            for (int j = 0; j < n; j++) {
                a[k + i][k + j] = (s.charAt(j) == 'B');
            }
        }

        int[][] r = new int[k + n][2];
        int[][] c = new int[k + n][2];
        for (int i = 0; i < k + n; i++) {
            int start, end;

