            for (int j = 0; j < k + n; j++) {
                if (a[i][j]) {
                    if (start == -1)
                        start = j;
                    end = j;
                }
            }
            r[i][0] = start;
            r[i][1] = end;

            start = end = -1;
            for (int j = 0; j < k + n; j++) {
                if (a[j][i]) {
                    if (start == -1)
                        start = j;
                    end = j;
                }
            }
            c[i][0] = start;
            c[i][1] = end;
        }

        int[][] dpr = new int[k + n][k + n];
        int[][] dpc = new int[k + n][k + n];

        int ans = 0;
        for (int i = 1; i < n + 1; i++) {
            for (int j = 1; j < n + 1; j++) {
                dpr[i][j] = dpr[i - 1][j];

                if (j <= r[i - 1][0] && r[i - 1][1] < j + k)
                    dpr[i][j]--;
                if (j <= r[k + i - 1][0] && r[k + i - 1][1] < j + k)
                    dpr[i][j]++;

                dpc[i][j] = dpc[i][j - 1];

                if (i <= c[j - 1][0] && c[j - 1][1] < i + k)
                    dpc[i][j]--;
                if (i <= c[k + j - 1][0] && c[k + j - 1][1] <  i + k)
                    dpc[i][j]++;

                ans = Math.max(ans, dpr[i][j] + dpc[i][j]);
            }
        }

        for (int i = k; i < k + n; i++) {
            if (r[i][0] == -1)
                ans++;
            if (c[i][0] == -1)
                ans++;
        }

        out.println(ans);

        out.close();
    }

