import java.util.Scanner;

public class DWhiteLines {

    public static void main(String []args){

        Scanner in = new Scanner(System.in);

        int n = in.nextInt();
        int k = in.nextInt();
        in.nextLine();
        char [][] board = new char[n][n];
        for(int i = 0; i < n; i++){
            String s = in.nextLine();
            board[i] = s.toCharArray();
        }

        int l[] = new int[n];
        int r[] = new int[n];
        int t[] = new int[n];
        int b[] = new int[n];

        for(int i = 0; i < n; i++){
            l[i] = 2001;
            r[i] = -1;
            t[i] = 1;
            b[i] = -1;
        }

        int whiteRows = 0;
        int whiteColumns = 0;
        for(int i = 0; i < n; i++){
            boolean isWhiteRow = true;
            boolean isWhiteColumn = true;
            for(int j = 0; j < n; j++){
                if(board[i][j] == 'B'){
                    l[i] = Math.min(l[i], j);
                    r[i] = Math.max(r[i], j);
                    isWhiteRow = false;
                }

                if(board[j][i] == 'B'){
                    t[i] = Math.min(t[i], j);
                    b[i] = Math.max(b[i], j);
                    isWhiteColumn = false;
                }
            }
            if(isWhiteRow) whiteRows++;
            if(isWhiteColumn) whiteColumns++;
        }

        int max = 0;
        int dpr[][] = new int[n - k + 1][n - k + 1];
        int dpc[][] = new int[n - k + 1][n - k + 1];
        for(int j = 0; j <= n - k; j++){
            for(int z = 0; z <=  k - 1; z++){
                if(l[z] != 2001 && l[z] >= j && r[z] <= j + k - 1){
                    dpr[0][j]++;
                }

                if(t[z] != 2001 && t[z] >= j && b[z] <= j + k - 1){
                    dpc[j][0]++;
                }
            }

        }

        for(int i = 1; i <= n - k; i++){
            for(int j = 0; j <= n - k; j++){
                dpr[i][j] = dpr[i - 1][j];
                dpc[j][i] = dpc[j][i - 1];
                if(l[i - 1] != 2001 && l[i - 1] >= j && r[i - 1] <= j + k - 1){
                    dpr[i][j]--;
                }

                if(l[i + k - 1]!= 2001 && l[i + k - 1] >= j && r[i + k - 1] <= j + k - 1){
                    dpr[i][j]++;
                }

                if(t[i - 1] != 2001 && t[i - 1] >= j && b[i - 1] <= j + k - 1){
                    dpc[j][i]--;
                }

                if(t[i + k - 1] != 2001 && t[i + k - 1] >= j && b[i + k - 1] <= j + k -1){
                    dpc[j][i]++;
                }
            }
        }

        for (int i = 0; i <= n - k; i++){
            for(int j = 0; j <= n - k; j++){
                max = Math.max(max, dpr[i][j] + dpc[j][i]);
            }
        }

        System.out.println(max + whiteRows + whiteColumns);

    }
}

