public class Main {
    static class FastScanner
    { 
        BufferedReader br; 
        StringTokenizer st; 

        public FastScanner() 
        { 
            br = new BufferedReader(new
                     InputStreamReader(System.in)); 
        } 

        String next() 
        { 
            while (st == null || !st.hasMoreElements()) 
            { 
                try
                { 
                    st = new StringTokenizer(br.readLine()); 
                } 
                catch (IOException  e) 
                { 
                    e.printStackTrace(); 
                } 
            } 
            return st.nextToken(); 
        } 

        int nextInt() 
        { 
            return Integer.parseInt(next()); 
        } 

        long nextLong() 
        { 
            return Long.parseLong(next()); 
        } 

        double nextDouble() 
        { 
            return Double.parseDouble(next()); 
        } 

        String nextLine() 
        { 
            String str = ""; 
            try
            { 
                str = br.readLine(); 
            } 
            catch (IOException e) 
            { 
                e.printStackTrace(); 
            } 
            return str; 
        } 
    } 

    public static void main(String[] args) throws IOException 
    { 
        FastScanner sc=new FastScanner();
        int N = sc.nextInt();
        int K = sc.nextInt();
        int[][] grid = new int[N][N];
        int WL = 0;
        for (int i = 0; i < N; i++) {
        	String s = sc.next();
        	for (int j = 0; j < N; j++) {
        		char c = s.charAt(j);
        		if (c == 'B') {
        			grid[i][j] = 1;
        		} else {
        			grid[i][j] = 0;
        		}
        	}
        }

        int[][] rowSum = new int[N][N+1];
        for (int i = 0; i < N; i++) {
        	for (int j = 1; j <= N; j++) {
        		rowSum[i][j] = rowSum[i][j-1] + grid[i][j-1];
        	}
        }
        int[][] cumRow = new int[N+1][N-K+1];
        for (int i = 1; i <= N; i++) {
        	int max = rowSum[i-1][N];
        	if (max == 0)
        		WL++;
        	for (int j = 0; j < N-K+1; j++) {
        		if (max > 0 && rowSum[i-1][j+K]-rowSum[i-1][j] == max) {
        			cumRow[i][j] = cumRow[i-1][j] + 1;
        		} else {
        			cumRow[i][j] = cumRow[i-1][j];
        		}
        	}
        }
        int[][] rowWL = new int[N-K+1][N-K+1];
        for (int i = 0; i < N-K+1; i++) {
        	for (int j = 0; j < N-K+1; j++) {
        		rowWL[i][j] = cumRow[K+i][j] - cumRow[i][j];
        	}
        }

        int[][] colSum = new int[N+1][N];
        for (int i = 1; i <= N; i++) {
        	for (int j = 0; j < N; j++) {
        		colSum[i][j] = colSum[i-1][j] + grid[i-1][j];
        	}
        }
        int[][] cumCol = new int[N-K+1][N+1];
        for (int j = 1; j <= N; j++) {
        	int max = colSum[N][j-1];
        	if (max == 0)
        		WL++;
        	for (int i = 0; i < N-K+1; i++) {
        		if (max > 0 && colSum[i+K][j-1] - colSum[i][j-1] == max) {
        			cumCol[i][j] = cumCol[i][j-1] + 1;
        		} else {
        			cumCol[i][j] = cumCol[i][j-1];
        		}
        	}
        }
        int[][] colWL = new int[N-K+1][N-K+1];
        for (int i = 0; i < N-K+1; i++) {
        	for (int j = 0; j < N-K+1; j++) {
        		colWL[i][j] = cumCol[i][j+K] - cumCol[i][j];
        	}
        }
        int maxWL = 0;
        for (int i = 0; i < N-K+1; i++) {
        	for (int j = 0; j < N-K+1; j++) {
        		maxWL = Math.max(maxWL,rowWL[i][j] + colWL[i][j]);
        	}
        }
        System.out.println(maxWL+WL);
    }
}

