import java.util.*;
import java.io.*;
import java.math.*;
public class Solution{
    public static void main(String[] args)throws IOException{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int[] rmin = new int[n];
        int[] rmax = new int[n];
        int[] cmin = new int[n];
        int[] cmax = new int[n];
        Arrays.fill(rmin,-1);
        Arrays.fill(rmax,-1);
        Arrays.fill(cmin,-1);
        Arrays.fill(cmax,-1);
        for(int i=0;i<n;i++){
            st = new StringTokenizer(br.readLine());
            char[] c = st.nextToken().toCharArray();
            for(int j=0;j<n;j++){
                if(c[j]=='B'){
                    if (rmin[i]==-1 || j < rmin[i]) rmin[i] = j;
                    if(cmin[j]==-1) cmin[j] = i;
                    rmax[i] = j;
                    cmax[j] = i;
                }
            }
        }
        int res = 0;
        for(int i=0;i<n;i++){
            if(rmin[i]==-1) res++;
            else if(rmax[i]-rmin[i]+1>k){
                rmax[i] = -1;
                rmin[i] = -1;
            }
            if(cmin[i]==-1) res++;
            else if(cmax[i]-cmin[i]+1>k){
                cmax[i] = -1;
                cmin[i] = -1;
            }
        }
        int[][] srmin = new int[n][n];
        int[][] srmax = new int[n][n];
        int[][] scmin = new int[n][n];
        int[][] scmax = new int[n][n];
        for(int i=0;i<n;i++){
            if(rmin[i]!=-1) srmin[i][rmin[i]] = 1;
            if(rmax[i]!=-1) srmax[i][rmax[i]] = 1;
            if(cmin[i]!=-1) scmin[cmin[i]][i] = 1;
            if(cmax[i]!=-1) scmax[cmax[i]][i] = 1;
        }
        for(int i=0;i<n;i++){
            for(int j=1;j<n;j++){
                srmin[j][i] += srmin[j-1][i];
                srmax[j][i] += srmax[j-1][i];
                scmin[i][j] += scmin[i][j-1];
                scmax[i][j] += scmax[i][j-1];
            }
        }
        int[][] dp = new int[n-k+1][n-k+1];
        for(int i=0;i<k;i++){
            dp[0][0] += srmax[k-1][i];
            dp[0][0] += scmax[i][k-1];
        }
        for(int i=0;i<n-k+1;i++){
            for(int j=0;j<n-k+1;j++){
                if(i==0&&j==0) continue;
                if(j==0){
                    dp[i][j] = dp[i-1][j];
                    dp[i][j] += scmax[i+k-1][j+k-1];
                    dp[i][j] -= scmin[i-1][j+k-1];
                    if(rmin[i-1]>=j&&rmax[i-1]<j+k) dp[i][j]--;
                    if(rmin[i+k-1]>=j&&rmax[i+k-1]<j+k) dp[i][j]++;
                }else{
                    dp[i][j] = dp[i][j-1];
                    dp[i][j] += srmax[i+k-1][j+k-1];
                    if(i>0) dp[i][j] -= srmax[i-1][j+k-1];
                    dp[i][j] -= srmin[i+k-1][j-1];
                    if(i>0) dp[i][j] += srmin[i-1][j-1];
                    if(cmin[j-1]>=i&&cmax[j-1]<i+k) dp[i][j]--;
                    if(cmin[j+k-1]>=i&&cmax[j+k-1]<i+k) dp[i][j]++;
                }
            }
        }

        int max = 0;
        for(int i=0;i<=n-k;i++){
            for(int j=0;j<=n-k;j++){
                max = Math.max(max,dp[i][j]);

            }
        }

        res += max;
        out.println(res);
        out.flush(); 
    }
}

import java.util.*;
import java.io.*;
import java.math.*;
public class Solution{
    public static void main(String[] args)throws IOException{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int[] rmin = new int[n];
        int[] rmax = new int[n];
        int[] cmin = new int[n];
        int[] cmax = new int[n];
        Arrays.fill(rmin,-1);
        Arrays.fill(rmax,-1);
        Arrays.fill(cmin,-1);
        Arrays.fill(cmax,-1);
        for(int i=0;i<n;i++){
            st = new StringTokenizer(br.readLine());
            char[] c = st.nextToken().toCharArray();
            for(int j=0;j<n;j++){
                if(c[j]=='B'){
                    if(rmin[i]==-1) rmin[i] = j;
                    if(cmin[j]==-1) cmin[j] = i;
                    rmax[i] = j;
                    cmax[j] = i;
                }
            }
        }
        int res = 0;
        for(int i=0;i<n;i++){
            if(rmin[i]==-1) res++;
            else if(rmax[i]-rmin[i]+1>k){
                rmax[i] = -1;
                rmin[i] = -1;
            }
            if(cmin[i]==-1) res++;
            else if(cmax[i]-cmin[i]+1>k){
                cmax[i] = -1;
                cmin[i] = -1;
            }
        }
        int[][] srmin = new int[n][n];
        int[][] srmax = new int[n][n];
        int[][] scmin = new int[n][n];
        int[][] scmax = new int[n][n];
        for(int i=0;i<n;i++){
            if(rmin[i]!=-1) srmin[i][rmin[i]] = 1;
            if(rmax[i]!=-1) srmax[i][rmax[i]] = 1;
            if(cmin[i]!=-1) scmin[cmin[i]][i] = 1;
            if(cmax[i]!=-1) scmax[cmax[i]][i] = 1;
        }
        for(int i=0;i<n;i++){
            for(int j=1;j<n;j++){
                srmin[j][i] += srmin[j-1][i];
                srmax[j][i] += srmax[j-1][i];
                scmin[i][j] += scmin[i][j-1];
                scmax[i][j] += scmax[i][j-1];
            }
        }
        int[][] dp = new int[n-k+1][n-k+1];
        for(int i=0;i<k;i++){
            dp[0][0] += srmax[k-1][i];
            dp[0][0] += scmax[i][k-1];
        }
        for(int i=0;i<n-k+1;i++){
            for(int j=0;j<n-k+1;j++){
                if(i==0&&j==0) continue;
                if(j==0){
                    dp[i][j] = dp[i-1][j];
                    dp[i][j] += scmax[i+k-1][j+k-1];
                    dp[i][j] -= scmin[i-1][j+k-1];
                    if(rmin[i-1]>=j&&rmax[i-1]<j+k) dp[i][j]--;
                    if(rmin[i+k-1]>=j&&rmax[i+k-1]<j+k) dp[i][j]++;
                }else{
                    dp[i][j] = dp[i][j-1];
                    dp[i][j] += srmax[i+k-1][j+k-1];
                    if(i>0) dp[i][j] -= srmax[i-1][j+k-1];
                    dp[i][j] -= srmin[i+k-1][j-1];
                    if(i>0) dp[i][j] += srmin[i-1][j-1];
                    if(cmin[j-1]>=i&&cmax[j-1]<i+k) dp[i][j]--;
                    if(cmin[j+k-1]>=i&&cmax[j+k-1]<i+k) dp[i][j]++;
                }
            }
        }

        int max = 0;
        for(int i=0;i<=n-k;i++){
            for(int j=0;j<=n-k;j++){
                max = Math.max(max,dp[i][j]);

            }
        }

        res += max;
        out.println(res);
        out.flush(); 
    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
