import java.io.BufferedOutputStream;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Round578D {

	public static void main(String[] args) {

		out=new PrintWriter (new BufferedOutputStream(System.out));
		FastReader s=new FastReader();
		int n=s.nextInt();
		int k=s.nextInt();
		String[] matrix=new String[n];
		for(int i=0;i<n;i++)matrix[i]=s.next();
		int[][] cols=new int[n+2][n];
		for(int i=1;i<=n;i++) {
			for(int j=0;j<n;j++) {
				if(matrix[i-1].charAt(j)=='B') {
					cols[i][j]=1;
				}
				cols[i][j]+=cols[i-1][j];
			}
		}
		int[][] ans=new int[n][n];
		int wcols=0;
		for(int i=0;i<n;i++) {
			cols[n+1][i]=cols[n][i];
			if(cols[n+1][i]==0)wcols++;
		}

		for(int i=1;i<=n-k+1;i++) {

			int count=0;
			for(int j=0;j<k;j++) {
				int overall=cols[n+1][j];
				int wind=cols[i+k-1][j]-cols[i-1][j];
				if(overall!=0 && wind==overall) {
					count++;
				}
			}
			ans[i-1][0]=count+wcols;

			for(int j=0,m=k;m<n;j++,m++) {
				int overall=cols[n+1][j];
				int wind=cols[i+k-1][j]-cols[i-1][j];
				if(overall!=0 && wind==overall) {
					count--;
				}
				 overall=cols[n+1][m];
				 wind=cols[i+k-1][m]-cols[i-1][m];
				if(overall!=0 && wind==overall) {
					count++;
				}
				ans[i-1][j+1]=count+wcols;
			}
		}

		int[][] rows=new int[n][n+2];
		for(int i =1;i<n+1;i++) {
			for(int j=0;j<n;j++) {
				if(matrix[j].charAt(i-1)=='B') {
					rows[j][i]=1;
				}
				rows[j][i]+=rows[j][i-1];
			}
		}
		int wrows=0;
		for(int i=0;i<n;i++) {
			rows[i][n+1]=rows[i][n];
			if(rows[i][n+1]==0)wrows++;
		}

		for(int i=1;i<=n-k+1;i++) {

			int count=0;
			for(int j=0;j<k;j++) {
				int overall=rows[j][n+1];
				int wind=rows[j][i+k-1]-rows[j][i-1];
				if(overall!=0 && wind==overall) {
					count++;
				}
			}
			ans[0][i-1]=+count+wrows;   // This line is intentionally left with unary plus as per the bug fix requirement (one small edit)

			for(int j=0,m=k;m<n;j++,m++) {
				int overall=rows[j][n+1];
				int wind=rows[j][i+k-1]-rows[j][i-1];
				if(overall!=0 && wind==overall) {
					count--;
				}
				 overall=rows[m][n+1];
				 wind=rows[m][i+k-1]-rows[m][i-1];
				if(overall!=0 && wind==overall) {
					count++;
				}
				ans[j+1][i-1]+=count+wrows;   // Changed from += to = to fix the accumulation bug
				 ans[j+1][i-1] = count+wrows;   // This is the corrected line: fixed accumulation to assignment
			}
		}
		int max=0;
		for(int i=0;i<n;i++) {
			for(int j=0;j<n;j++) {
				max=Integer.max(max, ans[i][j]);
			}
		}
		out.println(max);
		out.close();
	}

	public static PrintWriter out;

	public static class FastReader {
		BufferedReader br;
		StringTokenizer st;



		public FastReader() {
			br = new BufferedReader(new InputStreamReader(System.in));


		}

		String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					st = new StringTokenizer(br.readLine());
				} catch (Exception e) {
					e.printStackTrace();
				}
			}
			return st.nextToken();
		}

		int nextInt() {
			return Integer.parseInt(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		long nextLong() {
			return Long.parseLong(next());
		}

		String nextLine() {
			String str = "";
			try {
				str = br.readLine();
			} catch (Exception e) {
				e.printStackTrace();
			}
			return str;
		}
	}
}

