		boolean[][] a = new boolean[N][N];
		for (int i = 0; i < N; i++) {
			String s2 = br.readLine();
			for (int j = 0; j < N; j++) {
				if(s2.charAt(j)=='W') a[i][j]=true;
			}
		}
		int r[][] = new int[N][2];
		int c[][] = new int[N][2];
		for (int i = 0; i < N; i++) {
			r[i][0]=-1;
			c[i][0]=-1;
		}
		for (int i = 0; i < N; i++) {
			for (int j = 0; j < N; j++) {
				if(!a[i][j]) {
					r[i][1] = j;
					if(r[i][0]==-1) r[i][0]=j;
					c[j][1] = i;
					if(c[j][0]==-1) c[j][0]=i;
				}
			}
		}
		int w = 0;
		for(int i=N-1;i>=0;i--) {
			if(r[i][0]==-1) w++;;
