				row[i][j] += row[i+1][j];
			}
		}
		Integer max = 0;
		for(int i=N-k;i>=0;i--) {
			for(int j=N-k;j>=0;j--) {
				int v = col[i][j]+row[i][j];
				if((i+k)<N) {
					v-= row[i+k][j];
				}
				if((j+k)<N) {
					v-= col[i][j+k];
				}
				max = Math.max(max, v);
			}
		}
		System.out.println((max+w));
	}

