public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        DWhiteLines solver = new DWhiteLines();
        solver.solve(1, in, out);
        out.close();
    }

    static class DWhiteLines {
        public void solve(int testNumber, InputReader s, PrintWriter w) {
            int n = s.nextInt(), k = s.nextInt();
            char[][] a = new char[n + 1][];
            for (int i = 1; i <= n; i++)
                a[i] = (" " + s.next()).toCharArray();
            int[][] rpre = new int[n + 1][n + 1];
            int[] rsub = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    rpre[i][j] = rpre[i][j - 1] + (a[i][j] == 'B' ? 1 : 0);
                }
                rsub[i] = rsub[i - 1];
                if (rpre[i][n] > 0)
                    rsub[i]++;
            }
            int[][] cpre = new int[n + 1][n + 1];
            int[] csub = new int[n + 1];
            for (int j = 1; j <= n; j++) {
                for (int i = 1; i <= n; i++) {
                    cpre[i][j] = cpre[i - 1][j] + (a[i][j] == 'B' ? 1 : 0);
                }
                csub[j] = csub[j - 1];
                if (cpre[n][j] > 0)
                    csub[j]++;
            }
            int[][] rdp = new int[n + 1][n + 1];
            for (int j = k; j <= n; j++) {
                int curr = 0;
                for (int i = 1; i <= k; i++) {
                    if (rpre[i][j] - rpre[i][j - k] != rpre[i][n])
                        curr++;
                }
                rdp[k][j] = curr;
                for (int i = k + 1; i <= n; i++) {
                    rdp[i][j] = rdp[i - 1][j] + (rpre[i][j] - rpre[i][j - k] != rpre[i][n] ? 1 : 0)
                            - (rpre[i - k][j] - rpre[i - k][j - k] != rpre[i - k][n] ? 1 : 0);
                }
            }

            int[][] cdp = new int[n + 1][n + 1];
            for (int i = k; i <= n; i++) {
                int curr = 0;
                for (int j = 1; j <= k; j++) {
                    if (cpre[i][j] - cpre[i - k][j] != cpre[n][j])
                        curr++;
                }
                cdp[i][k] = curr;
                for (int j = k + 1; j <= n; j++) {
                    cdp[i][j] = cdp[i][j - 1] + (cpre[i][j] - cpre[i - k][j] != cpre[n][j] ? 1 : 0)
                            - (cpre[i][j - k] - cpre[i - k][j - k] != cpre[n][j - k] ? 1 : 0);
                }
            }
            long res = 0;
            for (int i = k; i <= n; i++) {
                for (int j = k; j <= n; j++) {
                    res = Math.max(n - rdp[i][j] - (rsub[n] - rsub[i] + rsub[i - k]) + n - cdp[i][j] - (csub[n] - csub[j] + csub[j - k]), res);
                }
            }
            w.println(res);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public String next() {
            return nextString();
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

