public class F {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(reader.readLine());
        int n  = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int[] lx = new int[n];
        int[] rx = new int[n];
        int[] ly = new int[n];
        int[] ry = new int[n];
        for(int i = 0; i < n; ++i){
            lx[i] = rx[i] = ly[i] = ry[i] = -1;
        }
        for(int i = 0; i < n; ++i){
            char[] b = reader.readLine().toCharArray();
            for(int j = 0; j < n; ++j){
                if(b[j] == 'B'){
                    if(lx[i] == -1 || lx[i] > j) {
                        lx[i] = j;
                    }
                    rx[i] = Math.max(rx[i], j);
                    if(ly[j] == -1 || ly[j] > i) {
                        ly[j] = i;
                    }
                    ry[j] = Math.max(ry[j], i);
                }
            }
        }
        int ans = 0;
        int max = 0;
        for(int i = 0; i < n; ++i){
            if(lx[i] == -1){
                ++ans;
            }
            if(ly[i] == -1){
                ++ans;
            }
        }
        for(int i = 0; i < n - k + 1; ++ i){
            TreeMap<Integer, Integer> lefts = new TreeMap<>();
            TreeMap<Integer, Integer> rights = new TreeMap<>();
            int strs = 0;
            TreeSet<Integer> stolbs = new TreeSet<>();
            for(int j = i; j < i + k; ++j){
                if(lx[j] != -1 && rx[j] - lx[j] < k){
                    lefts.put(lx[j], lefts.getOrDefault(lx[j], 0) + 1);
                    rights.put(rx[j], rights.getOrDefault(rx[j], 0) + 1);
                    if(rx[j] <= k - 1){
                        ++strs;
                    }
                }
            }
            for(int j = 0; j < k; ++j){
                if(ry[j] < i + k && ly[j] >= i){
                    stolbs.add(j);
                }
            }
            max = Math.max(max, stolbs.size() + strs + ans);
            for(int j = k; j < n; ++j){
                stolbs.remove(j - k);
                strs -= lefts.getOrDefault(j - k, 0);
                strs += rights.getOrDefault(j, 0);
                if(ry[j] < i + k && ly[j] >= i){
                    stolbs.add(j);
                }
                max = Math.max(max, stolbs.size() + strs + ans);
            }
        }
        System.out.println(max);
        writer.close();
    }
}

