                if (columnHasBlack[x - 1] && ly[x - 1] <= y && y <= ry[x - 1]) {
                    curr--;
                }
                if (columnHasBlack[x + k - 1] && ly[x + k - 1] <= y && y <= ry[x + k - 1]) {
                    curr++;
                }

                answer = Math.max(answer, curr);
            }
        }
        System.out.println(answer);
    }
}

