            ans[Math.max(down[i] - k + 1, 0)][Math.max(i - k + 1, 0)]++;
            ans[up[i] + 1][Math.max(i - k + 1, 0)]--;
            ans[Math.max(down[i] - k + 1, 0)][i + 1]--;
            ans[up[i] + 1][i + 1]++;
        }

        for (int i = 0; i < n; i++) {
            if (left[i] == -1) {
                ans[0][0]++;
                ans[0][n]--;
                ans[n][0]--;
                ans[n][n]++;
                continue;
            } else if (right[i] - left[i] + 1 > k) continue;
            ans[Math.max(i - k + 1, 0)][Math.max(right[i] - k + 1, 0)]++;
