import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader sc = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Task solver = new Task();
        solver.solve(1, sc, out);
        out.close();
    }

    static class Task {
        public void solve(int testNumber, InputReader sc, PrintWriter out) {
            int n = sc.nextInt();
            int k = sc.nextInt();
            int[] preRow = new int[n+1];     
            int[] sufRow = new int[n+1];
            int[] preCol = new int[n+1];
            int[] sufCol = new int[n+1];
            Arrays.fill(preRow, Integer.MAX_VALUE);
            Arrays.fill(preCol, Integer.MAX_VALUE);
            Arrays.fill(sufCol, 0);
            Arrays.fill(sufCol, 0);

            char[][] res = new char[n+1][n+1];
            for (int i = 1; i <= n; i++) 
                res[i] = (" " + sc.next()).toCharArray();
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    if (res[i][j] == 'B') {
                        preRow[i] = Math.min(preRow[i], j);
                        sufRow[i] = Math.max(sufRow[i], j);
                        preCol[j] = Math.min(preCol[j], i);
                        sufCol[j] = Math.max(sufCol[j], i);
                    }
                }
            }

            int ans = 0;
            int cnt = 0;
            for (int i = 1; i <= n; i++) {
                if (preRow[i] == Integer.MAX_VALUE && sufRow[i] == 0) {
                    cnt++;
                    preRow[i] = -1;
                    sufRow[i] = n+1;
                }
                if (preCol[i] == Integer.MAX_VALUE && sufCol[i] == 0) {
                    cnt++;
                    preCol[i] = -1;
                    sufCol[i] = n+1;
                }
            }
            int[][] dp1 = new int[n+1][n+1];      
            for (int j = 1; (n - j + 1) >= k; j++) {
                int count = 0;
                for (int i0 = 1; i0 <= k; i0++) {
                    if (preRow[i0] >= j && sufRow[i0] <= j + k - 1) 
                        count++;
                }
                dp1[1][j] = count;
            }
            for (int i = 2; (n - i + 1) >= k; i++) {
                for (int j = 1; (n - j + 1) >= k; j++) {
                    int d = 0;
                    if (preRow[i-1] >= j && sufRow[i-1] <= j + k - 1) 
                        d--;
                    if (preRow[i+k-1] >= j && sufRow[i+k-1] <= j + k - 1) 
                        d++;
                    dp1[i][j] = dp1[i-1][j] + d;
                }
            }
            int[][] dp2 = new int[n+1][n+1];
            for (int i = 1; (n - i + 1) >= k; i++) {
                int count = 0;
                for (int j = 1; j <= k; j++) {
                    if (preCol[j] >= i && sufCol[j] <= i + k - 1) 
                        count++;
                }
                dp2[i][1] += count;
            }
            for (int i = 1; (n - i + 1) >= k; i++) {
                for (int j = 2; (n - j + 1) >= k; j++) {
                    int d = 0;
                    if (preCol[j-1] >= i && sufCol[j-1] <= i + k - 1) 
                        d--;
                    if (preCol[j+k-1] >= i && sufCol[j+k-1] <= i + k - 1) 
                        d++;
                    dp2[i][j] += dp2[i][j-1] + d;
                }
            }
            for (int i = 1; (n - i + 1) >= k; i++) {
                for (int j = 1; (n - j + 1) >= k; j++) {
                    ans = Math.max(dp1[i][j] + dp2[i][j], ans);
                }
            }
            out.println(ans + cnt);
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

    }
}

