                int left = Integer.MAX_VALUE;
                int right = Integer.MIN_VALUE;
                for (int j = 0; j < n; j++) {
                    if (black[i][j] > 0) {
                        left = Math.min(left, j);
                        right = Math.max(right, j);
                    }
