import java.io.BufferedInputStream;
import java.io.IOException;
import java.util.Scanner;

public class D {
    public static void main(String[] args) throws IOException {
        Scanner in = new Scanner(new BufferedInputStream(System.in, 1 << 19));

        int n = in.nextInt();
        int k = in.nextInt() - 1;

        int[][] accV = new int[n][];
        int[][] accH = new int[n][];

        for (int i = 0; i < n; i++) {
            accV[i] = new int[n];
            accH[i] = new int[n];
        }

        for (int i = 0; i < n; i++) {
            char[] line = in.next().toCharArray();
            for (int j = 0; j < n; j++) {
                char c = line[j];
                accV[i][j] = ((i > 0) ? accV[i - 1][j] : 0) + ((c == 'B') ? 1 : 0);
                accH[i][j] = ((j > 0) ? accH[i][j - 1] : 0) + ((c == 'B') ? 1 : 0);
            }
        }

        int[][] upBonus = new int[n][];
        int[][] leftBonus = new int[n][];

        for (int i = 0; i < n; i++) {
            upBonus[i] = new int[n];
            leftBonus[i] = new int[n];
        }

        for (int i = 0; i < n - k; i++) {
            for (int j = 0; j < n; j++) {
                upBonus[i][j] = (accV[i + k][j] - ((i > 0) ? accV[i - 1][j] : 0)) == accV[n - 1][j] ? 1 : 0;
                if (accV[n-1][j] == 0) --upBonus[i][j];
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n - k; j++) {
                leftBonus[i][j] = (accH[i][j + k] - ((j > 0) ? accH[i][j - 1] : 0)) == accH[i][n - 1] ? 1 : 0;
                if (accH[i][n-1] == 0) --leftBonus[i][j];
            }
        }

        int[][] upBonusAcc = new int[n][];
        int[][] leftBonusAcc = new int[n][];

        for (int i = 0; i < n; i++) {
            upBonusAcc[i] = new int[n];
            leftBonusAcc[i] = new int[n];
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                upBonusAcc[i][j] = ((j > 0) ? upBonusAcc[i][j - 1] : 0) + upBonus[i][j];
                leftBonusAcc[i][j] = ((i > 0) ? leftBonusAcc[i - 1][j] : 0) + leftBonus[i][j];
            }
        }

        int best = 0;
        for (int i = 0; i < n - k; i++) {
            for (int j = 0; j < n - k; j++) {
                int bonus = upBonusAcc[i][j + k] - ((j > 0) ? upBonusAcc[i][j - 1] : 0)
                        + leftBonusAcc[i + k][j] - ((i > 0) ? leftBonusAcc[i - 1][j] : 0);
                best = Math.max(best, bonus);
            }
        }

        int initial = 0;
        for (int i = 0; i < n; i++) {
            if (accV[n - 1][i] == 0) ++initial;
            if (accH[i][n - 1] == 0) ++initial;
        }

        System.out.println(best + initial);
    }
}

