    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        arr = new char[n][];
        for (int i = 0; i < n; i++)
            arr[i] = sc.next().toCharArray();
