            int row_i = -1, row_j = -1, col_i = -1, col_j = -1;
            for (int j = 0; j < n; j++) {
                if (arr[i][j] == 'B') {
                    bool_row = false;
                    if (row_i != -1)
                        row_j = j;
                    if (row_i == -1) {
                        row_i = j;
                        row_j = j;
                    }
                }
                if (arr[j][i] == 'B') {
                    bool_col = false;
                    if (col_i != -1)
                        col_j = j;
                    if (col_i == -1) {
                        col_i = j;
                        col_j = j;
                    }
                }
            }
            col[i] = bool_col;
            row[i] = bool_row;
            oc_row[i] = new Pair(row_i, row_j);
            oc_col[i] = new Pair(col_i, col_j);
        }
        int cnt = col_init();

        int kitna_col_khali[][] = new int[n][n];
        int kitna_row_khali[][] = new int[n][n];
        kitna_col_khali[0][0] = cnt;
        kitna_row_khali[0][0] = cnt;
        for (int i = 0; i <= n - k; i++) {
            int ori = cnt;
            for (int j = 0; j < n - k; j++) {
                cnt = right_col(i, j, cnt, kitna_col_khali);
            }
            if (i < n - k)
                cnt = down_col(i, 0, ori, kitna_col_khali);
        }
        cnt = row_init();
        for (int j = 0; j <= n - k; j++) {
            int ori = cnt;
            for (int i = 0; i < n - k; i++) {
                cnt = down_row(i, j, cnt, kitna_row_khali);
            }
            if (j < n - k)
                cnt = right_row(0, j, ori, kitna_row_khali);
        }

        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                max = Math.max(max, kitna_col_khali[i][j] + kitna_row_khali[i][j]);
        System.out.println(max);
    }

