        for (int p = i; p < i + k; p++) {
            if (!row[p] && oc_row[p].first >= j && oc_row[p].last < j + k)
                cnt--;
            if (!row[p] && oc_row[p].first > j && oc_row[p].last <= j + k)
                cnt++;
        }

        arr[i][j + 1] = cnt;
        return cnt;
    }

    static int down_col(int i, int j, int cnt, int arr[][]) {

        for (int p = j; p < j + k; p++) {
            if (!col[p] && oc_col[p].first >= i && oc_col[p].last < i + k)
                cnt--;
            if (!col[p] && oc_col[p].first > i && oc_col[p].last <= i + k)
                cnt++;
        }
        arr[i + 1][j] = cnt;
        return cnt;
    }

    static int right_col(int i, int j, int cnt, int arr[][]) {


        if (!col[j] && oc_col[j].first >= i && oc_col[j].last < i + k)
            cnt--;

        if (!col[j + k] && oc_col[j + k].first >= i && oc_col[j + k].last < i + k)
            cnt++;
        arr[i][j + 1] = cnt;
        return cnt;
    }
}

