import java.util.*;

public class Solution {
    static int[][][][] dp;

    static int min(int o, int e, int pos, int last, int[] arr) {
        if (pos == arr.length)
            return 0;

        if (dp[o][e][pos][last] != -1)
            return dp[o][e][pos][last];

        if (arr[pos] == 0) {
            int x = 10000, y = 10000;

            if (last == 0) {
                if (e >= 1)
                    x = min(o, e - 1, pos + 1, 0, arr);
                if (o >= 1)
                    y = 1 + min(o - 1, e, pos + 1, 1, arr);
                dp[o][e][pos][last] = Math.min(x, y);
                return dp[o][e][pos][last];
            } else if (last == 1) {
                if (e >= 1)
                    x = 1 + min(o, e - 1, pos + 1, 0, arr);
                if (o >= 1)
                    y = min(o - 1, e, pos + 1, 1, arr);
                dp[o][e][pos][last] = Math.min(x, y);
                return dp[o][e][pos][last];
            } else {
                if (o >= 1)
                    x = min(o - 1, e, pos + 1, 1, arr);
                if (e >= 1)
                    y = min(o, e - 1, pos + 1, 0, arr);
                dp[o][e][pos][last] = Math.min(x, y);
                return dp[o][e][pos][last];
            }
        } else {
            if (last == 0) {
                if (arr[pos] % 2 == 0) {
                    dp[o][e][pos][last] = min(o, e, pos + 1, 0, arr);
                    return dp[o][e][pos][last];
                } else {
                    dp[o][e][pos][last] = 1 + min(o, e, pos + 1, 1, arr);
                    return dp[o][e][pos][last];
                }
            } else if (last == 1) {
                if (arr[pos] % 2 == 0) {
                    dp[o][e][pos][last] = 1 + min(o, e, pos + 1, 0, arr);
                    return dp[o][e][pos][last];
                } else {
                    dp[o][e][pos][last] = min(o, e, pos + 1, 1, arr);
                    return dp[o][e][pos][last];
                }
            } else {
                dp[o][e][pos][last] = min(o, e, pos + 1, arr[pos] % 2, arr);
                return dp[o][e][pos][last];
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] arr = new int[n];
        int o = 0, e = 0;
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
            if (arr[i] != 0) {
                if (arr[i] % 2 == 1)
                    o++;
                else
                    e++;
            }
        }

        if (n % 2 == 0) {
            o = n / 2 - o;
            e = n / 2 - e;
        } else {
            e = n / 2 - e;
            o = n / 2 + 1 - o;
        }

        dp = new int[o + 1][e + 1][n][3];

        for (int i = 0; i <= o; i++) {
            for (int j = 0; j <= e; j++) {
                for (int k = 0; k < n; k++) {
                    dp[i][j][k][0] = -1;
                    dp[i][j][k][1] = -1;
                    dp[i][j][k][2] = -1;
                }
            }
        }

        System.out.println(min(o, e, 0, 2, arr));
    }
}

