                        for(int j = n - 1; j > i; --j){
                            array[j] = chet.pollFirst();
                        }
                    }
                    else if(array[i] % 2 == 1 && nech.size() >= n - 1 - i){
                        for(int j = n - 1; j > i; --j){
                            array[j] = nech.pollFirst();
                        }
