        int cnt = 0, f0 = 0, f1 = 0, l0 = 0, l1 = 0;
        for (int i = 0; i < n; i++) {
            if (p[i] == 0) {
                int j = i;
                while (j < n && p[j] == 0) j++;

                if (i == 0) {
                    if (p[j] % 2 == 0) {
                        f0 = j;
                    } else {
                        f1 = j;
                    }
                } else if (j == n) {
                    if (p[i - 1] % 2 == 0) {
                        l0 = n - i;
                    } else {
                        l1 = n - i;
                    }
                } else {
                    if (p[i - 1] % 2 == 0 && p[j] % 2 == 0) {
                        q00.add(j - i);
                    } else if (p[i - 1] % 2 == 0 && p[j] % 2 == 1) {
                        q01.add(j - i);
                    } else if (p[i - 1] % 2 == 1 && p[j] % 2 == 0) {
                        q10.add(j - i);
                    } else if (p[i - 1] % 2 == 1 && p[j] % 2 == 1) {
                        q11.add(j - i);
                    }
                }

                i = j;
            } else {
                if (i > 0 && p[i - 1] != 0) {
                    if ((p[i - 1] % 2 + p[i] % 2) % 2 == 1) {
                        cnt++;
                    }
                }
            }
        }
        cnt += q01.size();
        cnt += q10.size();

        while (!q00.isEmpty()) {
            int x = q00.poll();
            if (free[0] >= x) {
                free[0] -= x;
            } else {
                cnt += 2;
            }
        }
        while (!q11.isEmpty()) {
            int x = q11.poll();
            if (free[1] >= x) {
                free[1] -= x;
            } else {
                cnt += 2;
            }
        }

        if (f0 != 0) {
            if (free[0] >= f0) {
                free[0] -= f0;
            } else {
                cnt++;
            }
        }
        if (f1 != 0) {
            if (free[1] >= f1) {
                free[1] -= f1;
            } else {
                cnt++;
            }
        }
        if (l0 != 0) {
            if (free[0] >= l0) {
                free[0] -= l0;
            } else {
                cnt++;
            }
        }
        if (l1 != 0) {
            if (free[1] >= l1) {
                free[1] -= l1;
            } else {
                cnt++;
            }
        }

        out.println(cnt);
    }

