public class Codeforces {

    enum Type {
        ODD, EVEN
    }

    static class Interval implements Comparable<Interval> {
        Type type;

        int count;

        public Interval(Type type, int count) {
            this.type = type;
            this.count = count;
        }


        @Override
        public int compareTo(Interval o) {
            return count - o.count;
        }
    }

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        int n = in.nextInt();
        int[] p = in.nextIntArr(n);

        Set<Integer> used = new HashSet<>();
        for (int i = 0; i < p.length; i++) {
            used.add(p[i]);
        }

        int even = 0;
        int odd = 0;
        for (int i = 1; i <= n; i++) {
            if (!used.contains(i)) {
                if (i % 2 == 0) {
                    even++;
                } else {
                    odd++;
                }
            }
        }

        if (even + odd == n) {
            if (n == 1) {
                out.println(0);
            } else {
                out.println(1);
            }

            out.close();
            return;
        }

        List<Interval> intervals = new ArrayList<>();
        List<Interval> openIntervals = new ArrayList<>();

        int res = 0;

        int count = 0;
        int prev = -1;
        for (int i = 0; i < p.length; i++) {
            if (p[i] != 0) {
                if (prev == -1) {
                    if (count == 0) {
                        prev = p[i];
                        continue;
                    }

                    if (p[i] % 2 == 0) {
                        openIntervals.add(new Interval(Type.EVEN, count));
                    } else {
                        openIntervals.add(new Interval(Type.ODD, count));
                    }
                } else {
                    if (count == 0) {
                        prev = p[i];
                        continue;
                    }

                    if (p[i] % 2 == prev % 2) {
                        if (p[i] % 2 == 0) {
                            intervals.add(new Interval(Type.EVEN, count));
                        } else {
                            intervals.add(new Interval(Type.ODD, count));
                        }
                    } else {
                        res++;
                    }

                    count = 0;
                    prev = p[i];
                }
            } else {
                count++;
                if (i == p.length - 1) {
                    if (prev % 2 == 0) {
                        openIntervals.add(new Interval(Type.EVEN, count));
                    } else {
                        openIntervals.add(new Interval(Type.ODD, count));
                    }
                }
            }
        }

        for (int i = 1; i < p.length; i++) {
            if (p[i] != 0 && p[i - 1] != 0 && p[i] % 2 != p[i - 1] % 2) {
                res++;
            }
        }

        Collections.sort(intervals);

        for (Interval interval : intervals) {
            if (interval.type == Type.EVEN) {
                if (even >= interval.count) {
                    even -= interval.count;
                } else {
                    res += 2;
                }
            } else {
                if (odd >= interval.count) {
                    odd -= interval.count;
                } else {
                    res += 2;
                }
            }
        }

        for (Interval openInterval : openIntervals) {
            if (openInterval.type == Type.EVEN) {
                if (even < openInterval.count) {
                    res++;
                }
            } else {
                if (odd < openInterval.count) {
                    res++;
                }
            }
        }

        out.println(res);
        out.close();
    }

