import java.util.*;
import java.lang.*;
import java.io.*;

public class EF3 {
    static PrintWriter out=new PrintWriter(new OutputStreamWriter(System.out));
    public static void main(String[] Args)throws Exception{
        FastReader scan=new FastReader(System.in);
        int t=1;

        while(t-->0){
            int n=scan.nextInt();
            int ods=n/2;
            int evs=n/2;
            if(n%2!=0){
                ods++;
            }
            int[] arr=new int[n];
            for(int i=0;i<n;i++){
                int num=scan.nextInt();
                if(num==0){
                    arr[i]=-1;
                }else {
                    if (num % 2 == 0) {
                        evs--;
                        arr[i] = 0;
                    } else {
                        ods--;
                        arr[i] = 1;
                    }
                }
            }
            int[][][][] dp=new int[n][ods+1][evs+1][3];
            for(int i=0;i<n;i++){
                for(int j=0;j<=ods;j++){
                    for(int k=0;k<=evs;k++){
                        Arrays.fill(dp[i][j][k],-1);
                    }
                }
            }
            out.println(recur(dp,0,arr,ods,evs,2));
        }
        out.flush();
        out.close();
    }
    static int recur(int[][][][] dp,int i,int[] arr,int ods,int evs,int p){
        if(i==arr.length){
            return 0;
        }
        if(dp[i][ods][evs][p]!=-1){
            return dp[i][ods][evs][p];
        }
        int ans=0;
        if(arr[i]!=-1){
            if((arr[i]==0&&p==1)||(arr[i]==1&&p==0)){
                ans++;
            }
            ans+=recur(dp,i+1,arr,ods,evs,arr[i]);
        }else{
            int t1=Integer.MAX_VALUE;
            int t2=Integer.MAX_VALUE;
            if(ods>0){
                t1 = (p==0 ? 1 : 0) + recur(dp,i+1,arr,ods-1,evs,1);
            }
            if(evs>0){
                t2 = (p==1 ? 1 : 0) + recur(dp,i+1,arr,ods,evs-1,0);
            }
            ans=Math.min(t1,t2);
        }
        dp[i][ods][evs][p]=ans;
        return ans;
    }
    static class FastReader {

        byte[] buf = new byte[2048];
        int index, total;
        InputStream in;

        FastReader(InputStream is) {
            in = is;
        }

        int scan() throws IOException {
            if (index >= total) {
                index = 0;
                total = in.read(buf);
                if (total <= 0) {
                    return -1;
                }
            }
            return buf[index++];
        }

        String next() throws IOException {
            int c;
            for (c = scan(); c <= 32; c = scan()) ;
            StringBuilder sb = new StringBuilder();
            for (; c > 32; c = scan()) {
                sb.append((char) c);
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c, val = 0;
            for (c = scan(); c <= 32; c = scan()) ;
            boolean neg = c == '-';
            if (c == '-' || c == '+') {
                c = scan();
            }
            for (; c >= '0' && c <= '9'; c = scan()) {
                val = (val << 3) + (val << 1) + (c & 15);
            }
            return neg ? -val : val;
        }
        long nextLong() throws IOException {
            int c;
            long val = 0;
            for (c = scan(); c <= 32; c = scan()) ;
            boolean neg = c == '-';
            if (c == '-' || c == '+') {
                c = scan();
            }
            for (; c >= '0' && c <= '9'; c = scan()) {
                val = (val << 3) + (val << 1) + (c & 15);
            }
            return neg ? -val : val;
        }
    }
}

