        dp[0][nOdd-1][nEven][1] = 0;
      if (nEven>0)
        dp[0][nOdd][nEven-1][0] = 0;
    } else {
      dp[0][nOdd][nEven][arr[0]%2] = 0;
    }
    for (int i=1; i<n; i++) {
      for (int j=0; j<=nOdd; j++) {
        for (int k=0; k<=nEven; k++) {
          if (arr[i]==-1) {
            if (j>0) {
              dp[i][j-1][k][1] = dp[i-1][j][k][1];
              if (dp[i-1][j][k][0] != null && (dp[i][j-1][k][1]==null || dp[i-1][j][k][0] < dp[i][j-1][k][1])) {
                dp[i][j-1][k][1] = 1+ dp[i-1][j][k][0];
              }
            }
            if (k>0) {
              dp[i][j][k-1][0] = dp[i-1][j][k][0];
              if (dp[i-1][j][k][1] != null && (dp[i][j][k-1][0]==null || dp[i-1][j][k][1] < dp[i][j][k-1][0]))
                dp[i][j][k-1][0] = 1+dp[i-1][j][k][1];
            }
          } else {
            dp[i][j][k][arr[i]%2] = dp[i-1][j][k][arr[i]%2];

            if (dp[i-1][j][k][1-(arr[i]%2)] != null && 
               (dp[i][j][k][arr[i]%2]==null || dp[i-1][j][k][1-(arr[i]%2)] < dp[i][j][k][arr[i]%2])) {
              dp[i][j][k][arr[i]%2] = 1 + dp[i-1][j][k][1-(arr[i]%2)];
            }
          }
        }
      }
    }
    Integer ans = dp[n-1][0][0][0];
    if (dp[n-1][0][0][1]!=null && (ans==null || dp[n-1][0][0][1] < ans)) {
      ans = dp[n-1][0][0][1];
    }
    System.out.println(ans);

  }
}

