import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Random;

public class Solution{




	public static void main(String[] args) {

		FastScanner fs = new FastScanner();
		PrintWriter out = new PrintWriter(System.out);


		int tt = 1;
		while(tt-->0) {

			int n = fs.nextInt();

			int[] par = new int[2];
			par[0] = (n)/2;
			par[1] = (n+1)/2;

			int[] p = new int[n];
			for(int i=0;i<n;i++) {
				p[i] = fs.nextInt();
				if(p[i]!=0) {
					if(p[i]%2==0) par[0]--;
					else par[1]--;
				}
			}

			ArrayList<Integer>[] list = new ArrayList[2];
			for(int i=0;i<2;i++ ) list[i] = new ArrayList<Integer>();

			ArrayList<Integer>[] sList = new ArrayList[2];
			for(int i=0;i<2;i++) sList[i] = new ArrayList<Integer>();

			int cnt = 0;



			for(int i=0;i<n;i++) {
				if(p[i] == 0) {
					int j = i;
					while(i<n-1 && p[i+1]==0) i++;
					int l = (j>0)?p[j-1]:-1;
					int r = (i<n-1)?p[i+1]:-1;

					if(l!=-1 && r!=-1) {
						if(l%2==r%2) {
							list[l%2].add(i-j+1);
						}
						else cnt++;
					}
					else if(l==-1) {
						sList[(r+2)%2].add(i-j+1);
					}
					else if(r==-1) {
						sList[(l+2)%2].add(i-j+1);
					}
				}
			}



			Collections.sort(list[0]);
			Collections.sort(list[1]);

			for(int i=0;i<2;i++) {
				int sum = 0;
				int c = 0;
				for(int j=0;j<list[i].size();j++) {
					if(sum + list[i].get(j)>par[i]) {
						break;
					}
					sum += list[i].get(j);
					c++;
				}
				par[i] -= sum;
				cnt += 2*(list[i].size()-c);
			}


			Collections.sort(sList[0]);
			Collections.sort(sList[1]);

			for(int i=0;i<2;i++) {
				int sum = 0;
				int c = 0;
				for(int j=0;j<sList[i].size();j++) {
					if(sum + sList[i].get(j)>par[i]) {
						break;
					}
					sum += sList[i].get(j);
					c++;
				}
				cnt += 1*(sList[i].size()-c);
			}


			for(int i=0;i<n-1;i++) {
				if(p[i]!=0 && p[i+1]!=0) {
					if(p[i]%2!=p[i+1]%2) cnt++;
				}
			}

			out.println(cnt);


		}

		out.close();

	}




