import java.util.Scanner;

public class Garland {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int countJi = (n % 2 == 0) ? (n / 2) : (n / 2) + 1;
        int countOu = n / 2;
        int[] arr = new int[n];
        int firstIndex = -1;
        int lastIndex = -1;
        int[] disArr = new int[n];
        int distance = 0;
        int frontNum = -1;
        for (int i = 0; i < n; i++) {
            arr[i] = scanner.nextInt();
            if (arr[i] != 0) {
                lastIndex = i;
                if (firstIndex == -1) {
                    firstIndex = i;
                }
                if (arr[i] % 2 == 0) {
                    countOu--;
                } else {
                    countJi--;
                }
                if (frontNum == -1) {
                    frontNum = arr[i];
                    distance = 0;
                } else {
                    if ((frontNum % 2 == 0 && arr[i] % 2 == 0) || (frontNum % 2 != 0 && arr[i] % 2 != 0)) {
                        disArr[distance] = 1;
                    }
                    frontNum = arr[i];
                    distance = 0;
                }
                continue;
            }
            distance++;
        }

        if (firstIndex == -1) {
            if (n == 1) {
                System.out.println(0);
            } else {
                System.out.println(1);
            }
        } else {

            for (int i = 1; i < n; i++) {
                if (disArr[i] != 0) {
                    distance = i;
                    for (int j = 0; j < n - distance - 1; j++) {
                        if (arr[j] != 0 && arr[j + distance + 1] != 0 &&
                                ((arr[j] % 2 == 0 && arr[j + distance +1] % 2 == 0) ||
                                        (arr[j] % 2 != 0 && arr[j + distance + 1] % 2 != 0))) {
                            boolean isZero = true;
                            for (int k = j + 1; k <= j + distance; k++) {
                                if (arr[k] != 0) {
                                    isZero = false;
                                    break;
                                }
                            }
                            if (isZero) {
                                if (arr[j] % 2 == 0 && countOu >= distance) {
                                    for (int k = j + 1; k <= j + distance; k++) {
                                        arr[k] = 2;
                                    }
                                    countOu -= distance;
                                }
                                if (arr[j] % 2 != 0 && countJi >= distance) {
                                    for (int k = j + 1; k <= j + distance; k++) {
                                        arr[k] = 1;
                                    }
                                    countJi -= distance;
                                }
                            }
                        }
                    }
                }
            }

            if (lastIndex != (n - 1)) { 
                int isInsert = -1;
                if (arr[lastIndex] % 2 == 0 && countOu >= (n - lastIndex - 1)) { 
                    isInsert = 2;
                    countOu -= (n - lastIndex - 1);
                }
                if (arr[lastIndex] % 2 != 0 && countJi >= (n - lastIndex - 1)) { 
                    isInsert = 1;
                    countJi -= (n - lastIndex - 1);
                }
                if (isInsert != -1) {
                    for (int i = lastIndex + 1; i < n; i++) {
                        arr[i] = isInsert;
                    }
                }
            }

            for (int i = firstIndex - 1; i >= 0; i--) {
                if (arr[i + 1] % 2 == 0) {
                    if (countOu > 0) {
                        countOu--;
                        arr[i] = 2;
