import java.io.*;
import java.util.*;

public class C {
    FastScanner scanner;
    PrintWriter writer;

    int n;
    int[] mods;

    void solve() throws IOException {
        scanner = new FastScanner(System.in);
        writer = new PrintWriter(System.out);

        n = scanner.nextInt();
        mods = new int[n];

        if (n == 1) {
            writer.println(0);
            writer.close();
            return;
        }

        List<Interval> ints = new ArrayList<>();
        int streak = 0;

        int[] cnts = new int[]{n / 2, (n + 1) / 2};

        int comp = 0;

        for (int i = 0; i < n; i++) {
            int p = scanner.nextInt();
            if (p == 0) {
                mods[i] = -1;
                streak++;
            } else {
                mods[i] = p % 2;
                cnts[mods[i]]--;

                if (streak > 0) {
                    ints.add(new Interval(i - streak, i));
                }
                streak = 0;

                if (i > 0 && mods[i - 1] != -1 && mods[i] != mods[i - 1])
                    comp++;
            }
        }

        if (streak > 0) {
            ints.add(new Interval(n - streak, n));
        }

        Collections.sort(ints);

        fillMatchingIntervals(ints, cnts);
        fillEdgeIntervals(ints, cnts);

        for (Interval interval : ints) {
            int mod = intMod(interval);
            if (mod != -1 && interval.start != 0 && interval.end != n)
                comp += 2;
            else
                comp++;
        }

        writer.println(comp);

        writer.close();
    }

    private void fillEdgeIntervals(List<Interval> ints, int[] cnts) {
        for (Iterator<Interval> it = ints.iterator(); it.hasNext(); ) {
            Interval interval = it.next();
            int mod = intMod(interval);
            if (mod != -1 && (interval.start == 0 || interval.end == n) && interval.len() <= cnts[mod]) {
                cnts[mod] -= interval.len();
                it.remove();
            }
        }
    }

    private void fillMatchingIntervals(List<Interval> ints, int[] cnts) {
        for (Iterator<Interval> it = ints.iterator(); it.hasNext(); ) {
            Interval interval = it.next();
            int mod = intMod(interval);
            if (mod != -1 && interval.start != 0 && interval.end != n && interval.len() <= cnts[mod]) {
                cnts[mod] -= interval.len();
                it.remove();
            }
        }
    }

    int intMod(Interval interval) {
        if (interval.start == 0 && interval.end == n)
            return -1;
        else if (interval.start == 0)
            return mods[interval.end];
        else if (interval.end == n)
            return mods[interval.start - 1];
        else {
            if (mods[interval.start - 1] == mods[interval.end])
                return mods[interval.start - 1];
            else
                return -1;
        }
    }

    static class Interval implements Comparable<Interval> {
        int start;
        int end;

        int len() {
            return end - start;
        }

        Interval(int start, int end) {
            this.start = start;
            this.end = end;
        }

        @Override
        public int compareTo(Interval o) {
            return Integer.compare(len(), o.len());
        }
    }

    public static void main(String[] args) throws IOException {
        new C().solve();
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer tokenizer;

        FastScanner(InputStream is) {
            this.br = new BufferedReader(new InputStreamReader(is));
        }

        FastScanner(File file) throws FileNotFoundException {
            this(new FileInputStream(file));
        }

        String nextLine() throws IOException {
            return br.readLine();
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens())
                tokenizer = new StringTokenizer(br.readLine());

            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

