import java.io.DataInputStream; 
import java.io.FileInputStream; 
import java.io.IOException; 
import java.io.InputStreamReader; 
import java.util.Scanner; 
import java.util.StringTokenizer; 
import java.util.*;

 public class Main 
{ 
    static class Reader 
    { 
        final private int BUFFER_SIZE = 1 << 16; 
        private DataInputStream din; 
        private byte[] buffer; 
        private int bufferPointer, bytesRead; 

        public Reader() 
        { 
            din = new DataInputStream(System.in); 
            buffer = new byte[BUFFER_SIZE]; 
            bufferPointer = bytesRead = 0; 
        } 

        public Reader(String file_name) throws IOException 
        { 
            din = new DataInputStream(new FileInputStream(file_name)); 
            buffer = new byte[BUFFER_SIZE]; 
            bufferPointer = bytesRead = 0; 
        } 

        public String readLine() throws IOException 
        { 
            byte[] buf = new byte[64]; 
            int cnt = 0, c; 
            while ((c = read()) != -1) 
            { 
                if (c == '\n') 
                    break; 
                buf[cnt++] = (byte) c; 
            } 
            return new String(buf, 0, cnt); 
        } 

        public int nextInt() throws IOException 
        { 
            int ret = 0; 
            byte c = read(); 
            while (c <= ' ') 
                c = read(); 
            boolean neg = (c == '-'); 
            if (neg) 
                c = read(); 
            do
            { 
                ret = ret * 10 + c - '0'; 
            } 
            while ((c = read()) >= '0' && c <= '9'); 

            if (neg) 
                return -ret; 
            return ret; 
        } 

        public long nextLong() throws IOException 
        { 
            long ret = 0; 
            byte c = read(); 
            while (c <= ' ') 
                c = read(); 
            boolean neg = (c == '-'); 
            if (neg) 
                c = read(); 
            do { 
                ret = ret * 10 + c - '0'; 
            } 
            while ((c = read()) >= '0' && c <= '9'); 
            if (neg) 
                return -ret; 
            return ret; 
        } 

        public double nextDouble() throws IOException 
        { 
            double ret = 0, div = 1; 
            byte c = read(); 
            while (c <= ' ') 
                c = read(); 
            boolean neg = (c == '-'); 
            if (neg) 
                c = read(); 

            do { 
                ret = ret * 10 + c - '0'; 
            } 
            while ((c = read()) >= '0' && c <= '9'); 

            if (c == '.') 
            { 
                while ((c = read()) >= '0' && c <= '9') 
                { 
                    ret += (c - '0') / (div *= 10); 
                } 
            } 

            if (neg) 
                return -ret; 
            return ret; 
        } 

        private void fillBuffer() throws IOException 
        { 
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE); 
            if (bytesRead == -1) 
                buffer[0] = -1; 
        } 

        private byte read() throws IOException 
        { 
            if (bufferPointer == bytesRead) 
                fillBuffer(); 
            return buffer[bufferPointer++]; 
        } 

        public void close() throws IOException 
        { 
            if (din == null) 
                return; 
            din.close(); 
        } 
    } 

    public static void main(String[] args) throws IOException 
    { 
        Reader sc=new Reader(); 
        int n=sc.nextInt();
        int a[]=new int[n];
        int even=0;
        for( int i=0;i<n;i++)
        {
            a[i]=sc.nextInt();
            if(a[i]%2==0 && a[i]!=0)
                even++;
        }
        long mod=1000000007;
        long dp[][][]=new long[n+1][1000][2];
        for( int i=0;i<=n;i++)
        {
            for( int j=0;j<=n;j++)
            {
                for( int k=0;k<2;k++)
                {
                    dp[i][j][k]=mod;
                }
            }
        }
        dp[0][0][0]=0;
        dp[0][0][1]=0;
        for( int i=1;i<=n;i++)
        {
            for( int j=0;j<i;j++)
            {
                for( int k=0;k<2;k++)
                {
                    long prev=dp[i-1][j][k];
                    if(a[i-1]!=0)
                    {
                        if(a[i-1]%2==0)
                        {
                            dp[i][j+1][0]=Math.min(dp[i][j+1][0],prev+k);
                        }
                        else 
                        {
                            dp[i][j][1]=Math.min(dp[i][j][1],prev+(1-k));
                        }
                    }
                    else
                    {
                        for(int s=0;s<2;s++)
                        {
                            int c=0;
                            if(s!=k)
                                c=1;
                            dp[i][j+1-s][s]=Math.min(dp[i][j+1-s][s],prev+c);
                        }
                    }
                }
            }
        }
        System.out.println(Math.min(dp[n][even][0],dp[n][even][1]));
    } 
}

