                           }
                           if(k<y){
                               dp[i][j][k+1][0]=Math.min( dp[i][j][k+1][0], dp[i-1][j][k][0]);
                           }
                       }

                       if(dp[i-1][j][k][1]!=max){
                           if(j<x){
                               dp[i][j+1][k][1]=Math.min( dp[i][j+1][k][1], dp[i-1][j][k][1]);
                           }
                           if(k<y){
                               dp[i][j][k+1][0]=Math.min( dp[i][j][k+1][0], 1+dp[i-1][j][k][1]);
                           }
                       }

                   }
               }
           }
        }

