import java.util.*;
import java.io.*;

public class Solution{

	public Solution(){
		Scanner sc = new Scanner(System.in);
		int tests = 1;

        for(int t=1; t<=tests; t++){
			int n = sc.nextInt();

			int[] arr = new int[n];
			int oddCount = 0;
			int evenCount = 0;

			for(int i=0; i<n; i++){
				arr[i] = sc.nextInt();
				if(arr[i] > 0){
					if(arr[i]%2 == 0){
						evenCount++;
					}
					else{
						oddCount++;
					}
				}
			}
			int totEven = n/2;
			int totOdd = n-totEven;
			oddCount = totOdd-oddCount;
			evenCount = totEven-evenCount;

			int[] odd = new int[n];
			int[] even = new int[n];

			int res = 0;
			for(int i=0; i<(n-1); i++){
				if(arr[i] == 0){
					continue;
				}
				int j = i+1;
				while(j < n && arr[j] == 0){
					j++;
				}
				if(j == n){
					break;
				}

				if((arr[i]%2) == 0){
					if(arr[j]%2 == 0){
						even[j-i-1]++;
					}
					else{
						res++;
					}
				}
				else{
					if(arr[j]%2 == 1){
						odd[j-i-1]++;
					}
					else{
						res++;
					}
				}
			}

			for(int i=1; i<n; i++){
				int req = i*odd[i];
				if(req <= oddCount){
					oddCount -= req;
				}
				else{
					int comp = oddCount/i;
					odd[i] -= comp;
					res += (odd[i]*2);
					comp *= i;
					oddCount -= comp;
				}

				req = i*even[i];
				if(req <= evenCount){
					evenCount -= req;
				}
				else{
					int comp = evenCount/i;
					even[i] -= comp;
					res += (even[i]*2);
					comp *= i;
					evenCount -= comp;
				}
			}

			int index = 0;
			while(index < n && arr[index] == 0){
				index++;
			}

			if(index == n){
				if(n == 1){
					System.out.println(0);
				}
				else{
					System.out.println(1);
				}
				continue;
			}

			if(arr[index]%2 == 0){
				if(index <= evenCount){
					evenCount -= index;
				}
				else{
					res++;
				}
			}
			else{
				if(index <= oddCount){
					oddCount -= index;
				}
				else{
					res++;
				}
			}

			index = n-1;
			while(index >= 0 && arr[index] == 0){
				index--;
			}

			if(arr[index]%2 == 0){
				if((n-1-index) <= evenCount){
					evenCount -= index;
				}
				else{
					res++;
				}
			}
			else{
				if((n-1-index) <= oddCount){
					oddCount -= index;
				}
				else{
					res++;
				}
			}

			System.out.println(res);
        }
	}

	public static void main(String[] args){
		new Solution();
	}
}

