					}
					else{
						res++;
					}
				}
			}

			for(int i=1; i<n; i++){
				int req = i*oddCount;
				if(req <= oddCount){
					oddCount -= req;
				}
				else{
					int comp = oddCount/i;
					oddCount -= comp;
					res += (comp*2);
					comp *= i;
					oddCount -= comp;
				}

				req = i*evenCount;
				if(req <= evenCount){
					evenCount -= req;
				}
				else{
					int comp = evenCount/i;
					evenCount -= comp;
					res += (comp*2);
					comp *= i;
					evenCount -= comp;
				}
			}

			int index = 0;
			while(index < n && arr[index] == 0){
