				else{
					System.out.println(1);
				}
				continue;
			}

			if(arr[index]%2 == 0){
				if(index <= evenCount){
					evenCount -= index;
				}
				else{
					res++;
				}
			}
			{
				if(index <= oddCount){
					oddCount -= index;
				}
				else{
					res++;
				}
			}

			index = n-1;
			while(index >= 0 && arr[index] == 0){
				index--;
			}

			if(arr[index]%2 == 0){
				if((n-1-index) <= evenCount){
					evenCount -= index;
				}
				else{
					res++;
				}
			}
			else{
				if((n-1-index) <= oddCount){
					oddCount -= index;
				}
				else{
					res++;
				}
			}

			System.out.println(res);
