import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader sc = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Task solver = new Task();
        solver.solve(1, sc, out);
        out.close();
    }

    static class Task {
        public void solve(int testNumber, InputReader sc, PrintWriter out) {
            int n = sc.nextInt();
            int[] f = new int[2];
            int[] a = new int[n + 1];

            for (int i = 1; i <= n; i++) {
                a[i] = sc.nextInt();
                if (a[i] != 0)
                    f[a[i] % 2]++;
            }
            int[] cnt = new int[2];
            cnt[0] = n / 2 - f[0];
            cnt[1] = (n + 1) / 2 - f[1];
            int[][][][] dp = new int[n + 1][cnt[1] + 1][cnt[0] + 1][3];
            for (int i = 0; i < dp.length; i++) {
                for (int j = 0; j < dp[0].length; j++) {
                    for (int k = 0; k < dp[0][0].length; k++) {
                        dp[i][j][k][0] = dp[i][j][k][1] = dp[i][j][k][2] = (int) 1e5;
                    }
                }
            }

            for (int i = 1; i <= n; i++) {
                if (a[i] != 0) {
                    if (i == 1) {
                        dp[i][0][0][2] = 0;
                        continue;
                    }
                    f[0] = f[1] = 0;
                    f[a[i] % 2]++;
                    if (a[i - 1] == 0) {
                        for (int j = 0; j <= cnt[1]; j++) {
                            for (int k = 0; k <= cnt[0]; k++) {
                                dp[i][j][k][2] = Math.min(dp[i - 1][j][k][0] + f[1], dp[i - 1][j][k][1] + f[0]);
                            }
                        }
                    } else {
                        int temp = (a[i] % 2) ^ (a[i - 1] % 2);
                        for (int j = 0; j <= cnt[1]; j++) {
                            for (int k = 0; k <= cnt[0]; k++) {
                                dp[i][j][k][2] = dp[i - 1][j][k][2] + temp;
                            }
                        }
                    }
                } else {
                    if (i == 1) {
                        if (cnt[1] > 0)
                            dp[i][1][0][1] = 0;
                        if (cnt[0] > 0)
                            dp[i][0][1][0] = 0;
                        continue;
                    }
                    if (a[i - 1] != 0) {
                        f[0] = f[1] = 0;
                        f[a[i - 1] % 2]++;
                        for (int j = 0; j <= cnt[1] - 1; j++) {
                            for (int k = 0; k <= cnt[0]; k++) {
                                dp[i][j + 1][k][1] = Math.min(dp[i][j + 1][k][1], dp[i - 1][j][k][2] + f[0]);
                            }
                        }
                        for (int j = 0; j <= cnt[1]; j++) {
                            for (int k = 0; k <= cnt[0] - 1; k++) {
                                dp[i][j][k + 1][0] = Math.min(dp[i][j][k + 1][0], dp[i - 1][j][k][2] + f[1]);
                            }
                        }
                        continue;
                    }
                    for (int j = 0; j <= cnt[1] - 1; j++) {
                        for (int k = 0; k <= cnt[0]; k++) {
                            dp[i][j + 1][k][1] = Math.min(dp[i][j + 1][k][1], Math.min(dp[i - 1][j][k][0] + 1, dp[i - 1][j][k][1]));
                        }
                    }
                    for (int j = 0; j <= cnt[1]; j++) {
                        for (int k = 0; k <= cnt[0] - 1; k++) {
                            dp[i][j][k + 1][0] = Math.min(dp[i][j][k + 1][0], Math.min(dp[i - 1][j][k][0], dp[i - 1][j][k][1] + 1));
                        }
                    }
                }
            }

            out.println(Math.min(dp[n][cnt[1]][cnt[0]][0], Math.min(dp[n][cnt[1]][cnt[0]][1], dp[n][cnt[1]][cnt[0]][2])));
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

    }
}

