@SuppressWarnings("unchecked")
public class Main {
	static class Tuple implements Comparable<Tuple> {
		int s, e, c, len;

		Tuple(int s, int e, int c) {
			this.s = s;
			this.e = e;
			this.c = c;
			len = e - s + 1;
		}

		public int compareTo(Tuple t) {
			return c == t.c ? len - t.len : t.c - c;
		}
	}

	public static void main(String[] args) {
		InputReader in = new InputReader();

		int N = in.nextInt();
		if (N == 1) {
			System.out.println(0);
			return;
		}
		int[] p = new int[N];
		int[] q = new int[2];
		q[0] = N / 2;
		q[1] = N / 2 + N % 2;
		int cost = 0;
		for (int i = 0; i < N; i++) {
			p[i] = in.nextInt();
			if (p[i] == 0) {
				p[i] = -1;
			} else {
				p[i] %= 2;
				q[p[i]]--;
				if (i > 0 && p[i - 1] != -1 && p[i] != p[i - 1]) {
					cost++;
				}
			}
		}
		if (q[0] + q[1] == N) {
			System.out.println(1);
			return;
		}

		List<Tuple>[] list = new List[2];
		for (int i = 0; i < 2; i++) {
			list[i] = new ArrayList<>();
		}
		for (int i = 0; i < N; i++) {
			if (p[i] != -1) {
				continue;
			}
			int start, end;
			start = end = i;
			for (int j = i + 1; j < N; j++) {
				if (p[j] == -1) {
					end = j;
				} else {
					break;
				}
			}
			if (start > 0 && end < N - 1) {
				if (p[start - 1] == p[end + 1]) {
					list[p[start - 1]].add(new Tuple(start, end, 2));
				} else {
					cost++;
				}
			} else {
				list[start > 0 ? p[start - 1] : p[end+1]].add(new Tuple(start, end, 1));
			}
			i = end + 1;
		}
		for (int i = 0; i < 2; i++) {
			Collections.sort(list[i]);
			for (Tuple t : list[i]) {
				if (q[i] >= t.len) {
					q[i] -= t.len;
				} else {
					cost += t.c;
				}
			}
		}

		System.out.println(cost);
	}

	static class InputReader {
		public BufferedReader reader;
		public StringTokenizer st;

		public InputReader() {
			reader = new BufferedReader(new InputStreamReader(System.in));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				st = new StringTokenizer(nextLine());
			}
			return st.nextToken();
		}

		public String nextLine() {
			try {
				return reader.readLine();
			} catch (IOException e) {
				e.printStackTrace();
			}
			return null;
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}
	}
}

