import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;

public class Problem7C {
	public static void main(String[] args) throws Exception {
		BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(reader.readLine());
		int[] x = Arrays.stream(reader.readLine().split(" ")).mapToInt(Integer::parseInt).toArray();
		int evens = 0;
		int odds = 0;
		int existingParity = 0;
		for (int i = 0; i < x.length - 1; i++) {
			if (isOdd(x, i) && isEven(x, i + 1)) {
				existingParity++;
			}
			if (isEven(x, i) && isOdd(x, i - 1)) {
				existingParity++;
			}
		}
		for (int i = 0; i < x.length; i++) {
			if (x[i] != 0) {
				if (x[i] % 2 == 0) {
					evens++;
				} else {
					odds++;
				}
			}
		}
		int evensNeeded = n / 2 - evens;
		int oddsNeeded = (n + 1) / 2 - odds;
		int numbersMissing = oddsNeeded + evensNeeded;

		int[][][] dp = new int[n + 5][numbersMissing + 5][3 + 5];
		for (int i = 0; i < dp.length; i++) {
			for (int j = 0; j < dp[0].length; j++) {
				Arrays.fill(dp[i][j], -1);
			}
		}
		int solved = existingParity + solve(x, 0, oddsNeeded, numbersMissing, 0, dp);
		System.out.println(solved);
	}
	public static int solve(int[] x, int index, int oddsNeeded, int numbersMissing, int prev, int[][][] dp) {
		int evensNeeded = numbersMissing - oddsNeeded;

		if (index >= x.length) {
			return 0;
		}
		if (dp[index][oddsNeeded][prev] != -1) {
			return dp[index][oddsNeeded][prev];
		}
		if (x[index] != 0) {
			int curPrev = (x[index] % 2 == 0) ? 2 : 1;
			int res = solve(x, index + 1, oddsNeeded, numbersMissing, curPrev, dp);
			dp[index][oddsNeeded][curPrev] = res;
			return res;
		}

		int min = Integer.MAX_VALUE;
		if (oddsNeeded > 0) {
			int oddParity = (prev == 2 || isEven(x, index - 1) ? 1 : 0) + (isEven(x, index + 1) ? 1 : 0);
			min = Math.min(min, oddParity + solve(x, index + 1, oddsNeeded - 1, numbersMissing - 1, 1, dp));
		}
		if (evensNeeded > 0) {
			int evenParity = (prev == 1 || isOdd(x, index - 1) ? 1 : 0) + (isOdd(x, index + 1) ? 1 : 0);
			min = Math.min(min, evenParity + solve(x, index + 1, oddsNeeded, numbersMissing - 1, 2, dp));
		}
		dp[index][oddsNeeded][prev] = min;
		return min;
	}
	public static boolean isOdd(int[] x, int i) {
		if (i < 0 || i >= x.length || x[i] == 0) {
			return false;
		}
		return x[i] % 2 == 1;
	}
	public static boolean isEven(int[] x, int i) {
		if (i < 0 || i >= x.length || x[i] == 0) {
			return false;
		}
		return x[i] % 2 == 0;
	}
}

import java.io.BufferedReader;
