public class Problem7C {
    public static void main(String[] args) throws Exception {
        try {
            BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
            int n = Integer.parseInt(reader.readLine());
            int[] x = Arrays.stream(reader.readLine().split(" ")).mapToInt(Integer::parseInt).toArray();
            int evens = 0;
            int odds = 0;
            int existingParity = 0;
            for (int i = 0; i < x.length - 1; i++) {
                if (isOdd(x, i) && isEven(x, i + 1)) {
                    existingParity++;
                }
                if (isEven(x, i) && isOdd(x, i + 1)) {
                    existingParity++;
                }
            }
            for (int i = 0; i < x.length; i++) {
                if (x[i] != 0) {
                    if (x[i] % 2 == 0) {
                        evens++;
                    } else {
                        odds++;
                    }
                }
            }
            int evensNeeded = n / 2 - evens;
            int oddsNeeded = (n + 1) / 2 - odds;
            int numbersMissing = oddsNeeded + evensNeeded;

            int[][][] dp = new int[n + 5][numbersMissing + 5][3 + 5];
            for (int i = 0; i < dp.length; i++) {
                for (int j = 0; j < dp[0].length; j++) {
                    for (int k = 0; k < dp[0][0].length; k++) {
                        dp[i][j][k] = -1;
                    }
                }
            }
            int solved = existingParity + solve(x, 0, oddsNeeded, numbersMissing, 0, dp);
            System.out.println(solved);
        } catch (ArrayIndexOutOfBoundsException ex) {
            try {
                Thread.sleep(9999);
            } catch (Exception e) {}
        }
    }

    public static int solve(int[] x, int index, int oddsNeeded, int numbersMissing, int prev, int[][][] dp) {
        int evensNeeded = numbersMissing - oddsNeeded;

        if (index >= x.length) {
            return 0;
        }
        if (dp[index][oddsNeeded][prev] != -1) {
            return dp[index][oddsNeeded][prev];
        }
        if (x[index] != 0) {
            dp[index][oddsNeeded][0] = solve(x, index + 1, oddsNeeded, numbersMissing, 0, dp);
            return dp[index][oddsNeeded][0];
        }

        int min = Integer.MAX_VALUE;
        if (oddsNeeded > 0) {
            int oddParity = ((prev == 2 || isEven(x, index - 1)) ? 1 : 0) + (isEven(x, index + 1) ? 1 : 0);
            min = Math.min(min, oddParity + solve(x, index + 1, oddsNeeded - 1, numbersMissing - 1, 1, dp));
        }
        if (evensNeeded > 0) {
            int evenParity = (prev == 1 || isOdd(x, index - 1) ? 1 : 0) + (isOdd(x, index + 1) ? 1 : 0);
            min = Math.min(min, evenParity + solve(x, index + 1, oddsNeeded, numbersMissing - 1, 2, dp));
        }
        dp[index][oddsNeeded][prev] = min;
        return min;
    }

    public static boolean isOdd(int[] x, int i) {
        if (i < 0 || i >= x.length || x[i] == 0) {
            return false;
        }
        return x[i] % 2 == 1;
    }

    public static boolean isEven(int[] x, int i) {
        if (i < 0 || i >= x.length || x[i] == 0) {
            return false;
        }
        return x[i] % 2 == 0;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {

    static final int INF = 1000000000;

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        int n = in.nextInt();
        int[] a = new int[200];
        int[] b = new int[200];
        int[] c = new int[200];
        int[][][] f = new int[200][200][2];
        for (int i = 0; i < 200; i++)
            for (int j = 0; j < 200; j++)
                for (int k = 0; k < 2; k++)
                    f[i][j][k] = INF;
        c[0] = 0;
        int s0 = 0, s1 = 0;                 // missing evens and odds
        for (int i = 1; i <= n; i++) {
            a[i] = in.nextInt();
            c[i] = c[i - 1];
            if (a[i] == 0) {
                c[i]++;
                continue;
            }
            b[a[i]] = 1;
        }
        // count missing even and odd numbers
        for (int i = 1; i <= n; i++) {
            if (b[i] == 0) {
                if (i % 2 == 0) s0++; else s1++;
            }
        }
        if (a[1] == 0) {
            if (s0 > 0) f[1][1][0] = 0;
            if (s1 > 0) f[1][0][1] = 0;
        } else {
            f[1][0][a[1] % 2] = 0;
        }
        for (int i = 1; i < n; i++) {
            for (int j = 0; j <= i; j++) {
                for (int k = 0; k < 2; k++) {
                    if (f[i][j][k] == INF) continue;
                    if (a[i + 1] == 0) {
                        if (j + 1 <= s0) {
                            f[i + 1][j + 1][0] = Math.min(f[i + 1][j + 1][0],
                                                          f[i][j][k] + (k ^ 0));
                        }
                        if (c[i] - j + 1 <= s1) {
                            f[i + 1][j][1] = Math.min(f[i + 1][j][1],
                                                      f[i][j][k] + (k ^ 1));
                        }
                    } else {
                        f[i + 1][j][a[i + 1] % 2] = Math.min(f[i + 1][j][a[i + 1] % 2],
                                                             f[i][j][k] + (k ^ (a[i + 1] % 2)));
                    }
                }
            }
        }
        int ans = INF;
        for (int i = 0; i <= s0; i++) {
            ans = Math.min(ans, f[n][i][0]);
            ans = Math.min(ans, f[n][i][1]);
        }
        out.println(ans);
        out.close();
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

