public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        int[][][][] dp;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.readInt();
            int[] g = in.readIntArray(n);
            int even = 0, odd = 0;
            for (int i = 0; i < n; i++) {
                boolean blank = true;
                for (int j = 0; j < n; j++) {
                    if (g[j] == i + 1) {
                        blank = false;
                        break;
                    }
                }
                if (blank) {
                    if (i % 2 == 0) odd++;
                    else even++;
                }
            }
            dp = new int[n][n + 1][n + 1][2];
            for (int a[][][] : dp) for (int[][] b : a) for (int[] c : b) Arrays.fill(c, -1);
            int ans = go(g, 0, even, odd, 0);
            ans = Math.min(go(g, 0, even, odd, 1), ans);
            out.println(ans);
        }

        int go(int[] g, int s, int e, int o, int l) {
            if (s == g.length) return 0;
            if (dp[s][e][o][l] != -1) return dp[s][e][o][l];
            if (g[s] != 0) {
                int t = g[s] % 2;
                int ans = go(g, s + 1, e, o, t);
                if (l != t) ans++;
                return dp[s][e][o][l] = ans;
            }
            int ans = 100000;
            if (e > 0) {
                ans = go(g, s + 1, e - 1, o, 0);
                if (l == 1) ans++;
            }
            if (o > 0) {
                int t = 0;
                if (l == 0) t++;
                ans = Math.min(ans, go(g, s + 1, e, o - 1, 1) + t);
            }
            return dp[s][e][o][l] = ans;
        }
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null)
                return filter.isSpaceChar(c);
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int[] readIntArray(int size) {
            int[] ans = new int[size];
            for (int i = 0; i < size; i++) ans[i] = readInt();
            return ans;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }
    }
}

