const int MAX = 101;

int dp[3][MAX][MAX][MAX];
int n;
vector<int> arr;
int tot_odd;
int tot_even;

int solve(int index, int odd_left, int even_left, int prev_parity) {
    if (index == n) {
        return 0;
    }
    if (dp[prev_parity][odd_left][even_left][index] != -1) {
        return dp[prev_parity][odd_left][even_left][index];
    }
    int res = 0;
    if (arr[index] != 0) {
        int current_parity = (arr[index] % 2 == 1) ? 1 : 2;
        int added = 0;
        if (index > 0) {
            if (prev_parity != current_parity) {
                added = 1;
            }
        }
        res = solve(index+1, odd_left, even_left, current_parity) + added;
    } else {
        int cost_odd = INT_MAX;
        int cost_even = INT_MAX;
        if (odd_left > 0) {
            int placed = 1;
            int added = 0;
            if (index > 0) {
                if (prev_parity != placed) {
                    added = 1;
                }
            }
            cost_odd = solve(index+1, odd_left-1, even_left, placed) + added;
        }
        if (even_left > 0) {
            int placed = 2;
            int added = 0;
            if (index > 0) {
                if (prev_parity != placed) {
                    added = 1;
                }
            }
            cost_even = solve(index+1, odd_left, even_left-1, placed) + added;
        }
        res = min(cost_odd, cost_even);
    }
    return dp[prev_parity][odd_left][even_left][index] = res;
}

