import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static StringBuilder sb = new StringBuilder();
    static int[][][][] dp = new int[3][102][102][102];

    public static void main(String[] args) {
        for (int i = 0; i <= 100; i++) {
            for (int j = 0; j <= 100; j++) {
                for (int k = 0; k <= 100; k++) {
                    dp[0][i][j][k] = -1;
                    dp[1][i][j][k] = -1;
                    dp[2][i][j][k] = -1;
                }
            }
        }
        Scanner sc = new Scanner(System.in);
        int n;
        n = sc.nextInt();
        List<Integer> g = new ArrayList<>();
        int odd = (n + 1) / 2;
        int even = n / 2;
        for (int i = 0; i < n; i++) {
            int ch = sc.nextInt();
            if (ch == 0) {
                g.add(0);
            } else if (ch % 2 == 1) {
                odd--;
                g.add(1);
            } else {
                even--;
                g.add(2);
            }
        }
        int ans = rec(g, odd, even, 0, 0);
        System.out.println(ans);
    }

    public static int rec(List<Integer> g, int odd, int even, int id, int state) {
        int ans = 0;
        if (id < g.size()) {
            if (dp[state][odd][even][id] != -1) {
                return dp[state][odd][even][id];
            }
            int sym = g.get(id);
            if (sym == 0) {
                int case1 = -1, case2 = -1;
                if (odd != 0) {
                    g.set(id, 1);
                    case1 = rec(g, odd - 1, even, id + 1, 1);
                    if (id > 0) {
                        case1 += Math.abs(g.get(id - 1) - 1);
                    }
                    g.set(id, 0);
                }
                if (even != 0) {
                    g.set(id, 2);
                    case2 = rec(g, odd, even - 1, id + 1, 2);
                    if (id > 0) {
                        case2 += Math.abs(g.get(id - 1) - 2);
                    }
                    g.set(id, 0);
                }
                if (case1 != -1 && case2 != -1) {
                    ans = Math.min(case1, case2);
                }
                if (case1 == -1) {
                    ans = case2;
                }
                if (case2 == -1) {
                    ans = case1;
                }
            } else {
                ans += rec(g, odd, even, id + 1, sym);
                if (id > 0) {
                    ans += Math.abs(g.get(id - 1) - sym);
                }
            }
            dp[state][odd][even][id] = ans;
        }
        return ans;
    }
}

