    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new TaskAdapter(), "", 1 << 27);
        thread.start();
        thread.join();
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            FastInput in = new FastInput(inputStream);
            FastOutput out = new FastOutput(outputStream);
            AGarland solver = new AGarland();
            solver.solve(1, in, out);
            out.close();
        }
    }

    static class AGarland {
        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            int[] parity = new int[n + 1];

            int[] unknown = {n / 2, n - n / 2};
            for (int i = 1; i <= n; i++) {
                int x = in.readInt();
                parity[i] = x;
                if (parity[i] != 0) {
                    unknown[parity[i] % 2]--;
                }
            }

            int[][][] dp = new int[n + 1][n + 1][2];
            SequenceUtils.deepFill(dp, (int) 1e8);
            dp[0][0][0] = dp[0][0][1] = 0;
            for (int i = 1; i <= n; i++) {
                int x = parity[i];
                for (int j = 0; j <= n; j++) {
                    for (int k = 0; k < 2; k++) {
                        if (x == 0) {
                            if (j > 0 && k == 0) {
                                dp[i][j][k] = Math.min(dp[i][j][k], dp[i - 1][j - 1][k]);
                                dp[i][j][k] = Math.min(dp[i][j][k], dp[i - 1][j - 1][1 - k] + 1);
                            }
                            if (k == 1) {
                                dp[i][j][k] = Math.min(dp[i - 1][j][k], dp[i][j][k]);
                                dp[i][j][k] = Math.min(dp[i - 1][j][1 - k] + 1, dp[i][j][k]);
                            }
                        } else {
                            if (x % 2 != k) {
                                continue;
                            }
                            dp[i][j][k] = Math.min(dp[i - 1][j][k], dp[i][j][k]);
                            dp[i][j][k] = Math.min(dp[i - 1][j][1 - k] + 1, dp[i][j][k]);
                        }
                    }
                }
            }

            int ans = Math.min(dp[n][unknown[0]][0], dp[n][unknown[0]][1]);
            out.println(ans);
        }

    }

    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

    }

    static class SequenceUtils {
        public static void deepFill(Object array, int val) {
            if (!array.getClass().isArray()) {
                throw new IllegalArgumentException();
            }
            if (array instanceof int[]) {
                int[] intArray = (int[]) array;
                Arrays.fill(intArray, val);
            } else {
                Object[] objArray = (Object[]) array;
                for (Object obj : objArray) {
                    deepFill(obj, val);
                }
            }
        }

    }

    static class FastOutput implements AutoCloseable, Closeable {
        private StringBuilder cache = new StringBuilder(10 << 20);
        private final Writer os;

        public FastOutput(Writer os) {
            this.os = os;
        }

        public FastOutput(OutputStream os) {
            this(new OutputStreamWriter(os));
        }

        public FastOutput println(int c) {
            cache.append(c).append('\n');
            return this;
        }

        public FastOutput flush() {
            try {
                os.append(cache);
                os.flush();
                cache.setLength(0);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return this;
        }

        public void close() {
            flush();
            try {
                os.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        public String toString() {
            return cache.toString();
        }

    }
}

