import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Garland {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());
        int[] a = new int[n + 1];
        boolean[] present = new boolean[n + 1];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 1; i <= n; i++) {
            a[i] = Integer.parseInt(st.nextToken());
            present[a[i]] = true;
        }
        int odd = 0, even = 0;
        for (int i = 1; i <= n; i++) {
            if (!present[i]) {
                if (i % 2 == 0) {
                    even++;
                } else {
                    odd++;
                }
            }
        }

        int dp[][][][] = new int[n + 1][odd + 1][even + 1][2];
        // use a sentinel larger than the maximal possible complexity (n ≤ 100 → max complexity ≤ 99)
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= odd; j++) {
                for (int k = 0; k <= even; k++) {
                    for (int l = 0; l < 2; l++) {
                        dp[i][j][k][l] = 100;
                    }
                }
            }
        }
        dp[0][0][0][1] = dp[0][0][0][0] = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= odd; j++) {
                for (int k = 0; k <= even; k++) {
                    if (a[i] == 0) {
                        if (j >= 1) {
                            dp[i][j][k][1] = Math.min(dp[i - 1][j - 1][k][0] + 1, dp[i - 1][j - 1][k][1]);
                        }
                        if (k >= 1) {
                            dp[i][j][k][0] = Math.min(dp[i - 1][j][k - 1][0], dp[i - 1][j][k - 1][1] + 1);
                        }
                    } else {
                        if (a[i] % 2 == 0) {
                            dp[i][j][k][0] = Math.min(dp[i - 1][j][k][0], dp[i - 1][j][k][1] + 1);
                        } else {
                            dp[i][j][k][1] = Math.min(dp[i - 1][j][k][1], dp[i - 1][j][k][0] + 1);
                        }
                    }
                }
            }
        }
        int ans = Math.min(dp[n][odd][even][0], dp[n][odd][even][1]);
        System.out.println(ans);
    }
}

