public class Main {
    static final int INF = 1000000007;

    public static void main(String[] args) {
        InputReader in = new InputReader();

        int N = in.nextInt();
        if (N == 1) {
            System.out.println(0);
            return;
        }
        int[] p = new int[N + 1];
        int zero = N / 2;
        int one = N / 2 + N % 2;
        for (int i = 1; i <= N; i++) {
            p[i] = in.nextInt();
            if (p[i] == 0) {
                p[i] = -1;
            } else {
                p[i] %= 2;
                if (p[i] == 0) {
                    zero--;
                } else {
                    one--;
                }
            }
        }
        if (zero + one == N) {
            System.out.println(1);
            return;
        }

        int[][][][] dp = new int[N + 1][zero + 1][one + 1][2];
        for (int i = 0; i <= N; i++) {
            for (int j = 0; j <= zero; j++) {
                for (int k = 0; k <= one; k++) {
                    Arrays.fill(dp[i][j][k], INF);
                }
            }
        }
        dp[0][0][0][0] = dp[0][0][0][1] = 0;
        for (int i = 1; i <= N; i++) {
            for (int j = 0; j <= zero; j++) {
                for (int k = 0; k <= one; k++) {
                    if (p[i] == -1) {
                        if (j > 0) {
                            dp[i][j][k][0] = Math.min(dp[i - 1][j - 1][k][0], dp[i - 1][j - 1][k][1] + 1);
                        }
                        if (k > 0) {
                            dp[i][j][k][1] = Math.min(dp[i - 1][j][k - 1][0] + 1, dp[i - 1][j][k - 1][1]);
                        }
                    } else {
                        dp[i][j][k][p[i]] = Math.min(dp[i - 1][j][k][p[i]], dp[i - 1][j][k][1 - p[i]] + 1);
                    }
                }
            }
        }

        System.out.println(Math.min(dp[N][zero][one][0], dp[N][zero][one][1]));
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer st;

        public InputReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(nextLine());
            }
            return st.nextToken();
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return null;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

