import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.List;
import java.util.Random;
import java.util.StringTokenizer;


public class Main implements Runnable {

	int INF = (int) 1e9;
	int sz[];
	int id[];
	List<Integer> edges[];

	BufferedReader br;
	StringTokenizer st;
	PrintWriter pw;

	public static void main(String args[]) {
		new Main().run();
	}

	public void run() {
		try {
			br = new BufferedReader(new InputStreamReader(System.in));
			pw = new PrintWriter(System.out);
			st = null;
			solve();
			pw.flush();
			pw.close();
			br.close();
		} catch (IOException e) {
			e.printStackTrace();
			System.exit(1);
		}
	}

	int nextInt() throws IOException {
		return Integer.parseInt(next());
	}

	long nextLong() throws IOException {
		return Long.parseLong(next());
	}

	double nextDouble() throws IOException {
		return Double.parseDouble(next());
	}

	String next() throws IOException {
		while (st == null || !st.hasMoreTokens()) {
			st = new StringTokenizer(br.readLine());
		}
		return st.nextToken();
	}

	void solve() throws IOException {
		int n = nextInt();
		int[] a = new int[n];
		for (int i = 0; i < n; ++i) {
			a[i] = nextInt();
		}

		// count fixed even numbers (non‑zero and even)
		int fixedEvens = 0;
		for (int x : a) {
			if (x != 0 && x % 2 == 0) {
				++fixedEvens;
			}
		}
		// total number of even numbers in 1..n
		int totalEvens = n / 2;          // floor(n/2)
		// missing even numbers that have to be placed
		int ev = totalEvens - fixedEvens;

		// dp[i][j][k] – minimum complexity after processing first i positions,
		//               having placed j even numbers among the missing ones,
		//               where k is the parity of the i‑th element (0 = even, 1 = odd)
		int[][][] dp = new int[n + 1][n + 1][2];
		for (int i = 0; i <= n; ++i) {
			for (int[] x : dp[i]) {
				Arrays.fill(x, INF);
			}
		}
		// before any element we consider both possible "previous parities"
		dp[0][0][0] = 0;
		dp[0][0][1] = 0;

		for (int i = 1; i <= n; ++i) {
			for (int j = 0; j < i; ++j) {
				for (int k = 0; k < 2; ++k) {
					int t = dp[i - 1][j][k];
					if (t == INF) {
						continue;
					}
					if (a[i - 1] != 0) {                     // fixed bulb
						if (a[i - 1] % 2 == 0) {               // even
							dp[i][j + 1][0] = Math.min(dp[i][j + 1][0],
									t + ((k != 0) ? 1 : 0));
						} else {                               // odd
							dp[i][j][1] = Math.min(dp[i][j][1],
									t + ((k != 1) ? 1 : 0));
						}
					} else {                                   // missing bulb – we may place even or odd
						for (int l = 0; l < 2; ++l) {          // l = parity we place now
							int nj = j + 1 - l;                 // ++j only when l == 0 (even)
							dp[i][nj][l] = Math.min(dp[i][nj][l],
									t + ((k != l) ? 1 : 0));
						}
					}
				}
			}
		}
		pw.println(Math.min(dp[n][ev][0], dp[n][ev][1]));
	}
}

