                    int nextp1 = p1.currChanged;
                    int nextp2 = p2.currChanged;

                    CGarland.pair ans = new CGarland.pair(0, 1);
                    if (nextp1 == 1) {
                        ans.ans = p1.ans;
                    } else if (nextp1 == 0) {
                        ans.ans = p1.ans + 1;
                    } else {
                        ans.ans = p1.ans;
                    }

                    if (nextp2 == 1) {
                        if (ans.ans > p2.ans + 1) {
                            ans.ans = p2.ans + 1;
                            ans.currChanged = 0;
                        } else if (ans.ans == p2.ans + 1) {
                            ans.currChanged = 3;
                        }
                    } else if (nextp2 == 0) {
                        if (ans.ans > p2.ans) {
                            ans.ans = p2.ans;
                            ans.currChanged = 0;
                        } else if (ans.ans == p2.ans) {
                            ans.currChanged = 3;
                        }
                    } else {
                        if (ans.ans > p2.ans) {
                            ans.ans = p2.ans;
                            ans.currChanged = 0;
                        } else if (ans.ans == p2.ans) {
                            ans.currChanged = 3;
                        }
                    }
                    return brr[odd][even][pos] = ans;
                }
            }

        }

        private static class pair {
            int ans;
            int currChanged;

            public pair(int ans, int currChanged) {
                this.ans = ans;
                this.currChanged = currChanged;
            }

            public boolean equals(Object o) {
                if (this == o) return true;
                if (!(o instanceof CGarland.pair)) return false;
                CGarland.pair pair = (CGarland.pair) o;
                return ans == pair.ans &&
                        currChanged == pair.currChanged;
            }

            public int hashCode() {
                return Objects.hash(ans, currChanged);
            }

        }

    }

    static class FastReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private FastReader.SpaceCharFilter filter;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int[] nextIntArray(int n) {
            int[] array = new int[n];
            for (int i = 0; i < n; ++i) array[i] = nextInt();
            return array;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

