    }

    static class TaskC {
        int[][][][] dp;
        int[] a;
        int ans;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int N = in.nextInt();
            dp = new int[N][N][N][2];
            a = new int[N];
            ans = Integer.MAX_VALUE;
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    for (int k = 0; k < N; k++) {
                        Arrays.fill(dp[i][j][k], Constants.INT_INFINITY);
                    }
                }
            }
            int evenRemaining = 0, oddRemaining = 0;
            HashSet<Integer> set = new HashSet<>();
            for (int i = 0; i < N; i++) {
                a[i] = in.nextInt();
                set.add(a[i]);
            }
            for (int i = 1; i <= N; i++) {
                if (!set.contains(i)) {
                    if (i % 2 == 0) {
                        evenRemaining++;
                    } else {
                        oddRemaining++;
                    }
                }
            }
            if (N == 1) {
                out.printLine(0);
                return;
            } else {
                ans = Math.min(recur(0, evenRemaining, oddRemaining, 0), recur(0, evenRemaining, oddRemaining, 1));
            }
            out.printLine(ans);
        }

        public int recur(int index, int evenRemaining, int oddRemaining, int last) {
            if (index >= a.length) {
                return 0;
            }
            if (dp[index][evenRemaining][oddRemaining][last] != Constants.INT_INFINITY) {
                return dp[index][evenRemaining][oddRemaining][last];
            }
            int p = Constants.INT_INFINITY, q = Constants.INT_INFINITY;
            if (a[index] == 0) {
                if (evenRemaining > 0) {
                    p = recur(index + 1, evenRemaining - 1, oddRemaining, 0);
                    if (index != 0 && last != 0) {
                        p++;
                    }
                }
                if (oddRemaining > 0) {
                    q = recur(index + 1, evenRemaining, oddRemaining - 1, 1);
                    if (index != 0 && last != 1) {
                        q++;
                    }
                }
            } else {
                p = recur(index + 1, evenRemaining, oddRemaining, a[index] % 2);
                if (index != 0 && last != (a[index] % 2)) {
                    p++;
                }
            }
            return dp[index][evenRemaining][oddRemaining][last] = Math.min(p, q);
        }

    }

    static class Constants {
        public static final Integer INT_INFINITY = (int) 2e9;

    }

