import java.io.*;
import java.util.*;

public class TaskC {
    private static final int INF = 1 << 30;

    public static void main(String[] args) throws Exception {
        MyReader in = new MyReader(new InputStreamReader(System.in));
        int n = in.nextInt();
        int[] arr = in.readIntArray(n);
        if (n == 1) {
            System.out.println(0);
            return;
        }

        // Find missing numbers and count evens/odds among them
        boolean[] present = new boolean[n + 1];
        for (int v : arr) if (v != 0) present[v] = true;
        int missingEven = 0, missingOdd = 0;
        for (int v = 1; v <= n; v++) {
            if (!present[v]) {
                if (v % 2 == 0) missingEven++;
                else missingOdd++;
            }
        }

        // memo[idx][eUsed][oUsed][prevParityCode]
        // prevParityCode: 0=even,1=odd,2=none (no previous element yet)
        int[][][][] memo = new int[n][missingEven + 1][missingOdd + 1][3];
        for (int[][][] a : memo) for (int[][] b : a) for (int[] c : b) Arrays.fill(c, -1);

        int answer = dfs(0, 0, 0, 2, arr, missingEven, missingOdd, memo);
        System.out.println(answer);
    }

    private static int dfs(int idx, int usedEven, int usedOdd, int prevParityCode,
                           int[] arr, int missEven, int missOdd, int[][][][] memo) {
        if (idx == arr.length) return 0;
        if (memo[idx][usedEven][usedOdd][prevParityCode] != -1) return memo[idx][usedEven][usedOdd][prevParityCode];

        int best = INF;
        int prevParity = (prevParityCode == 2) ? -1 : prevParityCode; // -1 means “no previous”

        if (arr[idx] != 0) {
            int p = arr[idx] % 2;                     // 0 = even, 1 = odd
            int cost = (prevParity == -1) ? 0 : (prevParity != p ? 1 : 0);
            best = cost + dfs(idx + 1, usedEven, usedOdd, p, arr, missEven, missOdd, memo);
        } else {
            // try placing an even number
            if (usedEven < missEven) {
                int p = 0;
                int cost = (prevParity == -1) ? 0 : (prevParity != p ? 1 : 0);
                best = Math.min(best, cost + dfs(idx + 1, usedEven + 1, usedOdd, p, arr, missEven, missOdd, memo));
            }
            // try placing an odd number
            if (usedOdd < missOdd) {
                int p = 1;
                int cost = (prevParity == -1) ? 0 : (prevParity != p ? 1 : 0);
                best = Math.min(best, cost + dfs(idx + 1, usedEven, usedOdd + 1, p, arr, missEven, missOdd, memo));
            }
        }
        memo[idx][usedEven][usedOdd][prevParityCode] = best;
        return best;
    }

    static class MyReader {
        private final BufferedReader bf;
        private StringTokenizer st;

        MyReader(Reader reader) {
            bf = new BufferedReader(reader);
            st = null;
            readNextLine();
        }

        String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) readNextLine();
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        int[] readIntArray(int n) throws IOException {
            int[] a = new int[n];
            for (int i = 0; i < n; ++i) a[i] = nextInt();
            return a;
        }

        private void readNextLine() throws IOException {
            String line = bf.readLine();
            if (line == null) line = "";
            st = new StringTokenizer(line);
        }
    }
}

