    static class Task {
        static int n;
        static int[][][][] dp;
        static int[] res;

        public void solve(int testNumber, FastReader scan, PrintWriter out) {
            n = scan.nextInt();
            res = new int[n];
            boolean[] u = new boolean[n+1];
            int[] c = new int[2];
            for(int i = 0; i < n; i++) u[res[i] = scan.nextInt()] = true;
            for(int i = 1; i <= n; i++) if(!u[i]) c[i%2]++;
            dp = new int[n][c[0]+1][c[1]+1][3];
            for(int i = 0; i < n; i++) {
                for(int j = 0; j < dp[0].length; j++) {
                    for(int k = 0; k < dp[0][0].length; k++) {
                        Arrays.fill(dp[i][j][k], -1);
                    }
                }
            }
            out.println(go(0, c[0], c[1], 2));
        }

        static int go(int index, int a, int b, int c) {
            if(index >= n) return 0;
            if(dp[index][a][b][c] != -1) return dp[index][a][b][c];
            int now = 0;
            if(res[index] != 0) {
                if(c != 2 && c != res[index]%2) now++;
                now += go(index+1, a, b, res[index]%2);
            }
            else {
                int aa = 100000, bb = 100000;
                if(a > 0) {
                    aa = 0;
                    if(c == 1) aa++;
                    aa += go(index+1, a-1, b, 0);
                }
                if(b > 0) {
                    bb = 0;
                    if(c == 0) bb++;
                    bb += go(index+1, a, b-1, 1);
                }
                now = Math.min(aa, bb);
            }
            return dp[index][a][b][c] = now;
        }

    }

