				out = Math.min(out, cost + go(idx + 1, num0 - 1, num1, 0));
			}
			if (num1 > 0) {
				int cost = (prev == 2 ? 0 : (1 == prev ? 0 : 1));
				out = Math.min(out, cost + go(idx + 1, num0, num1 - 1, 1));
			}
		}
