public class c {
    static int n;
    static int[] arr;
    static boolean[] have;
    static int[][][][] dp;
    public static void main(String[] args) {
        FS sc = new FS();
        n = sc.nextInt();
        arr = new int[n];
        have = new boolean[n + 1];
        for (int i = 0; i < n; ++i) {
            arr[i] = sc.nextInt();
            have[arr[i]] = true;
        }

        int num0 = 0, num1 = 0;
        for (int i = 1; i <= n; ++i) {
            if (!have[i]) {
                if (i % 2 == 0) ++num0;
                else ++num1;
            }
        }

        dp = new int[n + 1][num0 + 1][num1 + 1][3];
        for (int[][][] z : dp) {
            for (int[][] y : z) {
                for (int[] x : y) Arrays.fill(x, -1);
            }
        }

        int out = go(0, num0, num1, 2);
        System.out.println(out);
    }
    static int go(int idx, int num0, int num1, int prev) {
        if (dp[idx][num0][num1][prev] != -1) return dp[idx][num0][num1][prev];

        if (idx == n) return dp[idx][num0][num1][prev] = 0;

        int out = -1;
        if (arr[idx] != 0) {
            out = (arr[idx] % 2 == prev ? 0 : 1) + go(idx + 1, num0, num1, arr[idx] % 2);
        } else {
            int eve = 1000;
            if (num0 > 0) eve = (0 == prev ? 0 : 1) + go(idx + 1, num0 - 1, num1, 0);
            int odd = Integer.MAX_VALUE / 2;
            if (num1 > 0) odd = (1 == prev ? 0 : 1) + go(idx + 1, num0, num1 - 1, 1);

            out = Math.min(eve, odd);
        }

        if (prev == 2) --out;
        return dp[idx][num0][num1][prev] = out;
    }
    static class FS {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");
        String next() {
            while (!st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {}
            }
            return st.nextToken();
        }
        int nextInt() {
            return Integer.parseInt(next());
        }
        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

