        boolean ex = canExit(i+1,j) | canExit(i,j+1) | canExit(i-1,j) | canExit(i,j-1);
        if(ex)
        {
            mark(i+1,j);
            mark(i,j+1);
            mark(i-1,j);
            mark(i,j-1);
        }
        return ex;
    }
    public static void vis(int i, int j)
    {
        if(i<0 || j<0 || i>=n || j>=m)
            return;
        if(arr[i][j]==1)
            return;
        if(vis[i][j]==1)
            return;
        vis[i][j]=1;
        vis(i+1,j); vis(i,j+1); vis(i-1,j); vis(i,j-1);
    }
    public static void mark(int i, int j)
    {
        if(i>=0 && j>=0 && i<n && j<m && arr[i][j]!=1)
        {
            vis[i][j]=1;
            exit[i][j]=1;
        }
    }
