               return false;
            if(arr[i-1][j]=='.')
               arr[i-1][j] = '#';
        }
        if(i>=0 && i<n-1 && j>=0 && j<m){
            if(arr[i+1][j]=='G')
               return false;
            if(arr[i+1][j]=='.')
               arr[i+1][j] = '#';
        }
        if(i>=0 && i<n && j>=1 && j<m){
            if(arr[i][j-1]=='G')
               return false;
            if(arr[i][j-1]=='.')
               arr[i][j-1] = '#';
        }
        if(i>=0 && i<n && j>=0 && j<m-1){
            if(arr[i][j+1]=='G')
               return false;
            if(arr[i][j+1]=='.')
               arr[i][j+1] = '#';
        }
        return true;

    }
    public static void dfs(boolean [][]vis, int i, int j, char [][]arr, int n, int m)
    {
        if(i<0 || i>=n || j<0 || j>=m || arr[i][j]=='#' || vis[i][j])
            return;
        vis[i][j] = true;

        dfs(vis, i-1, j, arr, n, m);
        dfs(vis, i, j-1, arr, n, m);
        dfs(vis, i+1, j, arr, n, m);
        dfs(vis, i, j+1, arr, n, m);
    }
	public static void main(String[] args) {
		FastScanner sc=new FastScanner();
		PrintWriter out=new PrintWriter(System.out);

		int test = sc.nextInt();
