    		    for(int j=0;j<m;j++)
    		      arr[i][j] = str.charAt(j);
    		}
    		boolean flag=false, isG=false;   
    		for(int i=0;i<n;i++)
    		{
    		    for(int j=0;j<m;j++)
    		    {
    		        if(arr[i][j] == 'G')
    		           isG=true;
    		        if(arr[i][j] == '#')
    		           continue;
    		        else if(arr[i][j] == 'B'){
    		            if(!recur(arr, i, j, n, m)){
    		                flag=true;
    		                break;
    		            }
    		        }     
    		    }
    	        if(flag)
    	      break;
    		}
    		if(arr[n-1][m-1] == '#' && isG)
    	   flag=true;


    		if(flag){
    		out.println("No");
    		continue;
    		}
    		boolean [][]vis = new boolean[n][m];
    		dfs(vis, n-1, m-1, arr, n, m);

