                        dq.add(n * m - 1);

                        while (!dq.isEmpty()) {
                              int u = dq.poll();
                              for (int v : list[u]) {
                                    if (dis[v] == -1) {
                                          dis[v] = dis[u] + 1;
                                          dq.addLast(v);
                                    }
                              }
                        }

                        for (int i = 0; i < n * m; i++) {
                              int x = i / m;
