public class A {
	public static void main(String[] args) {
		FastScanner sc = new FastScanner();
		int t = sc.nextInt();
		for (int test = 0; test < t; test++) {
			int n = sc.nextInt(), m = sc.nextInt();
			char[][] a = new char[n][m];
			final int[] DELTAX = {-1, 1, 0, 0}, DELTAY = {0, 0, -1, 1};
			for (int i = 0; i < n; i++) {
				String s = sc.next();
				for (int j = 0; j < m; j++) {
					a[i][j] = s.charAt(j);
				}
			}
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					if (a[i][j] == 'B') {
						for (int pos = 0; pos < 4; pos++) {
							int newi = i+DELTAX[pos];
							int newj = j+DELTAY[pos];
							if (newi<n&&newi>=0&&newj<m&&newj>=0&&a[newi][newj]=='.') {

								a[newi][newj] = '#';
							}
						}
					}
				}
			}
			boolean[][]	isVisited = new boolean[n+5][m+5];
			Deque<Position> st = new ArrayDeque<>();
			if (a[n-1][m-1] != '#') {
				st.add(new Position(n-1, m-1));
				isVisited[n-1][m-1] = true;
			}
			while (!st.isEmpty()) {
				Position p = st.pop();
				for (int i = 0; i < 4; i++) {
					int newx = p.x+DELTAX[i];
					int newy = p.y+DELTAY[i];
					if (newx<n&&newx>=0&&newy<m&&newy>=0) {
						if (a[newx][newy]!='#'&&!isVisited[newx][newy]) {
							st.add(new Position(newx, newy));
							isVisited[newx][newy] = true;
						}
					}
				}
			}
			boolean ans = true;
			for (int i = 0; i < n; i++){
				for (int j = 0; j < m; j++) {
					if ((a[i][j] == 'G' && !isVisited[i][j]) || 
					(a[i][j] == 'B' && isVisited[i][j])) {
						ans = false;
						break;
					}
				}
			}
			if (ans) {
				System.out.println("Yes");
			} else {
				System.out.println("No");
			}
		}
	}

