public class Codechef {
    static class Pair {
        int x;
        int y;
        Pair ( int y,int x) {
            this.x = x;
            this.y = y;
        }
    }
    static int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    public static void main(String[] args) throws java.lang.Exception {
        out = new PrintWriter(new BufferedOutputStream(System.out));
        sc = new FastReader();
        int test = sc.nextInt();
        for (int t = 0; t < test; t++) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] arr = new char[n][m];
            for (int i = 0; i < n; i++) {
                arr[i] = sc.next().toCharArray();
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (arr[i][j] == 'B') {
                        for (int[] dir : directions) {
                            int x = dir[0] + i;
                            int y = dir[1] + j;
                            if (valid(x, y, n, m) && arr[x][y] == '.') {
                                arr[x][y] = '#';
                            }
                        }
                    }
                }
            }
            Queue<Pair> queue = new LinkedList<>();
            boolean[][] visited = new boolean[n][m];
            if (arr[n - 1][m - 1] == '.'){
                queue.add(new Pair(m - 1, n - 1));
                visited[n - 1][m - 1] = true;
            }
            while (!queue.isEmpty()) {
                Pair curr = queue.poll();
                for (int[] dir : directions) {
                    int x = dir[0] + curr.x;
                    int y = dir[1] + curr.y;
                    if (valid(x, y, n, m) && !visited[x][y] && arr[x][y] != '#') {
                        queue.add(new Pair(x, y));
                        visited[x][y] = true;
                    }
                }
            }
            boolean ok = true;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (arr[i][j] == 'G' && !visited[i][j]) {
                        ok = false;
                        break;
                    }
                    if (arr[i][j] == 'B' && visited[i][j]) {
                        ok = false;
                        break;
                    }
                }
            }
            if (ok) {
                out.println("Yes");
            }else {
                out.println("No");
            }
        }
        out.close();
    }

    private static boolean valid(int x, int y, int n, int m) {
        if (x >= 0 && x < n && y >= 0 && y < m) {
            return true;
        }
        return false;
    }

    public static FastReader sc;
    public static PrintWriter out;
    static class FastReader
    {
        BufferedReader br;
        StringTokenizer st;

        public FastReader()
        {
            br = new BufferedReader(new
                    InputStreamReader(System.in));
        }

        String next()
        {
            while (st == null || !st.hasMoreElements())
            {
                try
                {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException  e)
                {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt()
        {
            return Integer.parseInt(next());
        }

        long nextLong()
        {
            return Long.parseLong(next());
        }

        double nextDouble()
        {
            return Double.parseDouble(next());
        }

        String nextLine()
        {
            String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public void solve(InputProvider in, PrintWriter out) throws IOException {
        int testCount = in.nextInt();
        for (int test = 0; test < testCount; test++) {
            int rowCount = in.nextInt();
            int columnCount = in.nextInt();
            int[][] map = new int[rowCount][columnCount];
            Set<Position> badPositions = new HashSet<>();
            Set<Position> goodPositions = new HashSet<>();
            for (int row = 0; row < map.length; row++) {
                String rowDescription = in.nextLine();
                for (int column = 0; column < map[row].length; column++) {
                    map[row][column] = rowDescription.charAt(column);
                    if (map[row][column] == 'B') {
                        badPositions.add(new Position(row, column));
                    }
                    if (map[row][column] == 'G') {
                        goodPositions.add(new Position(row, column));
                    }
                }
            }
            map[map.length - 1][map[0].length - 1] = 'D';
            boolean can;
            if (goodPositions.isEmpty()) {
                can = true;
            } else {
                boolean badBlocked = true;
                for (Iterator<Position> iterator = badPositions.iterator(); iterator.hasNext() && badBlocked; ) {
                    Position badPosition = iterator.next();
                    badBlocked = tryBlock(map, badPosition);
                }
                if (!badBlocked) {
                    can = false;
                } else {
                    findWay(map);
                    can = true;
                    for (Iterator<Position> iterator = goodPositions.iterator(); iterator.hasNext() && can; ) {
                        Position goodPosition = iterator.next();
                        can = map[goodPosition.row][goodPosition.column] == 'D';
                    }
                }
            }
            out.print(can ? "Yes\n" : "No\n");
        }
    }

    private static class Position {

        private final int row;
        private final int column;

        private Position(int row, int column) {
            this.row = row;
            this.column = column;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, column);
        }

        @Override
        public boolean equals(Object obj) {
            return (obj instanceof Position) && (((Position) obj).row == row) && (((Position) obj).column == column);
        }

    }

    private static boolean tryBlock(int[][] map, Position position) {
        boolean canBlock = true;
        for (int row = Math.max(0, position.row - 1);
             row <= Math.min(position.row + 1, map.length - 1) && canBlock; row++) {
            canBlock = map[row][position.column] != 'G' && map[row][position.column] != 'D';
            map[row][position.column] = '#';
        }
        for (int column = Math.max(0, position.column - 1);
             column <= Math.min(position.column + 1, map[position.row].length - 1) && canBlock; column++) {
            canBlock = map[position.row][column] != 'G' && map[position.row][column] != 'D';
            map[position.row][column] = '#';
        }
        return canBlock;
    }

    private static void findWay(int[][] map) {
        findWay(map, map.length - 1, map[0].length - 1);
    }

    private static void findWay(int[][] map, int row, int column) {
        map[row][column] = 'D';
        if (row - 1 >= 0 && map[row - 1][column] != '#' && map[row - 1][column] != 'D') {
            findWay(map, row - 1, column);
        }
        if (row + 1 < map.length && map[row + 1][column] != '#' && map[row + 1][column] != 'D') {
            findWay(map, row + 1, column);
        }
        if (column - 1 >= 0 && map[row][column - 1] != '#' && map[row][column - 1] != 'D') {
            findWay(map, row, column - 1);
        }
        if (column + 1 < map[0].length && map[row][column + 1] != '#' && map[row][column + 1] != 'D') {
            findWay(map, row, column + 1);
        }
    }

    public static void main(String[] args) throws Exception {
        try (InputProvider input = new InputProvider(System.in);
             PrintWriter output = new PrintWriter(System.out)) {
            new Main().solve(input, output);
        }
    }

    public static class InputProvider implements AutoCloseable {

        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputProvider(Reader reader) {
            this.reader = new BufferedReader(reader);
        }

        public InputProvider(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            if (Objects.isNull(tokenizer) || !tokenizer.hasMoreTokens())
                tokenizer = new StringTokenizer(reader.readLine());
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        public String nextLine() throws IOException {
            return reader.readLine();
        }

        @Override
        public void close() throws Exception {
            reader.close();
        }

    }

}

