            char[][] ch = new char[n][m];
            for (int j=0;j<n;j++){
                str[j] = input.next();
                for (int k=0;k<m;k++){
                    ch[j][k] = str[j].charAt(k);
                    if (str[j].charAt(k) == 'G') g++;
                }
            }
            for (int j=0;j<n;j++){
                for (int k=0;k<m;k++){
                    if (ch[j][k] == 'B'){
                        for (int l=0;l<4;l++){
                            int fx = j + dir[l][0];
                            int fy = k + dir[l][1];
                            if (fx<0||fx>=n||fy<0||fy>=m) continue;
                            if (ch[fx][fy] == 'G'){
                                flag = false;
                                break;
                            } else if (ch[fx][fy] == '.'){
                                ch[fx][fy] = '#';
                            }
                        }
                    }
                    if (!flag) break;
                }
