import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

public class D1365 {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int t = in.nextInt();

        int[] dx = { 1, -1, 0, 0 };
        int[] dy = { 0, 0, 1, -1 };
        while (t-- > 0) {
            int n = in.nextInt();
            int m = in.nextInt();
            int[][] grid = new int[n][m];
            int goodCount1 = 0;

            for (int i = 0; i < n; i++) {
                String str = in.next();
                for (int j = 0; j < m; j++) {
                    if (str.charAt(j) == '.') {
                        grid[i][j] = 0;
                    } else if (str.charAt(j) == '#') {
                        grid[i][j] = 1;
                    } else if (str.charAt(j) == 'G') {
                        grid[i][j] = 2;
                        goodCount1++;
                    } else {
                        grid[i][j] = 3;
                    }
                }
            }
            // Block empty cells around bad people
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 3) {
                        for (int k = 0; k < 4; k++) {
                            int ni = i + dx[k];
                            int nj = j + dy[k];
                            if (ni < 0 || ni >= n || nj < 0 || nj >= m) continue;
                            if (grid[ni][nj] == 0) {
                                grid[ni][nj] = 1;
                            }
                        }
                    }
                }
            }

            if (grid[n - 1][m - 1] == 1) {
                // Exit is blocked
                if (goodCount1 == 0) {
                    System.out.println("Yes");
                } else {
                    System.out.println("No");
                }
            } else {
                Queue<Pair> queue = new LinkedList<>();
                boolean[][] visited = new boolean[n][m];
                // Mark the exit as visited before starting BFS
                visited[n - 1][m - 1] = true;
                queue.add(new Pair(n - 1, m - 1));
                boolean bad = false;
                int goodCount2 = 0;
                while (!queue.isEmpty()) {
                    Pair current = queue.poll();
                    for (int k = 0; k < 4; k++) {
                        int nx = current.x + dx[k];
                        int ny = current.y + dy[k];
                        if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
                        if (visited[nx][ny]) continue;
                        if (grid[nx][ny] == 1) continue;
                        if (grid[nx][ny] == 3) {
                            bad = true;
                            queue.clear();
                            break;
                        } else if (grid[nx][ny] == 2) {
                            goodCount2++;
                        }
                        queue.add(new Pair(nx, ny));
                        visited[nx][ny] = true;
                    }
                }
                if (bad) {
                    System.out.println("No");
                } else if (goodCount1 == goodCount2) {
                    System.out.println("Yes");
                } else {
                    System.out.println("No");
                }
            }
        }
    }
}

