public class Solve {
    FastScanner in;
    PrintWriter out;

    static final int[] dy = {0, 0, -1, 1};
    static final int[] dx = {1, -1, 0, 0};

    static boolean inBounds(int row, int col, int rows, int cols) {
        return (0 <= row &&
                0 <= col &&
                row < rows &&
                col < cols);
    }

    static class Point {
        int row, col;
        Point(int r, int c) {
            row = r;
            col = c;
        }
    }

    void solve() {
        int T = in.nextInt();
        while (T-- > 0) {
            int rows = in.nextInt();
            int cols = in.nextInt();
            char[][] maze = new char[rows][cols];
            for (int row = 0; row < rows; row++) {
                maze[row] = in.next().toCharArray();
            }

            int totalGood = 0;
            for (int row = 0; row < rows; row++) {
                for (int col = 0; col < cols; col++) {
                    if (maze[row][col] == 'B') {
                        for (int d = 0; d < 4; d++) {
                            int drow = row + dy[d];
                            int dcol = col + dx[d];
                            if (inBounds(drow, dcol, rows, cols) &&
                                maze[drow][dcol] == '.') {

                                maze[drow][dcol] = '#';
                            }

                        }

                    } else if (maze[row][col] == 'G') {
                        totalGood++;
                    }
                }
            }










            LinkedList<Point> bfs = new LinkedList<>();
            boolean[][] seen = new boolean[rows][cols];

            if (maze[rows-1][cols-1] == '.') {
                bfs.add(new Point(rows-1, cols-1));
                seen[rows-1][cols-1] = true;
            }

            int foundGood = 0;
            int foundBad = 0;
            while ( ! bfs.isEmpty()) {
                Point currPoint = bfs.poll();
                char curr = maze[currPoint.row][currPoint.col];

                if (curr == 'G') {
                    foundGood++;
                } else if (curr == 'B') {
                    foundBad++;
                }

                for (int d = 0; d < 4; d++) {
                    int drow = currPoint.row + dy[d];
                    int dcol = currPoint.col + dx[d];
                    if (inBounds(drow, dcol, rows, cols) &&
                        ! seen[drow][dcol] &&
                        maze[drow][dcol] != '#') {

                        bfs.add(new Point(drow, dcol));
                        seen[drow][dcol] = true;
                    }
                }
            }


            out.println((foundGood == totalGood && foundBad == 0) ? "Yes" : "No");
        }
    }

    void run() {
        try {
            in = new FastScanner(new File("Solve.in"));
            out = new PrintWriter(new File("Solve.out"));

            solve();

            out.close();
        } catch (FileNotFoundException e) {
