		Pair(int x, int y) {
			this.x = x;
			this.y = y;
		}
	}

	public static boolean bfs(Pair p) {
		Queue<Pair> q = new LinkedList<>();
		chk[p.x][p.y] = true;
		q.offer(p);
		while (!q.isEmpty()) {
			p = q.poll();
			for (int i = 0; i < 4; i++) {
				int nx = p.x + dx[i];
				int ny = p.y + dy[i];
				if (chk[nx][ny]) {
					continue;
				}
				switch (maze[nx][ny]) {
				case '.':
					maze[nx][ny] = '#';
					break;
				case '#':
					break;
				case 'G':
					chk[nx][ny] = true;
					q.offer(new Pair(nx, ny));
					break;
				case 'B':
					chk[nx][ny] = true;
					q.offer(new Pair(nx, ny));
					break;
				}
			}
		}
		return true;
	}

	public static boolean bfs2(Pair p) {
		if (maze[p.x][p.y] == '#') {
			return good_check();
		}
		for (int i = 1; i <= N; i++) {
			Arrays.fill(chk[i], false);
		}
		Queue<Pair> q = new LinkedList<>();
		chk[p.x][p.y] = true;
		q.offer(p);
		while (!q.isEmpty()) {
			p = q.poll();
			for (int i = 0; i < 4; i++) {
				int nx = p.x + dx[i];
				int ny = p.y + dy[i];
				if (chk[nx][ny]) {
					continue;
				}
				switch (maze[nx][ny]) {
				case '.':
					chk[nx][ny] = true;
					q.offer(new Pair(nx, ny));
					break;
				case '#':
					break;
				case 'G':
					chk[nx][ny] = true;
					q.offer(new Pair(nx, ny));
					break;
				case 'B':
					return false;
				}
			}
		}
		return good_check();
	}

	public static boolean good_check() {
		for (int i = 1; i <= N; i++) {
			for (int j = 1; j <= M; j++) {
				if (maze[i][j] == 'G' && !chk[i][j]) {
					return false;
				}
			}
		}
		return true;
	}

