import java.util.StringTokenizer;

public class DD {

	public static int count = 0;

	public static void main(String[] args) throws IOException {
		BufferedReader file = new BufferedReader(new InputStreamReader(System.in));
		int inputs = Integer.parseInt(file.readLine());
		while(!(inputs-->0)) {
			StringTokenizer st = new StringTokenizer(file.readLine());
			int rows = Integer.parseInt(st.nextToken());
			int cols = Integer.parseInt(st.nextToken());
			char[][] mat = new char[rows][cols];
			boolean[][] blocked = new boolean[rows][cols];
			for(int r = 0; r < rows; r++) {
				mat[r] = file.readLine().toCharArray();
			}
			int goodCount = 0;
			for(int r = 0; r < rows; r++) {
				for(int c = 0; c < cols; c++) {
					if(mat[r][c] == '#') {
						blocked[r][c] = true;
					}
					else if(mat[r][c] == 'B') {
						blocked[r][c] = true;
						if(r > 0 && mat[r-1][c] == '.') blocked[r-1][c] = true;
						if(c > 0 && mat[r][c-1] == '.') blocked[r][c-1] = true;
						if(r < rows-1 && mat[r+1][c] == '.') blocked[r+1][c] = true;
						if(c < cols-1 && mat[r][c+1] == '.') blocked[r][c+1] = true;
					}
					else if(mat[r][c] == 'G') {
						goodCount++;
					}
				}
			}
			count = 0;
			search(rows-1, cols-1, blocked, new boolean[rows][cols], mat);
			System.out.println(count == goodCount ? "Yes" : "No");
		}
	}

	public static void search(int r, int c, boolean[][] blocked, boolean[][] visited, char[][] mat) {
		if(r < 0 || c < 0 || r >= blocked.length || c >= blocked[r].length)
			return;
		if(visited[r][c] || blocked[r][c])
			return;
		visited[r][c] = true;
		if(mat[r][c] == 'G') {
			count++;
		}
		search(r-1, c, blocked, visited, mat);
		search(r+1, c, blocked, visited, mat);
		search(r, c-1, blocked, visited, mat);
		search(r, c+1, blocked, visited, mat);
	}

}

