import java.io.*;
import java.util.Arrays;

public class D2 { 

    static int[] dr = {1 , -1, 0, 0};
    static int[] dc = {0, 1, 0, -1};
    static int[][] grid = new int[52][52]; 

    public static void main(String[] args) {
        try {
            BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
            BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
            int testCnt = Integer.parseInt(br.readLine());
            Arrays.fill(grid[0], 1);
            for (int i = 0; i < testCnt; i++) {
                String[] line = br.readLine().split(" ");
                int rowCnt = Integer.parseInt(line[0]);
                int colCnt = Integer.parseInt(line[1]);

                for (int j = 1; j <= rowCnt; j++) {
                    Arrays.fill(grid[j], 0);
                    grid[j][0] = 1;
                    grid[j][colCnt + 1] = 1;
                }
                Arrays.fill(grid[rowCnt + 1], 1);

                int gCnt = 0;
                for (int j = 0; j < rowCnt; j++) {
                    String curRow = br.readLine();
                    for (int k = 0; k < colCnt; k++) {
                        char cur = curRow.charAt(k);
                        if (cur == '#') grid[j + 1][k + 1] = 1;
                        else if (cur == 'G') {
                            if (grid[j + 1][k + 1] == 0) grid[j + 1][k + 1] = 2;
                            gCnt++;
                        }
                        else if (cur == 'B') {
                            for (int l = 0; l < 4; l++) {
                                int nr = j + 1 + dr[l];
