public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskD solver = new TaskD();
        int testCount = Integer.parseInt(in.next());
        for (int i = 1; i <= testCount; i++)
            solver.solve(i, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            char[][] maze = in.readCharMatrix(n, m);

            GridConditions grid = new GridConditions(n, m);

            IntPair escape = IntPair.newPair(n - 1, m - 1);

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++)
                    if (maze[i][j] == 'B') {
                        List<IntPair> emptyOrGood = grid.neighbours(IntPair.newPair(i, j), (i1, j1) -> maze[i1][j1] == '.' || maze[i1][j1] == 'G');
                        for (IntPair cell : emptyOrGood) {
                            if (isGood(maze, cell)) {
                                out.No();
                                return;
                            }
                            maze[cell.first][cell.second] = '#';
                        }
                    }
            }


            boolean[][] seen = new boolean[n][m];
            if (maze[n - 1][m - 1] != '#')
                dfs(escape, seen, grid, (i, j) -> !seen[i][j] && maze[i][j] != '#');

            for (IntPair good : getPeople(n, m, maze, 'G')) {
                if (!seen[good.first][good.second]) {
                    out.No();
                    return;
                }
            }
            out.Yes();
        }

        private void dfs(IntPair node, boolean[][] seen, GridConditions grid, BiPredicate<Integer, Integer> isAvailable) {
            seen[node.first][node.second] = true;
            grid.neighbours(node, isAvailable).forEach(neighbor -> dfs(neighbor, seen, grid, isAvailable));
        }

        private boolean isGood(char[][] maze, IntPair pair) {
            return maze[pair.first][pair.second] == 'G';
        }

        private List<IntPair> getPeople(int n, int m, char[][] maze, char type) {
            List<IntPair> cells = new LinkedList<>();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (maze[i][j] == type) {
                        cells.add(IntPair.newPair(i, j));
                    }
                }
            }
            return cells;
        }

    }

    static class GridConditions {
        public static int[] rowDelta = {-1, 0, 1, 0};
        public static int[] columnDelta = {0, 1, 0, -1};
        private int rows;
        private int cols;
        private List<IntPair> tempList;
        private IntPair[] tempPair;

        public GridConditions(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;

            this.tempList = new LinkedList<>();
            this.tempPair = new IntPair[4];

            for (int i = 0; i < tempPair.length; ++i)
                tempPair[i] = IntPair.newPair();
        }

        public boolean withinBorders(int row, int col) {
            return 0 <= row && row < rows
                    && 0 <= col && col < cols;
        }

        public List<IntPair> neighbours(IntPair cell, BiPredicate<Integer, Integer> available) {
            LinkedList<IntPair> tempList = new LinkedList<>();
            int i = cell.first;
            int j = cell.second;
            for (int k = 0; k < rowDelta.length; k++) {
                int row = i + rowDelta[k];
                int col = j + columnDelta[k];

                if (withinBorders(row, col) && available.test(row, col)) {
                    tempList.add(IntPair.newPair(row, col));
                }
            }

            return tempList;
        }

    }

    static class IntPair implements Comparable<IntPair> {
        public int first;
        public int second;

        public IntPair(int first, int second) {
            this.first = first;
            this.second = second;
        }

        public int compareTo(IntPair o) {
            if (first != o.first)
                return Integer.compare(first, o.first);
            return Integer.compare(second, o.second);
        }

        public String toString() {
            return first + " " + second;
        }

        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof IntPair)) return false;
            IntPair intPair = (IntPair) o;
            return first == intPair.first &&
                    second == intPair.second;
        }

        public int hashCode() {
            return (31 * first + second);
        }

        public IntPair clone() {
            return newPair(first, second);
        }

        public static IntPair newPair() {
            return new IntPair(0, 0);
        }

        public static IntPair newPair(int first, int second) {
            return new IntPair(first, second);
        }

    }

    static class OutputWriter extends PrintWriter {
        public OutputWriter(OutputStream outputStream) {
            super(outputStream);
        }

        public OutputWriter(Writer writer) {
            super(writer);
        }

        public OutputWriter(String filename) throws FileNotFoundException {
            super(filename);
        }

        public void Yes() {
            println("Yes");
        }

        public void No() {
            println("No");
        }

        public void close() {
            super.close();
        }

    }

