public class Main {
    static int count ;
    static boolean mark [][] ;
    static final int row[]={0,0,1,-1};
    static final int column [] = {1,-1,0,0};
    static int n,m;
    static   String a[][];
    static boolean res;
    static boolean ck(int r, int c){
        if (r >=  n || c >= m) return false ;
        if (r < 0 || c < 0 ) return false ;
        if ( a[r][c].equals("#")) return false ;
        return true;
    }

    static void dfs (int r,int c){
        mark [r][c] = true;
        if (a[r][c].equals("G")) {
            count++;
            for (int i = 0; i < 4 ; i++)
                if (ck (r+row[i],c+column[i]) && a[r + row[i]][c+ column[i]].equals("B"))
                {
                    res = false;
                    return ;
                }
        }

        if (res == false ) return ;


        for (int i = 0; i < 4 ; i++)
        if (ck (r+row[i],c+column[i]) && !mark[r + row[i]][c+ column[i]]  && !a[r+row[i]][c+column[i]].equals("B"))
            dfs (r+row[i],c+ column[i]);
    }

    public static void main(String[] args) {
