            count = 0 ;
            totalG =0 ;
            mark = new boolean[n][m];
            res = true ;
            sc.nextLine();

            for (int i = 0 ; i < n ; i++)
                a[i] = sc.nextLine().split("");

            for (int i = 0 ; i < n ; i++)
                for (int j = 0 ; j< m ; j++)
                    if (a[i][j].equals("G")) totalG ++;
                    else if  ( a[i][j].equals("B"))
                    {
                        for (int q = 0 ; q <4;q++)
                            if (ck(i+row[q],j+column[q]) && a[i+row[q]][j+column[q]].equals("."))
                                a[i+row[q]][j+column[q]] = "#";
                    }

            dfs (n-1,m-1);

            for (int i=0 ; i <4 ; i++)
                if (ck(n-1+row[i],m-1+column[i]) && a[n-1 +row[i]][m-1+column[i]].equals("B") && totalG >0 )
                    res =false ;

            if (res && count == totalG) System.out.println ("Yes");
            else System.out.println("NO");
        }
    }
}

