                    is_pos=false;
                    break;
                }
            }
            ans.append("\n");
            if(!is_pos) {
                break;
            }
        }
        if(!is_pos) {
            System.out.println("NO");
        }
        else {
            System.out.println("YES\n"+ans);
        }
    }
}

