            for (int j = 0; j < m; j++) {
                cin >> a[i][j];
            }
        }

        vector<vector<int>> tar(n, vector<int>(m, 0));
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (i == 0 || i == n-1 || j == 0 || j == m-1) {
                    if ((i == 0 && j == 0) || (i == 0 && j == m-1) || 
                        (i == n-1 && j == 0) || (i == n-1 && j == m-1)) {
                        tar[i][j] = 2;
                    } else {
                        tar[i][j] = 3;
                    }
                } else {
                    tar[i][j] = 4;
                }
            }
        }

        bool valid = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (a[i][j] > tar[i][j]) {
                    valid = false;
                    break;
                }
            }
            if (!valid) break;
        }

