        @Override
        public int compare(Pair x, Pair y) {
            if (x.val < y.val) return -1;
            if (x.val > y.val) return 1;
            if (x.val == y.val) {
                if (x.ind < y.ind) return -1;
                if (x.ind > y.ind) return 1;
            }
            return 0;
        }
    }

