        if (arr[i][j] > 4) return false;
        int cnt = 0;
        if (i > 0 && arr[i - 1][j] > 0) cnt++;
        if (j > 0 && arr[i][j - 1] > 0) cnt++;
        if (i < arr.length - 1 && arr[i + 1][j] > 0) cnt++;
        if (j < arr[0].length - 1 && arr[i][j + 1] > 0) cnt++;
        return cnt == arr[i][j];
    }

