public class Main
{
    public static void main(String[] args)
    {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB
    {
        public void solve(int testNumber, Scanner in, PrintWriter out)
        {
            int T = in.nextInt();
            while (T-- > 0)
            {
                solve(in, out);
            }
        }

        private void solve(Scanner in, PrintWriter out)
        {
            int rows = in.nextInt();
            int columns = in.nextInt();
            int[][] M = new int[rows][columns];
            for (int i = 0; i < rows; i++)
            {
                for (int j = 0; j < columns; j++)
                {
                    M[i][j] = in.nextInt();
                }
            }
            try
            {
                process(M, rows, columns);
                out.println("YES");
                for (int i = 0; i < rows; i++)
                {
                    for (int j = 0; j < columns; j++)
                    {
                        if (j == columns - 1)
                            out.print(M[i][j]);
                        else
                            out.print(M[i][j] + " ");
                    }
                    out.println();
                }
            } catch (Exception e)
            {
                out.println("NO");
            }
        }

        private void process(int[][] M, int rows, int cols) throws Exception
        {
            processRow(0, cols, 2, M);
            processRow(rows - 1, cols, 2, M);
            for (int row = 1; row < rows - 1; row++)
            {
                processRow(row, cols, 3, M);
            }
        }

        private void processRow(int row, int cols, int startNumber, int[][] M) throws Exception
        {
            if (M[row][0] > startNumber) throw new Exception();
            M[row][0] = startNumber;
            if (M[row][cols - 1] > startNumber) throw new Exception();
            M[row][cols - 1] = startNumber;

            for (int col = 1; col < cols - 1; col++)
            {
                if (M[row][col] > startNumber + 1) throw new Exception();
                M[row][col] = startNumber + 1;
            }
        }

    }
}

