    static class BNeighborGrid {
        public void solve(int testNumber, InputReader in, PrintWriter w) {
            int t = in.nextInt();
            gg:
            while (t-- > 0) {
                int n = in.nextInt();
                int m = in.nextInt();

                int[][] a = new int[n][m];
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        a[i][j] = in.nextInt();
                    }
                }

                int[] xx = { -1, 1, 0, 0 };
                int[] yy = { 0, 0, -1, 1 };
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        int cnt = 0;
                        for (int k = 0; k < 4; k++) {
                            if (i + xx[k] >= 0 && i + xx[k] < n && j + yy[k] >= 0 && j + yy[k] < m)
                                cnt++;
                        }

                        if (a[i][j] > cnt) {
                            w.println("NO");
                            continue gg;
                        }

                        a[i][j] = cnt;
                    }
                }

                w.println("YES");
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        w.print(a[i][j] + " ");
                    }
                    w.println();
                }

            }
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();

            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }

                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();

            while (isSpaceChar(c))
                c = read();

            int sgn = 1;

            if (c == '-') {
                sgn = -1;
                c = read();
            }

            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            while (!isSpaceChar(c));

            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null)
                return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

