#include <vector>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n, m;
        cin >> n >> m;
        vector<vector<long long>> arr(n, vector<long long>(m));
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                cin >> arr[i][j];
            }
        }

        // Check if the grid is already good
        bool isGood = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (arr[i][j] > 0) {
                    int count = 0;
                    // Check neighbors: up, down, left, right
                    if (i > 0 && arr[i-1][j] > 0) count++;
                    if (i < n-1 && arr[i+1][j] > 0) count++;
                    if (j > 0 && arr[i][j-1] > 0) count++;
                    if (j < m-1 && arr[i][j+1] > 0) count++;
                    if (count != arr[i][j]) {
                        isGood = false;
                        break;
                    }
                }
            }
            if (!isGood) break;
        }

        if (isGood) {
            cout << "YES\n";
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    cout << arr[i][j];
                    if (j < m-1) cout << " ";
                }
                cout << '\n';
            }
            continue;
        }

        // Original checks from the Java program (translated to C++)
        bool flag = true;
        if (arr[0][0] > 2 || arr[n-1][m-1] > 2 || arr[0][m-1] > 2 || arr[n-1][0] > 2) {
            flag = false;
        }
        if (flag) {
            for (int i = 1; i < n-1; i++) {
                if (arr[i][0] > 3 || arr[i][m-1] > 3) {
                    flag = false;
                    break;
                }
            }
        }
        if (flag) {
            for (int i = 1; i < m-1; i++) {
                if (arr[0][i] > 3 || arr[n-1][i] > 3) {
                    flag = false;
                    break;
                }
            }
        }
        if (flag) {
            for (int i = 1; i < n-1; i++) {
                for (int j = 1; j < m-1; j++) {
                    if (arr[i][j] > 4) {
                        flag = false;
                        break;
                    }
                }
            }
        }

        if (!flag) {
            cout << "NO\n";
        } else {
