    private void load_inputs(final BufferedReader br) throws IOException {
        try (
                PrintWriter pw = select_output();) {
            int t = Integer.valueOf(br.readLine().trim());
            if (t-- > 0) {
                int[] nm = Arrays.stream(br.readLine().trim().split("\\s+")).mapToInt(v -> Integer.valueOf(v)).toArray();
                int[][] a = new int[nm[0]][];
                for (int i = 0; i < nm[0]; i++) {
                    a[i] = Arrays.stream(br.readLine().trim().split("\\s+")).mapToInt(v -> Integer.valueOf(v)).toArray();
                }
                solve(nm[0], nm[1], a, pw);
            }
        }
    }

    private void solve(final int n, final int m, final int[][] a, final PrintWriter pw) {
        boolean res = true;
        boolean changed = true;
        ArrayList<Integer> free = new ArrayList<>();
        l:
        while (changed) {
            changed = false;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if ((i == 0 || i == n - 1) && (j == 0 || j == m - 1) && a[i][j] > 2
                            || (i == 0 || i == n - 1 || j == 0 || j == m - 1) && a[i][j] > 3
                            || a[i][j] > 4) {
                        res = false;
                        break l;
                    }
                    if (a[i][j] > 0) {
                        free.clear();
                        int cnt = 0;
                        if (i - 1 >= 0) {
                            if (a[i - 1][j] > 0) {
                                cnt++;
                            } else {
                                free.add(0);
                            }
                        }
                        if (j - 1 >= 0) {
                            if (a[i][j - 1] > 0) {
                                cnt++;
                            } else {
                                free.add(1);
                            }
                        }
                        if (i + 1 < n) {
                            if (a[i + 1][j] > 0) {
                                cnt++;
                            } else {
                                free.add(2);
                            }
                        }
                        if (j + 1 < m) {
                            if (a[i][j + 1] > 0) {
                                cnt++;
                            } else {
                                free.add(3);
                            }
                        }
                        if (cnt < a[i][j]) {
                            for(int k = 0; k < a[i][j] - cnt; k++) {
                                switch(free.get(k)) {
                                    case 0:
                                        a[i - 1][j] = 1;
                                        break;
                                    case 1:
                                        a[i][j - 1] = 1;
                                        break;
                                    case 2:
                                        a[i + 1][j] = 1;
                                        break;
                                    case 3:
                                        a[i][j + 1] = 1;
                                        break;
                                }
                            }
                            changed = true;
                        } else if (cnt > a[i][j]) {
                            a[i][j] = cnt;
                            changed = true;   // <-- fixed: mark that the grid changed
                        }
                    }
                }
            }
        }
        pw.println(res ? "YES" : "NO");
        if (res) {
            for (int i = 0; i < n; i++) {
                pw.println(Arrays.stream(a[i]).mapToObj(v -> Integer.toString(v)).collect(Collectors.joining(" ")));
            }
        }
    }

