public class BGR9
{
	public static void main(String[] args) {

		Scanner obj=new Scanner(System.in);
		int t=obj.nextInt();
		while(t-->0)
		{
			int n=obj.nextInt();
			int m=obj.nextInt();
			long[][] arr=new long[n][m];

			for(int i=0;i<n;i++)
			{
				for(int j=0;j<m;j++)
				{
					arr[i][j]=obj.nextLong();
				}
			}			
			boolean flag=true;
			for(int i=0;i<n;i++)
			{
				for(int j=0;j<m;j++)
				{
					// compute degree (number of neighboring cells)
					int deg = 0;
					if (i > 0) deg++;
					if (i < n-1) deg++;
					if (j > 0) deg++;
					if (j < m-1) deg++;

					if (arr[i][j] > deg) {
						flag = false;
						break;
					} else {
						// replace the value by its degree (guaranteed reachable by increasing)
						arr[i][j] = deg;
					}
				}
				if (!flag) break;
			}
			if (!flag)
			{
				System.out.println("NO");
			}
			else
			{
				System.out.println("YES");
				for(int i=0;i<n;i++)
				{
					for(int j=0;j<m;j++)
					{
						System.out.print(arr[i][j]+" ");
					}
					System.out.println();
				}
			}
		}
	}
}

