public class Grid{
    boolean checkInc(int[][]gArr,int r, int c){
        boolean retV = false;
        if(gArr[r][c]==0){
            gArr[r][c]++;
            retV = true;
        }
        return retV;
    }

    int[][]updateGrid(int n, int m, int[][]gArr){
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                if(gArr[i][j]>0){
                    boolean cv = checkNBors(n,m,gArr,i,j);
                    if(!cv){
                        return new int[0][0];
                    }
                }
            }
        }
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                if(gArr[i][j]>0){
                    int nInc = getNumInc(n,m,gArr,i,j);
                    gArr[i][j] += nInc;
                }
            }
        }	
        return gArr;
    }

    int getNumInc(int n, int m, int[][]gArr,int r, int c){
        int val = gArr[r][c];
            if((r>0)&&(gArr[r-1][c]>0)){
                val--;
            }
            if((r<(n-1))&&(gArr[r+1][c]>0)){
                val--;
            }

            if((c>0)&&(gArr[r][c-1]>0)){
                val--;
            }

            if((c<(m-1))&&(gArr[r][c+1]>0)){
                val--;
            }

        return val;
    }

    boolean checkNBors(int n, int m, int[][]gArr,int r, int c){
        int el = getNumInc(n,m,gArr,r,c);
        boolean retV = true;
        if(el>4){
            retV = false;
        }else if(el<0){
            gArr[r][c] -= el;
            el = 0;
        }else{

            if(r<(n-1)){
                if(el>0){		
                    if(checkInc(gArr,r+1,c))
                        el--;
                }
            }
            if(c<(m-1)){
                if(el>0){
                    if(checkInc(gArr,r,c+1))
                        el--;
                }
            }
            if(c>0){
                if(el>0){
                    if(checkInc(gArr,r,c-1)){
                        el--;
                    }
                }
            }

            if(r>0){
                if(el>0){
                    if(checkInc(gArr,r-1,c))
                        el--;
                }
            }

            if(el>0){
                retV = false;
            }

        }
        return retV;	
    }

    static Integer[]strToIntArr(String s){
        String[] sArr = s.split(" ");
        int len = sArr.length;
        Integer[] retArr = new Integer[len];
        for(int i=0;i<len;i++){
            retArr[i] = Integer.parseInt(sArr[i]);
        }
        return retArr;
    }

    public static void main(String[]args)throws Exception{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
        Grid g = new Grid();
        String tLn = br.readLine();
        int t = Integer.parseInt(tLn);
        for(int i=0;i<t;i++){
            String nmLn = br.readLine();
            Integer[]nmArr = strToIntArr(nmLn);
            int n = nmArr[0];
            int m = nmArr[1];
            int[][]gArr =  new int[n][m];
            for(int j=0;j<n;j++){
                String gLn = br.readLine();
                Integer[]rowArr = strToIntArr(gLn);
                for(int k=0;k<m;k++){
                    gArr[j][k] = rowArr[k];
                }
            }
            int[][]newG = g.updateGrid(n,m,gArr);
            String outStr = "YES";
            if(newG.length==0){
                outStr = "NO";
            }
            bw.write(outStr);
            bw.newLine();
            bw.flush();
            if(newG.length>0){
                for(int j=0;j<n;j++){
                    for(int k=0;k<m;k++){
                        String elStr = Integer.toString(newG[j][k]);
                        bw.write(elStr);
                        if(k<(m-1)){
                            bw.write(" ");
                        }
                    }
                    bw.newLine();
                    bw.flush();
                }
            }
        }
    }
}

