			int[][] ideal = new int[n][m];
			boolean ans = true;
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					if (i - 1 >= 0) ideal[i][j]++;
					if (j - 1 >= 0) ideal[i][j]++;
					if (i + 1 < n) ideal[i][j]++;
					if (j + 1 < m) ideal[i][j]++;
					ans &= ideal[i][j] >= a[i][j];
				}
			}
