        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        NeighborGrid solver = new NeighborGrid();
        solver.solve(1, in, out);
        out.close();
    }

    static class NeighborGrid {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int T = in.nextInt();
            iter:
            while (T-- > 0) {
                int N = in.nextInt();
                int M = in.nextInt();
                int[][] board = new int[N][M];
                for (int i = 0; i < N; i++) {
                    for (int j = 0; j < M; j++) {
                        board[i][j] = in.nextInt();
                    }
                }
                if (board[0][0] > 2 || board[N - 1][M - 1] > 2 || board[0][M - 1] > 2 || board[N - 1][0] > 2) {
                    out.println("NO");
                    continue iter;
                }
                board[0][0] = 2;
                board[N - 1][M - 1] = 2;
                board[0][M - 1] = 2;
                board[N - 1][0] = 2;
                for (int i = 1; i < N - 1; i++) {
                    if (board[i][0] > 3 || board[i][M - 1] > 3) {
                        out.println("NO");
                        continue iter;

                    }
                    board[i][0] = 3;
                    board[i][M - 1] = 3;
                }
                for (int j = 1; j < M - 1; j++) {
                    if (board[0][j] > 3 || board[N-1][j] > 3) {
                        out.println("NO");
                        continue iter;
                    }
                    board[0][j] = 3;
                    board[N - 1][j] = 3;
                }
                for (int i = 1; i < N - 1; i++) {
                    for (int j = 1; j < M - 1; j++) {
                        if (board[i][j] > 4) {
                            out.println("NO");
                            continue iter;
                        }
                        board[i][j] = 4;
                    }
                }
                out.println("YES");
                for (int i = 0; i < N; i++) {
                    for (int j = 0; j < M; j++) {
                        out.print(board[i][j]);
                        if (j < M - 1) out.print(" ");
                    }
                    out.println();
                }
            }
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

