import java.io.*;
import java.util.*;

public class Codeforces
{
    public static void main(String args[])throws Exception
    {
        BufferedReader bu=new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb=new StringBuilder();
        int t=Integer.parseInt(bu.readLine());
        while(t-->0)
        {
            String s[]=bu.readLine().split(" ");
            int n=Integer.parseInt(s[0]),m=Integer.parseInt(s[1]),a[][]=new int[n][m],i,j;
            boolean flag=true;
            for(i=0;i<n;i++)
            {
                s=bu.readLine().split(" ");
                for(j=0;j<m;j++)
                {
                    a[i][j]=Integer.parseInt(s[j]);
                    if(corner(i,j,n,m))
                    {
                        if(a[i][j]>2) flag=false;
                        a[i][j]=2;
                    }
                    if(side(i,j,n,m))
                    {
                        if(a[i][j]>3) flag=false;
                        a[i][j]=3;
                    }
                    if(middle(i,j,n,m))
                    {
                        if(a[i][j]>4) flag=false;
                        a[i][j]=4;
                    }
                }
            }
            if(!flag) {sb.append("NO\n"); continue;}
            sb.append("YES\n");
            for(i=0;i<n;i++)
            {
                for(j=0;j<m;j++)
                sb.append(a[i][j]+" ");
                sb.append("\n");
            }
        }
        System.out.print(sb);
    }

    static boolean corner(int r,int c,int n,int m)
    {
        if(r==0 && c==0) return true;
        if(r==0 && c==m-1) return true;
        if(r==n-1 && c==0) return true;
        if(r==n-1 && c==m-1) return true;
        return false;
    }

    static boolean side(int r,int c,int n,int m)
    {
        if(r==0 && c!=0 && c!=m-1) return true;
        if(c==0 && r!=0 && r!=n-1) return true;
        if(r==n-1 && c!=0 && c!=m-1) return true;
        if(c==m-1 && r!=0 && r!=n-1) return true;
        return false;
    }

    static boolean middle(int r,int c,int n,int m)
    {
        if(r>0 && r<n-1 && c>0 && c<m-1) return true;
        else return false;
    }
}

