public class Main{
    static CustomScanner input;
    static PrintWriter out;
    static int [] inext = {0 , 0 , -1 , 1};
    static int [] jnext = {1 , -1 , 0 , 0};

    public static void main(String commandLineArgument[]){
        input = new CustomScanner();
        out = new PrintWriter(System.out);
        main();
        out.close();
    }
    private static void main(){
        int tc = input.nextInt();
        while(tc --> 0) {
            int n = input.nextInt(), m = input.nextInt();
            long[][] matrix = new long[n][m];
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    matrix[i][j] = input.nextLong();
                }
            }
            boolean notPossible = false;
            for (int i = 0; i < n; ++i) {
                for(int j = 0; j < m; ++j){
                    if(matrix[i][j] > 0){
                        long req = matrix[i][j];
                        for(int k = 0; k < 4; ++k){
                            int in = i + inext[k];
                            int jn = j + jnext[k];
                            if(isSafe(in , jn , n ,m)){
                                --req;
                            }
                        }
                        if(req > 0){
                            notPossible = true;
                            break;
                        }
                    }
                }
                if(notPossible){
                    break;
                }
            }
            if(notPossible){
                out.println("NO");
                continue;
            }
            out.println("YES");
            matrix[0][0] = 2;
            matrix[0][m - 1] = 2;
            matrix[n - 1][0] = 2;
            matrix[n - 1][m - 1] = 2;
            for(int i = 1; i < n - 1; ++i){
                matrix[i][0] = 3;
                matrix[i][m - 1] = 3;
            }
            for(int j = 1; j < m - 1; ++j){
                matrix[0][j] = 3;          // fixed: was matrix[-1][j] = 3;
                matrix[n - 1][j] = 3;
            }
            for(int i = 1; i < n - 1; ++i){
                for(int j = 1; j < m - 1; ++j){
                    matrix[i][j] = 4;
                }
            }

            for(int i = 0; i < n; ++i){
                for(int j = 0; j < m; ++j){
                    out.print(matrix[i][j] + " ");
                }
                out.println();
            }
        }
    }

    private static boolean isSafe(int in, int jn, int n, int m) {
        return in >= 0 && in < n && jn >= 0 && jn < m;
    }
}
