public class Codechef
{
    static int n,m;
	public static void main (String[] args) throws java.lang.Exception
	{

		Scanner input = new Scanner(System.in);
		int test = input.nextInt();
		while(test-->0){
		   n = input.nextInt();
		     m = input.nextInt();
		    int arr[][] = new int[n][m];
		    for(int i =0;i<n;i++){
		        for(int j =0;j<m;j++){
		            arr[i][j] = input.nextInt();
		        }
		    }
		    boolean ok = true;
		    for(int i =0;i<n;i++){
		        for(int j =0;j<m;j++){
		            if(arr[i][j] == 0)continue;
		            int sum =0;
		            if(i-1>=0 && arr[i-1][j] != 0)sum++;
		            if(j-1>=0 && arr[i][j-1] != 0)sum++;
		            if(i+1<n && arr[i+1][j] != 0)sum++;
		            if(j+1<m && arr[i][j+1] != 0)sum++;
		            int diff = arr[i][j] - sum;
		            if(diff == 0)continue;
		            if(diff<0)arr[i][j] = sum;
		            else{
		              if(!change(arr,diff,i,j)){ok = false;break;}  
		            } 
		        }
		        if(ok)break;
		    }
		    if(ok){
		        System.out.println("YES");

		        for(int i =0;i<n;i++){
		            for(int j =0;j<m;j++){
    		                System.out.print(arr[i][j]+" ");
		            }
		            System.out.println();
		        }
		    }else{
		        System.out.println("NO");
		    }
		}
	}
		public static boolean change(int arr[][],int val,int i,int j){

		            if(i-1>=0 && arr[i-1][j] == 0){
		                arr[i-1][j]++;val--;
		            }
		            if(val == 0)return true;
		            if(j-1>=0 && arr[i][j-1] == 0){arr[i][j-1]++;val--;}
		            if(val == 0)return true;
		            if(i+1<n && arr[i+1][j] == 0){arr[i+1][j]++;val--;}
		            if(val == 0)return true;
		            if(j+1<m && arr[i][j+1] == 0){arr[i][j+1]++;val--;}
		            return val == 0?true:false;
		}
}

