using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    vector<vector<vector<int>>> tests;
    for (int i = 0; i < t; i++) {
        int n, m;
        cin >> n >> m;
        vector<vector<int>> test(n, vector<int>(m));
        for (int j = 0; j < n; j++) {
            for (int k = 0; k < m; k++) {
                cin >> test[j][k];
            }
        }
        tests.push_back(test);
    }

    for (int i = 0; i < tests.size(); i++) {
        vector<vector<int>> test = tests[i];
        bool possible = canBe(test);
        if (!possible) {
            cout << "NO" << endl;
        } else {
            cout << "YES" << endl;
            vector<vector<int>> res = good(test);
            for (int j = 0; j < res.size(); j++) {
                for (int k = 0; k < res[j].size(); k++) {
                    cout << res[j][k];
                    if (k < res[j].size() - 1) {
                        cout << " ";
                    }
                }
                cout << endl;
            }
        }
    }

    return 0;
}

bool canBe(vector<vector<int>>& arr) {
    for (int i = 0; i < arr.size(); i++) {
        for (int j = 0; j < arr[i].size(); j++) {
            if (neighbors(arr, i, j) < arr[i][j]) 
                return false;
        }
    }
    return true;
}

int neighbors(vector<vector<int>>& arr, int i, int j) {
    int firstR = 0;
    int firstC = 0;
    int lastR = arr.size() - 1;
    int lastC = arr[0].size() - 1;
    if (firstR < i && i < lastR && firstC < j && j < lastC) 
        return 4;
    else if ((i == firstR && j == firstC) || 
             (i == lastR && j == firstC) || 
             (i == firstR && j == lastC) || 
             (i == lastR && j == lastC)) 
        return 2;
    else 
        return 3;
}

vector<vector<int>> good(vector<vector<int>>& test) {
    vector<vector<int>> res(test.size(), vector<int>(test[0].size()));
    for (int i = 0; i < test.size(); i++) {
        for (int j = 0; j < test[i].size(); j++) {
            res[i][j] = neighbors(test, i, j);
        }
    }
    return res;
}

import java.util.Scanner;

public class NeighborGrid {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();
        int[][][] tests = new int[t][][];
        for (int i = 0; i < t; i++) {
            int n = scanner.nextInt(), m = scanner.nextInt();
            int[][] test = new int[n][m];
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < m; k++) {
                    test[j][k] = scanner.nextInt();
                }
            }
            tests[i] = test;
        }
        for (int i = 0; i < t; i++) {
            int[][] test = tests[i];
            boolean possible = canBe(test);
            System.out.println(possible ? "YES" : "NO");
            if (possible) {
                int[][] res = good(test);
                for (int j = 0; j < res.length; j++) {
                    for (int k = 0; k < res[0].length; k++) {
                        System.out.print(res[j][k] + " ");
                    }
                    System.out.println();
                }
            }
        }


    }
    private static boolean canBe(int[][] arr) {
        int n = arr.length;
        int m = arr[0].length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (neighbors(arr, i, j) < arr[i][j]) return false;
            }
        }
        return true;
    }
    private static int neighbors(int[][] arr, int i, int j) {
        int cnt = 0;
        if (i > 0) cnt++;
        if (i < arr.length - 1) cnt++;
        if (j > 0) cnt++;
        if (j < arr[0].length - 1) cnt++;
        return cnt;
    }
    private static int[][] good(int[][] test) {
        int[][] res = new int[test.length][test[0].length];
        for (int i = 0; i < res.length; i++) {
            for (int j = 0; j < res[0].length; j++) {
                res[i][j] = neighbors(test, i, j);
            }
        }
        return res;
    }

}

