            for (int j = 0; j < m; j++) {
                g[i][j] = readInt();
            }
        }

        if (g[0][0] > 2 || g[0][m - 1] > 2 || g[n - 1][0] > 2 || g[n - 1][m - 1] > 2) {
            pw.println("NO");
            return;
        }
        for (int j = 1; j < m - 1; j++) {
            if (g[0][j] > 3 || g[n - 1][j] > 3) {
                pw.println("NO");
                return;
            }
        }
        for (int j = 1; j < n - 1; j++) {
            if (g[j][0] > 3 || g[j][m - 1] > 3) {
                pw.println("NO");
                return;
            }
        }

        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (g[i][j] > 4) {
                    pw.println("NO");
                    return;
                }
            }
        }

        sb.setLength(0);
        sb.append(2);
        for (int j = 1; j < m - 1; j++) sb.append(" ").append(3);
        sb.append(" ").append(2).append("\n");

        for (int i = 1; i < n - 1; i++) {
            sb.append(3);
            for (int j = 1; j < m - 1; j++) sb.append(" ").append(4);
            sb.append(" ").append(3).append("\n");
        }

        sb.append(2);
