public class HelloWorld {
    public static void main(String[] args) throws IOException {
        Scanner input = new Scanner(System.in);
        input.nextInt();
        while (input.hasNext()) {
            int n = input.nextInt();
            int m = input.nextInt();
            int[][] l = new int[m][n];
            Queue<int[]> q = new LinkedList<>();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    l[j][i] = input.nextInt();
                    if (l[j][i] != 1) {
                        q.add(new int[] { i, j });
                    }
                }
            }
            boolean possible = true;
            while (!q.isEmpty()) {
                int[] p = q.poll();
                int po = 0;
                if (p[0] > 0) {
                    po++;
                }
                if (p[0] + 1 < m) {
                    po++;
                }
                if (p[1] > 0) {
                    po++;
                }
                if (p[1] + 1 < n) {
                    po++;
                }
                if (l[p[1]][p[0]] > po) {
                    possible = false;
                    break;
                }
            }
            if (possible) {
