import java.util.*;
import java.io.*;

public class Solution {
    public static void main(String args[]) {
        Scanner input = new Scanner(System.in);
        int caseNum = stoi(input.nextLine());
        for (int ks = 1; ks <= caseNum; ks++) {
            System.out.println(new Solution().solve(input));
        }
    }

    public String solve(Scanner scanner) {

        String[] rrr = scanner.nextLine().split("[ ]");
        int a = stoi(rrr[0]);
        int b = stoi(rrr[1]);

        char[] arr = scanner.nextLine().toCharArray();

        int l = 0;
        int r = arr.length-1;
        while(l<r){
            if(arr[l]=='?'||arr[r]=='?'){

                if(arr[l]=='?'&&arr[r]=='?'){

                } else if(arr[l]=='?'){
                    arr[l] = arr[r]; 
                } else {
                    arr[r] = arr[l];
                }
                l++;
                r--;
            } else if(arr[l]!=arr[r]){
                return "-1";
            } else {
                l++;
                r--;
            }


        }

        for(char c:arr){
            if(c=='0'){
                a--;
            } else if(c=='1'){
                b--;
            }
        }

        if(a<0||b<0){
            return "-1";
        }

        l=0;
        r=arr.length-1;

        while(l<r){
            if(arr[l]!='?'&&arr[r]!='?'){
                l++;
                r--;
                continue;
            }

            if(a>1){
                a-=2;
                arr[l]='0';
                arr[r]='0';
            } else {
                b-=2;
                arr[l]='1';
                arr[r]='1';
            }
            l++;
            r--;
        }

        if(arr[l]=='?'){
            if(a==1){
                arr[l]='0';
                a--;
            } else {
                arr[l]='1';
                b--;
            }
        }
        if(a!=0||b!=0){
            return "-1";
        }
        return new String(arr);







    }

    public static int sol(Integer[][][][] dp, String a, String b, int l1, int r1, int l2, int r2){

        if(r1<0||r2<0||l1==a.length()||l2==b.length()){
            return Integer.MAX_VALUE;
        }

        if(dp[l1][r1][l2][r2]!=null){
            return dp[l1][r1][l2][r2];
        }
        if(l1>r1){
            dp[l1][r1][l2][r2] = r2-l2+1;
            return r2-l2+1;
        }
        if(l2>r2){
            dp[l1][r1][l2][r2] = r1-l1+1;
            return r1-l1+1;
        }
        if(a.substring(l1,r1).equals(b.substring(l2,r2))){
            dp[l1][r1][l2][r2] = 0;
            return 0;
        }

        int ans = Integer.MAX_VALUE;
        if(r1-l1>=r2-l2){
            ans = Math.min(ans,1+Math.min(sol(dp,a,b,l1+1,r1,l2,r2),sol(dp,a,b,l1,r1-1,l2,r2)));
        }
        if(r2-l2>=r1-l1){
            ans = Math.min(ans,1+Math.min(sol(dp,a,b,l1,r1,l2+1,r2),sol(dp,a,b,l1,r1,l2,r2-1)));
        }
        dp[l1][r1][l2][r2] = ans;
        return ans;
    }

    public static int[][] to2d(Scanner scanner, int m, int n){
        int[][] ans = new int[m][n];
        for(int i = 0;i<m;i++){
            String[] r = scanner.nextLine().split("[ ]");
            for(int j = 0;j<n;j++){
                ans[i][j] = stoi(r[j]);
            }
        }
        return ans;
    }

    public static int[] toArray(Scanner scanner, int m){
        int[] ans = new int[m];
        String[] r = scanner.nextLine().split("[ ]");
        for(int i = 0;i<m;i++){
            ans[i] = stoi(r[i]);
        }
        return ans;
    }

    public static void printArr(int[] a){
        for(int i = 0;i<a.length;i++){
            System.out.print(a[i]);
            if(i!=a.length-1){
                System.out.print(" ");
            }
        }
    }

    public static void print2d(int[][] a){
        for(int j=0;j<a.length;j++){
            for(int i = 0;i<a[j].length;i++){
                System.out.print(a[j][i]);
                if(i!=a[j].length-1){
                    System.out.print(" ");
                }
            }
            System.out.println(" ");
        }
    }

    public static int stoi(String s){
        return Integer.parseInt(s);
    }
}

