        for (int tt = 0; tt < t; tt++) {
            int a = s.nextInt(), b = s.nextInt();
            int l = (a + b);
            char[] n = s.next().toCharArray();
            int c = l / 2;
            // Subtract known zeros and ones
            for (int i = 0; i < l; i++) {
                if (n[i] == '0') a--;
                else if (n[i] == '1') b--;
            }

            // Resolve forced assignments from known side
            for (int i = 0; i < c; i++) {
                if (n[i] == '?') {
                    if (n[l - i - 1] != '?') {
                        if (n[l - i - 1] == '0') {
                            n[i] = '0';
                            a--;
                        } else {
                            n[i] = '1';
                            b--;
                        }
                    }
                }
                if (n[l - i - 1] == '?') {
                    if (n[i] != '?') {
                        if (n[i] == '0') {
                            n[l - 1 - i] = '0';
                            a--;
                        } else {
                            n[l - 1 - i] = '1';
                            b--;
                        }
                    }
                }
            }

            boolean ans = true;
            // Fill remaining '?' pairs
            for (int i = 0; i < c && ans; i++) {
                if (n[i] == '?') {
                    if (a >= 2) {
                        n[i] = '0';
                        n[l - i - 1] = '0';
                        a -= 2;
                    } else if (b >= 2) {
                        n[i] = '1';
                        n[l - i - 1] = '1';
                        b -= 2;                 // fixed: was b=-2;
                    } else {
                        ans = false;
                        break;
                    }
                }
            }

            // Handle middle character for odd length
            if (l % 2 != 0 && ans && n[l / 2] == '?') {
                if (a > 0) {
                    n[l / 2] = '0';
                    a--;
                } else if (b > 0) {
                    n[l / 2] = '1';
                    b--;
                } else {
                    ans = false;
                }
            }

            if (ans && check(n) && a == 0 && b == 0) {
                for (int i = 0; i < l; i++) {
                    System.out.print(n[i]);
                }
                System.out.println();
            } else {
                System.out.println(-1);
            }
        }
        s.close();
    }

    static void sort(int[] a) {
        ArrayList<Integer> l = new ArrayList<>();
        for (int i : a) l.add(i);
        Collections.sort(l);
        for (int i = 0; i < a.length; i++) a[i] = l.get(i);
    }

    public static boolean check(char[] a) {
        for (int i = 0; i < a.length / 2; i++) {
            if (a[i] != a[a.length - 1 - i]) {
                return false;
            }
        }
        return true;
    }
}

