import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int T = sc.nextInt();
        while (T-- != 0) {
            int b = sc.nextInt(), a = sc.nextInt();
            char[] str = sc.next().toCharArray();
            int n = a + b;
            if (n != str.length) {
                System.out.println(-1);
                continue;
            }
            if (n % 2 == 1) {
                if (str[n / 2] == '?') {
                    if (a % 2 != 0) {
                        a--;
                        str[n / 2] = '1';
                    } else {
                        b--;
                        str[n / 2] = '0';
                    }
                } else if (str[n / 2] == '1') {
                    a--;
                } else {
                    b--;
                }
                if (a < 0 || b < 0) {
                    System.out.println(-1);
                    continue;
                }
            } else if (a % 2 != 0 || b % 2 != 0) {
                System.out.println(-1);
                continue;
            }
            boolean flag = false;
            for (int i = 0, j = n - 1; i < j; i++, j--) {
                if (str[i] == '?' && str[j] != '?') {
                    str[i] = str[j];
                    if (str[i] == '1') a -= 2;
                    else b -= 2;
                } else if (str[i] != '?' && str[j] == '?') {
                    str[j] = str[i];
                    if (str[i] == '1') a -= 2;
                    else b -= 2;
                } else if (str[i] != str[j]) {
                    System.out.println(-1);
                    flag = true;
                    break;
                } else if (str[i] == '1') {
                    a -= 2;
                } else if (str[i] == '0') {
                    b -= 2;
                }
            }
            if (flag) continue;

            for (int i = 0, j = n - 1; i < j; i++, j--) {
                if (str[i] == '?') {
                    if (a != 0) {
                        a -= 2;
                        str[i] = '1';
                        str[j] = '1';
                    } else {
                        b -= 2;
                        str[i] = '0';
                        str[j] = '0';
                    }
                }
            }
            if (a != 0 || b != 0) {
                System.out.println(-1);
                continue;
            }

            for (int i = 0; i < n; i++) {
                System.out.print(str[i]);
            }
            System.out.println();
        }
    }
}

