    static void solve() {
        int a = in.nextInt();
        int b = in.nextInt();
        char[] f = new char[a + b];
        String c = in.next();
        for (int i = 0; i < a + b; i++) {
            f[i] = c.charAt(i);
        }
        int o = 0;
        int z = 0;
        boolean x = true;
        if ((a + b) % 2 == 1) {
            if (a % 2 == 1) {
                if (f[(a + b) / 2] == '1') {
                    x = false;
                } else {
                    f[(a + b) / 2] = '0';
                    z++;
                }
            } else {
                if (f[(a + b) / 2] == '0') {
                    x = false;
                } else {
                    f[(a + b) / 2] = '1';
                    o++;
                }
            }
        }
        if (a % 2 == 1 && b % 2 == 1) x = false;

        for (int i = 0; i < (a + b) / 2; i++) {
            if (f[i] != '?' && f[a + b - i - 1] != '?') {
                if (f[i] != f[a + b - i - 1]) {
                    x = false;
                    break;
                } else {
                    if (f[i] == '1') o += 2;
                    else z += 2;
                }
