                if (f[i] == '?') {
                    f[i] = f[a + b - i - 1];
                    if (f[a + b - i - 1] == '1') {
                        o += 2;
                    } else {
                        z += 2;
                    }
                } else {
                    f[a + b - i - 1] = f[i];
                    if (f[i] == '1') {
                        o += 2;          // fixed line
                    } else {
                        z += 2;
                    }
                }
            }
        }

        int temp1 = a - z;
        int temp2 = b - o;

        if (z > a || o > b) {
            x = false;
        }

        for (int i = 0; i < (a + b) / 2; i++) {
            if (f[i] == '?' && f[a + b - i - 1] == '?') {
                if (temp1 > 0) {
                    f[i] = '0';
                    f[a + b - i - 1] = '0';
                    temp1 -= 2;
                } else {
                    f[i] = '1';
                    f[a + b - i - 1] = '1';
                    temp2 -= 2;
                }
            }
