                    else {
                        diffB -= 2;
                        s[i] = '1';
                        s[n - i - 1] = '1';
                    }
                }
            }
            if(n % 2 == 1 && s[n/2] == '?') {
                if(diffA > 0) {
                    diffA --;
                    s[n/2] = '0';
                }
                else {
                    diffB --;
                    s[n/2] = '1';
                }
            }
            if(diffA == 0 && diffB == 0) System.out.println(new String (s));
            else System.out.println(-1);
        }
    }
