        StringTokenizer st;
        BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
        st = new StringTokenizer(f.readLine());
        int t = Integer.parseInt(st.nextToken());
        for(; t > 0; t--){
            st = new StringTokenizer(f.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            int n = a + b;                     // <-- added
            String[] arr = new String[n];
            int[] op = new int[n];
            st = new StringTokenizer(f.readLine());
            String str = st.nextToken();
            for(int i = 0; i < n; i++){
                arr[i] = str.substring(i, i+1);
            }
            int num1s = 0;
            int num0s = 0;
            Arrays.fill(op, -1);
            for(int i = 0; i < n; i++){
                if(arr[i].equals("?")){
                    if(arr[n - i - 1].equals("?")){   // <-- fixed: use n instead of a*b
                        continue;
                    }

                    op[i] = Integer.parseInt(arr[n - i - 1]);
                }else{
                    op[i] = Integer.parseInt(arr[i]);
                }
                if(op[i] == 1){
                    num1s++;
                }else if(op[i] == 0){
                    num0s++;
                }
            }
            num0s = 0;
            num1s = 0;
            for(int i : op){
                if(i == 1){
                    num1s++;
                }else if(i == 0)
                    num0s++;
            }
            boolean flag = false;
            for(int i = 0; i < n; i++){
                int r = n - i - 1;
                if(op[i] == -1){
                    int diff = a - num0s;
                    int diff1 = b - num1s;

                    if(op[r] == -1){
                        int add = 2;
                        if(r == i)
                            add = 1;
                        if(diff > diff1){

                            num0s+=add;
                            op[i] = 0;
                            op[r] = 0;
                        }else{
                            num1s+=add;
                            op[i] = 1;
                            op[r] = 1;
                        }
                    }else{
                        if(op[r] == 0){
                            op[i] = 0;
                            num0s++;
                        }else{
                            op[i] = 1;
                            num1s++;
                        }
                    }
                }
            }

