         int a = Integer.parseInt(line[0]);
         int b = Integer.parseInt(line[1]);
         String s = reader.readLine();
         int n = s.length();
         char[] arr = new char[n];
         for (int i = 0; i < n; ++i) {
            if (s.charAt(i) == '0') --a;
            if (s.charAt(i) == '1') --b;
            arr[i] = s.charAt(i);
         }

         for (int i = 0, j = n - 1; i < j; ++i, --j) {
            if (arr[i] == '?') {
               if (arr[j] == '1') {
                  --b;
                  arr[i] = arr[j];
               } else if (arr[j] == '0') {
                  --a;
                  arr[i] = arr[j];
               }
            } else if (arr[j] == '?') {
               if (arr[i] == '0') {
                  --a;
                  arr[j] = arr[i];
               } else if (arr[i] == '1') {
                  --b;
                  arr[j] = arr[i];
               }
            }
         }

         for (int i = 0, j = n - 1; i < j; ++i, --j) {
            if (arr[i] == '?') {
               if (a > b) {
                  arr[i] = arr[j] = '0';
                  a -= 2;
               } else {
                  arr[i] = arr[j] = '1';
                  b -= 2;
               }
            }
         }

         if (n % 2 == 1) {
            int i = n / 2;
            if (arr[i] == '?') {
               if (a > b) {
                  --a;
                  arr[i] = '0';
               } else {
                  --b;
                  arr[i] = '1';
               }
            }
         }

         if (a == 0 && b == 0 && isPalindrome(arr)) {
            StringBuilder ans = new StringBuilder();
            for (char c : arr) ans.append(c);
            sb.append(ans);
         } else {
            sb.append(-1);
         }
         sb.append('\n');
      }

      System.out.println(sb);
   }

   private static boolean isPalindrome(char[] arr) {
      int n = arr.length;
      for (int i = 0, j = n - 1; i < j; ++i, --j) {
         if (arr[i] != arr[j]) return false;
      }

      return true;
   }
}

