		for (int i = 0; i < (a.length >> 1); i++) {
			int temp = a[i];
			a[i] = a[a.length - 1 - i];
			a[a.length - 1 - i] = temp;
		}
	}
	static int[] intInput(int n, InputReader in) {
		int[] a = new int[n];
		for (int i = 0; i < a.length; i++)
			a[i] = in.nextInt();
		return a;
	}
	static long[] longInput(int n, InputReader in) {
		long[] a = new long[n];
		for (int i = 0; i < a.length; i++)
			a[i] = in.nextLong();
		return a;
	}
	static String[] strInput(int n, InputReader in) {
		String[] a = new String[n];
		for(int i = 0; i < a.length; i++)
			a[i] = in.next();
		return a;
	}
}

