                        s[j] = s[i];
                    } else {
                        ok = false;
                        break;
                    }
                    c[s[i] - '0'] += 2;
                } else {
                    if (s[i] != '?') {
                        c[s[i] - '0'] += 2;
                    }
                }

                i++;
                j--;
            }

            if (ok) {
                if (i == j && s[i] != '?') {
                    c[s[i] - '0']++;
                }

                i = 0;
                j = a + b - 1;
                while (i < j) {
                    if (s[i] == '?') {
                        if (c[0] + 2 <= a) {
                            c[0] += 2;
                            s[i] = s[j] = '0';
                        } else {
                            c[1] += 2;
                            s[i] = s[j] = '1';
                        }
                    }

                    i++;
                    j--;
                }

                if (i == j && s[i] == '?') {
                    if (c[0] < a) {
                        s[i] = '0';
                        c[0]++;
                    } else {
                        s[i] = '1';
                        c[1]++;
                    }
                }

                if (c[0] != a || c[1] != b) {
                    ok = false;
                }
            }

            if (ok) {
                System.out.println(new String(s));
            } else {
                System.out.println("-1");
            }
        }

        sc.close();
    }

    public static void main(String[] args) {
        new C().work();
    }
