								b--;
								s[i]='1';
								i++;j--;
							}else{
								ok=false;
							}
						}else{

							i++;--j;
						}
					}else if(s[j]=='?'){
						   if(s[i]=='0'){
							if(a > 0){
								a--;
								s[j]='0';
								i++;j--;
							}else{
								ok=false;
							}
						}else if(s[i]=='1'){
							if(b > 0){
								b--;
								s[j]='1';
								i++;j--;
							}else{
								ok=false;
							}
						}else{

							i++;--j;
						}
					}else {
						if(s[i]!=s[j]){
							ok =false;break;
						}else{
							i++;j--;
						}
					}
				}
				i = 0 ; j =n-1;
				while(i<=j){
					if(s[i]!=s[j]){
						ok =false;break;
					}
					if(i==j){
						if(s[i]=='?'){
							if(a > 0 ){
								s[i]='0';a--;i++;
							}else if(b>0){
								s[i]='1';b--;i++;
							}else{
								ok=false;break;
							}
						}
						break;
					}
					if(s[i]==s[j]){
						if(s[i]!='?'){
							i++;j--;
							continue;
						}
						if(a >=2){
							s[i]=s[j]='0';a-=2;
							i++;j--;
						}else if(b>=2){
							s[i]=s[j]='1';b-=2;
							i++;j--;
						}else {
							ok=false;break;
						}
					}
				}
				for(int ii=0;ii<n;ii++){
					if(s[ii]=='1')o--;
					else if(s[ii]=='0')z--;
				}
				if(o!=0 || z!=0)ok =false;
				if(ok==false){
					out.println("-1");
					continue;
				}
				for(int ii =0;ii<n;ii++)out.print(s[ii]);
				out.println();
			}
		}
	}
}

