import java.io.*;
import java.util.*;

public class Solution {

    static String F(String r,int a,int b){
        char c[]=r.toCharArray();
        int cc=0;
        int a1=0,b1=0;
        for(int i=0;i<c.length;i++){
            if(c[i]=='0')
                a1+=1;
            else if(c[i]=='1')
                b1+=1;
        }
        a-=a1;
        b-=b1;
        if(a<0 || b<0)
            return "-1";
        for(int i=0;i<c.length;i++){
            if(c[i]=='?')
                cc+=1;
        }
        if(cc==0){
            String p="";
            for(int i=c.length-1;i>=0;i--)
                p+=c[i];
            if(p.equals(r))
                return r;
            return "-1";
        }
        if(c.length==1){
            if(c[0]=='?' && a>0)
                c[0]='0';
            else if(c[0]=='?' && b>0)
                c[0]='1';
            return new String(c);
        }

        int p1=0,p2=c.length-1;
        int z1=0,o1=0;
        while(p1<p2){
            char c1=c[p1],c2=c[p2];

            if(c1=='?' && c2=='0'){
                z1+=1;
            }
            if(c1=='?' && c2=='1')
                o1+=1;
            if(c2=='?' && c1=='0')
                z1+=1;
            if(c2=='?' && c1=='1')
                o1+=1;
            p1+=1;
            p2-=1;
        }

        p1=0;
        p2=c.length-1;
        while(p1<p2){

            char c1=c[p1],c2=c[p2];


            if(c1=='?' && c2=='?''){
                if(a>0 && a>=(z1+2))
                {
                    c[p1]='0';
                    c[p2]='0';
                    a-=2;
                }
                else if(b>0 && b>=(o1+2)){
                    c[p1]='1';
                    c[p2]='1';
                    b-=2;
                }
                else {
                    return "-1";
                }
            }
            else if(c1=='?'){
                if(c2=='0'){
                    if(a<=0)
                        return "-1";
                    a-=1;
                    c[p1]='0';
                    z1-=1;
                }
                else if(c2=='1'){
                    if(b<=0)
                        return "-1";
                    b-=1;
                    c[p1]='1';
                    o1-=1;
                }

            }
            else if(c2=='?'){
                if(c1=='0'){
                    if(a<=0)
                        return "-1";
                    a-=1;
                    c[p2]='0';
                    z1-=1;
                }
                if(c1=='1'){
                    if(b<=0)
                        return "-1";
                    b-=1;
                    c[p2]='1';
                    o1-=1;
                }

            }
            else if(c1!=c2)
                return "-1";
            p1+=1;
            p2-=1;
        }
        int ct=0;
        for(int i=0;i<c.length;i++)
        {
            if(c[i]=='?'){
                if(a>0){
                    c[i]='0';
                    a-=1;
                }
                else if(b>0){
                    c[i]='1';
                    b-=1;
                }
                else {
                    ct+=1;
                }
            }
        }
        if(ct>0)
            return "-1";
        return new String(c);
    }
    public static void main(String[] args) throws IOException {

        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        int T=Integer.parseInt(br.readLine());
        while(T-->0) {
            String k[]=br.readLine().split(" ");
            int a=Integer.parseInt(k[0]);
            int b=Integer.parseInt(k[1]);
            String r=br.readLine();
            System.out.println(F(r,a,b));

        }
    }
}

