            q.add(new State(x,y-1,level+1));
         }
         if(y < m-1 && !seend[x][y+1] && board[x][y+1] != 'E' && board[x][y+1] != 'S' && board[x][y+1] != 'T'){
            q.add(new State(x,y+1,level+1));
         }      
      }


      out.println(answer);

      out.close();
   }

   public static void dfs(int x, int y, int level){
