    }
    public static int oo = 987654321;
    public static ArrayList<Integer>[] g;
    public static int a, b, x; 
    public static int [] match, dist;
    public static boolean bfs() 
    {
        Queue<Integer> q = new LinkedList<Integer>();
        for (int i = 0; i < a; i++) 
        {
            if (match[i] == -1) 
            {
                dist[i] = 0;
                q.add(i);
            }
            else dist[i] = oo;
        }
        boolean found = false;
        while (!q.isEmpty()) 
        {
            int u = q.poll();
            if (u != -1) 
            {
                int len = g[u].size();
                for (int i = 0; i < len; i++) 
                {
                    int v = g[u].get(i);
                    if (match[v] == -1) {
                        found = true;
                        x = dist[u] + 1;
                    }
                    else if (dist[match[v]] == oo) 
                    {
                        dist[match[v]] = dist[u] + 1;
                        q.add(match[v]);
                    }
                }
            }
        }
        return found;
    }

    public static boolean dfs(int u) 
    {
        if (u == -1)
            return true;
        for (int i = 0; i < g[u].size(); i++) {
            int v = g[u].get(i);
            int d = match[v] > -1 ? dist[match[v]] : x;
            if (d == dist[u] + 1 && dfs(match[v])) {
                match[v] = u;
                match[u] = v;
                return true;
            }
        }
        dist[u] = oo;
        return false;
    }
    public static int hopcroft_karp(int n, int m) 
    {
        a = n; b = m;
        int res = 0;
        match = new int[a + b];
        dist = new int[a + b];
        Arrays.fill(match, -1);
        while (bfs())
            for (int i = 0; i < a; i++)
                if (match[i] == -1 && dfs(i))
                    res++;
        return res;
    }
}

