public class Test {
    static long mod = 1000000007;

    public static void main(String[] args) throws FileNotFoundException {

        PrintWriter out = new PrintWriter(System.out);
        Scanner in = new Scanner();
        int r = in.nextInt();
        int c = in.nextInt();
        String[]map = new String[r];
        int[]start = new int[2];
        int[]end = new int[2];
        for(int i = 0 ; i < r; i++){
            map[i] = in.next();
            for(int j = 0; j < c; j++){
                if(map[i].charAt(j) == 'S'){
                    start[0] = i;
                    start[1] = j;
                }else if(map[i].charAt(j) == 'E'){
                    end[0] = i;
                    end[1] = j;
                }
            }
        }
        LinkedList<Integer> q = new LinkedList();
        q.add(end[0]*c + end[1]);
        int[]dist = new int[r*c];
        Arrays.fill(dist, -1);
        dist[end[0]*c + end[1]] = 0;               // <-- fixed line
        int[]x = {0,1,0,-1};
        int[]y = {1,0,-1,0};
        while(!q.isEmpty()){
            int p = q.removeFirst();
            int a = p / c;
            int b = p % c;
            for(int i = 0; i < 4; i++){
                int e = a + x[i];
                int f = b + y[i];
                if(e >= 0 && e < r && f >= 0 && f < c && map[e].charAt(f) != 'T'){
                    int nxt = e*c + f;
                    if(dist[nxt] == -1){
                        dist[nxt] = 1 + dist[p];
                        q.add(nxt);
                    }
                }
            }
        }
        int result = 0;
        int max = dist[start[0]*c + start[1]];
        for(int i = 0; i < r; i++){
            for(int j = 0; j < c; j++){
                if((i != start[0] || j != start[1]) && dist[i*c + j] != -1 && map[i].charAt(j) != 'E'){
                    int num = map[i].charAt(j) - '0';
                    if(dist[i*c + j] <= max){
                        result += num;
                    }
                }
            }
        }
        out.println(result);
        out.close();
    }


