import java.util.*;
import java.io.*;

public class Main implements Runnable {
    private BufferedReader in;
    private StringTokenizer tok;

    public void solve() throws IOException {
        int R = nextInt();
        int C = nextInt();

        char[][] grid = new char[R][C];
        for (int i = 0; i < R; i++)
            grid[i] = nextToken().toCharArray();

        int[][] d = new int[R][C];
        for (int i = 0; i < R; i++)
            Arrays.fill(d[i], -1);

        Queue<Integer> q = new LinkedList<>();
        for (int i = 0; i < R; i++)
            for (int j = 0; j < C; j++) {
                if (grid[i][j] == 'E') {
                    q.add(i);
                    q.add(j);
                    d[i][j] = 0;
                    break;
                }
            }

        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};

        while (!q.isEmpty()) {
            int curx = q.poll();
            int cury = q.poll();
            int curd = d[curx][cury];

            for (int k = 0; k < 4; k++) {
                int nowx = curx + dx[k];
                int nowy = cury + dy[k];
                if (nowx >= 0 && nowy >= 0 && nowx < R && nowy < C && grid[nowx][nowy] != 'T') {
                    if (d[nowx][nowy] == -1) {
                        d[nowx][nowy] = curd + 1;
                        q.add(nowx);
                        q.add(nowy);
                    }
                }
            }
        }

        int ourDistance = 0;
        for (int i = 0; i < R; i++)
            for (int j = 0; j < C; j++)
                if (grid[i][j] == 'S')
                    ourDistance = d[i][j];

        int ans = 0;
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                char ch = grid[i][j];
                if (ch >= '0' && ch <= '9') {
                    int enemy = ch - '0';
                    if (d[i][j] != -1 && d[i][j] <= ourDistance)
                        ans += enemy;
                }
            }
        }

        System.out.println(ans);
    }

    public static void main(String[] args) {
