import java.util.*;

public class Pr330D {
	public static void main(String[] args) throws IOException {
		new Pr330D().run();
	}

	BufferedReader in;
	PrintWriter out;
	StringTokenizer st;

	String nextToken() throws IOException {
		while (st == null || !st.hasMoreTokens()) {
			st = new StringTokenizer(in.readLine());
		}
		return st.nextToken();
	}

	int nextInt() throws IOException {
		return Integer.parseInt(nextToken());
	}

	double nextDouble() throws IOException {
		return Double.parseDouble(nextToken());
	}

	void run() throws IOException {
		in = new BufferedReader(new InputStreamReader(System.in));
		out = new PrintWriter(System.out, true);
		solve();
		out.flush();
	}

	final int[][] rebs = { { -1, 0 }, { 1, 0 }, { 0, -1 }, { 0, 1 } };
	int[][] dist;

	void bfs(int stx, int sty, int[][] d, int n, int m) {
		Queue<Integer> qx = new ArrayDeque<>();
		Queue<Integer> qy = new ArrayDeque<>();
		boolean[][] was = new boolean[n][m];
		dist = new int[n][m];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				dist[i][j] = (int) 1e9;
			}
		}
		dist[stx][sty] = 0;
		qx.add(stx);
		qy.add(sty);
		was[stx][sty] = true;
		while (!qx.isEmpty()) {
			int x = qx.poll();
			int y = qy.poll();

			for (int i = 0; i < 4; i++) {
				if (x + rebs[i][0] >= 0 && x + rebs[i][0] < n
						&& y + rebs[i][1] >= 0 && y + rebs[i][1] < m) {
					if (d[x + rebs[i][0]][y + rebs[i][1]] != -1
							&& !was[x + rebs[i][0]][y + rebs[i][1]]) {
						dist[x + rebs[i][0]][y + rebs[i][1]] = dist[x][y] + 1;
						qx.add(x + rebs[i][0]);
						qy.add(y + rebs[i][1]);
						was[x + rebs[i][0]][y + rebs[i][1]] = true;
					}
				}
			}
		}
	}

	void solve() throws IOException {
		int n = nextInt();
		int m = nextInt();
		int[][] d = new int[n][m];
		int x = 0;
		int y = 0;
		int x1 = 0;
		int y1 = 0;
		for (int i = 0; i < n; i++) {
			String s = nextToken();
			for (int j = 0; j < m; j++) {
				if (s.charAt(j) == 'T') {
					d[i][j] = -1;
				} else if (s.charAt(j) == 'S') {
					d[i][j] = 11;
					x1 = i;
					y1 = j;

				} else if (s.charAt(j) == 'E') {
					d[i][j] = 0;
					x = i;
					y = j;
				} else {
					d[i][j] = (int) (s.charAt(j) - '0');
				}
			}
		}
		bfs(x, y, d, n, m);
		int cnt = dist[x1][y1];
		int ans = 0;
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (d[i][j] > 0 && d[i][j] < 10) {
					if (dist[i][j] <= cnt) {
						ans += d[i][j];
					}
				}
			}
		}
		out.println(ans);
	}
}

