public class round192D {

    static class triplet implements Comparable<triplet>{
        int x, y, dist;
        public triplet(int xx, int yy, int d){
            x = xx;
            y = yy;
            dist = d;
        }
        public int compareTo(triplet t){
            if(this.dist < t.dist)
                return -1;
            if(this.dist > t.dist)
                return 1;
            return 0;
        }
    }

    static BufferedReader br = new BufferedReader(new InputStreamReader(
            System.in));
    static StringTokenizer st = new StringTokenizer("");

    static String next() throws Exception {
        while (true) {
            if (st.hasMoreTokens()) {
                return st.nextToken();
            }
            String s = br.readLine();
            if (s == null) {
                return null;
            }
            st = new StringTokenizer(s);
        }
    }

    static int r, c;
    static char graph [][];
    static int sx, sy, ex, ey;
    static int [] dx = new int []{0, 0, 1, -1};
    static int [] dy = new int []{1, -1, 0, 0};
    static int ans;

    public static int dijkstra(){
        PriorityQueue<triplet> q = new PriorityQueue<round192D.triplet>();
        boolean [][] vis = new boolean [r][c];
        q.offer(new triplet(sx, sy, 0));
        while(!q.isEmpty()){
            triplet t = q.poll();
            int x = t.x;
            int y = t.y;
            int dist = t.dist;
            if(x == ex && y == ey)
                return dist;
            if(vis[x][y])
                continue;
            vis[x][y] = true;
            for(int i = 0 ; i < 4 ; ++i){
                int nx = x + dx[i];
                int ny = y + dy[i];
                if(nx < 0 || ny < 0 || nx >= r || ny >= c)
                    continue;
                if(graph[nx][ny] != 'T' && !vis[nx][ny])
                    q.offer(new triplet(nx, ny, dist + 1));
            }
        }
        return -1;
    }

    public static void bfs(int dist){
        Queue<triplet> q = new LinkedList<triplet>();
        q.offer(new triplet(ex, ey, 0));
        boolean vis [][] = new boolean [r][c];
        while(!q.isEmpty()){
            triplet p = q.poll();
            int x = p.x;
            int y = p.y;
            int d = p.dist;
            if(Character.isDigit(graph[x][y]) && !vis[x][y])
                ans += (graph[x][y] - '0');
            if(vis[x][y])
                continue;
            vis[x][y] = true;
            for(int i = 0 ; i < 4 ; ++i){
                int nx = x + dx[i];
                int ny = y + dy[i];
                if(nx < 0 || ny < 0 || nx >= r || ny >= c || vis[nx][ny] || graph[nx][ny] == 'T' || d + 1 > dist)
                    continue;
                q.offer(new triplet(nx, ny, d + 1));
            }
        }
    }

    public static void main(String[] args) throws Exception {
        r = nextInt();
        c = nextInt();
        graph = new char [r][c];
        for(int i = 0 ; i < r ; ++i)
            graph[i] = next().toCharArray();
        for(int i = 0 ; i < r ; ++i){
            for(int j = 0 ; j < c ; ++j){
                if(graph[i][j] == 'S'){
                    sx = i;
                    sy = j;
                }
                if(graph[i][j] == 'E'){
                    ex = i;
                    ey = j;
                }
            }
        }       
        int shortest = dijkstra();
        bfs(shortest);
        System.out.println(ans);
    }
}

