                    dist[r][c] = dist[p.r][p.c] + 1;
                    q.add(new Pair(r, c));
                }
            }
        }
        int sd = dist[rs][rc];
        int ans = 0;
        for(int r = 0; r < m; r++) {
            for(int c = 0; c < n; c++) {
                if(a[r][c] > '0' && a[r][c] <= '9' && dist[r][c] <= sd) {
                    ans += a[r][c] - '0';
                }
            }
        }
        writer.println(ans);
        writer.flush();
    }

    void multiSolve() throws IOException {
        int n = readInts()[0];
        for(int i = 0; i < n; i++) {
            if(i > 0) writer.println();
            solve();
        }
    }

    public static void main(String[] args) throws IOException{
        new ProblemB().solve();
    }
}

