import java.io.*;
import java.util.*;

public class Biridian {

  static int R = -1;
  static int C = -1;
  static char[][] grid = null;
  static int INF = 100000000;
  static int[][] moves = null;
  static List<Integer> xPos = new ArrayList<Integer>();
  static List<Integer> yPos = new ArrayList<Integer>();

  public static void parseInput() {
    try {
      BufferedReader buf = new BufferedReader(new InputStreamReader(System.in));
      String[] tok = buf.readLine().split(" ");
      R = Integer.parseInt(tok[0]); C = Integer.parseInt(tok[1]);
      grid = new char[R][];
      for (int i = 0; i < R; i++) grid[i] = buf.readLine().toCharArray();
    } catch (Exception e) {}
  }

  public static void bfs() {
    boolean[][] visited = new boolean[R][C];
    moves = new int[R][C];
    for (int i = 0; i < grid.length; i++) {
      for (int j = 0; j < grid[i].length; j++) {
        moves[i][j] = INF;
        if (grid[i][j] == 'E') {
          xPos.add(i); yPos.add(j); visited[i][j] = true; moves[i][j] = 0;
        }
      }
    }
    int p = 0;
    while (p < xPos.size()) {
      int curX = xPos.get(p); int curY = yPos.get(p);
      if (curX+1 < grid.length && grid[curX+1][curY] != 'T' && !visited[curX+1][curY]) {
        xPos.add(curX+1); yPos.add(curY); moves[curX+1][curY] = 1 + moves[curX][curY]; visited[curX+1][curY] = true;
      }
      if (curX-1 >= 0             && grid[curX-1][curY] != 'T' && !visited[curX-1][curY]) {
        xPos.add(curX-1); yPos.add(curY); moves[curX-1][curY] = 1 + moves[curX][curY]; visited[curX-1][curY] = true;
      }
      if (curY+1 < grid[0].length    && grid[curX][curY+1] != 'T' && !visited[curX][curY+1]) {
        xPos.add(curX); yPos.add(curY+1); moves[curX][curY+1] = 1 + moves[curX][curY]; visited[curX][curY+1] = true;
      }
      if (curY-1 >= 0             && grid[curX][curY-1] != 'T' && !visited[curX][curY-1]) {
        xPos.add(curX); yPos.add(curY-1); moves[curX][curY-1] = 1 + moves[curX][curY]; visited[curX][curY-1] = true;
      }
      p++;
    }
  }

  public static void main(String[] args) {
    parseInput();
    bfs();
    int playerMoves = -1;
    for (int i = 0; i < grid.length; i++) {
      for (int j = 0; j < grid[i].length; j++) {
        if (grid[i][j] == 'S') playerMoves = moves[i][j];
      }
    }
    int res = 0;
    for (int i = 0; i < grid.length; i++) {
      for (int j = 0; j < grid[i].length; j++) {
        if (grid[i][j] >= '0' && grid[i][j] <= '9') {
          if (moves[i][j] <= playerMoves) {
            res += (int)(grid[i][j] - '0');
          }
        }
