import java.util.Queue;
public class BirrdianForest {
    static BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));
    static PrintWriter printWriter = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

    public static void main(String[] args) throws IOException{
    		String[] inputString = bufferedReader.readLine().split(" ");
    		int row = Integer.parseInt(inputString[0]);
    		int col = Integer.parseInt(inputString[1]);

    		char[][] forest = new char[row][col];
    		boolean[][] visited = new boolean[row][col];
    		int endR = -1;
    		int endC = -1;
    		boolean foundS = false;
    		boolean foundE = false;
    		for(int i = 0; i < row; i++) {
    			forest[i] = bufferedReader.readLine().toCharArray();

    			if( !foundE) {
                    for(int j = 0; j < col; j++) {
                        if(forest[i][j] == 'E') {
                            endR = i;
                            endC = j;
                            foundE = true;
                            break;
                        }
                    }
    			}
    		}

    		int r = endR;
    		int c = endC;
    		Queue<Integer> rows =new LinkedList<Integer>();
    		Queue<Integer> cols = new LinkedList<Integer>();
    		rows.offer(r);
    		cols.offer(c);
    		visited[r][c] = true;
    		int result = 0;
    		while(!rows.isEmpty() && !foundS) {
    			int size = rows.size();
    			for(int i = 0; i < size; i++) {
    				r = rows.poll();
    				c = cols.poll();

    				if(forest[r][c] == 'S') {
    					foundS = true;
    			} else if(forest[r][c] >= '1' && forest[r][c] <= '9') {
    					result += forest[r][c] - '0';
    			}

    				if(r - 1 >= 0 && forest[r-1][c] != 'T' && !visited[r-1][c]) {
    					rows.offer(r-1);
    					cols.offer(c);
    					visited[r-1][c] = true;
    			}
    			if(r + 1 < forest.length && forest[r+1][c] != 'T' && !visited[r+1][c]) {
    				rows.offer(r+1);
    				cols.offer(c);
    				visited[r+1][c] = true;
    		}
    			if(c - 1  >= 0 && forest[r][c-1] != 'T' && !visited[r][c-1]) {
    				rows.offer(r);
    				cols.offer(c-1);
    				visited[r][c-1] = true;
    		}
    			if(c + 1 < forest[0].length && forest[r][c+1] != 'T' && !visited[r][c+1]) {
    				rows.offer(r);
    				cols.offer(c+1);
    				visited[r][c+1] = true;
    		}

    			}
    		}

    		printWriter.println(result);
    		printWriter.flush();
    		printWriter.close();
    }
}

