		int n = nextInt();
		int m = nextInt();
		char[][] a = new char[n][m];
		for (int i = 0; i < n; i++) {
			a[i] = next().toCharArray();
		}
		int[] quex = new int[n * m];
		int[] quey = new int[n * m];
		int hd = 0;
		int tl = 1;
		int[][] d = new int[n][m];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (a[i][j] == 'E') {
					quex[0] = i;
					quey[0] = j;
					d[i][j] = 1;
				}
			}
		}
		while (hd < tl) {
			int curx = quex[hd];
			int cury = quey[hd];
