class TaskA {
    int[][] mat,dist,mark;
    int r,c;
    class node{
        int a,b;
        node(int row,int column){
            this.a = row;
            this.b = column;
        }
    }
    LinkedList<node> q;
    private boolean check(int i,int j){

        if (i >= 1 && i <= r && j >= 1 && j<= c && mat[i][j] != -3 && mark[i][j] == 0){

            return true;
        }

        return false;
    }
    private int find_dist(){
        int si=0,sj=0;
        for (int i = 1; i<=r; i++)
            for (int j = 1; j<=c; j++){
                if (mat[i][j] == -1)
                    q.add(new node(i,j));
                if (mat[i][j] == -2){
                    si = i;
                    sj = j;
                }
            }

        dist[q.peek().a][q.peek().b] = 0;
        while (!q.isEmpty()){
            node cur = q.remove();

            mark[cur.a][cur.b] = 1;
            int i = cur.a;
            int j = cur.b;
            if (check(i+1,j) == true){
                mark[i+1][j] = 1;
                q.add(new node(i+1,j));
                dist[i+1][j] = dist[i][j] + 1;
            }
            if (check(i-1,j) == true){
                mark[i-1][j] = 1;
                dist[i-1][j] = dist[i][j] + 1;
                q.add(new node(i-1,j));
            }
            if (check(i,j+1) == true){
                mark[i][j+1] = 1;
                dist[i][j+1] = dist[i][j] + 1;
                q.add(new node(i,j+1));
            }
            if (check(i,j-1) == true){
                mark[i][j-1] = 1;
                dist[i][j-1] = dist[i][j] + 1;
                q.add(new node(i,j-1));
            }
        }
        int ans = 0;

        for (int i = 1; i<=r; i++){
            for (int j = 1; j<=c; j++){
                if (dist[i][j] <= dist[si][sj] && mat[i][j] > 0 && (si != i || sj != j)){
                    ans += mat[i][j];
                }
            }
        }
        return ans;
    }
    public void solve(int testCase,InputReader in,PrintWriter out){
        mat = new int[2000][2000];
        dist = new int[2000][2000];
        mark = new int[2000][2000];
        String s[] = new String[2000];
        r = in.nextInt();c = in.nextInt();
        for (int i = 1; i<=r; i++)
            s[i] = in.next();
        for (int i = 1; i<=r; i++){
            for (int j = 0; j<s[i].length(); j++){
                dist[i][j+1] = 1000000009;

                if (s[i].charAt(j) >= 48 && s[i].charAt(j) <=57)
                    mat[i][j+1] = s[i].charAt(j)-48;
                else if (s[i].charAt(j) == 'E')
                    mat[i][j+1] = -1;
                else if (s[i].charAt(j) == 'S')
                    mat[i][j+1] = -2;
                else if (s[i].charAt(j) == 'T')
                    mat[i][j+1] = -3;
            }
        }
        q = new LinkedList<node>();
        out.println(find_dist());
    }
}

