		Queue<pair> q = new LinkedList<>();
		pair door = new pair(0, 0, 0);
		int ans = 0;
		char[][] chars = new char[r][c];
		boolean visited[][] = new boolean[r][c];
		for (int i = 0; i < r; i++) {
			String s = scn.next();
			for (int j = 0; j < c; j++) {
				chars[i][j] = s.charAt(j);
				if (s.charAt(j) == 'E') {
					door.x = i;
					door.y = j;
					door.d = 0;
				}
			}
		}
		q.add(door);
		boolean found = false;
		int maxd = 0;
		while (q.size() > 0) {
			pair p = q.remove();

			if (visited[p.x][p.y]) {
