		while (q.size() > 0) {
			pair p = q.remove();

			if (visited[p.x][p.y]) {
				continue;
			}
			if (chars[p.x][p.y] == 'S') {
				found = true;
				maxd = p.d;
			}
			else if (!found) {
				ans += chars[p.x][p.y] - '0';
				maxd = Math.max(maxd, p.d);
			} else if (found && p.d <= maxd) {
				ans += chars[p.x][p.y] - '0';

			}
			visited[p.x][p.y] = true;
			if (p.x + 1 < r && chars[p.x + 1][p.y] != 'T') {
				q.add(new pair(p.x + 1, p.y, p.d + 1));
			}
			if (p.y + 1 < c && chars[p.x][p.y + 1] != 'T') {
				q.add(new pair(p.x, p.y + 1, p.d + 1));
			}
			if (p.x - 1 >= 0 && chars[p.x - 1][p.y] != 'T') {
				q.add(new pair(p.x - 1, p.y, p.d + 1));
			}
			if (p.y - 1 >= 0 && chars[p.x][p.y - 1] != 'T') {
				q.add(new pair(p.x, p.y - 1, p.d + 1));
