        while (!frontR.isEmpty()) {
            ArrayList<Integer> nextFrontR = new ArrayList<Integer>();
            ArrayList<Integer> nextFrontC = new ArrayList<Integer>();
            for (int i = 0; i < frontR.size(); ++i) {
                int curR = frontR.get(i);
                int curC = frontC.get(i);
                for (int j = 0; j < 4; ++j) {
                    int nextR = curR + dx[j];
                    int nextC = curC + dy[j];
                    if (nextR >= 0 && nextR < r && nextC >= 0 && nextC < c
                        && res[nextR][nextC] == INF && map[nextR][nextC] != 'T') {
                        res[nextR][nextC] = t;
                        nextFrontR.add(nextR);
                        nextFrontC.add(nextC);
                    }
                }
            }
            frontR = nextFrontR;
            frontC = nextFrontC;
            ++t;
        }
        return res;
    }

