                    startR = i;
                    startC = j;
                } else if (s[j] == 'E') {
                    endR = i;
                    endC = j;
                }
            }
        }

        int[][] d = calcDistances(endR, endC);
        int t = d[startR][startC];

        int res = 0;
        for (int i = 0; i < r; ++i) for (int j = 0; j < c; ++j) {
            if (d[i][j] <= t && map[i][j] >= '1' && map[i][j] <= '9')
                res += (map[i][j] - '0');
        }

        out.println(res);
    }
