        int ey = -1;
        int sx = -1;
        int sy = -1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (mat[i][j] == 'E') {
                    ex = i;
                    ey = j;
                }
                else if (mat[i][j] == 'S') {
                    sx = i;
                    sy = j;
                }
            }
        }

        Deque<Integer> deckx = new LinkedList<>();
        Deque<Integer> decky = new LinkedList<>();
        Deque<Integer> dist = new LinkedList<>();
        boolean[][] vis = new boolean[n][m];
        deckx.add(ex);
        decky.add(ey);
        dist.add(0);
        vis[ex][ey] = true;
        int[][] res = new int[n][m];
        while (!deckx.isEmpty()) {
            int curx = deckx.removeFirst();
            int cury = decky.removeFirst();
            int curdist = dist.removeFirst();
            res[curx][cury] = curdist;
            for (int i = 0; i < dx.length; i++) {
                int nx = curx + dx[i];
                int ny = cury + dy[i];
                if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
                    if (mat[nx][ny] != 'T' && !vis[nx][ny]) {
                        vis[nx][ny] = true;
                        deckx.addLast(nx);
                        decky.addLast(ny);
                        dist.addLast(curdist + 1);
                    }
                }
            }
        }

        int sum = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (res[i][j] <= res[sx][sy] && mat[i][j] >= '1' && mat[i][j] <= '9' && vis[i][j]) {
                    sum += mat[i][j] - '0';
                }
            }
        }

        out(sum);
    }

    void shuffle(int[] a) {
        int n = a.length;
        for(int i = 0; i < n; i++) {
            int r = i + (int) (Math.random() * (n - i));
            int tmp = a[i];
            a[i] = a[r];
            a[r] = tmp;
        }
    }

    long gcd(long a, long b) {
        while(a != 0 && b != 0) {
            long c = b;
            b = a % b;
            a = c;
        }
        return a + b;
    }

