    static class BBiridianForest {
        char[][] ar;
        int n;
        int m;
        long[][] dis;

        public boolean isvalid(int x, int y) {
            return x >= 0 && x < n && y >= 0 && y < m && ar[x][y] != 'T';
        }

        private int dijkstra(int x, int y) {
            int tt = 0;
            PriorityQueue<pair> pq = new PriorityQueue<pair>();
            pq.add(new pair(x, y, 0));
            for (int i = 0; i < n; i++) Arrays.fill(dis[i], 1000000000);
            boolean[][] vis = new boolean[n][m];
            while (pq.size() > 0) {
                tt++;
                pair pp = pq.poll();
                if (vis[pp.x][pp.y]) continue;
                vis[pp.x][pp.y] = true;
                dis[pp.x][pp.y] = pp.dis;
                if (isvalid(pp.x + 1, pp.y) && !vis[pp.x + 1][pp.y])
                    pq.add(new pair(pp.x + 1, pp.y, pp.dis + 1));
                if (isvalid(pp.x - 1, pp.y) && !vis[pp.x - 1][pp.y])
                    pq.add(new pair(pp.x - 1, pp.y, pp.dis + 1));
                if (isvalid(pp.x, pp.y + 1) && !vis[pp.x][pp.y + 1])
                    pq.add(new pair(pp.x, pp.y + 1, pp.dis + 1));
                if (isvalid(pp.x, pp.y - 1) && !vis[pp.x][pp.y - 1])
                    pq.add(new pair(pp.x, pp.y - 1, pp.dis + 1));
