import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.Queue;

public class CF {

    public static void main(String[] args) throws IOException {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = new char[n][m];
        int doorRow = 0;
        int doorColumn = 0;
        int playerRow = 0;
        int playerColum = 0;
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == 'E') {
                    doorRow = i;
                    doorColumn = j;
                } else if (grid[i][j] == 'S') {
                    playerRow = i;
                    playerColum = j;
                }
            }
        }

        int[][] used = new int[n][m];
        for (int i = 0; i < used.length; i++) {
            Arrays.fill(used[i], -1);
        }

        Queue<Integer> queue = new LinkedList<>();
        queue.add(doorRow);
        queue.add(doorColumn);
        used[doorRow][doorColumn] = 0;

        while (!queue.isEmpty()) {
            int curRow = queue.poll();
            int curColumn = queue.poll();

            if (check(curRow + 1, curColumn, n, m) && grid[curRow + 1][curColumn] != 'T'
                    && used[curRow + 1][curColumn] == -1) {
                used[curRow + 1][curColumn] = used[curRow][curColumn] + 1;
                queue.add(curRow + 1);
                queue.add(curColumn);
            }
            if (check(curRow - 1, curColumn, n, m) && grid[curRow - 1][curColumn] != 'T'
                    && used[curRow - 1][curColumn] == -1) {
                used[curRow - 1][curColumn] = used[curRow][curColumn] + 1;
                queue.add(curRow - 1);
                queue.add(curColumn);
            }
            if (check(curRow, curColumn + 1, n, m) && grid[curRow][curColumn + 1] != 'T'
                    && used[curRow][curColumn + 1] == -1) {
                used[curRow][curColumn + 1] = used[curRow][curColumn] + 1;
                queue.add(curRow);
                queue.add(curColumn + 1);
            }
            if (check(curRow, curColumn - 1, n, m) && grid[curRow][curColumn - 1] != 'T'
                    && used[curRow][curColumn - 1] == -1) {
                used[curRow][curColumn - 1] = used[curRow][curColumn] + 1;
                queue.add(curRow);
                queue.add(curColumn - 1);
            }
        }

        int res = 0;
        for (int i = 0; i < used.length; i++) {
            for (int j = 0; j < used[0].length; j++) {
                if (i == playerRow && j == playerColum) continue;
                if (i == doorRow && j == doorColumn) continue;
                if (used[i][j] == -1) continue;

                if (used[i][j] <= used[playerRow][playerColum]) {
                    res += (grid[i][j] - '0');
                }
            }
        }
        out.println(res);
        out.close();
    }

    public static boolean check(int row, int column, int maxRow, int maxColumn) {
        return row >= 0 && row < maxRow && column >= 0 && column < maxColumn;
    }
}

