public class _25_Biridian_Forest {
	static int ei, ej = -1;
	static int si, sj = -1;
	static int[][] arr;
	static int[][] dist;

	public static void main(String[] args) {
		Scanner scn = new Scanner(System.in);
		int n = scn.nextInt();
