				rec = nt;
			}
			if (map[ny][nx] >= 1) {
				timetbl[nt] += map[ny][nx];
			}
			for (int d = 0 ; d < 4 ; d++) {
				int tx = nx + Dx[d];
				int ty = ny + Dy[d];
				if (tx < 0 || tx >= c || ty < 0 || ty >= r || map[ty][tx] == -1) {
					continue;
				}
				if (!done[ty][tx]) {
					done[ty][tx] = true;
					q.add(tx);
					q.add(ty);
					q.add(nt+1);
				}
			}
		}

		int numBattle = 0;
		for (int i = 0 ; i <= rec ; i++) {
			numBattle += timetbl[i];
		}
		return numBattle;
	}

	public static void debug(Object... o) {
