	}
}

import java.io.IOException;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Queue;
import java.util.Scanner;
import java.util.concurrent.ArrayBlockingQueue;

public class ProblemB {

	static final int[] Dx = {1, 0, -1, 0};
	static final int[] Dy = {0, 1, 0, -1};

	public static void main(String[] args) throws IOException {
		Scanner in = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);

		int r = in.nextInt();
		int c = in.nextInt();

		int[][] map = new int[r][c];
		int sx = -1, sy = -1;
		int gx = -1, gy = -1;
		for (int i = 0 ; i < r ; i++) {
			String l = in.next();
			for (int j = 0 ; j < c ; j++) {
				if (l.charAt(j) == 'S') {
					sx = j;
					sy = i;
				} else if (l.charAt(j) == 'E') {
					gx = j;
					gy = i;
				} else if (l.charAt(j) == 'T') {
					map[i][j] = -1;
				}
				if (l.charAt(j) >= '0' && l.charAt(j) <= '9') {
					map[i][j] = l.charAt(j) - '0';
				}
			}
		}
		out.println(plan(map, sx, sy, gx, gy));
		out.flush();
	}

	private static int plan(int[][] map, int sx, int sy, int gx, int gy) {
		int r = map.length;
		int c = map[0].length;

		int[] timetbl = new int[r*c+10];

		Queue<Integer> q = new ArrayBlockingQueue<Integer>(r*c*4);
		q.add(gx);
		q.add(gy);
		q.add(0);
		boolean[][] done = new boolean[r][c];
		done[gy][gx] = true;

		int rec = -1;
		while (q.size() >= 1) {
			int nx = q.poll();
			int ny = q.poll();
			int nt = q.poll();
			if (nx == sx && ny == sy) {
				rec = nt;
			}
			if (map[ny][nx] >= 1) {
				timetbl[nt] += map[ny][nx];
			}
			for (int d = 0 ; d < 4 ; d++) {
				int tx = nx + Dx[d];
				int ty = ny + Dy[d];
				if (tx < 0 || tx >= c || ty < 0 || ty >= r || map[ty][tx] == -1) {
					continue;
				}
				if (!done[ty][tx]) {
					done[ty][tx] = true;
					q.add(tx);
					q.add(ty);
					q.add(nt+1);
				}
			}
		}

		int numBattle = 0;
		for (int i = 0 ; i <= rec ; i++) {
			numBattle += timetbl[i];
		}
		return numBattle;
	}

	public static void debug(Object... o) {
		System.err.println(Arrays.deepToString(o));
	}
}

import java.io.*;
