public class cfjava {
    public static void main(String[] args) {
        OutputStream outputStream = System.out;
        FastReader in = new FastReader();
        PrintWriter out = new PrintWriter(outputStream);
        PROBLEM solver = new PROBLEM();
        int t = 1;
        for (int i = 0; i < t; i++) {
            solver.solve(in, out);
        }
        out.close();
    }

    static class PROBLEM {
        public void solve(FastReader in, PrintWriter out) {
            int r = in.nextInt();
            int c = in.nextInt();
            char[][] grid = new char[r][c];
            int startx = 0, starty = 0;
            int[][] vis = new int[r][c];
            Queue<pair> q = new LinkedList<>();

            for (int i = 0; i < r; i++) {
                grid[i] = in.nextLine().toCharArray();
                for (int j = 0; j < c; j++) {
                    if (grid[i][j] == 'E') {
                        q.add(new pair(i, j, 0));
                    } else if (grid[i][j] == 'S') {
                        startx = i;
                        starty = j;
                    }
                }
            }

            int startDist = -1;
            while (!q.isEmpty()) {
                pair cur = q.poll();
                int x = cur.x, y = cur.y, len = cur.len;
                if (vis[x][y] != 0) continue;
                vis[x][y] = len;
                if (grid[x][y] == 'S') {
                    startDist = len;
                }
                if (x + 1 >= 0 && x + 1 < r && vis[x + 1][y] == 0 && grid[x + 1][y] != 'T') {
                    q.add(new pair(x + 1, y, len + 1));
                }
                if (x - 1 >= 0 && x - 1 < r && vis[x - 1][y] == 0 && grid[x - 1][y] != 'T') {
                    q.add(new pair(x - 1, y, len + 1));
                }
                if (y + 1 >= 0 && y + 1 < c && vis[x][y + 1] == 0 && grid[x][y + 1] != 'T') {
                    q.add(new pair(x, y + 1, len + 1));
                }
                if (y - 1 >= 0 && y - 1 < c && vis[x][y - 1] == 0 && grid[x][y - 1] != 'T') {
                    q.add(new pair(x, y - 1, len + 1));
                }
            }

            int ans = 0;
            for (int i = 0; i < r; i++) {
                for (int j = 0; j < c; j++) {
                    char ch = grid[i][j];
                    if (ch >= '0' && ch <= '9') {
                        if (vis[i][j] != 0 && vis[i][j] <= startDist) {
                            ans += ch - '0';
                        }
                    }
                }
            }
            out.println(ans);
        }
    }

    static class pair {
        int x, y, len;
        pair(int x, int y, int len) {
            this.x = x;
            this.y = y;
            this.len = len;
        }
    }

    static class enemy {
        int x, y, nn;
        enemy(int x, int y, int nn) {
            this.x = x;
            this.y = y;
            this.nn = nn;
        }
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        boolean nextBoolean() {
            return Boolean.parseBoolean(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

