public class cf330d {
  public static void main(String[] args) {
    FastScanner in = new FastScanner(System.in);
    int n = in.nextInt();
    int m = in.nextInt();
    char[][] v = new char[n][];
    for(int i=0; i<n; i++)
      v[i] = in.next().trim().toCharArray();
    int[] dx = {0,1,0,-1}, dy = {1,0,-1,0};
    ArrayDeque<Integer> q = new ArrayDeque<Integer>();
    int oo = 987654321;
    int[][] dist = new int[n][m];
    int ex=0,ey=0,sx=0,sy=0;
    for(int i=0; i<n; i++)
      for(int j=0; j<m; j++)
        if(v[i][j] == 'E') {
          ex = i;
          ey = j;
        }
        else if(v[i][j] == 'S') {
          sx = i;
          sy = j;
        }
    for(int[] x : dist) Arrays.fill(x,oo);
    dist[ex][ey] = 0;
    q.add(ex);
    q.add(ey);
    while(!q.isEmpty()) {
      int cx = q.poll();
      int cy = q.poll();
      for(int i=0; i<4; i++) {
        int nx = cx+dx[i];
        int ny = cy+dy[i];
        if(nx < 0 || ny < 0 || nx >= n || ny >= m) continue;
        if(v[nx][ny] == 'T') continue;
        if(dist[nx][ny] > 1+dist[cx][cy]) {
          dist[nx][ny] = 1+dist[cx][cy];
          q.add(nx);
          q.add(ny);
        }
      }
    }
    int ans = 0;
    int thresh = dist[sx][sy];
    for(int i=0; i<n; i++)
      for(int j=0; j<m; j++)
        if(v[i][j] >= '0' && v[i][j] <= '9' && dist[i][j] <= thresh)
          ans += v[i][j]-'0';
    System.out.println(ans);
  }
