import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;
import java.util.Queue;
import java.util.LinkedList;

public class biridianForest {


    static class FastReader
    {
        BufferedReader br;
        StringTokenizer st;

        public FastReader()
        {
            br = new BufferedReader(new
                    InputStreamReader(System.in));
        }

        String next()
        {
            while (st == null || !st.hasMoreElements())
            {
                try
                {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException e)
                {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt()
        {
            return Integer.parseInt(next());
        }

        long nextLong()
        {
            return Long.parseLong(next());
        }

        double nextDouble()
        {
            return Double.parseDouble(next());
        }

        String nextLine()
        {
            String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }
    }

    private static boolean validateVertex (int[][] arr, int row, int col) {
        return (row >= 0) && (col >= 0) && (row < arr.length) && (col < arr[0].length);
    }


    public static void main(String[] args) {
        FastReader s = new FastReader();
        int r = s.nextInt();
        int c = s.nextInt();

        int[][] arr = new int[r][c];

        int er = 0;
        int ec = 0;

        int sr = 0;
        int sc = 0;

        for (int i = 0; i < r; i++) {
            String str = s.nextLine();
            for (int j = 0; j < c; j++) {
                if (str.charAt(j) == 'T') {
                    arr[i][j] = -1;
                }
                else if (str.charAt(j) == 'E') {
                    er = i;
                    ec = j;
                    arr[i][j] = 0;
                }

                else if (str.charAt(j) == 'S') {
                    sr = i;
                    sc = j;
                    arr[i][j] = -2;

                }

                else arr[i][j] = Character.getNumericValue(str.charAt(j));
            }
        }

        int[][] min = new int[r][c];
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                min[i][j] = Integer.MAX_VALUE;
            }
        }

        min[er][ec] = 0;
        boolean[][] visited = new boolean[r][c];

        Queue<Integer> rowQ = new LinkedList<Integer>();
        Queue<Integer> colQ = new LinkedList<Integer>();

        ((LinkedList<Integer>) rowQ).add(er);
        ((LinkedList<Integer>) colQ).add(ec);
        visited[er][ec] = true;

        while (!rowQ.isEmpty()) {

            int row = rowQ.remove();
            int col = colQ.remove();

            if (validateVertex(arr, row + 1, col) && !visited[row + 1][col] && arr[row + 1][col] != -1) {
                rowQ.add(row + 1);
                colQ.add(col);
                min[row + 1][col] = min[row][col] + 1;
                visited[row + 1][col] = true;
            }

            if (validateVertex(arr, row - 1, col) && !visited[row - 1][col] && arr[row - 1][col] != -1) {
                rowQ.add(row - 1);
                colQ.add(col);
                min[row - 1][col] = min[row][col] + 1;
                visited[row - 1][col] = true;
            }

