import java.io.PrintWriter;
import java.util.Scanner;

public class Solution {
    static int[][] pi = { { 0, 1, 2 }, { 0, 1, 2 }, { 0, 1, 2 }, { 0, 0, 0 }, { 1, 1, 1 }, { 2, 2, 2 }, { 0, 1, 2 }, { 2, 1, 0 } };
    static int[][] pj = { { 0, 0, 0 }, { 1, 1, 1 }, { 2, 2, 2 }, { 0, 1, 2 }, { 0, 1, 2 }, { 0, 1, 2 }, { 0, 1, 2 }, { 0, 1, 2 } };

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        char[][] c = new char[3][3];

        for (int i = 0; i < 3; i++) {
            String s = in.nextLine();
            for (int j = 0; j < 3; j++)
                c[i][j] = s.charAt(j);
        }

        int c0 = 0;
        int cx = 0;

        for (int i = 0; i < 3; i++)
            for (int j = 0; j < 3; j++)
                if (c[i][j] == '0')
                    c0++;
                else if (c[i][j] == 'X')
                    cx++;

        if (c0 > cx || cx - c0 > 1)
            out.print("illegal");
        else {
            boolean wonx = isWon(c, 'X');
            boolean won0 = isWon(c, '0');

            if (wonx && won0)
                out.print("illegal");
            else if (wonx && cx - c0 == 1)
                out.print("the first player won");
            else if (wonx)
                out.print("illegal");
            else if (won0 && cx == c0)
                out.print("the second player won");
            else if (won0)
                out.print("illegal");
            else if (cx + c0 == 9)
                out.print("draw");
            else if (cx == c0)
                out.print("first");
            else
                out.print("second");
        }

        out.close();
    }

    private static boolean isWon(char[][] c, char x) {
        for (int i = 0; i < pi.length; i++)
            if (c[pi[i][0]][pj[i][0]] == c[pi[i][1]][pj[i][1]] && 
                c[pi[i][1]][pj[i][1]] == c[pi[i][2]][pj[i][2]] && 
                c[pi[i][0]][pj[i][0]] == x)
                return true;
        return false;
    }
}

