import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.*;

public class Driver
{
    public static void main(String args[])
    {
        try
        {

            BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
            String[] board = new String[3];

            board[0] = reader.readLine();
            board[1] = reader.readLine();
            board[2] = reader.readLine();

            String result = "";

            if(illegal(board))
            {
                result = "illegal";
            }
            else if(threeInARow(board, 'X'))
            {
                result = "the first player won";
            }
            else if(threeInARow(board, '0'))
            {
                result = "the second player won";
            }
            else if(draw(board))
            {
                result = "draw";
            }
            else if(count(board, 'X') == count(board, '0'))
            {
                result = "first";
            }
            else if(count(board, 'X') == count(board, '0') + 1)
            {
                result = "second";
            }
            else
            {
                result = "unexpected";
            }

            System.out.println(result);

            reader.close();

        }
        catch(Exception ex)
        {
            System.out.println("ERROR");
        }
    }

    public static boolean draw(String[] board)
    {
        for(String row : board)
        {
            if(row.charAt(0) == '.')
            {
                return false;
            }

            if(row.charAt(1) == '.')
            {
                return false;
            }

            if(row.charAt(2) == '.')
            {
                return false;
            }
        }

        return true;
    }

    public static boolean illegal(String[] board)
    {
        if(!validCount(board))
        {
            return true;
        }

        if(threeInARow(board, 'X'))
        {
            if(threeInARow(board, '0')) 
            {
                return true;
            }

            if(count(board, 'X') == count(board, '0')) 
            {
                return true;
            }
        }
        else if(threeInARow(board, '0'))
        {
            if(count(board, 'X') > count(board, '0')) 
            {
                return true;
            }
        }

        return false;
    }

    public static int count(String[] board, char value)
    {
        int count = 0;
        for(String row : board)
        {
            if(row.charAt(0) == value)
            {
                count++;
            }

            if(row.charAt(1) == value)
            {
                count++;
            }

            if(row.charAt(2) == value)
            {
                count++;
            }
        }

        return count;
    }


    public static boolean validCount(String[] board)
    {
        int x = count(board, 'X');
        int o = count(board, '0');

        if(x == o || x == o + 1)
        {
            return true;
        }

        return false;
    }

    public static boolean threeInARow(String[] board, char value)
    {
        for(int i = 0; i < 3; i++)
        {
            String col = "" + board[0].charAt(i) + board[1].charAt(i) + board[2].charAt(i);
            if(stringThree(col, value))
            {
                return true;
            }

            if(stringThree(board[i], value))
            {
                return true;
            }
        }

        String topDiagonal = "" + board[0].charAt(0) + board[1].charAt(1) + board[2].charAt(2);
        if(stringThree(topDiagonal, value))
        {
            return true;
        }

        String bottomDiagonal = "" + board[2].charAt(0) + board[1].charAt(1) + board[0].charAt(2);
        if(stringThree(bottomDiagonal, value))
        {
            return true;
        }

        return false;
    }

    public static boolean stringThree(String str, char value)
    {
        return str.charAt(0) == str.charAt(1) && str.charAt(1) == str.charAt(2) && str.charAt(0) == value;
    }
}

