				} else if (!isFLined && !isSLined) {
					if ((fcount+scount) == 9) {
						System.out.print("draw");
					} else {
						System.out.print("second");
					}
				} else {
					System.out.print("illegal");
				}
			} else if (fcount == scount) {
				if (!isFLined && !isSLined) {
					System.out.print("first");
				} else if (!isFLined && isSLined) {
					System.out.print("the second player won");
				} else {
					System.out.print("illegal");
				}
			} else {
				System.out.print("illegal");
			}


		} catch (Exception e) {
			e.printStackTrace();
		}
	}

	private boolean isLined(char c) {
		int hcount = 0;
		int vcount = 0;
		int d1count = 0;
		int d2count = 0;
		for (int i = 0; i < 3; i++) {
			if ((c == pos[i][0]) && (c == pos[i][1]) && (c == pos[i][2]))
				hcount++;

			if ((c == pos[0][i]) && (c == pos[1][i]) && (c == pos[2][i]))
				vcount++;
		}

		if ((c == pos[0][0]) && (c==pos[1][1]) && (c == pos[2][2]))
			d1count++;

		if ((c == pos[0][2]) && (c==pos[1][1]) && (c == pos[2][0]))
			d2count++;

		if ((hcount == 1) || (vcount == 1) || (d1count == 1) || (d2count == 1))
			return true;
		else
			return false;

	}

	private String next() throws IOException {
		if (st == null || !st.hasMoreTokens())
			st = new StringTokenizer(bf.readLine());
		return st.nextToken();
	}

	public static void main(String[] args) {

		C3C c = new C3C();
	}
}

