import java.io.*;
import java.util.*;

public class Template implements Runnable {

    BufferedReader in;
    PrintWriter out;
    StringTokenizer tok = new StringTokenizer("");

    void init() throws FileNotFoundException {
        try {
            in = new BufferedReader(new FileReader("input.txt"));
            out = new PrintWriter("output.txt");
        } catch (Exception e) {
            in = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out);
        }
    }

    String readString() throws IOException {
        while (!tok.hasMoreTokens()) {
            try {
                tok = new StringTokenizer(in.readLine());
            } catch (Exception e) {
                return null;
            }
        }
        return tok.nextToken();
    }

    int readInt() throws IOException {
        return Integer.parseInt(readString());
    }

    int[] readIntArray(int size) throws IOException {
        int[] res = new int[size];
        for (int i = 0; i < size; i++) {
            res[i] = readInt();
        }
        return res;
    }

    long readLong() throws IOException {
        return Long.parseLong(readString());
    }

    double readDouble() throws IOException {
        return Double.parseDouble(readString());
    }

    <T> List<T>[] createGraphList(int size) {
        List<T>[] list = new List[size];
        for (int i = 0; i < size; i++) {
            list[i] = new ArrayList<>();
        }
        return list;
    }

    public static void main(String[] args) {
        new Template().run();

    }

    long timeBegin, timeEnd;

    void time() {
        timeEnd = System.currentTimeMillis();
        System.err.println("Time = " + (timeEnd - timeBegin));
    }

    long memoryTotal, memoryFree;

    void memory() {
        memoryFree = Runtime.getRuntime().freeMemory();
        System.err.println("Memory = " + ((memoryTotal - memoryFree) >> 10)
                + " KB");
    }

    public void run() {
        try {
            timeBegin = System.currentTimeMillis();
            memoryTotal = Runtime.getRuntime().freeMemory();
            init();
            solve();
            out.close();
            if (System.getProperty("ONLINE_JUDGE") == null) {
                time();
                memory();
            }
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(-1);
        }
    }

    boolean equal(char[][] a, char[][] b) {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (a[i][j] != b[i][j]) return false;
            }
        }
        return true;
    }

    char CROSS = 'X';
    char ZERO = '0';

    boolean found = false;
    char now = '$';
    boolean draw = false;

    void brut(char[][] a, char[][] b, char now) {
        if (equal(a, b)) {
            found = true;
            this.now = now;
            draw = true;
            for (char[] x : a) {
                for (char y : x) {
                    if (y == '.') draw = false;
                }
            }
        }
        if (winner(b, CROSS) || winner(b, ZERO)) return;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (b[i][j] == '.') {
                    b[i][j] = now;
                    brut(a, b, now == CROSS ? ZERO : CROSS);
                    b[i][j] = '.';
                }
            }
        }
    }

    boolean winner(char[][] a, char x) {
        for (int i = 0; i < 3; i++) {
            if (a[i][0] == x && a[i][1] == x && a[i][2] == x) return true;
            if (a[0][i] == x && a[1][i] == x && a[2][i] == x) return true;
        }
        if (a[0][0] == x && a[1][1] == x && a[2][2] == x) return true;
        if (a[0][2] == x && a[1][1] == x && a[2][0] == x) return true;
        return false;
    }

    void solve() throws IOException {
        char[][] a = new char[3][];
        a[0] = readString().toCharArray();
        a[1] = readString().toCharArray();
        a[2] = readString().toCharArray();
        char[][] b = {{'.', '.', '.'}, {'.', '.', '.'}, {'.', '.', '.'}};
        brut(a, b, CROSS);
        if (!found) {
            out.println("illegal");
            return;
        }
        boolean xwin = winner(a, CROSS);
        boolean owin = winner(a, ZERO);
        if (xwin) {
            out.println("the first player won");
            return;
        }
        if (owin) {
            out.println("the second player won");
            return;
        }
        if (draw) {
            out.println("draw");
            return;
        }
        if (now == CROSS) {
            out.println("first");
        } else {
            out.println("second");
        }

    }

}

