		for (int i = 0; i < board.length; i++) {
			strLine=br.readLine();
			for (int j = 0; j < board[i].length; j++) {
				board[i][j]=strLine.charAt(j);
				if(board[i][j]=='X')
					Xcount++;
				else if(board[i][j]=='0')
					Ocount++;
			}
		}

		boolean checkX,checkO;
		int count1=0,count2=0;
		for (int i = 0; i < 3; i++)
		{
			checkO=true;
            checkX=true;
			for (int j = 0; j < 3; j++)
			{
				if(board[i][j]=='X')
                    checkO = false;
                else if(board[i][j]=='0')
                    checkX = false;
                else if(board[i][j]=='.')
                {
                    checkO = false;
                    checkX = false;
                }
            }
			if(checkX)
				count1 ++;
            if(checkO)
            	count2++;
	    }

		for(int i=0; i<3; i++)
		{
			checkO=true;
            checkX=true;
            for (int j=0; j<3; j++)
            {

                if(board[j][i]=='X')
                    checkO = false;
                else if(board[j][i]=='0')
                    checkX = false;
                else if(board[j][i]=='.')
                {
                    checkO = false;
                    checkX = false;
                }
            } 
            if(checkX)
            	count1++;
            if(checkO)
            	count2++;
        }

		checkX=true;
		checkO=true;
		for (int j=0; j<3; j++) 
		{
            if (board[j][j] == 'X') 
                checkO = false;
            else if (board[j][j] == '0') 
                checkX = false;
            else if (board[j][j] == '.')
            {
                checkO = false;
                checkX = false;
            }
        }
		if(checkX)
        	count1++;
        if(checkO)
        	count2++;
        int c=2;
		checkX=true;
		checkO=true;
		for (int j=0; j<3; j++, c--) 
		{
            if (board[j][c] == 'X') 
                checkO = false;
            else if (board[j][c] == '0') 
                checkX = false;
            else if (board[j][c] == '.') 
            {
                checkO = false;
                checkX = false;
            }
        }
		if(checkX)
        	count1++;
        if(checkO)
        	count2++;

        if((count1 > 0 && count2 > 0) || (Ocount>Xcount) || (Xcount - Ocount >= 2) || (count1>0 && Xcount <= Ocount) || (count2>0 && Ocount != Xcount))
        	pw.println("illegal");
        else if(count1>0)
        	pw.println("the first player won");
        else if(count2>0) 
        	pw.println("the second player won");
        else if(Ocount+Xcount==9) 
        	pw.println("draw");
        else if(Ocount==Xcount) 
        	pw.println("first");
        else if(Xcount>Ocount) 
        	pw.println("second");
        br.close();
        pw.close();
	}

}

