			game[i] = s.next().toCharArray();
			for (int j=0;j<3;j++)
			{
				if (game[i][j] == 'X') 
				{
					first_move++;
				}
				else if (game[i][j] == '0') 
				{
					second_move++;
				}
			}
		}


		int total_move = first_move + second_move;
