                    ttt.a[i][j] = 1;
                    n1++;
                }
                else if (x.charAt(j) == '0') {
                    ttt.a[i][j] = 2;
                    n2++;
                }
                else ttt.a[i][j] = 0;
            }
        }
        if (n1-n2 > 1 || n1 < n2 || (ttt.win(1) && ttt.win(2))) {
            System.out.println("illegal");
