import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Solution implements Runnable {

	public static void main(String[] args) {
		(new Thread(new Solution())).start();
	}

	BufferedReader in;
	PrintWriter out;
	StringTokenizer st;

	String nextToken() throws IOException {
		while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(in.readLine());
		return st.nextToken();
	}

	int nextInt() throws IOException {
		return Integer.parseInt(nextToken());
	}

	double nextDouble() throws IOException {
		return Double.parseDouble(nextToken());
	}

	char vig(char[][] m) {
		for (int i = 0; i < 3; i++) {
			boolean f = true;
			for (int j = 1; j < 3; j++) f &= (m[i][j] == m[i][j - 1]);
			if (f && m[i][0] != '.') return m[i][0];
		}
		for (int i = 0; i < 3; i++) {
			boolean f = true;
			for (int j = 1; j < 3; j++) f &= (m[j][i] == m[j - 1][i]);
			if (f && m[0][i] != '.') return m[0][i];
		}
		boolean f = true;
		for (int i = 1; i < 3; i++) f &= (m[i][i] == m[i - 1][i - 1]);
		if (f && m[0][0] != '.') return m[0][0];
		f = true;
		for (int i = 1; i < 3; i++) f &= (m[i][2 - i] == m[i - 1][2 - i + 1]);
		if (f && m[0][2] != '.') return m[0][2];
		return '.';
	}

	void solve() throws IOException {
		char[][] m = new char[3][3];
		int x = 0, o = 0;
		for (int i = 0; i < 3; i++) {
			String s = nextToken();
			for (int j = 0; j < 3; j++) {
				m[i][j] = s.charAt(j);
				if (m[i][j] == 'X') x++;
				if (m[i][j] == '0') o++;
			}
		}
		if (x != o && x != o + 1) {
			out.print("illegal");
			return;
		}
		char c = vig(m);
		if (c == '.') {
			if (x + o == 9) out.print("draw"); else {
				if (x == o) out.print("first"); else out.print("second");
			}
		} else {
			if (c == 'X' && x == o + 1) out.print("the first player won"); else
				if (c == '0' && x == o) out.print("the second player won"); else
					out.print("illegal");
		}
	}

	public void run() {
		try {
			in = new BufferedReader(new InputStreamReader(System.in));
			out = new PrintWriter(System.out);
			solve();
		} catch (IOException e) {
			e.printStackTrace();
		}
		out.flush();
	}

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Solution implements Runnable {

	public static void main(String[] args) {
		(new Thread(new Solution())).start();
	}

	BufferedReader in;
	PrintWriter out;
	StringTokenizer st;

	String nextToken() throws IOException {
		while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(in.readLine());
		return st.nextToken();
	}

	int nextInt() throws IOException {
		return Integer.parseInt(nextToken());
	}

	double nextDouble() throws IOException {
		return Double.parseDouble(nextToken());
	}

	/* Checks if there is a winning line and returns the winning symbol,
	   or '.' if there is none. */
	char vig(char[][] m) {
		for (int i = 0; i < 3; i++) {
			boolean f = true;
			for (int j = 1; j < 3; j++) f &= (m[i][j] == m[i][j - 1]);
			if (f && m[i][0] != '.') return m[i][0];
		}
		for (int i = 0; i < 3; i++) {
			boolean f = true;
			for (int j = 1; j < 3; j++) f &= (m[j][i] == m[j - 1][i]);
			if (f && m[0][i] != '.') return m[0][i];
		}
		boolean f = true;
		for (int i = 1; i < 3; i++) f &= (m[i][i] == m[i - 1][i - 1]);
		if (f && m[0][0] != '.') return m[0][0];
		f = true;
		for (int i = 1; i < 3; i++) f &= (m[i][2 - i] == m[i - 1][2 - i + 1]);
		if (f && m[0][2] != '.') return m[0][2];
		return '.';
	}

	void solve() throws IOException {
		char[][] m = new char[3][3];
		int x = 0, o = 0;
		for (int i = 0; i < 3; i++) {
			String s = nextToken();
			for (int j = 0; j < 3; j++) {
				m[i][j] = s.charAt(j);
				if (m[i][j] == 'X') x++;
				if (m[i][j] == '0') o++;
			}
		}
		/* Illegal number of moves */
		if (x != o && x != o + 1) {
			out.print("illegal");
			return;
		}
		char c = vig(m);
		if (c == '.') {
			/* No winner yet */
			if (x + o == 9) {
				out.print("draw");
			} else {
				if (x == o) out.print("first");
				else out.print("second");
			}
		} else {
			/* There is a winner */
			if (c == 'X' && x == o + 1) {
