import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.util.ArrayList;

public class Tic_tac_toe {
    static int empty,xnum,onum;
    static BufferedReader in;
    static BufferedWriter out;
    static boolean xw, ow;
    public static void main(String[] args) throws IOException{
        in = new BufferedReader(new InputStreamReader(System.in));
        out = new BufferedWriter(new OutputStreamWriter(System.out));
        empty=0;
        xnum=0;
        onum=0;
        int[] Vwin= new int[3];
        int[] hwin= new int[3];
        int[] Dwin= new int[2];

        xw=false;
        ow=false;

        int c=in.read();
        count(c);
        Vwin[0]=c;
        hwin[0]=c;
        Dwin[0]=c;

        c=in.read();
        count(c);
        Vwin[1]=c;
        if(hwin[0]!=c)hwin[0]=0;

        c=in.read();
        count(c);
        Vwin[2]=c;
        Dwin[1]=c;

        in.readLine();

        c=in.read();
        count(c);
        if(Vwin[0]!=c)Vwin[0]=0;
        hwin[1]=c;

        c=in.read();
        count(c);
        if(Vwin[1]!=c)Vwin[1]=0;
        if(hwin[1]!=c)hwin[1]=0;
        if(Dwin[0]!=c)Dwin[0]=0;
        if(Dwin[1]!=c)Dwin[1]=0;

        c=in.read();
        count(c);
        if(Vwin[2]!=c)Vwin[2]=0;
        if(hwin[1]!=c)hwin[1]=0;

        in.readLine();

        c=in.read();
        count(c);
        if(Vwin[0]!=c)Vwin[0]=0;
        hwin[0]=c;
        if(Dwin[1]!=c)Dwin[1]=0;

        c=in.read();
        count(c);
        if(Vwin[1]!=c)Vwin[1]=0;
        if(hwin[2]!=c)hwin[2]=0;


        c=in.read();
        count(c);
        if(Vwin[2]!=c)Vwin[2]=0;
        if(hwin[2]!=c)hwin[2]=0;
        if(Dwin[0]!=c)Dwin[0]=0;


        if((xnum-onum)>1 || (xnum-onum)<0)
            quit();
        for(int i:Vwin){
            if(i=='X')
                setX();
            else if((i=='0'))
                set0();
        }
        for(int i:hwin){
            if(i=='X')
                setX();
            else if((i=='0'))
                set0();
        }
        for(int i:Dwin){
            if(i=='X')
                setX();
            else if((i=='0'))
                set0();
        }

        if(xw){
            if(xnum!=onum)
                out.write("the first player won");
            else
                quit();
        }else if(ow){
            if(xnum==onum)
                out.write("the second player won");
            else
                quit();
        }else if(empty==0){
            out.write("draw");
        }else if(onum==xnum){
            out.write("first");
        }else{
            out.write("second");
        }
        out.close();
    }

    private static void set0() throws IOException {
        if(xw)quit();
        ow=true;
    }
    private static void quit() throws IOException {
        out.write("illegal");
        out.close();
        System.exit(0);
    }

    private static void setX() throws IOException {
        if(ow)quit();
        xw=true;

    }
    private static void count(int c) {
        if (c == '0') ++onum;
        else if (c == 'X') ++xnum;
        else if (c != '\n' && c != '\r') ++empty; // ignore newline characters
    }
}

