import java.util.Scanner;

public final class TicTacToe {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[3][];
        for (int i = 0; i < 3; i++) {
            board[i] = scanner.nextLine().toCharArray();
        }

        int numberOfXs = 0;
        int numberOf0s = 0;
        int numberOfDots = 0;
        int numberOfXWins = 0;
        int numberOf0Wins = 0;
        for (int i = 0; i < 3; i++) {
            char row = board[i][0];
            char col = board[0][i];
            boolean rowSame = true;
            boolean colSame = true;
            for (int j = 0; j < 3; j++) {
                if (board[i][j] == 'X') numberOfXs++;
                else if (board[i][j] == '0') numberOf0s++;
                else if (board[i][j] == '.') numberOfDots++;

                if (board[i][j] != row) rowSame = false;
                if (board[j][i] != col) colSame = false;
            }

            if (rowSame)
                if (row == 'X') numberOfXWins++;
                else if (row == '0') numberOf0Wins++;

            if (colSame)
                if (col == 'X') numberOfXWins++;
                else if (col == '0') numberOf0Wins++;
        }

        char forward = board[0][0];
        char backward = board[2][0];
        boolean fSame = true;
        boolean bSame = true;
        for (int i = 0; i < 3; i++) {
            if (forward != board[i][i]) fSame = false;
            if (backward != board[2 - i][i]) bSame = false;
        }

        if (fSame)
            if (forward == 'X') numberOfXWins++;
            else if (forward == '0') numberOf0Wins++;

        if (bSame)
            if (backward == 'X') numberOfXWins++;
            else if (backward == '0') numberOf0Wins++;

        if (numberOfXWins >= 1 && numberOf0Wins >= 1 ||
            numberOfXWins >= 1 && numberOfXs == numberOf0s ||
            numberOf0Wins >= 1 && numberOfXs == numberOf0s + 1 ||
            numberOfXs < numberOf0s || numberOfXs > numberOf0s + 1)
            System.out.println("illegal");
        else if (numberOfXWins >= 1)
            System.out.println("the first player won");
        else if (numberOf0Wins >= 1)
            System.out.println("the second player won");
        else if (numberOfDots == 0)
            System.out.println("draw");
        else if (numberOfXs == numberOf0s)
            System.out.println("first");
        else if (numberOfXs == numberOf0s + 1)
            System.out.println("second");
        else
            throw new IllegalStateException(numberOfXs + " " +
                                            numberOf0s + " " +
                                            numberOfDots + " " +
                                            numberOfXWins + " " +
                                            numberOf0Wins);
    }
}

