        OutputStream outputStream = System.out;
        InputReader inp = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Solver solver = new Solver();
        solver.solve(inp, out);
        out.close();
    }

    static class Solver {
        private void solve(InputReader inp, PrintWriter out) {
            boolean[][] a = new boolean[3][3];
            boolean[][] b = new boolean[3][3];
            int a2 = 0, b2 = 0;
            for (int i = 0; i < 3; i++) {
                String row = inp.next();
                for (int j = 0; j < 3; j++) {
                    if (row.charAt(j) == 'X') {
                        a[i][j] = true;
                        a2++;
                    } else if (row.charAt(j) == '0') {
                        b[i][j] = true;
                        b2++;
                    }
                }
            }
            boolean first = false, second = false;
            if (a[0][0]&&a[0][1]&&a[0][2]) first = true;
            if (a[1][0]&&a[1][1]&&a[1][2]) first = true;
            if (a[2][0]&&a[2][1]&&a[2][2]) first = true;
            if (a[0][0]&&a[1][0]&&a[2][0]) first = true;
            if (a[0][1]&&a[1][1]&&a[2][1]) first = true;
            if (a[0][2]&&a[1][2]&&a[2][2]) first = true;
            if (a[0][0]&&a[1][1]&&a[2][2]) first = true;
            if (a[0][2]&&a[1][1]&&a[2][0]) first = true;

            if (b[0][0]&&b[0][1]&&b[0][2]) second = true;
            if (b[1][0]&&b[1][1]&&b[1][2]) second = true;
            if (b[2][0]&&b[2][1]&&b[2][2]) second = true;
            if (b[0][0]&&b[1][0]&&b[2][0]) second = true;
            if (b[0][1]&&b[1][1]&&b[2][1]) second = true;
            if (b[0][2]&&b[1][2]&&b[2][2]) second = true;
            if (b[0][0]&&b[1][1]&&b[2][2]) second = true;
            if (b[0][2]&&b[1][1]&&b[2][0]) second = true;

            if (b2 > a2 || (a2 - 2 >= b2) || (first && second) || (0==1)) {
                out.print("illegal");
                return;
            }
            else if (first) out.print("the first player won");
            else if (second) out.print("the second player won");
            else if (a2 + b2 == 9) out.print("draw");
            else if (a2 == b2 + 1) out.print("second");
            else if (a2 == b2) out.print("first");
            else out.print("draw");
        }
    }

    static class InputReader {
        BufferedReader reader;
        StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

