import java.util.Scanner;

public class Main {
    private static char[][] brd = new char[3][3];
    private static int xcnt = 0, ocnt = 0;

    private static boolean win(char sym) {
        for (int i = 0; i < 3; i++) {
            if (brd[i][0] == sym && brd[i][1] == sym && brd[i][2] == sym) return true;
            if (brd[0][i] == sym && brd[1][i] == sym && brd[2][i] == sym) return true;
        }

        if (brd[1][1] != sym) return false;

        if (brd[0][0] == sym && brd[2][2] == sym) return true;
        if (brd[0][2] == sym && brd[2][0] == sym) return true;

        return false;
    }

    private static boolean legal() {
        xcnt = 0;
        ocnt = 0;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                xcnt += brd[i][j] == 'X' ? 1 : 0;
                ocnt += brd[i][j] == '0' ? 1 : 0;
            }
        }

        if (xcnt - ocnt > 1) return false;
        if (xcnt - ocnt < 0) return false;
        if (win('X') && xcnt == ocnt) return false;
        if (win('0') && xcnt - ocnt == 1) return false;

        return true;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        for (int i = 0; i < 3; i++) {
            brd[i] = in.next().toCharArray();
        }
        do {
            if (!legal()) {
                System.out.println("illegal");
                break;
            }
            if (win('X')) {
                System.out.println("the first player won");
                break;
            }
            if (win('0')) {
                System.out.println("the second player won");
                break;
            }
            if (xcnt + ocnt == 9) {
                System.out.println("draw");
                break;
            }
            if (xcnt == ocnt) {
                System.out.println("first");
                break;
            }
            if (xcnt - ocnt == 1) {
                System.out.println("second");
                break;
            }
        } while (true);
    }
}

