import java.util.*;
import java.io.*;
public class Solution {

	public static int s=0; 



	public static boolean check(int graph[][],int i,int j){
		int n=graph.length-2,m=graph[0].length-2;
		if(i < 1 || i > n || j < 1 || j > m ){
			return false;
		}
		return true;
	}


	public static final int [] x={1,-1,0,0};
	public static final int [] y={0,0,1,-1};

	public static boolean dfsFindCycle(int [][] graph,boolean [][] visited,int i,int j,int iprev,int jprev){
		if(visited[i][j]) return true;
		visited[i][j]=true;
		for(int p = 0; p <= 3 ; ++p){
			int inext=i+x[p];
			int jnext=j+y[p];
			if(inext == iprev && jnext == jprev) continue;
			if(check(graph,inext,jnext) && graph[i][j]==graph[inext][jnext]){
				if(dfsFindCycle(graph,visited,inext,jnext,i,j)){
					return true;
				}
			}
		}
		visited[i][j]=false;
		return false;
	}

	public static void solve(int graph [][],boolean [][] visited){

		boolean flag=false;
		for(int i=1;i<graph.length && !flag;i++){
			for(int j=1;j<graph[0].length && !flag;j++){
					flag=dfsFindCycle(graph,visited,i,j,-1,-1);
			}
		}
		if(flag) System.out.println("Yes");
		else System.out.println("No");

	}

  public static void main(String[] args) {
    Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
      int n = in.nextInt();
      int m = in.nextInt();

      in.nextLine();
      int grid [][]= new int[n+2][m+2];
      boolean visited [][]= new boolean[n+2][m+2];
      for(int i=0;i<n+2;i++){
      	for(int j=0;j<m+2;j++){
      		if(i==0){
      			grid[0][j]=1;

      		}else if (j==0){
      			grid[i][0]=1;

      		}else if(i==n+1){
      			grid[n+1][j]=1;

      		}else if(j==m+1){
      			grid[i][m+1]=1;
    			}
      	}
      }
      int emptyCell=0;
      for(int i=1;i<n+1;i++){
      	String row=in.nextLine();
      	for(int j=1;j<m+1;j++){
      		grid[i][j]=row.charAt(j-1)-'A';

      	}
      }

      solve(grid,visited);

    }
 }

