import java.util.*;

public class Graph {

	public static class LinkedList {
		Node head; 

		public class Node {

			int element;
			Node nextElement;

			public Node(int e) {
				this.element = e;
				this.nextElement = null;
			}
		}

		public void add(int newElement) {
			if (head == null) { 
				head = new Node(newElement); 
				return;
			} else {
				Node newNode = new Node(newElement); 
				Node last = head; 
				while (last.nextElement != null) { 
					last = last.nextElement;
				}
				last.nextElement = newNode; 
				return;
			}
		}
	}

	static LinkedList graph[];
	static int V, n, m;

	public Graph(int v) {
		V = v;
		graph = new LinkedList[v];
		for (int aux = 0; aux < V; aux++) {
			graph[aux] = new LinkedList();
		}
	}

	public void addGraph(int v, int element) {
		graph[v].add(element);
		graph[element].add(v);
	}

	public static boolean checkCycle() {
		boolean visited[] = new boolean[V];

		Arrays.fill(visited, false);

		for (int aux = 0; aux < V; aux++) {
			if (!visited[aux]) {
				if (DFSUtil(aux, -1, visited)) {
					return true;
				}
			}
		}
		return false;
	}

	public static boolean DFSUtil(int index, int previous, boolean visited[]) {
		visited[index] = true;
		LinkedList.Node last = graph[index].head;

		while (last != null) {
			int a = last.element;
			if (!visited[a]) {
				if (DFSUtil(a, index, visited)) {
					return true;
				}
			} else if (a != previous) {
				return true;
			}
			last = last.nextElement;
		}
		return false;
	}

	public static void main(String[] args) {

		Scanner in = new Scanner(System.in);

		n = in.nextInt();
		m = in.nextInt();

		Graph g = new Graph(n * m);

		int index = 0;

		for (int i = 0; i < n; i++) {
			String line = in.next();
			for (int j = 0; j < m; j++, index++) {
				if (j < m - 1 && line.charAt(j) == line.charAt(j + 1)) {
					g.addGraph(index, index + 1);
				}
				if (i > 0 && line.charAt(j) == line.charAt(j - m)) {
					g.addGraph(index, index - m);
				}
			}
		}

		boolean cycle = checkCycle();

		if (cycle) {
			System.out.println("Yes");
		} else {
			System.out.println("No");
		}

		in.close();
	}
}

