            graph.add(new ArrayList<>());
        }

        for(int i=0;i<rows;i++){
            for(int j=0;j<cols;j++){
                int pointNumber1=(i)*cols+j+1;
                if(i-1>=0 && matrix[i-1][j]==matrix[i][j]){
                    int pointNumber2=(i-1)*cols+j+1;
                    graph.get(pointNumber1).add(pointNumber2);
                    graph.get(pointNumber2).add(pointNumber1);
                }
                if(j-1 >= 0 && matrix[i][j-1]==matrix[i][j]) {
                    int pointNumber2 = i*cols + (j-1) + 1;
                    graph.get(pointNumber1).add(pointNumber2);
                    graph.get(pointNumber2).add(pointNumber1);
                }
            }
        }

        boolean[] visited=new boolean[rows*cols+1];

        for(int i=1;i<=rows*cols;i++){
            if(visited[i]==false){
                Pair ans=dfs(graph,i,visited);
                int edges=ans.getDegreeSum()/2;
                if(edges>ans.getVertices()-1){
                    System.out.println("Yes");
