public class _511B {

	int n, m;
	public void solve() throws FileNotFoundException {
		InputStream inputStream = System.in;

		InputHelper inputHelper = new InputHelper(inputStream);

		PrintStream out = System.out;

		n = inputHelper.readInteger();
		m = inputHelper.readInteger();

		String[] g = new String[n];
		for(int i = 0; i < n; i++)
		{
			g[i] = inputHelper.read();
		}

		boolean[][] vis = new boolean[n][m];

		for(int i = 0; i < n; i++)
		{
			for(int j = 0; j < m; j++)
			{
				if(!vis[i][j])
				{
					if(dfs(i, j, g, vis, -1, -1))
					{

						System.out.println("Yes");
						return;
					}
				}
			}
		}
		System.out.println("No");

	}

	private boolean dfs(int i, int j, String[] g, boolean[][] vis, int pi, int pj) {

		if(vis[i][j])
		{

			return true;
		}


		vis[i][j] = true;

		boolean res = false;

		if(i - 1 >= 0 && (pi != i - 1 || pj != j) && g[i - 1].charAt(j) == g[i].charAt(j))
		{
			res |= dfs(i - 1, j, g, vis, i, j);
		}
		if(j - 1 >= 0 && (pi != i || pj != j - 1) && g[i].charAt(j - 1) == g[i].charAt(j))
		{
			res |= dfs(i, j - 1, g, vis, i, j);
		}
		if(j + 1 < m && (pi != i || pj != j + 1) && g[i].charAt(j + 1) == g[i].charAt(j))
		{
			// Fixed: call dfs on the correct neighbor (j+1) instead of (j-1)
			res |= dfs(i, j + 1, g, vis, i, j);
		}
		if(i + 1 < n && (pi != i + 1 || pj != j) && g[i + 1].charAt(j) == g[i].charAt(j))
		{
			res |= dfs(i + 1, j, g, vis, i, j);
		}

		return res;
	}

	public static void main(String[] args) throws FileNotFoundException {
		(new _511B()).solve();
	}

	class InputHelper {
		StringTokenizer tokenizer = null;
		private BufferedReader bufferedReader;

		public InputHelper(InputStream inputStream) {
			InputStreamReader inputStreamReader = new InputStreamReader(
					inputStream);
			bufferedReader = new BufferedReader(inputStreamReader, 16384);
		}

		public String read() {
			while (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					String line = bufferedReader.readLine();
					if (line == null) {
						return null;
					}
					tokenizer = new StringTokenizer(line);
				} catch (IOException e) {
					e.printStackTrace();
				}
			}

			return tokenizer.nextToken();
		}

		public Integer readInteger() {
			return Integer.parseInt(read());
		}

		public Long readLong() {
			return Long.parseLong(read());
		}
	}
}

