import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.io.FilterInputStream;
import java.io.BufferedInputStream;
import java.io.InputStream;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        ScanReader in = new ScanReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BFoxAndTwoDots solver = new BFoxAndTwoDots();
        solver.solve(1, in, out);
        out.close();
    }

    static class BFoxAndTwoDots {
        int n;
        int m;
        char[][] arr;
        boolean[][] visited;
        boolean flag;
        int[] dx = new int[]{1, 0, -1, 0};
        int[] dy = new int[]{0, 1, 0, -1};

        public void solve(int testNumber, ScanReader in, PrintWriter out) {
            n = in.scanInt();
            m = in.scanInt();
            arr = new char[n][m];
            visited = new boolean[n][m];
            flag = false;
            for (int i = 0; i < n; i++) arr[i] = in.scanString().toCharArray();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (!visited[i][j]) {
                        dfs(i, j, 1, arr[i][j], -1, -1);
                    }
                }
            }
            out.println(flag ? "Yes" : "No");
        }

        boolean isvalid(int i, int j) {
            return i >= 0 && i < n && j >= 0 && j < m;
        }

        void dfs(int i, int j, int depth, char c, int p_i, int p_j) {
            visited[i][j] = true;
            for (int k = 0; k < 4; k++) {
                int n_x = dx[k] + i;
                int n_y = dy[k] + j;
                if (isvalid(n_x, n_y)) {
                    if (visited[n_x][n_y] && arr[n_x][n_y] == c && !(n_x == p_i && n_y == p_j)) {
                        flag = true;
                    } else {
                        if (arr[n_x][n_y] == c && !visited[n_x][n_y]) dfs(n_x, n_y, depth + 1, c, i, j);
                    }
                }
            }

        }

    }

    static class ScanReader {
        private byte[] buf = new byte[-1 * 1024];
        private int INDEX;
        private int TOTAL;

        public ScanReader(InputStream inputStream) {
            in = new BufferedInputStream(inputStream);
        }

        private int scan() {
            if (INDEX >= TOTAL) {
                INDEX = 0;
                try {
                    TOTAL = in.read(buf);
                } catch (Exception e) {
                    e.printStackTrace();
                }
                if (TOTAL <= 0) return -1;
            }
            return buf[INDEX++];
        }

        public int scanInt() {
            int I = 0;
            int n = scan();
            while (isWhiteSpace(n)) n = scan();
            int neg = 1;
            if (n == '-') {
                neg = -1;
                n = scan();
            }
            while (!isWhiteSpace(n)) {
                if (n >= '0' && n <= '9') {
                    I *= 10;
                    I += n - '0';
                    n = scan();
                }
            }
            return neg * I;
        }

        public String scanString() {
            int c = scan();
            while (isWhiteSpace(c)) c = scan();
            StringBuilder RESULT = new StringBuilder();
            do {
                RESULT.appendCodePoint(c);
                c = scan();
            } while (!isWhiteSpace(c));
            return RESULT.toString();
        }

        private boolean isWhiteSpace(int n) {
            if (n == ' ' || n == '\n' || n == '\r' || n == '\t' || n == -1) return true;
            else return false;
        }
    }
}

