		scanner.nextLine();

		for(int i=0; i<row; i++){
			String rowInfo = scanner.nextLine();
			for(int j=0; j<column; j++){
				board[i][j] = (int)(rowInfo.charAt(j));	
			}
		}
		int alpha = 0;
		int turn = 0;
		stack = new Stack();

		for(int i=0; i<row; i++){
			for(int j=0; j<column; j++){

				if(board[i][j] != 0){
					alpha = board[i][j];

					foo(i,j, alpha,i,j);	
				}

				for(int k=0; k<row; k++){
					for(int l=0; l<column; l++){
						if(board[k][l] == 1){
							board[k][l] = 0;
						}
					}
				}
			}
		}
