	static void dfs(int fromI, int fromJ, int i, int j, boolean[][] V, char[][] grid) {
		int n = grid.length, m = grid[0].length;

		if(inBounds(i-1, j, n, m) && grid[i-1][j] == grid[i][j]) {
			if(!V[i-1][j]) {
				V[i-1][j] = true;
				dfs(i, j, i-1, j, V, grid);
			} else if(i-1 == startI && j == startJ && i-1 != fromI && j != fromJ) {

				cycleFound = true;
				return;
			}
		}
		if(inBounds(i+1, j, n, m) && grid[i+1][j] == grid[i][j]) {
			if(!V[i+1][j]) {
				V[i+1][j] = true;
				dfs(i, j, i+1, j, V, grid);
			} else if(i+1 == startI && j == startJ && i+1 != fromI && j != fromJ) {

				cycleFound = true;
				return;
			}
		}
