import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BFoxAndTwoDots solver = new BFoxAndTwoDots();
        solver.solve(1, in, out);
        out.close();
    }

    static class BFoxAndTwoDots {
        static char[][] a;
        static int[][] visited;
        static boolean ans;
        int m;
        int n;

        void dfs(int i, int j, int pi, int pj) {
            visited[i][j] = 1;
            if (i - 1 >= 0) {
                if (visited[i - 1][j] == 1 && (i - 1 != pi) && a[i][j] == a[i - 1][j]) {
                    ans |= true;
                    return;
                } else if (visited[i - 1][j] == 0 && (i - 1 != pi) && a[i][j] == a[i - 1][j]) {
                    dfs(i - 1, j, i, j);
                }
            }
            if (i + 1 <= n - 1) {
                if (visited[i + 1][j] == 1 && (i + 1 != pi) && a[i][j] == a[i + 1][j]) {
                    ans |= true;
                    return;
                } else if (visited[i + 1][j] == 0 && (i + 1 != pi) && a[i][j] == a[i + 1][j]) {
                    dfs(i + 1, j, i, j);   // fixed: call dfs on the correct neighbour (down)
                }
            }
            if (j + 1 <= m - 1) {
                if (visited[i][j + 1] == 1 && (j + 1 != pj) && a[i][j] == a[i][j + 1]) {
                    ans |= true;
                    return;
                } else if (visited[i][j + 1] == 0 && (j + 1 != pj) && a[i][j] == a[i][j + 1]) {
                    dfs(i, j + 1, i, j);
                }
            }
            if (j - 1 >= 0) {
                if (visited[i][j - 1] == 1 && (j - 1 != pj) && a[i][j] == a[i][j - 1]) {
                    ans |= true;
                    return;
                } else if (visited[i][j - 1] == 0 && (j - 1 != pj) && a[i][j] == a[i][j - 1]) {
                    dfs(i, j - 1, i, j);
                }
            }
        }

        public void solve(int testNumber, Scanner sc, PrintWriter out) {
            n = sc.nextInt();
            m = sc.nextInt();
            a = new char[n][m];
            for (int i = 0; i < n; i++) {
                String s = sc.next();
                for (int j = 0; j < m; j++) {
                    a[i][j] = s.charAt(j);
                }
            }
            ans = false;
            visited = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (visited[i][j] == 0) {
                        dfs(i, j, -1, -1);
                    }
                }
            }
            if (ans == true) out.println("Yes");
            else out.println("No");
        }

    }
}

