public class B {

    static BufferedReader in;
    static PrintWriter out;
    static StringTokenizer tok;

    public static void main(String[] args) throws IOException {
        in = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(new OutputStreamWriter(System.out));
        tok = new StringTokenizer("");
        new B().solve();
        out.flush();
        out.close();
    }

    String nextTok() throws IOException {
        if (!tok.hasMoreTokens()) {
            tok = new StringTokenizer(in.readLine());
        }
        return tok.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(nextTok());
    }

    long nextLong() throws IOException {
        return Long.parseLong(nextTok());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(nextTok());
    }

    int arr[][];
    int arrcolor[][];
    int n;
    int m;
    int xs, ys;

    void dfs(int x,int y, int cnt) {
        arrcolor[x][y] = 1;

        if (x+1 < n && arr[x][y] == arr[x+1][y]) {
            if (arrcolor[x+1][y] != 1) {
                dfs(x + 1, y, cnt + 1);
            } else if (xs == x+1 && ys == y && cnt+1 >= 3) {
                System.out.println("Yes");
                System.exit(0);
            }
        }
        if (x-1 >= 0 && arr[x][y] == arr[x-1][y]) {
            if (arrcolor[x-1][y] != 1) {
                dfs(x - 1, y, cnt + 1);
            } else if (xs == x-1 && ys == y && cnt+1 >= 3) {
                System.out.println("Yes");
                System.exit(0);
            }
        }
        if (y-1 >= 0 && arr[x][y] == arr[x][y-1]) {
            if (arrcolor[x][y-1] != 1) {
                dfs(x, y-1, cnt + 1);
            } else if (xs == x && ys == y-1 && cnt+1 >= 3) {
                System.out.println("Yes");
                System.exit(0);
            }
        }
        if (y+1 < m && arr[x][y] == arr[x][y+1]) {
            if (arrcolor[x][y+1] != 1) {
                dfs(x, y+1, cnt + 1);
            } else if (xs == x && ys == y+1 && cnt+1 >= 3) {
                System.out.println("Yes");
                System.exit(0);
            }
        }
    }

    void solve() throws IOException {
        n = nextInt();
        m = nextInt();
        arr = new int[n][m];
        arrcolor = new int[n][m];
        for (int i = 0; i < n; i++) {
            String tmp = nextTok();
            for (int j = 0; j < m; j++) {
                arr[i][j] = (int)(tmp.charAt(j)-'A'+1);
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (arrcolor[i][j] != 1) {
                    xs = i;
                    ys = j;
                    dfs(i,j,0);
                    for (int k = 0; k < n; k++) {
                        for (int l = 0; l < m; l++) {
                            arrcolor[k][l] = 0;
                        }
                    }
                }
            }
        }

        System.out.println("No");
    }
}

