public class Main2 {

    public static int m, n;



    public static void main(String[] args) throws Exception {

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] in = br.readLine().split(" ");

        n = Integer.parseInt(in[0]);
        m = Integer.parseInt(in[1]);
        char[][] g = new char[n][m];

        for (int i = 0; i < n; i++)
            g[i] = br.readLine().toCharArray();

        boolean[][]visited = new boolean[n][m];
        for(int i = 0 ;i<n;i++)
            Arrays.fill(visited[i], false);

        int[]parentOf = new int[n*m+2];

        boolean f = false;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
            if(!visited[i][j]){
                Arrays.fill(parentOf, 0);
                for(int k=0;k<n;k++)
                    Arrays.fill(visited[k], false);
                f|=getAns(g,parentOf,visited,i ,i,j,j);
            }
            }
        }
        if (f) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }

    }

    private static boolean getAns(char[][] g, int[] parentOf, boolean[][] visited, int x, int y
        ,int sx,int sy) {
        visited[x][y] = true;
        if( y==sy && x==sx && parentOf[x*m+(y+1)]!=0){
            return true;
        }
        boolean ans = false;
        if(x-1>=0 && (x-1)*m+(y+1)!=parentOf[(x*m)+(y+1)]  && g[x-1][y]==g[sx][sy]){
            parentOf[(x-1)*m+(y+1)]=(x*m)+(y+1);
            if(visited[x-1][y])
                return true;
            ans|=getAns(g,parentOf,visited,x-1,y,sx,sy);
        }
        if(y-1>=0 && (x)*m+(y)!=parentOf[(x*m)+(y+1)]   && g[x][y-1]==g[sx][sy]){
            parentOf[(x)*m+(y)]=(x*m)+(y+1);
            if(visited[x][y-1])
                return true;
            ans|=getAns(g,parentOf,visited,x,y-1,sx,sy);
        }
        if(x+1<n && (x+1)*m+(y+1)!=parentOf[(x*m)+(y+1)]  && g[x+1][y]==g[sx][sy]){
            parentOf[(x+1)*m+(y+1)]=(x*m)+(y+1);
            if(visited[x+1][y])
                return true;
            ans|=getAns(g,parentOf,visited,x+1,y,sx,sy);
        }
        if(y+1<m && (x)*m+(y+1)!=parentOf[(x*m)+(y+1)]  &&  g[x][y+1]==g[sx][sy]){
            parentOf[(x)*m+(y+1)]=(x*m)+(y+1);
            if(visited[x][y+1])
                return true;
            ans|=getAns(g,parentOf,visited,x,y+1,sx,sy);
        }
        return ans;
    }

}

