			graph[i] = br.readLine().toCharArray();

		boolean[][] visited = new boolean[n][m];
		HashMap<String, String> bfsParent = new HashMap<>();

		boolean cycleFound = false;

		for(int i=0; i<n; i++) {
			for(int j=0; j<m; j++) {
