	int dir[][]={{0,1},{0,-1},{1,0},{-1,0}};
	int n,m;
	boolean inmap(int x,int y)
	{
		return x>=0&&x<n&&y>=0&&y<m;
	}
	boolean dfs(int x,int y,int nowx,int nowy,int step){

		vis[nowx][nowy]=true;
		for(int i=0;i<4;i++)
		{
			int xx=nowx+dir[i][0];
			int yy=nowy+dir[i][1];
			if(xx==x&&yy==y&&step>=3)
				return true;
		}
		for(int i=0;i<4;i++)
		{
			int xx=nowx+dir[i][0];
			int yy=nowy+dir[i][1];
			if(inmap(xx,yy)&&!vis[xx][yy]&&s[xx][yy]==s[x][y])
				if(dfs(x,y,xx,yy,step+1)==true)
					return true;
		}
		return false;
	}
	public void solve(int testNumber, InputReader in,  PrintWriter out){
		n = in.nextInt();
		m = in.nextInt();
		for(int i=0;i<n;i++){
			String str = in.next();
			s[i] = str.toCharArray();
		}
		boolean flag = false;
		for(int i=0; i<n; i++){
			for(int j=0;j<m;j++){
				for(int x=0;x<n;x++)
					for(int y=0;y<m;y++)
						vis[x][y]=false;

				if(dfs(i,j,i,j,0))
				{
					flag = true;
					break;
				}
			}
			if(flag == true)
				break;
		}
		if(flag==true)
			out.println("Yes");
		else
			out.println("No");
	}
