    public static boolean search(String[] dots, int i, int j, boolean[][] history, int i_old, int j_old) {
        if (!history[i][j]) {
            char c = dots[i].charAt(j);
            if (i < dots.length - 1 && dots[i + 1].charAt(j) == c && i + 1 != i_old) {
                if (history[i + 1][j]) return true;
                history[i][j] = true;
                if (search(dots, i + 1, j, history, i, j)) return true;
            }
            if (i > 0 && dots[i - 1].charAt(j) == c && i - 1 != i_old) {
                if (history[i - 1][j]) return true;
                history[i][j] = true;
                if (search(dots, i - 1, j, history, i, j)) return true;
            }
            if (j < dots[0].length() - 1 && dots[i].charAt(j + 1) == c && j + 1 != j_old) {
                if (history[i][j + 1]) return true;
                history[i][j] = true;
                if (search(dots, i, j + 1, history, i, j)) return true;
            }
            if (j > 0 && dots[i].charAt(j - 1) == c && j - 1 != j_old) {
                if (history[i][j - 1]) return true;
                history[i][j] = true;
                if (search(dots, i, j - 1, history, i, j)) return true;
            }
        }
        return false;
    }

    public static boolean search(String[] dots, int i, int j, boolean[][] history) {
        for (int i = 0; i < dots.length; ++i) {
            for (int j = 0; j < dots[0].length(); ++j) {
                char c = dots[i].charAt(j);
                if (i < dots.length - 1 && dots[i + 1].charAt(j) == c) {
                    history[i][j] = true;
                    if (search(dots, i + 1, j, history, i, j)) return true;
                }
                if (i > 0 && dots[i - 1].charAt(j) == c) {
                    history[i][j] = true;
                    if (search(dots, i - 1, j, history, i, j)) return true;
                }
                if (j < dots[0].length() - 1 && dots[i].charAt(j + 1) == c) {
                    history[i][j] = true;
                    if (search(dots, i, j + 1, history, i, j)) return true;
                }
                if (j > 0 && dots[i].charAt(j - 1) == c) {
                    history[i][j] = true;
                    if (search(dots, i, j - 1, history, i, j)) return true;
                }
            }
        }
        return false;
    }

