			if (r == sr && c == sc && !(r == pr && c == pc))
				return true;
			for (int k = 0; k < 4; k++) {
				int rr = r + dr[k], cc = c + dc[k];
				if (rr < 0 || rr >= N || cc < 0 || cc >= M)
