    }

    static class TaskC {

	    public void solve(int testNumber, InputReader in, PrintWriter out) throws IOException {
	    	int t=1;
	    	while(t-->0) { 
	    		n=in.nextInt();
	    		m=in.nextInt();
	    		char[][] g=new char[n][m];
	    		for(int i=0;i<n;i++) {
	    			String s=in.nextLine();
	    			for(int j=0;j<m;j++) {
	    				g[i][j]=s.charAt(j);
	    			}
	    			// missing newline read? The original reads line after each row; keep same
	    		}
	    		boolean ans=false;
	    		for(int i=0;i<n;i++) {
	    			for(int j=0;j<m;j++) {
	    				int[][] vis=new int[n][m];
	    				ans|=rec(i,j,g,i,j,vis,0);
	    			}
	    		}
	    		if(ans) {
	    			out.println("Yes");
	    		}
	    		else {
	    			out.println("No");
	    		}

	        }


	    }


    }
    static boolean rec(int x,int y,char[][] g,int start,int end ,int[][] vis,int count) {
    	boolean a1=true;
    	boolean a2=true;
    	boolean a3=true;
    	boolean a4=true;
    	if(x>=n || x<0 || y>=m || y<0) {
    		return false;
    	}
    	if(x==start && y==end && count>=4) {
    		return true;
    	}
    	if(g[x][y]!=g[start][end] || (x==start && y==end && count<4)) {
    		return false;
    	}
    	vis[x][y]=1;
    	count++;
    	a1&=rec(x+1,y,g,start,end,vis,count);
    	a2&=rec(x,y+1,g,start,end,vis,count);
    	a3&=rec(x-1,y,g,start,end,vis,count);
    	a4&=rec(x,y-1,g,start,end,vis,count);
    	return a1||a2||a3||a4;
    }




    static class InputReader
    {
        BufferedReader br;
        StringTokenizer st;

        public InputReader()
        {
            br = new BufferedReader(new
                     InputStreamReader(System.in));
        }

        String next()
        {
            while (st == null || !st.hasMoreElements())
            {
                try
                {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException  e)
                {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt()
        {
            return Integer.parseInt(next());
        }

        long nextLong()
        {
            return Long.parseLong(next());
        }

        double nextDouble()
        {
            return Double.parseDouble(next());
        }

        String nextLine()
        {
            String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }

    }
    static void sort(int[] a, int low, int high) 
    {
        int N = high - low;         
        if (N <= 1) 
            return; 
        int mid = low + N/2; 
        sort(a, low, mid); 
        sort(a, mid, high); 
        int[] temp = new int[N];
        int i = low, j = mid;
        for (int k = 0; k < N; k++) 
        {
            if (i == mid)  
                temp[k] = a[j++];
            else if (j == high) 
                temp[k] = a[i++];
            else if (a[j]<a[i]) 
                temp[k] = a[j++];
            else 
                temp[k] = a[i++];
        }    
        for (int k = 0; k < N; k++) 
            a[low + k] = temp[k];         
    }
    static void lsort(long[] a, int low, int high) 
    {
        int N = high - low;         
        if (N <= 1) 
            return; 
        int mid = low + N/2; 
        lsort(a, low, mid); 
        lsort(a, mid, high); 
        long[] temp = new long[N];
        int i = low, j = mid;
        for (int k = 0; k < N; k++) 
        {
            if (i == mid)  
                temp[k] = a[j++];
            else if (j == high) 
                temp[k] = a[i++];
            else if (a[j]<a[i]) 
                temp[k] = a[j++];
            else 
                temp[k] = a[i++];
        }    
        for (int k = 0; k < N; k++) 
            a[low + k] = temp[k];         
    }
    public static long fexp(long x, long y, long p) {
        long res = 1;      


        x = x % p;  

        while (y > 0) 
        { 

            if((y & 1)==1) 
                res = (res * x) % p; 


            y = y >> 1;  
            x = (x * x) % p;  
        } 
        return res; 

    }
    static int gcd(int a, int b) 
    { 
        if (b == 0) 
            return a; 
        return gcd(b, a % b);  

    }
    static long lgcd(long a, long b) 
    { 
        if (b == 0) 
            return a; 
        return lgcd(b, a % b);  

    }

}

