public class File {
    public static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException e) {
                    e.printStackTrace();
                }
            }

            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }


    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int M = sc.nextInt();
        int N = sc.nextInt();

        char[][] board = new char[M][N];
        for (int r = 0; r < M; r++) {
            String row = sc.next();

            for (int c = 0; c < N; c++) {
                board[r][c] = row.charAt(c);
            }
        }

        boolean hasCycle = false;

        for (int r = 0; r < M; r++) {
            for (int c = 0; c < N; c++) {
                char val = board[r][c];

                if (DFS(board, r, c, -1, -1, val)) {
                    hasCycle = true;
                    break;
                }
            }
        }

        if (hasCycle) {
            out.println("Yes");
        } else {
            out.println("No");
        }

        out.close();
    }

    static int[][] dirs = new int[][] {{-1, 0},{1, 0},{0, -1},{0, 1}};

    public static boolean DFS(char[][] board, int r, int c, int prevR, int prevC, char val) {
        if (r < 0 || r >= board.length || c < 0 || c >= board[0].length) {
            return false;
        }
        if (board[r][c] == Character.toLowerCase(val)) { 
            return true;
        }
        else if (board[r][c] != val) {
            return false;
        }

        char prev = board[r][c];
        board[r][c] = Character.toLowerCase(val);

        for (int[] dir : dirs) {
            int nextR = r + dir[0];
            int nextC = c + dir[1];

            if (nextR == prevR && nextC == prevC) {
                continue;
            }
            if (nextR >= 0 && nextR < board.length && nextC >= 0 && nextC < board[0].length) {
                if (DFS(board, nextR, nextC, r, c, val)) {
                    return true;
                }
            }
        }

        board[r][c] = prev;
        return false;
    }
}

