public class Twodots implements Runnable 
{
    static class InputReader 
    {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;
        private BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        public InputReader(InputStream stream) 
        {
            this.stream = stream;
        }

        public int read()
        {
            if (numChars==-1) 
                throw new InputMismatchException();

            if (curChar >= numChars) 
            {
                curChar = 0;
                try
                {
                    numChars = stream.read(buf);
                }
                catch (IOException e)
                {
                    throw new InputMismatchException();
                }

                if(numChars <= 0)               
                    return -1;
            }
            return buf[curChar++];
        }

        public String nextLine()
        {
            String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }
        public int nextInt() 
        {
            int c = read();

            while(isSpaceChar(c)) 
                c = read();

            int sgn = 1;

            if (c == '-') 
            {
                sgn = -1;
                c = read();
            }

            int res = 0;
            do
            {
                if(c<'0'||c>'9') 
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            while (!isSpaceChar(c)); 

            return res * sgn;
        }

        public long nextLong() 
        {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-')
            {
                sgn = -1;
                c = read();
            }
            long res = 0;

            do 
            {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            while (!isSpaceChar(c));
                return res * sgn;
        }

        public double nextDouble() 
        {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-')
            {
                sgn = -1;
                c = read();
            }
            double res = 0;
            while (!isSpaceChar(c) && c != '.') {
                if (c == 'e' || c == 'E')
                    return res * Math.pow(10, nextInt());
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            if (c == '.') 
            {
                c = read();
                double m = 1;
                while (!isSpaceChar(c))
                {
                    if (c == 'e' || c == 'E')
                        return res * Math.pow(10, nextInt());
                    if (c < '0' || c > '9')
                        throw new InputMismatchException();
                    m /= 10;
                    res += (c - '0') * m;
                    c = read();
                }
            }
            return res * sgn;
        }

        public String readString() 
        {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do 
            {
                res.appendCodePoint(c);
                c = read();
            } 
            while (!isSpaceChar(c));

            return res.toString();
        }

        public boolean isSpaceChar(int c) 
        {
            if (filter != null)
                return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public String next()
        {
            return readString();
        }

        public interface SpaceCharFilter
        {
            public boolean isSpaceChar(int ch);
        }

    }

	static int dx[]={1,-1,0,0},dy[]={0,0,1,-1},n,m;
	static char grid[][];
	static boolean visited[][];

	static boolean bound(int x, int y)
	{
		return x>=0 && x<n && y>=0 && y<m;
	}

	static boolean dfs()
	{
		for(int i=0;i<n;++i)
		{
			for(int j=0;j<m;++j)
			{
				if(!visited[i][j]) 
				{
					if(dfsUtil(i,j,-1,-1)) return true;
				}
			}
		}
		return false;
	}

	static boolean dfsUtil(int x, int y, int parx, int pary)
	{
		visited[x][y]=true;
		for(int i=0;i<4;++i)
		{
			int xx=x+dx[i],yy=y+dy[i];

			if(bound(xx,yy))
			{
				if(xx!=parx || yy!=pary)
				{
					if(grid[xx][yy]==grid[x][y])
					{
						if(visited[xx][yy]) return true;
						else if(dfsUtil(xx,yy,x,y)) return true;
					}
				}
			}
		}
		return false;
	}


    public static void main(String args[]) throws Exception 
    {
        new Thread(null, new Twodots(),"Twodots",1<<27).start();
    }

    public void run()
    {
        InputReader sc = new InputReader(System.in);
        PrintWriter w = new PrintWriter(System.out);

		n=sc.nextInt();
		m=sc.nextInt();
		visited=new boolean[n][m];
		grid=new char[n][m];
		for(int i=0;i<n;++i) grid[i]=sc.next().toCharArray();
		if(dfs()) w.println("Yes");
		else w.println("No");

        System.out.flush();
        w.close();
    }
}

