import java.util.Scanner;

public class Backagain {

	static boolean cycle = false;

	public static boolean[][] dfs(int i, int j, boolean[][] visited, char[][] grid, int pi, int pj) {
		if (cycle)
			return visited;

		if (visited[i][j]) {
			cycle = true;
			return visited;
		}
		visited[i][j] = true;
		if (i > 0 && i - 1 != pi && grid[i][j] == grid[i - 1][j])
			visited = dfs(i - 1, j, visited, grid, i, j);

		if (i < grid.length - 1 && i + 1 != pi && grid[i][j] == grid[i + 1][j])
			visited = dfs(i + 1, j, visited, grid, i, j);

		if (j > 0 && j - 1 != pj && grid[i][j] == grid[i][j - 1])
			visited = dfs(i, j - 1, visited, grid, i, j);

		if (j < grid[0].length - 1 && j + 1 != pj && grid[i][j] == grid[i][j + 1])
			visited = dfs(i, j + 1, visited, grid, i, j);
		return visited;
	}

	public static void main(String[] args) {
