import java.util.Scanner;

public class Backagain {

    static boolean cycle = false;

    public static boolean[][] dfs(int i, int j, boolean[][] visited, char[][] grid, int pi, int pj) {
        if (cycle) {
            return visited;
        }

        if (visited[i][j]) {
            cycle = true;
            return visited;
        }
        visited[i][j] = true;
        if (i > 0 && i - 1 != pi && grid[i][j] == grid[i - 1][j]) {
            visited = dfs(i - 1, j, visited, grid, i, j);
        }

        if (i < grid.length - 1 && i + 1 != pi && grid[i][j] == grid[i + 1][j]) {
            visited = dfs(i + 1, j, visited, grid, i, j);
        }

        if (j > 0 && j - 1 != pj && grid[i][j] == grid[i][j - 1]) {
            visited = dfs(i, j - 1, visited, grid, i, j);
        }

        if (j < grid[0].length - 1 && j + 1 != pj && grid[i][j] == grid[i][j + 1]) {
            visited = dfs(i, j + 1, visited, grid, i, j);
        }
        return visited;

    }

    public static void main(String[] args) {

        Scanner s = new Scanner(System.in);
        int n = s.nextInt();
        int m = s.nextInt();

        char[][] grid = new char[n][m];
        boolean[][] visited = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            String st = s.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = st.charAt(j);
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!visited[i][j] && !cycle) {
                    visited = dfs(i, j, visited, grid, -1, -1);
                }
            }
        }

        if (cycle) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }
}

