import java.util.ArrayList;
import java.util.Stack;

public class Main {

    private static final BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));
    private static final Scanner scanner = new Scanner(bufferedReader);
    private static final PrintWriter printWriter = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

    public static void main(String[] args) throws IOException {
        String[] inputConstraints = bufferedReader.readLine().split(" ");
        int n = Integer.parseInt(inputConstraints[0]);
        int m = Integer.parseInt(inputConstraints[1]);
        char[][] board = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = bufferedReader.readLine();
            for (int j = 0; j < m; j++) {
                board[i][j] = row.charAt(j);
            }
        }
        if (containsCycle(board, n, m)) {
            printWriter.println("Yes");
        } else {
            printWriter.println("No");
        }
        printWriter.flush();
        scanner.close();
    }

    private static boolean containsCycle(char[][] board, int n, int m) {
        Node[][] graph = graphify(board, n, m);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!graph[i][j].isVisited()) {
                    if (dft(graph, n, m, i, j)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private static boolean dft(Node[][] graph, int n, int m, int r, int c) {
        Node root = new Node(-1, -1, '.');
        Stack<Node> s = new Stack<Node>();
        Stack<Node> p = new Stack<Node>();
        s.push(graph[r][c]);
        p.push(root);
        root.setVisited();
        while (!s.isEmpty()) {
            Node curr = s.pop();
            Node par = p.pop();
            ArrayList<Node> list = curr.getList();

            curr.setVisited();

            for (int i = 0; i < list.size(); i++) {
                if (list.get(i) != par && list.get(i).isVisited()) {
                    return true;
                } else if (!list.get(i).isVisited()) {
                    s.push(list.get(i));
                    p.push(curr);
                }
            }
        }

        return false;
    }

    private static Node[][] graphify(char[][] board, int n, int m) {
        Node[][] graph = new Node[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                graph[i][j] = new Node(i, j, board[i][j]);
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                ArrayList<Node> list = new ArrayList<Node>();
                try {
                    if (graph[i - 1][j].getColor() == graph[i][j].getColor()) {
                        list.add(graph[i - 1][j]);
                    }
                } catch (Exception e) {

                }
                try {
                    if (graph[i + 1][j].getColor() == graph[i][j].getColor()) {
                        list.add(graph[i + 1][j]);
                    }
                } catch (Exception e) {

                }
                try {
                    if (graph[i][j - 1].getColor() == graph[i][j].getColor()) {
                        list.add(graph[i][j - 1]);
                    }
                } catch (Exception e) {

                }
                try {
                    if (graph[i][j + 1].getColor() == graph[i][j].getColor()) {
                        list.add(graph[i][j + 1]);
                    }
                } catch (Exception e) {

                }
                graph[i][j].setList(list);
            }
        }

        return graph;
    }
}

