import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Stack;

public class C {

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int[] temp = readIntegerArray(br);
		int n = temp[0];
		int m = temp[1];
		char[][] a = new char[n][m];
		for (int i = 0; i < n; i++)
			a[i] = readString(br).toCharArray();
		br.close();
		String ans = solve(n, m, a);
		System.out.println(ans);
	}

	private static String solve(int n, int m, char[][] a) {
		int[] adjacentX = {1, -1, 0, 0};
		int[] adjacentY = {0, 0, 1, -1};
		boolean[][] visited = new boolean[n][m];
		Stack<Integer> xStack = new Stack<Integer>();
		Stack<Integer> yStack = new Stack<Integer>();
		Stack<Integer> xParentStack = new Stack<Integer>();
		Stack<Integer> yParentStack = new Stack<Integer>();
		for (int row = 0; row < n; row++) {
			for (int column = 0; column < m; column++) {
				if (visited[row][column]) {
					continue;
				}
				xStack.push(column);
				yStack.push(row);
				xParentStack.push(-1);
				yParentStack.push(-1);
				while (!xStack.isEmpty()) {
					int x = xStack.pop();
					int y = yStack.pop();
					int xParent = xParentStack.pop();
					int yParent = yParentStack.pop();
					for (int i = 0; i < 4; i++) {
						int neighborX = x + adjacentX[i];
						int neighborY = y + adjacentY[i];
						if (neighborX == xParent && neighborY == yParent) {
							continue;
						}
						if (neighborX < 0 || neighborX >= m || neighborY < 0 || neighborY >= n) {
							continue;
						}
						if (a[y][x] == a[neighborY][neighborX]) {
							if (visited[neighborY][neighborX]) {
								return "Yes";
							}
							visited[neighborY][neighborX] = true;
							xStack.push(neighborX);
							yStack.push(neighborY);
							xParentStack.push(x);
							yParentStack.push(y);
						}
					}
				}
			}
		}
		return "No";
	}

	private static String readString(BufferedReader br) throws IOException {
		return br.readLine().trim();
	}

	private static int[] readIntegerArray(BufferedReader br) throws IOException {
		String[] numbersString = br.readLine().trim().split(" ");
		int[] numbers = new int[numbersString.length];
		for (int i = 0; i < numbers.length; i++) {
			numbers[i] = Integer.parseInt(numbersString[i]);
		}
		return numbers;
	}

}

