public class FoxAndTwoDots {
    private static boolean hasCycle(char[][] arr, int n, int m, int si, int sj, int i, int j, int len, boolean[][] vis) {

        if ((i == si && j == sj) && len >= 4)
            return true;

        vis[i][j] = true;
        if (j + 1 < m && arr[i][j + 1] == arr[si][sj] && !vis[i][j + 1]) {
            if (hasCycle(arr, n, m, si, sj, i, j + 1, len + 1, vis))
                return true;
        }
        if (i - 1 >= 0 && arr[i - 1][j] == arr[si][sj] && !vis[i - 1][j]) {
            if (hasCycle(arr, n, m, si, sj, i - 1, j, len + 1, vis))
                return true;
        }
        if (j - 1 >= 0 && arr[i][j - 1] == arr[si][sj] && !vis[i][j - 1]) {
            if (hasCycle(arr, n, m, si, sj, i, j - 1, len + 1, vis))
                return true;
        }

        if (i + 1 < n && arr[i + 1][j] == arr[si][sj] && !vis[i + 1][j]) {
            if (hasCycle(arr, n, m, si, sj, i + 1, j, len + 1, vis))
                return true;
        }

        return false;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
