public class B {
    public static void solution(BufferedReader reader, PrintWriter out)
            throws IOException {
        In in = new In(reader);
        n = in.nextInt();
        m = in.nextInt();
        board = new char[n][m];
        for (int i = 0; i < n; i++)
            board[i] = in.next().toCharArray();
        visited = new int[n][m];
        root = new boolean[n][m];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                if (!root[i][j]) {
                    if (dfs(i, j, -1, -1, 1, board[i][j])) {
                        out.println("Yes");
                        return;
                    }
                }
        out.println("No");
    }

    private static int n, m;
    private static char[][] board;
    private static boolean[][] root;
    private static int[][] visited;
    private static int[] dr = new int[] { 0, 1, 0, -1 };
    private static int[] dc = new int[] { 1, 0, -1, 0 };

    private static boolean dfs(int r, int c, int pr, int pc, int d, char ch) {
        if (board[r][c] != ch)
            return false;
        root[r][c] = true;
        if (visited[r][c] > 0) {
            if (d - visited[r][c] >= 4)
                return true;
            else
                return false;
        }
        visited[r][c] = d;
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i], nc = c + dc[i];
            if (nr == pr && nc == pc)
                continue;
            if (nr < 0 || nr >= n || nc < 0 || nc >= m)
                continue;
            if (dfs(nr, nc, r, c, d + 1, ch))
                return true;
        }
        visited[r][c] = 0;
        return false;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(
                System.in));
        PrintWriter out = new PrintWriter(new BufferedWriter(
                new OutputStreamWriter(System.out)));
        solution(reader, out);
        out.close();
    }

    protected static class In {
        private BufferedReader reader;
        private StringTokenizer tokenizer = new StringTokenizer("");

        public In(BufferedReader reader) {
            this.reader = reader;
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens())
                tokenizer = new StringTokenizer(reader.readLine());
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

