        private static int[] e = {1,-1,0,0};
        private static int[] f = {0,0,1,-1};

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] graph = new char[n][m];
            for(int i = 0;i < n; i++){
