                for(int j = 0; j < m;j++){
                    graph[i][j] = s.charAt(j);
                }
            }

            boolean[][] visited = new boolean[n][m];

            boolean res = false;

            search_loop:
            for(int i = 0; i < n; i++){
                for(int j = 0; j < m; j++){
                    if(visited[i][j]) continue;
                    if(isCycle(graph, i, j,visited, graph[i][j], i, j)){
                        res = true;
                        break search_loop;
                    }
                }
            }

            if(res)
                out.println("Yes");
            else
                out.println("No");

        }

