import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;


public class FoxAndTwoDots {

    int n, m;
    char[][] B;

    List<Integer>[] G;
    boolean[] discovered, processed;

    void solve() {
        n = in.nextInt();
        m = in.nextInt();
        B = new char[n][];
        for (int i = 0; i < n; i++) {
            B[i] = in.nextToken().toCharArray();
        }

        G = new List[n * m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                G[i * m + j] = new ArrayList<>(4);
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (i - 1 >= 0 && B[i][j] == B[i - 1][j]) {
                    int u = i * m + j, v = (i - 1) * m + j;
                    G[u].add(v);
                    G[v].add(u);
                }
                if (j - 1 >= 0 && B[i][j] == B[i][j - 1]) {
                    int u = i * m + j, v = i * m + j - 1;
                    G[u].add(v);
                    G[v].add(u);
                }
            }
        }

        boolean found = false;
        discovered = new boolean[n * m];
        processed = new boolean[n * m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int u = i * m + j;                     // fixed index calculation
                if (!discovered[u]) {
                    if (dfs(u, -1)) {
                        found = true;
                        break;
                    }
                }
            }
        }

        if (found) out.println("Yes");
        else out.println("No");
    }

    boolean dfs(int u, int p) {
        boolean ok = false;
        discovered[u] = true;
        for (int v : G[u]) {
            if (v != p) {
                if (discovered[v] && !processed[v]) return true;
                if (!discovered[v]) ok |= dfs(v, u);
            }
        }
        processed[u] = true;
        return ok;
    }

    public static void main(String[] args) {
        in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        out = new PrintWriter(System.out);
        new FoxAndTwoDots().solve();
        out.close();
    }

    static FastScanner in;
    static PrintWriter out;

    static class FastScanner {
        BufferedReader in;
        StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        public long nextLong() {
            return Long.parseLong(nextToken());
        }

        public double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }
}

