import java.io.PrintStream;
import java.util.Scanner;

public class B {

    static class ConnectedComponent {
        public int nodesCount = 0;
        public int edgesCount = 0;
    }

    static int[] di = {-1, 0, 1, 0};

    static int[] dj = {0, 1, 0, -1};

    static void traverse(String[] board, char color, int i, int j, boolean[][] visited, ConnectedComponent cc, int n, int m){
        if (visited[i][j]){
            return;
        }

        visited[i][j] = true;
        cc.nodesCount++;

        for (int k = 0; k < 4; k++){
            int I = i + di[k];
            int J = j + dj[k];

            if (I >= 0 && I < n && J >= 0 && J < m){
                if (board[I].charAt(J) == color){
                    cc.edgesCount++;
                }

                if (board[I].charAt(J) == color && !visited[I][J]){
                    traverse(board, color, I, J, visited, cc, n, m);
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintStream out = System.out;

        int n = in.nextInt();
        int m = in.nextInt();

        String[] board = new String[n];
        boolean[][] visited = new boolean[n][m];

        for (int i = 0; i < n; i++){
            board[i] = in.next();
        }

        for (int i = 0; i < n; i++){
            for (int j = 0; j < m; j++){
                if (visited[i][j]){
                    continue;
                }

                ConnectedComponent cc = new ConnectedComponent();
                traverse(board, board[i].charAt(j), i, j, visited, cc, n, m);

                if (cc.nodesCount - 1 != cc.edgesCount / 2){
                    out.println("Yes");
                    return;
                }
            }
        }

        out.println("No");
    }

}

import java.io.*;
import java.util.*;

public class Solution {

    public static void main(String[] args) throws IOException{
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        String[] temp=br.readLine().trim().split(" ");
        int rows=Integer.parseInt(temp[0]);
        int cols=Integer.parseInt(temp[1]);
        int[][] matrix=new int[rows][cols];
        for(int i=0;i<rows;i++){
            String str=br.readLine();
            for(int j=0;j<cols;j++){
                matrix[i][j]=str.charAt(j);
            }
        }
        DSU graph=new DSU(rows*cols);
        for(int i=0;i<rows;i++){
            for(int j=0;j<cols;j++){
                int pointNumber=(i)*cols+j+1;
                if(i-1>=0 && matrix[i-1][j]==matrix[i][j]){
                    int pointNumber2=(i-1)*cols+j+1;
                    int parent1=graph.getParent(pointNumber);
                    int parent2=graph.getParent(pointNumber2);
                    if(parent1==parent2){
                        System.out.println("Yes");
                        return;
                    }
                    else{
                        graph.makeUnion(pointNumber,pointNumber2);
                    }
                }
                if(j-1>=0 && matrix[i][j-1]==matrix[i][j]){
                    int pointNumber2=i*cols+(j-1)+1;
                    int parent1=graph.getParent(pointNumber);
                    int parent2=graph.getParent(pointNumber2);
                    if(parent1==parent2){
                        System.out.println("Yes");
                        return;
                    }
                    else{
                        graph.makeUnion(pointNumber,pointNumber2);
                    }
                }
            }
        }
        System.out.println("No");
    }

}

class DSU{
    private int[] parent;
    private int[] size;

    public DSU(int V){
        parent=new int[V+1];
        size=new int[V+1];
        for(int i=1;i<=V;i++){
            parent[i]=i;
            size[i]=1;
        }
    }

    public int getParent(int vertex){
        int temp=vertex;
        while(parent[vertex]!=vertex){
            vertex=parent[vertex];
        }
        parent[temp]=vertex;
        return vertex;
    }
    public void makeUnion(int u,int v){
        int parent1=this.getParent(u);
        int parent2=this.getParent(v);
        if(parent1==parent2){
            return;
        }
        int size1=size[parent1];
        int size2=size[parent2];
        if(size2<size1){
            parent[parent2]=parent1;
            size[parent1]+=size[parent2];
        }
        else{
