import java.io.*;
import java.util.*;

public class Solution {

    public static void main(String[] args) throws IOException{
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        String[] temp=br.readLine().trim().split(" ");
        int rows=Integer.parseInt(temp[0]);
        int cols=Integer.parseInt(temp[1]);
        int[][] matrix=new int[rows][cols];
        for(int i=0;i<rows;i++){
            String str=br.readLine();
            for(int j=0;j<cols;j++){
                matrix[i][j]=str.charAt(j);
            }
        }
        DSU graph=new DSU(rows*cols);
        for(int i=0;i<rows;i++){
            for(int j=0;j<cols;j++){
                int pointNumber=(i)*cols+j+1;
                if(i-1>=0 && matrix[i-1][j]==matrix[i][j]){
                    int pointNumber2=(i-1)*cols+j+1;
                    int parent1=graph.getParent(pointNumber);
                    int parent2=graph.getParent(pointNumber2);
                    if(parent1==parent2){
                        System.out.println("Yes");
                        return;
                    }
                    else{
                        graph.makeUnion(pointNumber,pointNumber2);
                    }
                }
                if(j-1>=0 && matrix[i][j-1]==matrix[i][j]){
                    int pointNumber2=i*cols+(j-1)+1;
                    int parent1=graph.getParent(pointNumber);
                    int parent2=graph.getParent(pointNumber2);
                    if(parent1==parent2){
                        System.out.println("Yes");
                        return;
                    }
                    else{
                        graph.makeUnion(pointNumber,pointNumber2);
                    }
                }
            }
        }
        System.out.println("No");
    }

}

class DSU{
    private int[] parent;
    private int[] size;

    public DSU(int V){
        parent=new int[V+1];
        size=new int[V+1];
        for(int i=1;i<=V;i++){
            parent[i]=i;
            size[i]=1;
        }
    }

    public int getParent(int vertex){
        int temp=vertex;
        while(parent[vertex]!=vertex){
            vertex=parent[vertex];
        }
        parent[temp]=vertex;
        return vertex;
    }

    public void makeUnion(int u,int v){
        int parent1=this.getParent(u);
        int parent2=this.getParent(v);
        if(parent1==parent2){
            return;
        }
        if(size[parent2] < size[parent1]){
            parent[parent2]=parent1;
            size[parent1]+=size[parent2];
        } else {
            parent[parent1]=parent2;
            size[parent2]+=size[parent1];
        }
    }
}

