public class FoxAndTwoDots {
    static boolean[][] vis;
    static int[][] arr;
    static int n, m;
    static int[] dr = { -1, 0, 1, 0 };
    static int[] dc = { 0, 1, 0, -1 };
    static boolean flag;

    static void dfs(int i, int j, int rp, int cp) {
        vis[i][j] = true;

        for (int c = 0; c < 4; c++) {
            int cr = i + dr[c];
            int cc = j + dc[c];

            if (cr < 0 || cr >= n || cc < 0 || cc >= m)
                continue;

            if (arr[cr][cc] != arr[i][j])
                continue;

            if ((cr != rp || cc != cp) && vis[cr][cc]) {
                flag = true;
                break;
            }

            if (!vis[cr][cc]) {
                vis[cr][cc] = true;
                dfs(cr, cc, i, j);
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        OutputStream out = new BufferedOutputStream(System.out);
