        InputReader sc = new InputReader(System.in);
        int s, c;
        String inpuz[] = sc.nextLine().split(" ");
        s = Integer.valueOf(inpuz[0]);
        c = Integer.valueOf(inpuz[1]);
        char[][] arr = new char[s][c];
        int[][] num = new int[s][c];
        int count = 0;
        for (int i = 0; i < s; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < c; j++) {
                arr[i][j] = line.charAt(j);
                num[i][j] = count++;
            }
        }
        LinkedList<pair> box = new LinkedList<>();
        pair cob = new pair(0, -10);
        box.add(cob);
        boolean[] visited = new boolean[s * c];
        Arrays.fill(visited, false);
        visited[0] = true;

        while (!(!(checkedAll(visited) && box.isEmpty()))) {
            if (box.isEmpty()) {
                for (int p = 0; p < s * c; p++) {
                    if (visited[p] == false) {
                        visited[p] = true;
                        cob = new pair(p, -10);
                        box.addFirst(cob);
                        break;
                    }
                }
            }
            pair temp = box.pollFirst();
            int prev = temp.f;
            int popped = temp.o;

            int m = popped / c;
            int n = popped % c;

            char d = arr[m][n];
            if (m > 0) {
                if (arr[m - 1][n] == d) {
                    if (prev != num[m - 1][n]) {
                        if (visited[num[m - 1][n]]) {
                            System.out.println("Yes");
                            System.exit(0);
