                        cob = new pair(num[m - 1][n], popped);
                        box.addFirst(cob);
                        visited[num[m - 1][n]] = true;
                    }
                }
            }
            if (m < s - 1) {
                if (arr[m + 1][n] == d) {
                    if (prev != num[m + 1][n]) {
                        if (visited[num[m + 1][n]]) {
                            System.out.println("Yes");
                            System.exit(0);
                        }
                        cob = new pair(num[m + 1][n], popped);
                        box.addFirst(cob);
                        visited[num[m + 1][n]] = true;
                    }
                }
            }
            if (n > 0) {
                if (arr[m][n - 1] == d) {
                    if (prev != num[m][n - 1]) {
                        if (visited[num[m][n - 1]]) {
                            System.out.println("Yes");
                            System.exit(0);
                        }
                        cob = new pair(num[m][n - 1], popped);
                        box.addFirst(cob);
                        visited[num[m][n - 1]] = true;
                    }
                }
            }
            if (n < c - 1) {
                if (arr[m][n + 1] == d) {
                    if (prev != num[m][n + 1]) {
                        if (visited[num[m][n + 1]]) {
                            System.out.println("Yes");
                            System.exit(0);
                        }
                        cob = new pair(num[m][n + 1], popped);
                        box.addFirst(cob);
                        visited[num[m][n + 1]] = true;
                    }
                }
            }
        }
        System.out.println("No");
    }

    static boolean checkedAll(boolean[] arr) {
        for (boolean i : arr) {
            if (i == false) {
                return false;
            }
        }
        return true;
    }
