public class D {
    ArrayDeque<Integer> q = new ArrayDeque<>();
    int[] dx = {0, 0, 1, -1};
    int[] dy = {1, -1, 0, 0};
    int n, m;
    char[][] grid;
    boolean dot(int i, int j) {
        if (i < 0 || j < 0 || i >= n || j >= m) {
            return false;
        }
        return grid[i][j] == '.';
    }

    void adjacent(int i, int j) {
        int sc = 4;
        int ni = 0, nj = 0;
        for (int a = 0; a < 4; a++) {
            if (dot(i + dx[a], j + dy[a])) {
                sc--;
                ni = i + dx[a];
                nj = j + dy[a];
            }
        }
        if (sc == 3) {
            q.add(i);
            q.add(j);
            q.add(ni);
            q.add(nj);
        }
    }

    boolean soln() {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') return false;
            }
        }
        return true;
    }

    D() {
        Scanner s = new Scanner(System.in);
        n = s.nextInt();
        m = s.nextInt();
