        for (int i = 0; i < n; i++) {
            grid[i] = s.next().toCharArray();
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m ; j++) {
                adjacent(i, j);
            }
        }
        while (!q.isEmpty()) {
            int i = q.remove();
            int j = q.remove();
            int ni = q.remove();
            int nj = q.remove();

            if (dot(i, j) && dot(ni, nj)) {
                if (ni == i) {
                    if (nj > j) {
                        grid[i][j] = '<';
                        grid[ni][nj] = '>';
                    }
                    else {
                        grid[ni][nj] = '<';
                        grid[i][j] = '>';
                    }
                }
                else { 
                    if (ni > i) {
                        grid[i][j] = '^';
                        grid[ni][nj] = 'v';
                    }
                    else {
                        grid[ni][nj] = '^';
                        grid[i][j] = 'v';
                    }
                }
                for (int a = 0; a < 4; a++) {
                    if (dot(i + dx[a], j + dy[a]))
                        adjacent(i + dx[a], j + dy[a]);
                    if (dot(ni + dx[a], nj + dy[a]))
                        adjacent(ni + dx[a], nj + dy[a]);
                }
            }
        }
        boolean u = soln();
        if (u)
            for (int i = 0; i < n; i++) {
                System.out.println(new String(grid[i]));
            }
        else System.out.println("Not unique");
    }

