            if(x >= 0 && x < r && y >= 0 && y < c && map[x][y] == '.')
                return true;
            else
                return false;
        }

        private void set(int x, int y, int xx, int yy){
            if(x+y > xx + yy){
                int t = x;
                x = xx;
                xx = t;
                t = y;
                y = yy;
                yy = t;
            }

            if(x == xx){
                map[x][y] = '<';
                map[xx][yy] = '>';
            }
            else{
                map[x][y] = '^';
                map[xx][yy] = 'v';
            }
        }

        private void update(int x, int y){
            degree[x][y] = 0;
            for(int k = 0; k < 4; k++){
                int nx = x + dx[k];
                int ny = y + dy[k];
                if(is_good(nx, ny)){
                    degree[nx][ny]--;
                    if(degree[nx][ny] == 1){
                        q.add(nx); q.add(ny);
                    }
                }
            }
        }

