                for(int i = 0; i < r; i++)
                    for(int j = 0; j < c; j++)
                        if(is_good(i, j))
                        for(int k = 0; k < 4; k++){
                            int nx = i + dx[k];
                            int ny = j + dy[k];
                            if(is_good(nx, ny))
                                degree[i][j]++;
                        }


