public class DrazilandTiles {
    static Deque<Integer> deque = new ArrayDeque<>();
    public static void main(String args[]) {
        Scanner cin = new Scanner(System.in);
        int n = cin.nextInt(), m = cin.nextInt();
        grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String input = cin.next();
            grid[i] = input.toCharArray();
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != '.') {
                    continue;
                }
                idegree(i, j);
            }
        }

        while (!deque.isEmpty()) {
            int y = deque.remove();
            int x = deque.remove();
            int y2 = deque.remove();
            int x2 = deque.remove();

            if (grid[y][x] != '.') {
                continue;
            }
            if (grid[y2][x2] != '.') {
                System.out.println("Not unique");
                return;
            }

            if (x2 > x) {
                grid[y][x] = '<';
                grid[y2][x2] = '>';
            } else if (x2 < x) {
                grid[y][x] = '>';
                grid[y2][x2] = '<';
            } else if (y2 < y) {
                grid[y][x] = 'v';
                grid[y2][x2] = '^';
            } else {
                grid[y][x] = '^';
                grid[y2][x2] = 'v';
            }

            int i = y2;
            int j = x2;
            for (int k = 0; k < 4; k++) {
                int dxi = i + xs[k];
                int dyi = j + ys[k];
                if (dxi >= 0 && dxi < grid.length && dyi >= 0 && dyi < grid[0].length) {
                    if (grid[dxi][dyi] != '.') {
                        continue;
                    }
                    idegree(dxi, dyi);
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    System.out.println("Not unique");
                    return;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            System.out.println(new String(grid[i]));
        }
    }

    static char[][] grid;
    static int[] xs = {-1, 1, 0, 0};
    static int[] ys = {0, 0, -1, 1};

    private static void idegree(int i, int j) {
        int degree = 0;
        int dx = 0;
        int dy = 0;
        for (int k = 0; k < 4; k++) {
            int dxi = i + xs[k];
            int dyi = j + ys[k];
            if (dxi >= 0 && dxi < grid.length && dyi >= 0 && dyi < grid[0].length) {
                if (grid[dxi][dyi] == '.') {
                    degree++;
                    if (degree == 1) {
                        dx = dxi;
                        dy = dyi;
                    }
                }
            }
        }
        if (degree == 1) {
            deque.add(i);
            deque.add(j);
            deque.add(dx);
            deque.add(dy);
        }
    }

    static class Node {
        public int y;
        public int x;

        public Node() {}

        public Node(int y, int x) {
            this.x = x;
            this.y = y;
        }
    }
}

