        while (!deque.isEmpty()) {
             node.y = deque.remove();
            node.x = deque.remove();
            neighbour.y = deque.remove();
            neighbour.x = deque.remove();
            if (grid[node.y][node.x] != '.') {
                continue;
            }
            if (grid[neighbour.y][neighbour.x] != '.') {
                continue;
            }

            if (neighbour.x > node.x) {
                grid[node.y][node.x] = '<';
                grid[neighbour.y][neighbour.x] = '>';
            } else if (neighbour.x < node.x) {
                grid[node.y][node.x] = '>';
                grid[neighbour.y][neighbour.x] = '<';
            } else if (neighbour.y < node.y) {
                    grid[node.y][node.x] = 'v';
                    grid[neighbour.y][neighbour.x] = '^';
                } else {
                    grid[node.y][node.x] = '^';
                    grid[neighbour.y][neighbour.x] = 'v';
                }

        int i = neighbour.y;
        int j = neighbour.x;
        for (int k = 0; k < 4; k++) {
            int dxi = i + xs[k];
            int dyi = j + ys[k];
            if (dxi >= -1 && dxi < grid.length) {
                if (dyi >= 0 && dyi < grid[0].length) {
                    if (grid[dxi][dyi] == '.') {
                   if (grid[dxi][dyi] != '.') {
                    continue;
                }
                        idegree(dxi,dyi);
                    }
                }
            }
        }

        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    System.out.println("Not unique");
                    return;
                }
            }
        }

        for (int i = 0; i < n; i++) {
                System.out.println(new String(grid[i]));

        }

    }

    static char[][] grid;
    static int[] xs = {-1, 1, 0, 0};
    static int[] ys = {0, 0, -1, 1};


    private static void idegree(int i, int j) {

        int degree = 0;
        int dx = 0;
        int dy = 0;
        for (int k = 0; k < 4; k++) {
            int dxi = i + xs[k];
            int dyi = j + ys[k];
            if (dxi >= 0 && dxi < grid.length && dyi >= 0 &&  dyi < grid[0].length) {
                    if (grid[dxi][dyi] == '.') {
                        degree++;
                        if (degree == 1) {
                            dx = dxi; 
                            dy = dyi;
                        }

                    }

                }
            }
                if (degree == 1){
                    deque.add(i);
                    deque.add(j);
                    deque.add(dx);
                    deque.add(dy);
                }

    }


    static class Node {
        public  int y;
        public  int x;
        public Node neighbour;

        public Node() {
        }

        public Node(int y, int x) {
            this.x = x;
            this.y = y;
        }
    }
}

