#include <bits/stdc++.h>
using namespace std;

int dx[4] = {0, 0, -1, 1};
int dy[4] = {-1, 1, 0, 0};
char s1[4] = {'>','<','v','^'};
char s2[4] = {'<','>','^','v'};
int n, m;
vector<string> grid;
vector<int> deg;
vector<bool> inQueue;
int cnt;

bool valid(int x, int y) {
    return x >= 0 && x < n && y >= 0 && y < m && grid[x][y] == '.';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> n >> m;
    grid.resize(n);
    for (int i = 0; i < n; i++) {
        cin >> grid[i];
    }

    deg.resize(n*m);
    inQueue.resize(n*m, false);
    cnt = 0;
    queue<int> q;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (grid[i][j] == '.') {
                cnt++;
                int idx = i * m + j;
                deg[idx] = 0;
                for (int k = 0; k < 4; k++) {
                    int ni = i + dx[k];
                    int nj = j + dy[k];
                    if (valid(ni, nj)) {
                        deg[idx]++;
                    }
                }
                if (deg[idx] == 1) {
                    inQueue[idx] = true;
                    q.push(idx);
                }
            }
        }
    }

    while (!q.empty()) {
        int idx = q.front();
        q.pop();
        --cnt;
        int x = idx / m, y = idx % m;
        bool match = (grid[x][y] != '.');
        for (int k = 0; k < 4; k++) {
            int nx = x + dx[k];
            int ny = y + dy[k];
            if (!valid(nx, ny)) continue;
            int nidx = nx * m + ny;
            if (--deg[nidx] == 1) {
                if (!inQueue[nidx]) {
                    inQueue[nidx] = true;
                    q.push(nidx);
                }
            }
            if (!match) {
                match = true;
                grid[x][y] = s1[k];
                grid[nx][ny] = s2[k];
                if (!inQueue[nidx]) {
                    inQueue[nidx] = true;
                    q.push(nidx);
                }
            }
        }
        if (!match) {
            ++cnt;
        }
    }

    if (cnt != 0) {
        cout << "Not unique\n";
    } else {
        for (int i = 0; i < n; i++) {
            cout << grid[i] << '\n';
        }
    }

    return 0;
}

