        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        private static final int[] dx = new int[]{0 , -1, 0, 1};
        private static final int[] dy = new int[]{-1, 1, 0, 0};
        private static final char[] s1 = {'>', '<', 'v', '^'};
        private static final char[] s2 = {'<', '>', '^', 'v'};
        private int n;
        private int m;
        private char[][] grid;
        private boolean[] inQueue;
        private Queue<Integer> queue;

        public void solve(int testNumber, Scanner in, PrintWriter out) {
            n = in.nextInt();
            m = in.nextInt();

            int[] deg = new int[n * m];
            grid = new char[n][m];

            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            queue = new LinkedList<>();
            inQueue = new boolean[n * m];

            int cnt = 0; 
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.') {
                        cnt++;

                        for (int k = 0; k < 4; k++) {
                            int x = i + dx[k];
                            int y = j + dy[k];
                            if (valid(x, y)) {
                                deg[i * m + j]++;
                            }
                        }
                        if (deg[i * m + j] == 1) { 
                            addToQueue(i, j);
                        }
                    }
                }
            }

            while (!queue.isEmpty()) {
                int current = queue.remove();
                int x = current / m;
                int y = current % m;
                if (grid[x][y] != '.') {
                    continue;
                }
                cnt--;
                boolean match = false;
                for (int k = 0; k < 4; k++) {
                    int i = x + dx[k];
                    int j = y + dy[k];

                    if (valid(i, j)) {
                        deg[i * m + j]--;
                        if (deg[i * m + j] == 1) {
                            addToQueue(i, j);
                        }
                        if (!match) {
                            match = true;
                            grid[x][y] = s1[k];
                            grid[i][j] = s2[k];
                            if (!inQueue[i * m + j]) {
                                addToQueue(i, j);
                            }
                        }
                    }

                }
                if (!match) {
                    cnt++;
                }
            }

            if (cnt != 0) {
                out.println("Not unique");
            } else {
                for (char[] x : grid) {
                    out.println(x);
                }
            }

        }

        private void addToQueue(int i, int j) {
            inQueue[i * m + j] = true;
            queue.add(i * m + j);
        }

        private boolean valid(int x, int y) {
            return x >= 0 && y >= 0 && x < n && y < m && grid[x][y] == '.';
        }

    }
}

