   public static void main(String[] args) throws IOException{
      BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
      PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));
      String[] s=br.readLine().split(" ");
      i=Integer.parseInt(s[0]);
      j=Integer.parseInt(s[1]);
      ar=new char[i][j];
      for(int x=0;x<i;x++)
         ar[x]=br.readLine().toCharArray();

      find(ar,i,j);
      boolean bool=true;
      for(int x=0;x<i;x++)
         for(int y=0;y<j;y++)
            if(ar[x][y]=='.') bool=false;

      if(bool)
         for(int x=0;x<i;x++){
            for(int y=0;y<j;y++)
               out.print(ar[x][y]);
            out.println();
         }

      else out.println("Not unique");
      out.close();
   }

   public static void find(char[][] ar,int i,int j){
      for(int x=0;x<i;x++)
         for(int y=0;y<j;y++)
            if(count(x,y).size()==1) index(x,y);
   }

   public static void index(int xi,int yi){
      LinkedList<Pair> q = new LinkedList<Pair>();
      if(ar[xi][yi]=='.') q.add(new Pair(xi,yi));
      while(q.size()>0) {
         Pair cur = q.poll();
         int x=cur.a; int y=cur.b;
         ArrayList<Pair> adjacent=count(x,y);
         if(adjacent.size()==1){
            Pair r=adjacent.get(0);
            parenthesis(x,y,r.a,r.b);
            for(Pair p:count(r.a, r.b))
               q.add(p);
         }
      }
   }

   public static void parenthesis(int x ,int z,int y,int w){
      if((x-y)==0){
         ar[x][Math.max(z,w)]='>'; 
         ar[x][Math.min(z,w)]='<'; 
      }

      else{
         ar[Math.max(x,y)][z]='v'; 
         ar[Math.min(x,y)][z]='^'; 
      }
   }

   public static ArrayList<Pair> count(int x,int y){
      ArrayList<Pair> ret=new ArrayList<Pair>();

      if(x>0)
         if(ar[x-1][y]=='.') ret.add(new Pair(x-1,y));
      if(y>0)
         if(ar[x][y-1]=='.') ret.add(new Pair(x,y-1));
      if(x<i-1)
         if(ar[x+1][y]=='.') ret.add(new Pair(x+1,y));
      if(y<j-1)
         if(ar[x][y+1]=='.') ret.add(new Pair(x,y+1));

      return ret;
   }

}

class Pair implements Comparable<Pair> {
   Integer a;
   Integer b;

   public Pair(int ma, int mb) {
      a = ma;
      b = mb;
   }

   public int compareTo(Pair o) {
      if(a == o.a) 
         return a.compareTo(o.b);
      return a < o.a ? -1 : 1;
   }
}

