class Vertex {
    Vertex(int x, int y) {
        X = x;
        Y = y;
    }

    int X, Y;
}

class Task {
    int n, m;
    char[][] a;
    int[] dx = new int[]{0, 0, 1, -1};
    int[] dy = new int[]{1, -1, 0, 0};
    char[] begin = new char[]{'<', '>', '^', 'v'};
    char[] end = new char[]{'>', '<', 'v', '^'};

    boolean is(int x, int y) {
        return 0 <= x && x < n && 0 <= y && y < m;
    }

    int power(int i, int j) {
        if (a[i][j] != '.')
            return 0;
        int power = 0;
        for (int k = 0; k < 4; k++) {
            int tx = i + dx[k];
            int ty = j + dy[k];
            if (is(tx, ty) && a[tx][ty] == '.') {
                power++;
            }
        }
        return power;
    }

    void fail() {
        out.println("Not unique");
    }

    public void solve() {
        n = in.nextInt();
        m = in.nextInt();
        a = new char[n][m];
        Queue<Vertex> queue = new ArrayDeque<>(n * m);
        for (int i = 0; i < n; i++) {
            String s = in.next();
            for (int j = 0; j < m; j++) {
                a[i][j] = s.charAt(j);
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (power(i, j) == 1)
                    queue.add(new Vertex(i, j));
            }
        }
        while (!queue.isEmpty()) {
            Vertex v = queue.remove();
            if (a[v.X][v.Y] != '.')
                continue;
            int pow = 0;
            int dir = 0;
            for (int k = 0; k < 4; k++) {
                int tx = v.X + dx[k];
                int ty = v.Y + dy[k];
                if (is(tx, ty) && a[tx][ty] == '.') {
                    pow++;
                    dir = k;
                }
            }
            if (pow != 1) {
                fail();
                return;
            }
            a[v.X][v.Y] = begin[dir];
            int x = v.X + dx[dir];
            int y = v.Y + dy[dir];
            a[x][y] = end[dir];
            for (int k = 0; k < 4; k++) {
                int tx = x + dx[k];
                int ty = y + dy[k];
                if (is(tx, ty) && power(tx, ty) == 1) {
                    queue.add(new Vertex(tx, ty));
                }
            }
        }
        for (int i = 0; i < n; i++){
            for (int j = 0; j < m; j++){
                if (a[i][j] == '.'){
                    fail();
                    return;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out.print(a[i][j]);
            }
            out.println();
        }
    }

    private InputReader in;
    private PrintWriter out;

    Task(InputReader in, PrintWriter out) {
        this.in = in;
        this.out = out;
    }
}

