class InputReader {
    public BufferedReader reader;
    public StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
        tokenizer = null;
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    public double nextDouble(){
        return Double.parseDouble(next());
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong(){
        return Long.parseLong(next());
    }

    public byte nextByte(){
        return Byte.parseByte(next());
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Queue;
import java.util.StringTokenizer;
import java.util.function.BiFunction;

public class CF292B {
    public static void main(String[] args) throws Exception {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer strtok;
        strtok = new StringTokenizer(in.readLine());
        int n = Integer.parseInt(strtok.nextToken());
        int m = Integer.parseInt(strtok.nextToken());
        char[][] map = new char[n][];
        for (int i = 0; i < n; i++)
            map[i] = in.readLine().toCharArray();
        int[] di = { 0, 0, 1, -1 };
        int[] dj = { 1, -1, 0, 0 };
        Queue<int[]> q = new ArrayDeque<int[]>();
        int left = 0;
        ArrayList<Integer> list = new ArrayList<Integer>();
        BiFunction<Integer, Integer, ArrayList<int[]>> neighbours = (i, j) -> {
            ArrayList<int[]> res = new ArrayList<>();
            for (int d = 0; d < 4; d++) {
                int ni = i + di[d];
                int nj = j + dj[d];
                if (ni >= 0 && nj >= 0 && ni < n && nj < m
                        && map[ni][nj] == '.') {
                    res.add(new int[] { ni, nj });
                }
            }
            return res;
        };

        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++) {
                if (map[i][j] == '.') {
                    left++;
                    if (neighbours.apply(i, j).size() == 1)
                        q.add(new int[] { i, j });
                }
            }
        while (!q.isEmpty()) {
            int[] node = q.poll();
            int i = node[0];
            int j = node[1];
            ArrayList<int[]> nei = neighbours.apply(i, j);
            if (nei.size() != 1) {
                continue;
            } else {
                nei.stream().forEach(x -> {
                    int ii = x[0];
                    int jj = x[1];
                    if (ii != i) {
                        map[Math.min(ii, i)][j] = '^';
                        map[Math.max(ii, i)][j] = 'v';
                    } else {
                        map[i][Math.min(jj, j)] = '<';
                        map[i][Math.max(jj, j)] = '>';
                    }
                    ArrayList<int[]> neinei = neighbours.apply(ii, jj);
                    neinei.forEach(nn -> {
                        if (neighbours.apply(nn[0], nn[1]).size() == 1) {
                            q.add(nn);
                        }
                    });
                });
            }
        }
        for (char[] a : map)
            for (char c : a)
                if (c == '.') {
                    System.out.println("Not unique");
                    return;
                }
        for (char[] a : map)
            System.out.println(new String(a));
    }
}

