public class Div2_292_D{
	public static void main(String[] args) throws IOException{
		BufferedInputStream bis = new BufferedInputStream(System.in);
		BufferedReader br = new BufferedReader(new InputStreamReader(bis));
		StringTokenizer st = new StringTokenizer(br.readLine());
		int n = Integer.parseInt(st.nextToken());
		int m = Integer.parseInt(st.nextToken());

		int [] dx = {0, 0, -1, 1};
		int [] dy = {-1, 1, 0, 0};
		char [] repX = {'>', '<', 'v', '^'};
		char [] repY = {'<', '>', '^', 'v'};
		int nebX, nebY;
		LinkedList<Point> queue = new LinkedList<Point>();
		int[][]degree = new int[n][m];
		char [][] grid = new char[n][m];
		for (int i = 0; i < grid.length; i++) 
			grid[i] = br.readLine().toCharArray();

		for(int i = 0;i < grid.length;i++)
			for(int j = 0;j < grid[i].length;j++) {
				for(int k = 0;k < dx.length && grid[i][j] != '*';k++) {
					nebX = i+dx[k];
					nebY = j+dy[k];
					if(inGrid(nebX, nebY, n, m) && grid[nebX][nebY] != '*') {
						degree[i][j]++;
					}
				}
				if(degree[i][j] == 1) {
					queue.add(new Point(i, j));
				}
			}
		while(!queue.isEmpty()) {
			Point curr = queue.removeFirst();
			if(degree[curr.x][curr.y] != 1)continue;
			boolean nebFound = false;
			for(int k = 0;k < dx.length && !nebFound;k++) {
				nebX = curr.x+dx[k];
				nebY = curr.y+dy[k];
				if(inGrid(nebX, nebY, n, m) && grid[nebX][nebY] == '.') {
					degree[nebX][nebY] = -1;
					grid[curr.x][curr.y] = repX[k];
					grid[nebX][nebY] = repY[k];
					nebFound = true;
					decNeb(nebX, nebY, dx, dy, degree, grid, queue);
				}
			}
			if(nebFound)
				decNeb(curr.x, curr.y, dx, dy, degree, grid, queue);
		}
		boolean hasSolution = true;
		for(int i = 0;i < n && hasSolution;i++)
			for(int j = 0;j < m && hasSolution;j++)
				if(grid[i][j]=='.')
					hasSolution = false;
		if(!hasSolution)
			System.out.println("Not unique");
		else {
			for(int i = 0;i < n;i++)
				System.out.println(grid[i]);
		}

	}
	private static boolean inGrid(int x, int y, int n, int m) {
		return x >= 0 && x < n && y >= 0 && y < m;
	}
	private static void decNeb(int i, int j, int[] dx, int[] dy, int[][] degree, char[][] g, LinkedList<Point> q) {
		for(int k = 0;k < dx.length;k++) {
			int nebX = i+dx[k];
			int nebY = j+dy[k];
			if(inGrid(nebX, nebY, degree.length, degree[0].length) && g[nebX][nebY]=='.') {
				degree[nebX][nebY]--;
				if(degree[nebX][nebY] == 1)
					q.add(new Point(nebX, nebY));
			}
		}
	}
}

