import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.LinkedList;

public class B {
	static InputStreamReader isr = new InputStreamReader(System.in);
	static BufferedReader br = new BufferedReader(isr);

	static int[] readIntArray() throws IOException {
		String[] v = br.readLine().split(" ");
		int[] ans = new int[v.length];

		for (int i = 0; i < ans.length; i++) {
			ans[i] = Integer.valueOf(v[i]);
		}

		return ans;
	}

	static int n;
	static int m;
	static int[][] g;

	public static void main(String[] args) throws IOException {
		int[] d = readIntArray();
		n = d[0];
		m = d[1];

		g = new int[n][m];
		int emptyCnt = 0;
		for (int i = 0; i < n; i++) {
			String r = br.readLine();
			for (int j = 0; j < r.length(); j++) {
				if (r.charAt(j) == '*') {
					g[i][j] = 1;
				} else {
					emptyCnt++;
				}
			}
		}

		if (emptyCnt % 2 == 1) {
			System.out.println("Not unique");
			return;
		}

		if (emptyCnt == 0) {
			out(g);
			return;
		}

		LinkedList<Integer> q = new LinkedList<Integer>();
		boolean[] added = new boolean[n * m + 1];
		boolean[] solved = new boolean[n * m + 1];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (g[i][j] == 0) {
					if (cnt(i(i, j)) == 1) {
						q.addLast(i(i, j));
						added[i(i, j)] = true;
					}
				}
			}
		}

		while (!q.isEmpty()) {
			int v1 = q.removeFirst();
			if (solved[v1]) {
				continue;
			}

			int v2 = first(v1);
			if (v2 == -1) {
				System.out.println("Not unique");
				return;
			}

			solved[v1] = true;
			solved[v2] = true;
			int r1 = r(v1);
			int r2 = r(v2);
			int c1 = c(v1);
			int c2 = c(v2);

			if (r1 == r2) {
				if (c1 < c2) {
					g[r1][c1] = 2;
					g[r2][c2] = 3;
				} else {
					g[r1][c1] = 3;
					g[r2][c2] = 2;
				}
			} else {
				if (r1 < r2) {
					g[r1][c1] = 4;
					g[r2][c2] = 5;
				} else {
					g[r1][c1] = 5;
					g[r2][c2] = 4;
				}
			}

			checkNeighbours(v1, q, added);
			checkNeighbours(v2, q, added);
			emptyCnt -= 2;
		}

		if (emptyCnt > 0) {
			System.out.println("Not unique");
			return;
		}

		out(g);
	}

	static void checkNeighbours(int v, LinkedList<Integer> q, boolean[] added) {
		int r = r(v);
		int c = c(v);

		if (inAndEmpty(g, r - 1, c) && cnt(i(r - 1, c)) == 1
				&& !added[i(r - 1, c)]) {
			q.add(i(r - 1, c));
		}
		if (inAndEmpty(g, r + 1, c) && cnt(i(r + 1, c)) == 1
				&& !added[i(r + 1, c)]) {
			q.add(i(r + 1, c));
		}
		if (inAndEmpty(g, r, c - 1) && cnt(i(r, c - 1)) == 1
				&& !added[i(r, c - 1)]) {
			q.add(i(r, c - 1));
		}
		if (inAndEmpty(g, r, c + 1) && cnt(i(r, c + 1)) == 1
				&& !added[i(r, c + 1)]) {
			q.add(i(r, c + 1));
		}
	}

	static int first(int v) {
		int r = r(v);
		int c = c(v);

		if (inAndEmpty(g, r - 1, c)) {
			return i(r - 1, c);
		}
		if (inAndEmpty(g, r + 1, c)) {
			return i(r + 1, c);
		}
		if (inAndEmpty(g, r, c - 1)) {
			return i(r, c - 1);
		}
		if (inAndEmpty(g, r, c + 1)) {
			return i(r, c + 1);
		}

		return -1;
	}

	static int cnt(int v) {
		int r = r(v);
		int c = c(v);
		int res = 0;
		if (inAndEmpty(g, r - 1, c)) {
			res++;
		}
		if (inAndEmpty(g, r + 1, c)) {
			res++;
		}
		if (inAndEmpty(g, r, c - 1)) {
			res++;
		}
		if (inAndEmpty(g, r, c + 1)) {
			res++;
		}

		return res;
	}

	static int i(int r, int c) {
		return r * m + c;
	}

	static int r(int ind) {
		return ind / m;
	}

	static int c(int ind) {
		return ind % m;
	}

	static boolean inAndEmpty(int[][] g, int r, int c) {
		if (r < 0 || c < 0 || r >= g.length || c >= g[0].length) {
			return false;
		}

		return (g[r][c] == 0);
	}

	static void out(int[][] g) {
		for (int i = 0; i < g.length; i++) {
			StringBuilder sb = new StringBuilder();
			for (int j = 0; j < g[0].length; j++) {
				switch (g[i][j]) {
				case 1:
					sb.append('*');
					break;
				case 2:
					sb.append('<');
					break;
				case 3:
					sb.append('>');
					break;
				case 4:
					sb.append('^');
					break;
				case 5:
					sb.append('v');
					break;
				}
			}

			System.out.println(sb.toString());
		}
	}
}

