    int[][]f;
    int n,m;
    void solve(){
        Scanner sc=new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        sc.nextLine();
        f = new int[n][m];
        already = new boolean[n][m];
        for (int i = 0; i < f.length; i++) {
            char[] s =sc.nextLine().toCharArray();
            for (int j = 0; j < s.length; j++) {
                f[i][j] = s[j];
            }
        }
        Queue<int[]>q = new LinkedList<>();
        for (int i = 0; i < f.length; i++) {
            for (int j = 0; j < m; j++) {
                if(f[i][j] !='.')continue;
                if(ji(i, j)==1){
                    q.add(new int[]{i,j});
                }
            }
        }

        while(!q.isEmpty()){
            int y = q.peek()[0];
            int x = q.poll()[1];
            if(f[y][x]!='.')continue;
            for (int i = 0; i < v1.length; i++) {
                int yy = y + v1[i];
                int xx = x + v2[i];
                if(yy <0 || yy >= n || xx < 0 || xx >= m)continue;
                if(f[yy][xx] == '.'){
                    put(y,x,yy,xx);
                    for (int j = 0; j < v1.length; j++) {
                        int yyy = yy + v1[j];
                        int xxx = xx + v2[j];
                        if(yyy <0 || yyy >= n || xxx < 0 || xxx >= m)continue;
                        if(ji(yyy,xxx)==1){
                            q.add(new int[]{yyy,xxx});
                        }
                    }
                    break;
                }
            }

        }

