class TaskB {
    public void solve(int testNumber, InputReader in, OutputWriter out) {
        int n = in.readInt();
        int m = in.readInt();
        int r = n % m;
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};
        int total = n * m;
        int[] match = new int[total];
        int[] degree = new int[total];
        char[][] c = new char[n][m];
        boolean[] mark = new boolean[total];
        Queue<Integer> queue = new LinkedList<Integer>();
        for (int i = 0; i < n; i++) {
            c[i] = in.next().toCharArray();
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                for (int k = 0; k < 4; k++) {
                    int x = i + dx[k];
                    int y = j + dy[k];
                    if (x < 0 || x >= n || y < 0 || y >= m) {
                        continue;
                    }
                    if (c[i][j] == '*' || c[x][y] == '*') {
                        continue;
                    }
                    int v = x * m + y;
                    ++degree[v];
                }
            }
        }
        for (int i = 0; i < n * m; i++) {
            if (degree[i] <= 1) {
                mark[i] = true;
                queue.add(i);
            }
        }
        Arrays.fill(match, -1);
        while (!queue.isEmpty()) {
            int p = queue.poll();
            int x1 = p / m;
            int y1 = p % m;
            for (int k = 0; k < 4; k++) {
                int x2 = x1 + dx[k];
                int y2 = y1 + dy[k];
                if (x2 < 0 || x2 >= n || y2 < 0 || y2 >= m || c[x1][y1] == '*' || c[x2][y2] == '*') {
                    continue;
                }
                int i = x2 * m + y2;
                if (match[i] == -1 && match[p] == -1) {
                    match[i] = p;
                    match[p] = i;
                    if (!mark[i]) {
                        mark[i] = true;
                        queue.add(i);
                    }
                }
                if (--degree[i] <= 1 && !mark[i]) {
                    mark[i] = true;
                    queue.add(i);
                }
            }
        }
        for (int i = 0; i < n * m; i++) {
            if (match[i] == -1) {
                continue;
            }
            int x1 = i / m;
            int y1 = i % m;
            int x2 = match[i] / m;
            int y2 = match[i] % m;
            if (x1 == x2) {
                c[x1][Math.min(y1, y2)] = '<';
                c[x1][Math.max(y1, y2)] = '>';
            } else {
                c[Math.min(x1, x2)][y1] = '^';
                c[Math.max(x1, x2)][y2] = 'v';
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (c[i][j] == '.') {
                    out.printLine("Not unique");
                    return;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out.print(c[i][j] + (j == m - 1 ? "\n" : ""));
            }
        }
    }
}

class InputReader {

    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    public int readInt() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public String readString() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        StringBuilder res = new StringBuilder();
        do {
            if (Character.isValidCodePoint(c))
                res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    public boolean isSpaceChar(int c) {
        if (filter != null)
            return filter.isSpaceChar(c);
        return isWhitespace(c);
    }

    public static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public String next() {
        return readString();
    }

    public interface SpaceCharFilter {
        public boolean isSpaceChar(int ch);
    }
}

class OutputWriter {
    private final PrintWriter writer;

    public OutputWriter(OutputStream outputStream) {
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
