public class D {
	public static void main(String[] args) throws IOException{
		in.init(System.in);
		PrintWriter out = new PrintWriter(System.out);
		int n = in.nextInt();
		int m = in.nextInt();
		char[][] map = new char[n][m];
		for(int i = 0; i < n; i ++){
			String s = in.next();
			for(int j = 0; j < m; j ++){
				map[i][j] = s.charAt(j);
			}
		}

		Queue<Integer> hq = new LinkedList<Integer>();
		Queue<Integer> wq = new LinkedList<Integer>();

		int[] dh = {-1,0,1,0};
		int[] dw = {0,1,0,-1};
		char[] cc = {'^', '>', 'v', '<'};
		int[][] deg = new int[n][m];
		for(int i = 0; i < n; i ++){
			for(int j = 0; j < m; j ++){
				if(map[i][j] != '.')continue;
				for(int k = 0; k < 4; k ++){
					int nh = i + dh[k];
					int nw = j + dw[k];
					if(nh >= n || nh < 0 || nw >= m || nw < 0 || map[nh][nw] != '.')continue;
					deg[i][j] ++;
				}
			}
		}

		for(int i = 0; i < n; i ++){
			for(int j = 0; j < m; j ++){
				if(deg[i][j] == 1 && map[i][j] == '.'){

					hq.add(i);
					wq.add(j);
					deg[i][j] --;
				}
			}
		}



		while(!wq.isEmpty()){
			int ch = hq.poll();
			int cw = wq.poll();

			for(int i = 0; i < 4; i ++){
				int nh = ch + dh[i];
				int nw = cw + dw[i];
				if(nh < 0 || nh >= n || nw < 0 || nw >= m || map[nh][nw] != '.')continue;
				deg[nh][nw] = 0;
				map[nh][nw] = cc[i];
				map[ch][cw] = cc[(i + 2) % 4];
				for(int j = 0; j < 4; j ++){
					int nnh = nh + dh[j];
					int nnw = nw + dw[j];
					if(nnh < 0 || nnh >= n || nnw < 0 || nnw >= m || map[nnh][nnw] != '.')continue;
					deg[nnh][nnw] --;
					if(deg[nnh][nnw] == 1){
						hq.add(nnh);
						wq.add(nnw);
					}
				}
				// update degrees of neighbors of (ch,cw) as well
				for(int k = 0; k < 4; k++) {
					int nh2 = ch + dh[k];
					int nw2 = cw + dw[k];
					if(nh2 < 0 || nh2 >= n || nw2 < 0 || nw2 >= m || map[nh2][nw2] != '.') continue;
					deg[nh2][nw2]--;
					if(deg[nh2][nw2] == 1) {
						hq.add(nh2);
						wq.add(nw2);
					}
				}
			}
		}

		boolean ans = true;
		for(int i = 0; i < n; i ++){
			for(int j = 0; j < m; j ++){
				if(map[i][j] == '.'){
					ans = false;
					break;
				}
			}
		}
		if(ans){
			for(int i = 0; i < n; i ++){
				for(int j = 0; j < m; j ++){
					out.print(map[i][j]);
				}
				out.println();
			}
		}

		else out.println("Not unique");

		out.close();

	}

