                }
            }
            print(r0, c0, r1, c1, ret);
            done[r0][c0] = done[r1][c1] = true;

            // also update counts for neighbors of (r0,c0)
            for (int k = 0; k < 4; k++) {
                int rr = r0 + dr[k];
                int cc = c0 + dc[k];
                if (within(rr, cc) && !done[rr][cc] && str[rr].charAt(cc) == '.') {
                    cnt[rr][cc]--;
                    if (cnt[rr][cc] == 1) {
                        Q.add(pair(rr, cc));
                    }
                }
            }

