                int rr = r1 + dr[k];
                int cc = c1 + dc[k];
                if (within(rr, cc) && !done[rr][cc] && str[rr].charAt(cc) == '.') {
                    cnt[rr][cc]--;
                    if (cnt[rr][cc] == 1) {
                        Q.add(pair(rr, cc));
                    }
                }
            }
        }


        for (int r = 0; r < R; r++) {
