    }

    static class TaskB {
        String[] str = new String[]{"^v<>", "v^><"};

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.readInt();
            int m = in.readInt();
            char mat[][] = new char[n][m];
            for (int i = 0; i < n; i++) mat[i] = in.readLine().toCharArray();
            int[][] deg = new int[n][m];


            LinkedList<Integer> que = new LinkedList<>();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (mat[i][j] == '.') {
                        if (i + 1 < n && mat[i + 1][j] == '.') {
                            deg[i][j]++;
                            deg[i + 1][j]++;
                        }
                        if (j + 1 < m && mat[i][j + 1] == '.') {
                            deg[i][j]++;
                            deg[i][j + 1]++;
                        }
                    }
                    if (deg[i][j] == 1) {
                        if (!que.isEmpty()) {
                            out.println("Not unique");
                            return;
                        }
                        que.addLast(i);
                        que.addLast(j);
                    }
                }
            }
            int[] dx = new int[]{1, -1, 0, 0};
            int[] dy = new int[]{0, 0, 1, -1};

            while (!que.isEmpty()) {
                int x = que.pollFirst();
                int y = que.pollFirst();
                if (mat[x][y] != '.') continue;
                int nx = 0, ny = 0, idx = -1;
                for (int i = 0; i < 4; i++) {
                    nx = x + dx[i];
                    ny = y + dy[i];
                    if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
                    if (mat[nx][ny] == '.') {
                        idx = i;
                        break;
                    }
                }
                if (idx == -1) {
                    out.println("Not unique");
                    return;
                }
                mat[x][y] = str[0].charAt(idx);
                mat[nx][ny] = str[1].charAt(idx);
                deg[x][y]--;

                for (int i = 0; i < 4; i++) {
                    int tx = nx + dx[i];
                    int ty = ny + dy[i];
                    if (tx < 0 || tx >= n || ty < 0 || ty >= m) continue;
                    deg[tx][ty]--;
                    if (mat[tx][ty] == '.' && deg[tx][ty] == 1) {
                        que.addLast(tx);
                        que.addLast(ty);
                    }
                }
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (mat[i][j] == '.') {
                        out.println("Not unique");
                        return;
                    }
                }
            }
            for (int i = 0; i < n; i++) {
                out.println(new String(mat[i]));
            }

        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res =+ c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null)
                return filter.isSpaceChar(c);
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private String readLine0() {
            StringBuilder buf = new StringBuilder();
            int c = read();
            while (c != '\n' && c != -1) {
                if (c != '\r')
                    buf.appendCodePoint(c);
                c = read();
            }
            return buf.toString();
        }

        public String readLine() {
            String s = readLine0();
            while (s.trim().length() == 0)
                s = readLine0();
            return s;
