            char mat[][] = new char[n][m];
            for (int i = 0; i < n; i++) mat[i] = in.readLine().toCharArray();
            int[][] deg = new int[n][m];

            LinkedList<Integer> que = new LinkedList<>();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (mat[i][j] == '.') {
                        if (i + 1 < n && mat[i + 1][j] == '.') {
                            deg[i][j]++;
                            deg[i + 1][j]++;
                        }
                        if (j + 1 < m && mat[i][j + 1] == '.') {
                            deg[i][j]++;
                            deg[i][j + 1]++;
                        }
                    }
                    if (deg[i][j] == 1) {
                        que.addLast(i);
                        que.addLast(j);
                    }
                }
            }
