        if (ch(x-1,y)) c+=1;
        if (ch(x,y+1)) c+=1;
        if (ch(x,y-1)) c+=1;
        return c;
    }

    public static int f(int x, int y) {
        int c=-1;
        if (ch(x-1,y)) c=0;
        if (ch(x,y+1)) c=1;
        if (ch(x+1,y)) c=2;
        if (ch(x,y-1)) c=3;
        return c;
    }

