                b[x][y]=sy[c];
                b[x1][y1]=sy[c^2];
                for(int j=0; j<4; j++) {
                    if (ch(x1+nx[j],y1+ny[j]) && dg(x1+nx[j],y1+ny[j])==1) q1.add((x1+nx[j])*m+y1+ny[j]);
