    public static final char[] S2 = {'v', '>', '^', '<'};

    public B() throws Exception {
        int R = in.nextInt();
        int C = in.nextInt();
        char[][] map = new char[R][];
        for (int r=0; r<R; r++) map[r] = in.next().toCharArray();
        int empty = 0;
