public class Main {
	public static boolean result[];
	public static int dp[][];
	public static void main(String[] args) throws NumberFormatException, IOException{
		ContestScanner in = new ContestScanner();
		int n = in.nextInt();
		int m = in.nextInt();
		char[][] map = new char[n][m];
		int spaces = 0;
		for(int i=0; i<n; i++){
			map[i] = in.nextToken().toCharArray();
			for(int j=0; j<m; j++){
				if(map[i][j] == '.') spaces++;
			}
		}
		int[] dx = { 1, 0, -1, 0 };
		int[] dy = { 0, 1, 0, -1 };
		char[][] tile = {
				{'<', '>'},	
				{'^', 'v'},	
				{'>', '<'},	
				{'v', '^'},	
		};
		Queue<Val> qu = new LinkedList<Val>();
		for(int i=0; i<n; i++){
			for(int j=0; j<m; j++){
				if(map[i][j] != '.') continue;
				int sp = 0;
				int tmpk = -1;
				for(int k=0; k<4; k++){
					if(i+dy[k] < 0 || i+dy[k] >= n || j+dx[k] < 0 || j+dx[k] >= m) continue;
					if(map[i+dy[k]][j+dx[k]] == '.'){
						tmpk = k;
						sp++;
					}
				}
				if(sp == 1){
					qu.add(new Val(i, j, tmpk));
				}
			}
			if(spaces == 0) break;
		}
		while(!qu.isEmpty()){
			Val val = qu.poll();
			int y = val.y;
			int x = val.x;
			int k = val.k;
			if(map[y][x] != '.' || map[y+dy[k]][x+dx[k]] != '.') continue;
			spaces -= 2;
			map[y][x] = tile[k][0];
			map[y+dy[k]][x+dx[k]] = tile[k][1];
			if(spaces == 0) break;
			y = y+dy[k];
			x = x+dx[k];
			for(int j=0; j<4; j++){
				int newy = y+dy[j];
				int newx = x+dx[j];
				int tmpk = -1;
				int sp = 0;
				for(int i=0; i<4; i++){
					if(newy+dy[i] < 0 || newy+dy[i] >= n || newx+dx[i] < 0 || newx+dx[i] >= m) continue;
					if(map[newy+dy[i]][newx+dx[i]] == '.'){
						tmpk = i;
						sp++;
					}
				}
				if(sp == 1){
					qu.add(new Val(newy, newx, tmpk));
				}
			}
		}
		if(spaces == 0) System.out.println(output(map));
		else System.out.println("Not unique");
	}

	static String output(char[][] map){
		StringBuilder sb = new StringBuilder();
		for(int i=0; i<map.length; i++){
			for(int j=0; j<map[0].length; j++){
				sb.append(map[i][j]);
			}
			sb.append("\n");
		}
		return sb.toString();
	}
