import java.util.*;
import java.io.*;
public class MainClass
{
    static int n, m;
    static char[][] A;
    static int[] dx = {1, -1, 0, 0};
    static int[] dy = {0, 0, 1, -1};
    public static void main(String[] args) throws IOException
    {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        String s1[] = in.readLine().split(" ");
        n = Integer.parseInt(s1[0]);
        m = Integer.parseInt(s1[1]);
        A = new char[n][m];
        for (int i=0;i<n;i++)   A[i] = in.readLine().toCharArray();
        for (int i=0;i<n;i++)   for (int j=0;j<m;j++)   if (A[i][j] == '.') explore(i, j);
        boolean ff = true;
        for (int i=0;i<n;i++)   for (int j=0;j<m;j++)
        {
            if (A[i][j] == '.')
            {
                ff = false;
                break;
            }
        }
        if (ff)
        {
            StringBuilder stringBuilder = new StringBuilder();
            for (int i=0;i<n;i++)
            {
                for (int j=0;j<m;j++)   stringBuilder.append(A[i][j]);
                stringBuilder.append("\n");
            }
            System.out.println(stringBuilder);
        }
        else
            System.out.println("Not unique");
    }
    public static void explore(int x, int y)
    {
        int deg = deg(x, y);
        if (deg > 1 || deg < 1) return;
        int nx = -1;
        int ny = -1;
        for (int i=0;i<4;i++)
        {
            int xx = x + dx[i];
            int yy = y + dy[i];
            if (inBounds(xx, yy))
            {
                if (A[xx][yy] == '.')
                {
                    nx = xx;    ny = yy;
                }
            }
        }
        if (nx == x)
        {
            if (ny == y - 1)
            {
                A[nx][ny] = '<';
                A[x][y] = '>';
            }
            else
            {
                A[nx][ny] = '>';
                A[x][y] = '<';
            }
        }
        else
        {
            if (nx == x - 1)
            {
                A[nx][ny] = '^';
                A[x][y] = 'v';
            }
            else
            {
                A[nx][ny] = 'v';
                A[x][y] = '^';
            }
        }
        for (int i=0;i<4;i++)
        {
            int xx = x + dx[i];
            int yy = y + dy[i];
            if (inBounds(xx, yy) && A[xx][yy] == '.')
                explore(xx, yy);
        }
        for (int i=0;i<4;i++)
        {
            int xx = nx + dx[i];
            int yy = ny + dy[i];
            if (inBounds(xx, yy) && A[xx][yy] == '.')
                explore(xx, yy);
        }
    }
    public static int deg(int x, int y)
    {
        int count = 0;
        for (int i=0;i<4;i++)
        {
            int xx = x + dx[i];
            int yy = y + dy[i];
            if (inBounds(xx, yy) && A[xx][yy] == '.')
                count++;
        }
        return count;
    }
    public static boolean inBounds(int x, int y)
    {
        return x >= 0 && x < n && y >= 0 && y < m;
    }
}
