            }
            System.out.println(stringBuilder);
        }
        else
            System.out.println("Not unique");
    }
    public static void explore(int x, int y)
    {
        int deg = deg(x, y);
        if (deg > 1 || deg < 1) return;
        int nx = -1;
        int ny = -1;
        for (int i=0;i<4;i++)
        {
            int xx = x + dx[i];
            int yy = y + dy[i];
            if (inBounds(xx, yy))
            {
                if (A[xx][yy] == '.')
                {
                    nx = xx;    ny = yy;
                }
            }
        }
        if (nx == x)
        {
            if (ny == y - 1)
            {
                A[nx][ny] = '<';
                A[x][y] = '>';
            }
            else
            {
                A[nx][ny] = '>';
                A[x][y] = '<';
            }
        }
        else
        {
            if (nx == x - 1)
            {
                A[nx][ny] = '^';
                A[x][y] = 'v';
            }
            else
            {
                A[nx][ny] = 'v';
                A[x][y] = '^';
            }
        }
        for (int i=0;i<4;i++)
        {
            int xx = x + dx[i];
            int yy = y + dy[i];
            if (inBounds(xx, yy) && A[xx][yy] == '.')
                explore(xx, yy);
        }
        for (int i=0;i<4;i++)
        {
            int xx = nx + dx[i];
            int yy = ny + dy[i];
            if (inBounds(xx, yy) && A[xx][yy] == '.')
                explore(xx, yy);
        }
