                    G[i][j] = cnt;
                    if (G[i][j] == 1) {
                        Q.add(i);
                        Q.add(j);
                    }
                }
            }
        }
        while (!Q.isEmpty()) {
            int pi = Q.remove();
            int pj = Q.remove();
            if (A[pi][pj] != '.') continue;
            for (int d = 0; d < 4; d++) {
                int ni = pi + di[d];
                int nj = pj + dj[d];
                if (ni >= 0 && ni < N && nj >= 0 && nj < M && A[ni][nj] == '.') {
                    G[ni][nj]--;
                    if (G[ni][nj] == 1) {
                        Q.add(ni);
                        Q.add(nj);
                    }
                }
            }
            int mi = -1;
            int mj = -1;
            for (int d = 0; d < 4; d++) {
                int ni = pi + di[d];
                int nj = pj + dj[d];
                if (ni >= 0 && ni < N && nj >= 0 && nj < M && A[ni][nj] == '.') {
                    mark(pi, pj, ni, nj);
                    mi = ni;
                    mj = nj;
                    break;
                }
            }
            if (mi == -1) continue;
            for (int d = 0; d < 4; d++) {
                int ni = mi + di[d];
                int nj = mj + dj[d];
                if (ni >= 0 && ni < N && nj >= 0 && nj < M && A[ni][nj] == '.') {
