        for (int i = 0; i < N; i++) {
            out.println(A[i]);
        }
    }

    private void mark(int pi, int pj, int ni, int nj) {
        if (pi == ni) { 
            if (pj > nj) {
                int aux = pj; pj = nj; nj = aux;
            }
            A[pi][pj] = '<';
            A[ni][nj] = '>';
        }
        else { 
            if (pi > ni) {
                int aux = pi; pi = ni; ni = aux;
            }
            A[pi][pj] = '^';
            A[ni][nj] = 'v';
        }
    }
