import java.io.IOException;
import java.util.InputMismatchException;
import java.util.LinkedList;

public class DrazilAndTiles {
    private static final int[] DR = { -1, 0, 1, 0 };
    private static final int[] DC = { 0, 1, 0, -1 };

    public static void main(String[] args) {
        FasterScanner sc = new FasterScanner();

        int N = sc.nextInt();
        int M = sc.nextInt();

        char[][] board = new char[N][];
        for (int i = 0; i < N; i++) {
            board[i] = sc.nextString().toCharArray();
        }

        for (int r = 0; r < N; r++) {
            for (int c = 0; c < M; c++) {
                expand(board, N, M, r, c);
            }
        }

        for (int r = 0; r < N; r++) {
            for (int c = 0; c < M; c++) {
                if (board[r][c] == '.') {
                    System.out.println("Not unique");
                    return;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < N; r++) {
            sb.append(board[r]);
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }

    private static void expand(char[][] board, int N, int M, int r0, int c0) {
        int d0 = getDirection(board, N, M, r0, c0);
        if (d0 < 0) {
            return;
        }
        LinkedList<Integer> rQ = new LinkedList<Integer>();
        LinkedList<Integer> cQ = new LinkedList<Integer>();
        LinkedList<Integer> dQ = new LinkedList<Integer>();
        rQ.addLast(r0);
        cQ.addLast(c0);
        dQ.addLast(d0);
        updateBoard(board, N, M, r0, c0, d0);
        while (!rQ.isEmpty()) {
            int r = rQ.removeFirst();
            int c = cQ.removeFirst();
            int d = dQ.removeFirst();
            int rp = r + DR[d];
            int cp = c + DC[d];
            for (int i = 0; i < 4; i++) {
                int rn = rp + DR[i];
                int cn = cp + DC[i];
                int dn = getDirection(board, N, M, rn, cn);
                if (dn >= 0) {
                    updateBoard(board, N, M, rn, cn, dn);
                    rQ.addLast(rn);
                    cQ.addLast(cn);
                    dQ.addLast(dn);
                }
            }
        }
    }

    private static void updateBoard(char[][] board, int N, int M, int r, int c, int d) {
        if (d == 0) {
            board[r - 1][c] = '^';
            board[r][c] = 'v';
        } else if (d == 1) {
            board[r][c] = '<';
            board[r][c + 1] = '>';
        } else if (d == 2) {
            board[r][c] = '^';
            board[r + 1][c] = 'v';
        } else if (d == 3) {
            board[r][c - 1] = '<';
            board[r][c] = '>';
        }
    }

    private static int getDirection(char[][] board, int N, int M, int r0, int c0) {
        if (!valid(N, M, r0, c0) || board[r0][c0] != '.') {
            return -1;
        }

        int dir = -1;
        boolean found = false;
        for (int i = 0; i < 4; i++) {
            int r = r0 + DR[i];
            int c = c0 + DC[i];          // <--- fixed: was c0 * DC[i]
            if (valid(N, M, r, c) && board[r][c] == '.') {
                if (!found) {
                    dir = i;
                    found = true;
                } else {
                    return -1;
                }
            }
        }
        return dir;
    }

    private static boolean valid(int N, int M, int r, int c) {
        return (r >= 0 && r < N && c >= 0 && c < M);
    }

    public static class FasterScanner {
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = System.in.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public String nextLine() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        public long[] nextLongArray(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

