import java.util.*;
public class B {

    static Scanner reader = new Scanner(System.in);
    static int n,m;
    static StringBuilder a[];
    static class cell{
        public int row,col;
        cell(int row,int col){
            this.row=row; this.col=col;
        }
    };
    static int dr[]={0,0,-1,1},
            dc[]={-1,1,0,0};
    static ArrayList<cell> q=new  ArrayList<cell>();
    static boolean dd[][];
    static void doProc(int i,int j) throws Exception{
        if (calcdeg(i, j)!=1) return;
        int x=i,y=j,k;

        for (k=0;k<4;k++){
            x=i+dr[k]; y=j+dc[k];
            if (x>=0&&x<n&&y>=0&&y<m){
                if (a[x].charAt(y)=='.')
                    break;
            }
        }
        if (k<4){
            if (k<=1){
                if (k==0){
                    a[i].setCharAt(j-1,'<');
                    a[i].setCharAt(j,'>');
                }else{
                    a[i].setCharAt(j,'<');
                    a[i].setCharAt(j+1,'>');
                }
            }else{
                if (k==2){
                    a[i-1].setCharAt(j, '^');
                    a[i].setCharAt(j, 'v');
                }else{
                    a[i].setCharAt(j, '^');
                    a[i+1].setCharAt(j, 'v');
                }
            }
            for (k=0;k<4;k++){
                if (calcdeg(x+dr[k],y+dc[k])==1){
                    q.add(new cell(x+dr[k], y+dc[k]));
                }
            }
        }
    }
    static int calcdeg(int i,int j)throws Exception{
        if (i<0||i>=n||j<0||j>=m) return 0;
        if (a[i].charAt(j)!='.') return 0;
        int k,x =i,y=j,res;
        res=0;
        for (k=0;k<4;k++){
            x=i+dr[k]; y=j+dc[k];
            if (x>=0&&x<n&&y>=0&&y<m){
                if (a[x].charAt(y)=='.')
                    res++;
            }
        }
        if (res==1){
            if (dd[i][j]==false){
                q.add(new cell(i, j));
                dd[i][j]=true;
            }
        }
        return res;
    }

