        n=reader.nextInt();
        m=reader.nextInt();
        reader.nextLine();
        a=new StringBuilder[n];
        int i,j,k,x,y;
        dd=new boolean[n+2][m+2];
        for (i=0;i<=n;i++)Arrays.fill(dd[i], false); 
        for (i=0;i<n;i++)
            a[i]=new StringBuilder(reader.nextLine());
        for (i=0;i<n;i++) for (j=0;j<m;j++){
            if (a[i].charAt(j)=='.') calcdeg(i, j);
        }
        for (i=0;i<q.size();i++){
            doProc(q.get(i).row, q.get(i).col);
        }
        for (i=0;i<n;i++) for (j=0;j<m;j++) 
            if (a[i].charAt(j)=='.'){
                System.out.print("Not unique");
                return;
            }
        for (i=0;i<n;i++)
            System.out.println(a[i].toString());
    }

}

import java.io.*;
import java.util.*;

public class Solution {
    StringTokenizer st;
    BufferedReader in;
    PrintWriter out;

    void solve() throws IOException {
        in = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(new OutputStreamWriter(System.out));
        Locale.setDefault(Locale.ENGLISH);

        n = nextInt();
        m = nextInt();

        a = new char[n][m];
        for (int i = 0; i < n; i++) {
            String s = in.readLine();
            for (int j = 0; j < m; j++) {
                a[i][j] = s.charAt(j);
            }
        }

        Queue<int[]> q = new LinkedList<>();
        boolean[][] used = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int[] pos = getPos(i, j);
                if (pos[0] != -1) {
                    used[pos[0]][pos[1]] = true;          // fixed index
                    q.add(pos);
                }
            }
        }

        while (!q.isEmpty()) {
            int x = q.peek()[0];
            int y = q.peek()[1];
            q.poll();

            for (int k = 0; k < 4; k++) {
                int nx = x + dx[k];
                int ny = y + dy[k];
                int[] pos = getPos(nx, ny);
                if (pos[0] != -1 && !used[pos[0]][pos[1]]) {
                    used[pos[0]][pos[1]] = true;
                    q.add(pos);
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (a[i][j] == '.') {
                    out.print("Not unique");
                    out.close();
                    return;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out.print(a[i][j]);
            }
            out.println();
        }

        in.close();
        out.close();
    }

    char[][] a;
    int n, m;

    int[] dx = {-1, 0, 1, 0};
    int[] dy = {0, -1, 0, 1};

    int[] getPos(int x, int y) {
        if (!inside(x, y) || a[x][y] != '.') {
            return new int[]{-1, -1};
        }

        int[] pos = new int[]{-1, -1};

        for (int k = 0; k < 4; k++) {
            int nx = x + dx[k];
            int ny = y + dy[k];

            if (inside(nx, ny) && a[nx][ny] == '.') {
                if (pos[0] == -1) {
                    pos = new int[]{nx, ny};
                } else {
                    return new int[]{-1, -1};
                }
            }
        }

        if (pos[0] == -1) {
            return new int[]{-1, -1};
        }

        if (pos[0] < x) {
            a[pos[0]][y] = '^';
            a[x][y] = 'v';
        }

        if (pos[0] > x) {
            a[x][y] = '^';
            a[pos[0]][y] = 'v';
        }

        if (pos[1] < y) {
            a[x][pos[1]] = '<';
            a[x][y] = '>';
        }

        if (pos[1] > y) {
            a[x][y] = '<';
            a[x][pos[1]] = '>';
        }

        return pos;
    }

    boolean inside(int x, int y) {
        return 0 <= x && x < n && 0 <= y && y < m;
    }

    public static void main(String[] args) throws IOException {
        new Solution().solve();
    }

    String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(in.readLine());
        }
        return st.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }
}

