            a[i]=sc.next().toCharArray();
        deg=new int [V];
        int [] q=new int [V+10];
        int front=0,back=0;
        int cntDot=0;
        for(int i=0;i<n;i++)
        	for(int j=0;j<m;j++) {
        		if(a[i][j]=='.') {
        			cntDot++;
        			for(int k=0;k<4;k++) { 
        				int nr=i+dx[k];
        				int nc=j+dy[k];
        				if(valid(nr, nc) && a[nr][nc]=='.') {
        					deg[i*m+j]++;
        					deg[nr*m+nc]++;
        				}
        			}
        			if(deg[i*m+j]==1)
        				q[back++]=i*m+j;
        		}
        	}
        boolean ok=true;
        while(front!=back) {
        	int p=q[front++];
        	int r=p/m;
        	int c=p%m;
        	if(a[r][c]!='.')
        		continue;
        	cntDot-=2;
        	boolean done=false;
        	for(int k=0;k<4;k++) {
				int nr=r+dx[k];
				int nc=c+dy[k];
				if(valid(nr, nc) && a[nr][nc]=='.') {
					done=true;
					a[r][c]=s1[k];
					a[nr][nc]=s2[k];
					for(int k2=0;k2<4;k2++) {
						int nnr=nr+dx[k2];
						int nnc=nc+dy[k2];
						if(valid(nnr, nnc) && --deg[nnr*m+nnc]==1)
							q[back++]=nnr*m+nnc;
					}
					break;
				}
        	}
        	ok &=done;

        }
        if(!ok || cntDot>0)
        	pw.println("Not unique");
        else
        	for(int i=0;i<n;i++)
        		pw.println(new String(a[i]));

        pw.flush();
        pw.close();
    }

