                        int nj = j + dy[k];
                        if(isOk(ni,nj) && arr[ni][nj] == '.')
                        {
                            neigh[i][j]++;
                        }
                    }
                    if(neigh[i][j]==1)
                    {
                        queue.add(i);
                        queue.add(j);
                    }
                }
            }
        while(!queue.isEmpty())
        {
            int x=queue.poll();
            int y=queue.poll();
            if(arr[x][y]=='.')
            {
                for(int j = 0; j < 4; j++)
                {
                    int ni = x + dx[j];
                    int nj = y + dy[j];
                    if(isOk(ni, nj) && arr[ni][nj] == '.')
                    {
                        arr[x][y] = val[j];
                        arr[ni][nj] = val[j ^ 1];
                        update(x, y);
                        update(ni, nj);
                        break;
                    }
                }
            }
        }
        boolean ok=true;
        for(int i=0;i<n;i++)
            for(int j=0;j<m;j++)
                if(arr[i][j]=='.')
                    ok=false;
        if(!ok)
            out.println("Not unique");
        else
        {
            for(int i=0;i<n;i++)
                out.println(new String(arr[i]));
        }
    }

    private boolean isOk(int ni, int nj)
    {
        return 0 <= ni && ni < n && 0 <= nj && nj < m;
    }
}

