class SolverD {

    public void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        char a[][] = new char[n+2][m+2];


        for (int i=0; i<=m+1; i++) {
            a[0][i] = '*';
            a[n+1][i] = '*';
        }
        for (int i=0; i<=n+1; i++) {
            a[i][0] = '*';
            a[i][m+1] = '*';
        }

        for (int i=1; i<=n; i++) {
            String s = in.next();
            for (int j=1; j<=m; j++) {
                a[i][j] = s.charAt(j-1);
            }
        }

        Queue<Tuple> q = new LinkedList<>();
        for (int i=1; i<=n; i++) {
            for (int j=1; j<=m; j++) {
                if (a[i][j] == '.' && deg1(a, i, j)) {
                    q.add(new Tuple(i, j));
                }
            }
        }

        while (!q.isEmpty()) {
            Tuple t = q.poll();

            if (a[t.a][t.b] != '.') {
                continue;
            }

            Tuple next = next(a, t);

            if (next == null) {
                continue;
            }

            if (deg1(a, next.a-1, next.b)) {
                q.add(new Tuple(next.a-1, next.b));
            }
            if (deg1(a, next.a+1, next.b)) {
                q.add(new Tuple(next.a+1, next.b));
            }
            if (deg1(a, next.a, next.b-1)) {
                q.add(new Tuple(next.a, next.b-1));
            }
            if (deg1(a, next.a, next.b+1)) {
                q.add(new Tuple(next.a, next.b+1));
            }
        }

        boolean good = true;
        for (int i=1; i<=n; i++) {
            for (int j=1; j<=m; j++) {
                if (a[i][j] == '.') {
                    good = false;
                    break;
                }
            }
            if (!good) {
                break;
            }
        }

        if (!good) {
            out.println("Not unique");
        } else {
            for (int i=1; i<=n; i++) {
                for (int j=1; j<=m; j++) {
                    out.print(a[i][j]);
                }
                out.println();
            }
        }

    }

    private Tuple next(final char[][] a, final Tuple t) {
        if (a[t.a-1][t.b] == '.') {
            a[t.a-1][t.b] = '^';
            a[t.a][t.b] = 'v';
            return new Tuple(t.a-1, t.b);
        }
        if (a[t.a+1][t.b] == '.') {
            a[t.a][t.b] = '^';
            a[t.a+1][t.b] = 'v';
            return new Tuple(t.a+1, t.b);
        }
        if (a[t.a][t.b-1] == '.') {
            a[t.a][t.b-1] = '<';
            a[t.a][t.b] = '>';
            return new Tuple(t.a, t.b-1);
        }
        if (a[t.a][t.b+1] == '.') {
            a[t.a][t.b] = '<';
            a[t.a][t.b+1] = '>';
            return new Tuple(t.a, t.b+1);
        }
        return null;
    }

    private boolean deg1(final char[][] a, final int i, final int j) {
        if (a[i][j] != '.') {
            return false;
        }

        int d = 0;
        d += a[i][j-1] == '.' ? 1 : 0;
        d += a[i][j+1] == '.' ? 1 : 0;
        d += a[i-1][j] == '.' ? 1 : 0;
        d += a[i+1][j] == '.' ? 1 : 0;
        return d == 1;
    }

    class Tuple {
        int a, b;

        Tuple(int a, int b) {
            this.a = a;
            this.b = b;
        }
    }

    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

