        int x;
        int y;
        Pair(int x,int y){
            this.x = x;
            this.y = y;
        }
    }

    Queue<Pair> Q = new ArrayDeque<Pair>();

    private boolean good_cell(int x,int y){
        if(x >= n || y >= m || x < 0 || y < 0) return false;
        if(a[x][y] == '.') return true;
        return false;
    }

    private void update_neighbours(int i,int j){
        for(int k = 0; k < 4; k++){
            int x = i + dl[k];
            int y = j + dc[k];
            if(good_cell(x,y)) {
                grad[x][y]--;
                if(grad[x][y] == 1) Q.add(new Pair(x,y));
            }
        }
    }

    public void solve(int testNumber, Scanner in, PrintWriter out) {
        n = in.nextInt();
        m = in.nextInt();
