                    for (int k = 0; k < 4; k++) {
                        int ii = i + dl[k];
                        int jj = j + dc[k];
                        if (good_cell(ii, jj)) grad[i][j]++;
                    }
                    if (grad[i][j] == 1) Q.add(new Pair(i,j));
                }
        while(!Q.isEmpty()){
            Pair p = Q.remove();
            if(grad[p.x][p.y] == 0){
                out.print("Not unique");
                return;
            }
            for(int k = 0; k < 4; k++){
                int ii = p.x + dl[k];
                int jj = p.y + dc[k];
                if(good_cell(ii,jj)){
                    if(k == 0){
                        a[p.x][p.y] = '<';
                        a[ii][jj] = '>';
                        update_neighbours(ii,jj);
                    }
                    else if(k == 1){
                        a[p.x][p.y] = '>';
                        a[ii][jj] = '<';
                        update_neighbours(ii,jj);
                    }
                    else if(k == 2){
                        a[p.x][p.y] = 'v';
                        a[ii][jj] = '^';
                        update_neighbours(ii,jj);
                    }
                    else{
                        a[p.x][p.y] = '^';
                        a[ii][jj] = 'v';
                        update_neighbours(ii,jj);
                    }
                    break;
                }
            }
        }
        for(int i = 0; i < n; i++)
            for(int j = 0; j < m; j++)
                if(a[i][j] == '.'){
                    out.print("Not unique");
                    return;
                }
        for(int i = 0; i < n; i++){
            for(int j = 0; j < m; j++)
                out.print(a[i][j]);
            out.print("\n");
        }

    }
}

