public class D {
    private static class Pair {
        int i;
        int j;

        private Pair(int i, j) {
            this.i = i;
            this.j = j;
        }
    }

    private static int n;
    private static int m;
    private static int[][] countOfEmptyNeighbors;
    private static Pair[][] pairs;
    private static char[][] field;
    private static Queue<Pair> current;
    private static Queue<Pair> next;

    private static void recalEmptyNeighbors(int i, int j, Queue<Pair> queue) {
        if (i < 0 || i >= n) return;
        if (j < 0 || j >= m) return;
        countOfEmptyNeighbors[i][j] = 0;
        if (i > 0 && field[i - 1][j] == '.') {
            countOfEmptyNeighbors[i][j]++;
        }
        if (i < n - 1 && field[i + 1][j] == '.') {
            countOfEmptyNeighbors[i][j]++;
        }
        if (j > 0 && field[i][j - 1] == '.') {
            countOfEmptyNeighbors[i][j]++;
        }
        if (j < m - 1 && field[i][j + 1] == '.') {
            countOfEmptyNeighbors[i][j]++;
        }
        if (countOfEmptyNeighbors[i][j] == 1 && field[i][j] == '.') {
            queue.add(pairs[i][j]);
        }
    }


    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        n = in.nextInt();
        m = in.nextInt();
        in.nextLine();
        field = new char[n][m];
        pairs = new Pair[n][m];
        countOfEmptyNeighbors = new int[n][m];
        for (int i = 0; i < n; i++) {
            String str = in.nextLine();
            for (int j = 0; j < m; j++) {
                field[i][j] = str.charAt(j);
                pairs[i][j] = new Pair(i, j);
            }
        }

        current = new LinkedList<Pair>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                recalEmptyNeighbors(i, j, current);
            }
        }

        while (current.size() > 0) {
            next = new LinkedList<Pair>();
            for (Pair one : current) {

                if (field[one.i][one.j] != '.') continue;
                int i = one.i;
                int j = one.j;
                if (i > 0 && field[i - 1][j] == '.') {
                    field[i][j] = 'v';
                    field[i - 1][j] = '^';
                    recalEmptyNeighbors(i - 2, j, next);
                    recalEmptyNeighbors(i - 1, j - 1, next);
                    recalEmptyNeighbors(i - 1, j + 1, next);
                }
                if (i < n - 1 && field[i + 1][j] == '.') {
                    field[i][j] = '^';
                    field[i + 1][j] = 'v';
                    recalEmptyNeighbors(i + 2, j, next);
                    recalEmptyNeighbors(i + 1, j - 1, next);
                    recalEmptyNeighbors(i + 1, j + 1, next);
                }
                if (j > 0 && field[i][j - 1] == '.') {
                    field[i][j] = '>';
                    field[i][j - 1] = '<';
                    recalEmptyNeighbors(i, j - 2, next);
                    recalEmptyNeighbors(i - 1, j - 1, next);
                    recalEmptyNeighbors(i + 1, j - 1, next);
                }
                if (j < m - 1 && field[i][j + 1] == '.') {
                    field[i][j] = '<';
                    field[i][j + 1] = '>';
                    recalEmptyNeighbors(i, j + 2, next);
                    recalEmptyNeighbors(i - 1, j + 1, next);
                    recalEmptyNeighbors(i + 1, j + 1, next);
                }
            }
            current = next;
        }

        boolean notUniq = false;
        for (int i= 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (field[i][j] == '.') {
                    notUniq = true;
                }
            }
        }

        if (notUniq) {
            System.out.println("Not unique");
        } else {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    sb.append(field[i][j]);
                }
                sb.append("\n");
            }
            System.out.println(sb.toString());
        }
    }
}

