                    field[i][j] = '<';
                    field[i][j + 1] = '>';
                    recalEmptyNeighbors(i, j + 2, next);
                    recalEmptyNeighbors(i - 1, j + 1, next);
                    recalEmptyNeighbors(i + 1, j + 1, next);
                }
            }
            current = next;
        }

        boolean notUniq = false;
        for (int i= 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (field[i][j] == '.') {
                    notUniq = true;
                }
            }
        }

        if (notUniq) {
            System.out.println("Not unique");
        } else {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    sb.append(field[i][j]);
                }
                sb.append("\n");
            }
            System.out.println(sb.toString());
        }
    }
}

