        m.out.close();
    }

    public void initIO() throws IOException {
        if(!isFileIO) {
            in = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out);
        } else {
            in = new BufferedReader(new FileReader("input.txt"));
            out = new PrintWriter("output.txt");
        }
    }

    String nt() throws IOException {
        if(!st.hasMoreTokens()) {
            st = new StringTokenizer(in.readLine());
        }
        return st.nextToken(delim);
    }

    String rl() throws IOException {
        return in.readLine();
    }

    int ni() throws IOException {
        return Integer.parseInt(nt());
    }

    long nl() throws IOException {
        return Long.parseLong(nt());
    }

    double nd() throws IOException {
        return Double.parseDouble(nt());
    }

    class Pair {
        public int x, y;
        public Pair (int x,int y) {
            this.x = x;
            this.y = y;
        }
    }

    int n, m;
    char[][] s;
    boolean[][] used;
    boolean[][] inq;
    int[][] d = {{0, -1}, {-1, 0}, {0, 1}, {1, 0}};
    public void solve() throws IOException {
        n = ni(); m = ni();
        s = new char[n][m];
        used = new boolean[n][m];
        inq  = new boolean[n][m];
        for(int i = 0; i < n; i++) {
            String str = rl();
            for(int j = 0; j < m; j++) {
                s[i][j] = str.charAt(j);
            }
        }
        ArrayDeque<Pair> q = new ArrayDeque<Pair>();
        int cnt = 0;
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < m; j++) {
                if(s[i][j] == '.') {
                    cnt = 0;
                    for(int z = 0; z < 4; z++) {
                        if(isOk(i - d[z][0], j - d[z][1]) && s[i - d[z][0]][j - d[z][1]] == '.') {
                            cnt++;
                        }
                    }
                    if(cnt == 1) {
                        q.addLast(new Pair(i, j));
                        inq[i][j] = true;
                    }
                }
            }
        }
        ArrayList<Pair> ans = new ArrayList<Pair>();
        int _x, _y, degree, xx, yy;
        while(!q.isEmpty()) {
            Pair pair = q.pollFirst();
            if(used[pair.x][pair.y]) {
                continue;
            }
            used[pair.x][pair.y] = true;
            degree = getDegree(pair.x, pair.y);
            if(degree == 0) {
                out.println("Not unique");
                return;
            }
            _x = _y = 0;
            for(int i = 0; i < 4; i++) {
                _x = pair.x - d[i][0]; _y = pair.y - d[i][1];
                if(isOk(_x, _y) && s[_x][_y] == '.' && !used[_x][_y]) {
                    used[_x][_y] = true;
                    ans.add(new Pair(pair.x, pair.y));
                    ans.add(new Pair(_x, _y));
                    break;
                }
            }
            for(int i = 0; i < 4; i++) {
                xx = _x - d[i][0]; yy = _y - d[i][1];
                if(isOk(xx, yy) && s[xx][yy] == '.' && !used[xx][yy] && !inq[xx][yy]) {
                    degree = getDegree(xx, yy);
                    if(degree == 1) {
                        q.addLast(new Pair(xx, yy));
                        inq[xx][yy] = true;
                    }
                }
            }
            for(int i = 0; i < 4; i++) {
                _x = pair.x - d[i][0]; _y = pair.y - d[i][1];
                if(isOk(_x, _y) && s[_x][_y] == '.' && !used[_x][_y] && !inq[_x][_y]) {
                    degree = getDegree(_x, _y);
                    if(degree == 1) {
                        q.addLast(new Pair(_x, _y));
                        inq[_x][_y] = true;
                    }
                }
            }
        }
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < m; j++) {
                if(!used[i][j] && s[i][j] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }
        for(int i = 0; i < ans.size(); i += 2) {
            Pair first = ans.get(i);
            Pair second = ans.get(i + 1);
            if(first.x == second.x) {
                if(first.y < second.y) {
                    s[first.x][first.y] = '<';
                    s[first.x][second.y] = '>';
                } else {
                    s[first.x][first.y] = '>';
                    s[first.x][second.y] = '<';
                }
            } else {
                if(first.x < second.x) {
                    s[first.x][first.y] = '^';
                    s[second.x][first.y] = 'v';
                } else {
                    s[first.x][first.y] = 'v';
                    s[second.x][first.y] = '^';
                }
            }
        }
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < m; j++) {
                out.print(s[i][j]);
            }
            out.println();
        }
    }

    boolean isOk(int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    int getDegree(int x, int y) {
        int _x, _y, res;
        res = 0;
        for(int i = 0; i < 4; i++) {
            _x = x - d[i][0]; _y = y - d[i][1];
            if(isOk(_x, _y) && s[_x][_y] == '.' && !used[_x][_y]) {
                res++;
            }
        }
        return res;
    }
}

class Utils {

    public static long binpow(long a, long exp, long mod) {
        if(exp == 0) {
            return 1;
        }
        if(exp % 2 == 0) {
            long temp = binpow(a, exp / 2, mod);
            return (temp * temp) % mod;
        } else {
            return (binpow(a, exp - 1, mod) * a) % mod;
        }
    }

    public static long inv(long a, long mod) {
        return binpow(a, mod - 2, mod);
    }

    public static long addmod(long a, long b, long mod) {
        return ((a + b) % mod + mod) % mod;
    }

    public static long gcd(long a, long b) {
        if(b == 0)
            return a;
        return gcd(b, a % b);
    }


    public static long mulmod(long a, long b, long mod) {
        return (a * b + (((a * b) / mod) + 1) * mod) % mod;
    }
}

