              rec[x][y] = true;
            }
          }
        }
      }
    }
    for(int i = 0; i < rec.length; i++) {
      for(int j = 0; j < rec.length; j++) {
        if(rec[i][j] != atk[i][j]) {
          System.out.println("NO");
          return;
        }
      }
    }
    System.out.println("YES");
    for(int i = 0; i < res.length; i++) {
      for(int j = 0; j < res.length; j++) {
        if(i == n - 1 && j == n - 1) {
          System.out.print("o");
        } else {
          if(res[i][j]) {
            System.out.print("x");
          } else {
            System.out.print(".");
          }
        }
      }
      System.out.println();
    }

  }

