public class D {
    FastScanner in;
    PrintWriter out;
    boolean systemIO = true;

    public void solve() throws IOException {
        int n = in.nextInt();
        int[][] a = new int[n][n];
        int[] x = new int[n * n];
        int[] y = new int[n * n];
        int numofO = 0;
        for (int i = 0; i < n; i++) {
            String s = in.next();
            for (int j = 0; j < n; j++) {
                if (s.charAt(j) == '.') {
                    a[i][j] = 0;
                }
                if (s.charAt(j) == 'x') {
                    a[i][j] = 1;
                }
                if (s.charAt(j) == 'o') {
                    a[i][j] = 2;
                    x[numofO] = i;
                    y[numofO] = j;
                    numofO++;
                }
            }
        }

        int[][] ans = new int[2 * n - 1][2 * n - 1];
        int[][] cor = new int[n][n];

        for (int i = -n + 1; i < n; i++) {
            for (int j = -n + 1; j < n; j++) {


                int dh = 0;
                for (int k = 0; k < numofO; k++) {
                    int xx = x[k] + i;
                    int yy = y[k] + j;
                    if (xx < 0 || yy < 0 || yy >= n || xx >= n) {

                        continue;
                    }
                    if (a[xx][yy] == 0) {
                        dh++;
                        continue;
                    }

                }
                if (dh == 0) {
                    ans[i + n - 1][j + n - 1] = 1;
                    for (int k = 0; k < numofO; k++) {
                        int xx = x[k] + i;
                        int yy = y[k] + j;
                        if (xx < 0 || yy < 0 || yy >= n || xx >= n) {
                            continue;
                        }
                        cor[xx][yy] = 1;
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (a[i][j] == 1 && cor[i][j] == 0) {
                    out.print("NO");
                    return;
                }
            }
        }

        out.println("YES");
        ans[n - 1][n - 1] = 2;
        for (int i = 0; i < 2 * n - 1; i++) {
            for (int j = 0; j < 2 * n - 1; j++) {
                if (ans[i][j] == 0) {
                    out.print(".");
                }
                if (ans[i][j] == 1) {
                    out.print("x");
                }
                if (ans[i][j] == 2) {
                    out.print("o");
                }
            }
            out.println();
        }
    }

