    static class TaskD {
        char grid[][];
        char ans[][];

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            grid = new char[N + 2][N + 2];
            List<Point> pieces = new LinkedList<>();
            for (int i = 1; i <= N; i++) {
                char row[] = in.next().toCharArray();
                for (int j = 1; j <= N; j++) {
                    grid[i][j] = row[j - 1];
                    if (grid[i][j] == 'o') {
                        pieces.add(new Point(i, j));
                    }
                }
            }
            Point ps[] = pieces.toArray(new Point[0]);
            int points = ps.length;
            // Fixed allocation: (2N-1) x (2N-1)
            ans = new char[2 * N - 1][2 * N - 1];
            for (int i = 0; i < 2 * N - 1; i++) {
                for (int j = 0; j < 2 * N - 1; j++) {
                    ans[i][j] = 'x';
                }
            }
            ans[N - 1][N - 1] = 'o';

            for (int i = 0; i < 2 * N - 1; i++) {
                for (int j = 0; j < 2 * N - 1; j++) {
                    if (i == N - 1 && j == N - 1) continue;

                    int dx = (i + 1) - N;
                    int dy = (j + 1) - N;
                    for (int k = 0; k < points; k++) {
                        int x = ps[k].x + dx;
                        int y = ps[k].y + dy;
                        if (x < 1 || x > N || y < 1 || y > N) continue;
                        if (grid[x][y] == '.') {
                            ans[i][j] = '.';
                        }
                    }
                }
            }
            if (correct(N, ans, grid, ps, points)){
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < 2 * N - 1; i++) {
                    for (int j = 0; j < 2 * N - 1; j++) {
                        sb.append(ans[i][j]);
                    }
                    sb.append('\n');
                }

                out.println("YES");
                out.println(sb);
            } else {
                out.println("NO");
            }


        }

        private boolean correct(int N, char[][] ans, char[][] grid, Point[] ps, int points) {
            for (int i=1; i<=N; i++){
                for (int j=1; j<=N; j++){
                    if (grid[i][j] == 'x'){
                        boolean flag = false;
                        for (int k = 0; k < points; k++) {
                            int dx = i - ps[k].x ;
                            int dy = j - ps[k].y;
                            if (ans[N-1 + dx][N-1+dy] == 'x'){
                                flag = true;
                            }
                        }
                        if (!flag){
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        private static class Point {
            int x;
            int y;

            private Point(int x, int y) {
                this.x = x;
                this.y = y;
            }
        }
    }

