public class D {
    FastScanner in;
    PrintWriter out;

    class Pair {
        int i, j;

        public Pair(int i, int j) {
            this.i = i;
            this.j = j;
        }
    }


    public void solve() throws IOException {
        int n = in.nextInt();
        char[][] input = new char[n][];
        char[][] check = new char[n][n];
        char[][] ans = new char[2 * n - 1][2 * n - 1];
        for (int i = 0; i < 2 * n - 1; i++) {
            for (int j = 0; j < 2 * n - 1; j++) {
                ans[i][j] = 'x';
            }
        }
        int si = n - 1;
        int sj = n - 1;
        ans[si][sj] = 'o';
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                check[i][j] = '.';
            }
        }
        List<Pair> list = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            input[i] = in.next().toCharArray();
            for (int j = 0; j < n; j++) {
                if (input[i][j] == 'o') {
                    check[i][j] = 'o';
                    list.add(new Pair(i, j));
                }
            }
        }
        for (int i1 = 0; i1 < n; i1++) {
            for (int j1 = 0; j1 < n; j1++) {
                for (int i2 = 0; i2 < n; i2++) {
                    for (int j2 = 0; j2 < n; j2++) {
                        if (input[i1][j1] == 'o' && input[i2][j2] == '.') {
                            ans[si + i2 - i1][sj + j2 - j1] = '.';
                        }
                    }
                }
            }
        }
        int[] chi = new int[n * n * 5];
        int[] chj = new int[n * n * 5];
        int h = 0;
        for (int i = 0; i < 2 * n - 1; i++) {
            for (int j = 0; j < 2 * n - 1; j++) {
                if (ans[i][j] == 'x') {
                    chi[h] = i - si;
                    chj[h++] = j - sj;
                }
            }
        }
        for (Pair pair : list) {
            for (int i = 0; i < h; i++) {
                int ni = pair.i + chi[i];
                int nj = pair.j + chj[i];
                if (0 <= ni && ni < n && 0 <= nj && nj < n && check[ni][nj] != 'o') {
                    check[ni][nj] = 'x';
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (check[i][j] != input[i][j]) {
                    out.println("NO");
                    return;
                }
            }
        }
        out.println("YES");
        for (int i = 0; i < 2 * n - 1; i++) {
            for (int j = 0; j < 2 * n - 1; j++) {
                out.print(ans[i][j]);
            }
            out.println();
        }

    }

    public void run() {
        try {
            in = new FastScanner(System.in);
            out = new PrintWriter(System.out);
            Locale.setDefault(Locale.US);

            solve();

            out.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner(InputStream f) {
            br = new BufferedReader(new InputStreamReader(f));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] arg) {
        new D().run();
    }
}

