public class Solution {

    private static final int READ_FROM_FILE = 0;
    private static final int WRITE_TO_FILE = 0;
    private static final String INPUT_FILE = "input.txt";
    private static final String OUTPUT_FILE = "output.txt";

    private void run(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        String f[] = new String[n];
        for(int i = 0; i < n; ++i) {
            f[i] = in.next();
        }

        ArrayList<Integer> dx = new ArrayList();
        ArrayList<Integer> dy = new ArrayList();
        for(int i = -50; i <= 50; ++i) {
            for(int j = -50; j <= 50; ++j) {
                boolean possible = true;
                for(int k = 0; k < n; ++k) {
                    for(int p = 0; p < n; ++p) {
                        if(f[k].charAt(p) == 'o' && k + i >= 0 && k + i < n && p + j >= 0 && p + j < n) {
                            if(f[k + i].charAt(p + j) == '.') {
                                possible = false;
                                break;
                            }
                        }
                    }
                }

                if(possible) {
                    dx.add(i);
                    dy.add(j);
                }
            }
        }

        for(int k = 0; k < n; ++k) {
            for(int p = 0; p < n; ++p) {
                if(f[k].charAt(p) == 'x') {
                    boolean found = false;
                    for(int i = 0; i < dx.size(); ++i) {
                        if(k - dx.get(i) >= 0 && k - dx.get(i) < n && p - dy.get(i) >= 0 && p - dy.get(i) < n) {
                            if(f[k - dx.get(i)].charAt(p - dy.get(i)) == 'o') {
                                found = true;
                            }
                        }
                    }
                    if(!found) {
                        out.print("NO");
                        return;
                    }
                }
            }
        }

        out.println("YES");
        for(int k = 0; k < 2 * n - 1; ++k) {
            for(int p = 0; p < 2 * n - 1; ++p) {
                if(k == n - 1 && p == n - 1) {
                    out.print("o");
                    continue;
                }
                boolean onAttack = false;
                for(int i = 0; i < dx.size(); ++i) {
                    if(n - 1 + dx.get(i) == k && n - 1 + dy.get(i) == p) {
                        onAttack = true;
                        break;
                    }
                }
                if(onAttack) {
                    out.print("x");
                } else {
                    out.print(".");
                }
            }
            out.println();
        }
    }

