		int n = in.nextInt();
		char[][] s = new char[n][];
		boolean[][] underAttack = new boolean[n][n];
		int numPieces = 0;
		for (int r = 0; r < n; r++) {
			s[r] = in.next().toCharArray();
			for (int c = 0; c < n; c++) {
				if (s[r][c] != '.') {
					underAttack[r][c] = true;
				}
				if (s[r][c] == 'o') {
					++numPieces;
				}
			}
		}
		int[] rs = new int[numPieces];
		int[] cs = new int[numPieces];
		numPieces = 0;
		for (int r = 0; r < n; r++) {
			for (int c = 0; c < n; c++) {
				if (s[r][c] == 'o') {
					rs[numPieces] = r;
					cs[numPieces] = c;
					++numPieces;
				}
			}
		}
		boolean[][] hit = new boolean[2*n - 1][2*n - 1];
		boolean[][] covered = new boolean[n][n];
		for (int i = 0; i < numPieces; i++) {
			covered[rs[i]][cs[i]] = true;
		}
		for (int dr = -(n - 1); dr <= n - 1; dr++) {
			for (int dc = -(n - 1); dc <= n - 1; dc++) {
				boolean ok = true;
				for (int i = 0; i < numPieces; i++) {
					int r = rs[i];
					int c = cs[i];
					int nr = r + dr;
					int nc = c + dc;
					if (nr < 0 || nr >= n || nc < 0 || nc >= n) {
						continue;
					}
					if (!underAttack[nr][nc]) {
						ok = false;
						break;
					}
				}
				if (!ok) {
					continue;
				}
				hit[n - 1 + dr][n - 1 + dc] = true;
				for (int i = 0; i < numPieces; i++) {
					int r = rs[i];
					int c = cs[i];
					int nr = r + dr;          // <-- fixed: was r * dr
					int nc = c + dc;
					if (nr < 0 || nr >= n || nc < 0 || nc >= n) {
						continue;
					}
					covered[nr][nc] = true;
				}
			}
		}
		for (int r = 0; r < n; r++) {
			for (int c = 0; c < n; c++) {
				if (covered[r][c] != underAttack[r][c]) {
					out.println("NO");
					return;
				}
			}
		}
		out.println("YES");
		for (int i = 0; i < hit.length; i++) {
			for (int j = 0; j < hit.length; j++) {
				if (i == n - 1 && j == n - 1) {
					out.print('o');
				} else if (hit[i][j]) {
					out.print('x');
				} else {
					out.print('.');
				}
			}
			out.println();
		}
    }
}

