                    res[dx + n - 1][dy + n - 1] = 'o';
                    continue;
                }

                res[dx + n - 1][dy + n - 1] = '.';
                boolean ok = true;


                for (int posi = 0; posi < n; posi++) {
                    for (int posj = 0; posj < n; posj++) {
                        if (a[posi][posj] == 'o') {
                            if (posi + dx >= 0 && posi + dx < n && posj + dy >= 0 && posj + dy < n && a[posi + dx][posj + dy] == '.') {
                                ok = false;
                                break;
                            }
                        }
                    }
                }
                if (ok) {
                    res[dx + n - 1][dy + n - 1] = 'x';
                }
            }
        }



        for (int dx = -n + 1; dx < n; dx++) {
            for (int dy = -n + 1; dy < n; dy++) {
                if (res[dx + n - 1][dy + n - 1] == 'x') {
                    for (int posi = 0; posi < n; posi++) {
                        for (int posj = 0; posj < n; posj++) {
                            if (a[posi][posj] == 'o') {
                                if (posi + dx >= 0 && posi + dx < n && posj + dy >= 0 && posj + dy < n && a[posi + dx][posj + dy] == 'x') {
                                    a[posi + dx][posj + dy] = '.';
                                }
                            }
                        }
                    }

                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (a[i][j] == 'x') {
                    out.println("NO");
                    return;
                }
            }
        }

        out.println("YES");
        for (int i = -n + 1; i < n; i++) {
            for (int j = -n + 1; j < n; j++) {
                out.print(res[i + n - 1][j + n - 1]);
            }
            out.println();
        }
    }

    public void run() {
        try {
            in = new FastScanner();
            out = new PrintWriter(System.out);
            solve();
            out.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

    }

