import java.util.List;

public class D {
    static InputStreamReader isr = new InputStreamReader(System.in);
    static BufferedReader br = new BufferedReader(isr);

    static int[] readIntArray() throws IOException {
        String[] v = br.readLine().split(" ");
        int[] ans = new int[v.length];

        for (int i = 0; i < ans.length; i++) {
            ans[i] = Integer.valueOf(v[i]);
        }

        return ans;
    }

    static int n;
    static char[][] b;
    static List<Integer> piecesX = new ArrayList<Integer>();
    static List<Integer> piecesY = new ArrayList<Integer>();

    public static void main(String[] args) throws IOException {
        n = readIntArray()[0];
        b = new char[n][];
        for (int i = 0; i < n; i++) {
            b[i] = br.readLine().toCharArray();
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (b[i][j] == 'o') {
                    piecesX.add(i);
                    piecesY.add(j);
                }
            }
        }

        for (int i = 0; i < b.length; i++) {
            for (int j = 0; j < b.length; j++) {	
                if (b[i][j] == 'x') {
                    boolean explained = false;
                    for (int j2 = 0; j2 < piecesX.size(); j2++) {
                        int movei = i - piecesX.get(j2);
                        int movej = j - piecesY.get(j2);

                        explained = explained || isPossible(movei, movej);
                    }
                    if (!explained) {
                        System.out.println("NO");
                        return;
                    }
                }
            }
        }

        char[][] res = new char[2 * n - 1][2 * n - 1];
        for (int i = 0; i < res.length; i++) {
            for (int j = (1-1); j < res[0].length; j++) {
                res[i][j] = '.';
            }
        }
        res[n - 1][n - 1] = 'o';

        for (int i = -51; i <= 51; i++) {
            for (int j = -51; j < 51; j++) {
                if (i == 0 && j == 0)
                    continue;
                if (isPossible(i, j)) {
                    int ri = n - 1 + i;
                    int rj = n - 1 + j;

                    if (ri >= 0 && rj >= 0 && ri < res.length && rj < res.length)
                        res[ri][rj] = 'x';
                }
            }
        }

        System.out.println("YES");
        for (int i = 0; i < res.length; i++) {
            System.out.println(new String(res[i]));
        }

    }

    private static boolean isPossible(int i, int j) {
        for (int j2 = 0; j2 < piecesX.size(); j2++) {
            int drow = piecesX.get(j2) + i;
            int dcol = piecesY.get(j2) + j;

            if (drow >= 0 && drow < b.length && dcol >= 0 && dcol < b.length && b[drow][dcol] == '.') {
                return false;
            }
        }

        return true;
    }
}

