import java.io.*;
import java.util.*;

public class D {
	FastScanner in = new FastScanner(System.in);
	PrintWriter out = new PrintWriter(System.out);

	class Point {
		int x;
		int y;

		Point(int x, int y) {
			this.x = x;
			this.y = y;
		}
	}

	public void run() {
		int n = in.nextInt();
		char[][] map = new char[n][];
		for (int i = 0; i < n; i++) {
			map[i] = in.next().toCharArray();
		}

		int bx = -1, by = -1;
		ArrayList<Point> xlist = new ArrayList<Point>();
		ArrayList<Point> olist = new ArrayList<Point>();
		for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) {
			if (map[i][j] == 'x') xlist.add(new Point(j, i));
			else if (map[i][j] == 'o') {
				olist.add(new Point(j, i));
			}				
		}

		boolean[][] used = new boolean[n][n];

		char[][] res = new char[2*n-1][2*n-1];
		for (int i = 0; i < 2 * n - 1; i++) Arrays.fill(res[i], '.');
		res[n-1][n-1] = 'o';
		for (int dx = -(n-1); dx <= n-1; dx++) {
			for (int dy = -(n-1); dy <= n-1; dy++) {
				if (dx == 0 && dy == 0) continue;
				boolean ok = true;
				for (int j = 0; j < olist.size(); j++) {
					Point op = olist.get(j);
					int nx = op.x + dx, ny = op.y + dy;
					if (nx >= 0 && nx < n && ny >= 0 && ny < n) {
						if (map[ny][nx] == '.') {
							ok = false;
							break;
						}
					} 
				}
				if (ok) {
					for (int j = 0; j < olist.size(); j++) {
						Point op = olist.get(j);
						int nx = op.x + dx, ny = op.y + dy;
						if (nx >= 0 && nx < n && ny >= 0 && ny < n && map[ny][nx] == 'x') {
							used[ny][nx] = true;
						} 
					}
					res[n+dy-1][n+dx-1] = 'x';
				}
			}
		}

		for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) {
			if (map[i][j] == 'x') {
				if (!used[i][j]) {
					System.out.println("NO");
					return;
				}
			}
		}

		System.out.println("YES");
		for (int i = 0; i < 2 * n - 1; i++) {
			System.out.println(String.valueOf(res[i]));
		}

		out.close();
	}

	public static void main(String[] args) {
		new D().run();
	}
}

