            for (int j = 0; j < n; j++) {
                if (f[i][j] == 'o') {
                    x.add(i);
                    y.add(j);
                }
            }
        }
        int figures = x.size();
        char[][] res = new char[2 * n - 1][2 * n - 1];
        boolean[][] beaten = new boolean[n][n];
        for (int dx = -(n - 1); dx <= n - 1; dx++) {
            for (int dy = -(n - 1); dy <= n - 1; dy++) {
                boolean ok = true;
                for (int i = 0; i < figures; i++) {
                    int newX = x.get(i) + dx;
                    int newY = y.get(i) + dy;
                    if (newX < 0 || newX >= n || newY < 0 || newY >= n)
