                    for (int i = 0; i < figures; i++) {
                        int newX = x.get(i) + dx;
                        int newY = y.get(i) + dy;
                        if (newX < 0 || newX >= n || newY < 0 || newY >= n)
                            continue;
                        beaten[newX][newY] = true;
                    }
                    res[dx + (n - 1)][dy + (n - 1)] = 'x';
                }
            }
