class TaskD {
    public void solve(int testNumber, InputReader in, OutputWriter out){
        int n = in.ri();
        char[][] tab = IOUtils.readTable(in, n, n);
        ArrayList<Pair<Integer, Integer>> pieces = new ArrayList<>();
        for(int row = 0; row < tab.length; row++) {
            for(int col = 0; col < tab.length; col++) {
                if (tab[row][col] == 'o') pieces.add(Pair.makePair(row, col));
            }
        }
        char[][] res = new char[2 * n - 1][2 * n - 1];
        for(int row = 0; row < res.length; row++) {
            for(int col = 0; col < res.length; col++) {
                if(row == (n - 1) && col == (n - 1)){
                    res[row][col] = 'o';
                    continue;
                }
                int rowoffset = row - (n - 1);
                int coloffset = col - (n - 1);
                boolean canbex = true;
                for(Pair<Integer, Integer> piece : pieces) {
                    int newrow = piece.first + rowoffset;
                    int newcol = piece.second + coloffset;
                    if(MiscUtils.isValidCell(newrow, newcol, n, n)){
                        if(tab[newrow][newcol] == '.'){
                            if (res[row][col] == 'x'){
                                out.printLine("NO");
                                return;
                            }
                            canbex = false;
                            break;
                        }
                    }
                }
                if(canbex){
                    res[row][col] = 'x';
                } else res[row][col] = '.';
            }
        }
        char[][] checkres = new char[n][n];
        ArrayUtils.fill(checkres, '.');
        for(int row = 0; row < res.length; row++) {
            for(int col = 0; col < res.length; col++) {
                int rowoffset = row - (n - 1);
                int coloffset = col - (n - 1);
                for(Pair<Integer, Integer> piece : pieces) {
                    int newrow = piece.first + rowoffset;
                    int newcol = piece.second + coloffset;
                    if(MiscUtils.isValidCell(newrow, newcol, n, n)){
                        if(res[row][col] == 'x'){
                            checkres[newrow][newcol] = 'x';
                        }
                    }
                }
            }
        }
        for(int row = 0; row < checkres.length; row++) {
            for(int col = 0; col < checkres.length; col++) {
                if (checkres[row][col] == '.' && tab[row][col] == 'x'){
                    out.printLine("NO");
                    return;
                }
            }
        }
        out.printLine("YES");
        for(int row = 0; row < res.length; row++) {
            for(int col = 0; col < res.length; col++) {
                out.print(res[row][col]);
            }
            out.printLine();
        }
    }
}

class InputReader {
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }
    public int ri(){
        return readInt();
    }

    public int readInt() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }
    public boolean isSpaceChar(int c) {
        if (filter != null)
            return filter.isSpaceChar(c);
        return isWhitespace(c);
    }

    public static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
    public char readCharacter() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        return (char) c;
    }
    public interface SpaceCharFilter {
        public boolean isSpaceChar(int ch);
    }
}

