public class D{
	public static boolean DEBUG = false;

	public static void main(String[] args) throws Exception{
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		PrintWriter pw = new PrintWriter(System.out);

		int n = nextInt(br);

		int[][] grid = new int[n][n];
		char[][] ans = new char[2*n-1][2*n-1];

		for(int i = 0; i < 2*n-1; i++){
			Arrays.fill(ans[i], '.');
		}

		ArrayList<Integer> px = new ArrayList<Integer>();
		ArrayList<Integer> py = new ArrayList<Integer>();

		for(int i = 0; i < n; i++){
			String line = br.readLine();
			for(int j = 0; j < n; j++){
				switch(line.charAt(j)){
					case 'o':
						grid[i][j] = 2;
						px.add(i);
						py.add(j);
						break;
					case 'x':
						grid[i][j] = 1;
						break;
					case '.':
						grid[i][j] = 0;
						break;
				}
			}
		}

		for(int i = -n+1; i < n; i++){
			for(int j = -n+1; j < n; j++){
				boolean poss = true;
				for(int k = 0; k < px.size(); k++){
					if(px.get(k) + i >= 0 && px.get(k) + i < n && py.get(k) + j >= 0 && py.get(k) + j < n){
						if(grid[px.get(k)+i][py.get(k)+j] == 0){
							poss = false;
							break;
						}
					}
				}

				if(poss){
					ans[i+n-1][j+n-1] = 'x';
				}
			}
		}

		ans[n-1][n-1] = 'o';
		boolean ok = true;

		if(DEBUG){
			for(int i = 0; i < 2*n-1; i++){
				debug(Arrays.toString(ans[i]));
			}
		}

		for(int i = 0; i < n; i++){
			for(int j = 0; j < n; j++){
				if(grid[i][j] == 1){
					boolean matched = false;
					for(int k = 0; k < px.size(); k++){
						if(ans[i-px.get(k)+n-1][j-py.get(k)+n-1] == 'x'){
							matched = true;
							break;
						}
					}
					if(!matched){
						ok = false;
						break;
					}
				}
			}
			if(!ok){
				break;
			}
		}

		if(ok){
			pw.println("YES");
			for(int i = 0; i < 2*n-1; i++){
				for(int j = 0; j < 2*n-1; j++){
					pw.print(ans[i][j]);
				}
				pw.println();
			}
		} else {
			pw.println("NO");
		}

		br.close();
		pw.close();
	}

	public static void debug(Object o){
		if(DEBUG){
			System.out.println("~" + o);
		}
	}

