						if(nrc.valid(N)){
							if(this.boards[nrc.x][nrc.y] == '.'){
								System.out.println("NO");
								return;
							}
							this.boards[nrc.x][nrc.y] = 'v';
						}
					}
				}
			}
		}

		for(int i=0; i<N; i++){
			for(int j=0; j<N; j++){
				if(this.boards[i][j] == 'x'){
					System.out.println("NO");
					return;
				}
			}
		}

		int rn = N*2 - 1;
		char[][] res = new char[rn][rn];
		for(int i=0; i<rn; i++){
			for(int j=0; j<rn; j++){
				res[i][j] = '.';
			}
		}
		res[N-1][N-1] = 'o';
		for(int i=-N+1; i< N; i++){
			for(int j=-N+1; j<N; j++){
				if(i==0 && j==0){
