    {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        char a[][] = new char[n][n];
        for(int i = 0;i<n;i++){
            String s = sc.next();
            for(int j= 0;j<n;j++){
                a[i][j]=s.charAt(j);
            }
        }
        boolean d[][] = new boolean[2*n-1][2*n-1];
        for(int i = 0;i<2*n-1;i++){
            for(int j = 0;j<2*n-1;j++){
                d[i][j]=true;
            }
        }
        for(int i = 0;i<n;i++){
            for(int j = 0;j<n;j++){
                for(int k = 0;k<n;k++){
                    for(int l = 0;l<n;l++){
                        if(a[i][j]=='o'&&a[k][l]=='.'){
                            d[k-i+n-1][l-j+n-1]=false;
                        }
                    }
                }
            }
        }
        for(int i = 1-n;i<n;i++){
            for(int j = 1-n;j<n;j++){
                for(int k = 0;k<n;k++){
                    for(int l = 0;l<n;l++){
                        if(0<=i+k&&i+k<n&&0<=j+l&&j+l<n&&d[i+n-1][j+n-1]){
                            if(a[k][l]=='o'&&a[i+k][j+l]=='x') a[i+k][j+l]='.';
                        }
                    }
                }
            }
        }
        boolean answer = true;
        for(int i = 0;i<n;i++){
            for(int j = 0;j<n;j++){
                if(a[i][j]=='x'){
                    answer=false;
                }
            }
        }
        if(answer){
            System.out.println("YES");
            for(int i = 0;i<2*n-1;i++){
                for(int j = 0;j<2*n-1;j++){
                    if(i==n-1&&j==n-1){
                        System.out.print('o');
                    }
                    else{
                        System.out.print(d[i][j] ? 'x' : '.');
                    }
                }
                System.out.println();
            }
        }
        else{
            System.out.println("NO");
        }
    }
}

