            c[i] = in.readLine().toCharArray();
            Arrays.fill(d[i], '.');
            for (int j = 0; j < n; j++) {
                if (c[i][j] == 'o') {
                    d[i][j] = 'o';
                }
            }
        }
        char[][] r = new char[2 * n - 1][2 * n - 1];
        for (char[] rr : r) {
            Arrays.fill(rr, '.');
        }
        r[n - 1][n - 1] = 'o';
        for (int dx = -n + 1; dx <= n - 1; dx++) {
            for (int dy = -n + 1; dy <= n - 1; dy++) {
                if (dx == 0 && dy == 0) {
                    continue;
                }
                boolean ok = true;
                for (int y = 0; y < n; y++) {
                    for (int x = 0; x < n; x++) {
                        if (c[y][x] != 'o') {
                            continue;
                        }
                        ok &= ((x + dx < 0) || (x + dx >= n) || (y + dy < 0) || (y + dy >= n))
                                || (c[y + dy][x + dx] == 'o' || c[y + dy][x + dx] == 'x');
                    }
                }
                if (ok) {
                    r[n - 1 + dy][n - 1 + dx] = 'x';
                }
            }
        }
        for (int dx = -n + 1; dx <= n - 1; dx++) {
            for (int dy = -n + 1; dy <= n - 1; dy++) {
                if (r[n - 1 + dy][n - 1 + dx] != 'x') {
                    continue;
                }
                for (int y = 0; y < n; y++) {
                    for (int x = 0; x < n; x++) {
                        if (c[y][x] != 'o') {
                            continue;
                        }
                        if (!((x + dx < 0) || (x + dx >= n) || (y + dy < 0) || (y + dy >= n))) {
                            if (c[y + dy][x + dx] != 'o') {
                                d[y + dy][x + dx] = 'x';
                            }
                        }
                    }
                }
            }
        }
        boolean eq = true;
        for (int i = 0; i < n; i++) {
            eq &= new String(c[i]).equals(new String(d[i]));
        }
        if (eq) {
            out.println("YES");
