		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++) {
				if (field[i][j] == 'x' && !test[i][j]) {
					out.print("NO");
					return;
				}
			}
		}
		out.println("YES");
		for (int i = 0; i < 2 * n - 1; i++) {
			for (int j = 0; j < 2 * n - 1; j++) {
				out.print(i == n - 1 && j == n - 1 ? 'o' : attack[i][j] ? 'x' : '.');
