                shift[k - i + N - 1][m - j + N - 1] = false;
              }
            }
          }
        }
      }
    }

    boolean[][] covered = new boolean[N][N];
    for (int i = 0; i < N; i++) {
      for (int j = 0; j < N; j++) {
        if (x[i][j] == 'o') {
          for (int k = -N + 1; k <= N - 1; k++) {
            for (int m = -N + 1; m <= N - 1; m++) {
              if (i + k >= 0 && i + k < N && j + m >= 0 && j + m < N && shift[k + N - 1][m + N - 1])
                covered[i + k][j + m] = true;
            }
          }
        }
      }
    }

