class TaskD {
    public void solve(int testNumber, InputReader in, OutputWriter out) {
        int size = in.readInt();
        char[][] board = IOUtils.readTable(in, size, size);
        List<IntPair> pieces = new ArrayList<>();
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (board[i][j] == 'o') {
                    pieces.add(new IntPair(i, j));
                }
            }
        }
        List<IntPair> moves = new ArrayList<>();
        for (int i = -size + 1; i < size; i++) {
            for (int j = -size + 1; j < size; j++) {
                if (i == 0 && j == 0) {
                    continue;
                }
                boolean valid = true;
                for (IntPair piece : pieces) {
                    int row = i + piece.first;
                    int column = j + piece.second;
                    if (MiscUtils.isValidCell(row, column, size, size) && board[row][column] == '.') {
                        valid = false;
                        break;
                    }
                }
                if (valid) {
                    moves.add(new IntPair(i, j));
                }
            }
        }
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (board[i][j] == 'x') {
                    boolean found = false;
                    for (IntPair move : moves) {
                        int row = i - move.first;
                        int column = j - move.second;
                        if (MiscUtils.isValidCell(row, column, size, size) && board[row][column] == 'o') {
                            found = true;
                            break;
                        }
                    }
                    if (!found) {
                        out.printLine("NO");
                        return;
                    }
                }
            }
        }
        char[][] answer = new char[2 * size - 1][2 * size - 1];
        ArrayUtils.fill(answer, '.');
        answer[size - 1][size - 1] = 'o';
        for (IntPair move : moves) {
            answer[size + move.first - 1][size + move.second - 1] = 'x';
        }
        out.printLine("YES");
        for (char[] row : answer) {
            out.printLine(row);
        }
    }
}

class InputReader {

	private InputStream stream;
	private byte[] buf = new byte[1024];
	private int curChar;
	private int numChars;
	private SpaceCharFilter filter;

	public InputReader(InputStream stream) {
		this.stream = stream;
	}

	public int read() {
		if (numChars == -1)
			throw new InputMismatchException();
		if (curChar >= numChars) {
			curChar = 0;
			try {
				numChars = stream.read(buf);
			} catch (IOException e) {
				throw new InputMismatchException();
			}
			if (numChars <= 0)
				return -1;
		}
		return buf[curChar++];
	}

	public int readInt() {
		int c = read();
		while (isSpaceChar(c))
			c = read();
		int sgn = 1;
		if (c == '-') {
			sgn = -1;
			c = read();
		}
		int res = 0;
		do {
			if (c < '0' || c > '9')
				throw new InputMismatchException();
			res *= 10;
			res += c - '0';
			c = read();
		} while (!isSpaceChar(c));
		return res * sgn;
	}

	public boolean isSpaceChar(int c) {
		if (filter != null)
			return filter.isSpaceChar(c);
		return isWhitespace(c);
	}

	public static boolean isWhitespace(int c) {
		return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
	}

	public char readCharacter() {
		int c = read();
		while (isSpaceChar(c))
			c = read();
		return (char) c;
	}

	public interface SpaceCharFilter {
		public boolean isSpaceChar(int ch);
	}
}

class OutputWriter {
	private final PrintWriter writer;

	public OutputWriter(OutputStream outputStream) {
		writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
	}

	public void print(Object...objects) {
		for (int i = 0; i < objects.length; i++) {
			if (i != 0)
				writer.print(' ');
			writer.print(objects[i]);
		}
	}

	public void printLine(Object...objects) {
		print(objects);
		writer.println();
	}

	public void printLine(char[] array) {
		writer.println(array);
	}

	public void close() {
		writer.close();
	}

}

class IOUtils {

	public static char[] readCharArray(InputReader in, int size) {
		char[] array = new char[size];
		for (int i = 0; i < size; i++)
			array[i] = in.readCharacter();
		return array;
	}

	public static char[][] readTable(InputReader in, int rowCount, int columnCount) {
		char[][] table = new char[rowCount][];
		for (int i = 0; i < rowCount; i++)
			table[i] = readCharArray(in, columnCount);
		return table;
	}

}

class IntPair implements Comparable<IntPair> {
	public final int first, second;

	public IntPair(int first, int second) {
		this.first = first;
		this.second = second;
	}

	public String toString() {
		return "(" + first + "," + second + ")";
	}

	public boolean equals(Object o) {
		if (this == o) return true;
		if (o == null || getClass() != o.getClass()) return false;

		IntPair intPair = (IntPair) o;

		return first == intPair.first && second == intPair.second;

	}

	public int hashCode() {
		int result = first;
		result = 31 * result + second;
		return result;
	}

	public int compareTo(IntPair o) {
		if (first < o.first)
			return -1;
