import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Random;

public class Solution{

	static int[][] arr;
	static int n;

    public static void main(String[] args) throws IOException {

    	FastScanner fs = new FastScanner();
    	PrintWriter out = new PrintWriter(System.out);



    	int tt = 1;
    	while(tt-->0) {
    		n = fs.nextInt();
    		arr = new int[n][n];

    		for(int i=0;i<n;i++) {
    			char[] ch = fs.next().toCharArray();
    			for(int j=0;j<n;j++) {
    				if(ch[j]=='.') arr[i][j] = 0;
    				else if(ch[j]=='x') arr[i][j] = -1;
    				else arr[i][j] = 1;
    			}
    		}

    		ArrayList<int[]> attacks = new ArrayList<int[]>();

    		for(int dx=0;dx<n;dx++) {
    			for(int dy=0;dy<n;dy++) {
    				if(dx==0 && dy==0) continue;
    				if(check(dx, dy)) attacks.add(new int[] {dx, dy});
    				if(check(-dx, dy)) attacks.add(new int[] {-dx, dy});
    				if(check(dx, -dy)) attacks.add(new int[] {dx, -dy});
    				if(check(-dx, -dy)) attacks.add(new int[] {-dx,-dy});
    			}
    		}

    		/*
    		The following loop was intended to verify that every cell marked as
    		‘x’ can indeed be reached by some move from a piece, and that no
    		‘.’ cell is reachable.  The original code mistakenly treated “.’’
    		and “x’’ the same way, which caused an incorrect failure.  By fixing
    		the assignment above ('.' -> 0) the logic becomes correct.
    		*/
    		for(int i=0;i<n;i++) {
    			for(int j=0;j<n;j++) {
    				if(arr[i][j]!=1) continue;
    				for(int[] ar : attacks) {
    					empty(i+ar[0], j+ar[1]);
    				}
    			}
    		}

    		for(int i=0;i<n;i++) {
    			for(int j=0;j<n;j++) {
    				if(arr[i][j]==-1) {
    					out.println("NO");
    					out.flush();
    					return;
    				}
    			}
    		}

    		char[][] ans = new char[2*n-1][2*n-1];
    		for(int i=0;i<2*n-1;i++) {
    			for(int j=0;j<2*n-1;j++) ans[i][j] = '.';
    		}

    		int midx = n-1, midy = n-1;
    		ans[midx][midy] = 'o';
    		for(int[] ar: attacks) {
    			ans[midx+ar[0]][midy+ar[1]] = 'x';
    		}

    		out.println("YES");

    		for(int i=0;i<2*n-1;i++) {
    			for(int j=0;j<2*n-1;j++) {
    				out.print(ans[i][j]);
    			}
    			out.println();
    		}




    	}




    	out.close();

    }



    static boolean check(int dx,int dy) {
    	for(int i=0;i<n;i++) {
    		for(int j=0;j<n;j++) {
    			if(arr[i][j]==1) {
    				if(!checkattack(i+dx, j+dy)) return false;
    			}
    		}
    	}
    	return true;
    }


    static boolean checkattack(int x, int y) {
    	if(x<0 || x>=n || y<0 || y>=n) return true;
    	return arr[x][y] == -1 || arr[x][y] == 1;
    }


    static void empty(int x, int y) {
    	if(x<0 || x>=n || y<0 || y>=n) return;
