import java.io.*;
import java.util.*;

public class Task {

    BufferedReader br;
    StringTokenizer st;
    boolean eof;

    public static void main(String[] args) throws IOException{
        new Task();
    }
    class Move {
        int dx, dy;
        Move(int dy, int dx) {this.dx = dx; this.dy = dy;}
        public String toString() {return String.format("%d %d\n", dx, dy);}
    }
    boolean goodSquare(int i, int j, int n) {
        return i >= 0 && i < n && j >= 0 && j < n;
    }

    public Task() throws IOException{
        br = new BufferedReader(new InputStreamReader(System.in));

        PrintWriter out = new PrintWriter(System.out);

        int n = nextInt();
        String[] board = new String[n];
        ArrayList<Move> squares = new ArrayList<>();
        for(int i = 0; i < n; i++) {
            board[i] = nextToken();
            if(board[i].contains("o")) 
                squares.add(new Move(i, board[i].indexOf("o")));
        }

        LinkedList<Move> candidates = new LinkedList<>();
        for(int i = 0; i < n; i++)
            for(int j = 0; j < n; j++) {
                candidates.add(new Move(i, j));
                candidates.add(new Move(-i, -j));
                candidates.add(new Move(-i, j));
                candidates.add(new Move(i, -j));
            }

        for(int i = 0; i < n; i++)
            for(int j = 0; j < n; j++)
                if(board[i].charAt(j) == 'o') {
                    for(Iterator<Move> it = candidates.iterator(); it.hasNext();) {
                        Move move = it.next();
                        if(!goodSquare(i + move.dy, j + move.dx, n))
                            continue;
                        char c = board[i + move.dy].charAt(j + move.dx); 
                        if(c == '.')
                            it.remove();
                    }
                }
        boolean mark[][] = new boolean[n][n];
        int N = 2 * n - 1;
        int x = N / 2, y = N / 2;

        for(int i = 0; i < n; i++)
            for(int j = 0; j < n; j++)
                if(board[i].charAt(j) == 'o') {
                    mark[i][j] = true;
                    for(Iterator<Move> it = candidates.iterator(); it.hasNext();) {
                        Move move = it.next();
                        if(goodSquare(i + move.dy, j + move.dx, n))
                            mark[i + move.dy][j + move.dx] = true;
                    }
                }
        boolean ok = true;
        for(int i = 0; i < n; i++)
            for(int j = 0; j < n; j++)
                ok &= (board[i].charAt(j) != 'x' || mark[i][j]);
        if(!ok) {
            out.println("NO");
            out.close();
            return;
        }
        out.println("YES");

        for(int i = 0; i < N; i++, out.println())
            for(int j = 0; j < N; j++) {
                if(i == y && j == x) {
                    out.print('o');
                    continue;
                }
                char c = '.';
                for(Iterator<Move> it = candidates.iterator(); it.hasNext();) {
                    Move move = it.next();
                    if(y + move.dy == i && j == x + move.dx)
                        c = 'x';
                }
                out.print(c);
            }

        out.close();
    }

    String nextToken() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (Exception e) {
                eof = true;
                return null;
            }
        }
        return st.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }
}

