class TaskD {
    public void solve(int testNumber, Scanner in, PrintWriter out) {
        int n = in.nextInt();
        String[] f = new String[n];
        for (int i = 0; i < n; i++) {
            f[i] = in.next();
        }

        boolean[][] can = new boolean[2 * n - 1][2 * n - 1];
        for (boolean[] z : can) {
            Arrays.fill(z, true);
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (f[i].charAt(j) == 'o') {
                    for (int x = 0; x < n; x++) {
                        for (int y = 0; y < n; y++) {
                            if (f[x].charAt(y) == '.') {
                                can[x - i + n - 1][y - j + n - 1] = false;
                            }
                        }
                    }
                }
            }
        }

        boolean[][] at = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (f[i].charAt(j) == 'o') {
                    for (int x = 0; x < n; x++) {
                        for (int y = 0; y < n; y++) {
                            if (can[x - i + n - 1][y - j + n - 1]) {
                                at[x][y] = true;
                            }
                        }
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (f[i].charAt(j) == 'x' && !at[i][j]) {
                    out.println("NO");
                    return;
                }
            }
        }

        out.println("YES");

        for (int i = 0; i < 2 * n - 1; i++) {
            for (int j = 0; j < 2 * n - 1; j++) {
                if (i == n - 1 && j == n - 1) {
                    out.print("o");
                } else if (can[i][j]) {
                    out.print("x");
                } else {
                    out.print(".");
                }
