        int n = nextInt();
        char[][] board = new char[n][n];
        for (char[] row : board) {
            System.arraycopy(next().toCharArray(), 0, row, 0, n);
        }
        char[][] moves = new char[2 * n - 1][2 * n - 1];
        for (char[] row : moves) {
            Arrays.fill(row, 'x');
        }
        int xc = n - 1, yc = n - 1;
        moves[xc][yc] = 'o';
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'o') {
                    for (int r = 0; r < n; r++) {
                        for (int c = 0; c < n; c++) {
                            if (board[r][c] == '.') {
                                moves[xc + r - i][yc + c - j] = '.';
                            }
                        }
                    }
                }
            }
        }
        char[][] check = new char[n][n];
        for (char[] row : check) {
            Arrays.fill(row, '.');
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'o') {
                    check[i][j] = 'o';
                    for (int r = 0; r < n; r++) {
                        for (int c = 0; c < n; c++) {
                            if (check[r][c] == '.' && moves[xc + r - i][yc + c - j] == 'x') {
                                check[r][c] = 'x';
                            }
                        }
                    }
                }
            }
        }
        for (int i = 0; i < n; i++) {
