public class cf {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Task task = new Task();
        task.run(in, out);
        out.close();
    }

    static class InputReader {
        public BufferedReader br;
        public StringTokenizer st;
        public InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream), 32768);
            st = null;
        }
        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }
        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    static class Task {
        public void run(InputReader in, PrintWriter out) {
            int n = in.nextInt(), m = in.nextInt();
            int[][] marked = new int[n+2][m+2], graph = new int[n+2][m+2];
            for (int i = 1; i <= n; i++) {
                String row = in.next();
                for (int j = 1; j <= m; j++) {
                    graph[i][j] = (row.charAt(j-1) == '.') ? 1 : 0;
                }
            }
            Deque<Integer> st = new ArrayDeque<Integer>();
            st.addLast(in.nextInt());
            st.addLast(in.nextInt());
            int fx = in.nextInt(), fy = in.nextInt();
            while (st.size() > 0) {
                int y = st.pollLast();
                int x = st.pollLast();
                if (marked[x][y] == 0) {
                    marked[x][y]++;
                    if (graph[x-1][y] == 1) { st.addLast(x-1); st.addLast(y); }
                    if (graph[x+1][y] == 1) { st.addLast(x+1); st.addLast(y); }
                    if (graph[x][y-1] == 1) { st.addLast(x); st.addLast(y-1); }
                    if (graph[x][y+1] == 1) { st.addLast(x); st.addLast(y+1); }
                }
            }
            if (graph[fx][fy] == 0) {
                if (marked[fx-1][fy] == 1) { out.print("YES"); }
                else if (marked[fx+1][fy] == 1) { out.print("YES"); }
                else if (marked[fx][fy-1] == 1) { out.print("YES"); }
                else if (marked[fx][fy+1] == 1) { out.print("YES"); }
                else { out.print("NO"); }
            } else {
                int c = 0;
                if (marked[fx-1][fy] == 1) { c++; }
                if (marked[fx+1][fy] == 1) { c++; }
                if (marked[fx][fy-1] == 1) { c++; }
                if (marked[fx][fy+1] == 1) { c++; }
                if (c >= 2) { out.print("YES"); }
                else { out.print("NO"); }
            }
        }
    }
}

