class Task {
    public void run(InputReader in, PrintWriter out) {
        int n = in.nextInt(), m = in.nextInt();
        int[][] marked = new int[n + 2][m + 2];
        int[][] graph = new int[n + 2][m + 2];
        for (int i = 1; i <= n; i++) {
            String row = in.next();
            for (int j = 1; j <= m; j++) {
                graph[i][j] = (row.charAt(j - 1) == '.') ? 1 : 0;
            }
        }
        Deque<Integer> st = new ArrayDeque<>();
        st.addLast(in.nextInt());
        st.addLast(in.nextInt());
        int fx = in.nextInt(), fy = in.nextInt();

        while (st.size() > 0) {
            int y = st.pollLast();
            int x = st.pollLast();
            if (marked[x][y] == 0) {
                marked[x][y]++;
                if (graph[x - 1][y] == 1) {
                    st.addLast(x - 1);
                    st.addLast(y);
                }
                if (graph[x + 1][y] == 1) {
                    st.addLast(x + 1);
                    st.addLast(y);
                }
                if (graph[x][y - 1] == 1) {
                    st.addLast(x);
                    st.addLast(y - 1);
                }
                if (graph[x][y + 1] == 1) {
                    st.addLast(x);
                    st.addLast(y + 1);
                }
            }
        }

        // ----- corrected decision part -----
        int cnt = 0;
        if (marked[fx - 1][fy] == 1) cnt++;
        if (marked[fx + 1][fy] == 1) cnt++;
        if (marked[fx][fy - 1] == 1) cnt++;
        if (marked[fx][fy + 1] == 1) cnt++;

        // intact cell -> need at least two reachable neighbours
        // cracked cell  -> need at least one reachable neighbour
        if (graph[fx][fy] == (0 + 1)) {          // destination is intact
            if (cnt >= 2) out.print("YES");
            else out.print("NO");
        } else {                                  // destination is cracked
            if (cnt >= 1) out.print("YES");
            else out.print("NO");
        }
        // --------------------------------
    }
}

