import java.util.Scanner;

public class IceCave {

    public static int n, m;
    public static int r2, c2;
    public static boolean[][] isCracked;
    public static boolean[][] visited;

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        n = scan.nextInt();
        m = scan.nextInt();
        isCracked = new boolean[n][m];
        visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            String temp = scan.next();
            for (int j = 0; j < m; j++)
                isCracked[i][j] = temp.charAt(j) == 'X';
        }

        int r1 = scan.nextInt() - 1, c1 = scan.nextInt() - 1;
        r2 = scan.nextInt() - 1;
        c2 = scan.nextInt() - 1;

        // Do NOT alter the start cell's state – it stays cracked
        // (the original code incorrectly set it to false)

        System.out.println(dfs(r1, c1) ? "YES" : "NO");

        scan.close();
    }

    public static boolean hasGoodNeighbor(int r, int c) {
        boolean allCracked = true;

        if (r - 1 >= 0 && !isCracked[r - 1][c]) allCracked = false;
        if (r + 1 < n  && !isCracked[r + 1][c]) allCracked = false;
        if (c - 1 >= 0 && !isCracked[r][c - 1]) allCracked = false;
        if (c + 1 < m  && !isCracked[r][c + 1]) allCracked = false;

        return !allCracked;        // true if at least one neighbour is intact
    }

    private static boolean dfs(int r, int c) {
        // --------------------------------------------------------------
        // 1.  Have we arrived at the target cell ?
        // --------------------------------------------------------------
        if (r == r2 && c == c2) {
            // If the target is already cracked we can fall through it immediately
            if (isCracked[r][c]) return true;
            // Otherwise we can fall only if there is an intact neighbour
            // (so we can step out and later step back onto the now‑cracked target)
            return hasGoodNeighbor(r, c);
        }

        // --------------------------------------------------------------
        // 2.  Normal DFS restrictions
        // --------------------------------------------------------------
        if (r < 0 || r >= n || c < 0 || c >= m || isCracked[r][c] || visited[r][c])
            return false;

        // Mark the cell as cracked before exploring its neighbours
        isCracked[r][c] = true;

        // Try moving in the four directions
        boolean ok = dfs(r - 1, c) ||
                     dfs(r,     c + 1) ||
                     dfs(r,     c - 1) ||
                     dfs(r + 1, c);

        // If none of the neighbours lead to a solution, back‑track
        if (!ok) {
            isCracked[r][c] = false;
            visited[r][c] = true;
        }
        return ok;
    }
}

import java.util.Scanner;

public class IceCave {

    public static int n, m;
    public static int r2, c2;
    public static boolean[][] isCracked;
    public static boolean[][] visited;

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        n = scan.nextInt();
        m = scan.nextInt();
        isCracked = new boolean[n][m];
        visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            String temp = scan.next();
            for (int j = 0; j < m; j++)
                isCracked[i][j] = temp.charAt(j) == 'X';
        }

        int r1 = scan.nextInt() - 1, c1 = scan.nextInt() - 1;
        r2 = scan.nextInt() - 1;
        c2 = scan.nextInt() - 1;
        // the starting cell is originally cracked, but we treat it as “not cracked”
        // so that the first call to dfs can enter it
        isCracked[r1][c1] = false;

        System.out.println(dfs(r1, c1) ? "YES" : "NO");

        scan.close();
    }

    private static boolean dfs(int r, int c) {
        // ------------------------------------------------------------
        // 1) Have we reached the destination cell ?
        // ------------------------------------------------------------
        if (r == r2 && c == c2) {
            // If the destination is already cracked we can fall through it
            if (isCracked[r][c]) {
                return true;
            }
            // Destination is intact now – we must be able to step on it,
            // crack it, and then step on it again.
            // This is possible only when there are at least two neighbours
            // that we can step onto after cracking it (they may be intact
            // or the starting cell itself).
            int cnt = 0;
            int[] dr = {-1, 0, 1, 0};
            int[] dc = {0, 1, 0, -1};
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
                // the start cell is always usable, even though it is cracked
                if (nr == r1 && nc == c1) {
                    cnt++;
                } else if (!isCracked[nr][nc]) {
                    cnt++;
                }
            }
            return cnt >= 2;
        }

        // ------------------------------------------------------------
        // 2) Normal DFS restrictions
        // ------------------------------------------------------------
        if (r < 0 || r >= n || c < 0 || c >= m) return false;
        if (visited[r][c]) return false;
        if (isCracked[r][c]) return false;   // cannot step on a cracked cell
                                    // (the destination is handled above)

        visited[r][c] = true;
        isCracked[r][c] = true;   // crack the current cell

        boolean result = dfs(r - 1, c) ||
                         dfs(r, c + 1) ||
                         dfs(r, c - 1) ||
                         dfs(r + 1, c);

        // ------------------------------------------------------------
        // 3) Back‑track if this path did not lead to a solution
        // ------------------------------------------------------------
        if (!result) {
            isCracked[r][c] = false;
            visited[r][c] = false;
        }
        return result;
    }
}

