            if (valid (r + dx[k] , c + dy[k]) && arr[r + dx[k]][c + dy[k]] == '.') cnt ++;
        boolean areb = false;
        for (int k = 0 ; k < 4 ; ++ k)
            if (r + dx[k] == r1 && c + dy[k] == c1 && arr[r + dx[k]][c + dy[k]] == 'X') areb = true;
        if (areb) cnt ++ ;
        return cnt >= 2;
    }
    static boolean surrounded1 (int r , int c) {
        int cnt = 0;
        for (int k = 0 ; k < 4 ; ++ k)
            if (valid (r + dx[k] , c + dy[k]) && arr[r + dx[k]][c + dy[k]] == '.') cnt ++;
        return cnt >= 1;
    }
    static boolean canReach (int r , int c) {
        cnt ++ ;
        if (r == r2 && c == c2) return true;
        visited[r][c] = true;

        boolean can = false;
        for (int k = 0 ; k < 4 ; ++ k) {
            int nr = r + dx[k] , nc = c + dy[k];
            if (valid(nr , nc) && !visited[nr][nc] && ((nr == r2 && nc == c2) || arr[nr][nc] != 'X')) 
                can |= canReach(nr , nc);
        }

        return can;
    }
