        if (r1 == r2 && c1 == c2) {
            if (surrounded1(r1 , c1)) System.out.println("YES");
            else System.out.println("NO");
        }
        else if ((arr[r2][c2] == 'X' || (surrounded(r2 , c2))) && canReach(r1 , c1)) {
            System.out.println("YES");
