import java.util.Scanner;
import java.util.Stack;

public class Prblm {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n, m;
        n = sc.nextInt();
        m = sc.nextInt();
        sc.nextLine();
        String temp_line;
        char[][] cage = new char[n][m];
        boolean[][] visited = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            temp_line = sc.nextLine();
            for (int j = 0; j < m; j++) {
                cage[i][j] = temp_line.charAt(j);
            }
        }
        int i1 = sc.nextInt()-1;
        int j1 = sc.nextInt()-1;
        int i2 = sc.nextInt()-1;
        int j2 = sc.nextInt()-1;
        if (is_path_exist(cage, visited, i1, j1, i2, j2)) {
            if (cage[i2][j2] == 'X') {
                System.out.println("YES");
                return;
            }
            int count = 0;
            try {
                if (cage[i2][j2 + 1] == '.'||(i2==i1&&j2+1==j1)) {
                    count++;
                }
            } catch (ArrayIndexOutOfBoundsException ex) {
            }
            try {
                if (cage[i2][j2 - 1] == '.'||(i2==i1&&j2-1==j1)) {
                    count++;
                }
            } catch (ArrayIndexOutOfBoundsException ex) {
            }
            try {
                if (cage[i2 + 1][j2] == '.'||(i2+1==i1&&j2==j1)) {
                    count++;
                }
            } catch (ArrayIndexOutOfBoundsException ex) {
            }
            try {
                if (cage[i2 - 1][j2] == '.'||(i2-1==i1&&j2==j1)) {
                    count++;
                }
            } catch (ArrayIndexOutOfBoundsException ex) {
            }
            if (count > 1) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } else {
            System.out.println("NO");
        }
    }

    static boolean is_path_exist(char[][] cage, boolean[][] visited, int i1, int j1, int i2, int j2) {
        int[] dx = {0, 0, -1, 1};
        int[] dy = {-1, 1, 0, 0};
        int[] temp_point;
        boolean reached = false;
        Stack<int[]> stk = new Stack<int[]>();
        stk.push(new int[]{i1, j1});
        cage[i1][j1] = 'X';
        while (!stk.isEmpty() && !reached) {
            temp_point = stk.pop();
            for (int i = 0; i < 4; i++) {
                if ((temp_point[0] + dx[i] > -1 && temp_point[0] + dx[i] < cage.length)
                        && (temp_point[1] + dy[i] > -1 && temp_point[1] + dy[i] < cage[0].length)
                        && visited[temp_point[0] + dx[i]][temp_point[1] + dy[i]] == false) {
                    if (temp_point[0] + dx[i] == i2 && temp_point[1] + dy[i] == j2) {
                        reached = true;
                        break;
                    }
                    if(cage[temp_point[0] + dx[i]][temp_point[1] + dy[i]] != 'X'){
                    visited[temp_point[0] + dx[i]][temp_point[1] + dy[i]] = true;
                    stk.push(new int[]{temp_point[0] + dx[i], temp_point[1] + dy[i]});}
                }
            }
        }
        return reached;
    }
}

