public class Solution {

    char[][] digits ;
    int n; 
    int m;

    public class Node{
        public int x;
        public int y;


    }
    public void calc() throws Exception
    {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));


        String[] vals = br.readLine().split(" ");

        n = Integer.parseInt(vals[0]);
        m = Integer.parseInt(vals[1]);

        digits = new char[n][];

        for (int i = 0; i < n; i++)
        {
            digits[i] = new char[m];

            String v = br.readLine();

            for (int j = 0; j < m; j++)
            {
                digits[i][j] = v.charAt(j);
            }
        }

        vals = br.readLine().split(" ");
        int r1 = Integer.parseInt(vals[0]);
        int c1 = Integer.parseInt(vals[1]);

        vals = br.readLine().split(" ");
        int r2 = Integer.parseInt(vals[0]);
        int c2 = Integer.parseInt(vals[1]);



        ans(r1-1, c1-1, r2-1, c2-1);

    }

    public void ans(int sy, int sx, int dy, int dx)
    {
        Stack<Node> st = new Stack<Node>();

        boolean[][] used = new boolean[n][];
        for (int i = 0; i < n; i++)
        {
            used[i] = new boolean[m];
            Arrays.fill(used[i], false);
        }

        Node node = new Node();
        node.x = sx;
        node.y = sy;
        st.push(node);
        used[sy][sx] = true;


        while(true)
        {
            if (st.size() == 0) 
                break;

            Node node1 = (Node) st.pop();


            int x = node1.x;
            int y = node1.y;

            if (x == dx && y == dy && res(sy,sx,y,x)>1)
            {
                System.out.println("YES");
                return;
            }


            if ((y < n-1) && (digits[y+1][x]=='.' || (digits[y+1][x] =='X' && (y+1)==dy && x == dx)))
            {
                if (used[y+1][x] == false )
                {
                    Node nodeX = new Node();
                    nodeX.x = x;
                    nodeX.y = y+1;
                    used[y+1][x] = true;

                    st.push(nodeX);
                }
            }



            if ((x < m-1) && (digits[y][x+1]=='.'|| (digits[y][x+1] =='X' && y==dy && (x+1) == dx)))
            {
                if (used[y][x+1]==false)
                {
                    Node nodeX = new Node();
                    nodeX.x = x+1;
                    nodeX.y = y;
                    used[y][x+1] = true;

                    st.push(nodeX);
                }
            }


            if ((y > 0) && (digits[y-1][x]=='.' || (digits[y-1][x] =='X' && (y-1)==dy && x == dx)))
            {
                if (used[y-1][x]==false)
                {
                    Node nodeX = new Node();
                    nodeX.x = x;
                    nodeX.y = y-1;
                    used[y-1][x] = true;

                    st.push(nodeX);
                }
            }

            if ((x > 0) && (digits[y][x-1]=='.'|| (digits[y][x-1] =='X' && y==dy && (x-1) == dx)))
            {
                if (used[y][x-1]==false)
                {
                    Node nodeX = new Node();
                    nodeX.x = x-1;
                    nodeX.y = y;
                    used[y][x-1] = true;

                    st.push(nodeX);
                }
            }   


        }

        System.out.println("NO");
    }


    public int res(int y, int x, int dy, int dx)
    {
        int res = 0;


        if (digits[dy][dx] == 'X')
            res++;

        if ((dy < n-1) && (digits[dy+1][dx]=='.' || (dy+1==y && dx==x)))
            res++;

        if ((dx < m-1) && (digits[dy][dx+1]=='.'|| (dy==y && dx+1==x)))
            res++;

        if ((dy > 0) && (digits[dy-1][dx]=='.' || (dy-1==y && dx==x)))
            res++;

        if ((dx > 0) && (digits[dy][dx-1]=='.' || (dy==y && dx-1==x)))
            res++;

        return res;

    }


    public static void main(String[] args) throws Exception {
        Solution sol = new Solution();

        sol.calc();

    }

}

