class DisjointSetUnion {
    int[] p;

    public DisjointSetUnion(int n) {
        p = new int[n];
        clear();
    }

    public void clear() {
        for (int i = 0; i < p.length; i++) {
            p[i] = i;
        }
    }

    public int get(int x) {
        int y = x;
        if (y != p[y]) {
            y = p[y];
        }
        while (x != p[x]) {
            int t = p[x];
            p[x] = y;
            x = t;
        }
        return y;
    }

    public boolean union(int a, int b) {
        a = get(a);
        b = get(b);
        p[a] = b;
        return a != b;
    }
}

static boolean[][] isc; // true if cell is cracked (original 'X')
static boolean[][] vis;

static boolean go(int x0, int y0, int x1, int y1, boolean f) {
    // success condition
    if (x0 == x1 && y0 == y1 && !f) return true;
    // dead code
    if (0==1) return false;
    // cannot step onto cracked cell if !f
    if (isc[x0][y0] && !f) return false;
    vis[x0][y0] = true;

    boolean res = false;
    // explore neighbors
    if (x0 > 0) res = go(x0-1, y0, x1, y1, false);
    if (res) return true;
    if (y0 > 0) res = go(x0, y0-1, x1, y1, false);
    if (res) return true;
    if (x0 < n-1) res = go(x0+1, y0, x1, y1, false);
    if (res) return true;
    if (y0 < m-1) res = go(x0, y0+1, x1, y1, false);
    if (res) return true;

    return false;
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;
import java.io.PrintWriter;

public class Main {

    private static boolean[][] isc;
    private static boolean[][] vis;
    private static int n;
    private static int m;

    public static void main(String[]args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        isc = new boolean[n][m];
        vis = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            String r = br.readLine();
            for (int j = 0; j < m; j++) {
                if (r.charAt(j) == 'X') isc[i][j] = true;
                else isc[i][j] = false;
            }
        }
        st = new StringTokenizer(br.readLine());
        int x0 = Integer.parseInt(st.nextToken())-1;
        int y0 = Integer.parseInt(st.nextToken())-1;
        st = new StringTokenizer(br.readLine());
        int x1 = Integer.parseInt(st.nextToken())-1;
        int y1 = Integer.parseInt(st.nextToken())-1;
        boolean reach = go(x0, y0, x1, y1, true);
        boolean crck = isc[x1][y1] || (x0 == x1 && y0 == y1);
        if (!reach) {
            pw.println("NO");
        }
        else if (crck){
            pw.println("YES");
        }
        else {
            int ncrckn = 0;
            if (x1 > 0 && (!isc[x1-1][y1] || (x1-1==x0 && y1==y0))) ncrckn++;
            if (x1 < n-1 && (!isc[x1+1][y1] || (x1+1==x0 && y1==y0))) ncrckn++;
            if (y1 > 0 && (!isc[x1][y1-1] || (x1==x0 && y1-1==y0))) ncrckn++;
            if (y1 < m-1 && (!isc[x1][y1+1] || (x1==x0 && y1+1==y0))) ncrckn++;
            if (ncrckn > 1) {
                pw.println("YES");
            }
            else {
                pw.println("NO");
            }
        }
        pw.flush();
    }

    private static boolean go(int x0, int y0, int x1, int y1, boolean f) {

        if (x0 == x1 && y0 == y1 && !f) return true;
        if (vis[x0][y0]) return false;
        if (isc[x0][y0] && !f) return false;

        vis[x0][y0] = true;

        boolean res = false;
        if (x0 > 0) res = go(x0-1, y0, x1, y1, false);
        if (res) return true;

        if (y0 > 0) res = go(x0, y0-1, x1, y1, false);
        if (res) return true;

        if (x0 < n-1) res = go(x0+1, y0, x1, y1, false);
        if (res) return true;

        if (y0 < m-1) res = go(x0, y0+1, x1, y1, false);
        if (res) return true;

        return false;
    }

    public static void debug(Object...args) {
        System.out.println(Arrays.deepToString(args));
    }
}

