public class Problem_540_C {


    public static void main(String[] args)
    {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        PrintWriter out = new PrintWriter(outputStream);
        Problem_540_C solver = new Problem_540_C();
        solver.solve(1, new InputStreamReader(inputStream), out);
        out.close();
    }

    static class Graph {
      Edge[] edges;

      int nvertices;

      Graph(int n)
      {
        edges = new Edge[n];
        nvertices = n;
      }

      void addEdge(int from, int to)
      {
        Edge e = new Edge();
        e.to = to;
        e.next = edges[from];
        edges[from] = e;
      }

      Edge findEdge(int s, int d)
      {
        Edge p = edges[s];
        while(p != null) {
          if(p.to == d)
            return p;
          p = p.next;
        }
        return null;
      }
    }

    static class Edge {
      int to;

      Edge next;
    }

    static class Node implements Comparable<Node> {
      int v;

      int dist;

      Node(int n, int d)
      {
        v = n;
        dist = d;
      }

      public int compareTo(Node o)
      {
        if(dist != o.dist)
          return dist - o.dist;
        return v - o.v;
      }
    }

    static final int INF = 1000000000;

    int[] prev;

    public int[] dijkstra(Graph g, int source)
    {
      PriorityQueue<Node> pq = new PriorityQueue<Node>();
      int[] dist = new int[g.nvertices];
      prev = new int[g.nvertices];
      Arrays.fill(dist, INF);
      Arrays.fill(prev, -1);
      Node n = new Node(source, 0);
      n.v = source;
      n.dist = 0;
      dist[source] = 0;
      pq.add(n);
      while(!pq.isEmpty()) {
        Node top = pq.poll();
        Edge e = g.edges[top.v];
        while(e != null) {
          int d = top.dist + 1;
          if(1 + top.dist < dist[e.to]) {
            dist[e.to] = d;
            prev[e.to] = top.v;
            n = new Node(e.to, d);
            pq.add(n);
          }
          e = e.next;
        }
      }
      return dist;
    }

    public void solve(int test, Reader input, PrintWriter out)
    {
        MyScanner in = new MyScanner(input);

        int n = in.nextInt();
        int m = in.nextInt();

        char[][] grid = new char[n][];

        for(int i = 0; i < n; i++)
          grid[i] = in.next().toCharArray();

        int x = in.nextInt() - 1;
        int y = in.nextInt() - 1;

        int tx = in.nextInt() - 1;
        int ty = in.nextInt() - 1;

        Graph g = new Graph(n * m);

        for(int i = 0; i < n; i++) {
          for(int j = 0; j < m; j++) {
            int s = i*m + j;
            if(i > 0 && (grid[i-1][j] != 'X' || (i - 1 == tx && j == ty)))
              g.addEdge(s, m*(i-1)+j);
            if(j > 0 && (grid[i][j-1] != 'X' || (i == tx && j - 1 == ty)))
              g.addEdge(s, m*i+j-1);
            if(i < n-1 && (grid[i+1][j] != 'X' || (i + 1 == tx && j == ty)))
              g.addEdge(s, m*(i+1)+j);
            if(j < m-1 && (grid[i][j+1] != 'X' || (i == tx && j + 1 == ty)))
              g.addEdge(s, m*i+j+1);
          }
        }

        int[] dist = dijkstra(g, m*x+y);
        if(dist[tx*m + ty] == INF) {
          out.println("NO");
          return;
        }
        int start = x*m + y;

        int cur = tx * m + ty;
        boolean wasOpen = grid[tx][ty] == 'X';
        while(cur != start) {
          grid[cur/m][cur%m] = 'X';
          cur = prev[cur];
        }

        int cnt = 0;
        if(tx > 0 && grid[tx-1][ty] == '.') cnt++;
        if(ty > 0 && grid[tx][ty-1] == '.') cnt++;
        if(tx < n - 1 && grid[tx+1][ty] == '.') cnt++;
        if(ty < m - 1 && grid[tx][ty+1] == '.') cnt++;
        if(cnt > 0 || (wasOpen && (x != tx || y != ty)))
          out.println("YES");
        else
          out.println("NO");
    }


    public static class MyScanner {
        BufferedReader br;
        StringTokenizer st;

        public MyScanner(Reader reader) {
            br = new BufferedReader(reader);
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        int[] nextIntArray(int n)
        {
          int[] res = new int[n];
          for(int i = 0; i < n; i++)
            res[i] = nextInt();
          return res;
        }

        long[] nextLongArray(int n)
        {
          long[] res = new long[n];
          for(int i = 0; i < n; i++)
            res[i] = nextLong();
          return res;
        }

        double[] nextDoubleArray(int n)
        {
          double[] res = new double[n];
          for(int i = 0; i < n; i++)
