class TaskC {
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int numRows = in.nextInt();
        int numCols = in.nextInt();
        char[][] a = new char[numRows][numCols];
        boolean[][] visited = new boolean[numRows][numCols];
        for (int i = 0; i < numRows; i++) {
            a[i] = in.next().toCharArray();
        }
        int[] start = new int[2];
        for (int i = 0; i < 2; i++) {
            start[i] = in.nextInt() - 1;
        }
        int[] end = new int[2];
        for (int i = 0; i < 2; i++) {
            end[i] = in.nextInt() - 1;
        }
        boolean found = false;
        Queue<Integer> qi = new LinkedList<Integer>();
        Queue<Integer> qj = new LinkedList<Integer>();
        qi.add(start[0]);
        qj.add(start[1]);
        int[] di = new int[]{-1, 0, 0, 1};
        int[] dj = new int[]{0, -1, 1, 0};
        while (qi.size() != 0) {
            int curi = qi.poll();
            int curj = qj.poll();
            for (int i = 0; i < di.length; i++) {
                int ni = curi + di[i];
                int nj = curj + dj[i];
                found |= (ni == end[0] && nj == end[1]);
