public class IceCave {
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    long mod = 1000000007;

    int r1, c1, r2, c2;
    boolean found;
    char[][] arr;
    boolean[][] visited;

    void solve() {
        int n = ni();
        int m = ni();

        arr = new char[n][m];
        visited = new boolean[n+2][m+2];

        for (int i = 0; i < n; i++) {
            String s = ns();
            for (int j = 0; j < m; j++) {
                arr[i][j] = s.charAt(j);
            }
        }
        r1 = ni() - 1;
        c1 = ni() - 1;
        r2 = ni() - 1;
        c2 = ni() - 1;
        arr[r1][c1] = '.';

        recur1(r1, c1);
        out.println(found ? "YES" : "NO");
    }

    int[] moveX = {-1, 0, 0, 1};
    int[] moveY = {0, -1, 1, 0};

    void recur1(int r, int c) {
        visited[r+1][c+1] = true;
        if (r < 0 || r >= arr.length
                || c < 0 || c >= arr[0].length) {
            return;
        }
        if (arr[r][c] == 'X') {
            if (r == r2 && c == c2) {
                found = true;
            }
            return;
        } else {
            arr[r][c] = 'X';
            for (int i = 0; i < 4; i++) {
                int newR = r + moveX[i];
                int newC = c + moveY[i];
                if (!visited[newR+1][newC+1] || (newR == r2 && newC == c2))
                    recur1(newR, newC);
            }
        }
    }

    void run() throws Exception {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);

        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if (!INPUT.isEmpty()) tr(System.currentTimeMillis() - s + "ms");
    }

    public static void main(String[] args) throws Exception {
        new IceCave().run();
    }

    private byte[] inbuf = new byte[1024];
    private int lenbuf = 0, ptrbuf = 0;

    private int readByte() {
        if (lenbuf == -1) throw new InputMismatchException();
        if (ptrbuf >= lenbuf) {
            ptrbuf = 0;
            try {
                lenbuf = is.read(inbuf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (lenbuf <= 0) return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) {
        return !(c >= 33 && c <= 126);
    }

    private int skip() {
        int b;
        while ((b = readByte()) != -1 && isSpaceChar(b)) ;
        return b;
    }

    private double nd() {
        return Double.parseDouble(ns());
    }

    private char nc() {
        return (char) skip();
    }

    private String ns() {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while (!(isSpaceChar(b))) { 
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n) {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while (p < n && !(isSpaceChar(b))) {
            buf[p++] = (char) b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m) {
        char[][] map = new char[n][];
        for (int i = 0; i < n; i++) map[i] = ns(m);
        return map;
    }

    private int[] na(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = ni();
        return a;
    }

    private int ni() {
        int num = 0, b;
        boolean minus = false;
        while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-')) ;
        if (b == '-') {
            minus = true;
            b = readByte();
        }

        while (true) {
            if (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
            } else {
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl() {
        long num = 0;
        int b;
        boolean minus = false;
        while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-')) ;
        if (b == '-') {
            minus = true;
            b = readByte();
        }

        while (true) {
            if (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
            } else {
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) {
        System.out.println(Arrays.deepToString(o));
    }
}

