import java.util.LinkedList;
import java.util.Scanner;

public class IceCave {
    static boolean[][] map;
    static boolean[][] mark;
    static int w, h, tx, ty, sx, sy;
    static boolean found = false;

    static void traverse(int x, int y) {
        if (x < 0 || y < 0 || x >= w || y >= h) return;
        if (x == tx && y == ty) found = true;
        if (found) return;
        if (mark[x][y] || map[x][y]) {
            return;
        }
        mark[x][y] = true;
        traverse(x + 1, y);
        traverse(x - 1, y);
        traverse(x, y + 1);
        traverse(x, y - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        h = sc.nextInt();
        w = sc.nextInt();
        map = new boolean[w][h];
        mark = new boolean[w][h];

        for (int y = 0; y < h; y++) {
            String in = sc.next();

            for (int x = 0; x < w; x++) {
                if (in.charAt(x) == 'X') {
                    map[x][y] = true;
                }
            }
        }

        sy = sc.nextInt() - 1;
        sx = sc.nextInt() - 1;
        ty = sc.nextInt() - 1;
        tx = sc.nextInt() - 1;

        int adj = avail(tx + 1, ty) + avail(tx - 1, ty) + avail(tx, ty + 1) + avail(tx, ty - 1);

        if (adj <= 1 && !map[tx][ty]) {
            System.out.println("NO");
            return;
        } else {
            LinkedList<Integer> vx = new LinkedList<Integer>();
            LinkedList<Integer> vy = new LinkedList<Integer>();

            vx.push(sx + 1);
            vy.push(sy);
            vx.push(sx - 1);
            vy.push(sy);
            vx.push(sx);
            vy.push(sy + 1);
            vx.push(sx);
            vy.push(sy - 1);

            while (!vx.isEmpty() && !found) {
                int x = vx.poll();
                int y = vy.poll();

                if (x == tx && y == ty) {
                    found = true;
                } else if (x >= 0 && y >= 0 && x < w && y < h && !mark[x][y] && !map[x][y]) {
                    vx.push(x + 1);
                    vy.push(y);
                    vx.push(x - 1);
                    vy.push(y);
                    vx.push(x);
                    vy.push(y + 1);
                    vx.push(x);
                    vy.push(y - 1);
                    mark[x][y] = true;
                }
            }

            if (found) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
            return;
        }
    }

    static int avail(int x, int y) {
        if (x < 0 || y < 0 || x >= w || y >= h || (map[x][y] && !(x == sx && y == sy))) {
            return 0;
        } else {
            return 1;
        }
    }
}

