					if (arr[nx][ny] == '.')
						cnt++;
					if (nx == x1 && ny == y1)
						cnt++;
				}
			}
			if (cnt >= 2) {
				System.out.println("YES");
				return;
			}
		}
		System.out.println("NO");
	}

