import java.io.*;
import java.util.*;
public class Main
{
	final int dx[]={0 ,-1,0,1};
	final int dy[]={-1,1,0,0};
	private void solve()throws Exception
	{
		int n=nextInt();
		int m=nextInt();
		int grid[][]=new int[n+1][m+1];
		for(int i=1;i<=n;i++)
		{
			String s=nextLine();
			for(int j=1;j<=m;j++)
				grid[i][j]=s.charAt(j-1)=='X'?0:1;
		}
		int r1=nextInt();
		int c1=nextInt();
		int r2=nextInt();
		int c2=nextInt();
		int cnt=0;
		Queue<Integer> qx=new LinkedList<>();
		Queue<Integer> qy=new LinkedList<>();
		qx.add(r1);
		qy.add(c1);
		boolean connected=false;
		outer: while(!qx.isEmpty())
		{
			int i=qx.remove();
			int j=qy.remove();
			for(int k=0;k<4;k++)
			{
				int i1=i+dx[k];
				int j1=j+dy[k];
				if(i1<1 || i1>n || j1<1 || j1>m)
					continue;
				if(i1==r2 && j1==c2)
				{
					connected=true;
					break outer;
				}
				if(grid[i1][j1]==1)
				{
					grid[i1][j1]=0;
					qx.add(i1);
					qy.add(j1);
				}
			}
		}
		// recompute cnt after BFS – only neighbours that are still intact (or the start cell) are counted
		cnt=0;
		for(int i=0;i<4;i++)
		{
			int r=r2+dx[i];
			int c=c2+dy[i];
			if(r>=1 && r<=n && c>=1 && c<=m && (grid[r][c]==1||(r==r1 && c==c1)))
				cnt++;
		}
		if(connected)
		{
			if(grid[r2][c2]==1)
				out.println(cnt>1?"YES":"NO");
			else
				out.println("YES");
		}
		else
			out.println("NO");

	}





	public void run()throws Exception
	{
		br=new BufferedReader(new InputStreamReader(System.in));
		st=null;
		out=new PrintWriter(System.out);

		solve();

		br.close();
		out.close();
	}
	public static void main(String args[])throws Exception{
		new Main().run();
	}
