class TaskC {

    class Pair {
        public int x, y;
        public Pair ( int y,int x) {
            this.x = x;
            this.y = y;
        }
    }
    int n, m;
    int[][] d = {{0, -1}, {-1, 0}, {0, 1}, {1, 0}};
    public void solve(int testNumber, Reader in, PrintWriter out) {
        n = in.ni(); m = in.ni();
        String[] map = new String[n];
        boolean[][] visited = new boolean[n][m];
        for(int i = 0; i < n; i++) {
            map[i] = in.rl();
        }
        int r1, c1, r2, c2;
        r1 = in.ni() - 1; c1 = in.ni() - 1; r2 = in.ni() - 1; c2 = in.ni() - 1;
        ArrayDeque<Pair> q = new ArrayDeque<>();
        q.addFirst(new Pair(r1, c1));
        if(r1 == r2 && c1 == c2) {
            for(int i = 0; i < 4; i++) {
                int x = r1 + d[i][0];
                int y = c1 + d[i][1];
                if(check(x, y) && map[x].charAt(y) == '.') {
                    out.println("YES");
                    return;
                }
            }
            out.println("NO");
        } else {
            int x, y, cnt;
            cnt = 0;
            if(map[r2].charAt(c2) == '.') {
                for(int i = 0; i < 4; i++) {
                    x = r2 + d[i][0];
                    y = c2 + d[i][1];
                    if(check(x, y) && (map[x].charAt(y) == '.' || (r1 == x && c1 == y))) {
                        cnt++;
                    }
                }
                if(cnt < 2) {
                    out.println("NO");
                    return;
                }
            }
            visited[r1][c1] = true;

            while(q.size() != 0) {
                Pair pair = q.pollFirst();
                for(int i = 0; i < 4; i++) {
                    x = pair.x + d[i][0];
                    y = pair.y + d[i][1];
                    if(check(x, y) && !visited[x][y] && map[x].charAt(y) != 'X') {
                        visited[x][y] = true;
                        q.addLast(new Pair(x, y));
                    }
                }
            }
            for(int i = 0; i < 4; i++) {
                x = r2 + d[i][0];
                y = c2 + d[i][1];
                if(check(x, y) && visited[x][y]) {
                    out.println("YES");
                    return;
                }
            }
            out.println("NO");
        }
    }

    public boolean check(int x, int y) {
        return x >= 0 && x < m && y >= 0 && y < n;
    }
}

class Reader {
    private BufferedReader in;
    private StringTokenizer st = new StringTokenizer("");
    private String delim = " ";

    public Reader(InputStream in) {
        this.in = new BufferedReader(new InputStreamReader(in));
    }

    public String next() {
        if (!st.hasMoreTokens()) {
            st = new StringTokenizer(rl());
        }
        return st.nextToken(delim);
    }

    public String rl() {
        try {
            return in.readLine();
        } catch(IOException e) {
            throw new RuntimeException(e);
        }
    }

    public int ni() {
        return Integer.parseInt(next());
    }

}

