        int[] dr = new int[]{0, 1, 0, -1};
        int[] dc = new int[]{1, 0, -1, 0};

        for (int i = 0; i < 4; i++) {
            if (r + dr[i] >= 0 && r + dr[i] < N &&
                c + dc[i] >= 0 && c + dc[i] < M &&
                board[r + dr[i]][c + dc[i]] == '.' &&
                !marked[r + dr[i]][c + dc[i]]) {

                dfs(r + dr[i], c + dc[i]);
            }
        }
    }

