class Graph {
    int[][] visited;
    int[][] graph;
    int n, m;

    Graph(int n, int m, String[] str) {
        this.n = n;
        this.m = m;
        visited = new int[n][m];
        graph = new int[n][m];

        for (int i = 0; i < str.length; i++) {
            for (int j = 0; j < str[i].length(); j++) {
                if (str[i].charAt(j) == 'X') {
                    graph[i][j] = 0;
                } else {
                    // fixed: intact ice is represented by 1
                    graph[i][j] = 1;
                }
                visited[i][j] = 0;
            }
        }
    }

    public boolean check(int xc, int yc, int xr, int yr) {
        // reached the target cell and it is already cracked
        if ((xc == xr) && (yc == yr) && (graph[xc][yc] == 0))
            return true;

        // bounds, too many visits, or trying to step on a cracked cell (except the target)
        if ((xc >= n) || (yc >= m) || (xc < 0) || (yc < 0)
                || (visited[xc][yc] >= 2) || (graph[xc][yc] == 0))
            return false;

        visited[xc][yc]++;

        // turn intact ice into cracked after the first visit
        if (graph[xc][yc] == 1)
            graph[xc][yc] = 0;

        // explore neighbours
        if (check(xc + 1, yc, xr, yr) || check(xc - 1, yc, xr, yr)
                || check(xc, yc + 1, xr, yr) || check(xc, yc - 1, xr, yr))
            return true;

        return false;
    }
}

