                    cracked[i][j] = tmp[i][j] == 'X';
            }

            rS = sc.nextInt() - 1;
            cS = sc.nextInt() - 1;
            rE = sc.nextInt() - 1;
            cE = sc.nextInt() - 1;
            if (rS == rE && cS == cE) {
                for (int k = 0; k < 4; k++) {
