                        out.println("YES");
                        return;
                    }
                }
                out.println("NO");
                return;
            }

            flood_fill(rS, cS);

            if (cracked[rE][cE]) {
                if (visited[rE][cE]) out.println("YES");
                else out.println("NO");
                return;
            }

            int cntNxt = 0;
            boolean foundOne = false;
            for (int k = 0; k < 4; k++) {
