        }
        int startX = in.nextInt() - 1;
        int startY = in.nextInt() - 1;
        int endX = in.nextInt() - 1;
        int endY = in.nextInt() - 1;

        Stack<int[]> stack = new Stack<int[]>();
        stack.push(new int[]{startX, startY});

        int[][] delta = new int[][] { { 0, 1 }, { 0, -1 }, { 1, 0 }, { -1, 0 } };


        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int x = cur[0];
            int y = cur[1];

            if (x == endX && y == endY && visited[x][y]) {
                System.out.println("YES");
                return;
            }

            visited[x][y] = true;
            for (int[] d : delta) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (nx == endX && ny == endY) {
                    if (visited[nx][ny] || g[nx].charAt(ny) == 'X') {
                        System.out.println("YES");
                        return;
                    } else {
                        stack.push(new int[]{nx, ny});
                        continue;
                    }
                }

                if (nx >= 0 && ny >= 0 && nx < n && ny < m &&
                    g[nx].charAt(ny) == '.' && !visited[nx][ny]) {
                    stack.push(new int[]{nx, ny});
                }
            }
        }
        System.out.println("NO");
    }
}

