public class C {

	private static int[] is = { -1, 0, 1, 0 };
	private static int[] js = { 0, 1, 0, -1 };

	public static void main(String[] args) throws IOException {
		try (BufferedReader in = new BufferedReader(new InputStreamReader(System.in))) {
			StringTokenizer data = new StringTokenizer(in.readLine());
			int n = Integer.parseInt(data.nextToken());
			int m = Integer.parseInt(data.nextToken());
			char[][] field = new char[n][m];

			for (int i = 0; i < n; i++) {
				field[i] = in.readLine().toCharArray();
			}
			String res = "NO";
			data = new StringTokenizer(in.readLine());
			XY s = new XY(Integer.parseInt(data.nextToken()) - 1, Integer.parseInt(data.nextToken()) - 1);
			data = new StringTokenizer(in.readLine());
			XY t = new XY(Integer.parseInt(data.nextToken()) - 1, Integer.parseInt(data.nextToken()) - 1);
			int tAdjNum = getAdjs(field, t.x, t.y, n, m).size();

			if (isAdj(s.x, s.y, t.x, t.y) && (field[t.x][t.y] == 'X' || tAdjNum > 0)) {
				res = "YES";
			} else if (field[t.x][t.y] == 'X' || tAdjNum > 1) {
				int[][] visited = new int[n][m];
				visited[s.x][s.y] = 1;
				doDfs(field, visited, s, n, m);

				for (int i = 0; i < is.length; i++) {
					int adji = t.x + is[i];
					int adjj = t.y + js[i];

					if (adji >= 0 && adji < n && adjj >= 0 && adjj < m && visited[adji][adjj] > 0) {
						res = "YES";
						break;
					}
				}
			}
			System.out.println(res);
		}
	}

	private static void doDfs(char[][] field, int[][] visited, XY s, int n, int m) {

		for (XY adj : getAdjs(field, s.x, s.y, n, m)) {
			if (visited[adj.x][adj.y] == 0) {
				visited[adj.x][adj.y] = 1;
				doDfs(field, visited, adj, n, m);
			}
		}
	}

	private static boolean isAdj(int x1, int y1, int x2, int y2) {
		for (int i = 0; i < is.length; i++) {
			int adji = x1 + is[i];
			int adjj = y1 + js[i];   // fixed: was 'y % js[i]'

			if (adji == x2 && adjj == y2) {
				return true;
			}
		}
		return false;
	}

	private static List<XY> getAdjs(char[][] field, int x, int y, int n, int m) {
		List<XY> xy = new ArrayList<>();

		for (int i = 0; i < is.length; i++) {
			int adji = x + is[i];
			int adjj = y + js[i];   // fixed: was 'y % js[i]'

			if (adji >= 0 && adji < n && adjj >= 0 && adjj < m && field[adji][adjj] == '.') {
				xy.add(new XY(adji, adjj));
			}
		}
		return xy;
	}

	private static class XY {
		private int x;
		private int y;

		public XY(int x, int y) {
			this.x = x;
			this.y = y;
		}
	}
}

