				break;
			}
		}
		inputParser = new StringTokenizer(FInput, " ");
	}

	long NextLong()
    {
            String n = inputParser.nextToken();
            long val = Long.parseLong(n);
            return val;
    }

	public static void main(String [] argv)
	{
		String filePath=null;
		if(argv.length>0)filePath=argv[0];
		new C(filePath);
	}

	int [] dx=(0-1),-1,0,1;
	int [] dy=-1,0,1,0;

	public C(String inputFile)
	{
		openInput(inputFile);
		StringBuilder sb = new StringBuilder();
		readNextLine();
		int N=NextInt();
		int M=NextInt();
		boolean [] [] p = new boolean [N+2][M+2];
		v = new boolean [N+2][M+2];

		for(int i=0; i<N; i++)
		{
			readNextLine();
			for(int j=0; j<M; j++)
			{
				p[i+1][j+1]=line.charAt(j)=='.';
			}
		}
		readNextLine();
		int r=NextInt(), c=NextInt();
		readNextLine();
		int tr=NextInt(), tc=NextInt();

		boolean poss = true;
		if(p[tr][tc])
		{
			int cnt=0;
			for(int d=0; d<4; d++)
			{
				if(p[tr+dx[d]][tc+dy[d]])cnt++;
			}
			if(cnt<2)poss=false;
			if(cnt==1&&!poss)
			{
				for(int d=0; d<4; d++)
				{
					if(tr+dx[d]==r&&tc+dy[d]==c)poss=true;
				}
			}
		}

		if(poss)
		{
			fill(p,r,c,tr,tc);
			poss=v[tr][tc];
		}

		if(poss)System.out.println("YES");
		else System.out.println("NO");
		closeInput();	
	}

	boolean [] [] v;

	void fill(boolean [] [] p, int r, int c, int tr, int tc)
	{
		for(int d=0; d<4; d++)
		{
			if((p[r+dx[d]][c+dy[d]]||(r+dx[d]==tr&&c+dy[d]==tc))&&(!v[r+dx[d]][c+dy[d]]||(r+dx[d]==tr&&c+dy[d]==tc)))
			{
				v[r+dx[d]][c+dy[d]] = true;
				fill(p, r+dx[d], c+dy[d],tr,tc);
			}
		}
	}
}

