class Solver {
    public void solve(InputReader in, PrintWriter out) {
        int r = in.nextInt();
        int c = in.nextInt();

        char[][] board = new char[r][c];
        boolean[][] visited = new boolean[r][c];

        for (int i = 0; i < r; i++) {
        	String s = in.next();
        	char[] tmp = s.toCharArray();

        	for (int j = 0; j < c; j++) {
        		board[i][j] = tmp[j];
        	}
        }

        int a = in.nextInt();
        int b = in.nextInt();
        int x = in.nextInt();
        int y = in.nextInt();

        // Do not modify the start cell; keep its original 'X' value.
        // board[a-1][b-1] = '.';

        if (dfs(board, visited, a-1, b-1, x-1, y-1)) {
        	out.println("YES");
        } else {
        	out.println("NO");
        }
    }

    public boolean dfs(char[][] board, boolean[][] visited, int a, int b, int x, int y) {
    	if (a >= board.length || a < 0 || b >= board[0].length || b < 0) {
    		return false;
    	}

    	if (a == x && b == y) {
    		if (board[a][b] == 'X') {
    			return true;
    		} else {
    			if (x-1 >= 0 && board[x-1][y] == '.') {
    				return true;
    			} else if (x+1 < board.length && board[x+1][y] == '.') {
    				return true;
    			} else if (y-1 >= 0 && board[x][y-1] == '.') {
    				return true;
    			} else if (y+1 < board[0].length && board[x][y+1] == '.') {
    				return true;
    			} else {
    				return false;
    			}
    		}
    	}

    	if (visited[a][b] || board[a][b] == 'X') {
    		return false;
    	}

    	visited[a][b] = true;
    	if (dfs(board, visited, a-1, b, x, y) || dfs(board, visited, a+1, b, x, y) || dfs(board, visited, a, b-1, x, y) || dfs(board, visited, a, b+1, x, y)) {
    		return true;
    	}

    	return false;
    }
}

