import java.util.Scanner;

public class IceCave {

	public static boolean[][] iceCave;
	static boolean visited[][];
	public static int destX, destY, n, m;

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		n = scan.nextInt();
		m = scan.nextInt();
		iceCave = new boolean[n][m];
		visited = new boolean[n][m];
		for (int i = 0; i < n; i++) {
			String str = scan.next();
			for (int j = 0; j < m; j++)
				iceCave[i][j] = str.charAt(j) == 'X';
		}

		int myX = scan.nextInt() - 1;
		int myY = scan.nextInt() - 1;
		destX = scan.nextInt() - 1;
		destY = scan.nextInt() - 1;
		iceCave[myX][myY] = false;

		System.out.println(dfs(myX, myY) ? "YES" : "NO");
		scan.close();
	}

	public static boolean dfs(int r, int c) {
		if (c < 0 || c >= m || r < 0 || r >= n)
			return false;

		if (r == destX && c == destY) {
			if (iceCave[r][c])
				return true;
			return hasGoodNeighbor(destX, destY);
		}

		if (iceCave[r][c] || visited[r][c])
			return false;

		iceCave[r][c] = true;

		boolean result = dfs(r + 1, c) || dfs(r - 1, c) || dfs(r, c - 1) || dfs(r, c + 1);

		if (result == false) {
			iceCave[r][c] = false;
			visited[r][c] = true;
		}
		return result;
	}

	public static boolean hasGoodNeighbor(int r, int c) {
		boolean neighborsCracked = true;

		if (r - 1 >= 0 && !iceCave[r - 1][c])
			neighborsCracked = false;

		if (r + 1 < n && !iceCave[r + 1][c])
			neighborsCracked = false;

		if (c - 1 >= 0 && !iceCave[r][c - 1])
			neighborsCracked = false;

		if (c + 1 < m && !iceCave[r][c + 1])
			neighborsCracked = false;

		return !neighborsCracked;
	}

}

