class TaskC {
    static final int[] dx = {0, 0, -1, +1};
    static final int[] dy = {-1, +1, 0, 0};

    int n;
    int m;
    char[][] map;

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        n = in.nextInt();
        m = in.nextInt();
        map = new char[n][m];
        for (int i = 0; i < n; ++i) map[i] = in.next().toCharArray();
        int r1 = in.nextInt() - 1;
        int c1 = in.nextInt() - 1;
        int r2 = in.nextInt() - 1;
        int c2 = in.nextInt() - 1;
        Queue<Integer> qX = new ArrayDeque<>();
        Queue<Integer> qY = new ArrayDeque<>();
        qX.add(r1);
        qY.add(c1);
        while (!qX.isEmpty()) {
            int curX = qX.poll();
            int curY = qY.poll();
            for (int i = 0; i < 4; ++i) {
                int newX = curX + dx[i];
                int newY = curY + dy[i];
                if (newX == r2 && newY == c2 && map[newX][newY] == 'X') {
