public class IceCave {
    static boolean isValidPoint(int x, int y, char[][] graph, boolean[][] visitedGraph) {
        if (x < 0 || x >= graph.length) return false;
        if (y < 0 || y >= graph[0].length) return false;
        if (visitedGraph[x][y]) return false;
        return true;
    }
    static boolean canReachDestinantion(Point startPoint, Point targetPoint, char[][] graph) {
        Deque<Point> queue = new LinkedList<>(); 
        boolean[][] visitedGraph = new boolean[graph.length][graph[0].length];

        graph[startPoint.x][startPoint.y] = '.';
        queue.addLast(startPoint);
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};
        while(!queue.isEmpty()) {
            Point p = queue.pollFirst();
            if (p.equals(targetPoint) && graph[targetPoint.x][targetPoint.y] == 'X') {
                return true;
            }
            if (!visitedGraph[p.x][p.y]) {
                if (graph[p.x][p.y] == '.') {
                    graph[p.x][p.y] = 'X';
                } else {
                    visitedGraph[p.x][p.y] = true;
                }
            }

            if (visitedGraph[p.x][p.y]) {
                continue;
            }
            for (int i=0; i < dx.length; i++) {
                if (isValidPoint(p.x + dx[i], p.y + dy[i], graph, visitedGraph)) {
                    queue.add(new Point(p.x + dx[i], p.y + dy[i]));
                }
            }
        }

        return false;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
