public class Replacement {
    void solve() {
        int n = in.nextInt(), m = in.nextInt();
        String s = in.nextToken();
        char[] ch = s.toCharArray();

        long periods = 0, segments = 0;
        for (int i = 0; i < n; ) {
            if (ch[i] == '.') {
                int j = i;
                while (j + 1 < n && ch[j + 1] == '.') j++;
                periods += j - i + 1;
                segments++;
                i = j + 1;
            } else {
                i++;
            }
        }

        for (int i = 0; i < m; i++) {
            int x = in.nextInt() - 1;
            char c = in.nextToken().charAt(0);
            char old = ch[x];
            if (old != c) {
                if (c == '.') periods++; else periods--;
                ch[x] = c;

                boolean left = (x > 0 && ch[x - 1] == '.');
                boolean right = (x < n - 1 && ch[x + 1] == '.');

                if (old == '.' && c != '.') {
                    // removing a dot
                    if (left && right) {
                        segments++;               // split a run
                    } else if (!left && !right) {
                        segments--;               // isolated dot disappears
                    }
                } else if (old != '.' && c == '.') {
                    // adding a dot
                    if (left && right) {
                        segments--;               // merge two runs
                    } else if (!left && !right) {
                        segments++;               // new isolated run
                    }
                }
            }
            out.println(periods - segments);
        }
    }

    int search(List<Range> ranges, int s, int e, int x) {
        int m = (s + e) / 2;
        Range r = ranges.get(m);
        if (x >= r.a && x <= r.b) return m;
        if (x < r.a) return search(ranges, s, m - 1, x);
        return search(ranges, m + 1, e, x);
    }

    static class Range implements Comparable<Range> {
        int a;
        int b;
        boolean p;

        public Range(int a, int b, boolean p) {
            this.a = a;
            this.b = b;
            this.p = p;
        }

        @Override
        public int compareTo(Range r) {
            if (a != r.a) return a - r.a;
            return b - r.b;
        }
    }

