                        if (cur1 == null && cur2 == null) {
                            set.add(new Seg(x - 1, x + 1));
                            ans += 2;
                        } else if (cur1 == null) {
                            set.add(new Seg(cur2.l, x + 1));
                            set.remove(cur2);
                            ans += 2;
                        } else if (cur2 == null) {
                            set.add(new Seg(x - 1, cur1.r));
                            set.remove(cur1);
                            ans += 2;
                        } else {
                            set.add(new Seg(cur2.l, cur1.r));
                            set.remove(cur1);
                            set.remove(cur2);
                            ans -= cur1.r - cur1.l;
                            ans -= cur2.r - cur2.l;
                            ans += cur1.r - cur2.l;
                        }
