                Seg cur = set.lower(new Seg(x, -1));
                if (cur == null || cur.r < x) {
                    out.println(ans);
                    continue;
                }
                TaskC.Seg left = new Seg(cur.l, x - 1);
                TaskC.Seg right = new Seg(x + 1, cur.r);
                set.remove(cur);
                if (left.r - left.l > 0) {
                    set.add(left);
                    ans += left.r - left.l;
                }
                if (right.r - right.l > 0) {
                    set.add(right);
                    ans += right.r - right.l;
                }
                ans -= cur.r - cur.l;
                out.println(ans);
            }
        }

