public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Replacement solver = new Replacement();
        solver.solve(1, in, out);
        out.close();
    }

    static class Replacement {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[] str = in.nextLine().toCharArray();
            int tot = 0;
            int c = 0;
            for (int i = 0; i < n; i++) {
                if (str[i] == '.') {
                    c++;
                    if (i == n - 1) {
                        tot += (c - 1);
                    }
                } else {
                    if (c >= 2) {
                        tot += (c - 1);
                    }
                    c = 0;
                }
            }

            while (m-- > 0) {
                int x = in.nextInt() - 1;
                char rep = in.next().toCharArray()[0];
                if (n == 1) {
                    out.println(0);
                    continue;
                } else if (rep == '.') {
                    if (str[x] != '.') {
                        if (x == 0) {
                            if (str[x + 1] == '.') {
                                tot++;
                            }
                        } else if (x == n - 1) {
                            if (str[x - 1] == '.') {
                                tot++;
                            }
                        } else {
                            if (str[x - 1] == '.' && str[x + 1] == '.') {
                                tot += 2;
                            } else if (str[x - 1] == '.' || str[x + 1] == '.') {
                                tot++;
                            }
                        }
                    }
                } else {
                    if (x == 0) {
                        if (str[x] == '.' && str[x + 1] == '.') {
                            tot--;
                        }
                    } else if (x == n - 1) {
                        if (str[x] == '.' && str[x - 1] == '.') {
                            tot--;
                        }
                    } else {
                        if (str[x] == '.' && str[x - 1] == '.' && str[x + 1] == '.') {
                            tot -= 2;
                        } else if (str[x] == '.' && str[x + 1] == '.') {
                            tot--;
                        } else if (str[x] == '.' && str[x - 1] == '.') {
                            tot--;
                        }
                    }
                }
                str[x] = rep;
                out.println(tot);
            }
        }

    }

    static class Scanner {
        StringTokenizer st;
        BufferedReader br;

        public Scanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public Scanner(String s) {
            try {
                br = new BufferedReader(new FileReader(s));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

    }
}

