        			boolean join = false;
        			Integer l1 = map.floorKey(pos-1);
        			Integer l2 = map.ceilingKey(pos+1);

        			if(l1 != null && l2 != null) {
        				Integer r1 = map.get(l1);
        				Integer r2 = map.get(l2);

        				if(r1 == pos-1 && l2 == pos+1) {

        					ans-=r1-l1+r2-l2;
