						}
						if(!join) {
							map.put(pos,pos);
						}
					}
				  }
			}else {
				if(s[pos] == '.') {
					int l = map.floorKey(pos);
					int r = map.get(l);
					ans-=r-l;
					map.remove(l);
					if(l<=pos-1) map.put(l, pos-1);
					if(pos+1<=r) map.put(pos+1, r);
					ans+=Math.max(0,pos-1-l) + Math.max(0,r-pos-1);
				}
			}
			s[pos] = c;
