import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        String inp = br.readLine();
        char[] ar = inp.toCharArray();
        int count = 0, segcount = 0, c = 0;

        if (n == 1) {
            for (int i = 0; i < m; i++) {
                StringTokenizer ss = new StringTokenizer(br.readLine());
                int x = Integer.parseInt(ss.nextToken()) - 1;
                char z = ss.nextToken().charAt(0);
                System.out.println(0);
            }
            return;
        }

        // compute initial count and segcount
        for (int i = 0; i < n; i++) {
            if (inp.charAt(i) != '.') {
                if (c > 0) {
                    segcount++;
                    c = 0;
                }
            }
            if (inp.charAt(i) == '.') {
                count++;
                c++;
            }
        }
        if (c > 0) segcount++;

        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < m; i++) {
            StringTokenizer ss = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(ss.nextToken()) - 1;
            char z = ss.nextToken().charAt(0);

            if (z == '.') {
                // putting a dot where there was not a dot
                if (ar[x] != '.') {
                    count++;                     // total '.' increases
                    if (x == 0) {
                        if (ar[x + 1] != '.') segcount++;   // new isolated group at the beginning
                    } else if (x == n - 1) {
                        if (ar[x - 1] != '.') segcount++;   // new isolated group at the end
                    } else {
                        if (ar[x - 1] == '.' && ar[x + 1] == '.') segcount--;   // joining two groups
                        else if (ar[x - 1] != '.' && ar[x + 1] != '.') segcount++; // isolated new group
                    }
                }
            } else {
                // removing a dot
                if (ar[x] == '.') {
                    count--;                     // total '.' decreases
                    if (x == 0) {
                        if (ar[x + 1] != '.') segcount--;   // group at the beginning disappears
                    } else if (x == n - 1) {
                        if (ar[x - 1] != '.') segcount--;   // group at the end disappears
                    } else {
                        if (ar[x - 1] == '.' && ar[x + 1] == '.') segcount++; // splitting a group
                        else if (ar[x - 1] != '.' && ar[x + 1] != '.') segcount--; // isolated group disappears
                    }
                }
            }

            ar[x] = z;                // apply the change
            sb.append(count - segcount).append('\n');
        }

        System.out.print(sb);
    }
}

import java.io.BufferedReader;
