public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Reader in = new Reader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, Reader in, PrintWriter out) {
            int n, m;
            n = in.ni();
            m = in.ni();
            char[] s = in.rl().toCharArray();
            TreeSet<PairInt> set = new TreeSet<PairInt>(new Comparator<PairInt>() {

                public int compare(PairInt o1, PairInt o2) {
                    return o1.x - o2.x;
                }
            });
            long total = 0;
            for (int i = 0; i < n; ) {
                if (s[i] != '.') {
                    ++i;
                    continue;
                }
                int j = i;
                for (; j < n; j++) {
                    if (s[j] != '.') {
                        break;
                    }
                }
                PairInt pair = new PairInt(i, j - 1);
                set.add(pair);
                total += (pair.y - pair.x);
                i = j;
            }
            for (int i = 0; i < m; i++) {
                int x = in.ni() - 1;
                char ch = in.next().charAt(0);
                PairInt pairInt = new PairInt(x, x);
                if (ch == '.') {
                    if (s[x] != '.') {
                        PairInt lower, higher;
                        lower = higher = null;
                        if (x > 0) {
                            if (s[x - 1] == '.') {
                                lower = set.lower(pairInt);
                                total -= (lower.y - lower.x);
                            }
                        }
                        if (x < n - 1) {
                            if (s[x + 1] == '.') {
                                higher = set.higher(pairInt);
                                total -= (higher.y - higher.x);
                            }
                        }
                        PairInt res = new PairInt(x, x);
                        if (lower != null) {
                            set.remove(lower);
                            res.x = lower.x;
                        }
                        if (higher != null) {
                            set.remove(higher);
                            res.y = higher.y;
                        }
                        total += (res.y - res.x);
                        set.add(res);
                    }
                } else {
                    if (s[x] == '.') {
                        PairInt floor = set.floor(pairInt);
                        set.remove(floor);
                        total -= (floor.y - floor.x);
                        PairInt lower, higher;
                        lower = higher = null;
                        if (floor.x != x) {
                            lower = new PairInt(floor.x, x - 1);
                        }
                        if (floor.y != x) {
                            higher = new PairInt(x + 1, floor.y);
                        }
                        if (lower != null) {
                            set.add(lower);
                            total += (lower.y - lower.x);
                        }
                        if (higher != null) {
                            set.add(higher);
                            total += (higher.y - higher.x);
                        }
                    }
                }
                out.println(total);
                s[x] = ch;
            }
        }

    }

    static class PairInt {
        public int x;
        public int y;

        public PairInt(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public String toString() {
            return x + " " + y;
        }

        public PairInt clone() {
            return new PairInt(x, y);
        }

    }

    static class Reader {
        private BufferedReader in;
        private StringTokenizer st = new StringTokenizer("");
        private String delim = " ";

        public Reader(InputStream in) {
            this.in = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            if (!st.hasMoreTokens()) {
                st = new StringTokenizer(rl());
            }
            return st.nextToken(delim);
        }

        public String rl() {
            try {
                return in.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public int ni() {
            return Integer.parseInt(next());
        }

    }
}

