import java.util.*;
import java.io.*;

public class Replacement {
  public static void main(String[] args) throws IOException {
    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    String[] input = in.readLine().split(" ");
    int N = Integer.parseInt(input[0]);
    int M = Integer.parseInt(input[1]);
    char[] s = in.readLine().toCharArray();
    int total = 0;
    int streak = 1;
    boolean[] isPeriod = new boolean[N];
    isPeriod[0] = s[0] == '.';
    for(int i = 1; i < N; i++) {
      isPeriod[i] = s[i] == '.';
      if(isPeriod[i] == isPeriod[i-1])
        streak++;
      else {
        if(isPeriod[i-1])
          total += streak - 1;
        streak = 1;
      }
    }
    if(isPeriod[N-1])
      total += streak - 1;

    for(int i = 0; i < M; i++) {
      if(isPeriod.length == 1) {
        System.out.println("0");
        continue;
      }
      String[] q = in.readLine().split(" ");
      int index = Integer.parseInt(q[0]) - 1;
      boolean isPer = q[1].charAt(0) == '.';
      if(isPer ^ isPeriod[index]) {
        if(index == 0)
          total = onEnd(total, isPer, isPeriod[index+1]);
        else if(index == N-1)
          total = onEnd(total, isPer, isPeriod[index-1]);
        else {
          if(isPeriod[index-1] == isPer && isPeriod[index+1] == isPer)
            total = merge(total, isPer);
          else if(isPeriod[index-1] == isPer ^ isPeriod[index+1] == isPer)
            total = add(total, isPer);
          else
            total = split(total, isPer);
        }
        isPeriod[index] = isPer;
      }
      System.out.println(total);
    }
  }

  public static int merge(int total, boolean addingPeriod) {
    return addingPeriod ? total + 2 : total;
  }
  public static int split(int total, boolean addingPeriod) {
    return addingPeriod ? total : total - 2;
  }
  public static int add(int total, boolean addingPeriod) {
    return addingPeriod ? total + 1 : total - 1;
  }
  public static int onEnd(int total, boolean addingPeriod, boolean nextTo) {
    if(nextTo == addingPeriod)
      return addingPeriod ? total + 1 : total;
    else
      return addingPeriod ? total : total - 1;
  }
}

