                verificadorBool = false;
            }
            caractere[verificadorInt - 1] = verificadorChar;
            if (verificadorBool) {
                if (verificadorInt != primeiroInteiro) {
                    if (caractere[verificadorInt] == '.') {
                        if (verificadorChar == '.') {
                            aux++;
                        } else {
                            aux--;
                        }
                    }
