        char[] s = br.readLine().toCharArray();

        // count occurrences of consecutive ".."
        int pairs = 0;
        for (int i = 0; i < n - 1; i++) {
            if (s[i] == '.' && s[i + 1] == '.') {
                pairs++;
            }
        }

        for (int q = 0; q < m; q++) {
            String[] query = br.readLine().split(" ");
            int idx = Integer.parseInt(query[0]) - 1;   // 0‑based index
            char c = query[1].charAt(0);                // new character

            char old = s[idx];
            if (old == c) {               // no change
                out.println(pairs);
                continue;
            }

            // remove contributions of pairs that involve the position being changed
            for (int i = idx - 1; i <= idx; i++) {
                if (i < 0 || i >= n - 1) continue;
                if (s[i] == '.' && s[i + 1] == '.') {
                    pairs--;
                }
            }

            // apply the substitution
            s[idx] = c;

            // add back contributions of pairs that involve the updated position
            for (int i = idx - 1; i <= idx; i++) {
                if (i < 0 || i >= n - 1) continue;
                if (s[i] == '.' && s[i + 1] == '.') {
                    pairs++;
                }
            }

            out.println(pairs);
        }
        out.flush();
    }
}

