        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt(), q = in.nextInt();
            char[] s = in.next().toCharArray();
            int count = 0, moves = 0;
            for (int i = 0; i < n; i++) {
                if (s[i] == '.') count++;
                else if (count > 0) {
                    moves += count - 1;
                    count = 0;
                }
