        public void solve(int testNumber, input in, PrintWriter out) {
            int t = in.nextInt();
            int q = in.nextInt();
            char[] ch = in.next().toCharArray();
            int sols = 0;
            for (int i = 0; i < t - 1; i++) {
                if (ch[i] == '.' && ch[i + 1] == '.')
                    sols++;
            }
            for (int i = 0; i < q; i++) {
                int f = in.nextInt();
                f--;
                char c = in.next().charAt(0);
                if (ch[f] != '.') {
