		for(int i=0;i<n;)
		{
			int c = 0;
			while(i<n && arr[i++]=='.')
				c++;
			if(c!=0)
			ans+=(c-1);
		}
		for(int i=0;i<m;i++)
		{
			sa = br.readLine().split(" ");
			int idx = Integer.parseInt(sa[0])-1;
			char cc = sa[1].charAt(0);
			if(cc == '.')
			{
				if(arr[idx] == '.')
				{
					sb.append(ans+"\n");
					continue;
				}
				int c = 0;
				if(idx-1>=0 && arr[idx-1]=='.')
					c++;
				if(idx+1<arr.length && arr[idx+1]=='.')
					c++;
				ans+=c;
				sb.append(ans+"\n");
				arr[idx] = cc;
			}
