	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		InputReader in = new InputReader(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		solve(in, out);
		out.close();
	}

	public static void solve(InputReader in, PrintWriter out) {
		int n = in.nextInt();
		int m = in.nextInt();
		StringBuffer sb = new StringBuffer(in.next());
		int ans = f(sb.toString());
		for(int i = 0; i < m; ++i) {
			int pos = in.nextInt();
			char ch = in.nextChar();
			ans += query(sb, pos - 1, ch);
			out.println(ans);
		}
	}

	public static int query(StringBuffer sb, int pos, char ch) {
		int ans = 0;
		if(ch == '.') {
			if (sb.charAt(pos) == '.')
				return 0;
			if (pos - 1 >= 0 && sb.charAt(pos - 1) == '.') {
				ans++;
			}
			if (pos + 1 < sb.length() && sb.charAt(pos + 1) == '.') {
				ans++;
			}
		}
		else {
			if (sb.charAt(pos) != '.')
				return 0;
			if (pos - 1 >= 0 && sb.charAt(pos - 1) == '.') {
				ans--;
			}
			if (pos + 1 < sb.length() && sb.charAt(pos + 1) == '.') {
				ans--;
			}
		}
		sb.setCharAt(pos, ch);
		return ans;
	}

	public static int f(String s) {
		int result = 0;
		boolean isPrevDot = false; 
		for(int i = 0; i < s.length(); ++i) {
			if (s.charAt(i) == '.') {
				if(isPrevDot) {
					++result;
				} else {
					isPrevDot = true;
				}
			} else {
				isPrevDot = false;
			}
		}
		return result;
	}

	static class InputReader {
		public BufferedReader reader;
		public StringTokenizer tokenizer;

		public InputReader(InputStream stream) {
			reader = new BufferedReader(new InputStreamReader(stream), 32768);
		}

		public String next() {
			while(tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(reader.readLine());
				} catch(IOException e) {
					throw new RuntimeException(e);
				}
			}
			return tokenizer.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

		public char nextChar() {
			return next().charAt(0);
		}
	}
}

