import java.util.*;
import java.io.*;

public class Main {
    static class TaskA {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt(), m = in.nextInt();
            char[] s = new char[n + 2];               // 0 and n+1 are sentinels
            System.arraycopy(in.next().toCharArray(), 0, s, 1, n);

            int dots = 0;      // total number of '.' characters
            int cc = 0;        // number of blocks of '.' (i.e. starts of blocks)

            // initial counting of '.' and block starts
            for (int i = 1; i <= n; i++) {
                if (s[i] == '.') {
                    dots++;
                    if (i == 1 || s[i - 1] != '.') {
                        cc++;
                    }
                }
            }

            for (int q = 0; q < m; q++) {
                int x = in.nextInt();
                char what = in.next().charAt(0);   // new character for position x

                char old = s[x];
                if (old == what) {                 // nothing changes
                    out.println(dots - cc);
                    continue;
                }

                // ----- update dot counter -----
                if (old == '.' && what != '.') {
                    dots--;
                } else if (old != '.' && what == '.') {
                    dots++;
                }
                s[x] = what;                       // place the new character

                // ----- recompute contribution of positions x and x+1 to block starts -----
                int oldStartX = (old == '.' && (x == 1 || s[x - 1] != '.')) ? 1 : 0;
                int newStartX = (what == '.' && (x == 1 || s[x - 1] != '.')) ? 1 : 0;

                int oldStartX1 = 0, newStartX1 = 0;
                if (x + 1 <= n) {
                    // start of a block at x+1 depends on the character to its left (position x)
                    oldStartX1 = (s[x + 1] == '.' && old != '.') ? 1 : 0;
                    newStartX1 = (s[x + 1] == '.' && what != '.') ? 1 : 0;
                }

                // delta of block‑start count
                cc += newStartX + newStartX1 - oldStartX - oldStartX1;

                // f(s) = total '.' – number of blocks
                out.println(dots - cc);
            }
        }
    }

    public static void main(String[] args) {
        InputStream in = System.in;
        OutputStream out = System.out;
        Scanner scanner = new Scanner(in);
        PrintWriter pw = new PrintWriter(out);
        TaskA solver = new TaskA();
        solver.solve(1, scanner, pw);
        pw.close();
    }
}

