import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class trial {
    static int n, m;
    static char[] str;
    static StringBuilder out = new StringBuilder();

    // count positions i where s[i]=='.' and (i==0 or s[i-1]!='.')
    static int countStarts(char[] s) {
        int cnt = 0;
        for (int i = 0; i < s.length; i++) {
            if (s[i] == '.' && (i == 0 || s[i - 1] != '.')) {
                cnt++;
            }
        }
        return cnt;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        str = br.readLine().toCharArray();

        // initial aggregates
        int cntDot = 0;
        for (char c : str) if (c == '.') cntDot++;
        int cntRun = countStarts(str);
        int res = cntDot - cntRun;               // f(s) for the initial string

        for (int q = 0; q < m; q++) {
            st = new StringTokenizer(br.readLine());
            int idx = Integer.parseInt(st.nextToken()) - 1;
            char newC = st.nextToken().charAt(0);
            char oldC = str[idx];

            if (oldC == newC) {
                // nothing changes
                out.append(res).append('\n');
                continue;
            }

            // ----- update cntDot -----
            int deltaDot = (newC == '.') ? 1 : 0;
            deltaDot -= (oldC == '.') ? 1 : 0;

            // ----- collect old starts around idx -----
            int oldStarts = 0;
            for (int i : new int[]{idx - 1, idx, idx + 1}) {
                if (i < 0 || i >= n) continue;
                if (str[i] == '.' && (i == 0 || str[i - 1] != '.')) {
                    oldStarts++;
                }
            }

            // apply the change
            str[idx] = newC;

            // ----- collect new starts around idx -----
            int newStarts = 0;
            for (int i : new int[]{idx - 1, idx, idx + 1}) {
                if (i < 0 || i >= n) continue;
                if (str[i] == '.' && (i == 0 || str[i - 1] != '.')) {
                    newStarts++;
                }
            }

            // update aggregates
            int deltaRun = newStarts - oldStarts;
            cntDot += deltaDot;
            cntRun += deltaRun;
            res = cntDot - cntRun;

            out.append(res).append('\n');
        }

        System.out.print(out);
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.StringBuilder;

public class trial {
    static int n, m;
    static char[] str;
    static StringBuilder out = new StringBuilder();

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] in = br.readLine().split("\\s+");
        n = Integer.parseInt(in[0]);
        m = Integer.parseInt(in[1]);
        str = br.readLine().toCharArray();

        int res = 0;
        int last = -1;
        for (int i = 0; i < str.length; i++) {
            if (str[i] != '.' && last != -1) {
                int diff = (i - 1) - last + 1;
                res += diff - 1;
                last = -1;
            } else if (str[i] == '.' && last == -1) {
                last = i;
            }
        }
        if (last != -1) {
            res += (str.length - 1) - last;
        }

        for (int w = 0; w < m; w++) {
            in = br.readLine().split(" ");
            int ind = Integer.parseInt(in[0]) - 1;
            char c = in[1].charAt(0);
            char old = str[ind];

            if (old == c) {
                out.append(res).append('\n');
                continue;
            }

            int deltaDot = 0;
            if (old == '.' && c != '.') {
                deltaDot = -1;
            } else if (old != '.' && c == '.') {
                deltaDot = 1;
            }

            int oldStart = 0;
            if (old == '.') {
                if (ind == 0 || str[ind - 1] != '.') {
                    oldStart = 1;
                }
            }

            int oldNextStart = 0;
            if (ind + 1 < n && str[ind + 1] == '.' && old != '.') {
                oldNextStart = 1;
            }

            int newStart = 0;
            if (c == '.') {
                if (ind == 0 || str[ind - 1] != '.') {
                    newStart = 1;
                }
            }

            int newNextStart = 0;
            if (ind + 1 < n && str[ind + 1] == '.' && c != '.') {
                newNextStart = 1;
            }

            int deltaRun = (newStart + newNextStart) - (oldStart + oldNextStart);
            int delta = deltaDot - deltaRun;
            res += delta;

            str[ind] = c;
            out.append(res).append('\n');
        }

        System.out.print(out);
    }
}

