class SegmentTree {

    char data[][];          // each node stores leftmost and rightmost character of its segment
    int score[];            // number of operations (f) for this segment
    int n;                  // size of the underlying complete binary tree (power of two)

    public SegmentTree(char arr[]) {
        n = (int) pow(2, ceil(log(arr.length) / log(2)));
        data = new char[2 * n][];
        score = new int[2 * n];

        // fill leaves
        for (int i = n; i < n + arr.length; ++i)
            data[i] = new char[]{arr[i - n], arr[i - n]};
        for (int i = n + arr.length; i < 2 * n; ++i)
            data[i] = new char[]{'c', 'c'};   // placeholder (non‑dot)

        // build internal nodes
        for (int i = n - 1; i > 0; --i) {
            if (data[i * 2][1] == '.' && data[i * 2 + 1][0] == '.') {
                data[i] = new char[]{data[i * 2][0], data[i * 2 + 1][1]};
                score[i] = score[i * 2] + score[i * 2 + 1] + 1;
            } else {
                // ----> fixed line: use left child's leftmost, not data[i+2][0]
                data[i] = new char[]{data[i * 2][0], data[i * 2 + 1][1]};
                score[i] = score[i * 2] + score[i * 2 + 1];
            }
        }
    }

    public int solution() {
        return score[1];
    }

    public void update(int index, char c) {
        index += n;

        // no change needed if the type (dot / non‑dot) does not change
        if ((data[index][0] == '.' && c == '.') ||
            (data[index][0] != '.' && c != '.')) {
            return;
        }

        data[index][0] = data[index][1] = c;

        // propagate changes upwards
        for (int i = index; i > 1; i >>= 1) {
            int left = i, right = i ^ 1;          // sibling index
            if (data[left][1] == '.' && data[right][0] == '.') {
                data[i >> 1][0] = data[left][0];
                data[i >> 1][1] = data[right][1];
                score[i >> 1] = score[left] + score[right] + 1;
            } else {
                data[i >> 1][0] = data[left][0];
                data[i >> 1][1] = data[right][1];
                score[i >> 1] = score[left] + score[right];
            }
        }
    }
}

