class SegmentTree{

    char data[][];
    int score[];

    int n;

    public SegmentTree(char arr[]){

        n =(int) pow(2, ceil(log(arr.length)/log(2)));;
        data = new char[2*n][];
        score = new int[2*n];

        for(int i = n; i < n + arr.length; ++i)
            data[i] = new char[]{arr[i-n], arr[i-n]};

        for(int i = n + arr.length; i < n*2; ++i)
            data[i] = new char[]{'c', 'c'};

        for(int i = n - 1; i > 0; --i){

            if(data[i*2][1] == '.' && data[i*2 + 1][0] == '.'){

                data[i] = new char[]{data[i*2][0], data[i*2 + 1][1]};
                score[i] = score[i*2] + score[i*2 + 1] + 1;
            }

            else{

                data[i] = new char[]{data[i*2][0], data[i*2 + 1][1]};
                score[i] = score[i*2] + score[i*2 + 1];
            }
        }

    }

    public int solution(){return score[1];}

    public void update(int index, char c){

        index += n;                         // <-- fixed line

        if((data[index][0] == '.' && c == '.') || (data[index][0] != '.' && c != '.'))
            return;

        data[index][0] = data[index][1] = c;

        int i = index;
        while(i > 1){

            i /= 2;

            if(data[i*2][1] == '.' && data[i*2 + 1][0] == '.'){

                data[i][0] = data[i*2][0];
                data[i][1] = data[i*2 + 1][1];
                score[i] = score[i*2] + score[i*2 + 1] + 1;
            }

            else{

                data[i][0] = data[i*2][0];
                data[i][1] = data[i*2 + 1][1];
                score[i] = score[i*2] + score[i*2 + 1];
            }
        }

    }
}

