            StringBuilder sb = new StringBuilder(in.next());
            int count = 0;
            // initial count of adjacent ".." pairs
            for (int i = 1; i < len; i++) {
                if (sb.charAt(i) == '.' && sb.charAt(i - 1) == '.')
                    count++;
            }

            for (int q = 0; q < m; q++) {
                int index = in.nextInt() - 1;          // zero‑based index
                char newC = in.next().charAt(0);       // new character

                char oldC = sb.charAt(index);
                // 1) Remove contributions of the old character
                if (oldC == '.') {
                    if (index > 0 && sb.charAt(index - 1) == '.')
                        count--;
                    if (index < len - 1 && sb.charAt(index + 1) == '.')
                        count--;
                }

                // 2) Perform the replacement
                sb.setCharAt(index, newC);

                // 3) Add contributions of the new character
                if (newC == '.') {
                    if (index > 0 && sb.charAt(index - 1) == '.')
                        count++;
                    if (index < len - 1 && sb.charAt(index + 1) == '.')
                        count++;
                }

                out.println(count);
            }
        }
    }

    static class InputReader {
        BufferedReader br;
        StringTokenizer st;

        public InputReader(InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

