    public static void main(String[] args) throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        int n = nextInt();
        int m = nextInt();
        String s = next();
        char[] a = s.toCharArray();

        /* cnt = number of overlapping ".." pairs, i.e. f(s) */
        int cnt = 0;
        for (int i = 1; i < a.length; i++) {
            if (a[i - 1] == '.' && a[i] == '.') {
                cnt++;
            }
        }

        for (int i = 1; i <= m; i++) {
            int idx = nextInt() - 1;          // 0‑based index
            char newC = next().charAt(0);      // character to write

            char oldC = a[idx];
            if (oldC != newC) {
                /* 1. Remove contributions of the old character */
                if (oldC == '.') {
                    if (idx - 1 >= 0 && a[idx - 1] == '.') cnt--;
                    if (idx + 1 < n && a[idx + 1] == '.') cnt--;
                }

                /* 2. Write the new character */
                a[idx] = newC;

                /* 3. Add contributions of the new character */
                if (newC == '.') {
                    if (idx - 1 >= 0 && a[idx - 1] == '.') cnt++;
                    if (idx + 1 < n && a[idx + 1] == '.') cnt++;
                }
            }
            pw.println(cnt);
        }
        pw.close();
    }

