public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		InputReader in = new InputReader(inputStream);
		OutputWriter out = new OutputWriter(outputStream);
		TaskC solver = new TaskC();
		solver.solve(1, in, out);
		out.close();
	}

	static class TaskC {
		private int n;
		private int m;
		private boolean[][] isFree;
		private DSU dsu;
		private Set<Integer> around = new HashSet<>(4);

		public void solve(int testNumber, InputReader in, OutputWriter out) {
			input(in);
			calculate();
			print(out);
		}

		private boolean checkRange(int i, int n) {
			return 0 <= i && i < n;
		}

		private void print(OutputWriter out) {
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					if (isFree[i][j]) {
						out.print('.');
					} else {
						around.clear();
						for (int k = 0; k < 4; k++) {
							int ii = i + MiscUtils.DX4[k];
							int jj = j + MiscUtils.DY4[k];
							if (checkRange(ii, n) && checkRange(jj, m) && isFree[ii][jj]) {
								around.add(dsu.findParent(ii, jj));
							}
						}
						int sum = around.stream().reduce(0, (s, cur) -> s + dsu.getSize(cur)) + 1;
						out.print(sum % 10);
					}
				}
				out.printLine();
			}
		}

		private void calculate() {
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					if (isFree[i][j]) {
						for (int k = 0; k < 4; k++) {
							int ii = i + MiscUtils.DX4[k];
							int jj = j + MiscUtils.DY4[k];
							if (checkRange(ii, n) && checkRange(jj, m) && isFree[ii][jj]) {
								dsu.unite(i, j, ii, jj);
							}
						}
					}
				}
			}
		}

		private void input(InputReader in) {
			n = in.readInt();
			m = in.readInt();
			isFree = new boolean[n][m];
			dsu = new DSU(n, m);
			for (int i = 0; i < n; i++)
				for (int j = 0; j < m; j++)
					isFree[i][j] = in.readCharacter() == '.';
		}

	}

	static class MiscUtils {
		public static final int[] DX4 = {1, 0, -1, 0};
		public static final int[] DY4 = {0, -1 , 1, 0};

	}

	static class OutputWriter {
		private final PrintWriter writer;

		public OutputWriter(OutputStream outputStream) {
			writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
		}

		public OutputWriter(Writer writer) {
			this.writer = new PrintWriter(writer);
		}

		public void printLine() {
			writer.println();
		}

		public void print(char i) {
			writer.print(i);
		}

		public void close() {
			writer.close();
		}

		public void print(int i) {
			writer.print(i);
		}

	}

	static class InputReader {
		private InputStream stream;
		private byte[] buf = new byte[1024];
		private int curChar;
		private int numChars;
		private SpaceCharFilter filter;

		public InputReader(InputStream stream) {
			this.stream = stream;
		}

		public int read() {
			if (numChars == -1)
				throw new InputMismatchException();
			if (curChar >= numChars) {
				curChar = 0;
				try {
					numChars = stream.read(buf);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (numChars <= 0)
					return -1;
			}
			return buf[curChar++];
		}

		public int readInt() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			int sgn = 1;
			if (c == '-') {
				sgn = -1;
				c = read();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res *= 10;
				res += c - '0';
				c = read();
			} while (!isSpaceChar(c));
			return res * sgn;
		}

		public boolean isSpaceChar(int c) {
			if (filter != null)
				return filter.isSpaceChar(c);
			return isWhitespace(c);
		}

		public static boolean isWhitespace(int c) {
			return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
		}

		public char readCharacter() {
			int c = read();
			while (isSpaceChar(c))
				c = read();
			return (char) c;
		}

		public interface SpaceCharFilter {
			public boolean isSpaceChar(int ch);

		}

	}

	static class DSU {
		private final int n;
		private final int m;
		private final int[] parent;
		private final int[] size;

		public DSU(int n, int m) {
			this.n = n;
			this.m = m;
			int nm = n * m;
			parent = IntStream.range(0, nm).toArray();
			size = ArrayUtils.createArray(nm, 1);
		}

		public int findParent(int v) {
			if (parent[v] == v) return v;
			return parent[v] = findParent(parent[v]);
		}

		private void unite(int i1, int i2) {
			int p1 = findParent(i1);
			int p2 = findParent(i2);
			if (p1 != p2) {
				parent[p1] = p2;
				size[p2] += size[p1];
			}
		}

		private int convertToIndex(int i, int j) {
			return i * m + j;
		}

		public int findParent(int i, int j) {
			return findParent(convertToIndex(i, j));
		}

		public void unite(int i1, int j1, int i2, int j2) {
			unite(convertToIndex(i1, j1), convertToIndex(i2, j2));
		}

		public int getSize(int index) {
			return size[findParent(index)];
		}

	}

	static class ArrayUtils {
		public static int[] createArray(int count, int value) {
			int[] array = new int[count];
			Arrays.fill(array, value);
			return array;
		}

	}
}

import java.io.*;
import java.util.*;

public class C {

    void solve() {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] map = new char[n][m];
        for (int i = 0; i < n; i++) {
            String s = in.next();
            for (int j = 0; j < m; j++) {
                map[i][j] = s.charAt(j);
            }
        }

        Union union = new Union(n * m);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (map[i][j] == '.') {
                    if (i + 1 < n && map[i + 1][j] == '.')
                        union.link(i * m + j, i * m + j + m);
                    if (j + 1 < m && map[i][j + 1] == '.')
                        union.link(i * m + j, i * m + j + 1);   // fixed line
                }
            }
        }

        int[] dr = {1, 0, -1, 0};
        int[] dc = {0, 1, 0, -1};

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (map[i][j] == '.')
                    continue;
                int[] roots = new int[4];
                int curRoot = 0;
                int total = 0;
                outer:
                for (int k = 0; k < 4; k++) {
                    int nr = i + dr[k], nc = j + dc[k];
                    if (nr < n && nr >= 0 && nc < m && nc >= 0 && map[nr][nc] == '.') {
                        int root = union.root(nr * m + nc);
                        for (int u = 0; u < curRoot; u++) {
                            if (root == roots[u])
                                continue outer;
                        }
                        roots[curRoot++] = root;
                        total -= union.upper[root];
                    }
                }
                map[i][j] = (char) ('0' + (total + 1) % 10);
            }
        }

        for (int i = 0; i < n; i++) {
            out.println(map[i]);
        }
    }

    class Union {
        int[] upper;

        public Union(int n) {
            upper = new int[n];
            Arrays.fill(upper, -1);
        }

        int root(int x) {
            return upper[x] < 0 ? x : (upper[x] = root(upper[x]));
        }

        boolean link(int x, int y) {
            x = root(x);
            y = root(y);
            if (x != y) {
                if (upper[y] < upper[x]) {
                    int tmp = x;
                    x = y;
                    y = tmp;
                }
                upper[x] += upper[y];
                upper[y] = x;
            }
