import java.io.*;
import java.util.*;

public class C {

    void solve() {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] map = new char[n][m];
        for (int i = 0; i < n; i++) {
            String s = in.next();
            for (int j = 0; j < m; j++) {
                map[i][j] = s.charAt(j);
            }
        }

        Union union = new Union(n * m);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (map[i][j] == '.') {
                    if (i + 1 < n && map[i + 1][j] == '.')
                        union.link(i * m + j, i * m + j + m);
                    if (j + 1 < m && map[i][j + 1] == '.')
                        union.link(i * m + j, i * m + j + 1);
                }
            }
        }

        int[] dr = {1, 0, -1, 0};
        int[] dc = {0, 1, 0, -1};

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (map[i][j] == '.')
                    continue;
                int[] roots = new int[4];
                int curRoot = 0;
                int total = 0;
                outer:
                for (int k = 0; k < 4; k++) {
                    int nr = i + dr[k], nc = j + dc[k];
                    if (nr < n && nr >= 0 && nc < m && nc >= 0 && map[nr][nc] == '.') {
                        int root = union.root(nr * m + nc);
                        for (int u = 0; u < curRoot; u++) {
                            if (root == roots[u])
                                continue outer;
                        }
                        roots[curRoot++] = root;
                        total += -union.upper[root];
                    }
                }
                map[i][j] = (char) ('0' + (total + 1) % 10);
            }
        }

        for (int i = 0; i < n; i++) {
            out.println(map[i]);
        }
    }

    class Union {
        int[] upper;

        public Union(int n) {
            upper = new int[n];
            Arrays.fill(upper, -1);
        }

        int root(int x) {
            return upper[x] < 0 ? x : (upper[x] = root(upper[x]));
        }

        boolean link(int x, int y) {
            x = root(x);
            y = root(y);
            if (x != y) {
                if (upper[y] < upper[x]) {
                    int tmp = x;
                    x = y;
                    y = tmp;
                }
                upper[x] += upper[y];
                upper[y] = x;
            }
            return x == y;
        }
    }

