class Task {
    char[][] a;
    int[][] belongTo;
    int[] sizeByCom;
    int n, m;

    int[] di = { -1, 0, 0, 1 };
    int[] dj = { 0, -1, 1, 0 };

    public void solve(InputReader in, PrintWriter out) {
        n = in.nextInt();
        m = in.nextInt();
        a = new char[n][m];
        for (int i = 0; i < n; i++) {
            a[i] = in.next().toCharArray();
        }
        belongTo = new int[n][m];
        sizeByCom = new int[(n + 2) * m];
        int count = 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (a[i][j] == '.' && belongTo[i][j] == 0) {
                    dfs(i, j, count);
                    count++;
                }
            }
        }
        char[][] res = new char[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (a[i][j] == '.') {
                    res[i][j] = '.';
                } else {
                    HashSet<Integer> set = new HashSet<Integer>();
                    int r = 1;
                    for (int k = 0; k < di.length; k++) {
                        int nextI = i + di[k];
                        int nextJ = j + dj[k];
                        if (!isValid(nextI, nextJ) || a[nextI][nextJ] == '*'
                                || set.contains(belongTo[nextI][nextJ])) {
                            continue;
                        }
                        set.add(belongTo[nextI][nextJ]);
                        r += sizeByCom[belongTo[nextI][nextJ]];
                    }
                    res[i][j] = (char) (r % 10 + '0');
                }
            }
        }
        for (int i = 0; i < n; i++) {
            out.println(new String(res[i]));
        }
    }

    void dfs(int i, int j, int count) {
        if (a[i][j] != '.' || belongTo[i][j] > 0) {
            return;
        }
        belongTo[i][j] = count;
        ++sizeByCom[count];
        for (int k = 0; k < di.length; k++) {
            int nextI = i + di[k];
            int nextJ = j + dj[k];
            if (isValid(nextI, nextJ)) {
                dfs(nextI, nextJ, count);
            }
        }
    }

    boolean isValid(int i, int j) {
        return i >= 0 && i < n && j >= 0 && j < m;
    }
}

