import java.io.BufferedReader;
import java.io.FileNotFoundException;
import java.io.FileReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.Queue;
import java.util.TreeSet;

public class C {

    static char[][] grid;
    static int[] dx = new int[]{0, 0, 1, -1};
    static int[] dy = new int[]{1, -1, 0, 0};
    static int[][] findCC;
    static int R, C;
    static ArrayList<Integer> ccSize;

    static void bfs()
    {
        findCC = new int[R][C];
        ccSize = new ArrayList<Integer>(R * C);
        int counter = 0;
        for(int i = 0; i < R; ++i)
            for(int j = 0; j < C; ++j)
                if(grid[i][j] == '.' && findCC[i][j] == 0)
                {
                    int count = 1;
                    findCC[i][j] = ++counter;
                    Queue<Cell> q = new LinkedList<Cell>();
                    q.add(new Cell(i, j));
                    while(!q.isEmpty())
                    {
                        Cell cur = q.remove();
                        for(int k = 0; k < 4; ++k)
                        {
                            int x = cur.x + dx[k], y = cur.y + dy[k];
                            if(valid(x, y) && findCC[x][y] == 0)
                            {
                                count++;
                                findCC[x][y] = counter;
                                q.add(new Cell(x, y));
                            }
                        }
                    }

                    ccSize.add(count);

                }
    }

    static boolean valid(int i, int j)
    {
        return i != -1 && j != -1 && i != R && j != C && grid[i][j] == '.';
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        R = sc.nextInt(); C = sc.nextInt();
        grid = new char[R][];
        for(int i = 0; i < R; ++i)
            grid[i] = sc.next().toCharArray();

        bfs();
        TreeSet<Integer> used;
        StringBuilder sb = new StringBuilder();
        for(int i = 0; i < R; ++i)
        {
            for(int j = 0; j < C; ++j)
                if(grid[i][j] == '.')
                    sb.append(".");
                else
                {
                    int ans = 0;
                    used = new TreeSet<Integer>();
                    for(int k = 0; k < 4; ++k)
                    {
                        int x = i + dx[k], y = j + dy[k];
                        if(valid(x, y))
                        {
                            int cc = findCC[x][y];
                            if(!used.contains(cc))
                            {
                                used.add(cc);
                                ans += ccSize.get(cc-1);

                            }
                        }
                    }

                    sb.append((ans + 1)%10);
                }
            sb.append("\n");

        }

        out.print(sb);
        out.flush();
        out.close();
    }

    static class Cell 
    {
        int x, y;

        Cell(int a, int b) { x = a; y = b; } 
    }
    static class Scanner 
    {
        StringTokenizer st;
        BufferedReader br;

        public Scanner(FileReader fileReader) throws FileNotFoundException{ br = new BufferedReader(fileReader);}

        public Scanner(InputStream s) throws FileNotFoundException{ br = new BufferedReader(new InputStreamReader(s));}

        public String next() throws IOException 
        {
            while (st == null || !st.hasMoreTokens()) 
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        public double nextDouble() throws IOException
        {
            String x = next();
            StringBuilder sb = new StringBuilder("0");
            double res = 0, f = 1;
            boolean dec = false, neg = false;
            int start = 0;
            if(x.charAt(0) == '-')
            {
                neg = true;
                start++;
            }
            for(int i = start; i < x.length(); i++)
                if(x.charAt(i) == '.')
                {
                    res = Long.parseLong(sb.toString());
                    sb = new StringBuilder("0");
                    dec = true;
                }
                else
                {
                    sb.append(x.charAt(i));
                    if(dec)
                        f *= 10;
                }
            res += Long.parseLong(sb.toString()) / f;
            return res * (neg?-1:1);
        }


        public int nextInt() throws IOException {return Integer.parseInt(next());}

