import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.HashMap;
import java.util.Map;


public class TheLabyrinth {

    static int p[][];

    static int size[][];

    static class pair {

        int x;
        int y;

        pair(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String args[]) {
        int n, m;
        InputStreamReader ir = new InputStreamReader(System.in);
        BufferedReader br = new BufferedReader(ir);
        PrintWriter pr = new PrintWriter(System.out);
        String line;
        String[] arr;
        String grid[];
        try {
            line = br.readLine();
            arr = line.split(" ");

            n = Integer.parseInt(arr[0]);
            m = Integer.parseInt(arr[1]);

            p = new int[n][m];
            size = new int[n][m];
            grid = new String[n];

            while (n != 0) {
                line = br.readLine();
                grid[grid.length - n] = line;
                n--;
            }

            for (int i = 0; i < grid.length; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i].charAt(j) == '.') {
                        p[i][j] = (m * i) + j;
                        size[i][j] = 1;
                    } else {
                        p[i][j] = -1;
                        size[i][j] = 0;
                    }

                }
            }

            for (int i = 0; i < grid.length; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i].charAt(j) == '.') {
                        dfs(grid, i, j);
                    }

                }
            }

            for (int i = 0; i < grid.length; i++) {
                StringBuilder sb = new StringBuilder();
                for (int j = 0; j < m; j++) {
                    if (grid[i].charAt(j) == '.') {
                        sb.append(grid[i].charAt(j));
                    } else {
                        sb.append(connect(grid, i, j));
                    }

                }
                System.out.println(sb);
            }

        } catch (Exception ex) {
            ex.printStackTrace();
        }
    }

    public static int find(int i, int j) {
        if (p[i][j] == ((p[i].length * i) + j)) {
            return p[i][j];
        }

        int x = p[i][j] / p[i].length;
        int y = p[i][j] - (x * p[i].length);

        return p[i][j] = find(x, y);

    }

    public static void merge(int i1, int j1, int i2, int j2) {

        int a = find(i1, j1);
        int b = find(i2, j2);

        if (a != b) {

            int x1 = a / p[i1].length;
            int y1 = a - (x1 * p[i1].length);

            int x2 = b / p[i1].length;
            int y2 = b - (x2 * p[i1].length);

            p[x1][y1] = b;
            size[x2][y2] += size[x1][y1];

        }

    }

    private static void dfs(String[] grid, int i, int j) {

        if (i < grid.length - 1 && grid[i + 1].charAt(j) == '.') {
            merge(i, j, i + 1, j);
        }
        if (j < grid[i].length() - 1 && grid[i].charAt(j + 1) == '.') {
            merge(i, j, i, j + 1);
        }

    }

    private static int connect(String[] grid, int i, int j) {

        int count = 0;
        int a;
        int x, y;
        Map<Integer, Boolean> map = new HashMap<>();

        if (i < grid.length - 1 && grid[i + 1].charAt(j) == '.') {
            a = find(i + 1, j);
            map.put(a, Boolean.TRUE);
            x = a / grid[i].length();
            y = a - (x * grid[i].length());
            count += (size[x][y] % 10);

        }
        if (j + 1 < grid[i].length() && grid[i].charAt(j + 1) == '.') {
            a = find(i, j + 1);
            if (!map.containsKey(a)) {
                map.put(a, Boolean.TRUE);
                x = a / grid[i].length();
                y = a - (x * grid[i].length());
                count += (size[x][y] % 10);
            }
        }
        if (i > 0 && grid[i - 1].charAt(j) == '.') {
            a = find(i - 1, j);
            if (!map.containsKey(a)) {
                map.put(a, Boolean.TRUE);
                x = a / grid[i].length();
                y = a - (x * grid[i].length());
                count += (size[x][y]) % 10;
            }
        }
        if (j > 0 && grid[i].charAt(j - 1) == '.') {
            a = find(i, j - 1);
            if (!map.containsKey(a)) {
                map.put(a, Boolean.TRUE);
                x = a / grid[i].length();
                y = a - (x * grid[i].length());
                count += (size[x][y] % 10);
            }
        }

        return (count + 1) % 10;

    }

}

