        for(int i = 0; i < n; i++) {
            for(int j = 0; j < m; j++) {
                filledValues[filled[i][j]]++;
            }
        }
        boolean[] used = new boolean[filler + 5];
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < m; j++) {
                if(c[i][j] == '.') {
                    continue;
                }
                int[] arr = new int[4];
                for(int k = 0; k < 4; k++) {
                    int row = i + dx[k];
                    int col = j + dy[k];
                    if(row < 0 || col < 0 || row >= n || col >= m) {
                        continue;
                    }
                    arr[k] = filled[row][col];
                }
                int sum = 0;
                for(int fillerValue : arr) {
                    if(fillerValue == 0) {
                        continue;
                    }
                    if(!used[fillerValue]) {
                        sum += filledValues[fillerValue];
                        used[fillerValue] = true;
                    }
                }
                for(int fillerValue : arr) {
                    used[fillerValue] = false;
                }
                sum++;
                sum %= 10;
                char in = (char)(sum + '0');
                c[i][j] = in;
            }
        }
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < m; j++) {
                res.append(c[i][j]);
            }
            res.append("\n");
        }
        System.out.print(res);
    }

    int[] dx = new int[] {1, 0, -1, 0};
    int[] dy = new int[] {0, 1, 0, -1};
    void dfs(int r, int c, char[][] bd, int[][] filled, int filler) {
        filled[r][c] = filler;
        for(int i = 0; i < 4; i++) {
            int row = r + dx[i];
            int col = c + dy[i];
            if(row < 0 || col < 0 || row >= bd.length || col >= bd[0].length || filled[row][col] != 0 || bd[row][col] == '*') {
                continue;
            }
            dfs(r + dx[i], c + dy[i], bd, filled, filler);
        }
    }


    String nextToken() throws Exception {
        if (stk == null || !stk.hasMoreTokens())
            stk = new StringTokenizer(br.readLine(), " ");
        return stk.nextToken();
    }

    char[] nc() throws Exception {
        return nextToken().toCharArray();
    }

    int ni() throws Exception {
        return Integer.parseInt(nextToken());
    }

    long nl() throws Exception {
        return Long.parseLong(nextToken());
    }

    double nd() throws Exception {
        return Double.parseDouble(nextToken());
    }

    int get(int l, int r, int[] a) {
        return l == 0 ? a[r] : a[r] - a[l - 1];
    }

    void shuffle(long[] a) {
        Random r = new Random();
        for(int i = 0; i < a.length; i++) {
            int idx = r.nextInt(a.length);
            long temp = a[i];
            a[i] = a[idx];
            a[idx] = temp;
        }
    }

    void reverse(long[] a) {
        for(int i = 0, j = a.length - 1; i < j; i++, j--) {
            long temp = a[i];
            a[i] = a[j];
            a[j] = temp;
        }
    }
}

