    static char[][] a;
    static boolean[][] visited;
    static int[][] connectedcom;
    static int n,m;
    static int[] dx={1,-1,0,0};
    static int[] dy={0,0,1,-1};
    static int count=0;
    static int  size=0;
    public static void main(String[] args) throws Exception
    {
        InputReader in=new InputReader(System.in);
        PrintWriter pw=new PrintWriter(System.out);
        n=in.nextInt();
        m=in.nextInt();
        a=new char[n][m];
        visited=new boolean[n][m];
        connectedcom=new int[n][m];
        for(int i=0;i<n;i++)
        {
            Arrays.fill(connectedcom[i],-1);
        }
        for(int i=0;i<n;i++)
        {
            a[i]=in.readString().toCharArray();
        }
        HashMap<Integer,Integer> map=new HashMap<Integer,Integer>();
        for(int i=0;i<n;i++)
        {
            for(int j=0;j<m;j++)
            {
                if(!visited[i][j] && a[i][j]=='.')
                {
                    size=0;
                    dfs(i,j);

                    map.put(count,size);
                    count++;
                }
            }
        }
        for(int i=0;i<n;i++)
        {
            for(int j=0;j<m;j++)
            {
                if(a[i][j]=='*')
                {
                    HashSet<Integer> temp=new HashSet<Integer>();
                    if(i-1>=0  && connectedcom[i-1][j]!=-1)
                    {
                        temp.add(connectedcom[i-1][j]);
                    }
                    if(i+1<n && connectedcom[i+1][j]!=-1)
                    {
                        temp.add(connectedcom[i+1][j]);
                    }
                    if(j-1>=0 && connectedcom[i][j-1]!=-1)
                    {
                        temp.add(connectedcom[i][j-1]);
                    }
                    if(j+1<m && connectedcom[i][j+1]!=-1)
                    {
                        temp.add(connectedcom[i][j+1]);
                    }
                    int ans=1;
                    for(int ff:temp)
                    {
                        ans+=map.get(ff);
                    }
                    ans%=10;
                    a[i][j]=(char)(ans+'0');
                }
            }
        }
        for(int i=0;i<n;i++)
        {
            for(int j=0;j<m;j++)
            {
                pw.print(a[i][j]);
            }
            pw.println();
        }

        pw.close();
    }
    static boolean valid(int x,int y)
    {
        if(x>=0 && y>=0 && x<n && y<m)
        {
            return true;
        }
        return false;
    }
    public static void dfs(int i,int j)
    {
        visited[i][j]=true;
        connectedcom[i][j]=count;
        size++;
        for(int f=0;f<4;f++)
        {

                if(valid(i+dx[f],j+dy[f]) && !visited[i+dx[f]][j+dy[f]])
                {
                    if(a[i+dx[f]][j+dy[f]]=='.')
                    {
                    dfs(i+dx[f],j+dy[f]);
                    }
                }

        }


    }






     static class InputReader {

        private InputStream stream;
        private byte[] buf = new byte[8192];
        private int curChar;
        private int snumChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int snext() {
            if (snumChars == -1)
                throw new InputMismatchException();
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (snumChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = snext();
            while (isSpaceChar(c))
                c = snext();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }

            int res = 0;

            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));

            return res * sgn;
        }

        public long nextLong() {
            int c = snext();
            while (isSpaceChar(c))
                c = snext();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = snext();
            }

            long res = 0;

            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = snext();
            } while (!isSpaceChar(c));

            return res * sgn;
        }

        public String readString() {
            int c = snext();
            while (isSpaceChar(c))
                c = snext();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = snext();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null)
                return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);
        }
    }

}

