public class c {
public static void main(String[] args) throws IOException {
    input.init(System.in);
    PrintWriter out = new PrintWriter(System.out);
    int n = input.nextInt(), m = input.nextInt();
    char[][] g = new char[n][m];
    for(int i = 0; i<n; i++) g[i] = input.next().toCharArray();
    int[][] count = new int[n][m];
    boolean[][] vis = new boolean[n][m];
    ArrayDeque<Integer> q = new ArrayDeque<Integer>();
    ArrayDeque<Integer> dq = new ArrayDeque<Integer>();
    int[] di = new int[]{0, 1, 0, -1};
    int[] dj = new int[]{1, 0, -1, 0};
    DisjointSet ds = new DisjointSet(n*m);
    for(int i = 0; i<n; i++)
        for(int j = 0; j<m; j++)
        {
            if(vis[i][j] || g[i][j] != '.') continue;
            q.add(i);
            q.add(j);
            vis[i][j] = true;
            while(!q.isEmpty())
            {
                int ati = q.poll(), atj = q.poll();
                dq.add(ati);
                dq.add(atj);
                for(int k = 0; k<4; k++)
                {
                    int ni = ati + di[k], nj = atj + dj[k];
                    if(ni < 0 || nj < 0 || ni >=n || nj >=m || vis[ni][nj] || g[ni][nj] != '.')
                    {
                        continue;
                    }
                    ds.union(m*ati+atj, m*ni+nj);
                    vis[ni][nj] = true;
                    q.add(ni);
                    q.add(nj);
                }
            }
            int size = dq.size()/2;
            while(!dq.isEmpty())
            {
                int ati = dq.poll(), atj = dq.poll();
                count[ati][atj] = size;
            }
        }
    for(int i = 0; i<n; i++)
        for(int j = 0; j<m; j++)
        {
            if(g[i][j] != '.')
            {
                int res = 1;
                boolean[] on = new boolean[4];
                for(int k = 0; k<4; k++)
                {
                    int ni = i + di[k], nj = j + dj[k];
                    if(ni < 0 || nj < 0 || ni>=n || nj>=m) continue;
                    boolean c = true;
                    on[k] = true;
                    for(int l = 0; l<k; l++)
                    {
                        if(ds.find(ni*m+nj) == ds.find((i + di[l]) * m + (j + dj[l]))) c = false;
                    }
                    if(!c) continue;
                    res += count[ni][nj];
                    res %= 10;
                }
                g[i][j] = (char)('0' + res);
            }
        }
    for(char[] A : g) out.println(new String(A));
    out.close();
}
public static class DisjointSet
{
    int[] map; 
    public DisjointSet(int n)
    {
        map = new int[n+1];
        Arrays.fill(map, -1);
    }
    public int find(int x)
    {
        if(map[x] < 0) return x;
        return map[x] = find(map[x]);
    }
    public void union(int a, int b)
    {
        int roota = find(a), rootb = find(b);
        if(roota == rootb)
            return;
        if(map[roota] < map[rootb])
        {
            map[roota] += map[rootb]; 
            map[rootb] = roota; 
        }
        else
        {
            map[rootb] += map[roota];
            map[roota] = rootb;
        }
    }
}
