        int count = 0;
        boolean[][] visited = new boolean[n][m];
        Stack<int[]> stack = new Stack();
        stack.add(new int[]{i, j});
        while (!stack.empty()) {

            int[] pop = stack.pop();
            int row = pop[0];
            int col = pop[1];
            if (visited[row][col] == false) {
                visited[row][col] = true;
                count++;
                if ((row - 1 >= 0) && (matrix[row - 1][col] == false)) {
                    stack.add(new int[]{row - 1, col});
                }
                if ((row <= n - 2) && (matrix[row + 1][col] == false)) {
                    stack.add(new int[]{row + 1, col});
                }
                if ((col - 1 >= 0) && (matrix[row][col - 1] == false)) {
                    stack.add(new int[]{row, col - 1});
                }
                if ((col <= m - 2) && (matrix[row][col + 1] == false)) {
                    stack.add(new int[]{row, col + 1});
                }
            }


        }
        if (count > 10) count = count % 10;
        if (count < 0) count = count + 10;
        return count;
    }

