public class Main {
    static boolean[][] visited;
    static boolean[][] visited1;
    static char[][] matrix;
    static int[][] update;
    static int[][] color;
    static int tot;
    static int cnt;

    static void dfs(int i, int j) {
        visited[i][j] = true;
        color[i][j] = cnt;
        if (i - 1 >= 0 && matrix[i - 1][j] == '.' && !visited[i - 1][j]) {
            ++tot; dfs(i - 1, j);
        }
        if (i + 1 < matrix.length && matrix[i + 1][j] == '.' && !visited[i + 1][j]) {
            ++tot; dfs(i + 1, j);
        }
        if (j - 1 >= 0 && matrix[i][j - 1] == '.' && !visited[i][j - 1]) {
            ++tot; dfs(i, j - 1);
        }
        if (j + 1 < matrix[0].length && matrix[i][j + 1] == '.' && !visited[i][j + 1]) {
            ++tot; dfs(i, j + 1);   // fixed: was dfs(i, j * 1);
        }
    }

    static void update(int cnt, int i, int j) {
        visited1[i][j] = true;
        update[i][j] = cnt;
        if (i - 1 >= 0 && matrix[i - 1][j] == '.' && !visited1[i - 1][j])
            update(cnt, i - 1, j);
        if (i + 1 < matrix.length && matrix[i + 1][j] == '.' && !visited1[i + 1][j])
            update(cnt, i + 1, j);
        if (j - 1 >= 0 && matrix[i][j - 1] == '.' && !visited1[i][j - 1])
            update(cnt, i, j - 1);
        if (j + 1 < matrix[0].length && matrix[i][j + 1] == '.' && !visited1[i][j + 1])
            update(cnt, i, j + 1);
    }

    static int calculate(int a, int b) {
        int ans = 1;
        HashSet<Integer> set = new HashSet<Integer>();
        if (a - 1 >= 0) {
            ans += update[a - 1][b];
            set.add(color[a - 1][b]);
        }
        if (a + 1 < update.length && !set.contains(color[a + 1][b])) {
            set.add(color[a + 1][b]);
            ans += update[a + 1][b];
        }
        if (b - 1 >= 0 && !set.contains(color[a][b - 1])) {
            set.add(color[a][b - 1]);
            ans += update[a][b - 1];
        }
        if (b + 1 < update[0].length && !set.contains(color[a][b + 1]))
            ans += update[a][b + 1];
        return ans % 10;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        matrix = new char[n][m];
        for (int i = 0; i < n; i++) {
            String str = br.readLine();
            for (int j = 0; j < m; j++) {
                matrix[i][j] = str.charAt(j);
            }
        }
        visited = new boolean[n][m];
        visited1 = new boolean[n][m];
        update = new int[n][m];
        color = new int[n][m];
        cnt = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                tot = 1;
                if (!visited[i][j] && matrix[i][j] == '.') {
                    ++cnt;
                    dfs(i, j);
                    update(tot, i, j);
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (matrix[i][j] == '*')
                    sb.append(calculate(i, j));
                else
                    sb.append('.');
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }
}

