    }
    if(j  - 1 >= 0 && matrix[i][j - 1] == '.' && !visited[i][j - 1]){
        ++tot;dfs(i,j - 1);
    }
    if(j + 1 < matrix[0].length && matrix[i][j + 1] == '.' && !visited[i][j + 1]){
        ++tot;dfs(i,j + 1);
    }
