static void update(int cnt,int i,int j){
    visited1[i][j] = true;
    update[i][j] = cnt;
    if(i - 1 >= 0 && matrix[i - 1][j] == '.' && !visited1[i - 1][j])
        update(cnt,i - 1,j);
    if(i + 1 < matrix.length && matrix[i + 1][j] == '.' && !visited1[i + 1][j])
        update(cnt,i + 1,j);
    if(j  - 1 >= 0 && matrix[i][j - 1] == '.' && !visited1[i][j - 1])
        update(cnt,i,j - 1);
    if(j + 1 < matrix[0].length && matrix[i][j + 1] == '.' && !visited1[i][j + 1])
        update(cnt,i,j + 1);
}
