        set.add(color[a - 1][b]);
    }
    if(a + 1 < update.length && !set.contains(color[a + 1][b])){
        set.add(color[a + 1][b]);
        ans += update[a + 1][b];
    }
    if(b - 1 >= 0 && !set.contains(color[a][b - 1])){
        set.add(color[a][b - 1]);
        ans += update[a][b - 1];
    }
    if(b + 1 < update[0].length && !set.contains(color[a][b + 1]))
        ans += update[a][b + 1];
    return ans % 10;
}
