import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.Map;
import java.util.Queue;
import java.util.Set;


public class C {
	private static final char E = '.';
	private static final char O = '*';

	private static final int[] X = {1, -1,  0, 0};
	private static final int[] Y = {0,  0, -1, 1};

	public static void main(String[] args) throws Exception {
		try (FastScanner s = new FastScanner(System.in);
				PrintWriter pw = new PrintWriter(System.out);) {
			final int n = s.nextInt();
			final int m = s.nextInt();
			final String[] board = new String[n];
			for (int i = 0; i < n; ++i) {
				board[i] = s.next();
			}
			final Map<Integer, Integer> map = new HashMap<>();
			final int [][] color = new int[n][m];
			int currentColor = 1;
			for (int i = 0; i < n; ++i) {
				for (int j = 0; j < m; ++j) {
					if (board[i].charAt(j) == E) {
						if (color[i][j] == 0) {
							final int newColor = currentColor++;
							int size = 1;
							final Queue<int[]> queue = new LinkedList<>();
							color[i][j] = newColor;
							queue.offer(new int[] {i, j});
							while (!queue.isEmpty()) {
								final int[] top = queue.poll();
								for (int d = 0; d < 4; ++d) {
									final int ni = top[0] + X[d];
									final int nj = top[1] + Y[d];
									if (ni >= n || 
											ni < 0 || 
											nj >= m || 
											nj < 0 ||
											board[ni].charAt(nj) != E || 
											color[ni][nj] != 0) {
										continue;
									}
									color[ni][nj] = newColor;
									size++;
									queue.offer(new int[]{ni, nj});
								}
							}
							map.put(newColor, size);
						}
					}
				}
			}
			for (int i = 0; i < n; ++i) {
				for (int j = 0; j < m; ++j) {
					if (board[i].charAt(j) == E) {
						pw.print(E);
					} else {
						final Set<Integer> colors = new HashSet<>();
						for (int d = 0; d < 4; ++d) {
							final int ni = i + X[d];
							final int nj = j + Y[d];
							if (ni >= n ||
									ni < 0 ||
									nj >= m ||
									nj < 0 ||
									board[ni].charAt(nj) != E) {
								continue;
							}
							colors.add(color[ni][nj]);
						}
						int size = 1;
						for (int c : colors) {
							size += map.get(c);
						}
						size %= 10;
						pw.print(size);
					}
				}
				pw.println();
			}
		}
	}

	private static final class FastScanner implements AutoCloseable {
		private final BufferedReader reader;
		private String[] tokens;
		private int next;

		FastScanner(InputStream is) {
			reader = new BufferedReader(new InputStreamReader(is));
		}

		int nextInt() throws IOException {
			return Integer.parseInt(next());
		}

		String next() throws IOException {
			if (tokens == null || next == tokens.length) {
				tokens = reader.readLine().split(" ");
				next = 0;
			}
			return tokens[next++];
		}

		@Override
		public void close() throws Exception {
			reader.close();
		}
	}
}

