public class TheLabyrinth {

    public static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(String s) {
            try {
                br = new BufferedReader(new FileReader(s));
            } catch (FileNotFoundException e) {

                e.printStackTrace();
            }
        }

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String nextToken() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {

                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        long nextLong() {
            return Long.parseLong(nextToken());
        }

        double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();

        int n = sc.nextInt();
        int m = sc.nextInt();

        char[][] graph = new char[n][m];
        int[][] component = new int[n][m];
        boolean[][] visited = new boolean[n][m];

        for (int i = 0; i < n; ++i) {
            String s = sc.nextToken();
            for (int j = 0; j < m; ++j) {
                graph[i][j] = s.charAt(j);
            }
        }

        Map<Integer, Integer> components = new HashMap<>();
        int c = 1;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (graph[i][j] == '.' && !visited[i][j]) {
                    int result = dfs(graph, i, j, visited, component, c);
                    components.put(c, result);
                    c++;
                }
            }
        }

        PrintWriter pw = new PrintWriter(System.out);
        for (int i = 0; i < n; ++i) {
            StringBuffer sb = new StringBuffer();
            for (int j = 0; j < m; ++j) {
                if (graph[i][j] == '*') {
                    Map<Integer, Boolean> has = new HashMap<>();
                    int result = 0;
                    if (i > 0) {
                        if (component[i - 1][j] != 0 && !has.containsKey(component[i - 1][j])) {
                            has.put(component[i - 1][j], true);
                            result += components.get(component[i - 1][j]);
                        }
                    }
                    if (i < graph.length - 1) {
                        if (component[i + 1][j] != 0 && !has.containsKey(component[i + 1][j])) {
                            has.put(component[i + 1][j], true);
                            result += components.get(component[i + 1][j]);
                        }
                    }
                    if (j > 0) {
                        if (component[i][j - 1] != 0 && !has.containsKey(component[i][j - 1])) {
                            has.put(component[i][j - 1], true);
                            result += components.get(component[i][j - 1]);
                        }
                    }
                    if (j < graph[0].length - 1) {
                        if (component[i][j + 1] != 0 && !has.containsKey(component[i][j + 1])) {
                            has.put(component[i][j + 1], true);
                            result += components.get(component[i][j + 1]);
                        }
                    }
                    graph[i][j] = (char) (((result + 1) % 10) + '0');
                }
                sb.append(graph[i][j]);
            }
            sb.append('\n');
            pw.print(sb.toString());
            pw.flush();
        }
    }

    private static int dfs(char[][] graph, int i, int j, boolean[][] visited, int[][] component, int c) {
        if (visited[i][j] || graph[i][j] == '*') {
            return 0;
        }
        else {
            int size = 1;

            visited[i][j] = true;
            component[i][j] = c;
            if (i > 0) {
                size += dfs(graph, i - 1, j, visited, component, c);
            }
            if (i < graph.length - 1) {
                size += dfs(graph, i + 1, j, visited, component, c);
            }
            if (j > 0) {
                size += dfs(graph, i, j - 1, visited, component, c);
            }
            if (j < graph[0].length - 1) {
                size += dfs(graph, i, j + 1, visited, component, c);
            }

            return size;
        }
    }
}

