public class test {
    private static void compare(String a, String b) {
        int i = 0, j = 0;
        while (i < a.length() && a.charAt(i) == '0') i++;
        while (j < b.length() && b.charAt(j) == '0') j++;
        if (a.length() - i > b.length() - j) {
            System.out.println(">");
            return;
        }
        if (a.length() - i < b.length() - j) {
            System.out.println("<");
            return;
        }
        while (i < a.length()) {
            if (a.charAt(i) < b.charAt(j)) {
                System.out.println("<");
                return;
            }
            if (a.charAt(i) > b.charAt(j)) {
                System.out.println(">");
                return;
            }
            i++; j++;
        }
        System.out.println("=");
    }

    private static void dinner(int[][] cs) {
        int gmax = 0;
        for (int i = 0; i < cs.length; i++) {
            int lmin = Integer.MAX_VALUE;
            for (int j = 0; j < cs[0].length; j++)
                lmin = Math.min(lmin, cs[i][j]);
            gmax = Math.max(gmax, lmin);
        }
        System.out.println(gmax);
    }

    private static int count = 0;
    private static void dfs(char[][] board, int i, int j) {
        if (i < 0 || i >= board.length || j < 0 || j >= board[0].length || board[i][j] != '.')
            return;
        count++;
        board[i][j] = '#';
        dfs(board, i - 1, j);
        dfs(board, i + 1, j);
        dfs(board, i, j - 1);
        dfs(board, i, j + 1);
    }
    private static void clear(char[][] board, int i, int j) {
        if (i < 0 || i >= board.length || j < 0 || j >= board[0].length || board[i][j] != '#')
            return;
        board[i][j] = '.';
        clear(board, i - 1, j);
        clear(board, i + 1, j);
        clear(board, i, j - 1);
        clear(board, i, j + 1);
    }

    private static int find(int[] pa, int cur) {
        int par = pa[cur];
        while (cur != par) {
            pa[cur] = pa[par];
            cur = pa[par];
            par = pa[par];
        }
        return cur;
    }

    private static void union(int[] pa, int[] sz, int r1, int r2) {
        if (sz[r1] >= sz[r2]) {
            pa[r2] = r1;
            sz[r1] += sz[r2];
        } else {
            pa[r1] = r2;
            sz[r2] += sz[r1];
        }
    }

    private static int[][] moves = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    private static void labyrinth(char[][] board) {
        int n = board.length, m = board[0].length;
        int[] pa = new int[n * m];
        int[] sz = new int[n * m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (board[i][j] == '.') {
                    pa[i * m + j] = i * m + j;
                    sz[i * m + j] = 1;
                    if (i > 0 && board[i - 1][j] == '.') {
                        int r1 = find(pa, i * m + j);
                        int r2 = find(pa, (i - 1) * m + j);
                        if (r1 != r2) union(pa, sz, r1, r2);
                    }
                    if (j > 0 && board[i][j - 1] == '.') {
                        int r1 = find(pa, i * m + j);
                        int r2 = find(pa, i * m + j - 1);
                        if (r1 != r2) union(pa, sz, r1, r2);
                    }
                }
            }
        }
        for (int i = 0; i < n; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < m; j++) {
                if (board[i][j] == '.') {
                    sb.append('.');
                } else {
                    int count = 1;
                    Set<Integer> set = new HashSet<>();
                    for (int k = 0; k < moves.length; k++) {
                        int r = i + moves[k][0], c = j + moves[k][1];
                        if (r >= 0 && r < n && c >= 0 && c < m && board[r][c] == '.') {
                            int rr = find(pa, r * m + c);
                            if (!set.contains(rr)) {
                                set.add(rr);
                                count += sz[rr];
                            }
                        }
                    }
                    sb.append(count % 10);
                }
            }
            System.out.println(sb.toString());
        }
    }

    public static void main(String[] args) throws InterruptedException {
        try {
            BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
            String[] nm = br.readLine().split(" ");
            int n = Integer.parseInt(nm[0]), m = Integer.parseInt(nm[1]);
            char[][] board = new char[n][m];
            for (int i = 0; i < n; i++)
                board[i] = br.readLine().toCharArray();
            labyrinth(board);
        } catch (IOException io) {
            io.printStackTrace();
        }
    }
}

