                                count += map.get(visited[a][b]);
                                codes.add(visited[a][b]);
                            }
                        }
                    }
                }
                count++;
                builder.append(count == 0 ? "." : (count % 10));
                A[i][j] = false;
            }
        }
        return joinValues(answer, "\n");
    }



    private static int getCount(int i, int j, int[][] visited , int code){
        int count = 0;
        Stack<Pair> stack = new Stack<>();
        stack.push(new Pair(i, j));
        while(!stack.empty()){
            Pair cell = stack.pop();
            if(visited[cell.x][cell.y] == 0){
                visited[cell.x][cell.y] = code;
                count++;
                for(int a = cell.x-1; a <= cell.x + 1; a++) {
                    for (int b = cell.y - 1; b <= cell.y + 1; b++) {
                        if(visited[a][b] != 0 || !A[a][b]){
                            continue;
                        }
                        if ((a == cell.x && b == cell.y)) {
                            continue;
                        }
                        if(a == cell.x || b == cell.y) {
                            stack.push(new Pair(a, b));
                        }
                    }
                }
            }
        }
        return count;
    }

