public class C {
	public static void main(String[] args) throws IOException{

		BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
		PrintWriter out = new PrintWriter(System.out);	
		String[] nums = in.readLine().split(" ");
		int row = Integer.parseInt(nums[0]);
		int col = Integer.parseInt(nums[1]);
		boolean[][] block = new boolean[row][col];
		for(int y = 0; y<row; y++){
			String s = in.readLine();
			for(int x= 0; x<col; x++){
				block[y][x] = s.charAt(x)=='*';
			}
		}
		int[][] pool = new int[row][col];
		for(int[] ar : pool){
			Arrays.fill(ar,-1);
		}
		int cur = 0;
		int[] size = new int[row*col+1];
		int[] dX = {1,-1,0,0};
		int[] dY = {0,0,1,-1};
		for(int y = 0; y<row; y++){
			for(int x = 0; x<col; x++){
				if(!block[y][x] && pool[y][x]==-1){
					cur++;
					ArrayList<Integer> yc = new ArrayList<Integer>();
					ArrayList<Integer> xc = new ArrayList<Integer>();
					yc.add(y);
					xc.add(x);
					int count = 0;
					pool[y][x] = cur;
					while(yc.size()>0){

						count++;
						int cY = yc.remove(0);
						int cX = xc.remove(0);
						for(int i =0 ; i<4; i++){
							int nY = cY+dY[i];
							int nX = cX+dX[i];
							if(nY>=0 &&nY<row && nX>=0 && nX<col && pool[nY][nX]==-1 && !block[nY][nX]){
								yc.add(nY);
								xc.add(nX);
								pool[nY][nX] = cur;
							}
						}
					}
					size[cur] = count;
				}
			}
		}
		for(int y = 0; y<row; y++){

			StringBuilder s = new StringBuilder("");
			for(int x = 0; x<col; x++){
				if(block[y][x]){
					TreeSet<Integer> set = new TreeSet<Integer>();
					for(int i = 0; i<4; i++){
						int nY = y+dY[i];
						int nX = x+dX[i];
						if(nY>=0 &&nY<row && nX>=0 && nX<col && pool[nY][nX]!=-1){
							set.add(pool[nY][nX]);
						}
					}
					int tot = 1;
					for(int num : set){
						tot += size[num];
					}
					s.append(tot%10);
				}
				else{
					s.append(".");
				}

			}
			out.println(s.toString());
		}
		out.flush();
		out.close();
	}
}

