public class Solution {
    private static final int[] X = { -1, 0, 1, 0 };
    private static final int[] Y = { 0, 1, 0, -1 };

    private static void dfs(char[][] array, int row, int column, int[][] num,
            int[] size, int current) {
        if (row >= array.length || row < 0 || column < 0
                || column >= array[0].length) {
            return;
        }

        if (array[row][column] == '*') {
            return;
        }

        if (num[row][column] != -1) {
            return;
        }

        size[current]++;
        num[row][column] = current;
        for (int i = 0; i < X.length; i++) {
            dfs(array, row + X[i], column + Y[i], num, size, current);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(
                System.in));
        String[] nm = reader.readLine().split(" ");
        int n = Integer.parseInt(nm[0]);
        int m = Integer.parseInt(nm[1]);

        char[][] array = new char[n][m];
        for (int i = 0; i < n; i++) {
            array[i] = reader.readLine().toCharArray();
        }

        int[] size = new int[n * m];
        int[][] num = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                num[i][j] = -1;
            }
        }
        int current = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (num[i][j] == -1 && array[i][j] == '.') {
                    dfs(array, i, j, num, size, current);
                    current++;
                }
            }
        }

        char[][] res = new char[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (array[i][j] != '.') {
                    int sum = 1;
                    Set<Integer> temp = new HashSet<>();
                    for (int k = 0; k < X.length; k++) {
                        int xx = i + X[k];
                        int yy = j + Y[k];
                        if (xx >= array.length || xx < 0 || yy < 0
                                || yy >= array[0].length) {
                            continue;
                        }
                        if (array[xx][yy] == '*') {
                            continue;
                        }
                        temp.add(num[xx][yy]);
                    }
                    for (Integer e : temp) {
                        sum += size[e];
                    }
                    res[i][j] = (char) ((sum % 10) + '0');
                } else {
                    res[i][j] = array[i][j];
                }
            }
        }
        PrintWriter pw = new PrintWriter(System.out);
        for (int i = 0; i < n; i++) {
            pw.println(String.valueOf(res[i]));
        }
        pw.close();
    }
}

