public class ProC {
    static int n,m,ct,c,x,y,a;
    static String ss;
    static int[] xx={0,0,1,-1},yy={1,-1,0,0};
    static int[] mm=new int[1000005];
    static int[][] vis=new int[1005][1005];
    static char[][] map=new char[1005][1005];
    static Map<Integer,Integer> mp=new HashMap<Integer,Integer>();
    static void dfs(int i,int j)
    {
        vis[i][j]=c;ct++;
        for(int k=0;k<4;k++)
        {
            x=i+xx[k];y=j+yy[k];
            if(0<x&&x<=n&&0<y&&y<=m&&vis[x][y]==0&&map[x][y]=='.')
                dfs(x,y);
        }
    }
    static PrintWriter out=new PrintWriter(new OutputStreamWriter(System.out));

    public static void main(String[] args) {
        Scanner in=new Scanner(System.in);
        n=in.nextInt();m=in.nextInt();
        in.nextLine();
        for(int i=1;i<=n;i++)
        {
            ss=in.nextLine();
            for(int j=0;j<m;j++)
                map[i][j+1]=ss.charAt(j);
        }
        for(int i=1;i<=n;i++)
        for(int j=1;j<=m;j++)
        {
            if(vis[i][j]==0&&map[i][j]=='.') 
            { 
                ct=0;c++;dfs(i,j);
                mm[c]=ct;
            }
        }
        for(int i=1;i<=n;i++)
        {
            for(int j=1;j<=m;j++)
            {
                if(map[i][j]=='.') out.print(".");
                else
                {
                    a=0;mp.clear();
                    for(int k=0;k<4;k++)
                    {
                        x=i+xx[k];y=j+yy[k];
                        if(0<x&&x<=n&&0<y&&y<=m)
                        {
                            c=vis[x][y];
                            if(mp.get(c)==null) { mp.put(c,1);a+=mm[c];}
                        }
                    }
                    a++;a%=10;
                    out.print(a);
                }
            }
            out.println();
        }
        out.flush();
    }
}

