                        { ccSize++; visited[ii+1][jj] = true; dfs.push(m*(ii+1) + jj); }
                    if ( 0 < jj  && b[ii][jj-1] == '.' && !visited[ii][jj-1]) 
                        { ccSize++; visited[ii][jj-1] = true; dfs.push(m*ii + jj - 1); }
                    if (jj < m-1 && b[ii][jj+1] == '.' && !visited[ii][jj+1]) 
                        { ccSize++; visited[ii][jj+1] = true; dfs.push(m*ii + jj + 1); }
                }
                cc2size.add(ccSize);
            }
        }



        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (b[i][j] == '.') out.append('.');
                else {
                    List<Integer> comps = new ArrayList<>(4);
                    if (0 < i   && b[i-1][j] == '.' && !comps.contains(ccnumber[i-1][j])) 
                        comps.add(ccnumber[i-1][j]);
                    if (i < n-1 && b[i+1][j] == '.' && !comps.contains(ccnumber[i+1][j]))
                        comps.add(ccnumber[i+1][j]);
                    if (0 < j   && b[i][j-1] == '.' && !comps.contains(ccnumber[i][j-1]))
                        comps.add(ccnumber[i][j-1]);
                    if (j < m-1 && b[i][j+1] == '.' && !comps.contains(ccnumber[i][j+1]))
                        comps.add(ccnumber[i][j+1]);

                    int c = 1;
                    for (int _c : comps)
                        c += cc2size.get(_c);

                    out.append((char) ('0' + (c % 10)));
                }
            }
            out.append('\n');
        }
        System.out.print(out.toString());
    }



    public static class Scanner {
        BufferedReader br;
        StringTokenizer st;

        public Scanner(Reader in) {
            br = new BufferedReader(in);
        }

        public Scanner() { this(new InputStreamReader(System.in)); }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }




        String readNextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

}

