public class TheLabyrinth {

	static char[][] arr;
	static int dr[] = { 1, 0, -1, 0 };
	static int dc[] = { 0, 1, 0, -1 };
	static Point[][] source;
	static int[][] cc;

	public static int floodfill(int r, int c, char X, Point s) {
		if (r < 0 || r >= arr.length || c < 0 || c >= arr[0].length)
			return 0;
		if (arr[r][c] != X)
			return 0;
		int ans = 1;
		arr[r][c] = ',';
		source[r][c] = s;
		for (int i = 0; i < 4; i++) {
			ans += floodfill(r + dr[i], c + dc[i], X, s);
		}

		return ans;
	}

	public static int count(int i, int j){
		ArrayList<Point>list = new ArrayList<>();
		int sum = 1;
		for(int l = 0; l<4;l++){
			int r = i+dr[l];
			int c = j+dc[l];
			if (r < 0 || r >= arr.length || c < 0 || c >= arr[0].length||arr[r][c]=='*'||list.contains(source[r][c]))continue;
			sum+=cc[source[r][c].x][source[r][c].y];
			list.add(source[r][c]);
		}
		return sum%10;
	}
	public static void main(String[] args) throws IOException {
		Scanner sc = new Scanner(System.in);
		PrintWriter pw = new PrintWriter(System.out);
