        for (int i = 0; i < n; i++) {
            char[] line = new char[m];
            for (int j = 0; j < m; j++) {
                if (matrix[i][j] == 0) {
                    int result = 1;
                    HashSet<Integer> visited = new HashSet<>();
                    visited.add(0);
                    if (i > 0 && !visited.contains(matrix[i - 1][j])) {
                        result += sizes.get(matrix[i - 1][j] - 1);
                        visited.add(matrix[i - 1][j]);
                    }
                    if (i < n - 1 && !visited.contains(matrix[i + 1][j])) {
                        result += sizes.get(matrix[i + 1][j] - 1);
                        visited.add(matrix[i + 1][j]);
                    }
                    if (j > 0 && !visited.contains(matrix[i][j - 1])) {
                        result += sizes.get(matrix[i][j - 1] - 1);
                        visited.add(matrix[i][j - 1]);
                    }
                    if (j < m - 1 && !visited.contains(matrix[i][j + 1])) {
                        result += sizes.get(matrix[i][j + 1] - 1);
                        visited.add(matrix[i][j + 1]);
                    }

                    line[j] = (char)('0' + (result % 10));
                } else {
                    line[j] = '.';
                }
            }
            System.out.println(new String(line));
        }
    }

    private static int dfs(int[][] matrix, int currentIndex, int x, int y) {
        if (x < 0 || y < 0 || x >= matrix.length || y >= matrix[0].length || matrix[x][y] != -1)
            return 0;

