        return 1 +
                dfs(matrix, currentIndex, x + 1, y) +
                dfs(matrix, currentIndex, x - 1, y) +
                dfs(matrix, currentIndex, x, y + 1) +
                dfs(matrix, currentIndex, x, y - 1);
    }

