		    counter = 0;
		    dfs(i, j);
		    floodfill(i, j);
		    curColor++;
		}
	    }
	}

	for (int i = 0; i < n; i++) {
	    for (int j = 0; j < m; j++) {
		if (grid[i][j] == '*') {
		    TreeSet<Integer> ts = new TreeSet<>();
		    int sum = 0;
		    for (int k = 0; k < 4; k++) {
			int newI = i + dx[k];
			int newJ = j + dy[k];

			if (valid(newI, newJ)) {
			    if (!ts.contains(colors[newI][newJ])) {
				sum += size[newI][newJ];
				ts.add(colors[newI][newJ]);
			    }
			}    
		    }

		    out.print(++sum%10);
		}
		else
		    out.print('.');
	    }
	    out.println();
	}

	out.flush();
	out.close();
    }

    private static void dfs(int i, int j) {
	visited[i][j] = true;
	counter++;

	for (int k = 0; k < 4; k++) {
	    int newI = i + dx[k];
	    int newJ = j + dy[k];

	    if (valid(newI, newJ) && !visited[newI][newJ])
		dfs(newI, newJ);
	}
    }

