	colors[i][j] = curColor;
	size[i][j] = counter;

	for (int k = 0; k < 4; k++) {
	    int newI = i + dx[k];
	    int newJ = j + dy[k];

	    if (valid(newI, newJ) && colors[newI][newJ] == 0)
		floodfill(newI, newJ);
	}
    }

