class RangeMinimumSegTree{
	int[] tree;
	int[] idx;
	int size;
	int len;
	int n;
	public RangeMinimumSegTree(int n){
		int beki = 1;
		while(beki < n) beki <<= 1;
		len = beki<<1;
		this.n = n;
		tree = new int[len];
		idx = new int[len];
		Arrays.fill(tree, Integer.MAX_VALUE);
		size = beki;
	}
	public void set(int id, int x){
		int i = id | size;
		tree[i] = x;
		idx[i] = id;
		for(i>>=1; i>0; i>>=1){

			if(tree[i<<1]<tree[(i<<1)+1]){
				tree[i] = tree[i<<1];
				idx[i] = idx[i<<1];
			}else{
				tree[i] = tree[(i<<1)+1];
				idx[i] = idx[(i<<1)+1];
			}
		}
	}
	public int get(int id){
		return tree[id|size];
	}

	public long min(int left, int right){
		int res = Integer.MAX_VALUE;
		left |= size;
		right|= size;
		right++;
		int id = 0;
		while(left < right){
			if((right&1) == 1){

				if(res > tree[--right]){
					res = tree[right];
					id = idx[right];
				}
			}
			if((left&1) == 1){

				if(res > tree[left]){
					res = tree[left];
					id = idx[left];
				}left++;
			}
			right >>= 1;
			left >>= 1;
		}
		return (long)id<<32|res;
	}
}

