import java.io.*;
import java.util.*;

public class Solution {

    static class Point {
        int x;
        int y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static boolean isVertical(Point[] points) {
        int x = points[0].x;
        for (Point p : points)
            if (p.x != x) return false;
        return true;
    }

    static boolean isHorizontal(Point[] points) {
        int y = points[0].y;
        for (Point p : points)
            if (p.y != y) return false;
        return true;
    }

    static boolean midy(Point a, Point b, Point c) {
        if ((a.y < b.y && a.y > c.y) || (a.y < c.y && a.y > b.y))
            return true;
        else
            return false;
    }

    static boolean midx(Point a, Point b, Point c) {
        if ((a.x < b.x && a.x > c.x) || (a.x < c.x && a.x > b.x))
            return true;
        else
            return false;
    }

    static void solve(InputReader in, OutputWriter out) {
        Point[] points = new Point[3];
        for (int i = 0; i < 3; i++)
            points[i] = new Point(in.nextInt(), in.nextInt());

        if (isHorizontal(points) || isVertical(points)) {
            out.print(1);
            return;
        }

        if ((points[0].x == points[1].x && !midy(points[2], points[0], points[1]))
                || (points[0].x == points[2].x && !midy(points[1], points[0], points[2]))
                || (points[1].x == points[2].x && !midy(points[0], points[1], points[2]))) {
            out.print(2);
            return;
        }

        if ((points[0].y == points[1].y && !midx(points[2], points[0], points[1]))
                || (points[0].y == points[2].y && !midx(points[1], points[0], points[2]))
                || (points[1].y == points[2].y && !midx(points[0], points[1], points[2]))) {
            out.print(2);
            return;
        }

        out.print(3);
    }

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        solve(in, out);
        in.close();
        out.close();
    }

    static class InputReader {
        BufferedReader br;
        StringTokenizer st;

        InputReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
            st = null;
        }

        String nextLine() {
            String line = null;
            try {
                line = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return line;
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String line = nextLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        void close() {
            try {
                br.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    static class OutputWriter {
        BufferedWriter bw;

        OutputWriter(OutputStream os) {
            bw = new BufferedWriter(new OutputStreamWriter(os));
        }

        void print(int i) {
            print(Integer.toString(i));
        }

        void println(int i) {
            println(Integer.toString(i));
        }

        void print(long l) {
            print(Long.toString(l));
        }

        void println(long l) {
            println(Long.toString(l));
        }

        void print(double d) {
            print(Double.toString(d));
        }

        void println(double d) {
            println(Double.toString(d));
        }

        void print(boolean b) {
            print(Boolean.toString(b));
        }

        void println(boolean b) {
