public class Codechef
{
    static class InputReader {

		private InputStream stream;
		private byte[] buf = new byte[8192];
		private int curChar;
		private int snumChars;
		private SpaceCharFilter filter;

		public InputReader(InputStream stream) {
			this.stream = stream;
		}

		public int snext() {
			if (snumChars == -1)
				throw new InputMismatchException();
			if (curChar >= snumChars) {
				curChar = 0;
				try {
					snumChars = stream.read(buf);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (snumChars <= 0)
					return -1;
			}
			return buf[curChar++];
		}

		public int nextInt() {
			int c = snext();
			while (isSpaceChar(c))
				c = snext();
			int sgn = 1;
			if (c == '-') {
				sgn = -1;
				c = snext();
			}

			int res = 0;

			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res *= 10;
				res += c - '0';
				c = snext();
			} while (!isSpaceChar(c));

			return res * sgn;
		}

		public long nextLong() {
			int c = snext();
			while (isSpaceChar(c))
				c = snext();
			int sgn = 1;
			if (c == '-') {
				sgn = -1;
				c = snext();
			}

			long res = 0;

			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res *= 10;
				res += c - '0';
				c = snext();
			} while (!isSpaceChar(c));

			return res * sgn;
		}

		public String readString() {
			int c = snext();
			while (isSpaceChar(c))
				c = snext();
			StringBuilder res = new StringBuilder();
			do {
				res.appendCodePoint(c);
				c = snext();
			} while (!isSpaceChar(c));
			return res.toString();
		}

		public boolean isSpaceChar(int c) {
			if (filter != null)
				return filter.isSpaceChar(c);
			return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
		}

		public interface SpaceCharFilter {
			public boolean isSpaceChar(int ch);
		}
	}
	public static int[][] d = new int[3][2];
	public static boolean is(int x,int y,int z){
	    if(Math.min(x,y)<=z && Math.max(x,y)>=z)return true;
	    return false;
	}
	public static boolean f(int a,int b,int c){
	    if((d[a][0] == d[c][0] || d[b][0] == d[c][0]) && is(d[a][1],d[b][1],d[c][1])||
	    (d[a][1] == d[c][1] || d[b][1] == d[c][1]) && is(d[a][0],d[b][0],d[c][0]))return true;
	    return false;
	}
	public static void main (String[] args) throws java.lang.Exception
	{
		InputReader in = new InputReader(System.in);
		int x1 = d[0][0] = in.nextInt();
		int y1 = d[0][1] = in.nextInt();
		int x2 = d[1][0] = in.nextInt();
		int y2 = d[1][1] = in.nextInt();
		int x3 = d[2][0] = in.nextInt();
