public class Arena {

    public static void main(String[] args) {
        MyScanner input = new MyScanner();
        PrintWriter output = new PrintWriter(new BufferedOutputStream(System.out));

        Point first = new Point(input.nextLong(), input.nextLong());
        Point second = new Point(input.nextLong(), input.nextLong());
        Point third = new Point(input.nextLong(), input.nextLong());

        output.println(getResult(first, second, third));
        output.close();
    }

    private static int getResult(Point first, Point second, Point third) {
        // 1 segment – all points share the same x or the same y
        if ((first.a == second.a && second.a == third.a) ||
            (first.b == second.b && second.b == third.b)) {
            return 1;
        }

        // 2 segments – one of the points lies on a segment between the other two
        if (first.a == second.a && between(first.b, second.b, third.b)) return 2;
        if (first.a == third.a && between(first.b, third.b, second.b)) return 2;
        if (second.a == third.a && between(second.b, third.b, first.b)) return 2;

        if (first.b == second.b && between(first.a, second.a, third.a)) return 2;
        if (first.b == third.b && between(first.a, third.a, second.a)) return 2;
        if (second.b == third.b && between(second.a, third.a, first.a)) return 2;

        return 3;
    }

    /** Returns true if v lies between lo and hi (inclusive). */
    private static boolean between(long lo, long hi, long v) {
        return v >= Math.min(lo, hi) && v <= Math.max(lo, hi);
    }

    private static void swap(Point p1, Point p2) {
        Point temp = p1;
        p1 = p2;
        p2 = temp;
    }

    private static class Point {
        private long a;
        private long b;

