public class Main {

	static int MOD = 1000 * 1000 * 1000 + 7;

	public static void main(String[] args) {

		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		InputReader in = new InputReader(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		solve(in, out);
		out.close();
		System.exit(0);
	}

	private static void solve(InputReader in, PrintWriter out) {

		int[][] tab = new int[3][2];
		for (int i = 0; i < 3; i++) {
			tab[i][0] = in.nextInt();
			tab[i][1] = in.nextInt();
		}

		int res = 3;

		if (tab[0][0] == tab[1][0] && tab[1][0] == tab[2][0]) {
			res = 1;
		}
		if (tab[0][1] == tab[1][1] && tab[1][1] == tab[2][1]) {
			res = 1;
		}

		if (res == 1) {
			out.print(res);
			return;
		}

		if (ok(tab)) {
			out.print(2);
			return;
		}

		for (int i = 0; i < 3; i++) {
			int tmp = tab[i][0];
			tab[i][0] = tab[i][1];
			tab[i][1] = tmp;
		}

		if (ok(tab)) {
			out.print(2);
			return;
		}

		out.print(3);

	}

	private static boolean ok(int[][] tab) {

		for (int i = 0; i < tab.length; i++) {
			for (int j = i + 1; j < tab.length; j++) {
				if (tab[i][0] != tab[j][0]) {
					continue;
				}
				int x = tab[i][0];
				for (int k = 0; k < 3; k++) {
					if (tab[k][0] == x) {
						continue;
					}

					int y = tab[k][1];
					if (y >= Math.min(tab[i][1], tab[j][1]) && y <= Math.max(tab[i][1], tab[j][1])) {
						return true;
					}
				}

			}
		}

		return false;
	}



	static class InputReader {
		public BufferedReader reader;
		public StringTokenizer tokenizer;

