    private static void solve(Reader in, PrintWriter out) {
        int n = 3;
        Point[] a = new Point[n];
        for (int i = 0; i < n; i++) {
            a[i] = new Point(in.nextInt(), in.nextInt());
        }

        Set<Integer> cx = new HashSet<>();
        Set<Integer> cy = new HashSet<>();
        for (int i = 0; i < n; i++) {
            cx.add(a[i].x);
            cy.add(a[i].y);
        }

        if (Math.min(cx.size(), cy.size()) != 2) {
            out.println(Math.min(cx.size(), cy.size()));
            return;
        }

        if (cx.size() == 2) {
            Arrays.sort(a, Comparator.comparingInt(o -> o.x));
            if (a[1].x == a[0].x) {
                int left = Math.min(a[0].y, a[1].y);
                int right = Math.max(a[0].y, a[1].y);
                if (a[2].y <= left || a[2].y >= right) {
                    out.println(2);
                } else {
                    out.println(3);
                }
            } else {
                int left = Math.min(a[2].y, a[1].y);
                int right = Math.max(a[2].y, a[1].y);
                if (a[0].y <= left || a[0].y >= right) {
