	static class Task {

		public void solve(int testNumber, FastReader sc, PrintWriter pw) {
			int[][] arr = {{sc.nextInt(),sc.nextInt()},{sc.nextInt(),sc.nextInt()},{sc.nextInt(),sc.nextInt()}};
			// all three points share the same x‑coordinate or the same y‑coordinate → 1 segment
			if (arr[0][0] == arr[1][0] && arr[0][0] == arr[2][0]) {
				pw.println(1);
				return;
			}
			if (arr[0][1] == arr[1][1] && arr[0][1] == arr[2][1]) {
				pw.println(1);
				return;
			}
			// check whether some point is the "corner": it shares its x with one point
			// and its y with another point
			boolean canTwo = false;
			for (int i = 0; i < 3; i++) {
				for (int j = 0; j < 3; j++) {
					if (j == i) continue;
					for (int k = 0; k < 3; k++) {
