        }
        public double scanDouble()throws IOException
        {
            double doub=0;
            int n=scan();
            while(isWhiteSpace(n))
            n=scan();
            int neg=1;
            if(n=='-')
            {
                neg=-1;
                n=scan();
            }
            while(!isWhiteSpace(n)&&n!='.')
            {
                if(n>='0'&&n<='9')
                {
                    doub*=10;
                    doub+=n-'0';
                    n=scan();
                }
                else throw new InputMismatchException();
            }
            if(n=='.')
            {
                n=scan();
                double temp=1;
                while(!isWhiteSpace(n))
                {
                    if(n>='0'&&n<='9')
                    {
                        temp/=10;
                        doub+=(n-'0')*temp;
                        n=scan();
                    }
                    else throw new InputMismatchException();
                }
            }
            return doub*neg;
        }
        public String scanString()throws IOException
        {
            StringBuilder sb=new StringBuilder();
            int n=scan();
            while(isWhiteSpace(n))
            n=scan();
            while(!isWhiteSpace(n))
            {
                sb.append((char)n);
                n=scan();
            }
            return sb.toString();
        }
        private boolean isWhiteSpace(int n)
        {
            if(n==' '||n=='\n'||n=='\r'||n=='\t'||n==-1)
            return true;
            return false;
        }
    }
    public static void main(String args[]) throws IOException {
        Scan input=new Scan();
        int x1=input.scanInt();
        int y1=input.scanInt();
        int x2=input.scanInt();
        int y2=input.scanInt();
        int x3=input.scanInt();
        int y3=input.scanInt();

        // all three share the same x or the same y -> 1 segment
        if(x1==x2 && x2==x3) {
            System.out.println(1);
            return;
        }
        if(y1==y2 && y2==y3) {
            System.out.println(1);
            return;
        }

        // check whether one of the points can serve as the corner of an L-shaped polyline
        if ( (x1==x2 && y1==y3) || (x1==x3 && y1==y2) ||
             (x2==x1 && y2==y3) || (x2==x3 && y2==y1) ||
             (x3==x1 && y3==y2) || (x3==x2 && y3==y1) ) {
            System.out.println(2);
            return;
        }

        // otherwise at least three segments are needed
        System.out.println(3);
    }
}

