import java.util.*;
import java.io.*;

public class P617D
{
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

    public static void main(String[] args) throws IOException
    {
    	int[] x = new int[3];
    	int[] y = new int[3];

    	for(int i=0; i<x.length; i++)
    	{
    		String[] s = br.readLine().split(" ");
    		x[i] = Integer.parseInt(s[0]);
    		y[i] = Integer.parseInt(s[1]);
    	}

    	pw.println(process(x, y));
    	pw.close();
    }

    static int process(int[] x, int[] y)
    {
        /* 1 segment : all x equal or all y equal */
        if (x[0] == x[1] && x[1] == x[2]) return 1;
        if (y[0] == y[1] && y[1] == y[2]) return 1;

        /* 2 segments : a point that is the “corner” (shares x with one point and y with another) */
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                if (i == j) continue;
                for (int k = 0; k < 3; ++k) {
                    if (k == i || k == j) continue;
                    if (x[i] == x[j] && y[i] == y[k]) return 2;
                }
            }
        }

        /* 2 segments : a pair sharing a coordinate and the third coordinate lies between them */
        // pair shares x
        if (x[0] == x[1] && y[2] >= Math.min(y[0], y[1]) && y[2] <= Math.max(y[0], y[1])) return 2;
        if (x[0] == x[2] && y[1] >= Math.min(y[0], y[2]) && y[1] <= Math.max(y[0], y[2])) return 2;
        if (x[1] == x[2] && y[0] >= Math.min(y[1], y[2]) && y[0] <= Math.max(y[1], y[2])) return 2;
        // pair shares y
        if (y[0] == y[1] && x[2] >= Math.min(x[0], x[1]) && x[2] <= Math.max(x[0], x[1])) return 2;
        if (y[0] == y[2] && x[1] >= Math.min(x[0], x[2]) && x[1] <= Math.max(x[0], x[2])) return 2;
        if (y[1] == y[2] && x[0] >= Math.min(x[1], x[2]) && x[0] <= Math.max(x[1], x[2])) return 2;

        /* otherwise 3 segments are needed */
        return 3;
    }
}

