public class C {

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int n = input.nextInt(), m = input.nextInt(), u, v;
        ArrayList[] node = new ArrayList[n];
        boolean[][] matrix = new boolean[n][n];

        // Fixed the loop start index (was -1)
        for (int i = 0; i < n; i++)
            node[i] = new ArrayList<Integer>();

        for (int i = 0; i < m; i++) {
            u = input.nextInt();
            u--;
            v = input.nextInt();
            v--;
            node[u].add(v);
            node[v].add(u);
            matrix[u][v] = true;
            matrix[v][u] = true;
        }
        char[] row = new char[n];
        for (int i = 0; i < n; i++) {
            if (node[i].size() == n - 1) row[i] = 'b';
            else row[i] = 'x';
        }
        int i = 0;
        while (i < n && row[i] != 'x')
            i++;

        boolean isAnswer = false;
        if (i < n && row[i] == 'x') {
            int x;
            row[i] = 'a';
            for (int j = 0; j < node[i].size(); j++) {
                x = (int) node[i].get(j);
                if (row[x] == 'x') row[x] = 'a';
            }
            for (int j = 0; j < n; j++)
                if (row[j] == 'x') row[j] = 'c';
        }
        for (i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i != j && row[i] != 'b') {
                    if (matrix[i][j] && row[i] != row[j] && row[j] != 'b')
                        isAnswer = true;
                    if (matrix[i][j] == false) {
                        if (row[j] == row[i] || row[j] == 'b')
                            isAnswer = true;
                    }
                }
            }
            if (isAnswer) break;
        }

        if (isAnswer) System.out.println("No");
        else {
            System.out.println("Yes");
            for (i = 0; i < n; i++)
                System.out.print(row[i]);
            System.out.println();
        }
    }

}

import java.io.*;
import java.util.*;

public class ProblemA{
	static class Solver{
		int n, m;
		boolean[][] g;
		char[] c;

		public void solve(InputReader in, PrintWriter out) {
			n = in.nextInt();
			m = in.nextInt();
			g = new boolean[n+1][n+1];
			for (int i = 0; i < m; ++ i) {
				int u = in.nextInt(), v = in.nextInt();
				g[u][v] = g[v][u] = true;
			}
			c = new char[n+1];
			String s = restoreString();
			if (s == null)
				out.println("No");
			else {
				out.println("Yes\n" + s);
			}
		}

		String restoreString() {
            // reset colors
            Arrays.fill(c, (char)0);
            for (int start = 1; start <= n; ++start) {
                if (c[start] != 0) continue;          // already coloured
                // does 'start' belong to any non‑edge ?
                boolean hasMissing = false;
                for (int j = 1; j <= n; ++j) {
                    if (start == j) continue;
                    if (!g[start][j]) {
                        hasMissing = true;
                        break;
                    }
                }
                if (!hasMissing) {
                    c[start] = 'b';
                    continue;
                }
                // BFS on the complement graph (non‑edges)
                LinkedList<Integer> q = new LinkedList<>();
                q.add(start);
                c[start] = 'a';
                while (!q.isEmpty()) {
                    int node = q.poll();
                    for (int next = 1; next <= n; ++next) {
                        if (next == node) continue;
                        // skip existing edges of the original graph
                        if (g[node][next]) continue;
                        // we are inside a non‑edge
                        if (c[next] == 0) {
                            // must be opposite extreme
                            c[next] = (c[node] == 'a') ? 'c' : 'a';
                            q.add(next);
                        } else if (c[next] == c[node]) {
                            // same extreme on a non‑edge -> impossible
                            return null;
                        }
                    }
                }
            }
            // any still uncoloured vertex gets 'b'
            for (int i = 1; i <= n; ++i) {
                if (c[i] == 0) c[i] = 'b';
            }
            // final verification: no edge may join 'a' and 'c'
            for (int i = 1; i <= n; ++i) {
                for (int j = 1; j <= n; ++j) {
                    if (i == j) continue;
                    if (g[i][j] && 
                        ((c[i] == 'a' && c[j] == 'c') || (c[i] == 'c' && c[j] == 'a'))) {
                        return null;
                    }
                }
            }
            return new String(c).substring(1);
        }
	}

