public class ProblemA{
	static class Solver{
		int n, m;
		boolean[][] g;
		char[] c;

		public void solve(InputReader in, PrintWriter out) {
			n = in.nextInt();
			m = in.nextInt();
			g = new boolean[n+1][n+1];
			for (int i = 0; i < m; ++ i) {
				int u = in.nextInt(), v = in.nextInt();
				g[u][v] = g[v][u] = true;
			}
			c = new char[n+1];
			String s = restoreString();
			if (s == null)
				out.println("No");
			else {
				out.println("Yes\n" + s);
			}
		}

		String restoreString() {
			LinkedList<Integer> q = new LinkedList<>();
			// fixed: iterate only over existing vertices 1..n
			for (int i = 1; i <= n; ++ i) {
				boolean hasEdges = false;
				for (int j = 1; j <= n; ++ j)
					if (j != i && !g[i][j]) {
						hasEdges = true;
						break;
					}
				if (! hasEdges) continue;

				q.add(i);
				if (c[i] == '\u0000') c[i] = 'a';
				while (!q.isEmpty()) {
					int node = q.poll().intValue();
					for (int next = 1; next <= n; ++ next) {
						if (next == node || g[node][next]) continue;
						if (c[next] == c[node]) return null;
						if (c[next] != '\u0000') continue;
						c[next] = (c[node] == 'a') ? 'c' : 'a';
						q.add(next);
					}
				}
			}
			for (int i = 1; i <= n; ++ i)
				if (c[i] == '\u0000') c[i] = 'b';

			for (int i = 1; i <= n; ++ i) {
				for (int j = 1; j <= n; ++ j) {
					if (i == j) continue;
					if (g[i][j] && (c[i] == 'a' && c[j] == 'c' || c[i] == 'c' && c[j] == 'a'))
						return null;
				}
			}
			return new String(c).substring(1);
		}
	}

