public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskA_ATM_1 solver = new TaskA_ATM_1();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskA_ATM_1 {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt(), m = in.nextInt();
            boolean[][] g = new boolean[n][n];
            for (int i = 0; i < m; ++i) {
                int a = in.nextInt() - 1;
                int b = in.nextInt() - 1;
                g[a][b] = g[b][a] = true;
            }
            for (int i = 0; i < n; ++i) {
                g[i][i] = true;
            }

            int[] res = new int[n];
            Arrays.fill(res, -1);
            for (int i = 0; i < n; ++i) {
                boolean isB = true;
                for (int j = 0; j < n; ++j) {
                    if (!g[i][j]) {
                        isB = false;
                        break;
                    }
                }
                if (isB) {
                    res[i] = 1;
                }
            }

            boolean[] u = new boolean[n];
            for (int i = 0; i < n; ++i) {
                if (res[i] != -1) continue;
                if (u[i]) {
                    for (int j = 0; j < n; ++j) {
                        if (res[j] == -1) {
                            if (g[i][j] && !u[j]) {
                                out.println("No");
                                return;
                            }
                            if (!g[i][j] && u[j]) {
                                out.println("No");
                                return;
                            }
                        }
                    }
                } else {
                    for (int j = 0; j < n; ++j) {
                        if (res[j] == -1) {
                            if (g[i][j] && u[j]) {
                                out.println("No");
                                return;
                            }
                            if (!g[i][j] && !u[j]) {
                                out.println("No");
                                return;
                            }
                        }
                    }
                }
            }
            for (int i = 0; i < n; ++i) {
                if (u[i]) {
                    res[i] = 0;
                }
            }
            out.println("Yes");
            for (int c : res) {
                if (c == 0) {
                    out.print('a');
                } else if (c == 1) {
                    out.print('b');
                } else {
                    out.print('c');
                }
            }
            out.println();
        }

        private void dfs(int v, boolean[][] g, boolean[] u, int[] a) {
            u[v] = true;
            for (int i = 0; i < g.length; ++i) {
                if (g[v][i] && !u[i] && a[i] == -1) {
                    dfs(i, g, u, a);
                }
            }
        }

    }

    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer stt;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }

        public String nextString() {
            while (stt == null || !stt.hasMoreTokens()) {
                stt = new StringTokenizer(nextLine());
            }
            return stt.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }

    }
}

