public class GraphAndString {
    public static void main(String[] args) {
        FasterScanner sc = new FasterScanner();

        int N = sc.nextInt();
        int M = sc.nextInt();

        IntSet[] G = new IntSet[N];
        for (int i = 0; i < N; i++) {
            G[i] = new IntSet();
        }

        for (int i = 0; i < M; i++) {
            int U = sc.nextInt() - 1;
            int V = sc.nextInt() - 1;
            G[U].add(V);
            G[V].add(U);
        }

        char[] S = new char[N];

        for (int i = 0; i < N; i++) {
            if (G[i].size() == N - 1) {
                S[i] = 'b';
            }
        }

        for (int i = 0; i < N; i++) {
            if (S[i] == '\0') {
                S[i] = 'a';
                for (int j = i + 1; j < N; j++) {
                    if (!G[i].contains(j)) {
                        S[j] = 'c';
                    }
                }
