public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskA solver = new TaskA();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskA {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            ArrayList<ArrayList<Integer>> neig = new ArrayList<>();
            for (int i = 0; i <= n; i++) neig.add(new ArrayList<>());
            char[] ans = new char[n + 1];
            for (int i = 0; i < m; i++) {
                int v = in.nextInt();
                int u = in.nextInt();
                neig.get(u).add(v);
                neig.get(v).add(u);
            }
            for (int i = 1; i <= n; i++) {
                if (neig.get(i).size() == n - 1) ans[i] = 'b';
            }
            for (int i = 1; i <= n; i++) {
                if (ans[i] == 0) {
                    dfs(ans, neig, i);
                    break;
                }
            }
            for (int i = 1; i <= n; i++) {
                if (ans[i] == 0) {
                    ans[i] = 'c';
                }
            }
            for (int i = 1; i <= n; i++) {
                Set<Integer> neigSet = new HashSet<>();
                for (int j : neig.get(i)) {
                    neigSet.add(j);
                    if (Math.abs(ans[i] - ans[j]) > 1) {
                        out.println("No");
                        return;
                    }
                }
                for (int j = 1; j <= n; j++) {
                    if (!neigSet.contains(j) && j != i) {
                        if (Math.abs(ans[i] - ans[j]) <= 1) {
                            out.println("No");
                            return;
                        }
                    }
                }
            }
            out.println("Yes");
            for (int i = 1; i <= n; i++) out.print(ans[i]);
        }

        void dfs(char[] ans, ArrayList<ArrayList<Integer>> neig, int node) {
            ans[node] = 'a';
            for (int nei : neig.get(node)) {
                if (ans[nei] == 0) {
                    dfs(ans, neig, nei);
                }
            }
        }

    }

    static class InputReader {
        private StringTokenizer tokenizer;
        private BufferedReader reader;

        public InputReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        private void fillTokenizer() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }
        }

        public String next() {
            fillTokenizer();
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
