import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

public class C {

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer(br.readLine());
		int n = Integer.parseInt(st.nextToken());
		int m = Integer.parseInt(st.nextToken());
		boolean[][] graph = new boolean[n][n];
		for (int i = 0; i < m; i++) {
			StringTokenizer st2 = new StringTokenizer(br.readLine());
			int a = Integer.parseInt(st2.nextToken()) - 1;
			int b = Integer.parseInt(st2.nextToken()) - 1;   // fixed: removed extra minus sign
			graph[a][b] = true;
			graph[b][a] = true;
		}

		boolean[][] comp = new boolean[n][n];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < n; j++)
				if (j != i) {
					comp[i][j] = !graph[i][j];
				}
		}

		int[] color = new int[n]; 
		int[] neig = new int[n];
		for (int i = 0; i < n; i++) {
			int t = 0;
			for (int j = 0; j < n; j++)
				if (comp[i][j]) {
					t++;
				}
			neig[i] = t;
			if (t == 0) {
				color[i] = 2;
			}
		}
		int root = -1;
		for (int i = 0; i < n; i++) {
			if (neig[i] > 0) {
				root = i;
				break;
			}
		}
		boolean can = true;
		if (root != -1) {
			color[root] = 1;
			Queue<Integer> q = new ArrayDeque<>();
			q.add(root);
			int aes = 1;
			int ces = 0;
			while (!q.isEmpty()) {
				int cur = q.poll();
				for (int next = 0; next < n; next++)
					if (next != cur && comp[cur][next]) {
						if (color[next] == 2 || color[next] == color[cur]) {
							can = false;
						} else if (color[next] == 0) {
							if (color[cur] == 1) {
								color[next] = 3;
								ces++;
							} else {
								color[next] = 1;
								aes++;
							}
							q.add(next);
						}
					}
			}
			for (int i = 0; i < n; i++) {
				if (color[i] == 0) {
					can = false;
				}
				if (color[i] == 1 && neig[i] != ces) {
					can = false;
				} else if (color[i] == 3 && neig[i] != aes) {
					can = false;
				}
			}
		}
		if (can) {
			char[] ls = new char[] { 'a', 'b', 'c' };
			StringBuilder sb = new StringBuilder();
			for (int i = 0; i < n; i++) {
				sb.append(ls[color[i] - 1]);
			}
			System.out.println("Yes");
			System.out.println(sb.toString());
		} else {
			System.out.println("No");
		}
	}
}

import java.io.*;
import java.lang.reflect.Array;
import java.util.*;

public class Main {

    private static InputStream inputStream;
    private static OutputStream outputStream;
    private static PrintWriter writer;
    private static InputReader reader;

    public static void main(String[] args) {
        inputStream = System.in;
        outputStream = System.out;
        reader = new InputReader(inputStream);
        writer = new PrintWriter(outputStream);
        new Main().main();
        writer.close();
    }


    static boolean[][] gragh;
    static boolean[] visit;
    static int n;
    static int[] color;

    boolean dfs(int u, int pre, int colored) {
        visit[u] = true;
        color[u] = colored;
        for (int i = 0; i < n; ++i) {
            if (i == pre || !gragh[u][i] || i == u) {
                continue;
            }
            if (visit[i] && color[i] == colored) {
                return false;
            }
            if (!visit[i] && !dfs(i, u, colored ^ 1)) {
                return false;
            }
        }
        return true;
    }

    private void main() {
        n = reader.nextInt();
        int m = reader.nextInt();
        gragh = new boolean[n][n];
        visit = new boolean[n];
        color = new int[n];
        int[] degrees = new int[n];
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                gragh[i][j] = true;
            }
            degrees[i] = n - 1;
        }
        for (int i = 0; i < m; ++i) {
            int u = reader.nextInt() - 1;
            int v = reader.nextInt() - 1;
            gragh[u][v] = gragh[v][u] = false;
            degrees[u]--;
            degrees[v]--;
        }

        for (int i = 0; i < n; ++i) {
            if (!visit[i]) {
                if (!dfs(i, i, 0)) {
                    writer.println("No");
                    return;
                }
            }
        }

        int[] ans = new int[n];
        for (int i = 0; i < n; ++i) {
            if (degrees[i] == 0) {
                ans[i] = 1;
            } else if (color[i] == 1) {
                ans[i] = 2;
            } else {
                ans[i] = 0;
            }
        }
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                if (ans[i] == ans[j] || Math.abs(ans[i] - ans[j]) == 1) {
                    --m;
                }
            }
        }
        if (m != 0) {
            writer.println("No");
        } else {
            writer.println("Yes");
            for (int i = 0; i < n; ++i) {
                char ch = (char) (ans[i] + 'a');
                writer.print(ch);
            }
            writer.println();
        }
    }


}

class InputReader {
    private StringTokenizer tokenizer;
    private BufferedReader reader;

    public InputReader(InputStream inputStream) {
        tokenizer = null;
        reader = new BufferedReader(new InputStreamReader(inputStream));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }
}

