            degrees[v]--;
        }

        for (int i = 0; i < n; ++i) {
            if (!visit[i]) {
                if (!dfs(i, i, 0)) {
                    writer.println("No");
                    return;
                }
            }
        }

        int[] ans = new int[n];
        for (int i = 0; i < n; ++i) {
            if (degrees[i] == 0) {
                ans[i] = 1;
            } else if (color[i] == 1) {
                ans[i] = 2;
            } else {
                ans[i] = 0;
            }
        }
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                if (ans[i] == ans[j] || Math.abs(ans[i] - ans[j]) == 1) {
                    --m;
                }
            }
        }
        if (m != 0) {
            writer.println("No");
        } else {
            writer.println("Yes");
            for (int i = 0; i < n; ++i) {
                char ch = (char) (ans[i] + 'a');
                writer.print(ch);
            }
            writer.println();
        }
    }


}
