		int n = Integer.parseInt(line[0]);
		int m = Integer.parseInt(line[1]);
		List<Integer> bs = new ArrayList<Integer>();
		int[][] graph = new int[n+1][n+1];
		for (int i =1; i<=n; i++){
			graph[i][0] = 0;
			graph[i][i] = 1;
		}
		for (int i = 0; i< m; i++) {
			line = br.readLine().split(" ");
			int x = Integer.parseInt(line[0]);
			int y = Integer.parseInt(line[1]);
			graph[x][y] = 1;
			graph[y][x] = 1;
			if (x == y) {
				continue;
			}
			graph[x][0]++;
			if (graph[x][0] == n-1) {
				bs.add(x);
			}
			graph[y][0]++;
			if (graph[y][0] == n-1) {
				bs.add(y);
			}
		}
		br.close();
		for (int y=0; y<=n; y++){
			if (graph[y][0] == n-1) {
				bs.add(y);
			}
		}
		int notb=0;
		for (int i =1; i<=n && notb == 0; i++){
			if (graph[i][0] != n-1) {
				notb = i; 
			}
		}
		Map< Point, List<Integer>> map = new HashMap<>();
		for (int i =1; i<=n; i++){
			if (graph[i][0] >= n-1){
				continue;
			}
			Point id = new Point(graph[i][0], graph[i][notb]);
			if (!map.containsKey(id)){
				map.put(id, new ArrayList<Integer>());
			}
			map.get(id).add(i);
		}
		if (map.keySet().size() > 2) {
			System.out.println("No");
			return;
		}


		for (Point key : map.keySet()) {
			List<Integer> componenta = map.get(key);
			for (int i = 0; i< componenta.size(); i++) {
				Integer varf1 = componenta.get(i);
				for (int j  = 0; j<componenta.size() ; j++) {
					if (graph[varf1][componenta.get(j)] == 0) {

						System.out.println("No");
						return;
					}
				}
			}
		}

		char[] str = new char[n];
		for (int i : bs) {
			str[i-1] = 'b';
		}
		Iterator<Point> iterator = map.keySet().iterator();
		if (iterator.hasNext()) {
			for (int i : map.get(iterator.next())) {
				str[i-1] = 'a';
			}
		}
		if (iterator.hasNext()) {
			for (int i : map.get(iterator.next())) {
				str[i-1] = 'c';
			}
		}

		// Verify that no edge connects an 'a' vertex with a 'c' vertex
		for (int i = 1; i <= n; i++) {
			if (str[i-1] == 'a' || str[i-1] == 'c') {
				for (int j = i+1; j <= n; j++) {
					if (graph[i][j] == 1) {
						if ((str[i-1] == 'a' && str[j-1] == 'c') ||
                            (str[i-1] == 'c' && str[j-1] == 'a')) {
							System.out.println("No");
							return;
						}
					}
				}
			}
		}

		System.out.println("Yes");
		System.out.println(String.valueOf(str));
	}
}

