            return false;
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        char[] label = new char[n];
        ArrayList<ArrayList<Integer>> adjList = new ArrayList<>();
        ArrayList<Integer> as = new ArrayList<>();
        ArrayList<Integer> cs = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            ArrayList<Integer> list = new ArrayList<>();
            adjList.add(list);
            label[i] = 'x';
        }
        for (int i = 0; i < m; i++) {
            int n1 = sc.nextInt();
            int n2 = sc.nextInt();
            adjList.get(n1 - 1).add(n2 - 1);
            adjList.get(n2 - 1).add(n1 - 1);
        }
        for (int i = 0; i < n; i++) {
            if (adjList.get(i).size() == n - 1) {
                label[i] = 'b';
            }
        }
        int firstUnmarked = -1;
        for (int i = 0; i < n; i++) {
            if (label[i] == 'x') {
                firstUnmarked = i;
                break;
            }
        }
        if (firstUnmarked > -1) {
            label[firstUnmarked] = 'a';
            as.add(firstUnmarked);
            for (int i = 0; i < adjList.get(firstUnmarked).size(); i++) {
                if (label[adjList.get(firstUnmarked).get(i)] == 'x') {
                    label[adjList.get(firstUnmarked).get(i)] = 'a';
                    as.add(adjList.get(firstUnmarked).get(i));
                }
            }
        }

        for (int i = 0; i < as.size(); i++) {
            for (int j = i + 1; j < as.size(); j++) {
                if (!adjList.get(as.get(i)).contains(as.get(j))) {
                    System.out.println("No");
                    return;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            if (label[i] == 'x') {
                label[i] = 'c';
                cs.add(i);
            }
        }

        for (int i = 0; i < cs.size(); i++) {
            for (int j = i + 1; j < cs.size(); j++) {   // Fixed condition: j < cs.size()
                if (!adjList.get(cs.get(i)).contains(cs.get(j))) {
                    System.out.println("No");
                    return;
                }
            }
        }

        String answer = "";
        boolean can = true;
        boolean[] taken = new boolean[n];
        for (int i = 0; i < n && can; i++) {
            if (!taken[i]) {
                answer = answer + label[i];
                for (int j = 0; j < adjList.get(i).size(); j++) {
                    can = match(label[i], label[adjList.get(i).get(j)]);
                    if (!can) {
                        break;
                    }
                }
            }
        }
        if (can) {
            System.out.println("Yes\n" + answer);
        } else {
            System.out.println("No");
        }
    }
}

