public class C {

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        Solver solver = new Solver();
        solver.solve(1, in, out);

        out.close();
    }

    static class Solver {

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            int[] colors = new int[n];
            int[][] a = new int[n][n];
            for (int i = 0; i < m; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                a[u][v] = a[v][u] = 1;
            }
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (a[i][j] == 0) {
                        int color_1 = colors[i];
                        int color_2 = colors[j];
                        if (color_1 == 0 && color_2 == 0) {
                            colors[i] = 1;
                            colors[j] = 3;
                        } else if (color_1 == 0) {
                            if (color_2 == 2) {
                                out.println("No");
                                return;
                            }
                            colors[i] = (color_2 == 1 ? 3 : 1);
                        } else if (color_2 == 0) {
                            if (color_1 == 2) {
                                out.println("No");
                                return;
                            }
                            colors[j] = (color_1 == 1 ? 3 : 1);
                        } else if (Math.abs(color_1 - color_2) <= 1) {
                            out.println("No");
                            return;
                        }
                    }
                }
            }
            for (int i = 0; i < n; i++) {
                if (colors[i] == 0) {
                    colors[i] = 2;
                }
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (a[i][j] == 1) {
                        if (Math.abs(colors[i] - colors[j]) > 1) {
                            out.println("No");
                            return;
                        }
                    }
                }
            }

            out.println("Yes");
            for (int i = 0; i < n; i++) {
                out.print(colors[i] == 1 ? "a" : (colors[i] == 2 ? "b" : "c"));
            }
        }

    }

    static class InputReader {

        public BufferedReader reader;
