        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    static int N, M;
    static boolean [][] graph;
    static char [] letter;

    public static void main(String []args) {
        InputReader reader = new InputReader(System.in);
        N = reader.nextInt();
        M = reader.nextInt();
        graph = new boolean[N][N];
        letter = new char[N];
        for (int i = 0; i < M; i++) {
            int a = reader.nextInt();
            int b = reader.nextInt();
            graph[a - 1][b - 1] = graph[b - 1][a - 1] = true;
        }

        for (int i = 0; i < N; i++) {
            boolean connectedToAll = true;
            for (int j = 0; j < N; j++) {
                if (i == j) continue;
                if (!graph[i][j]) {
                    connectedToAll = false;
                    break;
                }
            }
            if (connectedToAll) {
                letter[i] = 'b';
            }
        }

        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                for (int k = j + 1; k < N; k++) {
                    int edgeCnt = 0;
                    if (letter[i] != '\0' || letter[j] != '\0' || letter[k] != '\0')
                        continue;
                    if (graph[i][j]) edgeCnt++;
                    if (graph[j][k]) edgeCnt++;
                    if (graph[i][k]) edgeCnt++;
                    if (edgeCnt == 0 || edgeCnt == 2) {
                        System.out.println("No");
                        return;
                    }
                }
            }
        }

        System.out.println("Yes");
        char curr = 'a';
        for (int i = 0; i < N; i++) {
            if (letter[i] != '\0') continue;
            boolean found = false;
            for (int j = 0; j < N; j++) {
                if (graph[i][j] && letter[j] != '\0' && letter[j] != 'b') {
                    letter[i] = letter[j];
                    found = true;
                    break;
                }
            }
            if (!found) {
                letter[i] = curr;
                curr = 'c';
            }
        }
        System.out.println(new String(letter));
    }
}

