            for (int j = i + 1; j < N; j++) {
                for (int k = j + 1; k < N; k++) {
                    int edgeCnt = 0;
                    if (letter[i] != '\0' || letter[j] != '\0' || letter[k] != '\0')
                        continue;
                    if (graph[i][j]) edgeCnt++;
                    if (graph[j][k]) edgeCnt++;
                    if (graph[i][k]) edgeCnt++;
                    if (edgeCnt == 0) {
                        System.out.println("No");
                        return;
                    }
                }
            }
        }

        System.out.println("Yes");
        char curr = 'a';
        for (int i = 0; i < N; i++) {
            if (letter[i] != '\0') continue;
            boolean found = false;
            for (int j = 0; j < N; j++) {
                if (graph[i][j] && letter[j] != '\0' && letter[j] != 'b') {
                    letter[i] = letter[j];
                    found = true;
                    break;
                }
            }
            if (!found) {
                letter[i] = curr;
                curr = 'c';
            }
        }
        System.out.println(new String(letter));
    }
