    static class TaskC {
        boolean[][] graph;
        int[] indexes;
        char[] colors = new char[]{'a', 'b', 'c'};

        public void solve(int testNumber, FastInputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            graph = new boolean[n][n];
            indexes = new int[n];

            for (int i = 0; i < m; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                graph[u][v] = graph[v][u] = true;
            }

            for (int i = 0; i < n; i++) {
                if (indexes[i] == 0) {
                    if (isNo(i, -1, 1)) {
                        out.println("No");
                        return;
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                boolean ok = true;
                for (int j = 0; j < n; j++) {
                    if (i != j && !graph[i][j]) {
                        ok = false;
                    }
                }
                if (ok)
                    indexes[i] = 2;
            }

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (graph[i][j] && Math.abs(indexes[i] - indexes[j]) == 2) {
                        out.println("No");
                        return;
                    }
                }
            }

            out.println("Yes");
            for (int i = 0; i < n; i++) {
                out.print(colors[indexes[i] - 1]);
            }
        }

        private boolean isNo(int u, int p, int c) {
            indexes[u] = c;
            for (int v = 0; v < graph[u].length; v++) {
                if (u == v || v == p)
                    continue;
                if (!graph[u][v]) {
                    if (indexes[v] == 0) {
                        if (isNo(v, u, 4 - c)) {
                            return true;
                        }
                    } else {
                        if (indexes[v] == c) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

    }

    static class FastInputReader {
        static InputStream is;
        static private byte[] buffer;
        static private int lenbuf;
        static private int ptrbuf;

        public FastInputReader(InputStream stream) {
            is = stream;
            buffer = new byte[1024];
            lenbuf = 0;
            ptrbuf = 0;
        }

        private int readByte() {
            if (lenbuf == -1)
                throw new InputMismatchException();
            if (ptrbuf >= lenbuf) {
                ptrbuf = 0;
                try {
                    lenbuf = is.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (lenbuf <= 0)
                    return -1;
            }
            return buffer[ptrbuf++];
        }

        public int nextInt() {
            int num = 0, b;
            boolean minus = false;
            while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
                ;
            if (b == '-') {
                minus = true;
                b = readByte();
            }

            while (true) {
                if (b >= '0' && b <= '9') {
                    num = num * 10 + (b - '0');
                } else {
                    return minus ? -num : num;
                }
                b = readByte();
            }
        }

    }
}

