                     ar[y]="c";
                  }
                  else if (ar[y].equals("a"))
                     ar[x]="c";
                  else ar[x]="a";
               }

               else if(ar[x].equals("a")){
                  if(ar[y]==null) ar[y]="c";
                  else if(ar[y].equals("a")) bool=false;
               }

               else if(ar[x].equals("c")){
                  if(ar[y]==null) ar[y]="a";
                  else if(ar[y].equals("c")) bool=false;
               }  
            }
         }

      for(int x=0;x<N;x++)
         for(int y=x+1;y<N;y++)
            if(connected[x][y]==1)
               if(ar[x]!=null && ar[y]!=null){
                  // check if the pair of letters is allowed on an edge
                  if(!(ar[x].equals(ar[y])
                       || (ar[x].equals("a") && ar[y].equals("b"))
                       || (ar[x].equals("b") && ar[y].equals("a"))
                       || (ar[x].equals("b") && ar[y].equals("c"))
                       || (ar[x].equals("c") && ar[y].equals("b")))){
                     bool=false;
                  }
               }

      if(!bool) System.out.println("No");
      else{
         System.out.println("Yes");
         for(int x=0;x<N;x++)
            if(ar[x]==null) ar[x]="b";
         for(int x=0;x<N;x++)
            System.out.print(ar[x]);
      }
   }

   public static void setUpChoose(int t){
      cAr=new long[t+1];
      div=new long[t+1];
      cAr[0]=1;
      div[0]=1;

      for(int x=1;x<=t;x++){
         cAr[x]=(x*cAr[x-1])%(MOD);
         div[x]=pow(cAr[x],MOD-2);} 
   }

   public static long choose(int x,int y){
      long a=cAr[x+y];
      long b=div[x];
      long c=div[y];
      a=(a*b)%MOD;
      a=(a*c)%MOD;
      return a;
   } 

   public static long pow(long a,long b){
      if(b==1) 
         return a;
      long c=b/2;
      long temp=pow(a,c)%MOD;
      temp=(temp*temp)%MOD;
      if(b%2==1) temp=temp*a;
      return temp%MOD;
   }
}

