		for(int i = 0 ; i < n ; i++)
			adj[i] = new ArrayList<>();
		for(int i = 0 ; i < m ; i++) {
			int u = scan.nextInt()-1, v = scan.nextInt()-1;
			adj[u].add(v);
			adj[v].add(u);
		}
		char[] color = new char[n];
		Arrays.fill(color, 'c');
		for(int u = 0 ; u < n ; u++)
			if(adj[u].size() == n-1)
				color[u] = 'b';
		for(int u = 0 ; u < n ; u++) {
			if(color[u] != 'b') {
				color[u] = 'a';
				for(int v : adj[u])
					if(color[v] != 'b')
						color[v] = 'a';
				break;
			}
		}
		int a = 0, b = 0, c = 0;
		for(int i = 0 ; i < n ; i++)
			if(color[i] == 'a')
				a = a + 1;
			else if(color[i] == 'b')
				b = b + 1;
			else
				c = c + 1;
		boolean valid = true;
		for(int u = 0 ; u < n ; u++) {
			int a_ = 0, b_ = 0, c_ = 0;
			a_+=color[u]=='a'?1:0;
			b_+=color[u]=='b'?1:0;
			c_+=color[u]=='c'?1:0;

			for(int v : adj[u]) {
				a_+=color[v]=='a'?1:0;
				b_+=color[v]=='b'?1:0;
				c_+=color[v]=='c'?1:0;
			}

			if(color[u] == 'a' && (c_ > 0 || b_ != b || a_ != a)) {
				valid = false;
				break;
			}
			if(color[u] == 'c' && (a_ > 0 || b_ != b || c_ != c)) {
				valid = false;
				break;
			}
		}

		out.println(valid?"Yes":"No");
