                paint(e, c);
            }
        }
    }

    static boolean check() {
        for (int i = 0; i < sb.length(); i++) {
            for (int j = i + 1; j < sb.length(); j++) {
                boolean cond = Math.abs(sb.charAt(i) - sb.charAt(j)) <= 1;
                if (cond != w[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

