public class GraphString {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();

        Set<Integer>[] graph = new Set[n];

        Set<Integer> all = new HashSet<>();
        for (int i = 0; i < n; i++) {
            graph[i] = new HashSet<>();
            all.add(i);
        }

        for (int i = 0; i < m; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            graph[u].add(v);
            graph[v].add(u);
        }

        Set<Integer> setB = findB(graph);

        boolean yes = false;
        if (setB.size() == n) {
            print(Collections.emptySet(), setB, Collections.emptySet());
            yes = true;
        } else {
            all.removeAll(setB);
            Set<Integer> setA = findClique(graph, all);
            if (setB.size() + setA.size() == n) {
                print(setA, setB, Collections.emptySet());
                yes = true;
            } else {
                all.removeAll(setA);
                Set<Integer> setC = findClique(graph, all);
                if (setB.size() + setA.size() + setC.size() == n) {
                    yes = true;
                    for (Integer i : setA) {
                        for (Integer c : setC) {
                            if (graph[i].contains(c)) {
                                yes = false;
                                break;
                            }
                        }
                    }
                }
                if (yes) {
                    print(setA, setB, setC);
                }
            }
        }
        if (!yes) {
            System.out.println("No");
        }
    }


    private static Set<Integer> findB(Set<Integer>[] graph) {
        Set<Integer> res = new HashSet<>();
        for (int i = 0; i < graph.length; i++) {
            if (connectedToAll(graph, i)) {
                res.add(i);
            }
        }
        return res;
    }

    private static boolean connectedToAll(Set<Integer>[] graph, Integer cand) {
        for (int i = 0; i < graph.length; i++) {
            if (i != cand) {
                if (!graph[i].contains(cand)) {
                    return false;
                }
            }
        }
        return true;
    }

    private static void print(Set<Integer> a, Set<Integer> b, Set<Integer> c) {
        System.out.println("Yes");
        StringBuilder sb = new StringBuilder();
        sb.setLength(a.size() + b.size() + c.size());

        for (Integer i : a) {
            sb.setCharAt(i, 'a');
        }
        for (Integer i : b) {
            sb.setCharAt(i, 'b');
        }
        for (Integer i : c) {
            sb.setCharAt(i, 'c');
        }

        System.out.println(sb.toString());
    }

    private static Set<Integer> findClique(Set<Integer>[] graph, Collection<Integer> cands) {
        Set<Integer> res = new HashSet<>();
        for (Integer i : cands) {
            boolean connectedToAll = true;

            for (Integer node : res) {
                if (!graph[i].contains(node)) {
                    connectedToAll = false;
                    break;
                }
            }
            if (connectedToAll) {
                res.add(i);
            }
        }
        return res;
    }
}

