import java.util.*;

public class graph_and_string
{
    static int n, m;

    static ArrayList<Integer>[] e;

    static int[] c;

    static boolean search;

    @SuppressWarnings("unchecked")
    public static void main( String[] args )
    {
        Scanner in = new Scanner( System.in );
        n = in.nextInt();
        m = in.nextInt();
        e = new ArrayList[n + 1];
        for ( int i = 1; i <= n; i++ )
            e[i] = new ArrayList<Integer>();
        for ( int i = 0; i < m; i++ )
        {
            int u = in.nextInt(), v = in.nextInt();
            e[u].add( v );
            e[v].add( u );
        }
        c = new int[n + 1];
        for ( int i = 1; i <= n; i++ )
            if ( e[i].size() == n - 1 )
                c[i] = 2;
        search = false;
        for ( int i = 1; i <= n && !search; i++ )
            if ( c[i] == 0 )
                fill( i, 1 );
        search = false;
        for ( int i = 1; i <= n && !search; i++ )
            if ( c[i] == 0 )
                fill( i, 3 );
        if (!all() || !cxed())
            System.out.println( "No" );
        else
        {
            System.out.println( "Yes" );
            for ( int i = 1; i <= n; i++ )
                System.out.print( (char)( c[i] - 1 + 'a' ) );
        }
        in.close();
        System.exit( 0 );
    }

    public static boolean cxed()
    {
        for ( int i = 1; i < n; i++ )
            for ( int j = i + 1; j <= n; j++ )
                if ( Math.abs( c[i] - c[j] ) <= 1 && !e[i].contains( j ) )
                    return false;
                else if ( Math.abs( c[i] - c[j] ) > 1 && e[i].contains( j ) )
                    return false;
        return true;
    }

    public static boolean all()
    {
        for ( int i = 1; i <= n; i++ )
            if ( c[i] == 0 )
                return false;
        return true;
    }

    public static void fill( int x, int co )
    {
        LinkedList<Integer> q = new LinkedList<Integer>();
        q.add( x );
        while ( !q.isEmpty() )
        {
            int v = q.pop();
            ArrayList<Integer> adj = e[v];
            for ( int i = 0; i < adj.size(); i++ )
                if ( c[adj.get( i )] == 0 )
                    q.add( adj.get( i ) );
            c[v] = co;
        }
        search = true;
    }
}

