import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.StringTokenizer;
import java.io.BufferedReader;
import java.io.InputStream;


public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        MyScanner in = new MyScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskA solver = new TaskA();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskA {
        private static int[] cntComops;
        private static boolean[] markComps;
        private static boolean[][] matrix;
        private static int ch;
        private static char[] result;

        public void solve(int testNumber, MyScanner in, PrintWriter out) {

            int n = in.nextInt();
            int m = in.nextInt();
            ch = 0;
            result = new char[n];
            List<List<Integer>> g = new ArrayList<>();

            for (int i = 0; i < n; i++) {
                g.add(new ArrayList<>());
            }
            matrix = new boolean[n][n];

            for (int i = 0; i < m; i++) {
                int v = in.nextInt() - 1;
                int u = in.nextInt() - 1;
                g.get(v).add(u);
                g.get(u).add(v);
                matrix[v][u] = true;
                matrix[u][v] = true;
            }
            cntComops = new int[n];
            int compLabel = 0;
            List<List<Integer>> comps = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if (cntComops[i] == 0) {
                    if (compLabel == 2) {
                        out.println("No");
                        return;
                    }
                    List<Integer> subGraph = new ArrayList<>();
                    Set<Integer> subset = new HashSet<>();
                    subGraph.add(i);
                    subset.add(i);
                    cntComops[i]++;
                    int it = 0;
                    while (it < subGraph.size()) {
                        int cur = subGraph.get(it++);
                        for (int j = 0; j < g.get(cur).size(); j++) {
                            int to = g.get(cur).get(j);
                            if (!subset.contains(to)) {
                                Set<Integer> toSubset = new HashSet<>(g.get(to));
                                if (toSubset.containsAll(subGraph)) {
                                    subGraph.add(to);
                                    subset.add(to);
                                    cntComops[to]++;
                                }
                            }
                        }
                    }
                    compLabel++;
                    comps.add(subGraph);
                }
            }

            for (int i = 0; i < n; i++) {
                if (cntComops[i] > 2) {
                    out.print("No");
                    return;
                }
            }
            for (int i = 0; i < comps.size(); i++) {
                for (int j = i + 1; j < comps.size(); j++) {
                    for (int x : comps.get(i)) {
                        for (int y : comps.get(j)) {
                            if (x != y && matrix[x][y] && cntComops[x] == 1 && cntComops[y] == 1) {
                                out.print("No");
                                return;
                            }
                        }
                    }
                }
            }
            markComps = new boolean[comps.size()];
            for (int i = 0; i < comps.size(); i++) {
                if (!markComps[i] && isStart(comps.get(i))) {
                    dfs(i, comps);
                }
            }
            if (ch > 4) {
                out.println("No");
                return;
            }
            out.println("Yes");
            for (int i = 0; i < n; i++) {
                out.print(result[i]);
            }
        }

        private static boolean isStart(List<Integer> comp) {
            for (int i = 0; i < comp.size(); i++) {
                if (cntComops[comp.get(i)] == 1) {
                    return true;
                }
            }
            return false;
        }

        private static void dfs(int id, List<List<Integer>> g) {
            markComps[id] = true;
            char cur = (char) (ch + 'a');
            char next = (char) (ch + 1 + 'a');
            for (int i = 0; i < g.size(); i++) {
                if (!markComps[i] && isBro(g.get(id), g.get(i))) {
                    for (int x : g.get(id)) {
                        boolean isX = true;
                        for (int y : g.get(i)) {
                            if (x == y) {
                                isX = false;
                                break;
                            }
                        }
                        if (result[x] == 0) {
                            if (isX) {
                                result[x] = cur;
                            } else {
                                result[x] = next;
                            }
                        }
                    }
                    ch += 2;
                    dfs(i, g);
                    return;
                }
            }
            for (int x : g.get(id)) {
                if (result[x] == 0) {
                    result[x] = cur;
                }
            }
            ch += 2;
        }

        private static boolean isBro(List<Integer> a, List<Integer> b) {
            for (Integer x : a) {
                for (Integer y : b) {
                    if (matrix[x][y]) {
                        return true;
                    }
                }
            }
            return false;
        }

    }

