        OutputWriter out = new OutputWriter(outputStream);
        Div2723D_LakesInBerland solver = new Div2723D_LakesInBerland();
        solver.solve(1, in, out);
        out.close();
    }

    static class Div2723D_LakesInBerland {
        int n;
        int m;
        int k;
        char[][] map;
        ArrayList<ArrayList<GraphUtils.Cell>> lakes = new ArrayList<>();
        boolean[][] visited;
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        public void solve(int testNumber, InputReader in, OutputWriter out) {

            n = in.nextInt();
            m = in.nextInt();
            k = in.nextInt();

            map = new char[n][m];
            for (int i = 0; i < n; i++) {
                char[] row = in.nextString().toCharArray();
                System.arraycopy(row, 0, map[i], 0, m);
            }

            prepocess('.', '#');


            visited = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (!visited[i][j]) {
                        ArrayList<GraphUtils.Cell> lake = new ArrayList<>();
                        findLakes(lake, i, j);
                        if (lake.size() != 0)
                            lakes.add(lake);
                    }

                }
            }


            int ans = 0;
            lakes.sort((o1, o2) -> Integer.compare(o1.size(), o2.size()));
            int toRemove = lakes.size() - k;
            for (int i = 0; i < toRemove; i++) {
                GraphUtils.Cell someCell = lakes.get(i).get(0);
                ans += lakes.get(i).size();
                visited = new boolean[n][m];
                replceWith('.', '*', someCell.r, someCell.c);
            }

            prepocess('#', '.');

            out.println(ans);
            debug(map, out);
        }

        private void findLakes(ArrayList<GraphUtils.Cell> lake, int r, int c) {

            if (!isvalid(r, c) || map[r][c] != '.') {
                return;
            }

            if (visited[r][c]) return;

            lake.add(new GraphUtils.Cell(r, c));
            visited[r][c] = true;
            for (int i = 0; i < dr.length; i++) {
                int nr = dr[i] + r;
                int nc = dc[i] + c;
                findLakes(lake, nr, nc);
            }
        }

        private void prepocess(char oldC, char newC) {

            visited = new boolean[n][m];



            for (int i = 0; i < n; i++) {
                if (!visited[i][0])
                    replceWith(oldC, newC, i, 0);
            }

            for (int i = 0; i < m; i++) {
                if (!visited[0][i])
                    replceWith(oldC, newC, 0, i);
            }

            for (int i = 0; i < n; i++) {
                if (!visited[i][m - 1])
                    replceWith(oldC, newC, i, m - 1);
            }

            for (int i = 0; i < m; i++) {
                if (!visited[n - 1][i])
                    replceWith(oldC, newC, n - 1, i);
            }
        }

        void debug(char[][] map, OutputWriter outputWriter) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    outputWriter.print(map[i][j]);
                }
                outputWriter.println();
            }

        }

        void replceWith(char oldChar, char newChar, int r, int c) {

            if (!isvalid(r, c) || map[r][c] != oldChar) {
                return;
            }

            if (visited[r][c]) return;

            map[r][c] = newChar;
            visited[r][c] = true;
            for (int i = 0; i < dr.length; i++) {
                int nr = dr[i] + r;
                int nc = dc[i] + c;
                replceWith(oldChar, newChar, nr, nc);
            }

        }

        private boolean isvalid(int r, int c) {
            return r >= 0 && r < n && c >= 0 && c < m;
        }

    }

    static class GraphUtils {
        public static class Cell {
            public int r;
            public int c;

            public Cell(int r, int c) {
                this.r = r;
                this.c = c;
            }

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void println() {
            writer.println();
        }

        public void print(char i) {
            writer.print(i);
        }

        public void close() {
            writer.close();
        }

        public void println(int i) {
            writer.println(i);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res =+ c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

