    public void run() {
        try {
            timeBegin = System.currentTimeMillis();
            memoryTotal = Runtime.getRuntime().freeMemory();
            init();
            solve();
            out.close();
            if (System.getProperty("ONLINE_JUDGE") == null) {
                time();
                memory();
            }
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(-1);
        }
    }

    int n, m;

    boolean isSea(int i, int j) {
        if (i == 0 || j == 0) return true;
        if (i == n-1 || j == m - 1) return true;
        return false;
    }

    boolean valid(int i, int j) {
        return i >= 0 && j >= 0 && i < n && j < m;
    }

    class Component implements Comparable<Component> {
        List<Integer> ises = new ArrayList<>();
        List<Integer> jses = new ArrayList<>();

        void add(int i, int j) {
            ises.add(i);
            jses.add(j);
        }

        int size() {
            return ises.size();
        }

        @Override
        public int compareTo(Component o) {
            return size() - o.size();
        }
    }

    void solve() throws IOException {
        n = readInt();
        m = readInt();
        int k = readInt();

        char[][] a = new char[n][];
        for (int i = 0; i < n; i++) {
            a[i] = readString().toCharArray();
        }

        boolean[][] vis = new boolean[n][m];

        int[] di = {0, 0, 1, -1};
        int[] dj = {1, -1, 0, 0};
        PriorityQueue<Component> sizes = new PriorityQueue<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (vis[i][j]) continue;
                if (a[i][j] == '*') continue;
                ArrayDeque<Integer> dequeX = new ArrayDeque<>();
                ArrayDeque<Integer> dequeY = new ArrayDeque<>();
                dequeX.add(i);
                dequeY.add(j);
                vis[i][j] = true;

                Component component = new Component();
                boolean haveSea = false;
                while (dequeX.size() > 0) {
                    int ci = dequeX.poll();
                    int cj = dequeY.poll();
                    haveSea |= isSea(ci, cj);
                    component.add(ci, cj);

                    for (int s = 0; s < 4; s++) {
                        int ni = ci + di[s];
                        int nj = cj + dj[s];
                        if (valid(ni, nj) && a[ni][nj] == '.' && !vis[ni][nj]) {
                            vis[ni][nj] = true;
                            dequeX.add(ni);
                            dequeY.add(nj);
                        }
                    }
                }
                if (!haveSea) {
                    sizes.add(component);
                }
            }
        }

        int cnt = 0;
        while (sizes.size() > k) {
            Component component = sizes.poll();
            for (int i = 0; i < component.size(); i++) {
                a[component.ises.get(i)][component.jses.get(i)] = '*';
                cnt++;
            }
        }
        out.println(cnt);
        for (char[] x : a) {
            out.println(new String(x));
        }
    }
}

