import java.io.*;
import java.util.*;

public class Solution {
    static BufferedReader br;
    StringTokenizer tokenizer;
    static PrintWriter out;

    class Pair {
        int x, y;

        Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    int n, m;
    char[][] g;
    boolean[][] used;
    int[] dx = {0, 0, 1, -1};
    int[] dy = {1, -1, 0, 0};
    ArrayList<Pair> lakeSize;

    void dfs(int x, int y) {
        if (used[x][y] || g[x][y] != '.') {
            return;
        }
        used[x][y] = true;
        lakeSize.add(new Pair(x, y));

        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i];
            int my = y + dy[i];
            if (nx < 0 || nx >= n) {
                continue;
            }
            if (my < 0 || my >= m) {
                continue;
            }
            if (!used[nx][my]) {
                dfs(nx, my);
            }
        }
    }

    void run() throws IOException {
        n = nextInt();
        m = nextInt();
        int k = nextInt();

        g = new char[n][m];
        used = new boolean[n][m];
        lakeSize = new ArrayList<Pair>();
        ArrayList<ArrayList<Pair>> ans = new ArrayList<ArrayList<Pair>>();

        for (int i = 0; i < n; i++) {
            String s = br.readLine();
            for (int j = 0; j < m; j++) {
                g[i][j] = s.charAt(j);
            }
        }

        for (int i = 0; i < n; i++) {
            dfs(i, 0);
            dfs(i, m - 1);
        }
        for (int i = 0; i < m; i++) {
            dfs(0, i);
            dfs(n - 1, i);
        }

        int lakes = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!used[i][j] && g[i][j] == '.') {
                    lakeSize = new ArrayList<Pair>();
                    dfs(i, j);
                    ++lakes;
                    ans.add(lakeSize);
                }
            }
        }

        if (lakes == k) {
            out.print(0 + "\n");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    out.print(g[i][j]);
                }
                out.print("\n");
            }
            return;
        }

        Comparator<ArrayList<Pair>> cmp = new Comparator<ArrayList<Pair>>() {
            @Override
            public int compare(ArrayList<Pair> o1, ArrayList<Pair> o2) {
                if (o1.size() != o2.size()) {
                    return o1.size() - o2.size();
                }
                return 0;
            }
        };

        Collections.sort(ans, cmp);

        int a = 0;
        for (int i = 0; i < ans.size() - k; i++) {
            for (int j = 0; j < ans.get(i).size(); j++) {
                g[ans.get(i).get(j).x][ans.get(i).get(j).y] = '*';
                ++a;
            }
        }

        out.print(a + "\n");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out.print(g[i][j]);
            }
            out.print("\n");
        }
    }

    String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(br.readLine());
        }
        return tokenizer.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    public static void main(String[] args) throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        new Solution().run();
        br.close();
        out.close();
    }
}

