		for (int i = 0; i < n; i++) {
			System.out.println(new String(map[i]));
		}
	}

	public static final int[][] dirs = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 }, }};

	private static boolean dfs(int row, int col, char[][] map, boolean[][] visited, LinkedList<int[]> coords) {
		boolean isOcean = (row == 0) || (col == 0) || (row == map.length - 1) || (col == map[0].length - 1);

		visited[row][col] = true;
		coords.add(new int[] { row, col });

		for (int i = 0; i < 4; i++) {
			int nextRow = row + dirs[i][0];
			int nextCol = col + dirs[i][1];
			if (nextRow >= 0 && nextRow < map.length && nextCol >= 0 && nextCol < map[0].length) {
				if (!visited[nextRow][nextCol] && map[nextRow][nextCol] == '.') {
					isOcean |= dfs(nextRow, nextCol, map, visited, coords);
				}
			}
		}
		return isOcean;
	}
