public class Codeforces 
{	
	public static class Point
	{
		int row, column; 

		public Point(){}; 
		public Point(int newRow, int newColumn)
		{
			row = newRow; 
			column = newColumn; 
		}
	}

	static char map[][] = new char[51][51];
	static boolean visited[][] = new boolean[101][101];
	static List< List<Point> > lake = new ArrayList< List<Point> >(51);
	static int dirI[] = {0, 0, 1, -1}, dirJ[] = {1, -1, 0, 0}; 
	static Scanner input = new Scanner(System.in);

	private static void constructLake(int row, int column, int numberOfRows, int numberOfColumns)
	{

		List currentLake = new ArrayList<Point>();
		boolean isOcean = false; 

		Queue <Point> queue = new LinkedList <Point> ();
		queue.add(new Point(row, column)); 

		while (queue.isEmpty() == false) 
		{			 
			 Point currentPoint = queue.element(); 
			 queue.remove(); 


			 if (visited[currentPoint.row][currentPoint.column] == true)
				 continue; 
			 visited[currentPoint.row][currentPoint.column] = true; 


			 if (currentPoint.row == 0 || currentPoint.row == numberOfRows-1)
				 isOcean = true; 
			 if (currentPoint.column == 0 || currentPoint.column == numberOfColumns-1)
				 isOcean = true; 

			 currentLake.add(currentPoint); 



			 for (int index = 0; index < 4; index++)
			 {
				 int nextRow = currentPoint.row + dirI[index]; 
				 int nextColumn = currentPoint.column + dirJ[index];


				 if (nextRow < 0 || nextColumn < 0 || nextRow >= numberOfRows || nextColumn >= numberOfColumns)
					 continue; 

				 if (map[nextRow][nextColumn] == '*')
					 continue; 

				 if (visited[nextRow][nextColumn] == true)
					 continue; 

				 queue.add(new Point(nextRow, nextColumn)); 
			 }		 
		}

		if (isOcean == false)  
			lake.add(currentLake);


	}

	public static void main(String[] args)
	{
		int numberOfRows = input.nextInt();
		int numberOfColumns = input.nextInt(); 
		int requiredLakes = input.nextInt(); 

		for (int row = 0; row < numberOfRows; row++)
		{
			String line = input.next();
			for (int column = 0; column < numberOfColumns; column++)
				map[row][column] = line.charAt(column);
		}

		for (int row = 1; row < numberOfRows-1; row++) 
			for (int column = 1; column < numberOfColumns-1; column++)
				if (map[row][column] == '.' && visited[row][column] == false) 
					constructLake(row, column, numberOfRows, numberOfColumns);

		Collections.sort(lake, new Comparator<List<Point>>() {
			public int compare(List<Point> list1, List<Point> list2)
				{return list1.size() - list2.size();}
		});

		int result = 0; 
		for (int lakesDestroyed = 0; lakesDestroyed < lake.size()-requiredLakes; lakesDestroyed++)
			for (int index = 0; index < lake.get(lakesDestroyed).size(); index++)
			{
				int changeRow = lake.get(lakesDestroyed).get(index).row; 
				int changeColumn = lake.get(lakesDestroyed).get(index).column;
				map[changeRow][changeColumn] = '*'; 

				result++;
			}

		System.out.println(result); 
		for (int row = 0; row < numberOfRows; row++)
		{
			for (int column = 0; column < numberOfColumns; column++)
				System.out.print(map[row][column]);
			System.out.println();
		}
	} 	
}

