        for(int i=0; i<n; i++) {
            for (int j = 0; j < m; j++) {
                if(earth[i][j] == '.' && visited[i][j] == false) {
                    cntLakeCells = 0;
                    if(dfs(i, j)) {
                        Lake lake = new Lake(cntLakeCells, j,i);
                        lakes.add(lake);
                    }
                }
            }
        }

        int lakeSize = lakes.size();
        Collections.sort(lakes);
        int i=0;
        int covered = 0;
        visited2 = new boolean[n][m];
