        if(y >= n || x >= m) return;
        if(y < 0 || x < 0) return;
        if(earth[y][x] == '*') return;
        if(visited2[y][x] == true) return;

        visited2[y][x] = true;
        earth[y][x] = '*';

        for(int i=0; i<4; i++) {
            coverLake(y+Y[i], x+X[i]);
        }

    }
    public static boolean dfs(int y, int x) {
        if(y >= n || x >= m) return false;
        if(y < 0 || x < 0) return false;
        if(earth[y][x] == '*') return true;
        if(visited[y][x]) return false;

        visited[y][x] = true;
        cntLakeCells++;


        boolean isLake = true;
        for(int i=0; i<4; i++) {
            isLake = isLake & dfs(y+Y[i], x+X[i]);
        }

        return isLake;
    }

