public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        DLakesInBerland solver = new DLakesInBerland();
        solver.solve(1, in, out);
        out.close();
    }

    static class DLakesInBerland {
        private int n;
        private int m;
        private char[][] arr;
        private int[][] vis;
        private int comp_id = 1;
        private int comp_size;

        private boolean isValid(int x, int y) {
            return x >= 0 && x <= n + 1 && y >= 0 && y <= m + 1 && arr[x][y] == '.' && vis[x][y] == 0;
        }

        private void floodFill(int x, int y) {
            vis[x][y] = comp_id;
            comp_size++;
            if (isValid(x + 1, y)) floodFill(x + 1, y);
            if (isValid(x - 1, y)) floodFill(x - 1, y);
            if (isValid(x, y + 1)) floodFill(x, y + 1);
            if (isValid(x, y - 1)) floodFill(x, y - 1);
        }

        private void printMatrix(OutputWriter out) {
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    out.print(arr[i][j]);
                }
                out.println();
            }
        }

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            n = in.nextInt();
            m = in.nextInt();
            int k = in.nextInt();
            arr = new char[n + 2][m + 2];
            for (int i = 0; i <= n + 1; i++) {
                arr[i][0] = arr[i][m + 1] = '.';
            }
            for (int j = 0; j <= m + 1; j++) {
                arr[0][j] = arr[n + 1][j] = '.';
            }

            for (int i = 1; i <= n; i++) {
                String str = in.nextLine();
                for (int j = 1; j <= m; j++) {
                    arr[i][j] = str.charAt(j - 1);
                }
            }
            vis = new int[n + 2][m + 2];
            floodFill(0, 0);
            ArrayList<Util.Pair<Integer>> al = new ArrayList<>();
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (arr[i][j] == '.' && vis[i][j] == 0) {
                        comp_size = 0;
                        comp_id++;
                        floodFill(i, j);
                        al.add(new Util.Pair<>(comp_size, comp_id));
                    }
                }
            }
            int numOfLakes = comp_id - 1;
            if (numOfLakes == k) {
                out.println(0);
                printMatrix(out);
                out.flush();
                return;
            }
            Collections.sort(al, Comparator.comparingInt(o -> o.x));
            HashSet<Integer> hs = new HashSet<>();
            int toDelete = numOfLakes - k;
            int cellsChanged = 0;
            for (int i = 0; i < toDelete; i++) {
                Util.Pair<Integer> p = al.get(i);
                cellsChanged += p.x;
                hs.add(p.y);
            }
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (arr[i][j] == '.' && hs.contains(vis[i][j])) arr[i][j] = '*';
                }
            }
            out.println(cellsChanged);
            printMatrix(out);
            out.flush();
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;
        private ArrayList<String> res = new ArrayList<>();
        private StringBuilder sb = new StringBuilder("");

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void println(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                sb.append(objects[i]);
            }
            res.add(sb.toString());
            sb = new StringBuilder("");
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                sb.append(objects[i]);
            }
        }

        public void close() {

            writer.close();
        }

        public void flush() {
            for (String str : res) writer.printf("%s\n", str);
            res.clear();
            sb = new StringBuilder("");
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[8192];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public InputReader(FileInputStream file) {
            this.stream = file;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res = (res << 3) + (res << 1) + c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String nextLine() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

    }

    static class Util {
        public static class Pair<T> {
            public T x;
            public T y;

            public Pair(T x, T y) {
                this.x = x;
                this.y = y;
            }

            public boolean equals(Object obj) {
                if (obj == this) return true;
                if (!(obj instanceof Util.Pair)) return false;
                Util.Pair<T> pair = (Util.Pair<T>) obj;
                return this.x == pair.x && this.y == pair.y;
            }

            public String toString() {
                return ("(" + this.x + "," + this.y + ")");
            }

            public int hashCode() {
                return Objects.hash(x, y);
            }

        }

    }
}

