            this.sl = sl;
            this.x = x;
            this.y = y;
        }
        @Override
        public int compareTo(ds other) {
            return ((Integer) this.sl).compareTo(other.sl);
        }
    }
    static int dfs(int u, int v, int n, int m, StringBuilder[] b){
        int sum = 1;
        b[u].setCharAt(v, '*');
        for (int i = 0; i < 4; i++){
            int x = u + dx[i];
            int y = v + dy[i];
            if (x >= 0 && x < n && y >= 0 && y < m)
            if (b[x].charAt(y)=='.'){
                sum += dfs(x, y, n, m, b);
            }
        }
        return sum;
    }
