        {
            c[i] = new StringBuilder(a[i]) ;
        }

        for (int i = 0; i < n; i++)
        {
            if (a[i].charAt(0) == '.') dfs(i,0,n,m,b);
            if (a[i].charAt(m-1) == '.') dfs(i,m-1,n,m,b);	
