        for (int i = 0; i < n; i++){
            for (int j = 0; j < m; j++)
            if (b[i].charAt(j) == '.'){          // <-- fixed condition
                list.add(new ds(dfs(i,j,n,m,b), i, j));
            }
        }
        Collections.sort(list);
        int ans = 0;
        for (int i = 0; i < list.size() - k; i++){
            ds tmp = list.get(i);
            ans += dfs(tmp.x,tmp.y,n,m,c);
        }
        System.out.println(ans);
        for (int i = 0; i < n;i++) {
            System.out.println(c[i]);
        }
    }
