public class Main {
    private static Scanner sc = new Scanner(System.in);
    public static void main(String[] args) {
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        int needLakes = sc.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < grid.length; i++) {
            String line = sc.next();
            for (int j = 0; j < grid[i].length; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        List<Set<Point>> lakes = getLakes(grid);
        Collections.sort(lakes, (o1, o2) -> new Integer(o2.size()).compareTo(o1.size()));

        int nChanges = 0;
        while (needLakes < lakes.size()) {
            Set<Point> smallestLake = lakes.remove(lakes.size() - 1);
            for (Point point : smallestLake) {
                grid[point.i][point.j] = '*';
                nChanges++;
            }
        }

        System.out.println(nChanges);
        printGrid(grid);
    }

    private static void printGrid(char[][] grid) {
        for (char[] row : grid) {
            for (char c : row) {
                System.out.print(c);
            }
            System.out.println();
        }
    }

    private static List<Set<Point>> getLakes(char[][] grid) {
        List<Set<Point>> res = new ArrayList<>();
        boolean[][] visited = new boolean[grid.length][grid[0].length];
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == '*' || visited[i][j]) {
                    continue;
                }

                Set<Point> curLake = getLakeFrom(new Point(i, j), grid, visited);
                if (curLake != null) {
                    res.add(curLake);
                }
            }
        }
        return res;
    }

    private static Set<Point> getLakeFrom(Point point, char[][] grid, boolean[][] visited) {
        if (isEdge(point, grid))
            return null;

        visited[point.i][point.j] = true;

        Set<Point> res = new HashSet<>();
        res.add(point);
        Set<Point> allDistantNeighbours = getAllDistantNeighbours(point, grid, visited);
        res.addAll(allDistantNeighbours);

        for (Point curPoint : res) {
            if (isEdge(curPoint, grid))
                return null;
        }

        return res;
    }

    private static Set<Point> getAllDistantNeighbours(Point point, char[][] grid, boolean[][] visited) {
        Set<Point> res = new HashSet<>();
        Set<Point> nearNeighbours = getNearNeighbours(point, grid, visited);
        res.addAll(nearNeighbours);
        nearNeighbours.forEach(x -> visited[x.i][x.j] = true);
        for (Point nearNeighbour : nearNeighbours) {
            res.addAll(getAllDistantNeighbours(nearNeighbour, grid, visited));
        }

        return res;
    }

    private static Set<Point> getNearNeighbours(Point point, char[][] grid, boolean[][] visited) {
        Set<Point> res = new HashSet<>();
        List<Point> candidates = getNearNeighbourCandidates(point, grid);
        candidates.stream().filter(p -> grid[p.i][p.j] == '.' && !visited[p.i][p.j]).forEach(p -> {
            visited[p.i][p.j] = true;
            res.add(p);
        });
        return res;
    }

    private static List<Point> getNearNeighbourCandidates(Point point, char[][] grid) {
        List<Point> res = new ArrayList<>();
        List<Point> candidates = new ArrayList<>();
        candidates.add(new Point(point.i + 1, point.j));
        candidates.add(new Point(point.i - 1, point.j));
        candidates.add(new Point(point.i, point.j + 1));
        candidates.add(new Point(point.i, point.j - 1));
        res.addAll(candidates.stream().filter(candidate -> isInRange(candidate, grid)).collect(Collectors.toList()));
        return res;
    }

    private static boolean isEdge(Point point, char[][] grid) {
        return point.i == 0 || point.i == grid.length - 1 || point.j == 0 || point.j == grid[0].length - 1;
    }

    private static boolean isInRange(Point point, char[][] grid) {
        return point.i >= 0 && point.i < grid.length && point.j >= 0 && point.j < grid[0].length;
    }

    private static class Point {
        int i, j;

        Point(int i, int j) {
            this.i = i;
            this.j = j;
        }

        @Override
        public boolean equals(Object obj) {
            if (obj == null)
                return false;

            if (!(obj instanceof Point))
                return false;

            Point p1 = (Point) obj;
            return this.i == p1.i && this.j == p1.j;
        }
    }
}

import java.util.*;
import java.util.stream.Collectors;

public class Main {
    private static Scanner sc = new Scanner(System.in);
    public static void main(String[] args) {
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        int needLakes = sc.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < grid.length; i++) {
            String line = sc.next();
            for (int j = 0; j < grid[i].length; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        List<Set<Point>> lakes = getLakes(grid);
        Collections.sort(lakes, (o1, o2) -> new Integer(o2.size()).compareTo(o1.size()));

        int nChanges = 0;
        while (needLakes < lakes.size()) {
            Set<Point> smallestLake = lakes.remove(lakes.size() - 1);
            for (Point point : smallestLake) {
                grid[point.i][point.j] = '*';
                nChanges++;
            }
        }

        System.out.println(nChanges);
        printGrid(grid);
    }

    private static void printGrid(char[][] grid) {
        for (char[] row : grid) {
            for (char c : row) {
                System.out.print(c);
            }
            System.out.println();
        }
    }

    private static List<Set<Point>> getLakes(char[][] grid) {
        List<Set<Point>> res = new ArrayList<>();
        boolean[][] visited = new boolean[grid.length][grid[0].length];
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == '*' || visited[i][j]) {
                    continue;
                }

                Set<Point> curLake = getLakeFrom(new Point(i, j), grid, visited);
                if (curLake != null) {
                    res.add(curLake);
                }
            }
        }
        return res;
    }

    private static Set<Point> getLakeFrom(Point point, char[][] grid, boolean[][] visited) {
        if (isEdge(point, grid))
            return null;

        visited[point.i][point.j] = true;

        Set<Point> res = new HashSet<>();
        res.add(point);
        Set<Point> allDistantNeighbours = getAllDistantNeighbours(point, grid, visited);
        res.addAll(allDistantNeighbours);

        for (Point curPoint : res) {
            if (isEdge(curPoint, grid))
                return null;
        }

        return res;
    }

    private static Set<Point> getAllDistantNeighbours(Point point, char[][] grid, boolean[][] visited) {
        Set<Point> res = new HashSet<>();
        Set<Point> nearNeighbours = getNearNeighbours(point, grid, visited);
        res.addAll(nearNeighbours);
        nearNeighbours.forEach(x -> visited[x.i][x.j] = true);
        for (Point nearNeighbour : nearNeighbours) {
            res.addAll(getAllDistantNeighbours(nearNeighbour, grid, visited));
        }

        return res;
    }

    private static Set<Point> getNearNeighbours(Point point, char[][] grid, boolean[][] visited) {
        Set<Point> res = new HashSet<>();
        Set<Point> nearNeighbours = getNearNeighbourCandidates(point, grid);
        res.addAll(nearNeighbours);
        nearNeighbours.forEach(x -> visited[x.i][x.j] = true);
        return res;
    }

    private static List<Point> getNearNeighbourCandidates(Point point, char[][] grid) {
        List<Point> res = new ArrayList<>();
        List<Point> candidates = new ArrayList<>();
        candidates.add(new Point(point.i + 1, point.j));
        candidates.add(new Point(point.i - 1, point.j));
        candidates.add(new Point(point.i, point.j + 1));
        candidates.add(new Point(point.i, point.j - 1));   // fixed: was point.j - 0
        res.addAll(candidates.stream().filter(candidate -> isInRange(candidate, grid)).collect(Collectors.toList()));
        return res;
    }

    private static boolean isEdge(Point point, char[][] grid) {
        return point.i == 0 || point.i == grid.length - 1 || point.j == 0 || point.j == grid[0].length - 1;
    }

    private static boolean isInRange(Point point, char[][] grid) {
        return point.i >= 0 && point.i < grid.length && point.j >= 0 && point.j < grid[0].length;
    }

    private static class Point {
        int i, j;

        Point(int i, int j) {
            this.i = i;
            this.j = j;
        }

        @Override
        public boolean equals(Object obj) {
            if (obj == null)
                return false;

            if (!(obj instanceof Point))
                return false;

            Point p1 = (Point) obj;
            return this.i == p1.i && this.j == p1.j;
        }
    }
}

