import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.StringTokenizer;

public class A {

    static final int[] dx = { 0, 0, 1, -1 };
    static final int[] dy = { -1, 1, 0, 0 };
    static int R, C;
    static int[][] getCC;
    static char[][] grid;

    static boolean valid(int x, int y) { return x >= 0 && y >= 0 && x < R && y < C; }

    static int dfs(int x, int y, int c) {
        int ret = 1;
        grid[x][y] = '$';
        getCC[x][y] = c;
        for (int k = 0; k < 4; ++k) {
            int i = x + dx[k];
            int j = y + dy[k];
            if (valid(i, j)) {
                if (grid[i][j] != '.')
                    continue;
                int cur = dfs(i, j, c);
                if (cur == -1)
                    ret = -1;
                if (ret != -1)
                    ret += cur;
            } else {
                ret = -1;
            }
        }
        return ret;
    }

    public static void main(String[] args) throws IOException {
        java.util.Scanner sc = new java.util.Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        R = sc.nextInt();
        C = sc.nextInt();
        int k = sc.nextInt();
        grid = new char[R][C];
        getCC = new int[R][C];
        for (int i = 0; i < R; ++i)
            grid[i] = sc.next().toCharArray();

        ArrayList<Pair> ccs = new ArrayList<>();
        int c = 0;
        for (int i = 0; i < R; ++i)
            for (int j = 0; j < C; ++j)
                if (grid[i][j] == '.') {
                    Pair p = new Pair(c, dfs(i, j, c++));
                    if (p.count != -1)
                        ccs.add(p);
                }
        Collections.sort(ccs);
        int ans = 0;
        boolean[] makeLand = new boolean[c];
        for (int i = 0; ccs.size() - i > k; ++i) {
            makeLand[ccs.get(i).idx] = true;
            ans += ccs.get(i).count;
        }
        for (int i = 0; i < R; ++i)
            for (int j = 0; j < C; ++j)
                if (grid[i][j] == '$')
                    if (makeLand[getCC[i][j]])
                        grid[i][j] = '*';
                    else
                        grid[i][j] = '.';
        out.println(ans);
        for (char[] x : grid)
            out.println(x);
        out.flush();
        out.close();
    }

    static class Pair implements Comparable<Pair> {
        int idx, count;

        Pair(int a, int b) {
            idx = a;
            count = b;
        }

        public int compareTo(Pair p) {
            return count - p.count;
        }
    }

    static class Scanner {
        StringTokenizer st;
        BufferedReader br;

        Scanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        String nextLine() throws IOException {
            return br.readLine();
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

