public class SolveDD {
    public static class Pair implements Comparable {
        int size, x, y;
        Pair(int size, int x, int y) {
            this.size = size;
            this.x = x;
            this.y = y;
        }
        public int compareTo(Object o) {
            Pair pp = (Pair) o;
            if (pp.size == size) return 0;
            else if (size > pp.size) return 1;
            else return -1;
        }
    }
    public static boolean marked[][];
    public static int count = 0, min, kk = 0;
    public static void main(String[] args) throws IOException {
        Reader in = new Reader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));
        int n = in.nextInt();
        int m = in.nextInt();
        int k = in.nextInt();
        char mat[][] = new char[n][m];
        char dup[][] = new char[n][m];
        for (int i = 0; i < n; i++) {
            mat[i] = in.next().toCharArray();
            for (int j = 0; j < m; j++)
                dup[i][j] = mat[i][j];
        }
        marked = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            if (mat[i][0] == '.') {
                fill(mat, i, 0, n, m);
            }
            if (mat[i][m - 1] == '.') {
                fill(mat, i, m - 1, n, m);
            }
        }
        for (int i = 0; i < m; i++) {
            if (mat[0][i] == '.') {
                fill(mat, 0, i, n, m);
            }
            if (mat[n - 1][i] == '.') {
                fill(mat, n - 1, i, n, m);
            }
        }
        int arr[][] = new int[n][m];
        min = Integer.MAX_VALUE;
        int startx = -1, starty = -1;
        kk = 0;
        ArrayList<Pair> list = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (mat[i][j] == '*') continue;
                if (!marked[i][j]) {
                    count = 0;
                    dfs(mat, i, j, n, m);
                    list.add(new Pair(count, i, j));
                }
            }
        }
        Collections.sort(list);
        int localKk = 0;
        min = 0;
        localKk = list.size() - k;
        for (int i = 0; i < localKk; i++) {
            min += list.get(i).size;
            fill(dup, list.get(i).x, list.get(i).y, n, m);
        }
        out.println(min);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out.print(dup[i][j]);
            }
            out.println();
        }
        out.flush();
        out.close();
    }

    private static void fill(char[][] mat, int x, int y, int n, int m) {
        mat[x][y] = '*';
        if (x + 1 < n && mat[x + 1][y] == '.')
            fill(mat, x + 1, y, n, m);
        if (y + 1 < m && mat[x][y + 1] == '.')
            fill(mat, x, y + 1, n, m);
        if (x - 1 >= 0 && mat[x - 1][y] == '.')
            fill(mat, x - 1, y, n, m);
        if (y - 1 >= 0 && mat[x][y - 1] == '.')
            fill(mat, x, y - 1, n, m);
    }

    private static void dfs(char[][] mat, int x, int y, int n, int m) {
        count++;
        marked[x][y] = true;
        if (x + 1 < n && mat[x + 1][y] == '.' && marked[x + 1][y] == false)
            dfs(mat, x + 1, y, n, m);
        if (y + 1 < m && mat[x][y + 1] == '.' && marked[x][y + 1] == false)
            dfs(mat, x, y + 1, n, m);
        if (x - 1 >= 0 && mat[x - 1][y] == '.' && marked[x - 1][y] == false)
            dfs(mat, x - 1, y, n, m);
        if (y - 1 >= 0 && mat[x][y - 1] == '.' && marked[x][y - 1] == false)
            dfs(mat, x, y - 1, n, m);
    }

