        public int compare(LinkedList<Pair> a,LinkedList<Pair> b){
            return a.size()-b.size();
        }
    }
    static boolean visited[][];
    static LinkedList<LinkedList<Pair>> list=new LinkedList<LinkedList<Pair>>();
    static LinkedList<Pair> temp;
    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);
