        for(int i=0;i<n;i++){
            String str=sc.next();
            for(int j=0;j<m;j++){
                A[i][j]=str.charAt(j);
            }
        }
        /* mark all water cells that are connected to the ocean */
        for(int i=0;i<m;i++){
            if(A[0][i]=='.'){
                DFSForPlus(0,i);
            }
            if(A[n-1][i]=='.'){
                DFSForPlus(n-1,i);
            }
        }
