	private static List<Point> lakeList = new ArrayList<Point>();

	private static boolean isLake(Point start) {
		boolean ret = true;
		int count = 1;
		Queue<Point> queue = new LinkedList<Point>();
		queue.add(start);
		visited[start.x][start.y] = true;
		int x, y;
		Point tmp;
		if (start.x == 0 || start.x == rowNum - 1 || start.y == 0 || start.y == colNum - 1) {
			ret = false;
		}

		while (!queue.isEmpty()) {
			tmp = queue.poll();

			for (int i=0;i<4;i++) {
				x = tmp.x + dx[i];
				y = tmp.y + dy[i];

				if (x >= 0 && x < rowNum && y >= 0 && y < colNum) {
					if (!visited[x][y] && matrix[x][y] == '.') {
						visited[x][y] = true;
						queue.add(new Point(x, y));
						count++;
						if (ret && (x == 0 || x == rowNum - 1 || y == 0 || y == colNum - 1)) {
							ret = false;
						}
					}
				}
			}
		}

		if (ret) {
			start.setCount(count);
		}
		return ret;
	}

	private static int dfs(Point start) {
		int count = 1;
		Queue<Point> queue = new LinkedList<Point>();
		queue.add(start);
		visited[start.x][start.y] = false;
		matrix[start.x][start.y] = '*';
		int x, y;
		Point tmp;

		while (!queue.isEmpty()) {
			tmp = queue.poll();

			for (int i=0;i<4;i++) {
				x = tmp.x + dx[i];
				y = tmp.y + dy[i];

				if (x >= 0 && x < rowNum && y >= 0 && y < colNum) {
					if (visited[x][y] && matrix[x][y] == '.') {
						visited[x][y] = false;
						queue.add(new Point(x, y));
						matrix[x][y] = '*';
						count++;
					}
				}
			}
		}

		return count;
	}

	public static void main(String[] args) {
