		in.nextLine();
		int lakeCount = 0;
		matrix = new char[rowNum][colNum];

		for (int i=0;i<rowNum;i++) {
			matrix[i] = in.nextLine().toCharArray();
		}

		for (int i=0;i<rowNum;i++) {
			for (int j=0;j<colNum;j++) {
				if (matrix[i][j] == '.' && !visited[i][j]) {
					Point start = new Point(i, j);
					if (isLake(start)) {
						lakeList.add(start);
						lakeCount++;
					}
				}
			}
		}

		int count = 0;
		if (lakeCount > k) {
			int n = lakeCount - k;
			Collections.sort(lakeList, new Comparator<Point>() {

				@Override
				public int compare(Point p1, Point p2) {
					return p1.getCount() - p2.getCount();
				}

			});

			for (Point p : lakeList) {
				int landCount = dfs(p);
				count += landCount;
				n--;
				if (n == 0) {
					break;
				}
			}

		}

		System.out.println(count);
		for (int i=0;i<rowNum;i++) {
			for (int j=0;j<colNum;j++) {
				System.out.print(matrix[i][j]);
			}
			System.out.println();
		}

		in.close();
	}
}

