import java.io.*;
import java.util.*;

public class Solution {
    static char[][] grid;
    static char[][] gridNew;
    static int n;
    static int m;
    static boolean[][] visited;
    static int count;
    static boolean prob;

    static void dfs(int i, int j) {
        if (i >= n || j >= m || i < 0 || j < 0 || visited[i][j] || grid[i][j] == '*') {
            return;
        }
        visited[i][j] = true;
        if (i == n - 1 || i == 0 || j == m - 1 || j == 0) {
            prob = true;
        }
        count++;
        dfs(i + 1, j);
        dfs(i, j - 1);      // fixed: was dfs ( j,i - 1);
        dfs(i, j + 1);
        dfs(i, j - 1);
    }

    static void dfsChange(int i, int j) {
        if (i >= n || j >= m || i < 0 || j < 0 || visited[i][j] || grid[i][j] == '*') {
            return;
        }
        visited[i][j] = true;
        gridNew[i][j] = '*';
        dfsChange(i + 1, j);
        dfsChange(i - 1, j);
        dfsChange(i, j + 1);
        dfsChange(i, j - 1);
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        int k = sc.nextInt();
        grid = new char[n][m];
        gridNew = new char[n][m];
        visited = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            String s = sc.nextLine();
            for (int j = 0; j < m; j++) {
                grid[i][j] = s.charAt(j);
                gridNew[i][j] = s.charAt(j);
            }
        }

