public class Solution {
    static char[][] grid;
    static char[][] gridNew;
    static int n;
    static int m;
    static boolean[][] visited;
    static int count;
    static boolean prob;

    static void dfs(int i, int j) {
        if (i >= n || j >= m || i < 0 || j < 0 || visited[i][j] || grid[i][j] == '*') {
            return;
        }
        visited[i][j] = true;
        if (i == n - 1 || i == 0 || j == m - 1 || j == 0) {
            prob = true;
        }
        count++;
        dfs(i + 1, j);
        dfs(i - 1, j);
        dfs(i, j + 1);
        dfs(i, j - 1);
    }

    static void dfsChange(int i, int j) {
        if (i >= n || j >= m || i < 0 || j < 0 || visited[i][j] || grid[i][j] == '*') {
            return;
        }
        visited[i][j] = true;
        gridNew[i][j] = '*';
        dfsChange(i + 1, j);
        dfsChange(i - 1, j);
        dfsChange(i, j + 1);
        dfsChange(i, j - 1);
    }

