public class Main {
    static InputReader in = new InputReader(System.in);
    static PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {
        new Solution().solve();
        out.close();
    }

    static class Solution {
        boolean[][] visited;
        char[][] map;
        int[] dr = {0, 0, -1, 1};
        int[] dc = {-1, 1, 0, 0};
        int numRows, numCols;
        int size;

        public void solve() {
            numRows = in.nextInt();
            numCols = in.nextInt();
            int finalNumLakes = in.nextInt();
            map = new char[numRows][];

            for (int r = 0; r < numRows; r++) {
                map[r] = in.next().toCharArray();
            }

            visited = new boolean[numRows][];
            for (int r = 0; r < numRows; r++) {
                visited[r] = new boolean[numCols];
                Arrays.fill(visited[r], false);
            }

            for (int c = 0; c < numCols; c++) {
                if (map[0][c] == '.' && !visited[0][c]) {
                    dfsVisit(0, c);
                }
            }
            for (int c = 0; c < numCols; c++) {
                if (map[numRows - 1][c] == '.' && !visited[numRows - 1][c]) {
                    dfsVisit(numRows - 1, c);
                }
            }
            for (int r = 0; r < numRows; r++) {
                if (map[r][0] == '.' && !visited[r][0]) {
                    dfsVisit(r, 0);
                }
            }
            for (int r = 0; r < numRows; r++) {
                if (map[r][numCols - 1] == '.' && !visited[r][numCols - 1]) {
                    dfsVisit(r, numCols - 1);
                }
            }

            ArrayList<Lake> lakes = new ArrayList<>();
            for (int r = 1; r < numRows - 1; r++) {
                for (int c = 1; c < numCols - 1; c++) {
                    if (map[r][c] == '.' && !visited[r][c]) {
                        size = 0;
                        dfsVisit(r, c);
                        lakes.add(new Lake(r, c, size));
                    }
                }
            }

            Collections.sort(lakes, (o1, o2) -> Integer.compare(o1.size, o2.size));

            int numLakesToFill = lakes.size() - finalNumLakes;
            int fillCount = 0;
            for (int i = 0; i < numLakesToFill; i++) {
                dfsFill(lakes.get(i).sr, lakes.get(i).sc);
                fillCount += lakes.get(i).size;
            }

            out.println(fillCount);
            for (int r = 0; r < numRows; r++) {
                for (int c = 0; c < numCols; c++) {
                    out.print(map[r][c]);
                }
                out.println();
            }
        }

        private void dfsFill(int r, int c) {
            map[r][c] = '*';
            if (r < 1 || r > numRows - 2 || c < 1 || c > numCols - 2) {
                throw new RuntimeException("r = " + r + "; c = " + c);
            }
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (map[nr][nc] == '.') {
                    dfsFill(nr, nc);
                }
            }
        }

        private void dfsVisit(int r, int c) {
            visited[r][c] = true;
            size++;
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];
                if (nr > -1 && nr < numRows && nc > -1 && nc < numCols && map[nr][nc] == '.' && !visited[nr][nc]) {
                    dfsVisit(nr, nc);
                }
            }
        }

        class Lake {
            int sr;
            int sc;
            int size;

            Lake(int sr, int sc, int size) {
                this.sr = sr;
                this.sc = sc;
                this.size = size;
            }

            public String toString() {
                return "r = " + this.sr + "; c = " + this.sc + "; size = " + this.size;
            }
        }
    }

    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;
        public int numLines;

        public InputReader(InputStream inStream) {
            reader = new BufferedReader(new InputStreamReader(inStream));
            tokenizer = null;
            numLines = 0;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    numLines++;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Input Error");
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public char nextChar() {
            return next().charAt(0);
        }
    }
}

