public class Problem_723_D {
	public static final int testCases = 1;

	public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        for (int t = 1; t <= testCases; ++t) {
            Problem_723_D solver = new Problem_723_D ();
            solver.solve(t, in, out);
        }
        out.close();
    }

	int[][] map;
	boolean[][] used;
	int n, m, k;

	ArrayList <ArrayList <Pair>> vals;
	ArrayList <Pair> nvals;

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        n = in.nextInt();
        m = in.nextInt();
        k = in.nextInt();
        map = new int[n][m];
        used = new boolean[n][m];

        vals = new ArrayList <ArrayList <Pair>>();
        nvals = new ArrayList <Pair>();

        for (int i = 0; i < n; ++i) {
            char[] ss = in.next().toCharArray();
            for (int j = 0; j < m; ++j) {
                if (ss[j] == '*') {
                    map[i][j] = 1;
                }
            }
        }

        /* Visit all water cells connected to the border (ocean) */
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (!used[i][j] && map[i][j] == 0) {
                    if (i - 1 < 0 || i + 1 >= n || j - 1 < 0 || j + 1 >= m) {
                        dfs(i, j, false);
                    }
                }
            }
        }

        /* Collect all remaining water components (lakes) */
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (!used[i][j] && map[i][j] == 0) {
                    nvals.clear();
                    dfs(i, j, true);
                    vals.add((ArrayList<Pair>) nvals.clone());
                }
            }
        }

        Collections.sort(vals, new Comparator<ArrayList <Pair>> () {

            @Override
            public int compare(ArrayList<Pair> arg0, ArrayList<Pair> arg1) {
                if (arg0.size() < arg1.size()) {
                    return -1;
                } else if (arg0.size() > arg1.size()) {
                    return 1;
                } else {
                    return 0;
                }
            }
        });

        int sz = vals.size() - k;
        int res = 0;
        for (int i = 0; i < sz; ++i) {
            for (Pair id : vals.get(i)) {
                map[id.l][id.r] = 1;
            }
            res += vals.get(i).size();
        }

        out.println(res);
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                out.print(map[i][j] == 1 ? '*' : '.');
            }
            out.println();
        }
    }

    private void dfs(int i, int j, boolean put) {
        if (put) {
            nvals.add(new Pair(i, j));
        }
        used[i][j] = true;
        for (int dx = -1; dx < 2; ++dx) {
            for (int dy = -1; dy < 2; ++dy) {
                if (dx != 0 && dy != 0) continue;
                int nx = i + dx, ny = j + dy;
                if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;
                if (map[nx][ny] == 1) continue;
                if (used[nx][ny]) continue;
                dfs(nx, ny, put);
            }
        }
    }

    class Pair implements Comparable<Pair> {
        public int l, r;

        public Pair(int l, int r) {
            this.l = l;
            this.r = r;
        }

        @Override
        public int compareTo(Pair arg0) {
            if (this.l != arg0.l) {
                return this.l - arg0.l;
            }
            return this.r - arg0.r;
        }

    }


