    static void bfsLake(int x,int y){
    Queue<pair>s=new LinkedList<pair>() ;
     vis[x][y]=true;
     int cnt=1;
     s.add(new pair(x, y,0));
     while(!s.isEmpty()){
         pair cur=s.poll();
         for (int i = 0; i < 4; i++) {
             int nx=cur.x+dx[i];
