class pair implements Comparable<pair>{

    int x, y,size;

    public pair(int x, int y) {
        this.x = x;
        this.y = y;
    }
    public pair(int x, int y,int z) {
        this.x = x;
        this.y = y;
        size=z;
    }
    public int compareTo(pair o){
    return size-o.size;
    }

}

