public class D {
    String fileName = "D";

    boolean[][] matrix;
    boolean[][] scrMatrix;
    int[][] color;
    boolean[][] used;

    int[] deltaX = {1, -1, 0, 0};
    int[] deltaY = {0, 0, 1, -1};
    int count;

    public void dfs(int x, int y, int curColor) {
        color[x][y] = curColor;
        count += 1;
        for (int i = 0; i < deltaX.length; i++) {
            int tempX = x + deltaX[i];
            int tempY = y + deltaY[i];
            if (color[tempX][tempY] == -1 && matrix[tempX][tempY]) {
                dfs(tempX, tempY, curColor);
            }
        }
    }

    public void dfs2(int x, int y) {
        used[x][y] = true;
        matrix[x][y] = false;
        for (int i = 0; i < deltaX.length; i++) {
            int tempX = x + deltaX[i];
            int tempY = y + deltaY[i];
            if (color[tempX][tempY] == -1 && matrix[tempX][tempY]) {
                dfs2(tempX, tempY);
            }
        }
    }

    public void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();
        int k = nextInt();
        matrix = new boolean[n + 2][m + 2];
        scrMatrix = new boolean[n][m];
        color = new int[n + 2][m + 2];
        used = new boolean[n + 2][m + 2];
        for (int i = 0; i < (n + 2); i++) {
            for (int j = 0; j < (m + 2); j++) {
                color[i][j] = -1;
            }
        }
        for (int i = 1; i < (n + 1); i++) {
            String temp = nextToken();
            for (int j = 1; j < (m + 1); j++) {
                if (temp.charAt(j - 1) == '.') {
                    matrix[i][j] = true;
                    scrMatrix[i - 1][j - 1] = true;   // fixed indexing
                }
            }
        }
        for (int i = 0; i < (m + 2); i++) {
            if (matrix[n][i] && !used[n][i])
                dfs2(n, i);
        }
        for (int i = 0; i < (m + 2); i++) {
            if (matrix[1][i] && !used[1][i])
                dfs2(1, i);
        }
        for (int i = 0; i < (n + 2); i++) {
            if (matrix[i][1] && !used[i][1])
                dfs2(i, 1);
        }
        for (int i = 0; i < (n + 2); i++) {
            if (matrix[i][m] && !used[i][m])
                dfs2(i, m);
        }

        int curColor = 0;
        List<Pair> comps = new ArrayList<>();
        for (int i = 1; i < (n + 1); i++) {
            for (int j = 1; j < (m + 1); j++) {
                if (color[i][j] == -1 && matrix[i][j]) {
                    count = 0;
                    dfs(i, j, curColor++);
                    comps.add(new Pair(count, curColor - 1));
                }
            }
        }
        Collections.sort(comps, new Comparator<Pair>() {
            @Override
            public int compare(Pair o1, Pair o2) {
                if (o1.size < o2.size)
                    return -1;
                else if (o1.size > o2.size)
                    return 1;
                else
                    return 0;
            }
        });
        int res = 0;
        Set<Integer> colors = new HashSet<>();
        for (int i = 0; i < (curColor - k); i++) {
            res += comps.get(i).size;
            colors.add(comps.get(i).color);
        }
        for (int i = 1; i < (n + 1); i++) {
            for (int j = 1; j < (m + 1); j++) {
                if (colors.contains(color[i][j])) {
                    scrMatrix[i - 1][j - 1] = false;
                }
            }
        }
        out.println(res);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (scrMatrix[i][j]) {
                    out.print('.');
                } else {
                    out.print('*');
                }
            }
            out.print(System.lineSeparator());
        }
    }

    public void run() {
        try {
            br = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out);

            solve();

            out.close();
        } catch (IOException e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

