        visited1[x][y]=1;
        a[x][y]='*';
        if(x-1>=0 && a[x-1][y]=='.' && visited1[x-1][y]==0){
            dfs1(x-1,y);
        }
        if(x+1<=n-1 && a[x+1][y]=='.' && visited1[x+1][y]==0){
            dfs1(x+1,y);
        }
        if(y-1>=0 && a[x][y-1]=='.' && visited1[x][y-1]==0){
            dfs1(x,y-1);
        }
        if(y+1<=m-1 && a[x][y+1]=='.' && visited1[x][y+1]==0){
            dfs1(x,y+1);
        }
    }

    boolean dfs(int x,int y){
        visited[x][y]=1;
        count++;               // count current cell
        boolean b1=true,b2=true,b3=true,b4=true;
        if(x-1<0)b1=false;
        else{
            if(a[x-1][y]=='.' && visited[x-1][y]==0){
