        else{
            if(a[x+1][y]=='.' && visited[x+1][y]==0){
                b2=dfs(x+1,y);
            }
        }
        if(y-1<0)b3=false;
        else{
            if(a[x][y-1]=='.' && visited[x][y-1]==0){
                b3=dfs(x,y-1);
            }
        }
        if(y+1>m-1)b4=false;
        else{
            if(a[x][y+1]=='.' && visited[x][y+1]==0){
                b4=dfs(x,y+1);
            }
        }
