						if (posY < 0 || posY >= m) {
							continue;
						}
						if (board[posX][posY] == '.' && scc[posX][posY] == 0) {
							xs.add(posX);
							ys.add(posY);
						}
					}
				}

			}
		}

		HashSet<Integer> map = new HashSet<>();
		for (int i = 0; i < n; i++) {
			if (board[i][0] == '.') {
				map.add(scc[i][0]);
			}
			if (board[i][m - 1] == '.') {
				map.add(scc[i][m - 1]);
			}
		}

		for (int j = 0; j < m; j++) {
			if (board[0][j] == '.') {
				map.add(scc[0][j]);
			}
			if (board[n - 1][j] == '.') {
				map.add(scc[n - 1][j]);
			}
		}

		ArrayList<Pair> arr = new ArrayList<>();
		for (int i = 1; i < n * m + 1; i++) {
			if (map.contains(i)) {
				continue;
			}

			arr.add(new Pair(cntScc[i], i));
		}

		Collections.sort(arr);

		int num = arr.size();
		map.clear();
		for (int i = 0; i < num - k; i++) {
			map.add(arr.get(i).y);
		}

		int result = 0;
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (map.contains(scc[i][j])) {
					board[i][j] = '*';
					result++;
				}
			}
		}

		out.println(result);
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				out.print(board[i][j]);
			}
			if (i != n - 1) {
