import java.util.Stack;
import java.util.StringTokenizer;

public class Main {

    static class Pair implements Comparable<Pair> {
        public int x;
        public int y;

        public Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public int compareTo(Pair arg0) {
            if (Integer.compare(this.x, arg0.x) != 0) {
                return Integer.compare(this.x, arg0.x);
            }

            return Integer.compare(this.y, arg0.y);

        }

    }

    public static void main(String[] args) throws FileNotFoundException, UnsupportedEncodingException {

        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        solve(in, out);
        out.flush();
        out.close();
        System.exit(0);
    }

    private static void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        int k = in.nextInt();

        int[] moveX = new int[] { -1, 0, 1, 0 };
        int[] moveY = new int[] { 0, -1, 0, 1 };

        int cnt = 0;
        int[][] scc = new int[n][m];
        int[] cntScc = new int[n * m + 1];

        char[][] board = new char[n][m];
        for (int i = 0; i < n; i++) {
            board[i] = in.next().toCharArray();
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (scc[i][j] > 0 || board[i][j] == '*') {
                    continue;
                }

                Stack<Integer> xs = new Stack<>();
                Stack<Integer> ys = new Stack<>();
                xs.add(i);
                ys.add(j);
                ++cnt;

                while (!xs.isEmpty()) {
                    int x = xs.pop();
                    int y = ys.pop();
                    if (scc[x][y] > 0) {
                        continue;
                    }
                    scc[x][y] = cnt;
                    cntScc[cnt]++;

                    for (int a = 0; a < 4; a++) {
                        int posX = x + moveX[a];
                        int posY = y + moveY[a];
                        if (posX < 0 || posX >= n) {
                            continue;
                        }
                        if (posY < 0 || posY >= m) {
                            continue;
                        }
                        if (board[posX][posY] == '.' && scc[posX][posY] == 0) {
                            xs.add(posX);
                            ys.add(posY);
                        }
                    }
                }

            }
        }

        HashSet<Integer> map = new HashSet<>();
        for (int i = 0; i < n; i++) {
            if (board[i][0] == '.') {
                map.add(scc[i][0]);
            }
            if (board[i][m - 1] == '.') {
                map.add(scc[i][m - 1]);
            }
        }

        for (int j = 0; j < m; j++) {
            if (board[0][j] == '.') {
                map.add(scc[0][j]);
            }
            if (board[n - 1][j] == '.') {
                map.add(scc[n - 1][j]);
            }
        }

        ArrayList<Pair> arr = new ArrayList<>();
        for (int i = 1; i < n * m + 1; i++) {
            if (map.contains(i)) {
                continue;
            }

            arr.add(new Pair(cntScc[i], i));
        }

        Collections.sort(arr);

        int num = arr.size();
        map.clear();
        for (int i = 0; i < num - k; i++) {
            map.add(arr.get(i).y);
        }

        int result = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (map.contains(scc[i][j])) {
                    board[i][j] = '*';
                    result++;
                }
            }
        }

        out.println(result);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out.print(board[i][j]);
            }
            if (i != n - 1) {
                out.println();
            }
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            String str = "";
            try {
                str = reader.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }

            return str;
        }
    }

