import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;

public class VirtC {

	static int n, m, c;

	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		n = scan.nextInt();
		m = scan.nextInt();
		int k = scan.nextInt();
		char[][] grid = new char[n][m];
		for(int i = 0; i < n; i++) grid[i] = scan.next().toCharArray();
		for(int i = 0; i < n; i++){
			for(int j = 0; j < m; j++){
				if((i == 0 || j == 0 || i == n-1 || j == m-1) && grid[i][j] == '.') {
					dfs(i, j, grid, new boolean[n][m]);
				}
			}
		}
		ArrayList<Lake> a = new ArrayList<Lake>();
		boolean[][] v = new boolean[n][m];
		for(int i = 0; i < n; i++){
			for(int j = 0; j < m; j++){
				if(grid[i][j] == '.' && !v[i][j]){
					c = 0;
					DFS(i, j, grid, v);
					a.add(new Lake(i, j, c));

				}
			}
		}
		Collections.sort(a);

		int count = 0;
		while(a.size() > k){
			Lake l = a.remove(0);

			DeeEfEs(l.x, l.y, grid, new boolean[n][m]);
			count += l.s;
		}
		System.out.println(count);
		for(int i = 0; i < n; i++){
			for(int j = 0; j < m; j++){
				if(grid[i][j] == '#') System.out.print(".");
				else System.out.print(grid[i][j]);
			}
			System.out.println();
		}
	}

	static void DeeEfEs(int x, int y, char[][] grid, boolean[][] v){
		int[] d = {-1, 1, 0, 0};
		v[x][y] = true;
		grid[x][y] = '*';
		for(int i = 0; i < 4; i++){
			int dx = x+d[i], dy = y+d[3-i];
			if(inBounds(dx, dy) && !v[dx][dy]){
				if(grid[dx][dy] == '.') {
					DeeEfEs(dx, dy, grid, v);
				}
			}
		}
	}

	static void DFS(int x, int y, char[][] grid, boolean[][] v){
		int[] d = {-1, 1, 0, 0};
		v[x][y] = true;
		c++;
		for(int i = 0; i < 4; i++){
			int dx = x+d[i], dy = y+d[3-i];
			if(inBounds(dx, dy) && !v[dx][dy]) {
				if(grid[dx][dy] == '.') {
					DFS(dx, dy, grid, v);
				}
			}
		}
	}

	static void dfs(int x, int y, char[][] grid, boolean[][] v){
		int[] d = {-1, 1, 0, 0};
		v[x][y] = true;
		grid[x][y] = '#';
		for(int i = 0; i < 4; i++){
			int dx = x+d[i], dy = y+d[3-i];
			if(inBounds(dx, dy) && !v[dx][dy]) {
				if(grid[dx][dy] == '.') {
					dfs(dx, dy, grid, v);
				}
			}
		}
	}
	static boolean inBounds(int x, int y){return x >= 0 && x < n && y >= 0 && y < m;}

	static class Lake implements Comparable<Lake>{
		int x, y, s;
		public Lake(int a, int b, int c){
			x = a;
			y = b;
			s = c;
		}
		@Override
		public int compareTo(Lake o) {
			return this.s-o.s;
		}
	}
}

