                        addEdge(i * m + j, i * m + j + 1);
                    }
                    if (j - 1 >= 0 && s[i][j - 1] == '.') {
                        addEdge(i * m + j, i * m + j - 1);
                    }
                    if (i + 1 < n && s[i + 1][j] == '.') {
