		for (int i = 0; i < n; i++) {
			String str = in.nextLine();
			for (int j = 0; j < m; j++) {
				if (str.charAt(j) == '*') {
					b[i][j] = false;
				} else {
					b[i][j] = true;
				}
			}
		}
		in.close();
	}

	ArrayList<ArrayList<int[]>> getLakes(){
		boolean[][] b1 = new boolean[n][m];
		for(int i = 0; i<n; i++){
			for (int j = 0; j<m; j++){
				 b1[i][j] = b[i][j];
			}
		}
		ArrayList<ArrayList<int[]>> lakes = new ArrayList<>();
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				boolean hasBorder = false;
				LinkedList<int[]> ll = new LinkedList<>();
				if (b1[i][j]) {
					ArrayList<int[]> lake = new ArrayList<>();
					int[] arr = new int[2];
					arr[0] = i;
					arr[1] = j;
					lake.add(arr);
					ll.addLast(arr);

					if (i == 0 || i == n - 1 || j == 0 || j == m - 1)
						hasBorder = true;

					b1[i][j] = false;
					int i1, j1;
					while (!ll.isEmpty()) {
						arr = ll.removeFirst();
						i1 = arr[0];
						j1 = arr[1];
						if (i1 == 0 || i1 == n - 1 || j1 == 0 || j1 == m - 1)
							hasBorder = true;
						if (i1 != 0)
							if (b1[i1 - 1][j1] == true) {
								arr = new int[2];
								arr[0] = i1 - 1;
								arr[1] = j1;
								lake.add(arr);
								ll.addLast(arr);
								b1[i1 - 1][j1] = false;
							}
						if (i1 != n - 1)
							if (b1[i1 + 1][j1] == true) {
								arr = new int[2];
								arr[0] = i1 + 1;
								arr[1] = j1;
								lake.add(arr);
								ll.addLast(arr);
								b1[i1 + 1][j1] = false;
							}
						if (j1 != 0)
							if (b1[i1][j1 - 1] == true) {
								arr = new int[2];
								arr[0] = i1;
								arr[1] = j1 - 1;
								lake.add(arr);
								ll.addLast(arr);
								b1[i1][j1 - 1] = false;
							}
						if (j1 != m - 1)
							if (b1[i1][j1 + 1] == true) {
								arr = new int[2];
								arr[0] = i1;
								arr[1] = j1 + 1;
								lake.add(arr);
								ll.addLast(arr);
								b1[i1][j1 + 1] = false;
							}
					}
					if (!hasBorder)
						lakes.add(lake);
				}
			}
		}
		return lakes;
	}
	int fillLakes(){
		ArrayList<ArrayList<int[]>> lakes = getLakes();


		class Pair implements Comparable<Pair> {
			int i;
			int j;

			Pair(int i, int j) {
				this.i = i;
				this.j = j;
			}

			@Override
			public int compareTo(Pair o) {
				if (this.i > o.i)
					return 1;
				else if (this.i < o.i)
					return -1;
				else
					return 0;
			}
		}

		ArrayList<Pair> utilList = new ArrayList<>();
		for (int i = 0; i < lakes.size(); i++) {
			utilList.add(new Pair(lakes.get(i).size(), i));
		}
		Collections.sort(utilList);
		int count = lakes.size();
		int res = 0;
		for (int i = 0; i < count - k; i++) {
			ArrayList<int[]> lake = lakes.get(utilList.get(i).j);
			for (int[] arr : lake) {
				b[arr[0]][arr[1]] = false;
				res++;
			}
		}
		return res;
	}
	void out(){
		if (m <= 2 || n <= 2) {
			System.out.println(0);
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					System.out.print(b[i][j] ? '.' : '*');
				}
				System.out.println();
			}
		}else{
			System.out.println(fillLakes());
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					System.out.print(b[i][j] ? '.' : '*');
				}
				System.out.println();
			}
		}

	}
}

	public static void main(String[] args) {
		Field f = new Field();
		f.out();
	}
}

