        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken()); int m = Integer.parseInt(st.nextToken()); int k = Integer.parseInt(st.nextToken());
        grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            String line = st.nextToken();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        marked = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!marked[i][j] && grid[i][j] == '.') {
                    marked[i][j] = true;
                    isLake = true;
                    count = 0;
                    curCells = new ArrayList<>();
                    flood_fill(i, j);

                    if (isLake) {
                        lakeCells.add(curCells);
                        lakes.add(new int[] {count, lakes.size()});
                    }
                }
            }
        }

        java.util.Collections.sort(lakes, new java.util.Comparator<int[]>() {
            public int compare(int[] a, int[] b) {
                return Integer.compare(a[0], b[0]);
            }
        });
        int ans = 0;
        for (int i = 0; i < lakes.size() - k; i++) {
            ans += lakes.get(i)[0];
            for (int j = 0; j < lakeCells.get(lakes.get(i)[1]).size(); j++) {
                grid[lakeCells.get(lakes.get(i)[1]).get(j)[0]][lakeCells.get(lakes.get(i)[1]).get(j)[1]] = '*';
            }
        }
