            for (int j = 0; j < m; j++) {
                System.out.print(grid[i][j]);
            }
            System.out.println();
        }
    }

    public static void flood_fill(int r, int c) {
        if (r == 0 || c == 0 || r == grid.length - 1 || c == grid[0].length - 1) {
            isLake = false;
        }
        count++;
        curCells.add(new int[] {r, c});
        for (int i = 0; i < 4; i++) {
            if (r + di[i] >= 0 && r + di[i] < grid.length && c + dj[i] >= 0 && c + dj[i] < grid[0].length && grid[r + di[i]][c + dj[i]] == '.' && !marked[r + di[i]][c + dj[i]]) {
