    public static int[] dj = new int[] {0, 0, 1, -1};
    public static boolean isLake = true;
    public static ArrayList<int[]> lakes = new ArrayList<>();
    public static ArrayList<ArrayList<int[]>> lakeCells = new ArrayList<>();
    public static ArrayList<int[]> curCells = new ArrayList<>();
