        grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            String line = st.nextToken();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        marked = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!marked[i][j] && grid[i][j] == '.') {
                    marked[i][j] = true;
                    isLake = true; count = 0;
                    curCells = new ArrayList<>();
                    flood_fill(i, j);

                    if (isLake) {
                        lakeCells.add(curCells);
                        lakes.add(new int[] {count, lakes.size()});
                    }
                }
            }
        }

        // sort lakes by size (ascending)
        lakes.sort(new Comparator<int[]>() {
            @Override
            public int compare(int[] a, int[] b) {
                return Integer.compare(a[0], b[0]);
            }
        });

        // fill up the smallest lakes until exactly k lakes remain
        int ans = 0;
        for (int i = 0; i < lakes.size() - k; i++) {
            ans += lakes.get(i)[0];
            ArrayList<int[]> cells = lakeCells.get(lakes.get(i)[1]);
            for (int[] cell : cells) {
                grid[cell[0]][cell[1]] = '*';
            }
        }
        System.out.println(ans);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                System.out.print(grid[i][j]);
            }
            System.out.println();
        }
    }

    public static void flood_fill(int r, int c) {
        // check if current cell is on the border (any side)
        if (r == 0 || r == grid.length - 1 || c == 0 || c == grid[0].length - 1) {
            isLake = false;
