import java.awt.Point;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;
import java.util.Stack;



public class Main {

    static int dx[] = {0,0,1,-1};
    static int dy[] = {1,-1,0,0};
    private static int [][] path;
    private static char [][] input;
    private static int N;
    private static int M;
    private static boolean [][] visited;
    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        M = sc.nextInt();
        int K = sc.nextInt();
        input  = new char [N][M];
        for (int i = 0; i < N; i++){
            String line = sc.next();
            for (int j = 0; j < M; j++){
                input[i][j] = line.charAt(j);
            }
        }
        path = new int [N][M];
        for (int i = 0; i < N; i++){
            for (int j = 0; j < M; j++){
                path[i][j] = -1;
            }
        }
        for (int i = 0; i < N; i++){
            for (int j = 0; j < M; j++){
                if (isPointOnEdge(new Point(i,j)) == true && input[i][j] == '.'){
                    DFS(new Point(i,j));
                }
            }
        }
        int cur_lake = 0;
        ArrayList<ArrayList<Point>> dots = new ArrayList<>();
        ArrayList<Integer> length = new ArrayList<>();

        for (int i = 0; i < N; i++){
            for (int j = 0; j < M; j++){
                if (path[i][j] == -1 && input[i][j] == '.'){
                    ArrayList<Point> temp = DFS( new Point(i,j));
                    dots.add(temp);
                    length.add(temp.size());
                    cur_lake ++;
                }
            }
        }
        Collections.sort(length);
        int clear_lake = cur_lake - K;
        int min_num = 0;
        for (int i = 0; i < clear_lake; i++){
            min_num += length.get(i);

            for (int j = 0; j < dots.size(); j++){
                if (dots.get(j).size() == length.get(i)){
                    Point t = dots.get(j).get(0);
                    if (path[t.x][t.y] != 1){
                        for (int k = 0; k < dots.get(j).size(); k++){
                            Point p = dots.get(j).get(k);
                            path[p.x][p.y] = 1;
                        }
                        break;
                    }
                }
            }
        }
        System.out.println(min_num);

        for (int i = 0; i < N; i++){
            for (int j = 0; j < M; j++){
                if (path[i][j] == -1 || path[i][j] == 0) 
                    System.out.print(input[i][j]);
                if (path[i][j] == 1) System.out.print("*");
            }
            System.out.println();
        }

    }

    public static boolean isPointOnEdge(Point s){
        return(s.x == 0 || s.y == 0 || s.x == N-1 || s.y == M-1);
    }
    public static ArrayList<Point> DFS (Point s){
        Stack<Point> stack = new Stack <>();
        ArrayList<Point> dots_arr = new ArrayList<>();
        stack.push(s);
        dots_arr.add(s);
        path [s.x][s.y] = 0;
        while (!stack.isEmpty()){
            Point u = stack.peek();
            stack.pop();
            for (int i = 0; i < dx.length; i++){
                int x = u.x + dx[i];
                int y = u.y + dy[i];
                if (x >= 0 && x < N && y >= 0 && y < M){
                    if (path[x][y] == -1 && input[x][y] == '.'){
                        stack.add(new Point(x,y));
                        dots_arr.add(new Point(x,y));
                        path[x][y] = 0;
                    }
                }
            }
        }
        return dots_arr;
    }
}

