import java.util.Scanner;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Set;
import java.util.HashSet;
import java.util.Comparator;
import java.util.Collections;

public class BigO2302 {

	private static Queue<int[]> moving = new LinkedList<>(); 
	private static int[] dx = {0, 0, -1, 1};
	private static int[] dy = {-1, 1, 0, 0};
	private static int N;
	private static int M;
	private static int K;
	private static char[][] map;
	private static Set<int[]> mark;
	private static boolean[][] check;
	private static LinkedList<Set<int[]>> lakes = new LinkedList<Set<int[]>>();

	public static void move() {
		boolean checking = false;
		while (!moving.isEmpty()) {
			int[] temp = moving.remove();
			for (int i = 0; i < dx.length; i++) {
				int x = temp[0] + dx[i];
				int y = temp[1] + dy[i];
				int[] tempA = {x, y};
				if (((x >= 0) && (x <= M - 1) && (y >= 0) && (y <= N - 1)) && (map[x][y] == '.') && (check[x][y] == false)) {
					if ((x == 0) || (y == 0) || (x == M - 1) || (y == N - 1))
						checking = true;
					mark.add(tempA);
					moving.add(tempA);
					check[x][y] = true;
				}
			}
		}
		if (checking) {
			mark.clear();
			return;
		}
		Set<int[]> tempMark = new HashSet<int[]>(mark);
		lakes.add(tempMark);
		mark.clear();
	}

	public static void main(String[] args) {
		Scanner userInput = new Scanner(System.in);
		N = userInput.nextInt();
		M = userInput.nextInt();
		K = userInput.nextInt();
		map = new char[M][N];
		check = new boolean[M][N];
		mark = new HashSet<int[]>();
		for (int i = 0; i < N; i++) {
			String t = userInput.next();
			for (int j = 0; j < M; j++) 
				map[j][i] = t.charAt(j);
		}
		for (int y = 1; y < N - 1; y++)
			for (int x = 1; x < M - 1; x++) {
