            p = q.poll();
            int x = p.u;
            int y = p.v;
            c[x][y] = '*';
            for (int m = -1; m <= 1; m++) {
                for (int l = -1; l <= 1; l++) {
                    if (Math.abs(m) != Math.abs(l)) {
                        if (c[x + m][y + l] == '.' && !visited[x + m][y + l]) {
                            q.add(new Pair(x + m, y + l));
