        while (!q.isEmpty()) {
            Pair p = q.poll();
            count++;
            int x = p.u;
            int y = p.v;
            for (int m = -1; m <= 1; m++) {
                for (int l = -1; l <= 1; l++) {
                    if(x+m>=0 && x+m<=a-1 && y+l>=0 && y+l<=b-1 && Math.abs(m)!=Math.abs(l)){
                        if ((x + m == 0 || y + l == 0 || x + m == a - 1 || y + l == b - 1) && c[x + m][y + l] == '.') {
