import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.StringTokenizer;

public class D375 {
    public static void main(String[] args) {
        MyScanner scan = new MyScanner();
        PrintWriter out = new PrintWriter(System.out);

        int R = scan.nextInt(), C = scan.nextInt(), K = scan.nextInt();

        char[][] mat = new char[R][C];
        for (int i = 0; i < R; i++) {
            String line = scan.next();
            for (int j = 0; j < C; j++) {
                mat[i][j] = line.charAt(j);
            }
        }
        int[] dr = {-1, 1, 0, 0}, dc = {0, 0, -1, 1};
        int lake = 1;
        int countValid = 0;
        boolean[] valid = new boolean[R * C + 1];
        Arrays.fill(valid, true);
        int[] size = new int[R * C + 1];
        int[][] map = new int[R][C];
        boolean[][] seen = new boolean[R][C];
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                if (seen[i][j]) continue;
                if (mat[i][j] == '*') continue;
                ArrayDeque<Integer> q = new ArrayDeque<>();
                q.add(i); q.add(j);
                size[lake]++;
                seen[i][j] = true;
                map[i][j] = lake;
                while (!q.isEmpty()) {
                    int r = q.poll(), c = q.poll();
                    for (int k = 0; k < 4; k++) {
                        int tr = r + dr[k], tc = c + dc[k];
                        if (tr < 0 || tc < 0 || tr >= R || tc >= C) {
                            valid[lake] = false;
                            continue;
                        }
                        if (!seen[tr][tc] && mat[tr][tc] == '.') {
                            seen[tr][tc] = true;
                            q.add(tr);
                            q.add(tc);
                            size[lake]++;
                            map[tr][tc] = lake;
                        }
                    }
                }

                if (valid[lake]) {
                    countValid++;
                }
                lake++;
            }
        }

        int filled = 0;
        if (countValid > K) {
            ArrayList<Integer> list = new ArrayList<>();
            for (int i = 1; i < lake; i++) {
                if (valid[i]) list.add(i);
            }
            Collections.sort(list, new Comparator<Integer>() {
                public int compare(Integer a, Integer b) {
                    return Integer.compare(size[a], size[b]);
                }
            });
            for (int i = 0; i < countValid - K; i++) {
                for (int r = 0; r < R; r++) {
                    for (int c = 0; c < C; c++) {
                        if (map[r][c] == list.get(i)) {
                            filled++;
                            mat[r][c] = '*';
                        }
                    }
                }
            }
        }

        out.println(filled);
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                out.print(mat[i][j]);
            }
            out.println();
        }
        out.close();
    }

    private static class MyScanner {
        BufferedReader br;
        StringTokenizer st;
        public MyScanner() { br = new BufferedReader(new InputStreamReader(System.in)); }
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try { st = new StringTokenizer(br.readLine()); }
                catch (IOException e) { e.printStackTrace(); }
            }
            return st.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }
    }
}

