import java.util.ArrayList;
import java.util.Map;
import java.util.Scanner;
import java.util.Stack;
import java.util.TreeMap;

public class LakesInBerlandCodeforces {
	private static Scanner in;

	public static void main(String[] args) {

		in = new Scanner(System.in);
		int n = in.nextInt();
		int m = in.nextInt();
		int lakes = in.nextInt();

		in.nextLine();		
		char[][] map = new char[n][m];

		for(int i = 0; i < n; i++)
		{
			String s = in.nextLine();
			map[i] = s.toCharArray();
		}

		char[][] backupMap = new char[n][m];

		for(int j = 0; j < n; j++)
		{
			for(int k = 0; k < m; k++)
			{
				backupMap[j][k] = map[j][k];
			}
		}

		Map<Integer, ArrayList<ArrayList<Point>>> hs = new TreeMap<Integer, ArrayList<ArrayList<Point>>>();
		int totalLakes = 0;

		for(int j = 0; (n > 1) ? j < n - 1 : j < n; j++)
		{
			for(int k = 0; k < m; k++)
			{
				if(isValidPoint(n, m, j, k) && map[j][k] == '.')
				{
					ArrayList<Point> result = DFS(n, m, map, lakes, new Point ( k,j));

					if(result != null)
					{											
						int tempSize = result.size();
						totalLakes++;

						if (hs.containsKey(tempSize))
						{
							hs.get(tempSize).add(result);
						}
						else
						{
							ArrayList<ArrayList<Point>> aal = new ArrayList<ArrayList<Point>>();
							aal.add(result);
							hs.put(tempSize, aal);
						}		
					}
				}
			}
		}		

		int numOfCells = 0;

		while(totalLakes > lakes)
		{
			int diff = totalLakes - lakes;

			for(int l = 0; l < diff; l++)
			{
				if(totalLakes == lakes)
				{
					break;
				}

				int tempValue = (int)hs.keySet().toArray()[l];

				for(int q = 0; q < hs.get(tempValue).size(); q++)
				{
					numOfCells = numOfCells + tempValue;
					totalLakes--;
					ArrayList<Point> al = hs.get(tempValue).get(q);

					for(int z = 0; z < al.size(); z++)
					{
						Point pp = al.get(z);
						backupMap[pp.y][pp.x] = '*';   // corrected index order
					}

					if(totalLakes == lakes)
					{
						break;
					}
				}
			}
		}		

		System.out.println(numOfCells);

		for(int j = 0; j < n; j++)
		{
			for(int k = 0; k < m; k++)
			{
				System.out.print(backupMap[j][k]);
			}

			System.out.println();
		}
	}

	private static boolean isValidPoint(int n, int m, int j, int k)
	{
		return (j >= 0 && j < n) && (k >= 0 && k < m);
	}

	private static ArrayList<Point> DFS(int n, int m, char[][] map, int lakes, Point p)
	{
		Stack<Point> stack = new Stack<Point>();
		stack.add(p);				
		int[] X = {-1, 0, 1, 0};
		int[] Y = {0, 1, 0, -1};

		ArrayList<Point> result = new ArrayList<Point>();
		result.add(p);
		map[p.y][p.x] = '*';		
		boolean connectedToOcean = false;

		if(isConnectedToOcean(p.y, p.x, n, m))
		{
			connectedToOcean = true;
		}

		while(!stack.isEmpty())
		{
			Point current = stack.pop();

			for(int i = 0; i < 4; i++)
			{
				int xx = current.x + X[i];
				int yy = current.y + Y[i];

				if(isValidPoint(n, m, yy, xx) && map[yy][xx] == '.')
				{
					if(isConnectedToOcean(yy, xx, n, m))
					{
						connectedToOcean = true;
					}

					Point temp = new Point(xx, yy);
					stack.add(temp);
					map[yy][xx] = '*';
					result.add(temp);
				}
			}
		}

		if(connectedToOcean)
		{
			return null;
		}

		return result;
	}

	private static boolean isConnectedToOcean(int xx, int yy, int n, int m)
	{
		return (xx == 0 || xx == n - 1 || yy == 0 || yy == m - 1);
	}

	private static class Point
	{
		int x;
		int y;

		Point(int x, int y)
		{
			this.x = x;
			this.y = y;
		}
	}
}

