import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.List;
import java.util.Map;
import java.util.Collection;
import java.util.Scanner;
import java.util.HashMap;
import java.util.Collections;
import java.util.ArrayList;


public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, Scanner in, PrintWriter out) {

            int n = in.nextInt();
            int m = in.nextInt();
            int k = in.nextInt();

            in.nextLine();

            int[][] map = new int[n][m];

            for (int i = 0; i < n; i++) {
                String line = in.nextLine();
                for (int j = 0; j < m; j++) {
                    map[i][j] = line.charAt(j) == '.' ? -1 : 0;
                }
            }

            int cnt = 1;

            for (int i = 0; i < n; i++) {
                if (map[i][0] == -1) {
                    fill(map, i, 0, -2, -1);
                }
                if (map[i][m - 1] == -1) {
                    fill(map, i, m - 1, -2, -1);
                }

            }

            for (int i = 0; i < m; i++) {
                if (map[0][i] == -1) {
                    fill(map, 0, i, -2, -1);
                    cnt++;
                }
                if (map[n - 1][i] == -1) {
                    fill(map, n - 1, i, -2, -1);
                    cnt++;
                }

            }

            Map<Integer, Lake> lakes = new HashMap<>();

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (map[i][j] == -1) {
                        fill(map, i, j, (char) cnt, -1);
                        cnt++;
                    }
                    if (map[i][j] > 0) {
                        if (lakes.containsKey(map[i][j])) {
                            lakes.get(map[i][j]).size++;
                        } else {
                            lakes.put(map[i][j], new Lake(i, j, 1, cnt - 1));
                        }
                    }
                }
            }
            int cells = 0;
            if (lakes.values().size() - k > 0) {

                List<Lake> sortedLake = new ArrayList<>(lakes.values());
                Collections.sort(sortedLake);
                for (int i = 0; i < sortedLake.size() - k; i++) {
                    Lake lake = sortedLake.get(i);
                    fill(map, lake.i, lake.j, 0, lake.count);
                    cells += lake.size;
                }
            }
            out.write(Integer.toString(cells));
            out.write("\n");
            printMap(map, out);
        }

        void fill(int[][] map, int i, int j, int c, int t) {
            if (map[i][j] == t) {
                map[i][j] = c;
                if (i > 0) {
                    fill(map, i - 1, j, c, t);
                }
                if (i < map.length - 1) {
                    fill(map, i + 1, j, c, t);
                }
                if (j > 0) {
                    fill(map, i, j - 1, c, t);   // fixed: correct parameter order
                }
                if (j < map[i].length - 1) {
                    fill(map, i, j + 1, c, t);
                }
            }
        }

        void printMap(int[][] map, PrintWriter out) {
            for (int i = 0; i < map.length; i++) {
                for (int j = 0; j < map[map.length - 1].length; j++) {
                    out.write(map[i][j] != 0 ? '.' : '*');
                }
                out.write("\n");
            }
        }

        class Lake implements Comparable<Lake> {
            public int size;
            public int i;
            public int j;
            public int count;

            public Lake(int i, int j, int size, int cnt) {
                this.size = size;
                this.i = i;
                this.j = j;
                this.count = cnt;
            }


            public int compareTo(Lake o) {
                return Integer.compare(size, o.size);
            }

        }

    }
}

