import java.util.*;
import java.math.*;
import java.io.*;
import java.text.*;

public class A {
    static class Node implements Comparable<Node>{
        int id;
        int x;

        public Node(int id,int x){
           this.id=id;
           this.x=x;
        }
        public int compareTo(Node c){
            int i=Long.compare(this.x,c.x);
          return i;

        }
        @Override
        public boolean equals(Object o){
            if(o instanceof Node){
                Node c = (Node)o;
                return true;
            }
            return false;
        }
    }

    public static PrintWriter pw = new PrintWriter(System.out);

    public static void solve() throws IOException {

        FastReader sc = new FastReader();
        int n=sc.I(); int m=sc.I(); int k=sc.I();
        graph=new char[n][m];
        for(int i=0;i<n;i++){
            graph[i]=sc.next().toCharArray();
        }
        CC=new int[n][m];
        vis=new boolean[n][m];
        total=new int[10000];
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                if(graph[i][j]=='.' && !vis[i][j]){
                    cc++;
                    dfs(i,j,n,m);
                }
            }
        }
        PriorityQueue<Node> q=new PriorityQueue<>();
        for(int i=1;i<=cc;i++) q.offer(new Node(i,total[i]));
        int ans=0;                                   // <-- fixed: initialize to 0 instead of (0-1)
        int cnt=0;

        while(cnt<cc-onBorder.size()-k){
            Node p=q.poll();
            if(onBorder.contains(p.id)) continue;
            for(int i=0;i<n;i++){
                for(int j=0;j<m;j++) {
                    if (graph[i][j] == '.' && CC[i][j] == p.id) {
                        graph[i][j] = '*';
                        ans++;
                    }
                }
            }

            cnt++;
        }
        pw.println(ans);
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++) pw.print(graph[i][j]);
            pw.println("");
        }
        pw.close();


    }
    static int cc=0;
    static int CC[][];
    static int dx[]={-1,0,1,0};
    static int dy[]={0,1,0,-1};
    static char graph[][];
    static boolean vis[][];
    static int total[];
    static boolean isValid(int x,int y,int n,int m){
        return x>=0 && x<n && y>=0 && y<m && !vis[x][y] && graph[x][y]=='.';
    }
    static HashSet<Integer> onBorder=new HashSet<>();
    static void dfs(int i,int j,int n,int m){
        vis[i][j]=true;
        CC[i][j]=cc;
        total[cc]++;
        if(i==0 || i==n-1 || j==0 || j==m-1) onBorder.add(cc);
        for(int ii=0;ii<4;ii++){
            if(isValid(i+dx[ii],j+dy[ii],n,m)){
                dfs(i+dx[ii],j+dy[ii],n,m);
            }
        }
