    static class TaskD {
        int[][] lakeSize;
        boolean[][] isWater;
        int ze;
        int sp;
        String[] s;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            ze = in.nextInt();
            sp = in.nextInt();
            int goal = in.nextInt();
            s = new String[ze];
            for (int i = 0; i < ze; i++) {
                s[i] = in.next();
            }

            isWater = new boolean[ze][sp];
            for (int i = 0; i < ze; i++) {
                for (int j = 0; j < sp; j++) {
                    if (s[i].charAt(j) == '.') isWater[i][j] = true;
                }
            }

            lakeSize = new int[ze][sp];
            List<Lake> lakeList = new ArrayList<Lake>();

            for (int i = 0; i < ze; i++) {
                for (int j = 0; j < sp; j++) {
                    if ((i == 0) || (i == ze - 1) || (j == 0) || (j == sp - 1) || (!isWater[i][j])) lakeSize[i][j] = -1;
                    else {
                        if (lakeSize[i][j] == 0) {
                            lakeSize[i][j] = getLakeSize(i, j, new boolean[ze][sp]);
                            fillLakeSize(i, j, lakeSize[i][j], new boolean[ze][sp]);



                            if (lakeSize[i][j] > 0) lakeList.add(new Lake(i, j, lakeSize[i][j]));

                        }
                    }

                }

            }





            Collections.sort(lakeList, new Comparator<Lake>() {

                public int compare(Lake a, Lake b) {
                    return a.size - b.size;
                }
            });

            int result = 0;
            for (int i = 0; i < lakeList.size() - goal; i++) {
                result += lakeList.get(i).size;
                fillLake(lakeList.get(i));
            }

            out.println(result);
            for (int i = 0; i < ze; i++) {
                out.println(s[i]);
            }
        }

        void fillLake(Lake lake) {
            fillLakeRec(lake.ze, lake.sp, new boolean[ze][sp]);
        }

        void fillLakeRec(int i, int j, boolean[][] visited) {
            if (visited[i][j]) return;
            visited[i][j] = true;
            if (lakeSize[i][j] > 0) {

                StringBuilder sb = new StringBuilder(s[i]);
                sb.setCharAt(j, '*');
                s[i] = sb.toString();

                if (!visited[i + 1][j]) fillLakeRec(i + 1, j, visited);
                if (!visited[i - 1][j]) fillLakeRec(i - 1, j, visited);
                if (!visited[i][j + 1]) fillLakeRec(i, j + 1, visited);
                if (!visited[i][j - 1]) fillLakeRec(i, j - 1, visited);
            }
        }

        void fillLakeSize(int i, int j, int z, boolean[][] visited) {
            if (visited[i][j]) return;
            visited[i][j] = true;
            lakeSize[i][j] = z;
            if ((i + 1 < ze) && (isWater[i + 1][j]) && (!visited[i + 1][j])) fillLakeSize(i + 1, j, z, visited);
            if ((i > 0) && (isWater[i - 1][j]) && (!visited[i - 1][j])) fillLakeSize(i - 1, j, z, visited);
            if ((j + 1 < sp) && (isWater[i][j + 1]) && (!visited[i][j + 1])) fillLakeSize(i, j + 1, z, visited);
            if ((j > 0) && (isWater[i][j - 1]) && (!visited[i][j - 1])) fillLakeSize(i, j - 1, z, visited);
        }

        int getLakeSize(int i, int j, boolean[][] visited) {
            if (visited[i][j]) return 0;
            visited[i][j] = true;
            if (!isWater[i][j]) return 0;
            if ((i == 0) || (i == ze - 1) || (j == 0) || (j == sp - 1)) return -1;
            int result = 1;

            int up = 0;
            if (!visited[i - 1][j]) up = getLakeSize(i - 1, j, visited);
            if (up == -1) return -1;
            result += up;

            up = 0;
            if (!visited[i + 1][j]) up = getLakeSize(i + 1, j, visited);
            if (up == -1) return -1;
            result += up;

            up = 0;
            if (!visited[i][j + 1]) up = getLakeSize(i, j + 1, visited);
            if (up == -1) return -1;
            result += up;

            up = 0;
            if (!visited[i][j - 1]) up = getLakeSize(i, j - 1, visited);
            if (up == -1) return -1;
            result += up;

            return result;
        }

        class Lake {
            int ze;
            int sp;
            int size;

            public Lake(int i, int j, int s) {
                ze = i;
                sp = j;
                size = s;
            }

        }

    }

    static class InputReader {
        private static BufferedReader in;
        private static StringTokenizer tok;

        public InputReader(InputStream in) {
            this.in = new BufferedReader(new InputStreamReader(in));
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            try {
                while (tok == null || !tok.hasMoreTokens()) {
                    tok = new StringTokenizer(in.readLine());
                }
            } catch (IOException ex) {
                System.err.println("An IOException was caught :" + ex.getMessage());
            }
            return tok.nextToken();
        }

    }
