class TaskD {

    public class UnionFind {

        private int[] _parent;
        private int[] _rank;


        public int find(int i) {

            int p = _parent[i];
            if (i == p) {
                return i;
            }
            return _parent[i] = find(p);

        }


        public void union(int i, int j) {

            int root1 = find(i);
            int root2 = find(j);

            if (root2 == root1) return;

            if (_rank[root1] > _rank[root2]) {
                _parent[root2] = root1;
            } else if (_rank[root2] > _rank[root1]) {
                _parent[root1] = root2;
            } else {
                _parent[root2] = root1;
                _rank[root1]++;
            }
        }


        public UnionFind(int max) {

            _parent = new int[max];
            _rank = new int[max];

            for (int i = 0; i < max; i++) {
                _parent[i] = i;
            }
        }

    }


    public void solve(int testNumber, Scanner in, PrintWriter out) {

        int n = in.nextInt();
        int m = in.nextInt();
        int k = in.nextInt();
        in.nextLine();

        boolean[][] map = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            String s = in.nextLine();
            for (int j = 0; j < m; j++) {
                map[i][j] = (s.charAt(j) == '.');
            }

        }

        UnionFind uf = new UnionFind(n*m+1);



        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (map[i][j]) {
                    if (i+1 < n && map[i+1][j]) uf.union(i*m+j,(i+1)*m+j);
                    if (j+1 < m && map[i][j+1]) uf.union(i*m+j,(i)*m+(j+1));
                }
            }
        }

        for (int i = 0; i < n; i++) {
            if (map[i][0]) uf.union(i*m+0, m*n);
            if (map[i][m-1]) uf.union(i*m+(m-1), m*n);
        }
        for (int j = 0; j < m; j++) {
            if (map[0][j]) uf.union(0*m+j, m*n);
            if (map[n-1][j]) uf.union((n-1)*m+j, m*n);
        }



        int[] lakes = new int[n*m+2];


        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                lakes[uf.find(i*m+j)]++;
            }
        }
        lakes[uf.find(m*n)] = 0;


        HashMap<Integer, Integer> hm = new HashMap<Integer,Integer>();

        int numLakes = 0;
        int sumLand = 0;
        for (int i = 0; i < lakes.length; i++) {
            sumLand += lakes[i];
            if (lakes[i] > 0) {
                numLakes++;
                hm.put(i,lakes[i]);
            }
        }

        List<Map.Entry<Integer, Integer>> l = new ArrayList<Map.Entry<Integer, Integer>>(hm.entrySet());

        Collections.sort(l, new Comparator<Map.Entry<?, Integer>>() {
            @Override
            public int compare(Map.Entry<?, Integer> e1, Map.Entry<?, Integer> e2) {
                return e2.getValue().compareTo(e1.getValue());
            }
        });

        int Fills = 0;

        for (int o = 0; o < l.size()-k; o++) {
            int ent = l.get(l.size()-1-o).getKey();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (uf.find(i*m+j) == ent) {
                        map[i][j] = false;
                        Fills++;
                    }
                }
            }

        }

        out.println(String.valueOf(Fills));
        for (int i = 0; i < n; i++) {
            String s = "";
            for (int j = 0; j < m; j++) {
                if (map[i][j]) s = s+".";
                else s = s+"*";
            }
            out.println(s);
        }
    }

}

