            uf.union(0*m+j,m*n);
            uf.union((n-1)*m+j,m*n);
        }

        int[] lakes = new int[n*m+2];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                lakes[uf.find(i*m+j)]++;
            }
        }
        lakes[uf.find(m*n)] = 0;

        HashMap<Integer, Integer> hm = new HashMap<Integer,Integer>();

        int numLakes = 0;
        int sumLand = 0;
        for (int i = 0; i < lakes.length; i++) {
            sumLand += lakes[i];
            if (lakes[i] > 0) {
                numLakes++;
                hm.put(i,lakes[i]);
            }
        }

        List<Map.Entry<Integer, Integer>> l = new ArrayList<Map.Entry<Integer, Integer>>(hm.entrySet());

        Collections.sort(l, new Comparator<Map.Entry<?, Integer>>() {
            @Override
            public int compare(Map.Entry<?, Integer> e1, Map.Entry<?, Integer> e2) {
                return e2.getValue().compareTo(e1.getValue());
            }
        });

        int Fills = 0;
        for (int o = 0; o < l.size()-k; o++) {
            int ent = l.get(l.size()-1-o).getKey();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (uf.find(i*m+j) == ent) {
                        map[i][j] = false;
                        Fills++;
                    }
                }
            }
        }

        out.println(String.valueOf(Fills));
        for (int i = 0; i < n; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < m; j++) {
                if (map[i][j]) {
                    sb.append('.');
                } else {
                    sb.append('*');
                }
            }
            out.println(sb.toString());
        }
    }

}

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.stream.*;

@SuppressWarnings("unchecked")
public class P723D {

  final static int X = 0, Y = 1, S = 2;
  final static int [][] DXY = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

  int n, m, k;

  int [] fill(char [][] f, int [] xy) {
    int [] ans = new int [] {xy[X], xy[Y], 0};
    Deque<int []> w = new ArrayDeque();
    w.push(xy);
    f[xy[Y]][xy[X]] = '*';
    while (w.size() > 0) {
      xy = w.pop();
      if (ans != null) {
        ans[S]++;
      }
      for (int [] dxy : DXY) {
        int nx = xy[X] + dxy[X], ny = xy[Y] + dxy[Y];
        if ((nx < 0) || (ny < 0) || (nx >= m) || (ny >= n)) {
          ans = null;
        } else if (f[ny][nx] == '.') {
          f[ny][nx] = '*';
          w.push(new int [] {nx, ny});
        }
      }
    }
    return ans;
  }

  public void run() throws Exception {
    n = nextInt();
    m = nextInt();
    k = nextInt();
    char [][] f = new char [n][];
    char [][] l = new char [n][];
    for (int i = 0; i < n; i++) {
      f[i] = next().toCharArray();
      l[i] = Arrays.copyOf(f[i], m);
    }

    TreeSet<int []> lakes = new TreeSet(new Comparator<int []>() {
      @Override
      public int compare(int [] a, int [] b) {
        return ((a[S] <= b[S]) ? -1 : 1);
      }
    });

    for (int y = 0; y < n; y++) {
      for (int x = 0; x < m; x++) {
        if (f[y][x] == '.') {
          int [] cl = fill(f, new int [] {x, y});
          if (cl != null) {
            lakes.add(cl);
          }
        }
      }
    }

    int s = 0;
    while (lakes.size() > k) {
      s += fill(l, lakes.pollFirst())[S];
    }

    println(s);
    Arrays.stream(l).forEach(sl -> println(new String(sl)));
  }

  public static void main(String... args) throws Exception {
    br = new BufferedReader(new InputStreamReader(System.in));
    pw = new PrintWriter(new BufferedOutputStream(System.out));
    new P723D().run();
    br.close();
    pw.close();
    System.err.println("\n[Time : " + (System.currentTimeMillis() - startTime) + " ms]");
  }

  static long startTime = System.currentTimeMillis();
  static BufferedReader br;
  static PrintWriter pw;
  StringTokenizer stok;

  String nextToken() throws IOException {
    while (stok == null || !stok.hasMoreTokens()) {
      String s = br.readLine();
      if (s == null) { return null; }
      stok = new StringTokenizer(s);
    }
    return stok.nextToken();
  }

  void print(byte b) { print("" + b); }
  void print(int i) { print("" + i); }
  void print(long l) { print("" + l); }
  void print(double d) { print("" + d); }
  void print(char c) { print("" + c); }
  void print(Object o) {
    if (o instanceof int[]) { print(Arrays.toString((int [])o));
    } else if (o instanceof long[]) { print(Arrays.toString((long [])o));
    } else if (o instanceof char[]) { print(Arrays.toString((char [])o));
    } else if (o instanceof byte[]) { print(Arrays.toString((byte [])o));
    } else if (o instanceof short[]) { print(Arrays.toString((short [])o));
    } else if (o instanceof boolean[]) { print(Arrays.toString((boolean [])o));
    } else if (o instanceof float[]) { print(Arrays.toString((float [])o));
    } else if (o instanceof double[]) { print(Arrays.toString((double [])o));
