public class berland {

  static int n;
  static int m;
  static int k;
  static int numberOfLakes;

  static Character[][] map;
  static TreeMap<Integer, ArrayList<Point>> toRemove;
  static boolean[][] visited;

  static int dx[] = {0, 0, 1, -1};
  static int dy[] = {1, -1, 0, 0};

  static int getLakeSize(Point from) {
    Boolean touchedOcean = false;
    if (from.x == 1 || from.x == n || from.y == 1 || from.y == m)
      touchedOcean = true;
    visited[from.x][from.y] = true;
    int result = 1;
    Queue<Point> q = new LinkedList<Point>();
    q.add(from);
    int x, y;
    Point u;
    while (!q.isEmpty()) {
      u = q.remove();
      for (int i = 0; i < 4; i++) {
        x = u.x + dx[i];
        y = u.y + dy[i];
        if ((x == 1 || x == n || y == 1 || y == m) && (x >= 0 && x <= n && y >= 0 && y <= m) && map[x][y] == '.')
          touchedOcean = true;
        if (x >= 0 && x <= n && y >= 0 && y <= m) {
          if (visited[x][y] == false && map[x][y] == '.' ) {
            visited[x][y] = true;
            result++;
            q.add(new Point(x, y));
          }
        }
      }
    }
    if (!touchedOcean)
      return result;
    else
      return 0;
  }

  static int lakeToLand(Point from) {
    map[from.x][from.y] = '*';
    int result = 1;
    Queue<Point> q = new LinkedList<Point>();
    q.add(from);
    int x, y;
    Point u;
    visited[from.x][from.y] = true;
    while (!q.isEmpty()) {
      u = q.remove();
      for (int i = 0; i < 4; i++) {
        x = u.x + dx[i];
        y = u.y + dy[i];
        if (x >= 0 && x <= n && y >= 0 && y <= m) {
          if (visited[x][y] == false && map[x][y] == '.' ) {
            visited[x][y] = true;
            map[x][y] = '*';
            result++;
            q.add(new Point(x, y));
          }
        }
      }
    }
    return result;
  }

  public static void main(String[] args) {

      Scanner sc = new Scanner(System.in);

      n = sc.nextInt();
      m = sc.nextInt();
      k = sc.nextInt();


      map = new Character[n + 1][m + 1];
      for (int i = 0; i <= n; i++)
        map[i][0] = '*';
      for (int i = 0; i <= m; i++)
        map[0][i] = '*';

      for (int i = 0; i < n; i++) {
        String temp = sc.next();
        for (int j = 0; j < temp.length(); j++)
          map[i + 1][j + 1] = temp.charAt(j);
      }


      visited = new boolean[n + 1][m + 1];


      numberOfLakes = 0;


      toRemove = new TreeMap<Integer, ArrayList<Point>>();
      for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
          if (map[i][j] == '.' && !visited[i][j]) {
            int temp_lakeSize = getLakeSize(new Point(i, j));
            if (temp_lakeSize > 0) {
              numberOfLakes++;
              if (toRemove.containsKey(temp_lakeSize)) {
                toRemove.get(temp_lakeSize).add(new Point(i, j));
              }
              else {
                toRemove.put(temp_lakeSize, new ArrayList<Point>());
                toRemove.get(temp_lakeSize).add(new Point(i, j));
              }
            }
          }
        }
      }


      Queue<Point> points_to_remove = new LinkedList<Point>();
      while (points_to_remove.size() < numberOfLakes - k) {
        ArrayList<Point> temp_list = toRemove.get(toRemove.firstKey());
        for (int i = 0; i < temp_list.size(); i++)
          points_to_remove.add(temp_list.get(i));
        toRemove.remove(toRemove.firstKey());
      }


      visited = new boolean[n + 1][m + 1];
      int final_output = 0;
      while (numberOfLakes > k) {
        final_output += lakeToLand(points_to_remove.remove());
        numberOfLakes--;
      }


      System.out.println(final_output);
      for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++)
          System.out.print(map[i][j]);
        System.out.println();
      }


      sc.close();

  }

}

