public class Codeforcecontest {

	char arr[][];
	int n,m;
	public Codeforcecontest(int n,int m)
	{
		arr = new char[n][m];
		this.n = n;this.m = m;
	}

	public static void main(String[] args) throws NumberFormatException, IOException {
		Scanner s = new Scanner(System.in);
		int n,m,k;
		n = s.nextInt();
		m = s.nextInt();
		k = s.nextInt();
		Codeforcecontest cf = new Codeforcecontest(n, m);
		for(int i=0;i<n;i++){
			String str = s.next();
			for(int j=0;j<m;j++)
				cf.arr[i][j] = str.charAt(j);
		}

		cf.ans(k);
	}
	private void ans(int k) {

		ArrayList<ArrayList<Integer>>ar = new ArrayList<>();
		HashMap<Integer, Integer>seen = new HashMap<>();
		int visited[][] = new int[n][m];

		for(int i=1;i<n-1;i++)
		{
			for(int j=1;j<m-1;j++)
			{
				if(arr[i][j]=='.' && visited[i][j]==0)
				{
					ArrayList<Integer>ax = new ArrayList<>();
					boolean var= get(visited,i,j,ax);

					if(var==true)
						ar.add(ax);
				}
			}
		}

		for(int i=1;i<ar.size();i++)
		{
			for(int j=0;j<i;j++)
			{
				if(ar.get(i).size()<ar.get(j).size())
				{
					ArrayList<Integer> temp = ar.get(i);
					ar.set(i, ar.get(j));
					ar.set(j, temp);
				}
			}
		}

		int lakes = ar.size();
		int i=0;
		int cnt = 0;
		while(i<(lakes-k))
		{
			ArrayList<Integer> temp = ar.get(i);
			for(int x:temp){
				arr[x/m][x%m]='*';
				cnt++;
			}
			i++;
		}
		System.out.println(cnt);
		for( i=0;i<n;i++){
			for(int j=0;j<m;j++)
			{
				System.out.print(arr[i][j]+"");
			}
			System.out.println();
		}

	}
	private boolean get(int[][] visited, int i, int j, ArrayList<Integer> ax) {
		if(i==0 || i==n-1 || j==0 || j==m-1)
		{
			if(arr[i][j]=='*')
				return true;
			else
				return false;
		}

		if(arr[i][j]=='*')
			return true;

		visited[i][j]=1;
		boolean val1 = (visited[i][j+1]==1)?true:get(visited, i, j+1, ax);
		boolean val2 = (visited[i][j-1]==1)?true:get(visited, i, j-1, ax);
		boolean val3 = (visited[i-1][j]==1)?true:get(visited, i-1, j, ax);
		boolean val4 = (visited[i+1][j]==1)?true:get(visited, i+1, j, ax);
		boolean val =  val1 && val2 && val3 && val4;

		if(val==true)
			ax.add(i*m + j);
		else
			ax.clear();

		return val;

	}
}

