        if(!in(x,y)) return;
        if(mp[x][y] == '*') return;
        if(!vis[x][y]){
            vis[x][y] = true;
            set[x][y] = flag;
            fill(x,y+1,flag);
            fill(x,y-1,flag);
            fill(x+1,y,flag);
            fill(x-1,y,flag);
        }
