            for(int j=1; j<=m; j++){
                mp[i][j] = s[j-1];   // fixed index calculation
            }
        }



        int sptr = 0;
        for(int i=1; i<=n; i++){
            for(int j=1; j<=m; j++){
                if(mp[i][j] == '.' && !vis[i][j]){

                    fill(i,j, ++sptr);
                }
            }
        }


        HashSet<Pair>[] ts = new HashSet[sptr+1];

        for(int i=1; i<=sptr; i++) ts[i] = new HashSet<>();
        for(int i=1; i<=n; i++){
