import java.util.ArrayList;
import java.util.Collections;
import java.util.Scanner;

public class Main {

    static int n, m;
    static int cnt = 0;
    static boolean valid = true;
    static char[][] grid;
    static boolean[][] vis;

    static void solve(int i, int j) {

        if (i >= n || i < 0 || j >= m || j < 0) {
            valid = false;
            return;
        }
        if (grid[i][j] == '*') {
            return;
        }
        if (vis[i][j]) {
            return;
        }

        vis[i][j] = true;
        cnt++;

        solve(i + 1, j);
        solve(i - 1, j);
        solve(i, j + 1);
        solve(i, j - 1);

    }

    static void fill(int i , int j ){
        if (grid[i][j] == '*') {
            return;
        }
        if (vis[i][j]) {
            return;
        }

        vis[i][j] = true;
        grid[i][j]='*';

        fill(i + 1, j);
        fill(i - 1, j);
        fill(i, j + 1);
        fill(i, j - 1);

    }

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);

        n = scanner.nextInt();
        m = scanner.nextInt();
        int k = scanner.nextInt();
        grid = new char[n][m];
        vis = new boolean[n + 1][m + 1];
        scanner.nextLine();
        for (int i = 0; i < n; i++) {
            String curr = scanner.nextLine();
            for (int j = 0; j < m; j++) {
                grid[i][j] = curr.charAt(j);
            }
        }
        ArrayList<pair> sz = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {

                if (grid[i][j] == '.' && !vis[i][j]) {
                    cnt = 0;
                    valid = true;
                    solve(i, j);
                    if (cnt != 0 && valid) {
                        sz.add(new pair(cnt, i, j));
                    }
                }

            }
        }

        Collections.sort(sz);

        int ret = sz.size() - k;
        int celss = 0;
        vis = new boolean[n][m];
        for (int i = 0; i < ret; i++) {
            pair curr = sz.get(i);
            celss += curr.vlaue;
            fill(curr.first, curr.secod);
        }
        System.out.println(celss);
        for (int i = 0; i < n; i++) {
            System.out.println(new String(grid[i]));
        }
    }
}

