class TaskLakes {

    boolean [][] visited;

    int dx[] = new int[]{1, -1, 0, 0};
    int dy[] = new int[]{0, 0, -1, 1};

    int n;
    int m;
    int k;

    boolean ok;

    public int search(int i, int j, String [] lakes){
        visited[i][j] = true;
        int cnt = 0;
        for(int kp = 0; kp < 4; ++kp){
            int x = i + dx[kp];
            int y = j + dy[kp];
            if((x == 0 || y == 0  || x == n - 1 || y == m - 1)){
                if(x >= 0 && y >= 0 && x < n && y < m) {
                    if (lakes[x].charAt(y) == '.') {
                        ok = false;
                    }
                }
            }
            if(x >= 0 && y >= 0 && x < n && y < m) {
                if (visited[x][y] == false && lakes[x].charAt(y) == '.') {
                    cnt += search(x, y, lakes) + 1;
                }
            }
        }
        return cnt;
    }
    public class Start implements Comparable<Start> {
        int total;
        int x;
        int y;
        Start(int x, int y, int total){
            this.total = total;
            this.x = x;
            this.y = y;
        }
        @Override
        public int compareTo(Start start) {
            if(this.total < start.total){
                return -1;
            }
            if(this.total == start.total){
                return 0;
            }
            if(this.total > start.total){
                return 1;
            }
            return 0;
        }
    }

    public void fill(int i, int j, String [] lakes){
        visited[i][j] = true;
        for(int kp = 0; kp < 4; ++kp) {
            int x = i + dx[kp];
            int y = j + dy[kp];
            if (x >= 0 && y >= 0 && x < n && y < m) {
                if (visited[x][y] == false && lakes[x].charAt(y) == '.') {
                    fill(x, y, lakes);
                }
            }
        }
    }
    public void solve(int taskNumber, InputReaderLakes in, PrintWriter out) {
        n = in.nextInt();
        m = in.nextInt();
        k = in.nextInt();
        visited = new boolean[n][m];
        String [] lakes = new String[n];
        for(int i = 0; i < n; ++i){
            lakes[i] = in.next();
        }
        ArrayList<Start> sizes = new ArrayList<Start>();
        for(int i = 1; i < n - 1; ++i){
            for(int j = 1; j < m - 1; ++j){
                int cnt = 0;
                if(lakes[i].charAt(j) == '.' && visited[i][j] == false){
                    ok = true;
                    cnt = search(i, j, lakes);
                    cnt = cnt + 1;
                }
                if(ok && cnt > 0) {
                    Start start = new Start(i, j, cnt);
                    sizes.add(start);
                }
            }
        }
        Collections.sort(sizes);
        int res = 0;
        visited = new boolean[n][m];
        for(int i = 0; i < sizes.size() - k; ++i){
            res += sizes.get(i).total;
            fill(sizes.get(i).x, sizes.get(i).y, lakes);
        }
        System.out.println(res);
        for(int i = 0; i < n; ++i){
            String sp = "";
            for(int j = 0; j < m; ++j){
                if(visited[i][j] == true && lakes[i].charAt(j) == '.') {
                    sp += '*';
                }
                else if(visited[i][j] == false && lakes[i].charAt(j) == '*') {
                    sp += '*';
                }
                else {
                    sp += '.';
                }
            }
            System.out.println(sp);
        }
    }
}

class InputReaderLakes {
    public BufferedReader reader;
    public StringTokenizer tokenizer;

    public InputReaderLakes(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
        tokenizer = null;
    }

    public String next() {
        while (tokenizer == null || tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

