public class D {
    private static final long INF = (long)1e12;

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        long x0 = in.nextInt();
        long y0 = in.nextInt();

        char[] co = new char[n];
        long[] x = new long[n];
        long[] y = new long[n];
        for (int i = 0; i < n; i++) {
            co[i] = in.nextToken().toCharArray()[0];
            x[i] = in.nextInt();
            y[i] = in.nextInt();
        }

        boolean check = false;

        for (int rep = 0 ; rep <= 1 ; rep++) {
            char[] coma = new char[]{' ', ' ', ' ', ' '};
            long[] minMax = new long[]{-INF, INF, -INF, INF};
            for (int i = 0; i < n; i++) {
                int dir = -1;
                long value = -1;
                if (x[i] == x0) {
                    value = y[i];
                    if (y[i] < y0) {
                        dir = 2;
                    } else {
                        dir = 3;
                    }
                } else if (y[i] == y0) {
                    value = x[i];
                    if (x[i] < x0) {
                        dir = 0;
                    } else {
                        dir = 1;
                    }
                }
                if (dir == -1) {
                    continue;
                }
                if (dir % 2 == 0) {

                    if (minMax[dir] < value) {
                        minMax[dir] = value;
                        coma[dir] = co[i];
                    }
                } else {

                    if (minMax[dir] > value) {
                        minMax[dir] = value;
                        coma[dir] = co[i];
                    }
                }
            }
            for (int i = 0; i < 4; i++) {
                if (coma[i] == 'Q' || (coma[i] == 'R' && rep == 0) || (coma[i] == 'B' && rep == 1)) {
                    check = true;
                }
            }

            long tmpx = x0 + y0;
            long tmpy = x0 - y0;
            x0 = tmpx;
            y0 = tmpy;
            for (int i = 0; i < n ; i++) {
                tmpx = x[i] + y[i];
                tmpy = x[i] - y[i];
                x[i] = tmpx;
                y[i] = tmpy;
            }
        }

        out.println(check ? "YES" : "NO");
        out.flush();
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int[] nextInts(int n) {
            int[] ret = new int[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextInt();
            }
            return ret;
        }


        private int[][] nextIntTable(int n, int m) {
            int[][] ret = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    ret[i][j] = nextInt();
                }
            }
            return ret;
        }

        private long[] nextLongs(int n) {
            long[] ret = new long[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextLong();
            }
            return ret;
        }

        private long[][] nextLongTable(int n, int m) {
            long[][] ret = new long[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    ret[i][j] = nextLong();
                }
            }
            return ret;
        }

        private double[] nextDoubles(int n) {
            double[] ret = new double[n];
            for (int i = 0; i < n; i++) {
                ret[i] = nextDouble();
            }
            return ret;
        }

        private int next() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public char nextChar() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            if ('a' <= c && c <= 'z') {
                return (char) c;
            }
            if ('A' <= c && c <= 'Z') {
                return (char) c;
            }
            throw new InputMismatchException();
        }

        public String nextToken() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = next();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = next();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long nextLong() {
            int c = next();
            while (isSpaceChar(c))
                c = next();
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = next();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public double nextDouble() {
            return Double.valueOf(nextToken());
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);
        }
    }

    static void debug(Object... o) {
        System.err.println(Arrays.deepToString(o));
    }
}

