        State e = new State(Integer.MAX_VALUE, false);
        State w = new State(Integer.MAX_VALUE, false);
        State ne = new State(Integer.MAX_VALUE, false);
        State nw = new State(Integer.MAX_VALUE, false);
        State se = new State(Integer.MAX_VALUE, false);
