            int y = Integer.parseInt(st.nextToken());
            if(x == kingx){
                if(y > kingy){
                    if(y - kingy < n.dist){
                        n = new State(y - kingy, !type.equals("B"));
                    }
                } else {
                    if(kingy - y < s.dist){
                        s = new State(kingy - y, !type.equals("B"));
                    }
                }
            } else if(y == kingy){
                if(x > kingx){
                    if(x - kingx < w.dist){
                        w = new State(x - kingx, !type.equals("B"));
                    }
                } else {
                    if(kingx - x < e.dist){
                        e = new State(kingx - x, !type.equals("B"));
                    }
                }
