                if(x > kingx){
                    if(x - kingx < nw.dist){
                        nw = new State(x - kingx, !type.equals("R"));
                    }
                } else {
                    if(kingx - x < se.dist){
                        se = new State(kingx - x, !type.equals("R"));
                    }
                }
            } else if(x - kingx == kingy - y){
                if(x > kingx){
                    if(x - kingx < sw.dist){
                        sw = new State(x - kingx, !type.equals("R"));
                    }
                } else {
                    if(kingx - x < ne.dist){
                        ne = new State(kingx - x, !type.equals("R"));
                    }
                }
            }
        }
        if (n.threatening || s.threatening || e.threatening || w.threatening || ne.threatening || nw.threatening || se.threatening || sw.threatening){
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
        br.close();
        System.exit(0);
    }

