			split = f.readLine().split("\\s+");
			char id = split[0].charAt(0); long X = Long.parseLong(split[1]), Y = Long.parseLong(split[2]);
			a[i] = new Piece(id, X, Y);
			if(a[i].x == x) {
				if(a[i].y < y) {
					a[i].which[0] = true; 
					double dist = dist(X ,Y, x, y);
					if(dist < closestDists[0]) {
						closestDists[0] = dist;
						closest[0] = a[i];
					}
				}
				else {
					a[i].which[1] = true; 
					double dist = dist(X, Y, x, y);
					if(dist < closestDists[1]) {
						closestDists[1] = dist;
						closest[1] = a[i];
					}
				}
			} else if(a[i].y == y) {
				if(a[i].x < x) {
					a[i].which[2] = true; 
					double dist = dist(X, Y, x, y);
					if(dist < closestDists[2]) {
						closestDists[2] = dist;
						closest[2] = a[i];
					}
				}
				else {
					a[i].which[3] = true; 
					double dist = dist(X, Y, x, y);
					if(dist < closestDists[3]) {
						closestDists[3] = dist;
						closest[3] = a[i];
					}
				}
			} else if(Math.abs(a[i].x - x) == Math.abs(a[i].y - y)) {
				if(a[i].x < x && a[i].y > y) {
					a[i].which[4] = true; 
					double dist = dist(X, Y, x, y);
					if(dist < closestDists[4]) {
						closestDists[4] = dist;
						closest[4] = a[i];
					}
				}
				else if(a[i].x > x && a[i].y > y) {
					a[i].which[5] = true; 
					double dist = dist(X, Y, x, y);
					if (dist < closestDists[5]) {
						closestDists[5] = dist;
						closest[5] = a[i];
					}
				}
				else if(a[i].x < x && a[i].y < y) {
					a[i].which[6] = true; 
					double dist = dist(X, Y, x, y);
					if(dist < closestDists[6]) {
						closestDists[6] = dist;
						closest[6] = a[i];
					}
				}
				else {
					a[i].which[7] = true; 
					double dist = dist(X, Y, x, y);
					if(dist < closestDists[7]) {
						closestDists[7] = dist;
						closest[6] = a[i];
					}
				}
			}
		}

		boolean yes = false;
		for(int i = 0; i < 4; i++) {
			if(closest[i] == null) continue;
			if(closest[i].id == 'R' || closest[i].id == 'Q') yes = true;
		}
		for(int i = 4; i < 8; i++) {
			if(closest[i] == null) continue;
			if(closest[i].id == 'Q' || closest[i].id == 'B') yes = true;
		}
		System.out.println(yes ? "YES" : "NO");
	}

	static double dist(long x1, long y1, long x2, long y2) {
		long X = x1-x2;
		long Y = y1-y2;
		return (Math.sqrt(X*X + Y*Y));
	}
}


