private boolean processLine(int kx, int ky, Map<Character, List<Chess>> chess, boolean byX) {
    Chess main = new Chess('R', kx, ky);
    Map<Integer, List<Chess>> byLine = new HashMap<>();
    for (List<Chess> l : chess.values()) {
        for (Chess c : l) {
            byLine.computeIfAbsent(byX ? c.x : c.y, k -> new ArrayList<>()).add(c);
        }
    }
    List<Chess> curChess = byLine.get(byX ? main.x : main.y);
    if (curChess == null) {
        return false;
    }
    curChess.sort(Comparator.comparingInt(c -> c.x).thenComparingInt(c -> c.y));
    int sz = curChess.size();
    if ((sz == 1 && isR(curChess.get(0))) ||
            (isR(curChess.get(0)) && isAfterLine(main, curChess.get(0))) ||
            (isR(curChess.get(sz - 1)) && isAfterLine(curChess.get(sz - 1), main))) {
        return true;
    }
    for (int i = 0; i < sz - 1; i++) {
        Chess c1 = curChess.get(i);
        Chess c2 = curChess.get(i + 1);
        if (isOnLine(c1, main, c2)) {
            return isR(c1) || isR(c2);
        }
    }
    return false;
}

private boolean processDiag(int kx, int ky, Map<Character, List<Chess>> chess, boolean by1) {
    Chess main = new Chess('B', kx, ky);
    Map<Integer, List<Chess>> byDiag = new HashMap<>();
    for (List<Chess> l : chess.values()) {
        for (Chess c : l) {
            byDiag.computeIfAbsent(by1 ? c.diag1() : c.diag2(), k -> new ArrayList<>()).add(c);
        }
    }
    List<Chess> curChess = byDiag.get(by1 ? main.diag1() : main.diag2());
    if (curChess == null) return false;
    curChess.sort(Comparator.comparing(c -> c.x));
    int sz = curChess.size();
    if ((sz == 1 && isB(curChess.get(0))) ||
            (isB(curChess.get(0)) && isAfterDiag(main, curChess.get(0))) ||
            (isB(curChess.get(sz - 1)) && isAfterDiag(curChess.get(sz - 1), main))) {
        return true;
    }
    for (int i = 0; i < sz - 1; i++) {
        Chess c1 = curChess.get(i);
        Chess c2 = curChess.get(i + 1);
        if (isBetween(c1, main, c2)) {
            return isB(c1) || isB(c2);
        }
    }
    return false;
}

