public class D {

    public static void main(String[] args) throws IOException {
        new D().solve();
    }

    StringTokenizer tokenizer = null;
    BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

    String nextToken() throws IOException {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    private static class Pair {
        public long x, y;
        public Pair(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    void solve() throws IOException {
        int n = nextInt();
        long x0 = nextLong();
        long y0 = nextLong();
        List<Pair> f = new ArrayList<>();
        List<Pair> l = new ArrayList<>();
        List<Pair> s = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String token = nextToken();
            long x = nextLong();
            long y = nextLong();
            if ("B".equals(token)) {
                s.add(new Pair(x, y));
            } else if ("R".equals(token)) {
                l.add(new Pair(x, y));
            } else {
                f.add(new Pair(x, y));
            }
        }

        long up = Long.MAX_VALUE - 100;
        long down = Long.MAX_VALUE - 100;
        long left = Long.MAX_VALUE - 100;
        long right = Long.MAX_VALUE - 100;

        long upLeft = Long.MAX_VALUE - 100;
        long upRight = Long.MAX_VALUE - 100;
        long downLeft = Long.MAX_VALUE - 100;
        long downRight = Long.MAX_VALUE - 100;

        for (Pair slon: s) {
            if (slon.x == x0) {
                if (slon.y > y0) {
                    up = Math.min(up, slon.y - y0);
                } else {
                    down = Math.min(down, y0 - slon.y);
                }
            }
            if (slon.y == y0) {
                if (slon.x > x0) {
                    right = Math.min(right, slon.x - x0);
                } else {
                    left = Math.min(left, x0 - slon.x);
                }
            }
        }
        for (Pair lad: l) {
            if (lad.x - lad.y == x0 - y0) {
                if (lad.x > x0) {
                    upRight = Math.min(upRight, lad.x - x0);
                } else {
                    downLeft = Math.min(downLeft, x0 - lad.x);
                }
            }
            if (lad.x + lad.y == x0 + y0) {
                if (lad.x > x0) {
                    downRight = Math.min(downRight, lad.x - x0);
                } else {
                    upLeft = Math.min(upLeft, x0 - lad.x);
                }
            }
        }

        boolean result = false;
        for (Pair slon: s) {
            result = result || (
                    (slon.x + slon.y == x0 + y0 && -upLeft < slon.x - x0 && slon.x - x0 < downRight)
                    || (slon.x - slon.y == x0 - y0 && -upRight < slon.x - x0 && slon.x - x0 < downLeft)
                    );
        }
        for (Pair lad: l) {
            result = result || (
                    lad.x == x0 && -down < lad.y - y0 && lad.y - y0 < up ||
                    lad.y == y0 && -left < lad.x - x0 && lad.x - x0 < right
                    );
        }
        for (Pair ferz: f) {
            result = result || (
                    ferz.x - ferz.y == x0 - y0 && -downLeft < ferz.x - x0 && ferz.x - x0 < upRight ||
                            ferz.x + ferz.y == x0 + y0 && -upLeft < ferz.x - x0 && ferz.x - x0 < downRight ||
                            ferz.x == x0 && -down < ferz.y - y0 && ferz.y - y0 < up ||
                            ferz.y == y0 && -left < ferz.x - x0 && ferz.x - x0 < right
            );
        }
        if (result) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

}

