import java.util.Arrays;
import java.util.Scanner;

public class AntonAndChess {

    public static long diff(long n1, long n2) {
        if(n1 >= 0 && n2 >= 0) { 
            return Math.abs(n1-n2);
        }
        else if(n1 >= 0 && n2 < 0) { 
            return Math.abs(n1-n2);
        }
        else if(n1 < 0 && n2 >= 0) { 
            return Math.abs(n2-n1);
        }
        else { 
            return Math.abs((n2*-1)-(n1*-1));
        }
    }

    public static void resolveDirection(long[] xMax, long[] yMax, char[] dir, long x, long y, long bx, long by, char pi) {
        if(y == by && bx > x) { 
            if(xMax[0] > bx) {
                xMax[0] = bx; dir[0] = pi;
            }
        }
        else if(bx > x && by < y) { 
            long dif = diff(x, bx);
            if(Math.abs(bx-x) == Math.abs(by-y) && dif < xMax[1]) {
                xMax[1] = dif; dir[1] = pi;
            }
        }
        else if(x == bx && y > by) { 
            if (yMax[2] < by) {               // fixed condition
                yMax[2] = by; dir[2] = pi;
            }
        }
        else if(x > bx && y > by) { 
            long dif = diff(x, bx);
            if(Math.abs(bx-x) == Math.abs(by-y) && dif < xMax[3]) {
                xMax[3] = dif; dir[3] = pi;
            }
        }
        else if(y == by && bx < x) { 
            if(xMax[4] < bx) {
                xMax[4] = bx; dir[4] = pi;
            }
        }
        else if(bx < x && by > y) { 
            long dif = diff(x, bx);
            if(Math.abs(bx-x) == Math.abs(by-y) && dif < xMax[5]) {
                xMax[5] = dif; dir[5] = pi;
            }
        }
        else if(x == bx && y < by) { 
            if(by < yMax[6]) {
                yMax[6] = by; dir[6] = pi;
            }
        }
        else if(bx > x && by > y) { 
