@SuppressWarnings("unchecked")
public class P734D {

  int x0, y0;

  class Figure implements Comparable<Figure> {
    int x, y;
    long d;
    char t;

    public Figure(char t, int x, int y) {
      this.x = x;
      this.y = y;
      this.t = t;
      d = (long)Math.abs(x - x0) + (long)Math.abs(y - y0);
    }

    @Override
    public int compareTo(Figure f) {
      return Long.signum(d - f.d);
    }

    @Override
    public String toString() {
      return ("[x=" + x + ", y=" + y + ", t:" + t + "]");
    }
  }

  public void run() throws Exception {
    int n = nextInt();
    x0 = nextInt();
    y0 = nextInt();

    ArrayList<Figure> r = new ArrayList();
    ArrayList<Figure> l = new ArrayList();
    ArrayList<Figure> u = new ArrayList();
    ArrayList<Figure> d = new ArrayList();
    ArrayList<Figure> ru = new ArrayList();
    ArrayList<Figure> rd = new ArrayList();
    ArrayList<Figure> lu = new ArrayList();
    ArrayList<Figure> ld = new ArrayList();
    while ((n--) > 0) {
      char t = next().charAt(0);
      int x = nextInt(), y = nextInt();
      Figure f = new Figure(t, x, y);

      if (y == y0) {
        if (x > x0) {
          r.add(f);
        } else {
          l.add(f);
        }
      }

      if (x == x0) {
        if (y > y0) {
          u.add(f);
        } else {
          d.add(f);
        }
      }

      int dx = x - x0, dy = y - y0;
      if (Math.abs(dx) == Math.abs(dy) && dx != 0) {
        if (dx > 0) {
          if (dy > 0) {
            ru.add(f);
          } else {
            rd.add(f);
          }
        } else {
          if (dy > 0) {
            lu.add(f);
          } else {
            ld.add(f);
          }
        }
      }
    }

    r.sort(null); l.sort(null); u.sort(null); d.sort(null);
    ru.sort(null); rd.sort(null); lu.sort(null); ld.sort(null);

    println((((r.size() > 0) && ((r.get(0).t == 'R') || (r.get(0).t == 'Q'))) || 
             ((l.size() > 0) && ((l.get(0).t == 'R') || (l.get(0).t == 'Q'))) || 
             ((u.size() > 0) && ((u.get(0).t == 'R') || (u.get(0).t == 'Q'))) || 
             ((d.size() > 0) && ((d.get(0).t == 'R') || (d.get(0).t == 'Q'))) ||
             ((ru.size() > 0) && ((ru.get(0).t == 'B') || (ru.get(0).t == 'Q'))) ||  
             ((lu.size() > 0) && ((lu.get(0).t == 'B') || (lu.get(0).t == 'Q'))) ||  
             ((rd.size() > 0) && ((rd.get(0).t == 'B') || (rd.get(0).t == 'Q'))) ||  
             ((ld.size() > 0) && ((ld.get(0).t == 'B') || (ld.get(0).t == 'Q')))) ? "YES" : "NO");
  }

  public static void main(String... args) throws Exception {
    br = new BufferedReader(new InputStreamReader(System.in));
    pw = new PrintWriter(new BufferedOutputStream(System.out));
    new P734D().run();
    br.close();
    pw.close();
    System.err.println("\n[Time : " + (System.currentTimeMillis() - startTime) + " ms]");
  }

  static long startTime = System.currentTimeMillis();
  static BufferedReader br;
