import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class CF379Div2D {
    public static void main(String[] args) {
        InputStream input = System.in;
        OutputStream output = System.out;

        InputReader in = new InputReader(input);
        PrintWriter out = new PrintWriter(output);

        Solver solver = new Solver();
        solver.solve(in, out);

        out.close();
    }

    static class Solver {
        int n, x, y;
        Vertex[] vertex = new Vertex[8];

        public void solve(InputReader in, PrintWriter out) {
            n = in.nextInt();
            x = in.nextInt();
            y = in.nextInt();
            for (int i = 0; i < 8; ++i) {
                vertex[i] = new Vertex('?', 0, 0);
            }

            for (int i = 0; i < n; ++i) {
                char cc = in.nextChar();
                int xi = in.nextInt();
                int yi = in.nextInt();
                int index = check(xi, yi);
                if (index != -1) {
                    if (vertex[index].getC() == '?') {
                        vertex[index].setC(cc);
                        vertex[index].setX(xi);
                        vertex[index].setY(yi);
                    } else {
                        // keep the closest piece to the king in that direction
                        if (moreDistant(vertex[index].getX(), vertex[index].getY(), xi, yi)) {
                            vertex[index].setC(cc);
                            vertex[index].setX(xi);
                            vertex[index].setY(yi);
                        }
                    }
                }
            }
            boolean res = false;
            // rook / queen can check along vertical/horizontal directions (indices 0,2,4,6)
            for (int i : new int[]{0, 2, 4, 6}) {
                if (vertex[i].getC() == 'R' || vertex[i].getC() == 'Q') {
                    res = true;
                }
            }
            // bishop / queen can check along diagonal directions (indices 1,3,5,7)
            for (int i : new int[]{1, 3, 5, 7}) {
                if (vertex[i].getC() == 'B' || vertex[i].getC() == 'Q') {
                    res = true;
                }
            }
            if (res) {
                out.print("YES");
            } else {
                out.print("NO");
            }
        }

        /** returns true if (x1,y1) is farther from the king than (x2,y2) using Chebyshev distance */
        private boolean moreDistant(int x1, int y1, int x2, int y2) {
            int d1 = Math.max(Math.abs(x - x1), Math.abs(y - y1));
            int d2 = Math.max(Math.abs(x - x2), Math.abs(y - y2));
            return d1 > d2;
        }

        /** returns direction index (-1 if not aligned) */
        private int check(int x1, int y1) {
            int dx = x1 - x;
            int dy = y1 - y;

            if (dx == 0) {
                if (dy < 0) return 0;      // south
                else if (dy > 0) return 4; // north
            }
            if (dy == 0) {
                if (dx < 0) return 6;      // west
                else if (dx > 0) return 2; // east
            }
            if (Math.abs(dx) == Math.abs(dy)) {
                if (dx > 0 && dy < 0) return 1;   // southeast
                if (dx > 0 && dy > 0) return 3;   // northeast
                if (dx < 0 && dy > 0) return 5;   // northwest
                if (dx < 0 && dy < 0) return 7;   // southwest
            }
            return -1;
        }
    }

    static class Vertex {
        char c;
        int x, y;

        Vertex() {}

        Vertex(char c, int x, int y) {
            this.c = c;
            this.x = x;
            this.y = y;
        }

        int getX() { return x; }
        void setX(int x) { this.x = x; }
        int getY() { return y; }
        void setY(int y) { this.y = y; }
        char getC() { return c; }
        void setC(char c) { this.c = c; }
    }

    static class InputReader {
        BufferedReader br;
        StringTokenizer st;

        InputReader(InputStream input) {
            br = new BufferedReader(new InputStreamReader(input));
            st = null;
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }
        String nextLine() {
            String s = null;
            try {
                s = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return s;
        }

        char nextChar() { return next().charAt(0); }
    }
}

