	public static void main(String[] args){
		Scanner myS = new Scanner(System.in);
		long numPieces = myS.nextLong();
		long kingX = myS.nextLong();
		long kingY = myS.nextLong();
		String diaUpLeft = "none";
		String diaUpRight = "none";
		String diaDownLeft = "none";
		String diaDownRight = "none";
		String orthUp = "none";
		String orthRight = "none";
		String orthLeft = "none";
		String orthDown = "none";
		long distDUL = 2147483640;
		long distDUR = 2147483640;
		long distDDL = 2147483640;
		long distDDR = 2147483640;
		long distOU = 2147483640;
		long distOL = 2147483640;
		long distOR = 2147483640;
		long distOD = 2147483640;

		for(int i=0; i<numPieces; i++){
			String type = myS.next();
			long pieceX = myS.nextInt();
			long pieceY = myS.nextInt();

			if(pieceX == kingX){
				if(pieceY > kingY && ((pieceY-kingY) < distOD)) {
					orthDown = type;
					distOD = Math.abs(pieceY-kingY);
				}
				else if(pieceY < kingY && (kingY-pieceY) < distOU){
					orthUp = type;
					distOU = Math.abs(kingY - pieceY);
				}
			}
			if(pieceY == kingY){
				if(pieceX > kingX && ((pieceX-kingX) < distOR)) {
					orthRight = type;
					distOR = Math.abs(pieceX-kingX);
				}
				else if(pieceX < kingX && (kingX-pieceX) < distOL){
					orthLeft = type;
					distOL = Math.abs(kingX-pieceX);
				}
			}

			if(Math.abs(kingX-pieceX) == Math.abs(kingY-pieceY)){
				if(pieceX < kingX){
					if(pieceY < kingY && kingY-pieceY < distDUL){
						diaUpLeft = type;
						distDUL = Math.abs(kingY - pieceY);
					}
					if(pieceY > kingY && pieceY-kingY < distDDL){
						diaDownLeft = type;
						distDDL = Math.abs(pieceY - kingY);
					}
				}
				if(pieceX > kingX){
					if(pieceY < kingY && kingY-pieceY < distDUR){
						diaUpRight = type;
						distDUR = Math.abs(kingY-pieceY);
					}
					if(pieceY > kingY && pieceY-kingY < distDDR){
						diaDownRight = type;
						distDDR = Math.abs(pieceY-kingY);
					}
				}
			}
		}

		boolean inCheck = false;
		if(diaUpLeft.equals("B") || diaUpLeft.equals("Q")){
			inCheck = true;
		}
		if(diaUpRight.equals("B") || diaUpRight.equals("Q")){
			inCheck = true;
		}
		if(diaDownRight.equals("B") || diaDownRight.equals("Q")){
			inCheck = true;
		}
		if(diaDownLeft.equals("B") || diaDownLeft.equals("Q")){
			inCheck = true;
		}
		if(orthLeft.equals("R") || orthLeft.equals("Q")){
			inCheck = true;
		}
		if(orthRight.equals("R") || orthRight.equals("Q")){
			inCheck = true;
		}
		if(orthUp.equals("R") || orthUp.equals("Q")){
			inCheck = true;
		}
		if(orthDown.equals("R") || orthDown.equals("Q")){
			inCheck = true;
		}

		if(inCheck){
			System.out.println("YES");
		}
		else{
			System.out.println("NO");
		}
	}
}

