public class Main {

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(br.readLine());
		String[] line = br.readLine().split(" ");
		int kingX = Integer.parseInt(line[0]);
		int kingY = Integer.parseInt(line[1]);
		int[][] pieces = new int[n][3];
		ArrayList<ArrayList<int[]>> cand = new ArrayList<ArrayList<int[]>>();
		for(int i=0; i<8; i++) {
			cand.add(new ArrayList<int[]>());
		}
		for(int i=0; i<n; i++) {
			line = br.readLine().split(" ");
			pieces[i][0] = line[0].charAt(0);
			pieces[i][1] = Integer.parseInt(line[1]);
			pieces[i][2] = Integer.parseInt(line[2]);
			int x = pieces[i][1];
			int y = pieces[i][2];
			char piece = line[0].charAt(0);
			int diffX = kingX - x;
			int diffY = kingY - y;
			int dir = -1;
			if(diffX == 0) {
				if(diffY > 0)
					dir = 0;
				else
					dir = 4;
			} else if(diffY == 0) {
				if(diffX > 0) 
					dir = 2;
				else
					dir = 6;
			} else if(Math.abs(diffX) == Math.abs(diffY)) {
				if(diffX > 0) {
					if(diffY > 0)
						dir = 1;
					else 
						dir = 3;
				} else {
					if(diffY > 0)
						dir = 7;
					else
						dir = 5;
				}
			}
			int elg = 0;
			if(dir%2 == 0) {
				if(piece == 'R' || piece == 'Q')
					elg = 1;
			} else {
				if(piece == 'B' || piece == 'Q')
					elg = 1;
			}
			if(dir != -1) {
				int dist = 0;
				if(dir%2 == 0) {
					dist = Math.abs(diffX) + Math.abs(diffY);
				} else {
					dist = Math.abs(diffX);
				}
				int[] candArr = new int[] {dist, elg};
				cand.get(dir).add(candArr);
			}
		}
		boolean inCheck = false;
		for(int i=0; i<8 && !inCheck; i++) {
			Collections.sort(cand.get(i), new Comparator<int[]>() {
				@Override
				public int compare(final int[] a, final int[] b) {
					return a[0] - b[0];
				}
			});
			if(cand.get(i).size() > 0 && cand.get(i).get(0)[1] == 1)
				inCheck = true;
		}
		if(inCheck)
			System.out.println("YES");
		else
			System.out.println("NO");

	}

}

