import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int x0 = in.nextInt();
            int y0 = in.nextInt();
            char[] piece = new char[8];
            int[] dis = {Integer.MAX_VALUE, Integer.MAX_VALUE, Integer.MAX_VALUE, Integer.MAX_VALUE, Integer.MAX_VALUE, Integer.MAX_VALUE, Integer.MAX_VALUE, Integer.MAX_VALUE};
            for (int i = 0; i < n; i++) {
                char p = in.next().charAt(0);
                int x = in.nextInt();
                int y = in.nextInt();
                int d = dir(x - x0, y - y0);
                if (d != -1) {
                    int curDis = Math.max(Math.abs(x - x0), Math.abs(y - y0));
                    if (curDis < dis[d]) {
                        dis[d] = curDis;
                        piece[d] = p;
                    }
                }
            }
            for (int i = 0; i < 8; i++) {
                if (piece[i] == 'Q' || (i % 2 == 1 && piece[i] == 'B') || (i % 2 == 0 && piece[i] == 'R')) {
                    out.println("YES");
                    return;
                }
            }
            out.println("NO");
        }

        int dir(int dx, int dy) {
            if (dx == 0 && dy > 0) return 0;
            if (dx == dy && dy > 0) return 1;
            if (dy == 0 && dx > 0) return 2;
            if (dx == -dy && dy < 0) return 3;
            if (dx == 0 && dy < 0) return 4;
            if (dx == dy && dy < 0) return 5;
            if (dy == 0 && dx < 0) return 6;
            if (-dx == dy && dy > 0) return 7;
            return -1;
        }

    }

    static class InputReader {
        private StringTokenizer tokenizer;
        private BufferedReader reader;

        public InputReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        private void fillTokenizer() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }
        }

        public String next() {
            fillTokenizer();
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

