import java.math.BigInteger;
import java.util.*;


public class D {

    class Figure implements Comparable<Figure>{
        char c;
        int x;
        int y;
        long dist;

        public Figure(char c, int x, int y, long dist) {
            this.c = c;
            this.x = x;
            this.y = y;
            this.dist = dist;
        }

        @Override
        public int compareTo(Figure o) {
            if (dist==o.dist) return 0;
            if(dist<o.dist)return -1;
            return 1;
        }
    }

    void solve() throws IOException {
        int n=nextInt();
        long x0=nextInt();
        long y0=nextInt();
        Figure[] a=new Figure[n];
        for(int i=0;i<n;i++){
            char c=nextToken().charAt(0);
            int x=nextInt();
            int y=nextInt();
            long dist = Math.abs(x-x0)+Math.abs(y-y0);
            a[i]=new Figure(c,x,y,dist);
        }
        Arrays.sort(a);
        long mask=0;
        for(int i=0;i<n;i++){
            int x=a[i].x;
            int y=a[i].y;
            int curMask1=0;
            if(x>x0)curMask1=1;
            if(x<x0)curMask1=2;
            int curMask2=0;
            if(y>y0)curMask2=3;
            if(y<y0)curMask2=4;
            int curMask = curMask1+curMask2;
            if(curMask==0)continue;
            if(curMask1!=0&&curMask2!=0){
                if(curMask1==1){
                    if(curMask2==3)curMask=5;
                    else curMask=6;
                }else{
                    if(curMask2==3)curMask=7;
                    else curMask=8;
                }
                curMask=1<<curMask;
            }
            else curMask=1<<(curMask-1);
            if((mask&curMask)!=0)continue;
            if(x==x0||y==y0||Math.abs(x-x0)==Math.abs(y-y0)){
                mask|=curMask;
            }
            if(a[i].c!='B') {
                if(x==x0||y==y0){
                    out.println("YES");
                    return;
                }
            }
            if(a[i].c!='R'){
                if(Math.abs(x-x0)==Math.abs(y-y0)){
                    out.println("YES");
                    return;
                }
            }
        }
        out.println("NO");
    }

    public static void main(String[] args) throws IOException {
        new D().run();
    }

    void run() throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));

        tokenizer = null;
        out = new PrintWriter(new OutputStreamWriter(System.out));

        solve();
        reader.close();
        out.flush();

    }

    BufferedReader reader;
    StringTokenizer tokenizer;
    PrintWriter out;

    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

}

