class Piece
{
	private int x;
	private int y;
	private char type;

	public Piece(int x, int y, char type)
	{
		this.x = x;
		this.y = y;
		this.type = type;
	}

	public int getDirection(Piece piece)
	{
		if(this.x == piece.x && this.y < piece.y)
		{
			return 0;
		}
		else if(this.x < piece.x && this.x - piece.x == this.y - piece.y)
		{
			return 1;
		}
		else if(this.x < piece.x && this.x - piece.x == piece.y - this.y)
		{
			return 3;
		}
		else if(this.x == piece.x && this.y > piece.y)
		{
			return 4;
		}
		else if(this.x > piece.x && this.x - piece.x == this.y - piece.y)
		{
			return 5;
		}
		else if(this.x > piece.x && this.y == piece.y)
		{
			return 6;
		}
		else if(this.x > piece.x && this.x - piece.x == piece.y - this.y)
		{
			return 7;
		}

		return -1; 
	}

	public long getDistance(Piece piece)
	{
		return (long) Math.abs(this.x - piece.x) + Math.abs(this.y - piece.y);
	}

	public char getType()
	{
		return type;
	}
}

