		}
		else if(this.x > piece.x && this.x - piece.x == this.y - piece.y)
		{
			return 5;
		}
		else if(this.x > piece.x && this.y == piece.y)
		{
			return 6;
		}
		else if(this.x > piece.x && this.x - piece.x == piece.y - this.y)
		{
			return 7;
		}

		return -1; 
	}

	public long getDistance(Piece piece)
	{
		return (long) Math.abs(this.x - piece.x) + Math.abs(this.y - piece.y);
	}

