import static java.lang.System.exit;
import java.io.*;
import java.util.*;

public class C {

    static BufferedReader in;
    static PrintWriter out;
    static StringTokenizer tok;

    static int x0, y0;

    public static class figure {
        public int x, y;
        public char type;

        figure(char type, int x, int y) {
            this.type = type;
            this.x = x;
            this.y = y;
        }
    }

    public static int getDir(figure cur) {
        if (cur.y == y0 && cur.x < x0) {
            return 0;
        } else if (cur.y == y0 && cur.x > x0) {
            return 1;
        } else if (cur.x == x0 && cur.y < y0) {
            return 2;
        } else if (cur.x == x0 && cur.y > y0) {
            return 3;
        } else if (cur.x - cur.y == x0 - y0 && cur.x < x0) {
            return 4;
        } else if (cur.x - cur.y == x0 - y0 && cur.x > x0) {
            return 5;
        } else if (cur.x + cur.y == x0 + y0 && cur.x < x0) {
            return 6;
        } else if (cur.x + cur.y == x0 + y0 && cur.x > x0) {
            return 7;
        } else {
            return -1;
        }
    }

    public static int dist (int x1, int y1, int x2, int y2) {
        return Math.max(Math.abs(x1 - x2), Math.abs(y1 - y2));
    }

    public static void updateNearest (figure was, figure cur) {
        if (was.type == '?' || dist(x0, y0, cur.x, cur.y) < dist(x0, y0, was.x, was.y)) {
            int dir = getDir(cur);
            nearest[dir] = cur;
        }

    }

    static figure nearest[] = new figure[8];

    static void solve() throws Exception {
        final int n = nextInt();
        x0 = nextInt();
        y0 = nextInt();

        for (int i = 0; i < 8; ++i) {
            nearest[i] = new figure('?', 0, 0);
        }

        for (int i = 0; i < n; ++i) {
            char type = nextChar();
            int x = nextInt();
            int y = nextInt();

            figure cur = new figure(type, x, y);
            int dir = getDir(cur);

            if (dir >= 0) {
                updateNearest(nearest[dir], cur);
            }
        }

        boolean isFight = false;
        for (int i = 0; i < 4; ++i) {
            if (nearest[i].type == 'R' || nearest[i].type == 'Q')
                isFight = true;
        }

        for (int i = 4; i < 8; ++i) {
            if (nearest[i].type == 'B' || nearest[i].type == 'Q')
                isFight = true;
        }

        System.out.println(isFight ? "YES" : "NO");
    }



    static int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    static long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    static double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }

    static char nextChar() throws IOException {
        return (char)in.read();
    }

    static String next() throws IOException {
        while (tok == null || !tok.hasMoreTokens()) {
            tok = new StringTokenizer(in.readLine());
        }
        return tok.nextToken();
    }

    public static void main(String[] args) {
        try {
            in = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(new OutputStreamWriter(System.out));
            solve();
            in.close();
            out.close();
        } catch (Throwable e) {
            e.printStackTrace();
            exit(1);
        }
    }

}

