        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        static long[] dx = new long[]{0, 0, 1, 1, 1, -1, -1, -1};
        static long[] dy = new long[]{-1, 1, -1, 0, 1, -1, 0, 1};
        static long[] nearest = new long[8];
        static char[] nearestF = new char[8];
        long kingX;
        long kingY;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            Arrays.fill(nearest, 9000000000000000000L);
            Arrays.fill(nearestF, 'Z');
            int n = in.nextInt();
            kingX = in.nextInt();
            kingY = in.nextInt();
            for (int i = 0; i < n; ++i) {
                char type = in.next().charAt(0);
                long x = in.nextLong(), y = in.nextLong();
                long[] vector = getVector(x, y);
                for (int k = 0; k < 8; ++k) {
                    if (dx[k] == vector[0] && dy[k] == vector[1] && getDist(x, y) < nearest[k]) {
                        nearest[k] = getDist(x, y);
                        nearestF[k] = type;
                    }
                }
            }
            for (int k = 0; k < 8; ++k) {
                boolean threat = (dx[k] * dy[k] != 0 && nearestF[k] == 'B');
                threat |= (dx[k] * dy[k] == 0 && nearestF[k] == 'R');
                threat |= nearestF[k] == 'Q';
                if (threat) {
                    out.println("YES");
                    return;
                }
            }
            out.println("NO");
        }

        private long getDist(long x, long y) {
            return Math.abs(kingX - x) + Math.abs(kingY - y);
        }

        private long[] getVector(long x, long y) {
            long[] ret = new long[]{kingX - x, kingY - y};
            if (ret[0] != 0L && ret[1] != 0L) {
                long gcd = Math.abs(NumberTheory.gcd(ret[0], ret[1]));
                ret[0] /= gcd;
                ret[1] /= gcd;
            } else {
                long val = Math.max(Math.abs(ret[0]), Math.abs(ret[1]));
                ret[0] /= val;
                ret[1] /= val;
            }
            return ret;
        }

    }

    static class NumberTheory {
        public static long gcd(long a, long b) {
            if (b == 0L) return a;
            return gcd(b, a % b);
        }

    }

