import java.io.*;
import java.util.*;

public class AntonAndChess {
    static BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st;

    static class Dir {
        final int x, y;
        Dir(int x, int y) { this.x = x; this.y = y; }
        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Dir)) return false;
            Dir d = (Dir) o;
            return x == d.x && y == d.y;
        }
        @Override public int hashCode() { return Objects.hash(x, y); }
    }

    static class Info {
        final char type;
        final long dist;
        final Dir dir;
        Info(char type, long dist, Dir dir) {
            this.type = type;
            this.dist = dist;
            this.dir = dir;
        }
    }

    static long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }

    static String nextLine() throws IOException { return f.readLine(); }

    static String nextString() throws IOException {
        while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(nextLine());
        return st.nextToken();
    }

    static int nextInt() throws IOException { return Integer.parseInt(nextString()); }

    static long nextLong() throws IOException { return Long.parseLong(nextString()); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long x0 = nextLong();
        long y0 = nextLong();

        Map<Dir, Info> nearest = new HashMap<>();

        for (int i = 0; i < n; i++) {
            char type = nextString().charAt(0);
            long xi = nextLong();
            long yi = nextLong();
            long dx = xi - x0;
            long dy = yi - y0;
            if (dx == 0 && dy == 0) continue;               // impossible, but safe
            long g = gcd(Math.abs(dx), Math.abs(dy));
            int stepX = (int) (dx / g);
            int stepY = (int) (dy / g);
            Dir dir = new Dir(stepX, stepY);
            long dist = Math.max(Math.abs(dx), Math.abs(dy));
            Info cur = nearest.get(dir);
            if (cur == null || dist < cur.dist) {
                nearest.put(dir, new Info(type, dist, dir));
            }
        }

        for (Info info : nearest.values()) {
            Dir d = info.dir;
            if ((d.x == 0 || d.y == 0) && (info.type == 'R' || info.type == 'Q')) {
                System.out.println("YES");
