import java.io.*;
import java.util.*;

public class Main {

    private void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        long x0 = in.nextLong();
        long y0 = in.nextLong();
        String[] t = new String[n];
        long[] x = new long[n];
        long[] y = new long[n];

        for (int i = 0; i < n; i++) {
            t[i] = in.next();
            x[i] = in.nextLong();
            y[i] = in.nextLong();
        }

        long ny = Integer.MIN_VALUE;
        long py = Integer.MAX_VALUE;
        long nx = Integer.MIN_VALUE;
        long px = Integer.MAX_VALUE;
        String nt = "SS";
        String pt = "SS";
        String ntx = "SS";
        String ptx = "SS";
        for (int i = 0; i < n; i++) {
            if (x[i] == x0) {
                long yd = y[i] - y0;
                if (yd < 0 && yd > ny) {
                    ny = yd;
                    nt = t[i];
                } else if (yd > 0 && yd < py) {
                    py = yd;
                    pt = t[i];
                }
            }

            if (y[i] == y0) {
                long xd = x[i] - x0;
                if (xd < 0 && xd > nx) {
                    nx = xd;
                    ntx = t[i];
                } else if (xd > 0 && xd < px) {
                    px = xd;
                    ptx = t[i];
                }
            }
        }

        if ("R".equals(pt) || "Q".equals(nt) || "R".equals(nt) || "Q".equals(pt)
                || "R".equals(ptx) || "Q".equals(ntx) || "R".equals(ntx) || "Q".equals(ptx)) {
            out.println("YES");
        } else {

            long ll = Integer.MAX_VALUE;
            long lr = Integer.MAX_VALUE;
            long rl = Integer.MAX_VALUE;
            long rr = Integer.MAX_VALUE;
            String llt = "NO";
            String lrt = "NO";
            String rlt = "NO";
            String rrt = "NO";
            for (int i = 0; i < n; i++) {
                long xd = x[i] - x0;
                long yd = y[i] - y0;
                if (Math.abs(xd) == Math.abs(yd)) {
                    if (xd < 0 && yd < 0 && Math.abs(xd) < ll) {
                        ll = Math.abs(xd);
                        llt = t[i];
                    } else if (xd < 0 && yd > 0 && Math.abs(xd) < lr) {
                        lr = Math.abs(xd);
                        lrt = t[i];
                    } else if (xd > 0 && yd < 0 && Math.abs(xd) < rl) {
                        rl = Math.abs(xd);
                        rlt = t[i];
                    } else if (xd > 0 && yd > 0 && Math.abs(xd) < rr) {
                        rr = Math.abs(xd);
                        rrt = t[i];
                    }
                }
            }

            if ("B".equals(llt) || "B".equals(lrt) || "B".equals(rlt) || "B".equals(rrt)
                    || "Q".equals(llt) || "Q".equals(lrt) || "Q".equals(rlt) || "Q".equals(rrt)) {
                out.println("YES");
            } else {
                out.println("NO");
            }
        }
    }

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        new Main().solve(in, out);
        out.close();
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

    }
}

