import java.util.StringTokenizer;
import java.util.ArrayList;
import java.math.BigInteger;

public class Main{
  public static class InputReader {
    BufferedReader reader;
    StringTokenizer tokenizer;

    public InputReader(InputStream stream){
      reader = new BufferedReader(new InputStreamReader(stream));
    }

    public String next(){
      while(tokenizer == null || !tokenizer.hasMoreTokens()){
        try{
          tokenizer = new StringTokenizer(reader.readLine());
        } catch (IOException ioe) {
          throw new RuntimeException(ioe);
        }
      }
      return tokenizer.nextToken();
    }

    public int nextInt(){
      return Integer.parseInt(next());
    }

    public long nextLong(){
      return Long.parseLong(next());
    }

    public double nextDouble(){
      return Double.parseDouble(next());
    }

    public BigInteger nextBigInteger(){
      return new BigInteger(next());
    }
  }

  public static boolean canWin(char[][] p, int ax, int ay,  int bx, int by, int cx, int cy){
    int c = 0;
    int d = 0;
    if(p[ax][ay] == '.'){
      d++;
    }
    if(p[bx][by] == '.'){
      d++;
    }
    if(p[cx][cy] == '.'){
      d++;
    }
    if(p[ax][ay] == 'x'){
      c++;
    }
    if(p[bx][by] == 'x'){
      c++;
    }
    if(p[cx][cy] == 'x'){
      c++;
    }
    return (c == 2 && d == 1);
  }

  public static void main(String[] args){
    InputReader reader = new InputReader(System.in);
    PrintWriter pw = new PrintWriter(System.out);
    char[][] p = new char[4][4];
    for(int i=0;i<4;++i){
     p[i] = reader.next().toCharArray();
    } 
    boolean canWin = false;
    for(int i=0;i<4;++i){
      for(int j=0;j<2;++j){
        canWin |= canWin(p,i,j,i,j+1,i,j+2);
      }
    }
    for(int i=0;i<2;++i){
      for(int j=0;j<4;++j){
        canWin |= canWin(p,i,j,i+1,j,i+2,j);
      }
    }

    for(int i=0;i<2;++i){
      for(int j=0;j<2;++j){
        canWin |= canWin(p,i,j,i+1,j+1,i+2,j+2);
      }
    }

    for(int i=2;i<4;++i){
      for(int j=0;j<2;++j){
        canWin |= canWin(p,i,j,i-1,j+1,i-2,j+2);
      }
    }

    if(canWin){
      pw.println("YES");
    } else {
      pw.println("NO");
    }
    pw.flush();
    pw.close();
  }

}

