                }
            }
            String ans = "NO";
            for (i = 0; i < 4; i++) {
                for (j = 0; j <= 1; j++) {
                    if (a[i][j] + a[i][j + 1] + a[i][j + 2] == 2) {
                        ans = "YES";
                    }
                }
            }
            for (i = 0; i < 4; i++) {
                for (j = 0; j <= 1; j++) {
                    if (a[j][i] + a[j + 1][i] + a[j + 2][i] == 2) {
                        ans = "YES";
                    }
                }
            }
