            }
            if (a[0][3] + a[1][2] + a[2][1] == 2 || a[1][2] + a[2][1] + a[3][0] == 2) {
                ans = "YES";
            }
            // Added missing diagonal check
            if (a[1][3] + a[2][2] + a[3][1] == 2) {
                ans = "YES";
