        for (int c = 0; c < 3 && c + i < 4 && c + j < 4; c++) {
            char ch = board[c + i][j + c];
            if (ch == 'x')
                xs ++;
            if (ch == 'o')
                os ++;
            cnt++;
        }
        return xs == 2 && os == 0 && cnt == 3;
    }

    static boolean checkReverseDiagonal(int i, int j, char [][] board) {
        int xs = 0;
        int os = 0;
        int cnt = 0;
        for (int c = 0; c < 3 && i + c < 4 && j - c >= 0; c++) {
            char ch = board[i + c][j - c];
            if (ch == 'x')
                xs ++;
            if (ch == 'o')
                os ++;
            cnt++;
        }
        return xs == 2 && os == 0 && cnt == 3;
    }
}

