import java.util.Scanner;

public class Test {
    private static Scanner sc = new Scanner(System.in);
    public static void main(String[] args) {
        char[][] grid = new char[4][4];
        for (int i = 0; i < 4; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < 4; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        if (checkCanWin(grid)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    private static boolean checkCanWin(char[][] grid) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid.length; j++) {
                if (grid[i][j] != '.')
                    continue;

                grid[i][j] = 'x';
                if (checkWins(grid)) {
                    return true;
                }
                grid[i][j] = '.';
            }
        }
        return false;
    }

    private static boolean checkWins(char[][] grid) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid.length; j++) {
                if (grid[i][j] != 'x')
                    continue;

                if (checkFrom(i, j, grid)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean checkFrom(int i, int j, char[][] grid) {
        // vertical down
        if (i <= grid.length - 3) {
            if (grid[i + 1][j] == 'x' && grid[i + 2][j] == 'x')
                return true;
        }
        // horizontal right
        if (j <= grid.length - 3) {
            if (grid[i][j + 1] == 'x' && grid[i][j + 2] == 'x')
                return true;
        }
        // diagonal down‑right
        if (i <= grid.length - 3 && j <= grid.length - 3) {
            if (grid[i + 1][j + 1] == 'x' && grid[i + 2][j + 2] == 'x')
                return true;
        }
        // diagonal down‑left
        if (i <= grid.length - 3 && j >= 2) {
            if (grid[i + 1][j - 1] == 'x' && grid[i + 2][j - 2] == 'x')
                return true;
        }
        return false;
    }
}

