        // diagonal down‑right
        if (i < grid.length - 2 && j < grid.length - 2) {
            if (grid[i + 1][j + 1] == 'x' && grid[i + 2][j + 2] == 'x')
                return true;
        }

        // diagonal down‑left
        if (i < grid.length - 2 && j > 1) {
            if (grid[i + 1][j - 1] == 'x' && grid[i + 2][j - 2] == 'x')
                return true;
        }

