            for (int j = 0; j < 2; j++)
                if (grid[i][j] == 'x' && grid[i][j + 1] == 'x' && grid[i][j + 2] == 'x')
                    return true;
        return false;
    }

    static boolean col() {
        for (int i = 0; i < 4; i++)
