import java.util.*;

public class Main {
    static Scanner in = new Scanner(System.in);
    // directions: right, down, down‑right, down‑left
    private static final int[][] DIRS = {
            {0, 1},   // horizontal
            {1, 0},   // vertical
            {1, 1},   // diagonal down‑right
            {1, -1}   // diagonal down‑left
    };

    /** checks whether placing 'x' at (r,c) creates a winning triple */
    private static boolean makesWin(char[][] board, int r, int c) {
        board[r][c] = 'x';                       // temporary move
        // try every possible triple that contains (r,c)
        for (int[] d : DIRS) {
            for (int start = 0; start <= 1; ++start) { // we can start at most two steps before (r,c)
                int sr = r - start * d[0];
                int sc = c - start * d[1];
                // check the three cells starting from (sr,sc)
                if (sr < 0 || sr > 3 || sc < 0 || sc > 3) continue;
                boolean allX = true;
                for (int k = 0; k < 3; ++k) {
                    int rr = sr + k * d[0];
                    int cc = sc + k * d[1];
                    if (rr < 0 || rr > 3 || cc < 0 || cc > 3 || board[rr][cc] != 'x') {
                        allX = false;
                        break;
                    }
                }
                if (allX) {
                    board[r][c] = '.';               // restore board before returning
                    return true;
                }
            }
        }
        board[r][c] = '.';                         // restore board
        return false;
    }

    public static void main(String[] args) {
        char[][] board = new char[4][4];
        for (int i = 0; i < 4; ++i) {
            String line = in.next();
            for (int j = 0; j < 4; ++j) {
                board[i][j] = line.charAt(j);
            }
        }

        // try every empty cell
        for (int i = 0; i < 4; ++i) {
            for (int j = 0; j < 4; ++j) {
                if (board[i][j] == '.') {
                    if (makesWin(board, i, j)) {
                        System.out.println("YES");
                        return;
                    }
                }
            }
        }
        System.out.println("NO");
    }
}

