  static class TaskB {
      char[][] field;

    void solve(int testNumber, InputReader in, PrintWriter out) {
        field = new char[4][4];
        for (int i = 0; i < 4; ++i) {
            field[i] = in.next().toCharArray();
        }
        for (int i = 0; i < 4; ++i) {
            for (int j = 0; j < 4; ++j) {
                if (field[i][j] == '.') {
                    char bk = field[i][j];
                    field[i][j] = 'x';
