                            out.println("YES");
                            return;
                        }                        
                    }
                    field[i][j] = bk;
                }
            }

        }
        out.println("NO");
    }

    int dfs(BitSet vis, int x, int y, int dir) {
        vis.set(hash(x, y));
        int ret = 0;
        int nx = 0;
        int ny = 0;
        if (dir == 0) {
            nx = x + 1;
            ny = y;
            if (iswithin(nx, ny) && !vis.get(hash(nx, ny)) && field[nx][ny] == 'x') {
                ret += dfs(vis, nx, ny, dir) + 1;
            }
            nx = x - 1;
            ny = y;
            if (iswithin(nx, ny) && !vis.get(hash(nx, ny)) && field[nx][ny] == 'x') {
                ret += dfs(vis, nx, ny, dir) + 1;
            }
        }
        if (dir == 1) {
            nx = x + 1;
            ny = y + 1;
            if (iswithin(nx, ny) && !vis.get(hash(nx, ny)) && field[nx][ny] == 'x') {
                ret += dfs(vis, nx, ny, dir) + 1;
            }
            nx = x - 1;
            ny = y - 1;
            if (iswithin(nx, ny) && !vis.get(hash(nx, ny)) && field[nx][ny] == 'x') {
                ret += dfs(vis, nx, ny, dir) + 1;
            }
        }
        if (dir == 2) {
            nx = x;
            ny = y + 1;
            if (iswithin(nx, ny) && !vis.get(hash(nx, ny)) && field[nx][ny] == 'x') {
                ret += dfs(vis, nx, ny, dir) + 1;
            }
            nx = x;
            ny = y - 1;
            if (iswithin(nx, ny) && !vis.get(hash(nx, ny)) && field[nx][ny] == 'x') {
                ret += dfs(vis, nx, ny, dir) + 1;
            }
        }
        if (dir == 3) {
            nx = x - 1;
            ny = y + 1;
            if (iswithin(nx, ny) && !vis.get(hash(nx, ny)) && field[nx][ny] == 'x') {
                ret += dfs(vis, nx, ny, dir) + 1;
            }
            nx = x + 1;
            ny = y - 1;
            if (iswithin(nx, ny) && !vis.get(hash(nx, ny)) && field[nx][ny] == 'x') {
                ret += dfs(vis, nx, ny, dir) + 1;
            }
        }
        return ret;
    }

    int hash(int x, int y) {
        return x * 4 + y;
    }

    boolean iswithin(int x, int y) {
        return x >= 0 && x < 4 && y >= 0 && y < 4;
    }

    int i(long x) {
      return (int) x;
    }

    <T> void heapsort(T[] a, int s, int e) {
      Queue<T> queue = new PriorityQueue<>();
      for (int i = s; i <= e; ++i)
        queue.add(a[i]);
      for (int i = s; i <= e; ++i)
        a[i] = queue.poll();
    }    

  }

