public class P2 {
    static boolean valid(int i, int j) {
        return i >= 0 && j >= 0 && i < 4 && j < 4;
    }

    public static void main(String[] args) throws Exception {
        java.util.Scanner sc = new java.util.Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        StringBuilder sb = new StringBuilder();

        char[][] arr = new char[4][4];
        for (int i = 0; i < 4; ++i)
            arr[i] = sc.next().toCharArray();

        int dx[] = {0, 0, 1, -1, 1, -1, 1, -1};
        int dy[] = {1, -1, 0, 0, 1, -1, -1, 1};

        boolean can = false;
        for (int i = 0; i < 4; ++i) {
            for (int j = 0; j < 4; ++j) {
                if (arr[i][j] == '.') {
                    for (int k = 0; k < 8; ++k) {
                        int nx = i + dx[k];
                        int ny = j + dy[k];
                        int nx2 = i + 2 * dx[k];
                        int ny2 = j + 2 * dy[k];
                        if (!(!valid(nx, ny) || !valid(nx2, ny2) || arr[nx][ny] != 'x' || arr[nx2][ny2] != 'x')) {
                            can = true;
                        }
                    }
                }
            }
        }

        for (int i = 0; i < 4; ++i) {
            for (int j = 0; j < 4; ++j) {
                if (arr[i][j] == '.') {
                    if (valid(i + 1, j) && valid(i - 1, j) && arr[i + 1][j] == 'x' && arr[i - 1][j] == 'x') {
                        can = true;
                    }
                    if (valid(i, j - 1) && valid(i, j + 1) && arr[i][j - 1] == 'x' && arr[i][j + 1] == 'x') {
                        can = true;
                    }
                    if (valid(i - 1, j + 1) && valid(i + 1, j - 1) && arr[i - 1][j + 1] == 'x' && arr[i + 1][j - 1] == 'x') {
                        can = true;
                    }
                    if (valid(i - 1, j - 1) && valid(i + 1, j + 1) && arr[i - 1][j - 1] == 'x' && arr[i + 1][j + 1] == 'x') {
                        can = true;
                    }
                }
            }
        }

        if (can) System.out.println("YES");
        else System.out.println("NO");
        out.flush();
        out.close();
    }

    static class Scanner {
        java.util.StringTokenizer st;
        BufferedReader br;

        public Scanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new java.util.StringTokenizer(br.readLine());
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public double nextDouble() throws IOException {
            String x = next();
            StringBuilder sb = new StringBuilder("0");
            double res = 0, f = 1;
            boolean dec = false, neg = false;
            int start = 0;
            if (x.charAt(0) == '-') {
                neg = true;
                start++;
            }
            for (int i = start; i < x.length(); i++)
                if (x.charAt(i) == '.') {
                    res = Long.parseLong(sb.toString());
                    sb = new StringBuilder("0");
                    dec = true;
                } else {
                    sb.append(x.charAt(i));
                    if (dec)
                        f *= 10;
                }
            res += Long.parseLong(sb.toString()) / f;
            return res * (neg ? -1 : 1);
        }

        public boolean ready() throws IOException {
            return br.ready();
        }
    }
}

