	void solve()
	{
		char[][] map = nm(4,4);
		for(int i = 0;i < 4;i++){
			for(int j = 0;j < 4;j++){
				if(map[i][j] == '.'){
					map[i][j] = 'x';
					if(win(map)){
						out.println("YES");
						return;
					}
					map[i][j] = '.';
				}
			}
		}
