	}

	boolean win(char[][] map)
	{
		for(int i = 0;i < 4;i++){
			for(int j = 0;j < 4;j++){
				for(int k = -1;k <= 1;k++){
					inner:
					for(int l = -1;l <= 1;l++){
						if(k == 0 && l == 0)continue;
						for(int d = 0;d <= 2;d++){
							int r = i + d*k, c = j + d*l;
							if(r >= 0 && r < 4 && c >= 0 && c < 4 && map[r][c] == 'x'){
							}else{
								continue inner;
							}
						}
						return true;
					}
				}
			}
		}
		return false;
	}

	void run() throws Exception
	{
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		long s = System.currentTimeMillis();
		solve();
		out.flush();
		if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
	}

	public static void main(String[] args) throws Exception 
	{ new Main().run(); }

	private byte[] inbuf = new byte[1024];
	public int lenbuf = 0, ptrbuf = 0;

	private int readByte()
	{
		if(lenbuf == -1)throw new InputMismatchException();
		if(ptrbuf >= lenbuf)
		{
			ptrbuf = 0;
			try 
			{ lenbuf = is.read(inbuf); } 
			catch (IOException e) 
			{ throw new InputMismatchException(); }
			if(lenbuf <= 0)return -1;
		}
		return inbuf[ptrbuf++];
	}

	private boolean isSpaceChar(int c)
	{ return !(c >= 33 && c <= 126); }
	private int skip() 
	{ int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

	private double nd() 
	{ return Double.parseDouble(ns()); }
	private char nc()
	{ return (char)skip(); }

	private String ns()
	{
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while(!(isSpaceChar(b)))
		{ 
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private char[] ns(int n)
	{
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while(p < n && !(isSpaceChar(b)))
		{
			buf[p++] = (char)b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private char[][] nm(int n, int m)
	{
		char[][] map = new char[n][];
		for(int i = 0;i < n;i++)map[i] = ns(m);
		return map;
	}

	private int[] na(int n)
	{
		int[] a = new int[n];
		for(int i = 0;i < n;i++)a[i] = ni();
		return a;
	}

	private int ni()
	{
		int num = 0, b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-')
		{
			minus = true;
			b = readByte();
		}

		while(true)
		{
			if(b >= '0' && b <= '9')
			{
				num = num * 10 + (b - '0');
			}else
			{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private long nl()
	{
		long num = 0;
		int b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-')
		{
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9')
			{
				num = num * 10 + (b - '0');
			}else
			{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static void tr(Object... o) 
	{ System.out.println(Arrays.deepToString(o)); }
}

import java.util.*;

public class Solution {
    private static boolean
    up(char[][] board, int count, int i, int j) {
        int I = i;
        int J = j - count;
        if (J < 0 || J > 3) {
            return false;
        }
        return board[I][J] == 'x';
    }

    private static boolean
    left(char[][] board, int count, int i, int j) {
        int I = i - count;
        int J = j;
        if (I < 0 || I > 3) {
            return false;
        }
        return board[I][J] == 'x';
    }

    private static boolean
    diagonal(char[][] board, int rotation, int count, int i, int j) {
        int incrementI = -10000;
        int incrementJ = -10000;
        switch (rotation) {
            case 1:
                incrementI = 1;
                incrementJ = 1;
                break;
            case 2:
                incrementI = 1;
                incrementJ = -1;
                break;
        }
        int I;
        int J;
        I = i + incrementI * count;
        J = j + incrementJ * count;
        if (I < 0 || I > 3 || J < 0 || J > 3) {
            return false;
        }
        return board[I][J] == 'x';
    }

    private static boolean checkHorizontal(char[][] board, int i, int j) {
        boolean case1, case2, case3;
        case1 = up(board, 2, i, j) &&
                up(board, 1, i, j);
        case2 = up(board, 1, i, j) &&
                up(board, -1, i, j);
        case3 = up(board, -1, i, j) &&
                up(board, -2, i, j);
        return case1 || case2 || case3;
    }

    private static boolean checkVertical(char[][] board, int i, int j) {
        boolean case1, case2, case3;
        case1 = left(board, 2, i, j) &&
                left(board, 1, i, j);
        case2 = left(board, 1, i, j) &&
                left(board, -1, i, j);
        case3 = left(board, -1, i, j) &&
                left(board, -2, i, j);
        return case1 || case2 || case3;
    }

    private static boolean checkDiagonal(char[][] board, int i, int j) {
        for (int rotation = 1; rotation <= 2; rotation++) {
            boolean case1, case2, case3;
            case1 = diagonal(board, rotation, 2, i, j) &&
                    diagonal(board, rotation, 1, i, j);
            case2 = diagonal(board, rotation, 1, i, j) &&
                    diagonal(board, rotation, -1, i, j);
            case3 = diagonal(board, rotation, -1, i, j) &&
                    diagonal(board, rotation, -2, i, j);
            if (case1 || case2 || case3) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        char[][] board = new char[4][4];

        for (int i = 0; i < 4; i++) {
            String input = in.nextLine().trim();
            for (int j = 0; j < 4; j++) {
                board[i][j] = input.charAt(j);
            }
        }

        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                if (board[i][j] != '.') {
                    continue;
                }
                if (checkDiagonal(board, i, j) ||
                        checkHorizontal(board, i, j) ||
                        checkVertical(board, i, j)) {
                    System.out.println("YES");
                    return;
                }
            }
        }

        System.out.println("NO");
    }
}

