            for (int i = 0; i < 4; ++i) {
                board[i] = in.next().toCharArray();
            }
            for (int i = 0; i < 4; ++i) {
                for (int j = 0; j < 4; ++j) {
                    if (board[i][j] == '.') {
                        board[i][j] = x;
                        if (check(board)) {
