                            return;
                        } else {
                            board[i][j] = '.';
                        }
                    }
                }
            }
            out.println("NO");
        }
        static boolean check(char[][] board) {
            for (int i = 0; i < 4; ++i) {
                if (String.valueOf(board[i]).contains("xxx")) {
                    return true;
                }
            }
            for (int i = 0; i < 4; ++i) {
                String temp = "";
                for (int j = 0; j < 4; ++j) {
                    temp += board[j][i];
                }
                if (temp.contains("xxx")) {
                    return true;
                }
            }
            for (int i = 0; i < 4; ++i) {
                for (int j = 0; j < 4; ++j) {
