                                if (board[i + 1][j - 1] == x && board[i + 2][j - 2] == x) {
                                    return true;
                                }
                            }
                        } else {
                            if (j < 2) {
                                if (board[i - 1][j + 1] == x && board[i - 2][j + 2] == x) {
                                    return true;
                                }
                            } else {
                                if (board[i - 1][j - 1] == x && board[i - 2][j - 2] == x) {
                                    return true;
                                }
                            }
                        }
                    }
                }
