                if (f[i+1][j] == 'x' && f[i+2][j] == 'x') return true;
            }
        }
    }

    // Main diagonal
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            if (f[i][j] == 'x') {
                if (f[i+1][j+1] == 'x' && f[i+2][j+2] == '.') return true;
