                    if (j+1 < 4 && j+2 < 4 && map[i][j+1]=='x' && map[i][j+2]=='x'){
                        return true;
                    }
                    // vertical
                    if (i+1 < 4 && i+2 < 4 && map[i+1][j]=='x' && map[i+2][j]=='x'){
                        return true;
                    }
                    // diagonal down‑right
                    if (i+1 < 4 && i+2 < 4 && j+1 < 4 && j+2 < 4 && map[i+1][j+1]=='x' && map[i+2][j+2]=='x'){
                        return true;
                    }
                    // diagonal down‑left
                    if (i+1 < 4 && i+2 < 4 && j-1 >= 0 && j-2 >= 0 && map[i+1][j-1]=='x' && map[i+2][j-2]=='x'){
                        return true;
                    }
                }
