import java.util.Random;
import java.util.StringTokenizer;

public class Main {

    static class Pair implements Comparable<Pair> {

        int x;
        int y;

        Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public int compareTo(Pair o) {
            int comp1 = Integer.compare(x, o.x);
            if (comp1 != 0) {
                return comp1;
            }
            return Integer.compare(y, o.y);
        }

    }

    static int MOD = 1000 * 1000 * 1000 + 7;

    public static void shuffleArray(int[] arr) {
        int n = arr.length;
        Random rnd = new Random();
        for (int i = 0; i < n; ++i) {
            int tmp = arr[i];
            int randomPos = i + rnd.nextInt(n - i);
            arr[i] = arr[randomPos];
            arr[randomPos] = tmp;
        }
    }

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        solve(in, out);
        out.close();
        System.exit(0);
    }

    private static void solve(InputReader in, PrintWriter out) {
        int SIZ = 4;
        char[][] tab = new char[SIZ][SIZ];
        for(int i = 0; i < SIZ; i++) {
            tab[i] = in.next().toCharArray();
        }

        for(int i = 0; i < SIZ; i++) {
            for(int j = 0; j < SIZ; j++) {
                if(tab[i][j] != '.') {
                    continue;
                }
                tab[i][j] = 'x';
                if(check(tab)) {
                    out.print("YES");
                    return;
                }
                tab[i][j] = '.';
            }
        }



        out.print("NO");
    }

    private static boolean check(char[][] tab) {
        int[] dirX = {0, 1, 1, -1};
        int[] dirY = {1, 0, 1, 1};

        for(int i = 0; i < tab.length; i++) {
            for(int j = 0; j < tab[i].length; j++) {

                for(int k = 0; k < 4; k++) {
                    boolean ok = true;
                    for(int cnt = 0; cnt < 3; cnt++) {
                        int newX = i + dirX[k] * cnt;
                        int newY = j + dirY[k] * cnt;   // Fixed: use addition instead of modulo
                        if(newX >= 0 && newX < tab.length && newY >= 0 && newY < tab.length && tab[newX][newY] == 'x') {
                            continue;
                        } else {
                            ok = false;
                        }
                    }
                    if(ok) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    static int gcd(int n, int m) {
        if (m == 0) {
            return n;
        }
        return gcd(m, n % m);
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            String str = "";
            try {
                str = reader.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

}

