import java.io.BufferedOutputStream;
import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintStream;
import java.util.Locale;
import java.util.StringTokenizer;

public class Solution implements Runnable {

	public static final String NO = "";
	public static final String YES = "YES";

	public static final char CE = '.';
	public static final char CX = 'x';
	public static final char CO = 'o';

	public static final int[] DI = {-1, -1, 0, 1, 1, 1, 0, -1};
	public static final int[] DJ = {0, 1, 1, 1, 0, -1, -1, -1};

	private PrintStream out;
	private BufferedReader in;
	private StringTokenizer st;

	public void solve() throws IOException {
		char[][] a = new char[4][];
		for (int i = 0; i < a.length; i++) {
			a[i] = next().toCharArray();
		}
		String answer = solve(a);
		out.println(answer);
	}

	private String solve(char[][] a) {
		for (int i = 0; i < 4; i++) {
			for (int j = 0; j < 4; j++) {
				if (a[i][j] == CE) {
					a[i][j] = CX;
					if (win(a)) {
						return YES;
					}
					a[i][j] = CE;
				}
			}
		}
		return NO;
	}

	private boolean win(char[][] a) {
		for (int i = 0; i < 4; i++) {
			for (int j = 0; j < 4; j++) {
				for (int d = 0; d < DI.length; d++) {
					if (win(i, j, DI[d], DJ[d], a)) {
						return true;
					}
				}
			}
		}
		return false;
	}

	private boolean win(int i, int j, int di, int dj, char[][] a) {
		for (int k = 0; k < 3; k++) {
			int ii = i + di * k;
			int jj = j + dj * k;
			if (ii < 0 || ii >= 4 || jj < 0 || jj >= 4) {
				return false;
			}
			if (a[ii][jj] != CX) {  // Fixed: use jj instead of j
				return false;
			}
		}
		return true;
	}

	public double nextDouble() throws IOException {
		return Double.parseDouble(next());
	}

	public long nextLong() throws IOException {
		return Long.parseLong(next());
	}

	public int nextInt() throws IOException {
		return Integer.parseInt(next());
	}

	public String next() throws IOException {
		while (!st.hasMoreTokens()) {
			String line = in.readLine();
			if (line == null) {
				return null;
			}
			st = new StringTokenizer(line);
		}
		return st.nextToken();
	}

	@Override
	public void run() {
		try {
			solve();
			out.close();
		} catch (Throwable e) {
			throw new RuntimeException(e);
		}
	}

	public Solution(String name) throws IOException {
		Locale.setDefault(Locale.US);
		if (name == null) {
			in = new BufferedReader(new InputStreamReader(System.in));
			out = System.out;
		} else {
			in = new BufferedReader(new InputStreamReader(new FileInputStream(name + ".in")));
			out = new PrintStream(new BufferedOutputStream(new FileOutputStream(name + ".out")));
		}
		st = new StringTokenizer("");
	}

	public static void main(String[] args) throws IOException {
		new Thread(new Solution(null)).start();
	}
}

