                        marks[0]++;
                    if (isX(g, i - k, j))
                        marks[1]++;
                    if (isX(g, i, j + k))
                        marks[2]++;
                    if (isX(g, i, j - k))
                        marks[3]++;
                    if(isX(g, i-k, j-k))
                        marks[4]++;
                    if (isX(g, i+k, j+k))
                        marks[5]++;
                    if (isX(g, i-k, j+k))
                        marks[6]++;
                    if (isX(g, i+k, j-k))
                        marks[7]++;
                }
                for (int k = 0; k < marks.length; k++)
                    if (marks[k] == 3)
                        return true;
            }
        return  false;
    }

    private static boolean isX(char[][] g, int i, int j) {
        if (i >= 0 && i <= 3 && j >= 0 && j <= 3)
            return g[i][j] == 'x';
        return false;
    }
}

