import java.io.*;
import java.util.*;


public class Main{


	BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
	static class State {
		int i;
		int j;
		int dir;
		int turns;
		public State(int a, int b, int c, int d) {
			i=a;
			j=b;
			dir=c;
			turns =d;
		}
		public String toString() {
			return "[" + i + ", " + j + "] | " + dir + " | " + turns;
		}
	}

	static final int UP = 0, RIGHT = 1, DOWN = 2, LEFT = 3;
   public static void main(String[] args) throws IOException{
	StringTokenizer st = new StringTokenizer(br.readLine());
	int n = Integer.parseInt(st.nextToken());
	int m = Integer.parseInt(st.nextToken());
	int si = 0;
	int sj = 0;
	char[][] g = new char[n][m];
	for (int i = 0; i < n; i++) {
		String s = br.readLine();
		for (int j = 0; j < m; j++) {
			g[i][j] = s.charAt(j);
			if (g[i][j] == 'S') {
				si = i;
				sj = j;
			}
		}
	}

	Queue<State> q = new LinkedList<State>();
	for (int i = 0; i < 4; i++) {
		q.add(new State(si,sj,i,0));
	}
	boolean works = false;
	int[][][] dp = new int[n][m][4];
	for (int[][] a: dp) {
		for (int[] x: a) {
			Arrays.fill(x, 4);
		}
	}
	while (!q.isEmpty() && !works) {
		State h = q.poll();


		if (h.turns > 2 || g[h.i][h.j] == '*') continue;

		if (dp[h.i][h.j][h.dir] > h.turns) {
			dp[h.i][h.j][h.dir] = h.turns;
		}
		else continue;

		if (g[h.i][h.j] == 'T') {
			works = true;
			break;
		}
		if (h.i != 0 && h.dir != DOWN) {
			int temp = 0;
			if (h.dir != UP) {
				temp++;
			}
			q.add(new State(h.i-1, h.j, UP, h.turns + temp));

		}
		if (h.i != n-1 && h.dir != UP) {
			int te = 0;
			if (h.dir != DOWN) {
				te++;
			}
			q.add(new State(h.i+1, h.j, DOWN, h.turns+te));
		}
		if (h.j != 0 && h.dir != RIGHT) {int asf =0;
			if (h.dir != LEFT) {
				asf++;
			}
			q.add(new State(h.i, h.j-1, LEFT, h.turns + asf));
		}
		if (h.j != m-1 && h.dir != LEFT) {int af = 0;
			if (h.dir != RIGHT) {
				af++;
			}
			q.add(new State(h.i, h.j+1, RIGHT, h.turns+af));
		}

	}

	out.println(works ? "YES" :"NO");

	out.close();
   }
