    public void dop(char[][] arr,int x,int y,int[][] brr)
    {
        int n=arr.length;
        int m=arr[0].length;
        int p=0;
        if(arr[x][y]=='T')
        p=1;
        brr[x][y]=p;
        int k=x-1;
        while(k>=0&&arr[k][y]=='.')
        {brr[k][y]=p;
        k--;}

        k=x+1;
        while(k<n&&arr[k][y]=='.')
        {brr[k][y]=p;
        k++;}

        k=y-1;
        while(k>=0&&arr[x][k]=='.')
        {brr[x][k]=p;
        k--;}
        k=y+1;
        while(k<m&&arr[x][k]=='.')
        {brr[x][k]=p;
        k++;}
    }
