public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Input in = new Input(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, Input in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] s = new char[n][];
            for (int i = 0; i < n; i++) {
                s[i] = in.nextLine().toCharArray();
            }

            boolean[][][][] used = new boolean[n][m][4][3];
            Queue<State> q = new LinkedList<>();
            int[] dx = new int[]{+1, -1, 0, 0};
            int[] dy = new int[]{0, 0, +1, -1};

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (s[i][j] == 'S') {
                        for (int dir = 0; dir < 4; dir++) {
                            used[i][j][dir][0] = true;
                            q.add(new State(j, i, dir, 0));
                        }
                        while (!q.isEmpty()) {
                            State p = q.poll();
                            for (int dir = 0; dir < 4; dir++) {
                                int x = p.x + dx[dir];
                                int y = p.y + dy[dir];
                                int changed = p.changed + (p.lastDir == dir ? 0 : 1);
                                if (!correct(x, y, changed, n, m, s, used, dir)) {
                                    continue;
                                }
                                used[y][x][dir][changed] = true;
                                q.add(new State(x, y, dir, changed));
                            }
                        }
                    }
                }
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (s[i][j] == 'T') {
                        boolean ok = false;
                        for (int k = 0; k < 4; k++)
                            for (int c = 0; c < 3; c++) {
                                ok |= used[i][j][k][c];
                            }
                        out.println(ok ? "YES" : "NO");
                    }
                }
            }

        }

        private boolean correct(int x, int y, int changed, int n, int m, char[][] s, boolean[][][][] used, int dir) {
            if (x < 0 || y < 0 || x >= m || y >= n)
                return false;
            if (s[y][x] == '*')
                return false;
            if (changed >= 3)
                return false;
            if (used[y][x][dir][changed])
                return false;

            return true;
        }

        class State {
            int x;
            int y;
            int lastDir;
            int changed;

            public State(int x, int y, int lastDir, int changed) {
                this.x = x;
                this.y = y;
                this.lastDir = lastDir;
                this.changed = changed;
            }

        }

    }

