public class B{
	public static void main(String[] args){
		Scanner in = new Scanner(System.in);
		int n = Integer.parseInt(in.next());
		int m = Integer.parseInt(in.next());

		short[][] s = new short[n][m];

		boolean[][][][] p = new boolean[4][3][n][m];

		int sx = -1, sy = -1;

		for(int i = 0; i < n; i++){
			String line = in.next();
			for(int i2 = 0; i2 < m; i2++){
				char c = line.charAt(i2);
				if(c == '.'){
					s[i][i2] = 1;
				}else if(c == '*'){
					s[i][i2] = 2;
				}else if(c == 'T'){
					s[i][i2] = 3;
				}else if(c == 'S'){
					s[i][i2] = 4;
					sy = i;
					sx = i2;
				}
			}
		}

		boolean f = false;

		if(xplore(0, sx, sy, s, p, 2, n, m)){
			f = true;
		}else if(xplore(1, sx, sy, s, p, 2, n, m)){
			f = true;
		}else if(xplore(2, sx, sy, s, p, 2, n, m)){
			f = true;
		}else if(xplore(3, sx, sy, s, p, 2, n, m)){
