            else break;
            flags[row][i] = L;
        }
    }

    private static void checkDown(int row, int col, int depth, Queue<int[]> queue) throws Exception {
        for (int i = row + 1; i < N; i++) {
            if (flags[i][col] == D) break;
            if (labyrinth[i][col] == '.') {
