import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

public class TinkoffB {
	public static void main(String args[]) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		InputReader in = new InputReader(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		Solver solver = new Solver();
		solver.solve(in, out);
		out.close();
	}

	static class Solver{

		public void solve(InputReader in, PrintWriter out) {
			final int NORTH = 0, EAST = 1, SOUTH = 2, WEST = 3;
			int n = in.nextInt();
			int m = in.nextInt();
			byte [][] arr = new byte[n][m];
			boolean [][][][] visited = new boolean[n][m][4][3];
			int start_row = 0;
			int start_col = 0;
			int end_row = 0;
			int end_col = 0;
			for (int i = 0; i < n; i++) {
				String temp = in.next();
				for (int j = 0; j < m; j++) {
					for (int k = 0; k < 4; k++) {
						visited[i][j][k][0] = false;
						visited[i][j][k][1] = false;
						visited[i][j][k][2] = false;
					}
					if (temp.charAt(j) == '.') {
						arr[i][j] = 0;
					} else if (temp.charAt(j) == '*') {
						arr[i][j] = 1;
					} else if (temp.charAt(j) == 'S') {
						start_row = i;
						start_col = j;
						arr[i][j] = 0;
					} else if (temp.charAt(j) == 'T') {
						arr[i][j] = 0;
						end_row = i;
						end_col = j;
					}
				}
			}
			Queue<Node> queue = new LinkedList<Node>();
			queue.add(new Node(start_row, start_col, 2, NORTH));
			queue.add(new Node(start_row, start_col, 2, EAST));
			queue.add(new Node(start_row, start_col, 2, SOUTH));
			queue.add(new Node(start_row, start_col, 2, WEST));
			for (int i = 0; i < 4; i++) {
				visited[start_row][start_col][i][2] = true;
			}
			boolean check = false;
			while (!queue.isEmpty()) {
				if (check) break;
				int count = queue.size();
				if (check) break;
				while (count != 0) {
					Node cur = queue.poll();
					for (int i = 0; i < 4; i++) {
						if (i == NORTH) {
							if (cur.row > 0 && arr[cur.row - 1][cur.col] == 0) {
								if (cur.dir == i && !visited[cur.row - 1][cur.col][NORTH][cur.turn]) {
									queue.add(new Node(cur.row - 1, cur.col, cur.turn, cur.dir));
									visited[cur.row - 1][cur.col][NORTH][cur.turn] = true;
								} else if (cur.turn > 0 && !visited[cur.row - 1][cur.col][NORTH][cur.turn - 1]) {
									queue.add(new Node(cur.row - 1, cur.col, cur.turn - 1, i));
									visited[cur.row - 1][cur.col][NORTH][cur.turn - 1] = true;
								}
							}
						} else if (i == EAST) {
							if (cur.col < m - 1 && arr[cur.row][cur.col + 1] == 0) {
								if (cur.dir == i && !visited[cur.row][cur.col + 1][EAST][cur.turn]) {
									queue.add(new Node(cur.row, cur.col + 1, cur.turn, cur.dir));
									visited[cur.row][cur.col + 1][EAST][cur.turn] = true;
								} else if (cur.turn > 0 && !visited[cur.row][cur.col + 1][EAST][cur.turn - 1]) {
									queue.add(new Node(cur.row, cur.col + 1, cur.turn - 1, i));
									visited[cur.row][cur.col + 1][EAST][cur.turn - 1] = true;
								}
							}
						} else if (i == SOUTH) {
							if (cur.row < n - 1 && arr[cur.row + 1][cur.col] == 0) {
								if (cur.dir == i && !visited[cur.row + 1][cur.col][SOUTH][cur.turn]) {
									queue.add(new Node(cur.row + 1, cur.col, cur.turn, cur.dir));
									visited[cur.row + 1][cur.col][SOUTH][cur.turn] = true;
								} else if (cur.turn > 0 && !visited[cur.row + 1][cur.col][SOUTH][cur.turn - 1]) {
									queue.add(new Node(cur.row + 1, cur.col, cur.turn - 1, i));
									visited[cur.row + 1][cur.col][SOUTH][cur.turn - 1] = true;
								}
							}
						} else {
							if (cur.col > 0 && arr[cur.row][cur.col - 1] == 0) {
								if (cur.dir == i && !visited[cur.row][cur.col - 1][WEST][cur.turn]) {
									queue.add(new Node(cur.row, cur.col - 1, cur.turn, cur.dir));
									visited[cur.row][cur.col - 1][WEST][cur.turn] = true;
								} else if (cur.turn > 0 && !visited[cur.row][cur.col - 1][WEST][cur.turn - 1]) {
									queue.add(new Node(cur.row, cur.col - 1, cur.turn - 1, i));
									visited[cur.row][cur.col - 1][WEST][cur.turn - 1] = true;
								}
							}
						}
					}
					count--;
				}
			}

			if (check) {
				out.println("YES");
			} else {
				out.print("NO");
			}
		}

		class Node {
			int row;
			int col;
			int turn;
			int dir;
			Node(int _row, int _col, int _turn, int _dir) {
				row = _row;
				col = _col;
				turn = _turn;
				dir = _dir;
			}
		}

	}

	static class InputReader {
		BufferedReader reader;
		StringTokenizer tokenizer;

		InputReader(InputStream inputStream) {
			reader = new BufferedReader(new InputStreamReader(inputStream));
		}

		public String next() {
			while (tokenizer == null || !tokenizer.hasMoreElements()) {
				try {
					tokenizer = new StringTokenizer(reader.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return tokenizer.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}
	}
}

