    static int R, C;
    static int[] dx = new int[] { -1, 1, 0, 0 };
    static int[] dy = new int[] { 0, 0, -1, 1 };
    static boolean visited[][];
    static int[][][][] memo;

    public static void main(String[] args) throws IOException {

        Scanner sc = new Scanner(System.in);

        R = sc.nextInt();
        C = sc.nextInt();
        grid = new char[R][C];
        visited = new boolean[R][C];
        memo = new int[R][C][4][3];
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                for (int j2 = 0; j2 < 4; j2++)
                    Arrays.fill(memo[i][j][j2], -1);

            }

        }
        int mx = 0;
        int my = 0;
        for (int i = 0; i < R; i++) {
            String s = sc.next();
            for (int j = 0; j < C; j++) {
                grid[i][j] = s.charAt(j);
                if (grid[i][j] == 'S') {
                    mx = i;
                    my = j;
                }
            }
        }

        boolean ans = search(mx, my, 0, 0) | search(mx, my, 1, 0) | search(mx, my, 2, 0) | search(mx, my, 3, 0);
        if (ans)
            System.out.println("YES");
        else
            System.out.println("NO");

    }

    static boolean search(int r, int c, int dir, int t) {

        if (t > 2 || !valid(r, c) || grid[r][c] == '*')
            return false;

        if (memo[r][c][dir][t] != -1)
            if (memo[r][c][dir][t] == 1)
                return true;
            else
                return false;
        if (grid[r][c] == 'T') {
            return true;
        }
        boolean leave = false;
        visited[r][c] = true;
        if (dir == 2) {
            if (valid(r, c - 1) && !visited[r][c - 1])
                leave = search(r, c - 1, 2, t);
        } else if (dir == 3) {
            if (valid(r, c + 1) && !visited[r][c + 1])
                leave = search(r, c + 1, 3, t);
        } else if (dir == 0) {
            if (valid(r - 1, c) && !visited[r - 1][c])
                leave = search(r - 1, c, 0, t);
        } else {
            if (valid(r + 1, c) && !visited[r + 1][c])
                leave = search(r + 1, c, dir, t);
        }

        boolean take = false;
        for (int i = 0; i < dx.length; i++) {
            int x = r + dx[i];
            int y = c + dy[i];
            if (valid(x, y) && !visited[x][y] && grid[x][y] != '*') {
                if (i == 0 && dir != 0) 
                    take |= search(x, y, 0, t + 1);
                else if (i == 1 && dir != 1) 
                    take |= search(x, y, 1, t + 1);
                else if (i == 2 && dir != 2)
                    take |= search(x, y, 2, t + 1);
                else if (i == 3 && dir != 3) 
                    take |= search(x, y, 3, t + 1);

            }

        }
        visited[r][c] = false;
        if (take | leave)
            memo[r][c][dir][t] = 1;
        else
            memo[r][c][dir][t] = 0;

        return take | leave;

    }

    static boolean valid(int i, int j) {
        return i != -1 && j != -1 && i != R && j != C;
    }

