import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;


public class TinkoffB {
    public static void main(String[] args) {
        FS scan = new FS(System.in);
        int R = scan.nextInt(), C = scan.nextInt();
        char[][] mat = new char[R][C];

        int r1 = 0, c1 = 0, r2 = 0, c2 = 0;
        for (int i = 0; i < R; i++) {
            String line = scan.next();
            for (int j = 0; j < C; j++) {          // fixed: was j <= C
                mat[i][j] = line.charAt(j);
                if (mat[i][j] == 'S') {
                    r1 = i;
                    c1 = j;
                }
                if (mat[i][j] == 'T') {
                    r2 = i;
                    c2 = j;
                }
            }
        }

        int[][][] memo = new int[2][R][C];
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < R; j++) {
                Arrays.fill(memo[i][j], 10);
            }
        }

        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(r1); q.add(c1); q.add(0);
        q.add(r1); q.add(c1); q.add(1);

        int[][] dr = {{0, 0}, {-1, 1}};
        int[][] dc = {{-1, 1}, {0, 0}};

        memo[0][r1][c1] = 0;
        memo[1][r1][c1] = 0;

        while (!q.isEmpty()) {
            int r = q.pollFirst();
            int c = q.pollFirst();
            int d = q.pollFirst();

            for (int k = 0; k < 2; k++) {
                int rr = r + dr[d][k];
                int cc = c + dc[d][k];
                if (rr < 0 || rr >= R || cc < 0 || cc >= C || mat[rr][cc] == '*')
                    continue;
                if (memo[d][rr][cc] > memo[d][r][c]) {
                    memo[d][rr][cc] = memo[d][r][c];
                    q.addLast(rr);
                    q.addLast(cc);
                    q.addLast(d);
                }
            }
            if (memo[d][r][c] < 2) {
                for (int k = 0; k < 2; k++) {
                    int rr = r + dr[d ^ 1][k];
                    int cc = c + dc[d ^ 1][k];
                    if (rr < 0 || rr >= R || cc < 0 || cc >= C || mat[rr][cc] == '*')
                        continue;
                    if (memo[d ^ 1][rr][cc] > memo[d][r][c] + 1) {
                        memo[d ^ 1][rr][cc] = memo[d][r][c] + 1;
                        q.addLast(rr);
                        q.addLast(cc);
                        q.addLast(d ^ 1);
                    }
                }
            }
        }

        System.out.println(
                (memo[0][r2][c2] <= 2 || memo[1][r2][c2] <= 2) ? "YES" : "NO");
    }

    private static class FS {
        BufferedReader br;
        StringTokenizer st;

        public FS(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

