        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < m; j++) {
                char c = line.charAt(j);
                if (c == 'S') {
                    start[0] = i;
                    start[1] = j;
                } else if (c == 'T') {
                    end[0] = i;
                    end[1] = j;
                    v[i][j] = true;
                } else if (c == '.') {
                    v[i][j] = true;
                }
            }
        }

        LinkedList<int[]> q = new LinkedList<>();
        q.add(start);
        turns[start[0]][start[1]] = -1;
        while (!q.isEmpty()) {
            int[] focus = q.remove();
            int dist = turns[focus[0]][focus[1]];

            // down
            for (int step = 1; focus[0] + step < n && v[focus[0] + step][focus[1]] && turns[focus[0] + step][focus[1]] > dist; step++) {
                turns[focus[0] + step][focus[1]] = dist + 1;
                q.add(new int[]{focus[0] + step, focus[1]});
            }
            // up
            for (int step = 1; focus[0] - step >= 0 && v[focus[0] - step][focus[1]] && turns[focus[0] - step][focus[1]] > dist; step++) {
                turns[focus[0] - step][focus[1]] = dist + 1;
                q.add(new int[]{focus[0] - step, focus[1]});
            }
            // right
            for (int step = 1; focus[1] + step < m && v[focus[0]][focus[1] + step] && turns[focus[0]][focus[1] + step] > dist; step++) {
                turns[focus[0]][focus[1] + step] = dist + 1;
                q.add(new int[]{focus[0], focus[1] + step});
            }
            // left
            for (int step = 1; focus[1] - step >= 0 && v[focus[0]][focus[1] - step] && turns[focus[0]][focus[1] - step] > dist; step++) {
                turns[focus[0]][focus[1] - step] = dist + 1;
                q.add(new int[]{focus[0], focus[1] - step});
            }
        }

        if (turns[end[0]][end[1]] >= 0 && turns[end[0]][end[1]] <= 2) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }
}

