		FastScanner scan = new FastScanner();
		PrintWriter out = new PrintWriter(System.out);
		int n = scan.nextInt(), m = scan.nextInt();
		char[][] grid = new char[n][m];
		int sx = -1, sy = -1, ex = -1, ey = -1;
		for(int i = 0; i < n; i++){
			grid[i] = scan.next().toCharArray();
			for(int j = 0; j < m; j++) 
				if(grid[i][j] == 'S') {
					sx = i;
					sy = j;
				} else if(grid[i][j] == 'T'){
					ex = i;
					ey = j;
				}
		}
		boolean[][][][] v = new boolean[n][m][4][3];
		ArrayDeque<N> q = new ArrayDeque<N>();
		int[] d = {0, 0, -1, 1};
		for(int i = 0; i < 4; i++){
			q.add(new N(sx, sy, i, 2));
			v[sx][sy][i][2] = true;
		}
		boolean good = false;
		while(!q.isEmpty()){ 
			N now = q.poll();
			int x = now.x, y = now.y, dir = now.d, t = now.t;
			if (x == ex && y == ey) {
				good = true;
				break;
			}
			for(int i = 0; i < 4; i++){
				int dx = x+d[i], dy = y+d[3-i];
				if(i == dir){
					if(inBounds(dx, dy, n, m) && grid[dx][dy] != '*' && !v[dx][dy][i][t]){
						v[dx][dy][i][t] = true;
						q.add(new N(dx, dy, i, t));
					}
				} else if(t > 0 && inBounds(dx, dy, n, m) && grid[dx][dy] != '*' && !v[dx][dy][i][t-1]){
					v[dx][dy][i][t-1] = true;
					q.add(new N(dx, dy, i, t-1));
				}
			}
		}
		out.println(good?"YES":"NO");
		out.close();
	}

	static boolean inBounds(int x, int y, int n, int m){return x >= 0 && x < n && y >= 0 && y < m;}

	static class N {
		int x, y, d, t;
		public N(int a, int b, int c, int e){
			x = a;
			y = b;
			d = c;
			t = e;
		}
	}

	static class FastScanner {
		BufferedReader br;
		StringTokenizer st;

		public FastScanner() {
			try	{
				br = new BufferedReader(new InputStreamReader(System.in));
				st = new StringTokenizer(br.readLine());
			} catch (Exception e){e.printStackTrace();}
		}

		public String next() {
			if (st.hasMoreTokens())	return st.nextToken();
			try {st = new StringTokenizer(br.readLine());}
			catch (Exception e) {e.printStackTrace();}
			return st.nextToken();
		}

		public int nextInt() {return Integer.parseInt(next());}

		public long nextLong() {return Long.parseLong(next());}

		public double nextDouble() {return Double.parseDouble(next());}

		public String nextLine() {
			String line = "";
			if(st.hasMoreTokens()) line = st.nextToken();
			else try {return br.readLine();}catch(IOException e){e.printStackTrace();}
			while(st.hasMoreTokens()) line += " "+st.nextToken();
			return line;
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for(int i = 0; i < n; i++) a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n){
			long[] a = new long[n];
			for(int i = 0; i < n; i++) a[i] = nextLong();
			return a;
		}

		public double[] nextDoubleArray(int n){
			double[] a = new double[n];
			for(int i = 0; i < n; i++) a[i] = nextDouble();
			return a;
		}

		public char[][] nextGrid(int n, int m){
			char[][] grid = new char[n][m];
			for(int i = 0; i < n; i++) grid[i] = next().toCharArray();
			return grid;
		}
	}
}

