public class B_CF {
    static boolean b = false;
    public static void main(String[] args) {
        FastScanner56 fs = new FastScanner56();
        PrintWriter pw = new PrintWriter(System.out);

        int t = 1;
        for (int tc = 0; tc < t; tc++) {
            int n = fs.ni();
            int m = fs.ni();
            char[][] matrix = new char[n][m];
            for (int i = 0; i < n; i++) {
                String s = fs.next();
                for (int j = 0; j < m; j++) {
                    matrix[i][j] = s.charAt(j);
                }
            }
            boolean[][][][] seen = new boolean[n][m][4][3];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (matrix[i][j]!='S') continue;
                    recur(i,j,0,2,matrix,seen);
                    recur(i,j,1,2,matrix,seen);
                    recur(i,j,2,2,matrix,seen);
                    recur(i,j,3,2,matrix,seen);

                }
            }
            if (b) {
                pw.println("YES");
            } else {
                pw.println("NO");
            }
        }

        pw.close();
    }
    public static void recur(int i, int j, int d, int k, char[][] matrix, boolean[][][][] seen) {
        if (i<0 || j<0 || i>=matrix.length || j>=matrix[i].length || matrix[i][j]=='*') return;
        if (matrix[i][j] == 'T') b = true;
        if (seen[i][j][d][k]) return;
        seen[i][j][d][k] = true;
        for (int g = 0; g < 4; g++) {
            if (k>0) {
                recur(i,j,g,k-1,matrix,seen);
            }
        }
        if (d==0) {
            recur(i+1,j,d,k,matrix,seen);
        } else if (d==1) {
            recur(i,j+1,d,k,matrix,seen);
        } else if (d==2) {
            recur(i-1,j,d,k,matrix,seen);
        } else {
            recur(i,j-1,d,k,matrix,seen);
        }
    }
}

