        Scanner in = new Scanner();
        int n = in.nextInt();
        int m = in.nextInt();
        String[] data = new String[n];
        int stX = -1;
        int stY = -1;
        for (int i = 0; i < n; i++) {
            data[i] = in.next();
            for (int j = 0; j < m; j++) {
                if (data[i].charAt(j) == 'S') {
                    stX = i;
                    stY = j;
                }
            }
        }
        dp = new boolean[n][m][4][3];
        boolean re = false;
        for (int i = 0; i < 4 && !re; i++) {
            re |= cal(stX, stY, i, 2, data);
        }
        if (re) {
            out.println("YES");
        } else {
            out.println("NO");
        }
        out.close();
    }

    static boolean cal(int x, int y, int dir, int left, String[] data) {
        if (left < 0) {
            return false;
        }
        if (data[x].charAt(y) == 'T') {
            return true;
        }

        if (dp[x][y][dir][left]) {
            return false;
        }
        dp[x][y][dir][left] = true;
        boolean re = false;
        for (int i = 0; i < 4; i++) {
            int nxtX = X[i] + x;
            int nxtY = Y[i] + y;
            if (nxtX >= 0 && nxtY >= 0 && nxtX < data.length && nxtY < data[0].length() && data[nxtX].charAt(nxtY) != '*') {
                re |= cal(nxtX, nxtY, i, left - (dir == i ? 0 : 1), data);
            }
        }
        return re;
    }


    public static int[] KMP(String val) {
        int i = 0;
        int j = -1;
        int[] result = new int[val.length() + 1];
        result[0] = -1;
        while (i < val.length()) {
            while (j >= 0 && val.charAt(j) != val.charAt(i)) {
                j = result[j];
            }
            j++;
            i++;
            result[i] = j;
        }
        return result;

    }

    public static boolean nextPerm(int[] data) {
        int i = data.length - 1;
        while (i > 0 && data[i] < data[i - 1]) {
            i--;
        }
        if (i == 0) {
            return false;
        }
        int j = data.length - 1;
        while (data[j] < data[i - 1]) {
            j--;
        }
        int temp = data[i - 1];
        data[i - 1] = data[j];
        data[j] = temp;
        Arrays.sort(data, i, data.length);
        return true;
    }

    public static int digit(long n) {
        int result = 0;
        while (n > 0) {
            n /= 10;
            result++;
        }
        return result;
    }

    public static double dist(long a, long b, long x, long y) {
        double val = (b - a) * (b - a) + (x - y) * (x - y);
        val = Math.sqrt(val);
        double other = x * x + a * a;
        other = Math.sqrt(other);
        return val + other;

    }

    public static class Point implements Comparable<Point> {

        int x, y;

        public Point(int start, int end) {
            this.x = start;
            this.y = end;
        }

        @Override
        public int hashCode() {
            int hash = 5;
            hash = 47 * hash + this.x;
            hash = 47 * hash + this.y;
            return hash;
        }

        @Override
        public boolean equals(Object obj) {
            if (obj == null) {
                return false;
            }
            if (getClass() != obj.getClass()) {
                return false;
            }
            final Point other = (Point) obj;
            if (this.x != other.x) {
                return false;
            }
            if (this.y != other.y) {
                return false;
            }
            return true;
        }

        @Override
        public int compareTo(Point o) {
            return Integer.compare(x, o.x);
        }
    }

    public static class FT {

        long[] data;

        FT(int n) {
            data = new long[n];
        }

        public void update(int index, long value) {
            while (index < data.length) {
                data[index] += value;
                index += (index & (-index));
            }
        }

        public long get(int index) {
            long result = 0;
            while (index > 0) {
                result += data[index];
                index -= (index & (-index));
            }
            return result;

        }
    }

    public static long gcd(long a, long b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }

    public static long pow(long a, long b, long MOD) {
        if (b == 0) {
            return 1;
        }
        if (b == 1) {
            return a;
        }
        long val = pow(a, b / 2, MOD);
        if (b % 2 == 0) {
            return val * val % MOD;
        } else {
            return val * (val * a % MOD) % MOD;

        }
    }

    static class Scanner {

        BufferedReader br;
        StringTokenizer st;

        public Scanner() throws FileNotFoundException {

            br = new BufferedReader(new InputStreamReader(System.in));

        }

        public String next() {

            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    throw new RuntimeException();
                }
            }
            return st.nextToken();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            st = null;
            try {
                return br.readLine();
            } catch (Exception e) {
                throw new RuntimeException();
            }
        }

        public boolean endLine() {
            try {
                String next = br.readLine();
                while (next != null && next.trim().isEmpty()) {
                    next = br.readLine();
                }
                if (next == null) {
                    return true;
                }
                st = new StringTokenizer(next);
                return st.hasMoreTokens();
            } catch (Exception e) {
                throw new RuntimeException();
            }
        }
    }
}

import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Scanner;

public class B793 {

	final int HOR = 0, VER = 1;
	final int oo = 987654321;

	class State {
		int dir;
		int row, col;
		State(int r, int c, int d) {
			row = r;
			col = c;
			dir = d;
		}
	}

	public void solve(Scanner in, PrintWriter out) {
		int n = in.nextInt();
		int m = in.nextInt();
		boolean[][] grid = new boolean[n][m];
		int sr = -1, sc = -1;
		int er = -1, ec = -1;
		for(int r = 0; r < n; ++r) {
			char[] row = in.next().toCharArray();
			for(int c = 0; c < m; ++c) {
				grid[r][c] = row[c] != '*';
				if(row[c] == 'S') {
					sr = r;
					sc = c;
				}
				if(row[c] == 'T') {
					er = r;
					ec = c;
				}
			}
		}
		int[][][] dp = new int[2][n][m];

		for(int i = 0; i < 2; ++i) {
			for(int j = 0; j < n; ++j) {
				Arrays.fill(dp[i][j], oo);
			}
		}

		Deque<State> q = new ArrayDeque<>();
		dp[HOR][sr][sc] = dp[VER][sr][sc] = 0;

		q.addLast(new State(sr, sc, HOR));
		q.addLast(new State(sr, sc, VER));

		while(!q.isEmpty()) {
			State top = q.removeFirst();
			int dir = top.dir;
			int r = top.row;
			int c = top.col;

			if(r > 0 && grid[r - 1][c]) {
				if(dp[VER][r - 1][c] > dp[dir][r][c] + (dir == VER ? 0 : 1)) {
					dp[VER][r - 1][c] = dp[dir][r][c] + (dir == VER ? 0 : 1);
					q.addLast(new State(r - 1, c, VER));
				}
			}

			if(r + 1 < n && grid[r + 1][c]) {
				if(dp[VER][r + 1][c] > dp[dir][r][c] + (dir == VER ? 0 : 1)) {
					dp[VER][r + 1][c] = dp[dir][r][c] + (dir == VER ? 0 : 1);
					q.addLast(new State(r + 1, c, VER));
				}
			}

			if(c > 0 && grid[r][c - 1]) {
				if(dp[HOR][r][c - 1] > dp[dir][r][c] + (dir == HOR ? 0 : 1)) {
					dp[HOR][r][c - 1] = dp[dir][r][c] + (dir == HOR ? 0 : 1);
					q.addLast(new State(r, c - 1, HOR));
				}
			}

			if(c + 1 < m && grid[r][c + 1]) {
				if(dp[HOR][r][c + 1] > dp[dir][r][c] + (dir == HOR ? 0 : 1)) {
					dp[HOR][r][c + 1] = dp[dir][r][c] + (dir == HOR ? 0 : 1);
					q.addLast(new State(r, c + 1, HOR));
				}
			}
		}

		int ans = Math.min(dp[0][er][ec], dp[1][er][ec]);

		if(ans > 2) {
			out.println("NO");
		} else {
			out.println("YES");
		}

	}

 public static void main(String[] args) {
     Scanner in = new Scanner(System.in);
     PrintWriter out = new PrintWriter(System.out);

     new B793().solve(in, out);

     in.close();
     out.close();
 }
}

