import java.util.Deque;
import java.util.Scanner;

public class B793 {

	final int HOR = 0, VER = 1;
	final int oo = 987654321;

	class State {
		int dir;
		int row, col;
		State(int r, int c, int d) {
			row = r;
			col = c;
			dir = d;
		}
	}

	public void solve(Scanner in, PrintWriter out) {
		int n = in.nextInt();
		int m = in.nextInt();
		boolean[][] grid = new boolean[n][m];
		int sr = -1, sc = -1;
		int er = -1, ec = -1;
		for(int r = 0; r < n; ++r) {
			char[] row = in.next().toCharArray();
			for(int c = 0; c < m; ++c) {
				grid[r][c] = row[c] != '*';
				if(row[c] == 'S') {
					sr = r;
					sc = c;
				}
				if(row[c] == 'T') {
					er = r;
					ec = c;
				}
			}
		}
		int[][][] dp = new int[2][n][m];

		for(int i = 0; i < 2; ++i) {
			for(int j = 0; j < n; ++j) {
				Arrays.fill(dp[i][j], oo);
			}
		}

		Deque<State> q = new ArrayDeque<>();
		dp[HOR][sr][sc] = dp[VER][sr][sc] = 0;

		q.addLast(new State(sr, sc, HOR));
		q.addLast(new State(sr, sc, VER));

		while(!q.isEmpty()) {
			State top = q.removeFirst();
			int dir = top.dir;
			int r = top.row;
			int c = top.col;

			// up
			if(r > 0 && grid[r - 1][c]) {
				int add = (r == sr && c == sc) ? 0 : (dir == VER ? 0 : 1);
				if(dp[VER][r - 1][c] > dp[dir][r][c] + add) {
					dp[VER][r - 1][c] = dp[dir][r][c] + add;
					q.addLast(new State(r - 1, c, VER));
				}
			}

			// down
			if(r + 1 < n && grid[r + 1][c]) {
				int add = (r == sr && c == sc) ? 0 : (dir == VER ? 0 : 1);
				if(dp[VER][r + 1][c] > dp[dir][r][c] + add) {
					dp[VER][r + 1][c] = dp[dir][r][c] + add;
					q.addLast(new State(r + 1, c, VER));
				}
			}

			// left
			if(c > 0 && grid[r][c - 1]) {
				int add = (r == sr && c == sc) ? 0 : (dir == HOR ? 0 : 1);
				if(dp[HOR][r][c - 1] > dp[dir][r][c] + add) {
					dp[HOR][r][c - 1] = dp[dir][r][c] + add;
					q.addLast(new State(r, c - 1, HOR));
				}
			}

			// right
			if(c + 1 < m && grid[r][c + 1]) {
				int add = (r == sr && c == sc) ? 0 : (dir == HOR ? 0 : 1);
				if(dp[HOR][r][c + 1] > dp[dir][r][c] + add) {
					dp[HOR][r][c + 1] = dp[dir][r][c] + add;
					q.addLast(new State(r, c + 1, HOR));
				}
			}
		}

		int ans = Math.min(dp[0][er][ec], dp[1][er][ec]);

		if(ans > 2) {
			out.println("NO");
		} else {
			out.println("YES");
		}

	}

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);
		new B793().solve(in, out);
		in.close();
		out.close();
	}
}

