public class Ideone
{
    static int n, m;
    static char[][] mat = new char[1005][1005];
    static int[][][] visited = new int[1005][1005][4];
    static int[] move_x = {0, 0, 1, -1};
    static int[] move_y = {1, -1, 0, 0};
    static String ans;

    static void dfs(int x, int y, int dir, int turn){
        if(x<0 || x>=n || y<0 || y>=m || mat[x][y]=='*' || turn>2)return;
        if(mat[x][y]=='T'){
            ans = "YES"; return;
        }
        if(visited[x][y][dir]<=turn) return;

        visited[x][y][dir] = turn;

        for(int k=0; k<4; k++){
            if(k!=dir || turn==-1){
                dfs(x+move_x[k], y+move_y[k], k, turn+1);

            }
            else dfs(x+move_x[k], y+move_y[k], dir, turn); 
        }

    }

    public static void main (String[] args)
    {
        Scanner in = new Scanner(System.in);
        n = in.nextInt();
        m = in.nextInt();
        int start_x=0, start_y=0;

        for(int i=0; i<n; i++){
            String s = in.next();
            for(int j=0; j<m; j++){
                mat[i][j] = s.charAt(j);
                if(mat[i][j]=='S'){
                    start_x = i; start_y = j;
                }
            }
        }

        for(int i=0; i<n; i++){
            for(int j=0; j<m; j++){
                for(int k=0; k<4; k++)
                    visited[i][j][k] = 1005;
            }
        }
        ans = "NO";
        dfs(start_x, start_y, 0, -1);
        System.out.println(ans);
    }
}

