public class h {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int n = fs.nextInt(), m = fs.nextInt();
        char[][] g = new char[n][m];
        for(int i = 0; i < n; i++) g[i] = fs.nextCharArray();
        State start = null;
        for(int i =0 ; i <n; i++) {
            for(int j = 0; j < m; j++) {
                if(g[i][j] == 'S') {
                    start = new State(i, j);
                    break;
                }
            }
        }
        boolean res = BFS(g, 0, start);
        if(!res) res |= BFS(g, 1, start);
        if(!res) res |= BFS(g, 2, start);
        if(!res) res |= BFS(g, 3, start);

        out.println(res ? "YES" : "NO");

        out.close();
    }

    static boolean BFS (char[][] a, int dir, State start) {
        ArrayDeque<State> bfs = new ArrayDeque<>();
        start.dir = dir;
        bfs.add(start);
        int n = a.length, m = a[0].length;
        int[] dx = {1, -1, 0, 0}, dy = {0, 0, -1, 1};
        boolean[][][] V = new boolean[n][m][4];
        V[start.i][start.j][dir] = true;
        while(!bfs.isEmpty()) {
            State now = bfs.pollFirst();
            if(a[now.i][now.j] == 'T') {
                if(now.change <= 2) return true;
                continue;
            }
            for(int i= 0; i < 4; i++) {
                int nx = now.i + dx[i], ny = now.j + dy[i];
                if(!good(nx, ny, n, m)) continue;
                if(a[nx][ny] == '*') continue;
                if(V[nx][ny][i]) continue;
                if(a[nx][ny] != 'T') V[nx][ny][i] = true;
                State add = new State(nx, ny);
                add.change = now.change;
                add.dir = i;
                if(i != now.dir) {
                    add.change++;
                    bfs.addLast(add);
                } else {
                    bfs.addFirst(add);
                }
            }
        }
        return false;
    }

    static boolean good (int i , int n, int j, int m) {
        return i >= 0 && j >= 0 && i < n && j < m;
    }

    static class State {
        int i, j, change, dir;
        State (int a, int b) {
            i = a; j = b;
            change = 0;
            dir = -1;
        }
    }

