        for (int i = 0; i < row; i++) {
            grid[i] = scan.next();
            for (int j = 0; j < col; j++) {
                if (grid[i].charAt(j) == 'S') {
                    x = i;
                    y = j;
                    break;
                }
            }
        }
        System.out.println(res[solve(x, y) ? 1 : 0]);
        scan.close();
    }

    static boolean solve(int startX, int startY) {
        Queue q = new LinkedList();
        for (int i = 0; i < 4; i++) {
            q.add(new Data(startX, startY, i));
            dp[startX][startY][i] = 0;
        }
        while (!q.isEmpty()) {
            Data data = (Data) q.element();
            q.remove();
            if (grid[data.x].charAt(data.y) == 'T' && dp[data.x][data.y][data.d] <= 2)
                return true;
            for (int i = 0; i < 4; i++) {
                int nx = data.x + xx[i];
                int ny = data.y + yy[i];
                if (nx < 0 || nx >= row || ny < 0 || ny >= col) {
                    continue;
                }
                if (grid[nx].charAt(ny) == '*') {
                    continue;
                }
                int cost = dp[data.x][data.y][data.d] + (i != data.d ? 1 : 0);
                if (dp[nx][ny][i] <= cost) {
                    continue;
                }
                dp[nx][ny][i] = cost;
                q.add(new Data(nx, ny, i));
            }
        }
        return false;
    }
}

