public class CF793B_2 {
    public static int mat[][], vis[][][][], n, m, xx[], yy[], sx, sy, dx, dy, vis2[][];
    public static void main(String[] args)throws Exception {
        InputReader in = new InputReader(System.in);
        PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out));

        xx = new int[]{0, 1, 0,-1};
        yy = new int[]{1, 0,-1, 0};

        n = in.nextInt();
        m = in.nextInt();
        mat = new int[n+1][m+1];
        vis = new int[n+1][m+1][5][5];

        for(int i = 0; i<= n; i++){
            for(int j = 0; j<= m; j++){
                for(int k = 0; k < 5; k++){
                    Arrays.fill(vis[i][j][k], -1);
                }
            }
        }

        for(int i = 1; i <= n; i++){
            String str = in.next();
            for(int j = 1; j <= m; j++){
                char s = str.charAt(j-1);
                if(s == 'S'){
                    sx = i; sy = j;
                }
                else if(s == 'T'){
                    dx = i; dy = j;
                }
                else if(s == '*') continue;
                mat[i][j] = 1;
            }
        }

        int ans = solve(sx, sy, 4, 0);

        if(ans <= 3) pw.println("YES");
        else pw.println("NO");

        pw.close();
    }

    static boolean isValid(int x, int y){
        return x >= 1 && x <= n && y >= 1 && y <= m && mat[x][y] == 1 ;
    }

    static int solve(int x, int y, int last, int sum){
        if(sum > 3) return (int)1e8;
        if(x == dx && y == dy) return sum;

        if(vis[x][y][last][sum] != -1) return vis[x][y][last][sum];
        int min = (int)1e9;

        for(int i = 0; i < 4; i++){
            int px = x+xx[i], py = y+yy[i];
            if(isValid(px, py)){
                if(i == last) min = Math.min(min, solve(px, py, i, sum));
                else min = Math.min(min, solve(px, py, i, sum+1));
            }
        }
        return vis[x][y][last][sum] = min;
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        public String next()throws Exception {
            while (tokenizer == null || !tokenizer.hasMoreTokens())
                tokenizer = new StringTokenizer(reader.readLine());
            return tokenizer.nextToken();
        }

        public String nextLine()throws Exception {
            String line = null;
            tokenizer = null;
            line =  reader.readLine();
            return line;
        }

        public int nextInt()throws Exception {
            return Integer.parseInt(next());
        }

        public double nextDouble() throws Exception{
            return Double.parseDouble(next());
        }

        public long nextLong()throws Exception {
            return Long.parseLong(next());
        }

    }
