    static boolean isValid(int x, int y){
        return x >= 1 && x <= n && y >= 1 && y <= m && mat[x][y] == 1 ;
    }

    static int solve(int x, int y, int last, int sum){
        if(sum > 3) return (int)1e8;
        if(x == dx && y == dy) return sum;

        if(vis[x][y][last][sum] != -1) return vis[x][y][last][sum];
        int min = (int)1e9;

        for(int i = 0; i < 4; i++){
            int px = x+xx[i], py = y + yy[i];
            if(isValid(px, py)){
                if(i == last) min = Math.min(min, solve(px, py, i, sum));
                else min = Math.min(min, solve(px, py, i, sum+1));
            }
        }
        return vis[x][y][last][sum] = min;
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

