public class Main {
  public static void main(String[] args) {
    InputStream inputStream = System.in;
    OutputStream outputStream = System.out;
    InputReader in = new InputReader(inputStream);
    PrintWriter out = new PrintWriter(outputStream);
    TaskB solver = new TaskB();
    solver.solve(1, in, out);
    out.close();
  }

  static class TaskB {
    private boolean[][][][] dp;
    private boolean[][][][] visited;
    int[] x = {0, 1, 0, -1};
    int[] y = {1, 0, -1, 0};

    public void solve(int testNumber, InputReader in, PrintWriter out) {
      int n = in.nextInt();
      int m = in.nextInt();
      String[] grid = new String[n];
      for (int i = 0; i < n; i++) {
        grid[i] = in.next();
      }
      dp = new boolean[n][m][4][3];
      visited = new boolean[n][m][4][3];
      int sti = -1;
      int stj = -1;
      for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
          if (grid[i].charAt(j) == 'S') {
            sti = i;
            stj = j;
            break;
          }
        }
      }
      for (int i = 0; i < 4; i++) {
        if (isPos(sti, stj, grid, i, 2)) {
          out.println("YES");
          return;
        }
      }
      out.println("NO");
    }

    private boolean isPos(int sti, int stj, String[] grid, int currentDir, int turnLeft) {
      if (grid[sti].charAt(stj) == '*') {
        return false;
      }
      if (turnLeft < 0) {
        return false;
      }
      if (grid[sti].charAt(stj) == 'T') {
        return true;
      }
      if (visited[sti][stj][currentDir][turnLeft]) {
        return dp[sti][stj][currentDir][turnLeft];
      }
      boolean isPos = false;
      for (int i = 0; i < x.length; i++) {
        int ni = sti + x[i];
        int nj = stj + y[i];
        if (ni >= 0 && ni < grid.length && nj >= 0 && nj < grid[0].length()) {
          if (i == currentDir) {
            isPos |= isPos(ni, nj, grid, currentDir, turnLeft);
          } else {
            isPos |= isPos(ni, nj, grid, i, turnLeft - 1);
          }
        }
        if (isPos) break;
      }
      visited[sti][stj][currentDir][turnLeft] = true;
      dp[sti][stj][currentDir][turnLeft] = isPos;
      return isPos;
    }
  }

  static class InputReader {
    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;

    public InputReader(InputStream stream) {
      this.stream = stream;
    }

    public int read() {
      if (numChars == -1)
        throw new InputMismatchException();
      if (curChar >= numChars) {
        curChar = 0;
        try {
          numChars = stream.read(buf);
        } catch (IOException e) {
          throw new InputMismatchException();
        }
        if (numChars <= 0)
          return -1;
      }
      return buf[curChar++];
    }

    public int readInt() {
      int c = read();
      while (isSpaceChar(c))
        c = read();
      int sgn = 1;
      if (c == '-') {
        sgn = -1;
        c = read();
      }
      int res = 0;
      do {
        if (c < '0' || c > '9')
          throw new InputMismatchException();
        res *= 10;
        res += c - '0';
        c = read();
      } while (!isSpaceChar(c));
      return res * sgn;
    }

    public String readString() {
      int c = read();
      while (isSpaceChar(c))
        c = read();
      StringBuffer res = new StringBuffer();
      do {
        res.appendCodePoint(c);
        c = read();
      } while (!isSpaceChar(c));
      return res.toString();
    }

    private boolean isSpaceChar(int c) {
      return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public int nextInt() {
      return readInt();
    }

    public String next() {
      return readString();
    }
  }
}

