public class Main {
  public static IO in;
  public static PrintWriter out;

  static void init_io(String filename) throws Exception {
    if (filename.equals("")) {
      in = new IO(System.in);
      out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)), true);
    } else {
      in = new IO(new FileInputStream(filename + ".in"));
      out = new PrintWriter(new BufferedWriter(new FileWriter(filename + ".out")), true);
    }
  }

  final static long mod = 1000000007;

  static int n, m;

  static int pack(int r, int c, int dir, int nturns) {
      return r * m * 12 + c * 1 + dir * 3 + nturns;
  }

  static int pack2(int pos, int dir, int nturns) {
      return pos * 12 + dir * 3 + nturns;
  }

  static int dr[] = new int[]{0, 0, -1, 1};
  static int dc[] = new int[]{1, -1, 0, 0};

  static boolean valid(int r, int c) {
      return r >= 0 && r < n && c >= 0 && c < m;
  }

  static void solve(int tc) throws Exception {
    n = in.nint();
    m = in.nint();

    boolean[][] grid = new boolean[n][m];
    boolean[] vis = new boolean[n * m * 12];

    int spos = 0, tpos = 0;
    for (int i = 0; i < n; i++) {
        String s = in.nstr();
        for (int j = 0; j < m; j++) {
            if (s.charAt(j) == 'S') spos = i * m + j;
            if (s.charAt(j) == 'T') tpos = i * m + j;
            grid[i][j] = (s.charAt(j) != '*');
        }
    }

    int[] queue = new int[15000000];

    int qstart = 0, qend = 0;

    for (int i = 0; i < 4; i++) {
        queue[qend++] = pack2(spos, i, 0);
    }

    while (qstart < qend) {
        int val = queue[qstart++];

        // decode state encoded with pack2: pos*12 + dir*3 + nturns
        int pos = val;
        int r = pos / m;
        int c = pos % m;
        int dir = (val % 12) / 3;      // dir * 3 is part of the remainder
        int nturns = val % 3;

        if (r * m + c == tpos) {
            out.println("YES\n");
            return;
        }

        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            int nt = nturns;
            if (d != dir) ++nt;

            if (nt <= 2 && valid(nr, nc) && grid[nr][nc]) {
                int nstate = pack2(nr * m + nc, d, nt);
                if (!vis[nstate]) {
                    vis[nstate] = true;
                    queue[qend++] = nstate;
                }
            }
        }
    }

    out.println("NO\n");
  }

  public static void main(String[] _unused_) throws Exception {
    init_io("");

    int t = 1;
    for (int tc = 0; tc < t; tc++) {
      solve(tc);
    }
  }

  // other helper methods left unchanged
  static long minv(long v) {
    return mpow(v, mod - 2);
  }

  static long mpow(long base, long exp) {
    long res = 1;
    while (exp > 0) {
      if ((exp & 1) == 1) {
        res = (res * base) % mod;
      }
      base = (base * base) % mod;
      exp >>= 1;
    }
    return res;
  }

  static int gcd(int x, int y) {
    if (x == 0) return y;
    if (y == 0) return x;
    return gcd(y % x, x);
  }
}

