import java.io.*;
import java.util.*;

public class B {

	BufferedReader in;
	StringTokenizer st;
	PrintWriter out;

	String next() throws IOException {
		while (st == null || st.hasMoreTokens())
			st = new StringTokenizer(in.readLine());
		return st.nextToken();
	}

	int nextInt() throws Exception {
		return Integer.parseInt(next());
	}

	long nextLong() throws Exception {
		return Long.parseLong(next());
	}

	double nextDouble() throws Exception {
		return Double.parseDouble(next());
	}

	int rowcnt[][];
	int colcnt[][];

	void solve() throws Exception {
		int n = nextInt();
		int m = nextInt();
		int t[][] = new int[n][m];
		int xt = -1;
		int yt = -1;
		int xs = -1;
		int ys = -1;
		for (int i = 0; i < n; i++) {
			String s = next();
			for (int j = 0; j < m; j++) {
				if (s.charAt(j) == '*')
					t[i][j] = 1;
				if (s.charAt(j) == 'S') {
					xs = i;
					ys = j;
				}
				if (s.charAt(j) == 'T') {
					xt = i;
					yt = j;
				}
			}
		}

		rowcnt = new int[n][m];
		colcnt = new int[m][n];

		for (int i = 0; i < n; i++) {
			rowcnt[i][0] = t[i][0];
			for (int j = 1; j < m; j++)
				rowcnt[i][j] = rowcnt[i][j - 1] + t[i][j];
		}

		for (int i = 0; i < m; i++) {
			colcnt[i][0] = t[0][i];
			for (int j = 1; j < n; j++)
				colcnt[i][j] = colcnt[i][j - 1] + t[j][i];
		}

		int dx[] = { 1, -1, 0, 0 };
		int dy[] = { 0, 0, 1, -1 };

		for (int ds = 0; ds < 4; ds++)
			for (int ls = 0; ls <= 1000; ls++) {
				int x1 = xs + dx[ds] * ls;
				int y1 = ys + dy[ds] * ls;
				if (x1 >= 0 && y1 >= 0 && x1 < n && y1 < m && cango(xs, ys, x1, y1))
					for (int dt = 0; dt < 4; dt++)
						for (int lt = 0; lt <= 1000; lt++) {
							int x2 = xt + dx[dt] * lt;
							int y2 = yt + dy[dt] * lt;
							if (x2 >= 0 && y2 >= 0 && x2 < n && y2 < m && cango(xt, yt, x2, y2))
								if (cango(x1, y1, x2, y2)) {
									out.println("YES");
									System.err.println(x1 + " " + y1 + " => " + x2 + " " + y2);
									return;
								}
						}
			}

		out.println("NO");
	}

	/*  Fixed obstacle‑checking routine  */
	private boolean cango(int x1, int y1, int x2, int y2) {
		/* make sure (x2,y2) is not “before” (x1,y1) */
		if (x2 < x1) {
			int t = x2;
			x2 = x1;
			x1 = t;
		}
		if (y2 < y1) {
			int t = y2;
			y2 = y1;
			y1 = t;
		}

		/* horizontal segment */
		if (x1 == x2) {
			int obstacles = rowcnt[x1][y2];
			if (y1 > 0) obstacles -= rowcnt[x1][y1 - 1];
			return obstacles == 0;
		}
		/* vertical segment */
		if (y1 == y2) {
			int obstacles = colcnt[y1][x2];
			if (x1 > 0) obstacles -= colcnt[y1][x1 - 1];
			return obstacles == 0;
		}
		return false;
	}

	void run() {
		try {
			Locale.setDefault(Locale.US);
			in = new BufferedReader(new InputStreamReader(System.in));
			out = new PrintWriter(new OutputStreamWriter(System.out));
			solve();
			out.close();
		} catch (Exception e) {
			e.printStackTrace();
			System.exit(1);
		}
	}

	public static void main(String[] args) {
		new B().run();
	}
}

