class Five_In_a_Row{

    public boolean finalVerdict(){
        boolean [] allVerdicts = new boolean[4];

        allVerdicts[0] = checkAllHorizontalSegments();
        allVerdicts[1] = checkAllVerticalSegments();
        allVerdicts[2] = checkAllPrimarySegments();
        allVerdicts[3] = checkAllSecondrySegments();

        return allVerdicts[0]||allVerdicts[1]||
                allVerdicts[2]||allVerdicts[3];
    }

    public boolean checkAllPrimarySegments(){
        for (int i = 0; i <= grid.length - segLength; i++) {
            for (int j = 0; j <= grid.length - segLength; j++) {
                if (helpPrimary(i, j)) {
                    return true;
                }
            }
        }
        return false;
    }

    public boolean checkAllSecondrySegments(){
        for (int i = 0; i <= grid.length - segLength; i++) {
            for (int j = segLength - 1; j < grid.length; j++) {
                if (helpSecondry(i, j)) {
                    return true;
                }
            }
        }
        return false;
    }

    public boolean checkAllHorizontalSegments(){
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j <= grid.length - segLength; j++) {
                if (helpHorizontal(i, j)) {
                    return true;
                }
            }
        }
        return false;
    }

    public boolean checkAllVerticalSegments(){
        for (int j = 0; j < grid.length; j++) {
            for (int i = 0; i <= grid.length - segLength; i++) {
                if (helpVertical(i, j)) {
                    return true;
                }
            }
        }
        return false;
    }

    public boolean helpPrimary(int rowX,int colX){
        int crossCount = 0,dotCount = 0;
        for (int x=(0-1);x<=segLength-1;++x){
            if(this.grid[x+rowX][x+colX] == 'X')
                ++crossCount;
            else if (this.grid[x+rowX][x+colX] == '.')
                ++dotCount;
        }
        return crossCount == 4 && dotCount == 1;
    }

    public boolean helpSecondry(int rowX,int colX){
        int crossCount = 0,dotCount = 0;
        for (int x=0;x<=segLength-1;++x){
            if(this.grid[x+rowX][colX-x] == 'X')
                ++crossCount;
            else if (this.grid[x+rowX][colX-x] == '.')
                ++dotCount;
        }
        return crossCount == 4 && dotCount == 1;
    }

    public boolean helpHorizontal(int rowX,int startX){
        int crossCount = 0,dotCount = 0;
        for (int x=startX;x<=startX+segLength-1;++x){
            if(this.grid[rowX][x] == 'X')
                ++crossCount;
            else if (this.grid[rowX][x] == '.')
                ++dotCount;
        }
        return crossCount == 4 && dotCount == 1;
    }

    public boolean helpVertical(int colX,int startX){
        int crossCount = 0,dotCount = 0;
        for (int x=startX;x<=startX+segLength-1;++x){
            if(this.grid[x][colX] == 'X')
                ++crossCount;
            else if (this.grid[x][colX] == '.')
                ++dotCount;
        }
        return crossCount == 4 && dotCount == 1;
    }

    public void loadGrid(){
        String inpStr = "";
        for (int i = 0;i<grid.length;++i){
            inpStr = Main.read.next();
            for (int j = 0;j<inpStr.length();++j){
              this.grid[i][j] =  inpStr.charAt(j); 
            }
        }
    }

    private char [][] grid = new char [10][10];
    private int segLength = 5;
}

