        for (int i = 0;i<grid.length;++i){
            for (int j = 0;j<=segLength;++j){
                if (helpHorizontal(i,j))
                    return true;
            }
        }
        return false;
    }

    public boolean checkAllVerticalSegments(){
        for (int i = 0;i<=segLength;++i){
            for (int j = 0;j<=segLength;++j){
                if (helpVertical(j,i))
                    return true;
            }
        }
        return false;
    }

