public class Main {
    static class Solver {
        private final static int SIZE = 10;

        private static int[] dr = {0, 1, 1, 1};
        private static int[] dc = {1, 0, 1, -1};

        public String solve() {
            Scanner in = new Scanner(System.in);

            char str[][] = new char[SIZE][SIZE];
            for (int i = 0; i < SIZE; ++i) {
                String tmp = in.next();
                for (int j = 0; j < SIZE; ++j) {
                    str[i][j] = tmp.charAt(j);
                }
            }

            if (check(str)) {
                return "YES";
            }

            for (int i = 0; i < SIZE; ++i) {
                for (int j = 0; j < SIZE; ++j) {
                    char save = str[i][j];
                    if (save != '.') continue;
                    str[i][j] = 'X';
                    if (check(str)) {          // <-- fixed condition
                        return "YES";
                    }
                    str[i][j] = save;
                }
            }
            return "NO";
        }

        private boolean check(char[][] str) {
            for (int i = 0; i < SIZE; ++i) {
                for (int j = 0; j < SIZE; ++j) {
                    for (int d = 0; d < 4; ++d) {
                        int k;
                        for (k = 0; k < 5; ++k) {
                            int r = i + k * dr[d];
                            int c = j + k * dc[d];

                            if (!valid(r, c) || str[r][c] != 'X') {
                                break;
                            }
                        }
                        if (k == 5) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private boolean valid(int r, int c) {
            return r >= 0 && r < SIZE && c >= 0 && c < SIZE;
        }
    }

    public static void main(String[] args) {
        System.out.println(new Solver().solve());
    }
}

