    }

    static boolean checkHorizontal(int iCurrent) {
        for (int counter = 0; counter <= 5; counter++) {
            boolean found = true;
            for (int j = counter; j < counter + 5 && found; j++) {
                if (grid[iCurrent][j] != 1) {
                    found = false;
                }
            }
            if (found) {
                return true;
            }
        }
        return false;
    }

    static boolean checkVertical(int jCurrent) {
        for (int counter = 0; counter <= 5; counter++) {
            boolean found = true;
            for (int i = counter; i < counter + 5 && found; i++) {
                if (grid[i][jCurrent] != 1) {
                    found = false;
                }
            }
            if (found) {
                return true;
            }
        }
        return false;
    }

    static boolean checkDiagonalLeft(int iCurrent, int jCurrent) {

        while (iCurrent != 0 && jCurrent != 0) {
            iCurrent--;
            jCurrent--;
        }

        while (iCurrent + 5 - 1 < 10 && jCurrent + 5 - 1 < 10) {
            boolean found = true;
            for (int i = 0; i < 5 && found; i++) {
                if (grid[iCurrent + i][jCurrent + i] != 1) {
                    found = false;
                }
            }
            if (found) {
                return true;
            }
            iCurrent++;
            jCurrent++;
        }

        return false;
    }

    static boolean checkDiagonalRight(int iCurrent, int jCurrent) {

        while (iCurrent != 0 && jCurrent != 10 - 1) {
            iCurrent--;
            jCurrent++;
        }

        while (iCurrent + 5 - 1 < 10 && jCurrent - 5 + 1 >= 0) {
            boolean found = true;
            for (int i = 0; i < 5; i++) {
                // *** Fixed: reject only cells that are NOT 'X' (value 1) ***
                if (grid[iCurrent + i][jCurrent - i] != 1) {
                    found = false;
                }
            }
            if (found) {
                return true;
            }
            iCurrent++;
            jCurrent--;
        }

        return false;
    }

