public class Main2 {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[][] field = new int[10][10];
        for (int i = 0; i < 10; i++) {
            String s = sc.next();
            for (int j = 0; j < 10; j++) {
                char c = s.charAt(j);
                if (c == '.') {
                    field[i][j] = 2;          // empty
                } else if (c == 'X') {
                    field[i][j] = 1;          // cross
                } else if (c == 'O') {
                    field[i][j] = 0;          // nought
                }
            }
        }

        boolean found = false;
        for (int i = 0; i < 10; i++) {
            for (int j = 0; j < 10; j++) {
                if (field[i][j] == 2 && pos(field, i, j)) {
                    found = true;
                }
            }
        }
        System.out.println(found ? "YES" : "NO");
    }

    /** Returns true if placing an 'X' at (i,j) creates a line of at least 5 X's. */
    static boolean pos(int[][] field, int i, int j) {
        if (field[i][j] != 2) {          // only empty cells are considered
            return false;
        }

        // four directions: right, down, down‑right, down‑left
        int[] dx = {0, 1, 1, 1};
        int[] dy = {1, 0, 1, -1};

        for (int d = 0; d < 4; d++) {
            int cnt = 1;   // the newly placed X

            // positive direction
            for (int step = 1; step < 5; step++) {
                int ni = i + step * dx[d];
                int nj = j + step * dy[d];
                if (ni < 0 || ni >= 10 || nj < 0 || nj >= 10) break;
                if (field[ni][nj] != 1) break;   // not an existing X
                cnt++;
                if (cnt >= 5) return true;
            }

            // negative direction
            for (int step = 1; step < 5; step++) {
                int ni = i - step * dx[d];
                int nj = j - step * dy[d];
                if (ni < 0 || ni >= 10 || nj < 0 || nj >= 10) break;
                if (field[ni][nj] != 1) break;
                cnt++;
                if (cnt >= 5) return true;
            }
        }
        return false;
    }
}

