    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[][] field = new int[10][10];
        for(int i = 0; i < 10; i++) {
            String s = sc.next();
            for(int j = 0; j < 10; j++) {
                char c = s.charAt(j);
                if(c == '.') {
                    field[i][j] = 2;
                } else if(c == 'X') field[i][j] = 1;
                // 'O' stays 0, but it is never used directly in the checks
            }
        }
        boolean pos = false;
        for(int i = 0; i < 10; i++) {
            for(int j = 0; j < 10; j++) {
                if(pos(field, i, j)) pos = true;
            }
        }
        if(pos) System.out.println("YES");
        else System.out.println("NO");
    }

    static boolean pos(int[][] field, int i, int j) {
        boolean pos = false;

        // vertical, looking forward (downwards)
        if(i <= 5) {
            int a = 0;
            int b = 0;
            for(int k = i; k < i+5; k++) {
                if(field[k][j] == 1) a++;
                if(field[k][j] == 2) b++;
            }
            if(b == 1 && a == 4) pos = true;
            if(a == 5) pos = true;
        }

        // vertical, looking backward (upwards)
        if(i >= 4) {
            int a = 0;
            int b = 0;
            for(int k = i-4; k <= i; k++) {
                if(field[k][j] == 1) a++;
                if(field[k][j] == 2) b++;
            }
            if(b == 1 && a == 4) pos = true;
            if(a == 5) pos = true;
        }

        // horizontal, looking forward (right)
        if(j <= 5) {
            int a = 0;
            int b = 0;
            for(int k = j; k < j+5; k++) {
                if(field[i][k] == 1) a++;
                if(field[i][k] == 2) b++;
            }
            if(b == 1 && a == 4) pos = true;
            if(a == 5) pos = true;
        }

        // horizontal, looking backward (left)
        if(j >= 4) {
            int a = 0;
            int b = 0;
            for(int k = j-4; k <= j; k++) {
                if(field[i][k] == 1) a++;
                if(field[i][k] == 2) b++;
            }
            if(b == 1 && a == 4) pos = true;
            if(a == 5) pos = true;
        }

        // main diagonal (top‑left to bottom‑right), looking forward (down‑right)
        if(i <= 5 && j <= 5) {
            int a = 0;
            int b = 0;
            for(int k = 0; k < 5; k++) {
                if(field[i+k][j+k] == 1) a++;
                if(field[i+k][j+k] == 2) b++;
            }
            if(b == 1 && a == 4) pos = true;
            if(a == 5) pos = true;
        }

        // main diagonal, looking backward (up‑left)
        if(i >= 4 && j >= 4) {
            int a = 0;
            int b = 0;
            for(int k = 0; k < 5; k++) {
                if(field[i-k][j-k] == 1) a++;
                if(field[i-k][j-k] == 2) b++;
            }
            if(b == 1 && a == 4) pos = true;
            if(a == 5) pos = true;
        }

        // anti‑diagonal (top‑right to bottom‑left), looking forward (up‑right)
        if(i <= 5 && j >= 4) {
            int a = 0;
            int b = 0;
            for(int k = 0; k < 5; k++) {
                if(field[i+k][j-k] == 1) a++;
                if(field[i+k][j-k] == 2) b++;
            }
            if(b == 1 && a == 4) pos = true;
            if(a == 5) pos = true;
        }

        // anti‑diagonal, looking backward (down‑left)
        if(i >= 4 && j <= 5) {
            int a = 0;
            int b = 0;
            for(int k = 0; k < 5; k++) {
                if(field[i-k][j+k] == 1) a++;
                if(field[i-k][j+k] == 2) b++;
            }
            if(b == 1 && a == 4) pos = true;
            if(a == 5) pos = true;
        }

        return pos;
    }
}

