import java.io.*;
import java.util.*;

public class Task {
    public static void main(String[] args) throws IOException {
        FScanner fs = new FScanner(new InputStreamReader(System.in));
        char[][] cube = new char[10][];
        for (int i = 0; i < 10; i++)
            cube[i] = fs.nextLine().toCharArray();

        for (int i = 0; i < 10; i++)
            for (int j = 0; j < 10; j++)
                if (cube[i][j] == '.') {
                    if (check(cube, i, j)) {
                        System.out.println("YES");
                        System.exit(0);
                    }
                }
        System.out.println("NO");
    }

    private static boolean check(char[][] cube, int q, int w) {
        // horizontal
        int left = 0;
        for (int i = w - 1; i >= 0 && cube[q][i] == 'X'; i--) left++;
        int right = 0;
        for (int i = w + 1; i < 10 && cube[q][i] == 'X'; i++) right++;
        if (left + right + 1 >= 5) return true;

        // vertical
        int up = 0;
        for (int i = q - 1; i >= 0 && cube[i][w] == 'X'; i--) up++;
        int down = 0;
        for (int i = q + 1; i < 10 && cube[i][w] == 'X'; i++) down++;
        if (up + down + 1 >= 5) return true;

        // diagonal \ (top‑left → bottom‑right)
        int diag1Up = 0;
        for (int i = q - 1, j = w - 1; i >= 0 && j >= 0 && cube[i][j] == 'X'; i--, j--) diag1Up++;
        int diag1Down = 0;
        for (int i = q + 1, j = w + 1; i < 10 && j < 10 && cube[i][j] == 'X'; i++, j++) diag1Down++;
        if (diag1Up + diag1Down + 1 >= 5) return true;

        // diagonal / (top‑right → bottom‑left)
        int diag2Up = 0;
        for (int i = q - 1, j = w + 1; i >= 0 && j < 10 && cube[i][j] == 'X'; i--, j++) diag2Up++;
        int diag2Down = 0;
        for (int i = q + 1, j = w - 1; i < 10 && j >= 0 && cube[i][j] == 'X'; i++, j++) diag2Down++;
        if (diag2Up + diag2Down + 1 >= 5) return true;

        return false;
    }
}

