class Algs {
    public static int[] Z_f(char[] s) {
        int[] zf = new int[s.length];
        zf[0] = -1;
        int l = 0, r = 0;
        for (int i = 1; i < s.length; i++) {
            if (i > r) {
                int g = i;
                while (g < s.length && s[g] == s[g - i]) g++;
                if (g == i) continue;
                l = i; r = g - 1; zf[i] = g - i;
            } else {
                if (zf[i - l] <= r - i + 1) zf[i] = zf[i - l];
                else {
                    int g = r + 1;
                    while (g < s.length && s[g] == s[g - i]) g++;
                    if (g == r + 1) zf[i] = r - i + 1;
                    else {
                        zf[i] = g - i; r = g - 1; l = i;
                    }
                }
            }
        }
        return zf;
    }
}
class FScanner {
    BufferedReader br;
    StringTokenizer st;
    FScanner(InputStreamReader isr) { br = new BufferedReader(isr); }
    String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String s = br.readLine();
            if (s == null) return null;
            st = new StringTokenizer(s);
        }
        return st.nextToken();
    }
    int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
    long nextLong() throws IOException { return Long.parseLong(nextToken()); }
    double nextDouble() throws IOException { return Double.parseDouble(nextToken()); }
    String nextLine() throws IOException { return br.readLine(); }
    char nextChar() throws IOException { return (char) br.read(); }
}

