                            if (charArr[i-j+4][j-4] == 'X') {
                                xcount--;
                            }
                        }
                    }
                }
            }
        }

        for (int i = 0; i < n-4; i++) {
            xcount = 0;
            steps = 0;
            for (int j = 0; j < n-i; j++) {
                if (charArr[n-1-j][i+j] == 'O') {
