            for (int j=1 ; j<=10 ; j++) {
                char c = s.charAt(j-1);
                if (c == 'X') board[i][j] = 1;
                else if (c == 'O') board[i][j] = -1;
            }
        }

        int xCount, dotCount;
        for (int r=1 ; r<=10 ; r++) {
            xCount = 0;
            dotCount = 0;
            for (int c=1 ; c<=5 ; c++) {
                if (board[r][c] == 1) xCount++;
                else if (board[r][c] == 0) dotCount++;
            }
            if (xCount + dotCount == 5 && dotCount<2) {
                System.out.println("YES");
                return;
            }
            for (int c=6 ; c<=10 ; c++) {
                if (board[r][c] == 1) xCount++;
                else if (board[r][c] == 0) dotCount++;

                if (board[r][c-5] == 1) xCount--;
                else if (board[r][c-5] == 0) dotCount--;

                if (xCount + dotCount == 5 && dotCount<2) {
                    System.out.println("YES");
                    return;
                }
            }
