            for (int r=1 ; r<=5 ; r++) {
                if (board[r][c] == 1) xCount++;
                else if (board[r][c] == 0) dotCount++;
            }
            if (xCount + dotCount == 5 && dotCount<2) {
                System.out.println("YES");
                return;
            }
            for (int r=6 ; r<=10 ; r++) {
                if (board[r][c] == 1) xCount++;
                else if (board[r][c] == 0) dotCount++;
                if (board[r-5][c] == 1) xCount--;
                else if (board[r-5][c] == 0) dotCount--;

                if (xCount + dotCount == 5 && dotCount<2) {
                    System.out.println("YES");
                    return;
                }
