public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        B825 solver = new B825();
        solver.solve(1, in, out);
        out.close();
    }

    static class B825 {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            char[][] board = new char[10][10];
            for (int i = 0; i < 10; i++) {
                for (int j = 0; j < 10; j++) {
                    board[i][j] = in.nextCharacter();
                }
            }
            for (int x = 0; x < 10; x++) {
                for (int y = 0; y < 10; y++) {
                    boolean replaced = false;
                    if (board[x][y] == '.') {
                        board[x][y] = 'X';
                        replaced = true;
                        for (int i = 0; i < 6; i++) {
                            for (int j = 0; j < 6; j++) {
                                char[][] newBoard = new char[5][5];
                                for (int k = 0; k < 5; k++) {
                                    for (int l = 0; l < 5; l++) {
                                        newBoard[k][l] = board[i + k][j + l];
                                    }
                                }
                                if (solveHelper(newBoard)) {
                                    out.print("YES");
                                    return;
                                }
                            }
                        }
                    }
                    if (replaced) board[x][y] = '.';
                }
            }

            out.print("NO");

        }

        public boolean solveHelper(char[][] board) {
            boolean ok;
            for (int i = 0; i < 5; i++) {
                boolean vertical = true;
                boolean horizontal = true;
                for (int j = 0; j < 4; j++) {
                    if (board[i][j] != board[i][j + 1] || board[i][j] != 'X' || board[i][j + 1] != 'X') {
                        vertical = false;
                    }
                    if (board[j][i] != board[j + 1][i] || board[j][i] != 'X' || board[j + 1][i] != 'X') {
                        horizontal = false;
                    }
                }
                ok = horizontal || vertical;
                if (ok) return true;
            }
            boolean diagonal1 = true;
            boolean diagonal2 = true;
            for (int i = 0; i < 4; i++) {
                if (board[i][i] != board[i + 1][i + 1] || board[i][i] != 'X' || board[i + 1][i + 1] != 'X') {
                    diagonal1 = false;
                }
                if (board[4 - i][i] != board[3 - i][i + 1] || board[4 - i][i] != 'X' || board[3 - i][i + 1] != 'X') {
                    diagonal2 = false;
                }
            }
            return diagonal1 || diagonal2;
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public char nextCharacter() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            return (char) c;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

