    PrintWriter out;

    public void solve() {
        boolean win = false;
        String s[] = new String[10];
        for (int i = 0; i < 10; i++){
            s[i] = in.next();
        }

        for (int i = 0; i < 10; i++){
            for (int j = 0; j < 10; j++){
                if (s[i].charAt(j) == '.'){
                    int l = j;
                    int r = j;
                    while ((l-1 >= 0)&&(s[i].charAt(l-1) == 'X')){
                        l--;
                    }
                    while ((r+1 < 10)&&(s[i].charAt(r+1) == 'X')){
                        r++;
                    }
                    if (r-l >= 4){
                        win = true;
                    }
                }
            }
        }

        for (int i = 0; i < 10; i++){
            for (int j = 0; j < 10; j++){
                if (s[i].charAt(j) == '.'){
                    int u = i;
                    int d = i;
                    while (u-1 >= 0 && s[u-1].charAt(j) == 'X'){
                        u--;
                    }
                    while (d+1 < 10 && s[d+1].charAt(j) == 'X'){
                        d++;
                    }
                    if (d - u >= 4){
                        win = true;
                    }
                }
            }
        }

        for (int i = 0; i < 10; i++){
            for (int j = 0; j < 10; j++){
                if (s[i].charAt(j) == '.'){
                    int l1 = i;
                    int r1 = i;
                    int l2 = j;
                    int r2 = j;
                    while ((l1-1 >= 0)&&(l2-1 >= 0)&&(s[l1-1].charAt(l2-1) == 'X')){
                        l1--;
                        l2--;
                    }
                    while ((r1+1 < 10)&&(r2+1 < 10)&&(s[r1+1].charAt(r2+1) == 'X')){
                        r1++;
                        r2++;
                    }
                    if (r1-l1 >= 4){
                        win = true;
                    }
                }
            }
        }

        for (int i = 0; i < 10; i++){
            for (int j = 0; j < 10; j++){
                if (s[i].charAt(j) == '.'){
                    int l1 = i;
                    int r1 = i;
                    int l2 = j;
                    int r2 = j;
                    while ((l1-1 >= 0)&&(r2+1 < 10)&&(s[l1-1].charAt(r2+1) == 'X')){
                        l1--;
                        r2++;
                    }
                    while ((l2-1 >= 0)&&(r1+1 < 10)&&(s[r1+1].charAt(l2-1) == 'X')){
                        l2--;
                        r1++;
                    }
                    if (r1-l1 >= 4){
                        win = true;
                    }
                }
            }
        }

        if (win){
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    public void run() {
        in = new FastScanner();
        out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        solve();
        out.close();
    }

    class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    public static void main(String[] args) {
        new CFE_25_B().run();
    }
}

