		}

		for (int r = 0; r < 10; ++r) {
			for (int c = 0; c < 10; ++c) {
				for (int d = 0; d < DR.length; ++d) {
					char[] p = new char[5];
					for (int i = 0; i < 5; ++i) {
						int nr = r + i * DR[d];
						int nc = c + i * DC[d];
						if (nr < 10 && nc >= 0 && nc < 10) {
							p[i] = A[nr][nc];
