        System.out.println(game.canAliceWinInOneMove());

    }

    public String canAliceWinInOneMove(){

        for (int row = 0; row < 10; row++) {
            for (int column = 0; column < 10; column++) {

                if (checkFiveInColumn(playField, row, column) ||
                        checkFiveInRow(playField, row, column) ||
                        checkFiveInDiagonalLeft(playField, row, column) ||
                        checkFiveInDiagonalRight(playField, row, column)) {
                    return "YES";
                }
            }
        }

        return "NO";
    }

    private boolean checkFiveInRow(char[][] playField, int column, int row) {

        if ((column + 4) >= 10) {
            return false;
        }
        int count = 0;
        int i = column;
        for (int j = 0; j < 5; j++) {
            if (playField[row][i] == 'O') {
                return false;
            }
            if (playField[row][i] == 'X') {
                count++;
            }
            i++;
        }
        return count == 4;

    }

    private boolean checkFiveInColumn(char[][] playField, int column, int row) {

        if ((row + 4) >= 10) {
            return false;
        }
        int count = 0;
        int i = row;
        for (int j = 0; j < 5; j++) {
            if (playField[i][column] == 'O') {
                return false;
            }
            if (playField[i][column] == 'X') {
                count++;
            }
            i++;
        }
        return count == 4;
    }

    private boolean checkFiveInDiagonalRight(char[][] playField, int column, int row) {
        if ((column - 4) < 0 || (row + 4) >= 10) {
            return false;
        }

        int count = 0;
        for (int j = 0; j < 5; j++) {
            if (playField[row + j][column - j] == 'O') {
                return false;
            }
            if (playField[row + j][column - j] == 'X') {
                count++;
            }
        }

        return count == 4;
    }

    private boolean checkFiveInDiagonalLeft(char[][] playField, int column, int row) {
        if ((row + 4) >= 10 || (column + 4) >= 10) {
            return false;
        }

        int count = 0;
        for (int j = 0; j < 5; j++) {
            if (playField[row + j][column + j] == 'O') {
                return false;
            }
            if (playField[row + j][column + j] == 'X') {
                count++;
            }
        }
        return count == 4;

    }
}

