public class FiveInARow {

	public static boolean horizontal(char[][] table,int i,int j)
	{
		int limit = Math.min(10, j+5);
		int Xcount=0,dotcount=0;
		for(int k=j;k<limit;k++)
		{
			if(table[i][k]=='X')
				Xcount++;
			else if(table[i][k]=='.')
				dotcount++;
		}
		if(Xcount==4 && dotcount==1)
			return true;
		else
			return false;
	}

	public static boolean vertical(char[][] table,int i,int j)
	{
		int limit = Math.min(10, i+5);
		int Xcount=0,dotcount=0;
		for(int k=i;k<limit;k++)
		{
			if(table[k][j]=='X')
				Xcount++;
			else if(table[k][j]=='.')
				dotcount++;
		}
		if(Xcount==4 && dotcount==1)
			return true;
		else
			return false;
	}

	public static boolean diagonal(char[][] table,int i,int j)
	{
		int Xcount=0,dotcount=0;
		for(int k=0;i+k<Math.min(10, i+5) && j+k<Math.min(10, j+5);k++)
		{
			if(table[i+k][j+k]=='X')
				Xcount++;
			else if(table[i+k][j+k]=='.')
				dotcount++;
		}
		if(Xcount==4 && dotcount==1)
			return true;
		else
			return false;
	}

	public static boolean reverseDiagonal(char[][] table,int i,int j)
	{
		int Xcount=0,dotcount=0;
		for(int k=0;i+k<Math.min(10, i+5) && j-k>Math.max(-1, j-5);k++)
		{
			if(table[i+k][j-k]=='X')
				Xcount++;
			else if(table[i+k][j-k]=='.')
				dotcount++;
		}
		if(Xcount==4 && dotcount==1)
			return true;
		else
			return false;
	}

	public static void main(String[] args) throws NumberFormatException, IOException {
		InputStreamReader in = new InputStreamReader(System.in);

		BufferedReader br = new BufferedReader(in);
		PrintWriter out = new PrintWriter(System.out);
		char[][] table = new char[10][10];
		for(int i=0;i<10;i++)
			table[i] = br.readLine().toCharArray();
		for(int i=0;i<10;i++)
		{
			for(int j=0;j<10;j++)
			{
				if(table[i][j]=='.')
				{
					if(horizontal(table, i, j) || vertical(table, i, j) || diagonal(table, i, j) || reverseDiagonal(table, i, j))
					{
						System.out.print("YES");
						return;
					}
				}
			}
		}
		System.out.println("NO");
		out.close();
		br.close();
	}

	public static void debug(Object...obj) {
        System.err.println(Arrays.deepToString(obj));
    }
}

