			for(int j = 0; j < n; j++) if(g[i][j] == '.') { 
				g[i][j] = 'X';
				if(win(g)) {
					System.out.println("YES");
					return;
				}
				g[i][j] = '.';
			}
		}
		System.out.println("NO");
