	}

	boolean win(char[][] g) {
		int n = 10;
		for(int i = 0; i < n; i++) {
			for(int j = 0; j < n; j++) {
				if(i <= 5) {
					String str = "";
					for(int k = i; k < i+5; k++) str += g[k][j];
					if(str.equals("XXXXX")) return true;
				}
				if(j <= 5) {
					String str = "";
					for(int k = j; k < j+5; k++) str += g[i][k];
					if(str.equals("XXXXX")) return true;
				}
				if(i <= 5 && j <= 5) {
					String str = "";
					for(int k = 0; k < 5; k++) str += g[i+k][j+k];
					if(str.equals("XXXXX")) return true;
				}
				if(i <= 5 && j >= 4) {
					String str = "";
					for(int k = 0; k < 5; k++) str += g[i+k][j-k];
					if(str.equals("XXXXX")) return true;
				}
			}
		}
		return false;
	}

