        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        char GOOD = 'X';

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            char[][] tab = new char[10][];
            for (int i = 0; i < tab.length; i++) {
                tab[i] = in.next().toCharArray();
            }
            for (int row = 0; row < tab.length; row++) {
                for (int col = 0; col < tab[row].length; col++) {
                    if (tab[row][col] == '.') {
                        tab[row][col] = GOOD;
                        if (works(tab)) {
                            out.printLine("YES");
                            return;
                        }
                        tab[row][col] = '.';
                    }
                }
            }
            out.printLine("NO");
        }

        private boolean works(char[][] tab) {
            for (int row = 0; row < tab.length; row++) {
                for (int col = 0; col < tab[row].length; col++) {
                    if (tab[row][col] == GOOD) {
                        for (int dir = 0; dir < 8; dir++) {
                            int res = dfs(row, col, dir, tab);
                            if (res >= 5) {
                                return true;
                            }
                        }
                    }
                }
            }
            return false;
        }

        private int dfs(int row, int col, int dir, char[][] tab) {
            if (!MiscUtils.isValidCell(row, col, tab.length, tab[0].length)) {
                return 0;
            }
            if (!MiscUtils.isValidCell(row + MiscUtils.DX8[dir], col + MiscUtils.DY8[dir], tab.length, tab[0].length)
                    || tab[row + MiscUtils.DX8[dir]][col + MiscUtils.DY8[dir]] != GOOD) {
                return 0;
            }
            return 1 + dfs(row + MiscUtils.DX8[dir], col + MiscUtils.DY8[dir], dir, tab);
        }
    }
    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public String next() {
            return readString();
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);
        }
    }
    static class MiscUtils {
        public static final int[] DX8 = {1, 1, 1, 0, -1, -1, -1, 0};
        public static final int[] DY8 = {-1, 0, 1, 1, 0, -1, -1, -1};

        public static boolean isValidCell(int row, int column, int rowCount, int columnCount) {
            return row >= 0 && row < rowCount && column >= 0 && column < columnCount;
        }
    }
    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }
    }
}

