                        if (arr[l].charAt(k) == 'X') ul++;
                        else break;
                    }
                    // down‑right
                    for (int k = j + 1, l = i + 1; l < 10 && k < 10; l++, k++) {
                        if (arr[l].charAt(k) == 'X') dr++;
                        else break;
                    }
                    // up‑right
                    for (int k = j + 1, l = i - 1; l >= 0 && k < 10; l--, k++) {
                        if (arr[l].charAt(k) == 'X') ur++;
                        else break;
                    }
                    // down‑left
                    for (int k = j - 1, l = i + 1; l < 10 && k >= 0; l++, k--) {
                        if (arr[l].charAt(k) == 'X') dl++;
                        else break;
                    }

                    int yes = 0;
                    if (left + right >= 4) yes = 1;
                    if (up + down >= 4) yes = 1;
                    if (ul + dr >= 4) yes = 1;
                    if (dl + ur >= 4) yes = 1;

                    if (yes == 1) {
                        System.out.println("YES");
                        return;
                    }
                }
            }
        }
        System.out.println("NO");
    }
