class Solver {
    void solve(int test_number, InputReader in, PrintWriter out) throws IOException {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] a = new char[n][m];
        for (int i = 0; i < n; i++) {
            String s = in.next();
            for (int j = 0; j < m; j++) {
                a[i][j] = s.charAt(j);
            }
        }
        if (check1(a, n, m) || check2(a, n, m)) out.println("YES");
        else out.println("NO");
    }

    private boolean check1(char[][] a, int n, int m) {
        if (n % 3 != 0) return false;
        char op = a[0][0];
        boolean r, g, b;
        r = op == 'R';
        b = op == 'B';
        g = op == 'G';
        for (int i = 0; i < n / 3; i++) {
            for (int j = 0; j < m; j++) {
                if (a[i][j] != op) return false;
            }
        }
        if (op == a[n / 3][0]) return false;
        op = a[n / 3][0];
        if (op == 'R' && r) return false;
        if (op == 'B' && b) return false;
        if (op == 'G' && g) return false;
        if (!r) r = op == 'R';
        if (!b) b = op == 'B';
        if (!g) g = op == 'G';
        for (int i = n / 3; i < (2 * n) / 3; i++) {
            for (int j = 0; j < m; j++) {
                if (a[i][j] != op) return false;
            }
        }
        if (op == a[2 * n / 3][0]) return false;
        op = a[2 * n / 3][0];
        if (op == 'R' && r) return false;
        if (op == 'B' && b) return false;
        if (op == 'G' && g) return false;
        for (int i = (2 * n) / 3; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (a[i][j] != op) return false;
            }
        }
        return true;
    }

    private boolean check2(char[][] a, int n, int m) {
        if (m % 3 != 0) return false;
        char op = a[0][0];
        boolean r, g, b;
        r = op == 'R';
        b = op == 'B';
        g = op == 'G';
        for (int i = 0; i < m / 3; i++) {
            for (int j = 0; j < n; j++) {
                if (a[j][i] != op) return false;
            }
        }
        if (op != a[0][m / 3])
            op = a[0][m / 3];
        if (op == 'R' && r) return false;
        if (op == 'B' && b) return false;
        if (op == 'G' && g) return false;
        if (!r) r = op == 'R';
        if (!b) b = op == 'B';
        if (!g) g = op == 'G';
        for (int i = m / 3; i < 2 * m / 3; i++) {
            for (int j = 0; j < n; j++) {
                if (a[j][i] != op) return false;
            }
        }
        if (op == a[0][2 * m / 3]) return false;
        op = a[0][2 * m / 3];
        if (op == 'R' && r) return false;
        if (op == 'B' && b) return false;
        if (op == 'G' && g) return false;
        for (int i = (2 * m) / 3; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (a[j][i] != op) return false;
            }
        }
        return true;
    }
}

