            int B = 0;
            int G = 0;

            for (int i = 0; i < n; i++) {
                for (char ch : c[i]) {
                    if (ch == 'R') R++;
                    if (ch == 'B') B++;
                    if (ch == 'G') G++;
                }
            }

            if (R != G || R != B || R != (n * m) / 3 || (n * m) % 3 != 0) {
                w.println("NO");
                return;
            }

            int req = (n * m) / 3;


            if (req % m == 0) {
                int start = 0;
                int start1 = req / m;
                int start2 = 2 * start1;

                int count = 0;
                boolean temp_flag = true;
                for (int i = start; i < start1; i++) {
                    for (int j = 0; j < m; j++) {
                        if (c[i][j] == c[start][0])
                            count++;
                    }
                }

                temp_flag &= (count == req);

                count = 0;
                for (int i = start1; i < start2; i++) {
                    for (int j = 0; j < m; j++) {
                        if (c[i][j] == c[start1][0])
                            count++;
                    }
                }

                temp_flag &= (count == req);

                count = 0;
                for (int i = start2; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        if (c[i][j] == c[start2][0])
                            count++;
                    }
                }

                temp_flag &= (count == req);
                if (temp_flag) {
                    w.println("YES");
                    return;
                }
            }

            if (req % n == 0) {
                int start = 0;
                int start1 = req / n;
                int start2 = 2 * start1;

                int count = 0;
                boolean temp_flag = true;
                for (int i = start; i < start1; i++) {
                    for (int j = 0; j < n; j++) {
                        if (c[j][i] == c[0][start])
                            count++;
                    }
                }

                temp_flag &= (count == req);

                count = 0;
                for (int i = start1; i < start2; i++) {
                    for (int j = 0; j < n; j++) {
                        if (c[j][i] == c[0][start1])
