        String[] flag = new String[n];
        for (int i = 0; i < n; i++) {
            flag[i] = input.next();
        }
        if (n % 3 == 0) {
            if (checkH(flag, n, m)) {
                System.out.println("YES");
                return;
            }
        }
        if (m % 3 == 0) {
            if (checkV(flag, n, m)) {
                System.out.println("YES");
                return;
            }
        }
        System.out.println("NO");
    }

    static boolean checkH(String[] flag, int n, int m) {
        int h = n / 3;
        char color1 = flag[0].charAt(0);
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < m; j++) {
                if (flag[i].charAt(j) != color1) {
                    return false;
                }
            }
        }
        char color2 = flag[h].charAt(0);
        for (int i = h; i < 2 * h; i++) {
            for (int j = 0; j < m; j++) {
                if (flag[i].charAt(j) != color2) {
                    return false;
                }
            }
        }
        char color3 = flag[2 * h].charAt(0);
        for (int i = 2 * h; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (flag[i].charAt(j) != color3) {
                    return false;
                }
            }
        }
        if (color3 != color2 && color2 != color1 && color3 != color1) {
            return true;
        } else {
            return false;
        }
    }

    static boolean checkV(String[] flag, int n, int m) {
        int w = m / 3;
        char color1 = flag[0].charAt(0);
        for (int i = 0; i < w; i++) {
            for (int j = 0; j < n; j++) {
                if (flag[j].charAt(i) != color1) {
                    return false;
                }
            }
        }
        char color2 = flag[0].charAt(w);
        for (int i = w; i < 2 * w; i++) {
            for (int j = 0; j < n; j++) {
                if (flag[j].charAt(i) != color2) {
                    return false;
                }
            }
        }
        char color3 = flag[0].charAt(2 * w);
        for (int i = 2 * w; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (flag[j].charAt(i) != color3) {
                    return false;
                }
            }
        }
        if (color3 != color2 && color2 != color1 && color3 != color1) {
            return true;
        } else {
            return false;
        }
    }

