					&& check(flag, flag[h][0], h, 0, h * 2, m) && check(flag, flag[h * 2][0], h * 2, 0, n, m)) {
				out.println("YES");
				out.close();
				return;
			} else {
				wrong(out);
				return;
			}
		} else {
			if (m % 3 != 0 || w != m / 3) {
				wrong(out);
				return;
			}
			if (c != flag[0][w] && c != flag[0][w * 2] && flag[0][w] != flag[0][w * 2] && check(flag, c, 0, 0, n, w)
					&& check(flag, flag[0][w], 0, w, n, w * 2) && check(flag, flag[0][w * 2], 0, w * 2, n, m)) {
				out.println("YES");
				out.close();
				return;
			} else {
				wrong(out);
				return;
			}
		}

	}

	private static void wrong(PrintWriter out) {
		out.println("NO");
		out.close();
	}

	private static boolean check(char[][] flag, char c, int row, int col, int endRow, int endCol) {

		for (; row < endRow; row++)
			for (int j = col; j < endCol; j++)
				if (flag[row][j] != c)
					return false;
		return true;
	}

}

