        for (int i = 0; i < n; i++) {
            String input = br.readLine();
            for (int j = 0; j < m; j++) {
                flag[i][j] = input.charAt(j);
            }
        }

        int stripeWidth = 0;
        int stripeLength = 0;

        for (int i = 0; i < m; i++) {
            if (flag[0][i] != flag[0][0])
                break;
            ++stripeLength;
        }

        for (int i = 0; i < n; i++) {
            if (flag[i][0] != flag[0][0])
                break;
            ++stripeWidth;
        }

        if ((stripeLength != m && stripeWidth != n) || stripeLength * 3 * stripeWidth != m * n) {
