            for (int j = 0; j < m; j++) {
                flag[i][j] = input.charAt(j);
            }
        }

        int stripeWidth = 0;
        int stripeLength = 0;

        for (int i = 0; i < m; i++) {
            if (flag[0][i] != flag[0][0])
                break;
            ++stripeLength;
        }

        for (int i = 0; i < n; i++) {
            if (flag[i][0] != flag[0][0])
                break;
            ++stripeWidth;
        }

        if ((stripeLength != m && stripeWidth != n) || stripeLength * 3 * stripeWidth != m * n) {
            pw.println("NO");
            pw.close();
            return;
        }

        boolean seenR = false;
        boolean seenG = false;
        boolean seenB = false;

        for (int i = 0; i < 3; i++) {
            int currRow = stripeWidth == n ? 0 : stripeWidth * i;
            int currCol = stripeLength == m ? 0 : stripeLength * i;
            char currChar = flag[currRow][currCol];
            if (seenR && currChar == 'R' || seenG && currChar == 'G' || seenB && currChar == 'B') {
                pw.println("NO");
                pw.close();
                return;
            }
            seenR = seenR ? true : flag[currRow][currCol] == 'R';
            seenG = seenG ? true : flag[currRow][currCol] == 'G';
            seenB = seenB ? true : flag[currRow][currCol] == 'B';
            for (int row = currRow; row < (currRow + stripeWidth); row++) {
                for (int col = currCol; col < (currCol + stripeLength); col++) {
                    if (flag[row][col] != flag[currRow][currCol]) {
                        pw.println("NO");
                        pw.close();
                        return;
                    }
                }
            }
        }

        pw.println("YES");
        pw.close();
    }

