                    if (s[i].charAt(j) != second) {
                        flag1 = 1;
                    }
                }
            }
            for (int i = 2 * term; i < 3 * term && flag1 != 1; i++) {
                for (int j = 0; j < m && flag1 != 1; j++) {
                    if (s[i].charAt(j) != third) {
                        flag1 = 1;
                    }
                }
            }
        }
