class Scan {

    private final InputStream stream;
    private final byte EOF = -1, NL = '\n', DASH = '-', SPACE = ' ', R = '\r';
    private final byte[] buffer;
    private char[] charBuff;
    private int $index, $readCount;

    public Scan(InputStream stream, int bufferSize, int chrBuffSize) {
        this.stream = stream;
        this.buffer = new byte[bufferSize];
        this.charBuff = new char[chrBuffSize];
    }

    public Scan() {
        this(System.in, 1 << 16, 1 << 8);
    }

    private void skip(byte skp) throws IOException {
        if ($readCount == EOF) return;
        for (;;) {
            while ($index < buffer.length) {
                if (buffer[$index] > skp) return;
                $index++;
            }
            $readCount = stream.read(buffer);
            $index = 0;
            if ($readCount == EOF) return;
        }
    }

    private void quadCharSize() {
        char[] tmp = new char[charBuff.length << 2];
		System.arraycopy(charBuff, 0, tmp, 0, charBuff.length);
        charBuff = tmp;
    }

    public char[] nextArr() throws IOException {
        skip(SPACE);
        if ($readCount == EOF) return null;

        for (int i = 0;;) {
            while ($index < $readCount) {
                if (buffer[$index] > SPACE) {
                    if (i == charBuff.length) quadCharSize();
                    charBuff[i++] = (char)buffer[$index++];
                } else
                    return java.util.Arrays.copyOf(charBuff, i);
            }
            $readCount = stream.read(buffer);
            $index = 0;
            if ($readCount == EOF) return java.util.Arrays.copyOf(charBuff, i);
        }
    }

    public char[] nextLineArr() throws IOException {
        if ($readCount == EOF) return null;

        for (int i = 0;;) {
            while ($index < $readCount) {
                if (buffer[$index] == NL) {
                    $index++;
                    return java.util.Arrays.copyOf(charBuff, i);
                } else {
                    if (i == charBuff.length) quadCharSize();
                    charBuff[i++] = (char)buffer[$index++];
                }
            }
            $readCount = stream.read(buffer);
            $index = 0;
            if ($readCount == EOF) return java.util.Arrays.copyOf(charBuff, i);
        }
    }

    public int nextInt() throws IOException {
        skip(SPACE);
        if ($readCount == EOF) throw new IOException();

        int res = 0;
        boolean neg = false;
        if (buffer[$index] == DASH) {
            neg = true;
            $index++;
        }

        for (;;) {
            if ($index < $readCount) {
                if (buffer[$index] > SPACE) {
                    res = (res << 3) + (res << 1);
                    res += buffer[$index++] - '0';
                } else return neg ? -res : res;
            }
            $index = 0;
            $readCount = stream.read(buffer);
            if ($readCount == EOF) return neg ? -res : res;
        }
    }

    public long nextLong() throws IOException {
        skip(SPACE);
        if ($readCount == EOF) throw new IOException();

        long res = 0;
        boolean neg = false;
        if (buffer[$index] == DASH) {
            neg = true;
            $index++;
        }
        for (;;) {
            while ($index < $readCount) {
                if (buffer[$index] > SPACE) {
                    res = (res << 3) + (res << 1);
                    res += buffer[$index++] - '0';
                } else
                    return neg ? -res : res;
            }
            $index = 0;
            $readCount = stream.read(buffer);
            if ($readCount == EOF) return neg ? -res : res;
        }
    }
}

