@SuppressWarnings("unchecked")
public class P837B {

  boolean test(char [][] f) {
    int h = f.length, w = f[0].length, h3 = h / 3;

    if ((h % 3) != 0) {
      return false;
    }

    Set<Character> rgb = new HashSet();
    rgb.add('R'); rgb.add('G'); rgb.add('B');

    for (int i = 0; i < 3; i++) {
      char c = f[i * h3][0];

      if (!rgb.contains(c)) {
        return false;
      }

      for (int y = 0; y < h3; y++) {
        for (int x = 0; x < w; x++) {
          if (f[i * h3 + y][x] != c) {
            return false;
          }
        }
      }

      rgb.remove(c);
    }

    return (rgb.size() == 0);
  }

  char [][] transponse(char [][] f) {
    int h = f.length, w = f[0].length;
    char [][] t = new char [w][h];

    for (int i = 0; i < h; i++) {
      for (int j = 0; j < w; j++) {
        t[j][i] = f[i][j];
      }
    }

    return t;
  }

  public void run() throws Exception {
    int n = nextInt(), m = nextInt();
    char [][] f = new char [n][];
    for (int i = 0; i < n; f[i] = next().toCharArray(), i++);

    println((test(f) || test(transponse(f))) ? "YES" : "NO");
  }

  public static void main(String... args) throws Exception {
    br = new BufferedReader(new InputStreamReader(System.in));
    pw = new PrintWriter(new BufferedOutputStream(System.out));
    new P837B().run();
    br.close();
    pw.close();
    System.err.println("\n[Time : " + (System.currentTimeMillis() - startTime) + " ms]");
  }

