    static class TaskB {
        boolean v(String s) {
            return s.lastIndexOf('R') - s.indexOf('R') + 1 == s.length() / 3 &&
                    s.lastIndexOf('G') - s.indexOf('G') + 1 == s.length() / 3 &&
                    s.lastIndexOf('B') - s.indexOf('B') + 1 == s.length() / 3;
        }

        public void solve(int testNumber, FastReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] b = new char[n][m];
            for (int i = 0; i < n; i++) {
                b[i] = in.next().toCharArray();
            }
            boolean same = true;
            for (int i = 0; i < m; i++) if (b[0][i] != b[0][0]) same = false;
            if (same) {
                if (n % 3 != 0) {
                    out.print("NO");
                    return;
                }
                String c = "";
                for (int i = 0; i < n; i++) c += b[i][0];
                if (!v(c)) {
                    out.print("NO");
                    return;
                }
                for (int i = 0; i < m; i++) {
                    String d = "";
                    for (int j = 0; j < n; j++) d += b[j][i];
                    if (!c.equals(d)) {
                        out.print("NO");
                        return;
                    }
                }
            } else {
                if (m % 3 != 0) {
                    out.print("NO");
                    return;
                }
                String c = "";
                for (int i = 0; i < m; i++) c += b[0][i];
                if (!v(c)) {
                    out.print("NO");
                    return;
                }
                for (int i = 0; i < n; i++) {
                    String d = "";
                    for (int j = 0; j < m; j++) d += b[i][j];
                    if (!c.equals(d)) {
                        out.print("NO");
                        return;
                    }
                }
            }
            out.print("YES");
        }

    }

    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer token;

        public FastReader(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in), 1 << 20);
        }

        String next() {
            while (token == null || !token.hasMoreElements()) {
                try {
                    token = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return token.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

