			s = transpose(s);
			if (f(s)) {
				out.println("YES");
				return;
			}
			out.println("NO");
		}

		private char[][] transpose(char[][] s) {
			int n = s.length;
			int m = s[0].length;
			char[][] t = new char[m][n];
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					t[j][i] = s[i][j];
				}
			}
			return t;
