    public static boolean checkVertical( int n , int m , String [][] str )
    {
        Set <String> set = new HashSet<>();
        int mod = m / 3 ;                     // each vertical stripe has m/3 columns
        String colo = str[0][0] ;
        set.add(colo);
        // first stripe: columns 0 .. mod-1
        for (int i = 0; i < mod; i++) {
            for (int j = 0; j < n; j++) {
                if( !str[j][i].equals(colo) )
                    return false ;
            }
        }

        colo = str[0][mod];                     // colour of second stripe
        set.add(colo);
        // second stripe: columns mod .. 2*mod-1
        for (int i = mod; i < mod*2; i++) {
            for (int j = 0; j < n; j++) {
                if( !str[j][i].equals(colo) )
                    return false ;
            }
        }

        colo = str[0][mod*2];                     // colour of third stripe
        set.add(colo);
        // third stripe: columns 2*mod .. m-1
        for (int i = mod*2; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if( !str[j][i].equals(colo) )
                    return false ;
            }
        }
        if( set.size()!= 3 )
            return false ;
        return true ;
    }

    public static boolean checkHorizontal( int n , int m , String [][] str )
    {
        Set <String> set = new HashSet<>();
        int mod = n / 3 ;
        String colo = str[0][0];
        set.add(colo);
        for (int i = 0; i < mod; i++) {
            for (int j = 0; j < m; j++) {
                if( !str[i][j].equals(colo) )
                    return false ;
            }
