            for (int j = 0; j < m; j++) {
                if( !str[i][j].equals(colo) )
                    return false ;
            }
        }

        colo = str[mod*2][0];
        set.add(colo);
        for (int i = mod*2; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if( !str[i][j].equals(colo) )
                    return false ;
            }
        }

        if( set.size()!= 3 )
            return false ;
        return true ;
    }

