public class Main
{
    public static void main (String[] args) throws java.lang.Exception
    {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] arr = new char[n][m];
        for(int i = 0; i < n; ++i) {
            arr[i] = in.next().toCharArray();
        }

        boolean b1 = check1(arr, n, m);
        boolean b2 = check2(arr, n, m);

        if(b1 || b2) System.out.println("YES");
        else System.out.println("NO");
    }

    public static int getInt(char c ) {
        if(c == 'R') return 0;
        if(c == 'G') return 1;
        return 2;
    }

    public static boolean check1(char[][] arr, int n, int m) {
        int[] tmp = new int[3];
        int[] len = new int[3];
        char last = 'Z';
        for(int i = 0; i < n; ++i) {
            if(last == 'Z') last = arr[i][0];
            else if(last != arr[i][0]) {
                ++tmp[getInt(last)];
                last = arr[i][0];
            }

            ++len[getInt(last)];
            for(int j = 1; j < m; ++j) {
                if(arr[i][j] != last) return false;
            }
        }

        ++tmp[getInt(last)];
        for(int i = 0; i < 3; ++i) {
            if(tmp[i] != 1) return false;
        }

        if(len[0] != len[1] || len[1] != len[2] || len[0] != len[2]) return false;
        return true;
    }

    public static boolean check2(char[][] arr, int n, int m) {
        int[] tmp = new int[3];
        int[] len = new int[3];
        char lastColor = arr[0][0];               // colour of the first column

        for (int j = 0; j < m; ++j) {
            char colColor = arr[0][j];

            // every cell in this column must have the same colour
            for (int i = 0; i < n; ++i) {
                if (arr[i][j] != colColor) return false;
            }

            // when the colour of the current column differs from the previous one,
            // we finish the previous stripe
            if (j > 0 && colColor != lastColor) {
                ++tmp[getInt(lastColor)];
                lastColor = colColor;
            }
            ++len[getInt(colColor)];               // count columns belonging to this stripe
        }
        // finish the last stripe
        ++tmp[getInt(lastColor)];

        // each colour must appear exactly once as a stripe
        for (int i = 0; i < 3; ++i) {
            if (tmp[i] != 1) return false;
        }

        // all three stripes must have the same width
        return len[0] == len[1] && len[1] == len[2];
    }
}

