public class Main {
    private static String[] input;

    private static boolean checkRow(int n, int m) {
        if (n % 3 != 0) {
            return false;
        }
        Set<Character> set = new HashSet<>();
        int stripeHeight = n / 3;
        for (int i = 0; i < n; i += stripeHeight) {
            char ch = input[i].charAt(0);
            for (int x = i; x < i + stripeHeight; x++) {
                for (int y = 0; y < m; y++) {
                    if (input[x].charAt(y) != ch) {
                        return false;
                    }
                }
            }
            set.add(ch);
        }
        return set.size() == 3;
    }

    private static boolean checkCol(int n, int m) {
        if (m % 3 != 0) {
            return false;
        }
        Set<Character> set = new HashSet<>();
        int stripeWidth = m / 3;
        for (int j = 0; j < m; j += stripeWidth) {
            char ch = input[0].charAt(j);
            for (int i = 0; i < n; i++) {
                for (int k = j; k < j + stripeWidth; k++) {
                    if (input[i].charAt(k) != ch) {
                        return false;
                    }
                }
            }
            set.add(ch);
        }
        return set.size() == 3;
    }

