import java.util.*;

public class Main
{
    public static boolean checkRow(int length, String s)
    {
        for (int i = 1; i < length; i++)
            if (s.charAt(i) != s.charAt(0)) return false;

        return true;
    }

    public static boolean checkColum(int n, int index, String[] s)
    {
        for (int i = 1; i < n; i++)
            if (s[i].charAt(index) != s[0].charAt(index)) return false;

        return true;
    }

    public static String findAnswer(String[] s, int n, int m)
    {
        boolean vertical = true;
        boolean horizontal = true;

        boolean redColor = false;
        boolean blueColor = false;
        boolean greenColor = false;

        int size = -1;
        int lastPos = 0;

        int loopInside = 0;

        for (int i = 0; i < n; i++)
            if (i == n - 1 || s[i].charAt(0) != s[i + 1].charAt(0)) {

                if (s[i].charAt(0) == 'R') redColor = true;
                if (s[i].charAt(0) == 'B') blueColor = true;
                if (s[i].charAt(0) == 'G') greenColor = true;

                int newPos = i;

                loopInside++;

                if (size == -1) size = newPos - lastPos + 1; else
                    if (size != newPos - lastPos + 1) {
                        horizontal = false; break;
                    }

                for (int j = lastPos; j <= newPos; j++)
                    if (!checkRow(m, s[j])) {

                        horizontal = false; break;
                    }

                lastPos = i + 1;   // fixed line
            }

        if (loopInside != 3) horizontal = false;
        if (!redColor || !greenColor || !blueColor) horizontal = false;

        redColor = false;
        blueColor = false;
        greenColor = false;

        size = -1;
        lastPos = 0;

        loopInside = 0;

        for (int i = 0; i < m; i++)
            if (i == m - 1 || s[0].charAt(i) != s[0].charAt(i + 1)) {

                if (s[0].charAt(i) == 'R') redColor = true;
                if (s[0].charAt(i) == 'B') blueColor = true;
                if (s[0].charAt(i) == 'G') greenColor = true;

                int newPos = i;

                loopInside++;

                if (size == -1) size = newPos - lastPos + 1; else
                    if (size != newPos - lastPos + 1) {
                        vertical = false; break;
                    }

                for (int j = lastPos; j <= newPos; j++)
                    if (!checkColum(n, j, s)) {

                        vertical = false; break;
                    }

                lastPos = i + 1;
            }

        if (loopInside != 3) vertical = false;
        if (!redColor || !greenColor || !blueColor) vertical = false;

        if (horizontal || vertical) return "YES"; else
            return "NO";
    }

    public static void main(String[] args)
    {
        Scanner in = new Scanner(System.in);

        int n = in.nextInt();
        int m = in.nextInt();

        in.nextLine();

        String[] s = new String[110];

        for (int i = 0; i < n; i++) s[i] = in.nextLine();

        System.out.println(findAnswer(s, n, m));
    }
}

