import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[][] cubes = new int[n][6];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                cubes[i][j] = sc.nextInt();
            }
        }

        // all numbers that can be formed
        Set<Integer> reachable = new HashSet<>();

        // consider every non‑empty subset of cubes
        for (int mask = 1; mask < (1 << n); mask++) {
            List<Integer> subset = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) subset.add(i);
            }

            // all permutations of the chosen cubes
            permute(subset, 0, new ArrayList<>(), perm -> {
                // for each permutation, try every combination of faces
                int k = perm.size();
                int[] faceIdx = new int[k];
                dfsFaces(perm, 0, faceIdx, cubes, reachable);
            });
        }

        // find the largest x such that 1..x are all present
        int x = 1;
        while (reachable.contains(x)) {
            x++;
        }
        System.out.println(x - 1);          // if nothing was reachable, prints 0
    }

    /** generate all permutations of a list and call action on each */
    private static void permute(List<Integer> src, int depth,
                                List<Integer> current,
                                Consumer<List<Integer>> action) {
        if (depth == src.size()) {
            action.accept(new ArrayList<>(current));
            return;
        }
        for (int i = depth; i < src.size(); i++) {
            Collections.swap(src, depth, i);
            current.add(src.get(depth));
            permute(src, depth + 1, current, action);
            current.remove(current.size() - 1);
            Collections.swap(src, depth, i);
        }
    }

    /** depth‑first search over the 6 faces for each position of the permutation */
    private static void dfsFaces(List<Integer> perm, int depth,
                                 int[] idx, int[][] cubes,
                                 Set<Integer> set) {
        if (depth == perm.size()) {
            // build the number from the selected faces
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < idx.length; i++) {
                int digit = cubes[perm.get(i)][idx[i]];
                sb.append(digit);
            }
            // reject numbers with leading zero
            if (sb.charAt(0) == '0') return;
            int num = Integer.parseInt(sb.toString());
            set.add(num);
            return;
        }
        // try each face of the current cube
        int cubeIdx = perm.get(depth);
        for (int f = 0; f < 6; f++) {
            idx[depth] = f;
            dfsFaces(perm, depth + 1, idx, cubes, set);
        }
    }
}

