public class B_KubikiDlyaMashi {
    static int number = 1;
    static byte[][] mas;
    static int nextIndex = 0;
    static boolean[] b = { false, false, false };

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        byte n = sc.nextByte();
        mas = new byte[n][];
        for (byte i = 0; i < n; i++) {
            mas[i] = new byte[6];
            for (int j = 0; j < 6; j++)
                mas[i][j] = sc.nextByte();
        }
        int sum = 0;
        boolean goOn = false;
        int k = 0;
        while (true) {
            goOn = false;
            p: for (byte i = 0; i < n; i++) {
                for (byte j = 0; j < n; j++) {
                    for (byte z = 0; z < n; z++) {
                        b = new boolean[] { false, false, false };
                        nextIndex = 0;
                        sum = 0;

                        if (cont(i, Npos(nextIndex))) {
                            sum++;
                            if (sum == Nlength()) {
                                goOn = true;
                                break p;
                            }
                        }
                        if (nextIndex < Nlength())
                            if (cont(j, Npos(nextIndex))) {
                                sum++;
                                if (sum == Nlength()) {
                                    goOn = true;
                                    break p;
                                }
                            }
                        if (nextIndex < Nlength())
                            if (cont(z, Npos(nextIndex))) {
                                sum++;
                                if (sum == Nlength()) {
                                    goOn = true;
                                    break p;
                                }
                            }

                    }
                }
            }

            if (!goOn)
                break;
            number++;
            sum = 0;
            k++;
        }
        if (k != 0)
            System.out.println(number - 1);
        else
            System.out.println(0);
    }

    private static int Npos(int nextIndex2) {
        return (number % (int) Math.pow(10, (nextIndex2 + 1))) / (int) Math.pow(10, nextIndex2);
    }

    private static int Nlength() {
        int buf = number;
        int k = 0;
        while (buf != 0) {
            k++;
            buf /= 10;
        }
        return k;
    }

    private static boolean cont(int index, int number) {
        if (b[index])
            return false;
        for (int el : mas[index]) {
            if (el == number) {
                b[index] = true;
                nextIndex++;
                return true;
            }
        }
        return false;
    }
}

