        {
            for (j = 0; j < 6; j++)
            {
                dice[i][j] = in.nextInt();
                bs.set(dice[i][j]);
            }
        }

        // ---------- generate all reachable numbers ----------
        // 1‑digit numbers are already stored (including 0)

        // numbers of length 2 using any ordered pair of distinct cubes
        if (n >= 2)
        {
            for (int i1 = 0; i1 < n; i1++)
            {
                for (int i2 = 0; i2 < n; i2++)
                {
                    if (i1 == i2) continue;                // distinct cubes
                    for (int a = 0; a < 6; a++)
                    {
                        if (dice[i1][a] == 0) continue;    // no leading zero
                        for (int b = 0; b < 6; b++)
                        {
                            int num = dice[i1][a] * 10 + dice[i2][b];
                            bs.set(num);
                        }
                    }
                }
            }
        }

        // numbers of length 3 using any ordered triple of distinct cubes
        if (n == 3)
        {
            for (int i1 = 0; i1 < n; i1++)
            {
                for (int i2 = 0; i2 < n; i2++)
                {
                    if (i2 == i1) continue;
                    for (int i3 = 0; i3 < n; i3++)
                    {
                        if (i3 == i1 || i3 == i2) continue;
                        for (int a = 0; a < 6; a++)
                        {
                            if (dice[i1][a] == 0) continue;
                            for (int b = 0; b < 6; b++)
                            {
                                for (int c = 0; c < 6; c++)
                                {
                                    int num = dice[i1][a] * 100
                                            + dice[i2][b] * 10
                                            + dice[i3][c];
                                    bs.set(num);
                                }
                            }
                        }
                    }
                }
            }
        }

        int missing = bs.nextClearBit(0);   // first non‑negative integer not present
        out.println(missing - 1);           // largest x such that 1..x are all present
    }
