import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class ProblemB {
    List<int[]> pe = new ArrayList<>();

    ProblemB() throws IOException {
        rd = new BufferedReader(new InputStreamReader(System.in));
        generatePerms();
        compute();
    }

    private void generatePerms() {
        // generate all permutations of indices 0 … n‑1 (n ≤ 3)
        int n = pe.size(); // will be set later in compute()
        permute(0, new int[n], new boolean[n]);
    }

    private void permute(int idx, int[] cur, boolean[] used) {
        if (idx == cur.length) {
            pe.add(new int[cur.length]);
            System.arraycopy(cur, 0, pe.get(pe.size() - 1), 0, cur.length);
            return;
        }
        for (int i = 0; i < cur.length; i++) {
            if (!used[i]) {
                used[i] = true;
                cur[i] = i;
                permute(idx + 1, cur, used);
                used[i] = false;
            }
        }
    }

    private void compute() throws IOException {
        int n = pint();
        int[][] d = new int[n][];
        for (int i = 0; i < n; i++) {
            d[i] = intarr();
        }
        int limit = (int) Math.pow(10, n);
        int max = 0;
        for (int i = 1; i < limit; i++) {
            if (!possible(d, i)) {
                break;
            }
            max = i;
        }
        out(max);
    }

    private int pow(int a, int b) {
        int res = 1;
        for (int i = 0; i < b; i++) {
            res *= a;
        }
        return res;
    }

    private boolean possible(int[][] d, int i) {
        char[] q = Integer.toString(i).toCharArray();
        int z = q.length;
        int[] u = new int[z];
        for (int j = 0; j < z; j++) {
            u[j] = q[j] - '0';
        }
        for (int[] p : pe) {
            boolean ok = true;
            for (int w = 0; w < z; w++) {
                if (p[w] >= d.length) {
                    ok = false;
                    break;
                }
                int[] a = d[p[w]];
                if (!contains(a, u[w])) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return true;
            }
        }
        return false;
    }

    private boolean contains(int[] a, int i) {
        for (int x : a) {
            if (x == i) {
                return true;
            }
        }
        return false;
    }

    private int pint() throws IOException {
        return pint(rd.readLine());
    }

    private int pint(String s) {
        return Integer.parseInt(s);
    }

    private int[] intarr() throws IOException {
        return intarr(rd.readLine());
    }

    private int[] intarr(String s) {
        String[] q = split(s);
        int n = q.length;
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(q[i]);
        }
        return a;
    }

    private String[] split(String s) {
        if (s == null) {
            return new String[0];
        }
        int n = s.length();
        int start = -1;
        int end = 0;
        int sp = 0;
        boolean lastWhitespace = true;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (!(isWhitespace(c))) {
                lastWhitespace = true;
            } else {
                if (lastWhitespace) {
                    sp++;
                }
                if (start == -1) {
                    start = i;
                }
                end = i;
                lastWhitespace = false;
            }
        }
        if (start == -1) {
            return new String[0];
        }
        String[] res = new String[sp];
        int x = 0;
        lastWhitespace = true;
        int last = start;
        for (int i = start; i <= end; i++) {
            char c = s.charAt(i);
            boolean w = isWhitespace(c);
            if (w && !lastWhitespace) {
                res[x++] = s.substring(last, i);
            } else if (!w && lastWhitespace) {
                last = i;
            }
            lastWhitespace = w;
        }
        res[x] = s.substring(last, end + 1);
        return res;
    }

    private boolean isWhitespace(char c) {
        return c == ' ' || c == '\t';
    }

    private static void out(Object x) {
        System.out.println(x);
    }

    private BufferedReader rd;

    public static void main(String[] args) throws IOException {
        new ProblemB();
    }
}

