    }

    static boolean nextComb(int[] comb, int k)
    {
        int i = comb.length - 1;
        while (i >= 0 && comb[i] == k)
            comb[i++] = 0;

        if (i < 0)
            return false;

        comb[i]++;
        return true;
    }

    // ---- fixed check method ----
    // now it rejects any representation that would have a leading zero
    static boolean check(int x, int[] nums)
    {
        if (x < 10)
        {
            for (int i = 0; i < nums.length; i++)
                if (nums[i] == x)
                    return true;
            return false;
        }

        if (x < 100)
        {
            for (int i = 0; i < nums.length; i++)
                for (int j = 0; j < nums.length; j++)
                    if (i != j && nums[i] != 0 && x == nums[i] * 10 + nums[j])
                        return true;
            return false;
        }

        for (int i = 0; i < nums.length; i++)
            for (int j = 0; j < nums.length; j++)
                for (int k = 0; k < nums.length; k++)
                    if (i != j && i != k && j != k && nums[i] != 0 &&
                        x == nums[i] * 100 + nums[j] * 10 + nums[k])
                        return true;

        return false;
    }
