        for (int i = 0; i < n; i++)
            for (int j = 0; j < 6; j++)
                mat[i][j] = s.nextInt();

        s.close();

        int[] arr = new int[n];
        int[] comb = new int[n];

        int x;
        for (x = 1; x < Math.pow(10, n); x++)
        {
            boolean flag = false;
            resetComb(comb);

            do
            {	
                for (int i = 0; i < n; i++)
                    arr[i] = mat[i][comb[i]];

                flag = check(x, arr);
            } while (nextComb(comb, 5) && flag == false);

            if (flag == false)
                break;
        }

        System.out.println(x - 1);
    }
