public class B {
    BufferedReader br;
    PrintWriter out;
    StringTokenizer stok;

    String nextToken() throws IOException {
        while (stok == null || !stok.hasMoreTokens()) {
            String s = br.readLine();
            if (s == null) {
                return null;
            }
            stok = new StringTokenizer(s);
        }
        return stok.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    char nextChar() throws IOException {
        return (char) (br.read());
    }

    String nextLine() throws IOException {
        return br.readLine();
    }

    int n;

    boolean can(int x, String[] a) {
        if (x < 10) {
            for (int j = 0; j < n; j++) {
                if (a[j].contains(Integer.toString(x))) {
                    return true;
                }
            }
            return false;
        }
        if (x < 100) {
            for (int j = 0; j < n; j++) {
                for (int i = 0; i < n; i++) {
                    if (i == j) continue;
                    if (a[j].contains(Integer.toString(x).substring(0, 1))
                            && a[i].contains(Integer.toString(x).substring(1, 2))) {
                        return true;
                    }
                }
            }
            return false;
        }
        for (int j = 0; j < n; j++) {
            for (int i = 0; i < n; i++) {
                for (int k = 0; k < n; k++) {
                    if (i == j || i == k || j == k) continue;
                    if (a[j].contains(Integer.toString(x).substring(0, 1))
                            && a[i].contains(Integer.toString(x).substring(1, 2))
                            && a[k].contains(Integer.toString(x).substring(2, 3))) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private void solve() throws IOException {
        n = nextInt();
        int[][] a = new int[n][6];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                a[i][j] = nextInt();
            }
        }
        String[] s = new String[n];
        for (int j = 0; j < n; j++) {
            s[j] = "";
            for (int i = 0; i < 6; i++) {
                s[j] += Integer.toString(a[j][i]);
            }
        }
        // Find the first integer that cannot be formed.
        for (int i = 1; ; i++) {
            if (!can(i, s)) {
                out.println(i - 1);
                return;
            }
            // All numbers up to 999 are possible – maximum with 3 cubes.
            if (i == 1000) {
                out.println(999);
                return;
            }
        }
    }

    void run() throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        solve();
        br.close();
        out.close();
    }

    public static void main(String[] args) throws IOException {
        new B().run();
    }
}

