    static class Solver {
        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();                     // number of cubes
            int[][] cubes = new int[n][6];              // store each cube's faces
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    cubes[i][j] = in.nextInt();
                }
            }

            // reuse the original list 't' and clear it
            t.clear();

            if (n == 1) {
                // single‑digit numbers from the only cube
                for (int f = 0; f < 6; f++) {
                    int d = cubes[0][f];
                    if (d != 0) t.add(d);
                }
            } else if (n == 2) {
                // single‑digit numbers from each cube
                for (int i = 0; i < 6; i++) {
                    int d = cubes[0][i];
                    if (d != 0) t.add(d);
                }
                for (int i = 0; i < 6; i++) {
                    int d = cubes[1][i];
                    if (d != 0) t.add(d);
                }
                // two‑digit numbers, order (0,1)
                for (int r0 = 0; r0 < 6; r0++) {
                    int d0 = cubes[0][r0];
                    if (d0 == 0) continue;
                    for (int r1 = 0; r1 < 6; r1++) {
                        int d1 = cubes[1][r1];
                        t.add(d0 * 10 + d1);
                    }
                }
                // two‑digit numbers, order (1,0)
                for (int r0 = 0; r0 < 6; r0++) {
                    int d0 = cubes[1][r0];
                    if (d0 == 0) continue;
                    for (int r1 = 0; r1 < 6; r1++) {
                        int d1 = cubes[0][r1];
                        t.add(d0 * 10 + d1);
                    }
                }
            } else if (n == 3) {
                // single‑digit numbers from any cube
                for (int i = 0; i < 6; i++) {
                    int d = cubes[0][i];
                    if (d != 0) t.add(d);
                    d = cubes[1][i];
                    if (d != 0) t.add(d);
                    d = cubes[2][i];
                    if (d != 0) t.add(d);
                }
                // two‑cube permutations (6 of them)
                // (0,1)
                for (int r0 = 0; r0 < 6; r0++) {
                    int d0 = cubes[0][r0];
                    if (d0 == 0) continue;
                    for (int r1 = 0; r1 < 6; r1++) {
                        int d1 = cubes[1][r1];
                        t.add(d0 * 10 + d1);
                    }
                }
                // (1,0)
                for (int r0 = 0; r0 < 6; r0++) {
                    int d0 = cubes[1][r0];
                    if (d0 == 0) continue;
                    for (int r1 = 0; r1 < 6; r1++) {
                        int d1 = cubes[0][r1];
                        t.add(d0 * 10 + d1);
                    }
                }
                // (0,2)
                for (int r0 = 0; r0 < 6; r0++) {
                    int d0 = cubes[0][r0];
                    if (d0 == 0) continue;
                    for (int r1 = 0; r1 < 6; r1++) {
                        int d1 = cubes[2][r1];
                        t.add(d0 * 10 + d1);
                    }
                }
                // (2,0)
                for (int r0 = 0; r0 < 6; r0++) {
                    int d0 = cubes[2][r0];
                    if (d0 == 0) continue;
                    for (int r1 = 0; r1 < 6; r1++) {
                        int d1 = cubes[0][r1];
                        t.add(d0 * 10 + d1);
                    }
                }
                // (1,2)
                for (int r0 = 0; r0 < 6; r0++) {
                    int d0 = cubes[1][r0];
                    if (d0 == 0) continue;
                    for (int r1 = 0; r1 < 6; r1++) {
                        int d1 = cubes[2][r1];
                        t.add(d0 * 10 + d1);
                    }
                }
                // (2,1)
                for (int r0 = 0; r0 < 6; r0++) {
                    int d0 = cubes[2][r0];
                    if (d0 == 0) continue;
                    for (int r1 = 0; r1 < 6; r1++) {
