                    }
                }
                // three‑cube permutations (6 of them)
                // 0,1,2
                for (int r0 = 0; r0 < 6; r0++) {
                    int d0 = cubes[0][r0];
                    if (d0 == 0) continue;
                    for (int r1 = 0; r1 < 6; r1++) {
                        int d1 = cubes[1][r1];
                        for (int r2 = 0; r2 < 6; r2++) {
                            int d2 = cubes[2][r2];
                            t.add(d0 * 100 + d1 * 10 + d2);
                        }
                    }
                }
                // 0,2,1
                for (int r0 = 0; r0 < 6; r0++) {
                    int d0 = cubes[0][r0];
                    if (d0 == 0) continue;
                    for (int r1 = 0; r1 < 6; r1++) {
                        int d1 = cubes[2][r1];
                        for (int r2 = 0; r2 < 6; r2++) {
                            int d2 = cubes[1][r2];
                            t.add(d0 * 100 + d1 * 10 + d2);
                        }
                    }
                }
                // 1,0,2
                for (int r0 = 0; r0 < 6; r0++) {
                    int d0 = cubes[1][r0];
                    if (d0 == 0) continue;
                    for (int r1 = 0; r1 < 6; r1++) {
                        int d1 = cubes[0][r1];
                        for (int r2 = 0; r2 < 6; r2++) {
                            int d2 = cubes[2][r2];
                            t.add(d0 * 100 + d1 * 10 + d2);
                        }
                    }
                }
                // 1,2,0
                for (int r0 = 0; r0 < 6; r0++) {
                    int d0 = cubes[1][r0];
                    if (d0 == 0) continue;
                    for (int r1 = 0; r1 < 6; r1++) {
                        int d1 = cubes[2][r1];
                        for (int r2 = 0; r2 < 6; r2++) {
                            int d2 = cubes[0][r2];
                            t.add(d0 * 100 + d1 * 10 + d2);
                        }
                    }
                }
                // 2,0,1
                for (int r0 = 0; r0 < 6; r0++) {
                    int d0 = cubes[2][r0];
                    if (d0 == 0) continue;
                    for (int r1 = 0; r1 < 6; r1++) {
                        int d1 = cubes[0][r1];
                        for (int r2 = 0; r2 < 6; r2++) {
                            int d2 = cubes[1][r2];
                            t.add(d0 * 100 + d1 * 10 + d2);
                        }
                    }
                }
                // 2,1,0
                for (int r0 = 0; r0 < 6; r0++) {
                    int d0 = cubes[2][r0];
                    if (d0 == 0) continue;
                    for (int r1 = 0; r1 < 6; r1++) {
                        int d1 = cubes[1][r1];
                        for (int r2 = 0; r2 < 6; r2++) {
                            int d2 = cubes[0][r2];
                            t.add(d0 * 100 + d1 * 10 + d2);
                        }
                    }
                }
            }

            Collections.sort(t);

            int counter = 1;
            while (counter <= 1000 && t.contains(counter)) {
                counter++;
            }
            if (!t.contains(1)) {
                counter = 0;
            } else {
                counter--;
            }
            out.print(counter);
        }
    }

