import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.StringTokenizer;

public class Template {

    static class Solver {
        public void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();                     // number of cubes
            int[][] cubes = new int[n][6];             // faces of each cube

            // read the 6 faces of each cube
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    cubes[i][j] = in.nextInt();
                }
            }

            // collect all numbers that can be formed
            HashSet<Integer> numbers = new HashSet<>();

            // helper to build numbers from an ordered list of cube indices
            // and a concrete choice of faces
            switch (n) {
                case 1:                                     // only one cube → 1‑digit numbers
                    for (int f0 = 0; f0 < 6; f0++) {
                        int d = cubes[0][f0];
                        if (d != 0) {                     // no leading zero
                            numbers.add(d);
                        }
                    }
                    break;

                case 2:                                     // two cubes → up to 2‑digit numbers
                    for (int i = 0; i < 2; i++) {         // first cube index
                        for (int j = 0; j < 2; j++) {     // second cube index, j != i
                            if (j == i) continue;
                            for (int f0 = 0; f0 < 6; f0++) {
                                int d0 = cubes[i][f0];
                                if (d0 == 0) continue;   // leading digit may not be 0
                                for (int f1 = 0; f1 < 6; f1++) {
                                    int d1 = cubes[j][f1];
                                    int num = d0 * 10 + d1;   // tens digit from i, unit from j
                                    numbers.add(num);
                                }
                            }
                        }
                    }
                    break;

                case 3:                                     // three cubes → up to 3‑digit numbers
                    for (int i = 0; i < 3; i++) {         // first cube index
                        for (int j = 0; j < 3; j++) {     // second cube index, j != i
                            if (j == i) continue;
                            for (int k = 0; k < 3; k++) { // third cube index, k distinct
                                if (k == i || k == j) continue;
                                for (int f0 = 0; f0 < 6; f0++) {
                                    int d0 = cubes[i][f0];
                                    if (d0 == 0) continue;   // leading digit may not be 0
                                    for (int f1 = 0; f1 < 6; f1++) {
                                        int d1 = cubes[j][f1];
                                        for (int f2 = 0; f2 < 6; f2++) {
                                            int d2 = cubes[k][f2];
                                            int num = d0 * 100 + d1 * 10 + d2;
                                            numbers.add(num);
                                        }
                                    }
                                }
                            }
                        }
                    }
                    break;
            }

            // find the maximal x such that 1..x are all present
            int counter = 1;
            while (numbers.contains(counter)) {
                counter++;
            }
            int answer = counter - 1;
            if (!numbers.contains(1)) {          // cannot even make the number 1
                answer = 0;
            }
            out.println(answer);
        }
    }

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Solver solver = new Solver();
        solver.solve(in, out);
        out.close();
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

