public class Main {

    static MyScanner in;
    static PrintWriter out;

    public static void main(String[] args) throws IOException {
        in = new MyScanner();
        out = new PrintWriter(new BufferedOutputStream(System.out), false);

        int n = in.nextInt();
        int[][] arr = in.next2Ints(n, 6);
        boolean[][] used = new boolean[n][3];

        int i;
        for (i = 1; i <= 1000; i++) {
            if (i == 1000)
                break;

            int a = i;
            int index = 0;
            while (a != 0) {
                int c = a % 10;
                a /= 10;

                for (int k = 0; k < n; k++)
                    used[k][index] = contains(arr[k], c);
                index++;
            }

            // *** FIXED: break when the current number cannot be built ***
            if (!can(used, 0, new boolean[n], index))
                break;
        }

        System.out.println(i - 1);
    }

    static boolean can(boolean[][] used, int pos, boolean[] visited, int cnt) {
        if (pos == cnt)
            return true;

        for (int i = 0; i < used.length; i++) {
            if (used[i][pos] && !visited[i]) {
                visited[i] = true;
                if (can(used, pos + 1, visited, cnt))
                    return true;
                visited[i] = false;
            }
        }

        return false;
    }

    static boolean contains(int[] arr, int k) {
        for (int a : arr)
            if (a == k)
                return true;
        return false;
    }


}

class MyScanner implements Closeable {

    public static final String CP1251 = "cp1251";

    private final BufferedReader br;
    private StringTokenizer st;
    private String last;

    public MyScanner() {
        br = new BufferedReader(new InputStreamReader(System.in));
    }

    public MyScanner(String path) throws IOException {
        br = new BufferedReader(new FileReader(path));
    }

    public MyScanner(String path, String decoder) throws IOException {
        br = new BufferedReader(new InputStreamReader(new FileInputStream(path), decoder));
    }

    public void close() throws IOException {
        br.close();
    }

    public String next() throws IOException {
        while (st == null || !st.hasMoreElements())
            st = new StringTokenizer(br.readLine());
        last = null;
        return st.nextToken();
    }

    public String next(String delim) throws IOException {
        while (st == null || !st.hasMoreElements())
            st = new StringTokenizer(br.readLine());
        last = null;
        return st.nextToken(delim);
    }

    public String nextLine() throws IOException {
        st = null;
        return (last == null) ? br.readLine() : last;
    }

    public boolean hasNext() {
        if (st != null && st.hasMoreElements())
            return true;

        try {
            while (st == null || !st.hasMoreElements()) {
                last = br.readLine();
                st = new StringTokenizer(last);
            }
        } catch (Exception e) {
            return false;
        }

        return true;
    }

    public String[] nextStrings(int n) throws IOException {
        String[] arr = new String[n];
        for (int i = 0; i < n; i++)
            arr[i] = next();
        return arr;
