public class codeforces implements Runnable { 

	public void run() {

		InputReader s = new InputReader(System.in);
		PrintWriter w = new PrintWriter(System.out);

		int t = 1;

		while(t++ > 0) {

			int n = s.nextInt();

			int[] check = new int[10000];

			int[][] val = new int[n][6];

			for(int i = 0; i < n; i++)
				for(int j = 0; j < 6; j++)
					val[i][j] = s.nextInt();

			for(int i = 0; i < n; i++)
				for(int v1 = 0; v1 < 6; v1++)
					check[val[i][v1]] = 1;

			for(int i = 0; i < n; i++)
				for(int j = 0; j < n; j++) {
					if(i == j)
						continue;
					for(int v1 = 0; v1 < 6; v1++)
						for(int v2 = 0; v2 < 6; v2++)
							check[10 * val[i][v1] + val[j][v2]] = 1;
				}

			for(int i = 0; i < n; i++) {
				for(int j = 0; j < n; j++) {
					if(i == j)
						continue;
					for(int k = 0; k < n; k++) {
						if(i == k || j == k)
							continue;
						for(int v1 = 0; v1 < 6; v1++) {
							if (val[i][v1] == 0) continue;
							for(int v2 = 0; v2 < 6; v2++)
								for(int v3 = 0; v3 < 6; v3++)
									check[100 * val[i][v1] + 10 * val[j][v2] + val[k][v3]] = 1;
						}
					}
				}
			}

			int x = 1;

			while(check[x] == 1)
				x++;

			w.println(x - 1);

