        for(int i = 0;i < n; i++){
            for(int j = 0;j < 6; j++){
                die[i][j] = in.nextInt();
            }
        }
        if(n == 1){
            for(int i = 0;i < 6; i++){
                canMake[die[0][i]]= true;
            }
        }
        if(n == 2){
            for(int i =0; i < 6; i++){
                for(int j = 0;j < 6; j++){
                    canMake[die[0][i]*10 + die[1][j]] = true;
                    canMake[die[1][j]*10 + die[0][i]] = true;
                }
            }
            for(int i = 0;i < 6; i++){
                canMake[die[0][i]] = true;
                canMake[die[1][i]] = true;
            }
        }
        if(n == 3){
            for(int i = 0;i < 6; i++){
                for(int k = 0;k < 6; k++){
                    for(int j = 0;j < 6; j++){
                        canMake[die[0][i]*100 + die[1][j]*10 + die[2][k]*1] = true;
                        canMake[die[0][i]*100 + die[1][j]*1 + die[2][k]*10] = true;
                        canMake[die[0][i]*10 + die[1][j]*100 + die[2][k]*1] = true;
                        canMake[die[0][i]*1 + die[1][j]*100 + die[2][k]*10] = true;
                        canMake[die[0][i]*1 + die[1][j]*10 + die[2][k]*100] = true;
                        canMake[die[0][i]*10 + die[1][j]*1 + die[2][k]*100] = true;
                    }
                }
            }
            for(int i =0; i < 6; i++){
                for(int j = 0;j < 6; j++){
                    canMake[die[0][i]*10 + die[1][j]] = true;
                    canMake[die[1][j]*10 + die[0][i]] = true;
                    canMake[die[2][i]*10 + die[1][j]] = true;
                    canMake[die[1][j]*10 + die[2][i]] = true;
                    canMake[die[0][i]*10 + die[2][j]] = true;
                    canMake[die[2][j]*10 + die[0][i]] = true;
                }
            }
            for(int i = 0;i < 6; i++){
                canMake[die[0][i]] = true;
                canMake[die[1][i]] = true;
                canMake[die[2][i]] = true;
            }
        }
        if(!canMake[1]){
            System.out.println(0);
            return;
        }
        for(int i = 1;i < 1000; i++){
            if(!canMake[i]){
                System.out.println(i-1);
                return;
            }
        }
    }

    private static class FastScanner {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
