    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.ni();
            boolean[][] arr = new boolean[n][10];
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < 6; ++j)
                    arr[i][in.ni()] = true;
            }
            int ans = 0;
            for (int i = 1; i < 1000; ++i) {
                boolean current = false;
                int dig = digits(i);
                if (dig == 1) {
                    current |= arr[0][i];
                    if (n >= 2)
                        current |= arr[1][i];
                    if (n == 3)
                        current |= arr[2][i];
                } else if (dig == 2) {
                    if (n == 2) {
                        int last = i % 10;
                        int first = (i / 10) % 10;
                        if (arr[0][first] && arr[1][last])
                            current = true;
                        if (arr[1][first] && arr[0][last])
                            current |= true;
                    } else if (n == 3) {
                        int last = i % 10;
                        int first = (i / 10) % 10;
                        if (arr[0][first] && arr[1][last])
                            current = true;
                        if (arr[0][last] && arr[1][first])
                            current = true;
                        if (arr[2][first] && arr[1][last])
                            current = true;
                        if (arr[2][last] && arr[1][first])
                            current = true;
                        if (arr[0][first] && arr[2][last])
                            current = true;
                        if (arr[0][last] && arr[2][first])
                            current = true;
                    }
                } else {
                    if (n == 3) {
                        int last = i % 10;
                        int middle = (i / 10) % 10;
                        int first = ((i / 10) / 10) % 10;
                        if (check(first, middle, last, arr) || check(first, last, middle, arr) || check(middle, first, last, arr) || check(middle, last, first, arr) || check(last, middle, first, arr) || check(last, first, middle, arr))
                            current = true;
                    }
                }
                if (current) {
                    ans = i;
                } else {
                    break;
                }
            }
            out.println(ans);
        }

        boolean check(int a, int b, int c, boolean[][] arr) {
            return arr[0][a] && arr[1][b] && arr[2][c];
        }

        int digits(int n) {
            int ans = 0;
            while (n > 0) {
                ++ans;
                n /= 10;
            }
            return ans;
        }

    }

