    static class B887 {
        public void solve(int testNumber, ScanReader in, PrintWriter out) {
            int n = in.scanInt();
            int array[][] = new int[n][6];
            boolean check[] = new boolean[1000];
            for (int i = 0; i < n; i++) for (int j = 0; j < 6; j++) check[array[i][j] = in.scanInt()] = true;
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    for (int k = 0; k < 6; k++) {
                        for (int l = 0; l < 6; l++) {
                            check[array[i][k] * 10 + array[j][l]] = true;
                            if (array[j][l] != 0) check[array[i][k] + array[j][l] * 10] = true;
                        }
                    }
                }
            }
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    for (int m = j + 1; m < n; m++) {
                        for (int k = 0; k < 6; k++) {
                            for (int l = 0; l < 6; l++) {
                                for (int p = 0; p < 6; p++) {
                                    check[array[i][k] * 100 + array[j][l] * 10 + array[m][p]] = true;
                                    check[array[i][k] * 100 + array[m][p] * 10 + array[j][l]] = true;
                                    check[array[j][l] * 100 + array[i][k] * 10 + array[m][p]] = true;
                                    check[array[j][l] * 100 + array[m][p] * 10 + array[i][k]] = true;
                                    check[array[m][p] * 100 + array[i][k] * 10 + array[j][l]] = true;
                                    check[array[m][p] * 100 + array[j][l] * 10 + array[i][k]] = true;
                                }
                            }
                        }
                    }
                }
            }
            int ans = 0;
            for (int i = 1; i <= 1000; i++) {
                if (check[i]) ans++;
                else break;
            }
            out.println(ans);
        }
    }

    static class ScanReader {
        private byte[] buf = new byte[4 * 1024];
        private int index;
        private BufferedInputStream in;
        private int total;

        public ScanReader(InputStream inputStream) {
            in = new BufferedInputStream(inputStream);
        }

        private int scan() {
            if (index >= total) {
                index = 0;
                try {
                    total = in.read(buf);
                } catch (Exception e) {
                    e.printStackTrace();
                }
                if (total <= 0) return -1;
            }
            return buf[index++];
        }

        public int scanInt() {
            int integer = 0;
            int n = scan();
            while (isWhiteSpace(n)) n = scan();
            int neg = 1;
            if (n == '-') {
                neg = -1;
                n = scan();
            }
            while (!isWhiteSpace(n)) {
                if (n >= '0' && n <= '9') {
                    integer += 10;
                    integer += n - '0';
                    n = scan();
                }
            }
            return neg * integer;
        }

        private boolean isWhiteSpace(int n) {
            if (n == ' ' || n == '\n' || n == '\r' || n == '\t' || n == -1) return true;
            else return false;
        }

    }
}

