		if(rep.length() > digits.length)
			return true;
		for(int i = 1; i <= Math.pow(2, digits.length); i++) {
			int ones = 0;
			int[]onepos = new int[digits.length];
			for(int j = 0 ; j < digits.length; j++) {
				if((i & (1 << j)) != 0) {
					ones++;
					onepos[j] = 1;
				}
			}
			if(ones != rep.length()) {
				continue;
			} else {
				String perm = "";
				for(int l = 0; l < digits.length; l++)
					if(onepos[l] == 1)
						perm += (""+l);

				char[]rot = perm.toCharArray();
				Arrays.sort(rot);

				if(correct(rot, rep))
					return false;
				while(j_next_permutation(rot))
					if(correct(rot, rep))
						return false;
			}
		}
		return true;
	}
	public static boolean correct(char[]rot, String rep) {
		for(int k = 0; k < rot.length; k++) {
			if(!contains(rot[k] - '0', rep.charAt(k)-'0'))
				return false;
		}
		return true;
	}
	public static boolean contains(int index, int num) {
		for(int i = 0; i < 6; i++)
			if(digits[index][i] == num)
				return true;
		return false;
	}
	public static boolean j_next_permutation(char[] a) {
		int F = 0, L = a.length, I = a.length;
		if (F == L || F == --I) return false;
		for (;;) {
			int Ip = I;
			if (a[--I] < a[Ip]) {
				int J = L;
				for (; !(a[I] < a[--J]););
				char tmp = a[I]; a[I] = a[J]; a[J] = tmp;
				for (int i = Ip; i < ((L - Ip) % 2 == 0 ? Ip + (L - Ip) / 2 : Ip + (L - Ip) / 2 + 1); ++i) {
					char tm = a[i]; a[i] = a[a.length - 1 - i + Ip]; a[a.length - 1 - i + Ip] = tm;
				}
				return true;
			}
			if (I == F) {
				for (int i = 0; i < ((L - F) % 2 == 0 ? (L - F) / 2 : (L - F) / 2 + 1); ++i) {
					char tm = a[i]; a[i] = a[a.length - 1 - i]; a[a.length - 1 - i] = a[i];
				}
				return false;
			}
		}
	}
}

import java.io.InputStream;
import java.io.PrintStream;
import java.util.Scanner;

public class Main887B {
	public static void main(String[] args) {
		run(System.in, System.out);
	}

	public static void run(InputStream in, PrintStream out) {

		try (Scanner sc = new Scanner(in)) {
			int n = sc.nextInt();
			int[][] dice = new int[n][6];

			for (int i = 0; i < n; i++) {
				for (int j = 0; j < 6; j++) {
					dice[i][j] = sc.nextInt();
				}
			}

			for (int i = 1; i < 10; i++) {
				boolean check = check(i, dice[0]);
				if (!check && n >= 2) check = check(i, dice[1]);
				if (!check && n == 3) check = check(i, dice[2]);
				if (!check) {
					out.print(i - 1);
					return;
				}
			}

			if (n == 1) {
				out.print(0);
				return;
			}
			for (int i = 10; i < 100; i++) {
				boolean check = check(i / 10, dice[0]) && check(i % 10, dice[1]);
				if (!check) check = check(i / 10, dice[1]) && check(i % 10, dice[0]);
				if (n == 3) {
					if (!check) check = check(i / 10, dice[0]) && check(i % 10, dice[2]);
					if (!check) check = check(i / 10, dice[2]) && check(i % 10, dice[0]);
					if (!check) check = check(i / 10, dice[1]) && check(i % 10, dice[2]);
					if (!check) check = check(i / 10, dice[2]) && check(i % 10, dice[1]);

				}
				if (!check) {
					out.print(i - 1);
					return;
				}
			}
			out.print(0);
		}
	}

	private static boolean check(int n, int[] t) {
		for (int i = 0; i < t.length; i++) {
			if (t[i] == n) return true;
		}
		return false;
	}
}

