        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public int maxNumber(int[][] presence) {

            int largest = 0;

            int[] total = new int[10];

            int numCubes = presence.length;

            for (int j = 0; j < 10; j++) {
                total[j] = 0;
                for (int c = 0; c < numCubes; c++) {
                    total[j] += presence[c][j];
                }
            }


            for (int i = 1; i <= numCubes * 100 - 1; i++) {
                if (canMake(i, presence, numCubes)) {
                    largest = i;
                } else {
                    break;
                }
            }
            return largest;
        }

        private boolean canMake(int num, final int[][] presence, int numCubes) {
            String s = Integer.toString(num);

            int delta = numCubes - s.length();

            StringBuilder sb = new StringBuilder();
            while (delta > 0) {
                sb.append('.');
                delta--;
            }

            final String toCheck = s + sb.toString();

            String perm = "012";
            if (numCubes == 2) perm = "01";
            else if (numCubes == 1) perm = "0";

            return check(perm.toCharArray(), presence, 0, perm.length() - 1, toCheck);
        }

        private boolean check(char[] a, int[][] presence, int l, int r, String toCheck) {
            if (l == r) {
                return satisfies(toCheck, a, presence);

            } else {
                for (int i = l; i <= r; i++) {
                    swap(a, i, l);
                    boolean ret = check(a, presence, l + 1, r, toCheck);
                    if (ret) return true;
                    swap(a, i, l);
                }
            }
            return false;
        }

        private void swap(char[] a, int to, int from) {
            char c = a[to];
            a[to] = a[from];
            a[from] = c;
        }

        private boolean satisfies(String check, char[] cubes, int[][] presence) {
            for (int i = 0; i < cubes.length; i++) {
                if (check.charAt(i) == '.') continue;

                char c = cubes[i];
                int cube = c - '0';

                int[] p = presence[cube];
                int num = check.charAt(i) - '0';

                if (p[num] == 0) return false;
            }
            return true;
        }

        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int n = in.nextInt();

            int[][] p = new int[n][10];

            for (int i = 0; i < n; i++) {
                for (int j = 1; j <= 6; j++) {
                    p[i][in.nextInt()] = 1;
                }
            }
            out.println(maxNumber(p));
        }

    }
}

