    static boolean next_perm(ArrayList<Integer> al) 
    {
        for(int i=al.size()-2;i>=0;i--)
        {
            if(al.get(i)<al.get(i+1))
            {
                for(int j=al.size()-1;j>=0;j++)
                {
                    if(al.get(j)>al.get(i))
                    {
                        int temp=al.get(i);al.set(i,al.get(j));al.set(j,temp);

                        for(int l=i+1,k=al.size()-1;l<k;l++,k--)
                        {
                            temp=al.get(l);al.set(l,al.get(k));al.set(k,temp);

                        }

                        return true;
                    }
                }
            }
        }

        return false;
    }

    static boolean check(ArrayList<Integer> al,int num)
    {
        char[] a=Integer.toString(num).toCharArray();

        int ptr=0;

        for(int i=0;i<a.length && ptr<n;)
        {
            int curr=a[i]-'0',idx=al.get(ptr);

            if(v[idx][curr])
            {
                i++;
            }

            ptr++;

            if(i==a.length)
            {
                return true;
            }
        }

        return false;
    }

    public static void main(String args[]) throws Exception
    {
        n=sc.nextInt();

        v=new boolean[n][10];

        for(int i=0;i<n;i++)
        {
            for(int j=0;j<6;j++)
            {
                int curr=sc.nextInt();

                v[i][curr]=true;
            }
        }

        int last=0,curr=1,now=0;

        while(now<n)
        {
            curr*=10;now++;
