public class ProblemB {
    static int n;
    static Set<Integer>[] cubes;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        n = Integer.parseInt(line);
        cubes = new Set[n];
        for (int i = 0; i < n; i++) {
            String[] sp = br.readLine().split(" ");
            cubes[i] = new TreeSet<>();
            for (int j = 0; j < 6; j++) {
                cubes[i].add(Integer.parseInt(sp[j]));
            }
        }
        int current = 1;
        while (canForm(current, 0)) {
            current++;
        }
        System.out.println(current - 1);
    }

    static boolean canForm(int x, int mask) {
        if (x == 0) {
            return true;
        }
        if (x / 10 == 0) {
            for (int i = 0; i < n; i++) {
                if (cubes[i].contains(x) && (mask & (1 << i)) == 0) {
                    return true;
                }
            }
            return false;
        } else {
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    continue;
                }
                if (cubes[i].contains(x % 10) && canForm(x / 10, (mask | (1 << i)))) {
                    return true;
                }
            }
            return false;
        }
    }
}

