    static class Cube_of_masha {
        public void solve(int testNumber, ScanReader in, PrintWriter out) {

            int n = in.scanInt();
            HashSet<Integer> hs[] = new HashSet[n];
            for (int i = 0; i < n; i++) {
                hs[i] = new HashSet<>();
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    hs[i].add(in.scanInt());
                }
            }
            int ans = 0;
            for (int i = 1; i < Math.pow(10, n); i++) {
                int temp = i;
                boolean f = true;
                if (temp / 10 == 0) {
                    boolean flag = false;
                    for (int j = 0; j < n; j++) {
                        if (hs[j].contains(temp)) {
                            flag = true;
                            break;
                        }
                    }
                    if (!flag) {
                        ans = i;
                        break;
                    }
                } else if (i >= 10 && i <= 99) {
                    boolean flag = false;
                    if (n > 1) {
                        if (hs[0].contains(temp % 10) && hs[1].contains((temp / 10) % 10)) {
                            flag = true;
                        }
                        if (hs[1].contains(temp % 10) && hs[0].contains((temp / 10) % 10)) {
                            flag = true;
                        }
