import java.util.Scanner;

public class Main {
    static char[][] maze = null;
    static int nRow, nCol;
    static char[] ops = {'a', 'd', 's', 'w'};
    static int[] dirs = null;
    static int startX, startY, endX, endY;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        nRow = in.nextInt();
        nCol = in.nextInt();
        maze = new char[nRow][nCol];
        for (int i = 0; i < nRow; i++) {
            String str = in.next();
            maze[i] = str.toCharArray();
            for (int j = 0; j < nCol; j++) {
                if (maze[i][j] == 'S') {
                    startX = i; startY = j;
                } else if (maze[i][j] == 'E') {
                    endX = i; endY = j;
                }
            }
        }
        String str = in.next();
        dirs = new int[str.length()];
        for (int i = 0; i < str.length(); i++) {
            dirs[i] = str.charAt(i) - '0';
        }

        int cnt = 0;
        do {
            if (tryMove())
                cnt++;
        } while (next_permutation(ops, 0, ops.length));
        System.out.println(cnt);
    }

    static boolean tryMove() {
        int cx = startX, cy = startY;
        for (int i = 0; i < dirs.length; i++) {
            int op = dirs[i];
            switch (ops[op]) {
                case 'a':
                    cy--;
                    break;
                case 'd':
                    cy++;
                    break;
                case 's':
                    cx++;
                    break;
                case 'w':
                    cx--;
                    break;
            }
            if (cx < 0 || cx >= nRow || cy < 0 || cy >= nCol)
                return false;
            if (maze[cx][cy] == '#')
                return false;
            if (cx == endX && cy == endY)
                return true;
        }
        return false;
    }

    static boolean next_permutation(char[] str, int start, int end) {
        if (str == null || str.length <= 1)
            return false;

        int i = end - 2;
        for (; i >= start && str[i] >= str[i + 1]; i--);
        if (i == start - 1)
            return false;

        int j = i + 1;
        for (; j < end && str[j] > str[i]; j++);
        swap(str, i, j - 1);

        i++;
        int k = end - 1;
        for (; i < k; i++, k--) {
            swap(str, i, k);
        }
        return true;
    }

    static void swap(char[] str, int a, int b) {
        char tmp = str[a];
        str[a] = str[b];
        str[b] = tmp;
    }
}

