public class ProblemB {
    public static void main(String[] args) {
        FastScanner input = new FastScanner();
        int n = input.nextInt();
        int m = input.nextInt();
        char[][] grid = new char[n][m];
        for (int a = 0; a < n; a++) {
            grid[a] = input.next().toCharArray();
        }

        int startX = -1;
        int startY = -1;
        for (int a = 0; a < n; a++) {
            for (int b = 0; b < m; b++) {
                if (grid[a][b] == 'S') {
                    startX = a;
                    startY = b;
                }
            }
        }

        int endX = -1;
        int endY = -1;
        for (int a = 0; a < n; a++) {
            for (int b = 0; b < m; b++) {
                if (grid[a][b] == 'E') {
                    endX = a;
                    endY = b;
                }
            }
        }

        String instructions = input.next();
        HashSet<ArrayList<Integer>> permutations = new HashSet<ArrayList<Integer>>();
        ArrayList<Integer> list = new ArrayList<Integer>();
        list.add(0);
        list.add(1);
        list.add(2);
        list.add(3);
        for (int a = 0; a < 10000; a++) {
            Collections.shuffle(list);
            permutations.add((ArrayList<Integer>) list.clone());
        }
        ArrayList<String> instructionPossibilities = new ArrayList<String>();
        for (ArrayList<Integer> perm : permutations) {
            StringBuilder output = new StringBuilder();
            for (int a = 0; a < instructions.length(); a++) {
                output.append((char) ('0' + perm.get(instructions.charAt(a) - '0')));
            }
            instructionPossibilities.add(output.toString());
        }

        int count = 0;
        for (String i : instructionPossibilities) {
            if (isGood(i, startX, startY, endX, endY, grid)) {
                count++;
            }
        }
        System.out.println(count);
    }
    static int[][] dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    private static boolean isGood(String i, int startX, int startY, int endX, int endY, char[][] grid) {
        try {
            for (int a = 0; a < i.length(); a++) {
                int instruction = i.charAt(a) - '0';
                startX += dirs[instruction][0];
                startY += dirs[instruction][1];
                if (grid[startX][startY] == 'E') {
                    return true;
                }
                if (grid[startX][startY] == '#') {
                    return false;
                }
            }
        } catch (Exception e) {
            return false;
        }
        return false;
    }

    public static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(Reader in) {
            br = new BufferedReader(in);
        }

        public FastScanner() {
            this(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String readNextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

        int[] readIntArray(int n) {
            int[] a = new int[n];
            for (int idx = 0; idx < n; idx++) {
                a[idx] = nextInt();
            }
            return a;
        }

        long[] readLongArray(int n) {
            long[] a = new long[n];
            for (int idx = 0; idx < n; idx++) {
                a[idx] = nextLong();
            }
            return a;
        }
    }
}

