import java.util.ArrayList;
import java.util.Scanner;

public class buggybot {
    public static ArrayList<String> per = new ArrayList<>();
    public static void generate(String[] s, String st) {
        if (st.length() == 4) {
            per.add(st);
            return;
        }
        for (int i = 0; i < 4; i++) {
            if (!st.contains(s[i])) {
                generate(s, st + s[i]);
            }
        }
    }
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        String r[] = input.nextLine().split(" ");
        int row = Integer.parseInt(r[0]);
        int col = Integer.parseInt(r[1]);
        char mat[][] = new char[row][col];
        int saveI = 0;
        int saveJ = 0;
        for (int i = 0; i < row; i++) {
            String s = input.nextLine();
            for (int j = 0; j < col; j++) {
                mat[i][j] = s.charAt(j);
                if (mat[i][j] == 'S') {
                    saveI = i;
                    saveJ = j;
                }
            }
        }
        String map = input.nextLine();
        String store[] = {"U", "D", "R", "L"};
        generate(store, "");

        int count = 0;
        for (String string : per) {
            int moveI = saveI;
            int moveJ = saveJ;
            for (int i = 0; i < map.length(); i++) {
                char move = string.charAt(map.charAt(i) - '0');
                if (move == 'R') moveJ++;
                else if (move == 'L') moveJ--;
                else if (move == 'U') moveI--;
                else if (move == 'D') moveI++;

                if (moveJ < 0 || moveJ >= col) break;
                if (moveI < 0 || moveI >= row) break;
                if (mat[moveI][moveJ] == '#') break;

                if (mat[moveI][moveJ] == 'E') {
                    count++;
                    break;
                }
            }
        }
        System.out.println(count);
    }
}

