        int p, q;
        p = u;  q = v;
        int len = s.length();
        for(int i = 0; i < len; i++){
            if(p == x && q == y)    return true;
            if(!isV(p, q) || c[p][q] == '#')  return false;
            int j = s.charAt(i) - '0';
            if(j == a){
                p++;
            }else if(j == b){
                p--;
            }else if(j == cc){
                q++;
            }else if(j == d){
                q--;
            }
        }
        if(p == x && q == y)    return true;
        return false;
    }

    void solve(){

        n = ni();
        m = ni();
        c = new char[n][m];
        for(int i = 0; i < n; i++)  c[i] = ns(m);
        s = ns();
