public class nyb {
    static int strtI;
    static int strtJ;
    static int endI;
    static int endJ;
    static String seq;
    static char [][] maze;
    static char []D= {'u','d','l','r'};
    static int cnt;
    static boolean []taken=new boolean[4];
    public static void main(String[] args) throws IOException {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st=new StringTokenizer(br.readLine());
        int n=Integer.parseInt(st.nextToken());
        int m=Integer.parseInt(st.nextToken());
        maze=new char[n+2][m+2];
        for(int i=1;i<maze.length-1;++i) {
            String s=br.readLine();
            for(int j=1;j<maze[i].length-1;++j) {
                maze[i][j]=s.charAt(j-1);
                if(maze[i][j]=='S')
                {
                    strtI=i;
                    strtJ=j;
                }
                else if(maze[i][j]=='E') {
                    endI=i;
                    endJ=j;
                }
            }	
        }
        cnt=0;
        seq=br.readLine();
        char []x=new char[4];
        backTrack(0,x);
        System.out.println(cnt);
    }
    public static void backTrack(int idx,char[]x) {
        if(idx==4) {
            if(isValid(x))
                ++cnt;
            return;
        }
        for(int i=0;i<4;++i) {
            if(!taken[i]) {
                taken[i]=true;
                x[idx]=D[i];
                backTrack(idx+1,x);
                taken[i]=false;
            }
        }
    }
    public static boolean isValid(char[]p) {
        int x=strtI;
        int y=strtJ;

        for(int i=0;i<seq.length();i++) {
            int dir=Integer.parseInt(seq.charAt(i)+"");
            char z=p[dir];
            if(z=='r')
                y+=1;
            else if(z=='l')
                y-=1;
            else if(z=='u')
                x-=1;
            else if(z=='d')
                x+=1;
            if(x==endI && y==endJ)
                return true;
            if(maze[x][y]!='.' && maze[x][y]!='S')
                return false;
        }
        return false;
    }
}

