                            flag = false;
                            break;
                        }
                    } else if (hm[i].get(temp) == 'U') {
                        cx--;
                        if (!isvalid(n, m, cx, cy, arr)) {
                            flag = false;
                            break;
                        }
                    } else if (hm[i].get(temp) == 'D') {
