class Solver{
	Reader ip = new Reader(System.in) ;	  
	PrintWriter op = new PrintWriter(System.out) ;
	int n,m ;
	char c[][] ;
	int per[] = new int[4] ;
	int hit[] = new int[4] ;
	int ans=0 ;
	int sx,sy,ex,ey ;
	boolean valid(int x,int y){
		if(x<0 || x>=n || y<0 || y>=m) return false ;
		return c[x][y]!='#' ;
	}
	boolean reached(int x,int y){
		return x==ex && y==ey ;
	}
	boolean check(){
		int x = sx ; int y = sy ;
		for(int i=0 ; i<dir.length ; i++){
			int bit = per[dir[i]-'0'] ;
			switch(bit){
				case 0 : x-- ;
				break ;
				case 1 : y++ ;
				break ;
				case 2 : x++ ;
				break ;
				case 3 : y-- ;
			}
			// bug fix: return false only when the move is *invalid*
			if (!valid(x,y)) return false ;
			if(reached(x,y)) return true ;
		}
		return reached(x,y) ;
	}
	void permute(int idx){
		if(idx==4){
			boolean flag = check() ;
			if(flag) ans++ ;
			return ;
		}
		for(int i=0 ; i<4 ; i++){
			if(hit[i]==0){
				hit[i]=1 ;
				per[idx]=i ;
				permute(idx+1) ;
				hit[i]=0 ;
			}
		}
	}
