class Maze {
    int dc[][2] = {{0, 1}, {-1, 0}, {0, -1}, {1, 0}}; // right, up, left, down
    private int xLowBound;
    private int xHighBound;
    private int yLowBound;
    private int yHighBound;
    private int currX;
    private int currY;
    private int startX;
    private int startY;
    private int endX;
    private int endY;
    private char array[][100]; // Fixed size for simplicity

public:
    Maze(int n, int m) {
        xLowBound = 0;
        yLowBound = 0;
        xHighBound = n - 1;
        yHighBound = m - 1;
        for (int i = 0; i < n; i++) {
            string input;
            getline(cin, input);
            if (input.empty()) {
                i--;
                continue;
            }
            for (int j = 0; j < m; j++) {
                array[i][j] = input[j];
                if (input[j] == 'S') {
                    startX = currX = i;
                    startY = currY = j;
                } else if (input[j] == 'E') {
                    endX = i;
                    endY = j;
                }
            }
        }
    }

    bool move(int direction) {
        currX += dc[direction][0];
        currY += dc[direction][1];
        if (currX < xLowBound || currX > xHighBound) return false;
        if (currY < yLowBound || currY > yHighBound) return false;
        if (array[currX][currY] == '#') return false;
        return true;
    }

    bool checkForWin() {
        return array[currX][currY] == 'E';
    }

    void reset() {
        currX = startX;
        currY = startY;
    }
};

int main() {
    int n, m;
    cin >> n >> m;
    cin.ignore(); // Ignore newline after reading n and m

    Maze maze(n, m);
    string instructions;
    getline(cin, instructions);

    vector<string> perms;
    string digits = "0123";
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            if (j == i) continue;
            for (int k = 0; k < 4; k++) {
                if (k == i || k == j) continue;
                for (int l = 0; l < 4; l++) {
                    if (l == i || l == j || l == k) continue;
                    perms.push_back(string() + digits[i] + digits[j] + digits[k] + digits[l]);
                }
            }
        }
    }

    int possibilities = 0;
    for (string sequence : perms) {
        maze.reset();
        char right = sequence[0];
        char up = sequence[1];
        char left = sequence[2];
        char down = sequence[3];
        bool won = false;
        for (char c : instructions) {
            if (c == right) {
                if (!maze.move(0)) continue;
            } else if (c == up) {
                if (!maze.move(1)) continue;
            } else if (c == left) {
                if (!maze.move(2)) continue;
            } else if (c == down) {
                if (!maze.move(3)) continue;
            }
            if (maze.checkForWin()) {
                won = true;
                break;
            }
        }
        if (won) possibilities++;
    }
    cout << possibilities << endl;
    return 0;
}

