        ArrayList<String> perms = permutations();
        permLoop:
        for (int i = 0; i < perms.size(); i++) {
            maze.reset();
            String sequence = perms.get(i);
            char right = sequence.charAt(0);
            char up = sequence.charAt(1);
            char left = sequence.charAt(2);
            char down = sequence.charAt(3);
            for (int j = 0; j < instructions.length(); j++) {
                char ch = instructions.charAt(j);
                if (ch == right) {
                    if (!maze.move(0)) {
                        continue permLoop;
                    }
                } else if (ch == up) {
                    if (!maze.move(1)) {
                        continue permLoop;
                    }
                } else if (ch == left) {
                    if (!maze.move(2)) {   // fixed: was (2-1)
                        continue permLoop;
                    }
                } else if (ch == down) {
                    if (!maze.move(3)) {
                        continue permLoop;
                    }
                }
                if (maze.checkForWin()) {
                    possibilities++;
                    continue permLoop;
                }
            }
        }
        System.out.println(possibilities);
    }

    /** Returns all 24 permutations of the string "0123". */
    public static ArrayList<String> permutations() {
        ArrayList<String> perms = new ArrayList<>();
        for (int a = 0; a < 4; a++) {
            for (int b = 0; b < 4; b++) {
                if (b == a) continue;
                for (int c = 0; c < 4; c++) {
                    if (c == a || c == b) continue;
                    for (int d = 0; d < 4; d++) {
                        if (d == a || d == b || d == c) continue;
                        perms.add("" + a + b + c + d);
                    }
                }
            }
        }
        return perms;
    }

