                        startCol = j;
                    } else if (arr[i][j] == 'E') {
                        endRow = i;
                        endCol = j;
                    }
                }
            }

            int[] permutation = {0, 1, 2, 3};
            int count = traverse(permutation) ? 1 : 0;
            while (nextPermutation(permutation)) {
                boolean find = traverse(permutation);
                count += find ? 1 : 0;
            }
            out.println(count);
        }

        boolean traverse(int[] permutation) {
            int len = s.length();
            int currentRow = startRow;
            int currentCol = startCol;
            for (int i = 0; i < len; ++i) {
                int get = s.charAt(i) - 48;

