    public void solve() {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        int n = in.nextInt();
        int m = in.nextInt();
        int s = 0, e = 0;

        char[] maze = new char[5152];
        for (int i = 1; i <= n; i++) {
            String line = in.next();
            for (int j = 1; j <= m; j++) {
                maze[i * 100 + j] = line.charAt(j - 1);
                if (line.charAt(j - 1) == 'S') {
                    s = i * 100 + j;
                } else if (line.charAt(j - 1) == 'E') {
                    e = i * 100 + j;
                }
            }
        }
        String order = in.next();
        int[] orderInt = new int[100];
        for (int i = 0; i < order.length(); i++) {
            orderInt[i] = Integer.parseInt(Character.toString(order.charAt(i)));
        }
        int[][] map = {
            {1, -1, 100, -100}, {1, -1, -100, 100},
            {1, 100, -1, -100}, {1, 100, -100, -1},
            {1, -100, -1, 100}, {1, -100, 100, -1},
            {-1, 1, -100, 100}, {-1, 1, 100, -100},
            {-1, 100, -100, 1}, {-1, 100, 1, -100},
            {-1, -100, 100, 1}, {-1, -100, 1, 100},
            {100, 1, -1, -100}, {100, 1, -100, -1},
            {100, -1, 1, -100}, {100, -1, -100, 1},
            {-100, 1, -1, 100}, {-100, 1, 100, -1},
            {-100, -1, 100, 1}, {-100, -1, 1, 100},
            {-100, 100, 1, -1}, {-100, 100, -1, 1},
            {100, -100, 1, -1}, {100, -100, -1, 1},
            {-100, 100, 1, -1}, {-100, 100, -1, 1}
        };
        int ans = 0;

        for (int i = 0; i < map.length; i++) {
            int pos = s;
            for (int j = 0; j < order.length(); j++) {
                pos += map[i][orderInt[j]];

                if (pos / 100 < 1 || pos % 100 < 1 || pos / 100 > n || pos % 100 > m || maze[pos] == '#') {
                    break;
                }
                if (maze[pos] == 'E') {
                    ans++;
                    break;
                }
            }
        }

        out.println(ans);
        out.close();
    }

