import java.util.*;

public class CODE {

    static Scanner sc = new Scanner(System.in);
    static char[][] map;
    static Point S = null;
    static String way;
    static int n, m;

    /* -------------------------------------------------------------
       Helper to generate all permutations of a string
       ------------------------------------------------------------- */
    static void permute(String prefix, String remaining, List<String> out) {
        if (remaining.isEmpty()) {
            out.add(prefix);
            return;
        }
        for (int i = 0; i < remaining.length(); i++) {
            permute(prefix + remaining.charAt(i),
                    remaining.substring(0, i) + remaining.substring(i + 1),
                    out);
        }
    }

    static List<String> allPermutations(String s) {
        List<String> res = new ArrayList<>();
        permute("", s, res);
        return res;
    }

    static void fillMap() {
        n = sc.nextInt();
        m = sc.nextInt();
        map = new char[n][m];

        for (int i = 0; i < n; i++) {
            String currentRow = sc.next();
            for (int j = 0; j < m; j++) {
                map[i][j] = currentRow.charAt(j);
                if (map[i][j] == 'S') {
                    S = new Point(i, j);
                }
            }
        }
    }

    static boolean tryMove(String move) {
        Point robot = new Point(S.x, S.y);

        for (int i = 0; i < way.length(); i++) {
            char dirChar = move.charAt(way.charAt(i) - '0'); // direction for this digit
            switch (dirChar) {
                case '>':
                    robot.x++;
                    break;
                case '<':
                    robot.x--;
                    break;
                case '^':
                    robot.y++;
                    break;
                case 'v':
                    robot.y--;
                    break;
            }

            // check bounds
            if (robot.x < 0 || robot.x >= n || robot.y < 0 || robot.y >= m) {
                return false;
            }

            if (map[robot.x][robot.y] == '#') {
                return false;
            }

            if (map[robot.x][robot.y] == 'E') {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        fillMap();
        way = sc.next();
        int c = 0;

        // generate all 4! = 24 permutations of the four direction symbols
        List<String> perms = allPermutations("^v<>");
        for (String perm : perms) {
            if (tryMove(perm)) {
                c++;
            }
        }
        System.out.println(c);
    }
}

