import java.util.*;

public class CODE {

    static Scanner sc = new Scanner(System.in);
    static String moves[] = {"><^v", "><v^", ">^<v", ">^v<", ">v^<", ">v<^", "<>^v",
        "<>v^", "<^>v", "<^v>", "<v^>", "<v>^", "^<>v", "^<v>", "^><v", "^>v<", "^v><",
        "^v<>", "v<^>", "v<>^", "v^<>", "v^><", "v>^<", "v><^"};

    static char map[][];
    static Point S = null;
    static String way;
    static int n, m;

    static void fillMap() {
        n = sc.nextInt();
        m = sc.nextInt();
        map = new char[n][m];

        for (int i = 0; i < n; i++) {
            String currentRow = sc.next();
            for (int j = 0; j < m; j++) {
                map[i][j] = currentRow.charAt(j);
                if (map[i][j] == 'S') {
                    S = new Point(i, j);
                }
            }
        }
    }

    /** Try a particular mapping (represented by a permutation string). */
    static boolean tryMove(String move) {
        Point robot = new Point(S.x, S.y);

        for (int i = 0; i < way.length(); i++) {
            // translate the current digit into the direction character
            char dir = move.charAt(way.charAt(i) - '0');

            // apply the direction
            switch (dir) {
                case '>': robot.y++; break;      // move right
                case '<': robot.y--; break;      // move left
                case '^': robot.x--; break;      // move up
                case 'v': robot.x++; break;      // move down
                default: return false;           // should never happen
            }

            // boundary check
            if (robot.x < 0 || robot.x >= n || robot.y < 0 || robot.y >= m) {
                return false;
            }

            // obstacle check
            if (map[robot.x][robot.y] == '#') {
                return false;
            }

            // reached the exit?
            if (map[robot.x][robot.y] == 'E') {
                return true;
            }
        }
        // finished all instructions without reaching the exit
        return false;
    }

    public static void main(String[] args) {
        fillMap();
        way = sc.next();
        int c = 0;
        for (String move : moves) {
            if (tryMove(move)) {
                c++;
            }
        }
        System.out.println(c);
    }
}

