public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        String comm;
        String[] str;
        int n;
        int m;
        int[] command;
        int ct = 0;
        int x1;
        int y1;
        int[][] ar = new int[24][4];

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            n = in.nextInt();
            m = in.nextInt();
            str = new String[n];
            for (int i = 0; i < n; i++) {
                str[i] = in.readString();
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (str[i].charAt(j) == 'S') {
                        x1 = i;
                        y1 = j;
                    }
                }
            }
            command = new int[4];
            int arr[] = new int[4];
            for (int i = 0; i < 4; i++) {
                arr[i] = i;
            }
            heapPermutation(arr, 4, 4);
            comm = in.readString();

            int ans = 0;
            for (int i = 0; i < 24; i++) {
                // *** FIX: map each digit to its direction index (inverse permutation) ***
                for (int j = 0; j < 4; j++) {
                    command[ar[i][j]] = j;
                }
                if (solve(x1, y1, 0)) {
                    ans++;
                }
            }
            out.print(ans);
        }

        boolean solve(int x, int y, int no) {
            if (x >= n || y >= m || x < 0 || y < 0)
                return false;
            if (str[x].charAt(y) == '#')
                return false;
            if (str[x].charAt(y) == 'E')
                return true;
            if (no >= comm.length())
                return false;
            int dir = command[comm.charAt(no) - '0'];
            if (dir == 0) {
                return solve(x + 1, y, no + 1);
            }
            if (dir == 1) {
                return solve(x, y - 1, no + 1);
            }
            if (dir == 2) {
                return solve(x - 1, y, no + 1);
            }
            if (dir == 3) {
                return solve(x, y + 1, no + 1);
            }
            return false;
        }

        void heapPermutation(int a[], int size, int n) {
            if (size == 1) {
                for (int i = 0; i < 4; i++) {
                    ar[ct][i] = a[i];
                }
                ct++;
            }

            for (int i = 0; i < size; i++) {
                heapPermutation(a, size - 1, n);

                if (size % 2 == 1) {
                    int temp = a[0];
                    a[0] = a[size - 1];
                    a[size - 1] = temp;
                } else {
                    int temp = a[i];
                    a[i] = a[size - 1];
                    a[size - 1] = temp;
                }
            }
        }

    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar;
        private int snumChars;

        public InputReader(InputStream st) {
            this.stream = st;
        }

        public int read() {
            if (snumChars == -1)
                throw new InputMismatchException();
            if (curChar >= snumChars) {
                curChar = 0;
                try {
                    snumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (snumChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

    }
}

