import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class B908{

    void solve()
    {
        int n = ni(), m = ni();
        char[][] gr = ca(n);
        char[] s = ca();
        int sx = -1, sy = -1, ex = -1, ey = -1;
        for(int i=0;i<n;i++)
            for(int j=0;j<m;j++)
                if(gr[i][j] == 'S')
                {
                    sx = i;
                    sy = j;
                }
                else if(gr[i][j] == 'E')
                {
                    ex = i;
                    ey = j;
                }
        int[] a = {0, 1, 2, 3};
        int[] dr = {1, 0, -1, 0};
        int[] dc = {0, -1, 0, 1};
        int cn = 0;
        OUTER:
        do {
            int cx = sx, cy = sy;
            for(char c : s)
            {
                cx += dr[a[c-'0']];   // <-- fixed line
                cy += dc[a[c-'0']];
                if(!valid(gr, cx, cy))
                    continue OUTER;
                if(cx == ex && cy == ey)
                {
                    cn++;
                    continue OUTER;
                }
            }
        } while(nextPermutation(a));
        out.println(cn);
    }

    boolean valid(char[][] gr, int x, int y)
    {
        if(x >= 0 && x < gr.length && y >= 0 && y < gr[0].length && gr[x][y] != '#')
            return true;
        return false;
    }

    boolean nextPermutation(int[] a)
    {
        int n = a.length;
        int ptr1, ptr2;
        for(ptr1=n-2;ptr1 >= 0 && a[ptr1] >= a[ptr1+1];ptr1--);
        if(ptr1 < 0)
            return false;
        for(ptr2=ptr1+1;ptr2 < n && a[ptr1] < a[ptr2];ptr2++);
        int d = a[ptr1]; a[ptr1] = a[ptr2-1]; a[ptr2-1] = d;
        for(int i=ptr1+1,j=n-1;i<j;i++,j--)
        {
            d = a[i];
            a[i] = a[j];
            a[j] = d;
        }
        return true;
    }

    public static void main(String[] args){new B908().run();}

    private byte[] bufferArray = new byte[1024];
    private int bufLength = 0;
    private int bufCurrent = 0;
    InputStream inputStream;
    PrintWriter out;

    public void run()
    {
        inputStream = System.in;
        out = new PrintWriter(System.out);
        solve();
        out.flush();
    }

    int nextByte()
    {
        if(bufLength == -1)
            throw new InputMismatchException();
        if(bufCurrent >= bufLength)
        {
            bufCurrent = 0;
            try
            {bufLength = inputStream.read(bufferArray);}
            catch(IOException e)
                throw new InputMismatchException();}
            if(bufLength <= 0)
                return -1;
        }
        return bufferArray[bufCurrent++];
    }

    boolean isSpaceChar(int x)	{return (x < 33 || x > 126);}

    boolean isDigit(int x)	{return (x >= '0' && x <= '9');}

    int nextNonSpace()
    {
        int x;
        while((x=nextByte()) != -1 && isSpaceChar(x));
        return x;
    }

    int ni()
    {
        long ans = nl();
        if (ans >= Integer.MIN_VALUE && ans <= Integer.MAX_VALUE)
            return (int)ans;
        throw new InputMismatchException();
    }

    long nl()
    {
        long ans = 0;
        boolean neg = false;
        int x = nextNonSpace();
        if(x == '-') 
        {
            neg = true;
            x = nextByte();
        }
        while(!isSpaceChar(x))
        {
            if(isDigit(x))
            {
                ans = ans * 10 + x -'0';
                x = nextByte();
            }
            else
                throw new InputMismatchException();
        }
        return neg ? -ans : ans;
    }

    String ns()
    {
        StringBuilder sb = new StringBuilder();
        int x = nextNonSpace();
        while(!isSpaceChar(x))
        {
            sb.append((char)x);
            x = nextByte();
        }
        return sb.toString();
    }

    char nc()	{ return (char)nextNonSpace();}

    double nd()	{ return (double)Double.parseDouble(ns()); }

    char[] ca()	{ return ns().toCharArray();}

    char[][] ca(int n)
    {
        char[][] ans = new char[n][];
        for(int i=0;i<n;i++)
            ans[i] = ca();
        return ans;
    }

    int[] ia(int n)
    {
        int[] ans = new int[n];
        for(int i=0;i<n;i++)
            ans[i] = ni();
        return ans;
    }

    void db(Object... o) {System.out.println(Arrays.deepToString(o));}

}

