import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

public class q908b {

    static List<String> vals = new ArrayList<>();

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String inp = in.nextLine();
        String[] f = inp.split(" ");
        int rows = Integer.valueOf(f[0]);
        int cols = Integer.valueOf(f[1]);
        String[] grid = new String[rows];
        int[] start = new int[2];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.nextLine();
            int sIdx = grid[i].indexOf('S');
            if (sIdx >= 0) {
                start[0] = i;
                start[1] = sIdx;
            }
        }
        String proc = in.nextLine();

        char[] c = new char[4];
        generate(0, c, new HashSet<>());

        int[][] dirs = { { -1, 0 }, { 1, 0 }, { 0, -1 }, { 0, 1 } };
        int answer = 0;
        for (String p : vals) {
            if (test(grid, p, proc, dirs, start)) {
                answer++;
            }
        }
        System.out.println(answer);
    }

    static boolean test(String[] grid, String perm, String instructions, int[][] dirs, int[] start) {
        // perm is a permutation of "0123".  It tells which direction index each digit maps to.
        int[] digitToDir = new int[4];
        for (int d = 0; d < 4; d++) {
            digitToDir[d] = perm.charAt(d) - '0';   // direction index for digit d
        }

        int x = start[0];
        int y = start[1];
        for (char ch : instructions.toCharArray()) {
            int digit = ch - '0';
            int dirIdx = digitToDir[digit];
            int[] d = dirs[dirIdx];
            int nx = x + d[0];
            int ny = y + d[1];

            // out of bounds or obstacle -> crash
            if (nx < 0 || ny < 0 || nx >= grid.length || ny >= grid[0].length()
                    || grid[nx].charAt(ny) == '#') {
                return false;
            }
            // reached the exit
            if (grid[nx].charAt(ny) == 'E') {
                return true;
            }
            // otherwise move forward
            x = nx;
            y = ny;
        }
        return false; // never reached exit
    }

    static void generate(int pos, char[] chars, Set<Character> used) {
        if (pos == 4) {
            vals.add(String.valueOf(chars));
            return;
        }
        for (char ch = '0'; ch <= '3'; ch++) {
            if (used.contains(ch)) {
                continue;
            }
            chars[pos] = ch;
            used.add(ch);
            generate(pos + 1, chars, used);
            used.remove(ch);
        }
    }
}

