public class q908b
{

	public static void main( String[] args )
	{

		Scanner in = new Scanner( System.in );
		String inp = in.nextLine();
		String[] f = inp.split( " " );
		int m = Integer.valueOf( f[0] ), n = Integer.valueOf( f[1] );
		String[] b = new String[m];
		int[] start = new int[2], end = new int[2];
		for ( int i = 0; i < m; i++ )
		{
			b[i] = in.nextLine();
			if ( b[i].indexOf( "S" ) >= 0 )
			{
				start[0] = i;
				start[1] = b[i].indexOf( "S" );
			}
			if ( b[i].indexOf( "E" ) >= 0 )
			{
				end[0] = i;
				end[1] = b[i].indexOf( "E" );
			}
		}
		String proc = in.nextLine();
		char[] c = new char[4];
		Arrays.fill( c, '0' );
		generate( 0, 0, c, new HashSet<>() );


		int re = 0;
		int[][] dirs = { { -1, 0 }, { 1, 0 }, { 0, 1 }, { 0, -1 } };
		for ( String p : vals )
		{
			if ( test( b, p, proc, dirs, start ) )
				re++;
		}
		System.out.println( re );

	}

	static boolean test( String[] b, String p, String proc, int[][] dirs, int[] start )
	{
		int[][] newDirs = new int[4][];
		for ( int i = 0; i < 4; i++ )
		{
			newDirs[i] = dirs[p.charAt( i ) - '0'];
		}
		int i = start[0], j = start[1], ni = i, nj = j, ti = i, tj = j;
		for ( char k : proc.toCharArray() )
		{
			int[] d = newDirs[k - '0'];
			ni = ti + d[0];
			nj = tj + d[1];
			if ( ni < 0 || nj < 0 || ni >= b.length || nj >= b[0].length() )
				return false;
			if ( b[ni].charAt( nj ) == '#' )
				return false;
			if ( b[ni].charAt( nj ) == 'E' )
				return true;
			ti = ni;
			tj = nj;
		}

		return false;
	}

	static List<String> vals = new ArrayList<>();

	static void generate( int pos, int cur, char[] c, Set<Character> set )
	{
		if ( pos == 4 )
		{
			vals.add( String.valueOf( c ) );
			return;
		}
		for ( int i = 0; i < 4; i++ )
		{
			char nextChar = (char) ( i + '0' );
			if ( set.contains( nextChar ) )
				continue;
			c[pos] = nextChar;
			set.add( nextChar );
			generate( pos + 1, i, c, set );
			set.remove( nextChar );
		}

	}

}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;
import java.io.IOException;
import java.io.InputStream;


public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        B908 solver = new B908();
        solver.solve(1, in, out);
        out.close();
    }

    static class B908 {
        int N;
        int M;
        int SR;
        int SC;
        int ER;
        int EC;
        boolean[][] grid;
        int[] inst;

        boolean ok(int UP, int LEFT, int RIGHT, int DOWN) {
            int r = SR, c = SC;
            for (int cmd : inst) {
                if (cmd == UP) {
                    r--;
                } else if (cmd == LEFT) {
                    c--;
                } else if (cmd == RIGHT) {
                    c++;
                } else if (cmd == DOWN) {
                    r++;
                }
                if (r < 0 || r == N || c < 0 || c == M || !grid[r][c]) return false;
                if (r == ER && c == EC) return true;
            }
            return false;
        }

        public void solve(int testNumber, FastScanner s, PrintWriter out) {

            N = s.nextInt();
            M = s.nextInt();
            grid = new boolean[N][M];
            for (int i = 0; i < N; i++) {
                char[] row = s.next().toCharArray();
                for (int j = 0; j < M; j++) {
                    if (row[j] == '#') continue;
                    grid[i][j] = true;
                    if (row[j] == 'S') {
                        SR = i;
                        SC = j;
                    } else if (row[j] == 'E') {
                        ER = i;
                        EC = j;
                    }
                }
            }
            char[] cinst = s.next().toCharArray();
            inst = new int[cinst.length];
            for (int i = 0; i < inst.length; i++) {
                inst[i] = cinst[i] - '0';
            }
            int tot = 0;

            if (ok(0, 1, 2, 3)) tot++;
