    }

    static class B908 {
        int N;
        int M;
        int SR;
        int SC;
        int ER;
        int EC;
        boolean[][] grid;
        int[] inst;

        boolean ok(int UP, int LEFT, int RIGHT, int DOWN) {
            int r = SR, c = SC;
            for (int cmd : inst) {
                if (cmd == UP) {
                    r--;
                } else if (cmd == LEFT) {
                    c--;
                } else if (cmd == RIGHT) {
                    c++;
                } else if (cmd == DOWN) {
                    r++;
                }
                if (r < 0 || r >= N || c < 0 || c >= M || !grid[r][c]) return false;
                if (r == ER && c == EC) return true;
            }
            return false;
        }

        public void solve(int testNumber, FastScanner s, PrintWriter out) {

            N = s.nextInt();
            M = s.nextInt();
            grid = new boolean[N][M];
            for (int i = 0; i < N; i++) {
                char[] row = s.next().toCharArray();
                for (int j = 0; j < M; j++) {
                    if (row[j] == '#') continue;
                    grid[i][j] = true;
                    if (row[j] == 'S') {
                        SR = i;
                        SC = j;
                    } else if (row[j] == 'E') {
                        ER = i;
                        EC = j;
                    }
                }
            }
            char[] cinst = s.next().toCharArray();
            inst = new int[cinst.length];
            for (int i = 0; i < inst.length; i++) {
                inst[i] = cinst[i] - '0';
            }
            int tot = 0;

            for (int a = 0; a < 4; a++) {
                for (int b = 0; b < 4; b++) {
                    if (b == a) continue;
                    for (int c = 0; c < 4; c++) {
                        if (c == a || c == b) continue;
                        for (int d = 0; d < 4; d++) {
                            if (d == a || d == b || d == c) continue;
                            if (ok(a, b, c, d)) tot++;
                        }
                    }
                }
            }

            out.println(tot);
        }

    }

