public class Codechef {
    static List<List<Integer>> list = new ArrayList<>();
    public static void main(String[] args) throws java.lang.Exception {
        out = new PrintWriter(new BufferedOutputStream(System.out));
        sc = new FastReader();
        int test = 1;
        for (int t = 0; t < test; t++) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] arr = new char[n][];
            for (int i = 0; i < n; i++) {
                arr[i] = sc.next().toCharArray();
            }
            String instructions = sc.next();

            // find the start position 'S'
            int startRow = -1, startCol = -1;
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (arr[r][c] == 'S') {
                        startRow = r;
                        startCol = c;
                        break;
                    }
                }
                if (startRow != -1) break;
            }

            int[] p = new int[4];
            p[0] = 0;
            p[1] = 1;
            p[2] = 2;
            p[3] = 3;
            heapPermutation(p, p.length, p.length);

            int res = 0;
            for (List<Integer> curr : list) {
                int[][] directions = new int[4][2];
                directions[curr.get(0)] = new int[]{0, -1};   // up
                directions[curr.get(1)] = new int[]{0, 1};    // down
                directions[curr.get(2)] = new int[]{-1, 0};   // left
                directions[curr.get(3)] = new int[] {1, 0};   // right

                if (runToExit(arr, startRow, startCol, directions, instructions)) {
                    res++;
                }
            }
            out.println(res);
        }
        out.close();
    }

    private static boolean runToExit(char[][] arr, int i, int j, int[][] directions, String instructions) {
        for (int k = 0; k < instructions.length(); k++) {
            int d = Integer.parseInt(String.valueOf(instructions.charAt(k)));
            int[] dir = directions[d];
            i += dir[0];
            j += dir[1];
            if (i < 0 || i >= arr.length || j < 0 || j >= arr[0].length) {
                return false;                 // went off the board
            }
            if (arr[i][j] == '#') {
                return false;                 // hit an obstacle
            }
            if (arr[i][j] == 'E') {
                return true;                  // reached the exit
            }
        }
        return false;                         // did not reach exit within the instructions
    }

    static void printArr(int a[], int n) {
        List<Integer> temp = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            temp.add(a[i]);
        }
        list.add(temp);
    }

    static void heapPermutation(int a[], int size, int n) {
        if (size == 1)
            printArr(a, n);
        for (int i = 0; i < size; i++) {
            heapPermutation(a, size - 1, n);
            if (size % 2 == 1) {
                int temp = a[0];
                a[0] = a[size - 1];
                a[size - 1] = temp;
            } else {
                int temp = a[i];
                a[i] = a[size - 1];
                a[size - 1] = temp;
            }
        }
    }

