	static String s;
	static boolean recur(int r, int c, int ind) {
		if(ind == s.length() && mat[r][c] == 'E') {
			return true;
		}
		else if(ind == s.length()) return false;
		if(mat[r][c] == 'E') return true;
		int x = Integer.parseInt(s.substring(ind, ind+1));
		if(map[x] == 0) return recur(r-1,c,++ind);
		if(map[x] == 1) return recur(r+1,c,++ind);
		if(map[x] == 2) return recur(r,c+1,++ind);
		if(map[x] == 3) return recur(r,c-1,++ind);
		return true;
	}
