public class CFB {
    static int n , m , cnt;
    static int sx , sy , ex , ey;
    static boolean[][] obs , seen;
    static int[] map;
    static String s;
    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner(System.in); 

        n = in.nextInt();
        m = in.nextInt();
        obs = new boolean[n][m];
        map = new int[4];
        for(int i = 0;i < n; i++){
            s = in.next();
            for(int j = 0;j < m; j++){
                if(s.charAt(j) == '#')obs[i][j] = true;
                if(s.charAt(j) == 'S'){
                    sx = i;
                    sy = j;
                }
                if(s.charAt(j) == 'E'){
                    ex = i;
                    ey = j;
                }
            }
        }
        s = in.next();
        perm(0);
        System.out.println(cnt);
    }
    private static void perm(int a){
        if(a == 4){
            seen = new boolean[n][m];
            int x = sx;
            int y = sy;
            int dir;
            for(int i = 0;i < s.length(); i++){
                dir = map[s.charAt(i) - '0'];
                if(dir == 0){
                    if(x < n-1 && !obs[x+1][y])x++;
                    else return;
                }
                if(dir == 1){
                    if(y < m-1 && !obs[x][y+1])y++;
                    else return;
                }
                if(dir == 2){
                    if(y > 0 && !obs[x][y-1])y--;
                    else return;
                }
                if(dir == 3){
                    if(x > 0 && !obs[x-1][y])x--;
                    else return;
                }
                if(x == ex && y == ey){
                    cnt++;
                    return;
                }
            }
        }
        boolean bad;
        for(int i = 0;i < 4; i++){
            bad = false;
            for(int j = 0;j < a; j++){
                if(i == map[j])bad = true;
            }
            if(!bad){
                map[a] = i;
                perm(a+1);
            }
        }
    }
    private static class FastScanner {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public String nextLine() {
            int c = read();
            while (isEndline(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }
    }
}

