    char[][] board;
    char[] path;
    int si=0, sj=0, ei=0, ej=0;
    public void solve(){
        n=ni(); m=ni();
        board=nm(n, m);
        path=ns().toCharArray();

        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                if(board[i][j]=='E'){
                    ei=i; ej=j;
                }
                if(board[i][j]=='S'){
                    si=i; sj=j;
                }
            }
        }

        TreeSet<Integer> ts =new TreeSet<Integer>();
        int ans=0;
        for(int i=0;i<4;i++){
            for(int j=0;j<4;j++){
                for(int k=0;k<4;k++){
                    for(int l=0;l<4;l++){
                        ts.clear();
                        ts.add(i);
                        ts.add(j);
                        ts.add(k);
                        ts.add(l);
                        if(ts.size()<4){
                            continue;
                        }
                        if(check(i, j, k, l))ans+=1;
                    }
                }
            }
        }
        out.println(ans);
    }
    boolean check(int a, int b, int c,int d){


        int ci=si, cj=sj;
        for(int i=0;i<path.length;i++){
            if(path[i]-48==a){
                ci-=1;
            }
            else if(path[i]-48==b){
                ci+=1;
            }
            else if(path[i]-48==c){
                cj-=1;
            }
            else if(path[i]-48==d){
                cj+=1;
            }
            if(ci<0 || ci>=n || cj<0 || cj>=m){
                return false;
            }
            if(board[ci][cj]=='#'){
                return false;
            }
            if(board[ci][cj]=='E'){
                return true;
            }



        }
        return false;
    }

