        public void solve(int testNumber, InputReader in, OutputWriter out) {
            n = in.nextInt();
            m = in.nextInt();
            x = 0;
            y = 0;
            mat = new char[n][m];
            for (int i = 0; i < n; i++) {
                String str = in.readLine();
                for (int j = 0; j < m; j++) {
                    char c = str.charAt(j);
                    if (c == 'S') {
