public class Codeforces908B {
	public static void main(String[] args) throws IOException {


		Scanner input = new Scanner(System.in);
		int n = input.nextInt();
		int m = input.nextInt();

		char[][] grid = new char[n][m];
		for (int i = 0; i < n; i++) {

			String s = input.next();
			for (int j = 0; j < m; j++) {
				grid[i][j] = s.charAt(j);
			}
		}


		String s = input.next();
		int k = s.length();
		int[] list = new int[k];
		for (int i = 0; i < k; i++) {
			list[i] = (int) s.charAt(i) - 48;
		}

		int Sx = -1;
		int Sy = -1;

		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) {
				if (grid[i][j] == 'S') {
					Sx = i;
					Sy = j;
				}
			}
		}

		int counter = 0;
		for (int a = 0; a < 4; a++) {
			for (int b = 0; b < 4; b++) {
				for (int c = 0; c < 4; c++) {
					for (int d = 0; d < 4; d++) {
						if ((a != b) && (a != c) && (a != d) && (b != c) && (b != d) && (c != d)) {
							boolean fail = false;
							int atx = Sx;
							int aty = Sy;
							for (int i = 0; (i < k) && !(fail); i++) {
								int r = -1;
								if (list[i] == 0) {
									r = a;
								}
								else if (list[i] == 1) {
									r = b;
								}
								else if (list[i] == 2) {
									r = c;
								}
								else {
									r = d;
								}

								if (r == 0) {
									atx++;
								}
								else if (r == 1) {
									aty++;
								}
								else if (r == 2) {
									atx--;
								}
								else {
									aty--;
								}

								if ((atx < 0) || (atx >= n) || (aty < 0) || (aty >= m)) {
									fail = true;
								}
								else if (grid[atx][aty] == '#') {
									fail = true;
								}
								else if (grid[atx][aty] == 'E') {
									counter++;
									fail = true;
								}
							}
						}
					}
				}
			}
		}

		System.out.println(counter);
	}
}

