import java.util.Scanner;

public class pB
{
	public static void main(String[] args)
	{
		Scanner scanner = new Scanner(System.in);

		int ans = 0;
		int n, m;
		n = scanner.nextInt();
		m = scanner.nextInt();

		scanner.nextLine();

		int[] S = new int[2];
		int[] E = new int[2];
		char[][] maze = new char[n][m];
		for(int i = 0; i <= n - 1; i++)
		{
			maze[i] = scanner.nextLine().toCharArray();
		}

		for(int i = 0; i <= maze.length - 1; i++)
		{
			for(int j = 0; j <= maze[0].length - 1; j++)
			{

				if(maze[i][j] == 'S')
				{
					S[0] = i;
					S[1] = j;
				}

				if(maze[i][j] == 'E')
				{
					E[0] = i;
					E[1] = j;
				}
			}
		}

		char[] ops = scanner.nextLine().toCharArray();

		int[][] dirs = {{0, 1}, {0, -1}, {-1, 0}, {1, 0}}; 

		for(int i = 0; i <= 3; i++)
		{
			for(int j = 0; j <= 3; j++)
			{
				for(int k = 0; k <= 3; k++)
				{
					for(int l = 0; l <= 3; l++)
					{
						if(i == j || i == k || i == l || j == k || j == l || k == l) continue;

						boolean flag = false;
						int[] cur = new int[2];
						cur[0] = S[0];
						cur[1] = S[1];

						for(int t = 0; t <= ops.length - 1; t++)
						{
							switch(ops[t])
							{
								case '0':
									cur[0] += dirs[i][0];
									cur[1] += dirs[i][1];
									break;
								case '1':
									cur[0] += dirs[j][0];
									cur[1] += dirs[j][1];
									break;
								case '2':
									cur[0] += dirs[k][0];
									cur[1] += dirs[k][1];
									break;
								case '3':
									cur[0] += dirs[l][0];
									cur[1] += dirs[l][1];
									break;
							}

							if(cur[0] >= maze.length || cur[0] < 0 || cur[1] < 0 || cur[1] >= maze[0].length || maze[cur[0]][cur[1]] == '#' )
							{
								break;
							}
							if(cur[0] == E[0] && cur[1] == E[1])
							{
								flag = true;
								break;
							}
						}

						if(flag) ans++;
					}
				}
			}
		}

		System.out.println(ans);

	}
