            int[] dx = {1,0,-1,0};
            int[] dy = {0,1,0,-1};
            for(int i = 0; i < c.length; i++){
                int[] ncur = new int[]{cur[0] + dx[a[d[i]]], cur[1] + dy[a[d[i]]]};
                if(ncur[0]==g[0] && ncur[1]==g[1]){
