                            a[2] = k;
                            myMap[k] = 1;
                        } else {
                            continue;
                        }
                        for (int p = 0; p < 4; p++) {
                            if (myMap[p] != 1) {
                                a[3] = p;
                                myMap[p] = 1;
                                if (bfs(a, sx, sy, ex, ey, str, n, m, st)) {
                                    h++;
                                }
                            } else {
                                continue;
                            }
                            myMap[p] = 0;
                        }
                        myMap[k] = 0;
                    }
                    myMap[j] = 0;
                }
                myMap[i] = 0;
            }
            out.println(h);
        }

        private boolean bfs(int[] a, int sx, int sy, int ex, int ey, char[][] str, int n, int m, String st) {
            int h = 0;
            char[] t = st.toCharArray();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (a[t[h] - '0'] == 0) {
                        sx -= 1;
                    }
                    if (a[t[h] - '0'] == 1) {
                        sx += 1;  // Fixed: changed from 'sx =+ 1;' to 'sx += 1;'
                    }
                    if (a[t[h] - '0'] == 2) {
                        sy -= 1;
                    }
                    if (a[t[h] - '0'] == 3) {
                        sy += 1;
                    }
                    if (sx > n - 1 || sx < 0 || sy > m - 1 || sy < 0 || str[sx][sy] == '#') {
                        return false;
                    }
                    if (sx == ex && sy == ey) {
                        return true;
                    }
                    h++;
                    if (h == t.length) {
                        return false;
                    }
                }
            }
            return false;
        }

    }
}

