public class Main {
    static FastScanner in;
    static PrintWriter out;
    static final long MOD = 1000000007;

    public static void main(String[] args) throws IOException {



        out = new PrintWriter(System.out);
        in = new FastScanner(System.in);

        int n = in.nextInt(), m = in.nextInt();
        char ma[][] = new char[n][m];
        for (int i = 0; i < n; i++) {
            ma[i] = in.next().toCharArray();
        }
        char s[] = in.next().toCharArray();
        char a[] = { 'D', 'L', 'U', 'R' };
        List<char[]> lis = new ArrayList<char[]>();
        permute(lis, a, 0, 3);
        int ans = 0;
        int startR = -1, endR = -1, startC = -1, endC = -1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (ma[i][j] == 'S') {
                    startR = i;
                    startC = j;
                }
                if (ma[i][j] == 'E') {
                    endR = i;
                    endC = j;
                }
            }
        }
        for (char[] aa : lis) {
            if (solve(aa, ma, startR, startC, endR, endC, n, m, s))
                ans++;
        }
        out.println(ans);
        out.close();
    }

    static boolean solve(char[] aa, char[][] ma, int startR, int startC, int endR, int endC, int n, int m, char[] s) {
        int dir[] = new int[s.length];
        for (int i = 0; i < dir.length; i++) {
            dir[i] = Character.getNumericValue(s[i]);
        }
        int curR = startR, curC = startC;
        for (int d : dir) {
            char di = aa[d];
            if (di == 'D') {
                curR++;
            }
            if (di == 'U') {
                curR--;
            }
            if (di == 'L') {
                curC--;
            }
            if (di == 'R') {
                curC++;
            }
            if (curR < 0 || curR >= n || curC < 0 || curC >= m || ma[curR][curC] == '#') {
                return false;
            }
            if (curR == endR && curC == endC)
                return true;
        }
        if (curR < 0 || curR >= n || curC < 0 || curC >= m || ma[curR][curC] == '#') {
            return false;
        }
        if (curR == endR && curC == endC)
            return true;
        return false;
    }

    static void permute(List<char[]> lis, char a[], int l, int r) {
        int i;
        if (l == r) {
            char b[] = new char[a.length];
            System.arraycopy(a, 0, b, 0, 4);
            lis.add(b);
        } else {
            for (i = l; i <= r; i++) {
                swap(a, l, i);
                permute(lis, a, l + 1, r);
                swap(a, l, i);
            }
        }
    }

    static void swap(char a[], int i, int j) {
        char temp = a[i];
        a[i] = a[j];
        a[j] = temp;
    }
}

class Pair {
    public int first; 
    public int second; 

    public Pair(int first, int second) {
        this.first = first;
        this.second = second;
    }

    public Pair() {

    }

    @Override
    public boolean equals(Object o) {
        if (this == o)
            return true;
        if (!(o instanceof Pair))
            return false;
        Pair p = (Pair) o;
        return first == p.first && second == p.second;
    }

    @Override
    public int hashCode() {
        int result = (int) first;
        result = 31 * result + (int) second;
        return result;
    }
}

class PairComparable implements Comparator<Pair> {

    @Override
    public int compare(Pair o1, Pair o2) {
        if (o1.second < o2.second)
            return -1;
        else if (o1.second > o2.second)
            return 1;
        else {
            return 0;
        }
    }
}

class FastScanner {

    BufferedReader br;
    StringTokenizer tokenizer;

    FastScanner(String fileName) throws FileNotFoundException {
        this(new FileInputStream(new File(fileName)));
    }

    FastScanner(InputStream is) {
        br = new BufferedReader(new InputStreamReader(is));
    }

    String nextLine() throws IOException {
        tokenizer = null;
        return br.readLine();
    }

    String next() throws IOException {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }

    char nextChar() throws IOException {
        return next().charAt(0);
    }
}

