public class yrdg {
	static int si,sj,ei,ej,x,y;
	static char[][] array;
	public static void main(String[] args) {
		Scanner scanny = new Scanner(System.in);
		x = scanny.nextInt();
		y = scanny.nextInt();
		si=0;sj=0;ei=0;ej=0;
		scanny.nextLine();
		array = new char[x][y];
		for (int i = 0; i < x; i++) {
			String line = scanny.nextLine();
			for (int j = 0; j < y; j++) {
				array[i][j] = line.charAt(j);
				if (array[i][j] == 'S') {
					si = i;
					sj = j;
				}
				else if (array[i][j] == 'E') {
					ei = i;
					ej = j;
				}
			}
		}
		String numbers = scanny.nextLine();
		int res = 0;
		int a,b,c,d;
		for(int i=0;i<4;i++) {
			a=i;
			for(int j=0;j<4;j++) {
				if(a==j)continue;
				b=j;
				for(int k=0;k<4;k++) {
					if(a==k||b==k)continue;
					c=k;
					for(int l=0;l<4;l++) {
						if(a==l||b==l||c==l)continue;
						d=l;
						int[] temp={a,b,c,d};
						res+=go(temp,numbers);
					}
				}
			}
		}
		System.out.println(res);
	}
	public static int go(int[] a, String s){
		ArrayDeque<Integer> q=new ArrayDeque<>();
		q.offer(si);q.offer(sj);
		int ind=0;
		while(!q.isEmpty()) {
			int curi=q.poll(), curj=q.poll();
			if (curi == ei && curj == ej) return 1;
			if (ind==s.length())return 0;
			int d=Integer.parseInt(s.charAt(ind)+"");

			if(a[0]==d) {
				int nexti=curi-1, nextj=curj;
				if(!inBounds(nexti,nextj)||array[nexti][nextj]=='#') return 0;
				q.offer(nexti);q.offer(nextj);
			}
			if(a[1]==d) {
				int nexti=curi+1, nextj=curj;
				if(!inBounds(nexti,nextj)||array[nexti][nextj]=='#') return 0;
				q.offer(nexti);q.offer(nextj);
			}
			if(a[2]==d) {
				int nexti=curi, nextj=curj+1;
				if(!inBounds(nexti,nextj)||array[nexti][nextj]=='#') return 0;
				q.offer(nexti);q.offer(nextj);
			}
			if(a[3]==d) {
				int nexti=curi, nextj=curj-1;
				if(!inBounds(nexti,nextj)||array[nexti][nextj]=='#') return 0;
				q.offer(nexti);q.offer(nextj);
			}
			ind++;
		}
		return 0;
	}
	public static boolean inBounds(int i, int j) {
		return i>=0&&i<x&&j>=0&&j<y;
	}
}

