public class B {
  public static void main(String[] args) {
    FastScanner sc = new FastScanner();

    numRows = sc.nextInt();
    numCols = sc.nextInt();
    int startRow = -1;
    int startCol = -1;
    char[][] grid = new char[numRows][];
    for (int i = 0; i < numRows; i++) {
      grid[i] = sc.next().toCharArray();
      for (int j = 0; j < numCols; j++) {
        if (grid[i][j] == 'S') {
          startRow = i;
          startCol = j;
        }
      }
    }
    String s = sc.next();
    int[] seq = new int[s.length()];
    for (int i = 0; i < seq.length; i++) {
      seq[i] = s.charAt(i) - '0';
    }

    int[] a = {-1, 0, 1, 0};
    int[] b = {0, 1, 0, -1};
    int count = 0;
    for (int i = 0; i < 4; i++) {
      dr[0] = a[i];
      dc[0] = b[i];
      for (int j = 0; j < 4; j++) {
        if (j == i) continue;
        dr[1] = a[j];
        dc[1] = b[j];
        for (int k = 0; k < 4; k++) {
          if (k == i || k == j) continue;
          dr[2] = a[k];
          dc[2] = b[k];
          for (int l = 0; l < 4; l++) {
            if (l == i || l == j || l == k) continue;
            dr[3] = a[l];
            dc[3] = b[l];
            int curRow = startRow;
            int curCol = startCol;
            for (int m = 0; m < seq.length; m++) {
              curRow += dr[seq[m]];
              curCol += dc[seq[m]];
              if (!valid(grid, curRow, curCol)) {
                break;
              }
              if (grid[curRow][curCol] == 'E') {
                count++;
                break;
              }
            }
          }
        }
      }
    }

    System.out.println(count);
  }

  static int numRows;
  static int numCols;
  static int[] dr = new int[4];
  static int[] dc = new int[4];

  static boolean valid(char[][] grid, int curRow, int curCol) {
    return curRow >= 0 && curRow < numRows && curCol >= 0 && curCol < numCols
        && grid[curRow][curCol] != '#';
  }

  static boolean dfs(char[][] grid, boolean[][] marked, int curRow, int curCol) {
    if (valid(grid, curRow, curCol) && !marked[curRow][curCol]) {
      marked[curRow][curCol] = true;
    }
    return false;
  }

  static void shuffle(int[] arr) {
    Random rng = new Random();
    int length = arr.length;
    for (int idx = 0; idx < arr.length; idx++) {
      int toSwap = idx + rng.nextInt(length - idx);
      int tmp = arr[idx];
      arr[idx] = arr[toSwap];
      arr[toSwap] = tmp;
    }
  }

  public static class FastScanner {
    BufferedReader br;
    StringTokenizer st;

    public FastScanner(Reader in) {
      br = new BufferedReader(in);
    }

    public FastScanner() {
      this(new InputStreamReader(System.in));
    }

    String next() {
      while (st == null || !st.hasMoreElements()) {
        try {
          st = new StringTokenizer(br.readLine());
        } catch (IOException e) {
          e.printStackTrace();
        }
      }
      return st.nextToken();
    }

    int nextInt() {
      return Integer.parseInt(next());
    }

    long nextLong() {
      return Long.parseLong(next());
    }

    double nextDouble() {
      return Double.parseDouble(next());
    }

    String readNextLine() {
      String str = "";
      try {
        str = br.readLine();
      } catch (IOException e) {
        e.printStackTrace();
      }
      return str;
    }

    int[] readIntArray(int n) {
      int[] a = new int[n];
      for (int idx = 0; idx < n; idx++) {
        a[idx] = nextInt();
      }
      return a;
    }

    long[] readLongArray(int n) {
      long[] a = new long[n];
      for (int idx = 0; idx < n; idx++) {
        a[idx] = nextLong();
      }
      return a;
    }
  }
}

