import java.io.Writer;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class BuggyBot {



    public static void main(String[] args) {

        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);

        int m = in.readInt();
        int n = in.readInt();

        char[][] map = new char[m][n];

        int startX = 0;
        int startY = 0;
        int exitX = 0;
        int exitY = 0;

        for (int i = 0; i < m; i++) {
            map[i] = in.readString().toCharArray();
            for (int j = 0; j < n; j++) {
                if(map[i][j]=='S') {
                    startX=i;
                    startY=j;
                }
                else if(map[i][j]=='E'){
                    exitX=i;
                    exitY=j;
                }
            }
        }

        char[] moves = in.readString().toCharArray();

        List<Integer[][]> list = new ArrayList<>();
        Integer[][] possible = {{-1,0},{0,1},{1,0},{0,-1}};
        heapPermutation(possible, possible.length, possible.length, list);

        int count=0;
        for(Integer[][] pass : list) {
            int tempX=startX;
            int tempY=startY;
            for(char c:moves) {
                if(c=='0') {
                    tempX = tempX + pass[0][0];
                    tempY = tempY + pass[0][1];
                }
                if(c=='1') {
                    tempX = tempX + pass[1][0];
                    tempY = tempY + pass[1][1];
                }
                if(c=='2') {
                    tempX = tempX + pass[2][0];
                    tempY = tempY + pass[2][1];
                }
                if(c=='3') {
                    tempX = tempX + pass[3][0];
                    tempY = tempY + pass[3][1];
                }
                if(tempX<0 || tempX>=m || tempY<0 || tempY>=n || map[tempX][tempY]=='#') {
                    break;
                }
                if(tempX== exitX && tempY==exitY) {
                    count++;
                    break;
                }
            }
        }

        out.printLine(count);
        out.flush();
    }

    static void heapPermutation(Integer a[][], int size, int n, List<Integer[][]> list)
    {


        if (size == 1) {
            Integer[][] temp = Arrays.copyOf(a, a.length);
            list.add(temp);
        }

        for (int i=0; i<size; i++)
        {
            heapPermutation(a, size-1, n, list);



            if (size % 2 == 1)
            {
                Integer[] temp = a[0];
                a[0] = a[size-1];
                a[size-1] = temp;
            }



            else
            {
                Integer[] temp = a[i];
                a[i] = a[size-1];
                a[size-1] = temp;
            }
        }
    }

    static class InputReader {

        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long readLong() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null)
                return filter.isSpaceChar(c);
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public String next() {
            return readString();
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0)
                    writer.print(' ');
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

        public void flush() {
            writer.flush();
        }

    }

    static class IOUtils {

        public static int[] readIntegerArray(InputReader in, int size) {
            int[] array = new int[size];
            for (int i = 0; i < size; i++) {
                array[i] = in.readInt();
            }
            return array;
        }

        public static long[] readLongArray(InputReader in, int size) {
            long[] array = new long[size];
            for (int i = 0; i < size; i++) {
                array[i] = in.readLong();
            }
            return array;
        }

        public static Set<Integer> readIntegerSet(InputReader in, int size) {
            Set<Integer> set = new HashSet<Integer>();
            for (int i = 0; i < size; i++) {
                set.add(in.readInt());
            }
            return set;
        }
    }


}

