public class B {
    private static class Solver {
        private static final char[] DIR = {'u', 'd', 'l', 'r'};

        public void solve(Reader in, PrintWriter out) throws IOException {
            int n = in.nextInt();
            int m = in.nextInt();

            char[][] a = new char[n][m];
            int[] start = new int[2];
            for (int i = 0; i < n; i++) {
                String s = in.nextWord();
                for (int j = 0; j < m; j++) {
                    a[i][j] = s.charAt(j);
                    if (a[i][j] == 'S') start = new int[]{i, j};
                }
            }
            char[] s = in.nextWord().toCharArray();
            List<String> mappings = new ArrayList<>();
            gen(mappings, "");
            int res = 0;
            for (String map : mappings) {
                if (go(s, a, 0, map.toCharArray(), start[0], start[1])) res++;
            }
            out.println(res);
        }

        private void gen(List<String> mappings, String s) {
            if (s.length() == 4) {
                mappings.add(s);
                return;
            }
            for (char d : DIR) {
                if (!checkDirUsed(s, d)) gen(mappings, s + d);
            }
        }

        private boolean go(char[] s, char[][] a, int step, char[] dir, int i, int j) {
            if (i < 0 || i >= a.length || j < 0 || j >= a[0].length || a[i][j] == '#') return false;
            if (a[i][j] == 'E') return true;
            if (step >= s.length) return false;

            int dirIdx = s[step] - '0';
            int[] next = getDir(dir[dirIdx], i, j);
            return go(s, a, step + 1, dir, next[0], next[1]);
        }

        private boolean checkDirUsed(String s, char d) {
            for (char c : s.toCharArray()) if (c == d) return true;
            return false;
        }

        private int[] getDir(char c, int i, int j) {
            switch (c) {
                case 'u':
                    return new int[]{i + 1, j};
                case 'd':
                    return new int[]{i - 1, j};
                case 'l':
                    return new int[]{i, j - 1};
                case 'r':
                    return new int[]{i, j + 1};
                default:
                    return new int[]{i, j};
            }
        }
    }

