            if (at == 4) {
                if (valid(meaning, cmds, height, width, field, sr, sc))
                    return 1;
                else
                    return 0;
            }
            int res = 0;
            for (int i = 0; i < 4; ++i)
                if (!used[i]) {
                    meaning[at] = i;
                    used[i] = true;
                    res += rec(meaning, used, cmds, height, width, field, sr, sc, at + 1);
                    used[i] = false;
                }
            return res;
        }

        private boolean valid(int[] meaning, String cmds, int height, int width, String[] field, int sr, int sc) {
            for (char ch : cmds.toCharArray()) {
                int what = meaning[ch - '0'];
                sr += dr[what];
                sc += dc[what];
                if (sr < 0 || sr >= height || sc < 0 || sc >= width || field[sr].charAt(sc) == '#')
                    return false;
                if (field[sr].charAt(sc) == 'E')
                    return true;
            }
            return false;
        }

