import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;

public class Main {

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] head1 = br.readLine().split(" ");
        String[] head2 = br.readLine().split(" ");
        String[] head3 = br.readLine().split(" ");

        int h = Integer.parseInt(head1[0]);
        int w = Integer.parseInt(head1[1]);
        int ch = Integer.parseInt(head2[0]) - 1;
        int cw = Integer.parseInt(head2[1]) - 1;
        int dh = Integer.parseInt(head3[0]) - 1;
        int dw = Integer.parseInt(head3[1]) - 1;
        String[] map = new String[h];
        for (int i = 0; i < h; i++) {
            map[i] = br.readLine();
        }
        br.close();

        Queue<Wizard> queueWalk = new ArrayDeque<>();
        Queue<Wizard> queueWarp = new ArrayDeque<>();
        int[][] visit = new int[h][w];
        for (int[] row : visit) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }
        // start with 0 magic uses
        Wizard start = new Wizard(ch, cw, 0);
        visit[ch][cw] = 0;
        queueWarp.add(start);

        while (!queueWarp.isEmpty()) {
            // move all nodes that share the current magic count to the walk‑queue
            while (!queueWarp.isEmpty()) {
                queueWalk.add(queueWarp.poll());
            }
            while (!queueWalk.isEmpty()) {
                Wizard wizard = queueWalk.poll();
                // skip if we have found a better way to this cell already
                if (visit[wizard.posH][wizard.posW] < wizard.warp) {
                    continue;
                }
                // explore neighbours in the 5×5 area
                for (int curH = wizard.posH - 2; curH <= wizard.posH + 2; curH++) {
                    if (curH < 0 || curH >= h) continue;
                    for (int curW = wizard.posW - 2; curW <= wizard.posW + 2; curW++) {
                        if (curW < 0 || curW >= w) continue;
                        if (map[curH].charAt(curW) == '#') continue;
                        // Manhattan distance == 1 → ordinary move (no extra magic)
                        if (Math.abs(curH - wizard.posH) + Math.abs(curW - wizard.posW) == 1) {
                            if (visit[curH][curW] > wizard.warp) {
                                visit[curH][curW] = wizard.warp;
                                queueWalk.add(new Wizard(curH, curW, wizard.warp));
                            }
                        } else {
                            // using magic to jump to a farther square
                            if (visit[curH][curW] > wizard.warp + 1) {
                                visit[curH][curW] = wizard.warp + 1;
                                queueWarp.add(new Wizard(curH, curW, wizard.warp + 1));
                            }
                        }
                    }
                }
            }
            // if the destination has been reached, output the answer and exit
            if (visit[dh][dw] != Integer.MAX_VALUE) {
                System.out.println(visit[dh][dw]);
                return;
            }
        }
        System.out.println(-1);
    }
}

class Wizard {
    int posH, posW, warp;   // warp = number of magic uses so far

    Wizard(int posH, int posW, int warp) {
        this.posH = posH;
        this.posW = posW;
        this.warp = warp;
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

public class Main {

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] head = br.readLine().split(" ");
        int H = Integer.parseInt(head[0]);
        int W = Integer.parseInt(head[1]);

        int[] start = Arrays.stream(br.readLine().split(" "))
                .mapToInt(Integer::parseInt).toArray();
        int[] goal = Arrays.stream(br.readLine().split(" "))
                .mapToInt(Integer::parseInt).toArray();

        String[] map = new String[H];
        for (int i = 0; i < H; i++) {
            map[i] = br.readLine();
        }
        br.close();

        int[] dhdw = {goal[0] - 1, goal[1] - 1};
        int[] chcw = {start[0] - 1, start[1] - 1};

        int INF = Integer.MAX_VALUE;
        int[][] dist = new int[H][W];
        for (int[] row : dist) Arrays.fill(row, INF);
        dist[chcw[0]][chcw[1]] = 0;

        Deque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{chcw[0], chcw[1], 0});

        int[] dhdr = {1, -1, 0, 0};
        int[] dwdc = {0, 0, 1, -1};

        while (!q.isEmpty()) {
            int[] cur = q.pollFirst();
            int h = cur[0], w = cur[1], d = cur[2];
            if (d != dist[h][w]) continue;               // outdated entry
            if (h == dhdr[0] && w == dhdr[1]) {
                System.out.println(d);
                return;
            }

            // ---- Move A : walk to orthogonal neighbour (cost 0) ----
            for (int dir = 0; dir < 4; dir++) {
                int nh = h + dhdr[dir];
                int nw = w + dwdc[dir];
                if (nh < 0 || nh >= H || nw < 0 || nw >= W) continue;
                if (map[nh].charAt(nw) == '#') continue;
                if (dist[nh][nw] > d) {
                    dist[nh][nw] = d;
                    q.addFirst(new int[]{nh, nw, d});    // 0‑cost edge -> front
                }
            }

            // ---- Move B : warp to any road cell in the 5×5 area (cost +1) ----
            for (int nh = h - 2; nh <= h + 2; nh++) {
                if (nh < 0 || nh >= H) continue;
                for (int nw = w - 2; nw <= w + 2; nw++) {
                    if (nw < 0 || nw >= W) continue;
                    if (map[nh].charAt(nw) == '#') continue;
                    if (dist[nh][nw] > d + 1) {
                        dist[nh][nw] = d + 1;
                        q.addLast(new int[]{nh, nw, d + 1});   // 1‑cost edge -> back
                    }
                }
            }
        }

        System.out.println(-1);
    }
}

