		int Cw = readInt()-1;
		int Dh = readInt()-1;
		int Dw = readInt()-1;
		int[][] map = new int[H][];
		for(int h=0;h<H;h++) {
			map[h] = new int[W];
			char[] cs = readLine()[0].toCharArray();
