		Integer[][] poses = new Integer[W][H];
		for(int h=0;h<H;h++) {
			for(int w=0;w<W;w++) {
				poses[w][h] = w*H+h;
			}
		}
		int ptr = 0;
		int seccnt = 0;
		int maxsize = 1;
		int nowsize = 1;
