				int p = fr.iterator().next();
				int X = p / H;          // column index
				int Y = p % H;           // row index
				fr.remove(p);
				nowsize--;
				int nowscore = map[Y][X];
				boolean xp = false;
				boolean xm = false;
				boolean yp = false;
				boolean ym = false;
				if(X>0) {
					if(map[Y][X-1]!=-2&&map[Y][X-1]>nowscore) {
						map[Y][X-1] = nowscore;
						fr.add(poses[X-1][Y]);
						nowsize++;
						xm=true;
					}
				}
				if(Y>0) {
					if(map[Y-1][X]!=-2&&map[Y-1][X]>nowscore) {
						map[Y-1][X] = nowscore;
						fr.add(poses[X][Y-1]);
						nowsize++;
						ym=true;
					}
				}
				if(X<W-1) {
					if(map[Y][X+1]!=-2&&map[Y][X+1]>nowscore) {
						map[Y][X+1] = nowscore;
						fr.add(poses[X+1][Y]);
						nowsize++;
						xp=true;
					}
