					for(int y=ym?Y:Math.max(0,Y-2);y<=(yp?Y:Math.min(H-1,Y+2));y++) {
						if(map[y][x]!=-2&&map[y][x]>nowscore+1) {
							map[y][x] = nowscore+1;
							if(frs.size()<=nowscore+1) {
								frs.add(new LinkedHashSet<>());
							}
							frs.get(nowscore+1).add(poses[x][y]);
							nowsize++;
						}
					}
				}

				maxsize = Math.max(maxsize,nowsize);


			}
