public class Main {

	public static void main(String[] args) {
		InputReader sc = new InputReader(System.in);
		PrintWriter pw = new PrintWriter(System.out);

		int n = sc.nextInt();
		int m = sc.nextInt();
		int startx = sc.nextInt() - 1;
		int starty = sc.nextInt() - 1;
		int destx = sc.nextInt() - 1;
		int desty = sc.nextInt() - 1;
		Pair start = new Pair(startx, starty);
		Pair dest = new Pair(destx, desty);
		char[][] s = new char[n][m];
		int[][] w = new int[n][m];
		for (int i = 0; i < n; i++) {
			s[i] = sc.readString().toCharArray();
			Arrays.fill(w[i], Integer.MAX_VALUE);
		}

		LinkedList<Pair> pq = new LinkedList<>();
		pq.add(start);
		w[start.x][start.y] = 0;

		int[] dx = { 1, 0, -1, 0 };
		int[] dy = { 0, 1, 0, -1 };
		int ans = -1;
		while (!pq.isEmpty()) {
			Pair curr = pq.pollFirst();
			if (curr.equals(dest)) {
				ans = w[curr.x][curr.y];
				break;
			}

			for (int i = 0; i < 4; i++) {
				int nx = curr.x + dx[i];
				int ny = curr.y + dy[i];
				if (nx >= 0 && nx < n && ny >= 0 && ny < m && s[nx][ny] != '#' && w[nx][ny] > w[curr.x][curr.y]) {
					Pair p = new Pair(nx, ny);
					pq.addFirst(p);
					w[nx][ny] = w[curr.x][curr.y];
				}
			}

			for (int i = -2; i <= 2; i++) {
				for (int j = -2; j <= 2; j++) {

					int nx = curr.x + i;
					int ny = curr.y + j;
					if (nx >= 0 && nx < n && ny >= 0 && ny < m && s[nx][ny] != '#'
							&& w[nx][ny] > w[curr.x][curr.y] + 1) {
						Pair p = new Pair(nx, ny);
						pq.addLast(p);
						w[nx][ny] = w[curr.x][curr.y] + 1;
					}

				}
			}

		}

		pw.println(ans);

		pw.close();
	}

