            for (int j = 0; j < W; j++) {
                char c = s.charAt(j);
                if (c == '#') {
                    cost[i][j] = -1;
                } else {
                    cost[i][j] = INF;
                }
            }
        }

        boolean[][] done = new boolean[H][W];
        PriorityQueue<Pair> pq = new PriorityQueue<>((a,b)->a.cost-b.cost);
        pq.offer(new Pair(Ch,Cw,0));
        while (!pq.isEmpty()) {
            Pair p = pq.poll();
            while (p != null && done[p.i][p.j]) {
                p = pq.poll();
            }
            if (p == null) {
                break;
            }
            done[p.i][p.j] = true;
            cost[p.i][p.j] = p.cost;

