                int nextj = p.j + dx[v];
                if (0 <= nexti && nexti < H
                    && 0 <= nextj && nextj < W
                    && !done[nexti][nextj]      // <-- fixed condition
                    && cost[nexti][nextj] != -1) {
                    pq.offer(new Pair(nexti,nextj,Math.min(p.cost,cost[nexti][nextj])));
                }
