                    && cost[nexti][nextj] != -1) {
                    pq.offer(new Pair(nexti,nextj,Math.min(p.cost+1,cost[nexti][nextj])));
                }
            }
        }

        System.out.println(cost[Dh][Dw] != INF ? cost[Dh][Dw] : -1);
    }

    private static int[] dx = new int[] { 0, 0, 1, -1 };
    private static int[] dy = new int[] { 1, -1, 0, 0 };
    private static int[] d2x = new int[] { -2, -2, -2, -2, -2, -1, 0, 1, 2, 2, 2,  2,  2,  1,  0, -1, -1, -1,  1, 1};
    private static int[] d2y = new int[] { -2, -1,  0,  1,  2,  2, 2, 2, 2, 1, 0, -1, -2, -2, -2, -2, -1,  1, -1, 1};

